pub const KindCategory = enum(u8) { id, literal, bit_enum, value_enum, composite };
pub fn kindCategory(kind: Kind) KindCategory {
    return switch (kind) {
        .IdResultType, .IdResult, .IdMemorySemantics, .IdScope, .IdRef => .id,
        .LiteralInteger, .LiteralString, .LiteralFloat, .LiteralContextDependentNumber, .LiteralExtInstInteger, .LiteralSpecConstantOpInteger => .literal,
        .ImageOperands, .FPFastMathMode, .SelectionControl, .LoopControl, .FunctionControl, .MemorySemantics, .MemoryAccess, .KernelProfilingInfo, .RayFlags, .FragmentShadingRate, .RawAccessChainOperands, .CooperativeMatrixOperands, .CooperativeMatrixReduce, .TensorAddressingOperands, .MatrixMultiplyAccumulateOperands, .TensorOperands, .DebugInfo_DebugInfoFlags, .CLDebug100_DebugInfoFlags, .ShDebug100_DebugInfoFlags, .ShDebug100_BuildIdentifierFlags, .Clspv_KernelPropertyFlags => .bit_enum,
        .SourceLanguage, .ExecutionModel, .AddressingModel, .MemoryModel, .ExecutionMode, .StorageClass, .Dim, .SamplerAddressingMode, .SamplerFilterMode, .ImageFormat, .ImageChannelOrder, .ImageChannelDataType, .FPRoundingMode, .FPDenormMode, .QuantizationModes, .FPOperationMode, .OverflowModes, .LinkageType, .AccessQualifier, .HostAccessQualifier, .FunctionParameterAttribute, .Decoration, .BuiltIn, .Scope, .GroupOperation, .KernelEnqueueFlags, .Capability, .RayQueryIntersection, .RayQueryCommittedIntersectionType, .RayQueryCandidateIntersectionType, .PackedVectorFormat, .CooperativeMatrixLayout, .CooperativeMatrixUse, .TensorClampMode, .InitializationModeQualifier, .LoadCacheControl, .StoreCacheControl, .NamedMaximumNumberOfRegisters, .FPEncoding, .CooperativeVectorMatrixLayout, .ComponentType, .GatherModes, .DebugInfo_DebugBaseTypeAttributeEncoding, .DebugInfo_DebugCompositeType, .DebugInfo_DebugTypeQualifier, .DebugInfo_DebugOperation, .CLDebug100_DebugBaseTypeAttributeEncoding, .CLDebug100_DebugCompositeType, .CLDebug100_DebugTypeQualifier, .CLDebug100_DebugOperation, .CLDebug100_DebugImportedEntity, .ShDebug100_DebugBaseTypeAttributeEncoding, .ShDebug100_DebugCompositeType, .ShDebug100_DebugTypeQualifier, .ShDebug100_DebugOperation, .ShDebug100_DebugImportedEntity => .value_enum,
        .PairLiteralIntegerIdRef, .PairIdRefLiteralInteger, .PairIdRefIdRef => .composite,
    };
}

