pub const InstDesc = struct {
    op: Op,
    name: []const u8, // without the `Op` prefix
    has_result: bool,
    has_type: bool,
    operands: []const OperandSpec,
    caps: []const Capability,
    exts: []const Extension,
    min_version: u32, // (major << 16) | (minor << 8); 0xFFFFFFFF = none
    last_version: u32, // 0xFFFFFFFF = no upper bound
};

