pub fn lookupInst(opcode: u32) ?*const InstDesc {
    var lo: usize = 0;
    var hi: usize = inst_table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const v: u32 = @intFromEnum(inst_table[mid].op);
        if (v == opcode) return &inst_table[mid];
        if (v < opcode) lo = mid + 1 else hi = mid;
    }
    return null;
}

