/// Binary search by exact value (for bit enums pass a single bit, or 0).
pub fn lookupEnumerant(kind: Kind, value: u32) ?*const Enumerant {
    const t = enumerantTable(kind);
    var lo: usize = 0;
    var hi: usize = t.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (t[mid].value == value) return &t[mid];
        if (t[mid].value < value) lo = mid + 1 else hi = mid;
    }
    return null;
}

