pub fn extInstTable(set: ExtSet) []const ExtInstDesc {
    return switch (set) {
        .none => &.{},
        .glsl_std_450 => &ext_insts_glsl_std_450,
        .opencl_std => &ext_insts_opencl_std,
        .amd_shader_explicit_vertex_parameter => &ext_insts_amd_shader_explicit_vertex_parameter,
        .amd_shader_trinary_minmax => &ext_insts_amd_shader_trinary_minmax,
        .amd_gcn_shader => &ext_insts_amd_gcn_shader,
        .amd_shader_ballot => &ext_insts_amd_shader_ballot,
        .debuginfo => &ext_insts_debuginfo,
        .opencl_debuginfo_100 => &ext_insts_opencl_debuginfo_100,
        .nonsemantic_shader_debuginfo_100 => &ext_insts_nonsemantic_shader_debuginfo_100,
        .nonsemantic_graph_debuginfo => &ext_insts_nonsemantic_graph_debuginfo,
        .nonsemantic_clspvreflection => &ext_insts_nonsemantic_clspvreflection,
        .nonsemantic_vkspreflection => &ext_insts_nonsemantic_vkspreflection,
        .tosa_001000_1 => &ext_insts_tosa_001000_1,
        .arm_motion_engine_100 => &ext_insts_arm_motion_engine_100,
        .arm_experimental_ml_operations => &ext_insts_arm_experimental_ml_operations,
        .nonsemantic_debugprintf => &ext_insts_nonsemantic_debugprintf,
        .nonsemantic_unknown => &ext_insts_nonsemantic_unknown,
    };
}

pub fn lookupExtInst(set: ExtSet, value: u32) ?*const ExtInstDesc {
    const t = extInstTable(set);
    var lo: usize = 0;
    var hi: usize = t.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (t[mid].value == value) return &t[mid];
        if (t[mid].value < value) lo = mid + 1 else hi = mid;
    }
    return null;
}

/// Mirrors source/ext_inst.cpp spvExtInstImportTypeGet.
pub fn extSetFromImportName(name: []const u8) ExtSet {
    if (std.mem.eql(u8, name, "GLSL.std.450")) return .glsl_std_450;
    if (std.mem.eql(u8, name, "OpenCL.std")) return .opencl_std;
    if (std.mem.eql(u8, name, "SPV_AMD_shader_explicit_vertex_parameter")) return .amd_shader_explicit_vertex_parameter;
    if (std.mem.eql(u8, name, "SPV_AMD_shader_trinary_minmax")) return .amd_shader_trinary_minmax;
    if (std.mem.eql(u8, name, "SPV_AMD_gcn_shader")) return .amd_gcn_shader;
    if (std.mem.eql(u8, name, "SPV_AMD_shader_ballot")) return .amd_shader_ballot;
    if (std.mem.eql(u8, name, "DebugInfo")) return .debuginfo;
    if (std.mem.eql(u8, name, "OpenCL.DebugInfo.100")) return .opencl_debuginfo_100;
    if (std.mem.startsWith(u8, name, "NonSemantic.Shader.DebugInfo.")) return .nonsemantic_shader_debuginfo_100;
    if (std.mem.startsWith(u8, name, "NonSemantic.Graph.DebugInfo.")) return .nonsemantic_graph_debuginfo;
    if (std.mem.startsWith(u8, name, "NonSemantic.ClspvReflection.")) return .nonsemantic_clspvreflection;
    if (std.mem.startsWith(u8, name, "NonSemantic.VkspReflection.")) return .nonsemantic_vkspreflection;
    if (std.mem.eql(u8, name, "TOSA.001000.1")) return .tosa_001000_1;
    if (std.mem.eql(u8, name, "Arm.MotionEngine.100")) return .arm_motion_engine_100;
    if (std.mem.startsWith(u8, name, "Arm.ExperimentalMLOperations.")) return .arm_experimental_ml_operations;
    if (std.mem.eql(u8, name, "NonSemantic.DebugPrintf")) return .nonsemantic_debugprintf;
    if (std.mem.startsWith(u8, name, "NonSemantic.")) return .nonsemantic_unknown;
    return .none;
}

pub fn extSetIsNonSemantic(set: ExtSet) bool {
    return switch (set) {
        .nonsemantic_shader_debuginfo_100, .nonsemantic_graph_debuginfo, .nonsemantic_clspvreflection, .nonsemantic_vkspreflection, .nonsemantic_debugprintf, .nonsemantic_unknown => true,
        else => false,
    };
}

/// Mirrors spvExtInstIsDebugInfo.
pub fn extSetIsDebugInfo(set: ExtSet) bool {
    return switch (set) {
        .debuginfo, .opencl_debuginfo_100, .nonsemantic_shader_debuginfo_100 => true,
        else => false,
    };
}

// END SPIR-V GRAMMAR TABLES

// Runtime support: fatal errors, the two arenas and the container types (List, Map, OrderedMap, Set, BitSet, Queue,
// SortedMap, SortedSet). Nothing in the file returns an error union: running out of memory and violated invariants
// are fatal.

/// Prints "spirvopt: error: ..." to stderr and exits with status 1. Nothing has been written to the output file at that point.
pub fn fatal(comptime fmt: []const u8, args: anytype) noreturn {
    std.debug.print("spirvopt: error: " ++ fmt ++ "\n", args);
    std.process.exit(1);
}

/// Always-on assertion (unlike std.debug.assert it is not compiled out in ReleaseFast).
pub fn check(ok: bool, comptime msg: []const u8) void {
    if (!ok) fatal("internal check failed: " ++ msg, .{});
}

/// Out of memory is fatal.
pub fn oom() noreturn {
    fatal("out of memory", .{});
}

// Two arenas. `ir` lives until process exit and holds every IR object (Inst, Block, Func, Module and the
// growable lists they own). `scratch` holds analyses, pass state and temporaries and is reset (free_all)
// after every pass; IR objects must never point into scratch memory.
var g_ir_arena: std.heap.ArenaAllocator = undefined;
var g_sc_arena: std.heap.ArenaAllocator = undefined;

/// Creates the two arenas. Call once at the start of the process.
pub fn memInit(backing: Allocator) void {
    g_ir_arena = std.heap.ArenaAllocator.init(backing);
    g_sc_arena = std.heap.ArenaAllocator.init(backing);
}

/// Frees both arenas.
pub fn memDeinit() void {
    g_sc_arena.deinit();
    g_ir_arena.deinit();
}

/// Frees everything in the scratch arena. Done after every pass: no analysis or pass state survives it.
pub fn scratchReset() void {
    _ = g_sc_arena.reset(.free_all);
}

/// The allocator of the IR arena (lives until the process exits).
pub fn irAllocator() Allocator {
    return g_ir_arena.allocator();
}

/// The allocator of the scratch arena (reset after every pass).
pub fn scAllocator() Allocator {
    return g_sc_arena.allocator();
}

/// Which arena a container allocates from: `ir` lives until process exit, `scratch` is reset after every pass.
pub const Pool = enum { ir, scratch };

/// The allocator of `pool`.
fn poolAllocator(comptime pool: Pool) Allocator {
    return switch (pool) {
        .ir => irAllocator(),
        .scratch => scAllocator(),
    };
}

/// Growable array without an allocator parameter. `ListIn(T, .ir)` allocates from the IR arena.
pub fn ListIn(comptime T: type, comptime pool: Pool) type {
    return struct {
        const Self = @This();
        items: []T = &[_]T{},
        cap: usize = 0,

        pub fn len(self: *const Self) usize {
            return self.items.len;
        }

        pub fn isEmpty(self: *const Self) bool {
            return self.items.len == 0;
        }

        pub fn reserve(self: *Self, n: usize) void {
            if (n <= self.cap) return;
            var new_cap: usize = if (self.cap == 0) 4 else self.cap * 2;
            if (new_cap < n) new_cap = n;
            const a: std.mem.Allocator = poolAllocator(pool);
            const mem = a.alloc(T, new_cap) catch oom();
            const old_len: usize = self.items.len;
            if (old_len > 0) @memcpy(mem[0..old_len], self.items);
            self.items = mem[0..old_len];
            self.cap = new_cap;
        }

        pub fn push(self: *Self, x: T) void {
            const n: usize = self.items.len;
            self.reserve(n + 1);
            self.items = self.items.ptr[0 .. n + 1];
            self.items[n] = x;
        }

        /// Grows the list to `n` elements, every new element set to `fill` (used for tables indexed by id).
        pub fn growFilled(self: *Self, n: usize, fill: T) void {
            const old_len: usize = self.items.len;
            if (n <= old_len) return;
            self.reserve(n);
            self.items = self.items.ptr[0..n];
            @memset(self.items[old_len..], fill);
        }

        pub fn pushSlice(self: *Self, xs: []const T) void {
            const n: usize = self.items.len;
            self.reserve(n + xs.len);
            self.items = self.items.ptr[0 .. n + xs.len];
            @memcpy(self.items[n..], xs);
        }

        pub fn pop(self: *Self) ?T {
            if (self.items.len == 0) return null;
            const x: T = self.items[self.items.len - 1];
            self.items = self.items[0 .. self.items.len - 1];
            return x;
        }

        pub fn last(self: *const Self) T {
            check(self.items.len > 0, "List.last on empty list");
            return self.items[self.items.len - 1];
        }

        pub fn insert(self: *Self, index: usize, x: T) void {
            check(index <= self.items.len, "List.insert index out of range");
            const n: usize = self.items.len;
            self.reserve(n + 1);
            self.items = self.items.ptr[0 .. n + 1];
            @memmove(self.items[index + 1 ..], self.items[index..n]);
            self.items[index] = x;
        }

        pub fn orderedRemove(self: *Self, index: usize) T {
            check(index < self.items.len, "List.orderedRemove index out of range");
            const x: T = self.items[index];
            @memmove(self.items[index .. self.items.len - 1], self.items[index + 1 ..]);
            self.items = self.items[0 .. self.items.len - 1];
            return x;
        }

        pub fn swapRemove(self: *Self, index: usize) T {
            check(index < self.items.len, "List.swapRemove index out of range");
            const x: T = self.items[index];
            self.items[index] = self.items[self.items.len - 1];
            self.items = self.items[0 .. self.items.len - 1];
            return x;
        }

        pub fn clear(self: *Self) void {
            self.items = self.items[0..0];
        }

        pub fn truncate(self: *Self, n: usize) void {
            check(n <= self.items.len, "List.truncate beyond length");
            self.items = self.items[0..n];
        }

        pub fn indexOf(self: *const Self, x: T) ?usize {
            for (self.items, 0..) |v, i| {
                if (std.meta.eql(v, x)) return i;
            }
            return null;
        }

        pub fn contains(self: *const Self, x: T) bool {
            return self.indexOf(x) != null;
        }
    };
}

/// Growable array in the scratch arena.
pub fn List(comptime T: type) type {
    return ListIn(T, .scratch);
}

/// Growable array in the IR arena, for lists owned by IR objects.
pub fn IrList(comptime T: type) type {
    return ListIn(T, .ir);
}

/// Hash map keyed by anything std.AutoHashMap accepts (ints, pointers, enums, small structs).
/// Iteration order is unspecified; use OrderedMap when the C++ code relied on a deterministic order.
pub fn Map(comptime K: type, comptime V: type) type {
    return struct {
        const Self = @This();
        pub const Hm = std.AutoHashMapUnmanaged(K, V);
        pub const GetOrPutResult = Hm.GetOrPutResult;
        hm: Hm = .empty,

        pub fn put(self: *Self, k: K, v: V) void {
            self.hm.put(scAllocator(), k, v) catch oom();
        }
        pub fn get(self: *const Self, k: K) ?V {
            return self.hm.get(k);
        }
        pub fn getPtr(self: *const Self, k: K) ?*V {
            return self.hm.getPtr(k);
        }
        pub fn contains(self: *const Self, k: K) bool {
            return self.hm.contains(k);
        }
        pub fn remove(self: *Self, k: K) bool {
            return self.hm.remove(k);
        }
        pub fn count(self: *const Self) usize {
            return self.hm.count();
        }
        pub fn getOrPut(self: *Self, k: K) GetOrPutResult {
            return self.hm.getOrPut(scAllocator(), k) catch oom();
        }
        pub fn iterator(self: *const Self) Hm.Iterator {
            return self.hm.iterator();
        }
        pub fn clear(self: *Self) void {
            self.hm.clearRetainingCapacity();
        }
    };
}

/// Insertion-ordered map (iteration order == insertion order; removal via swapRemove/orderedRemove).
pub fn OrderedMap(comptime K: type, comptime V: type) type {
    return struct {
        const Self = @This();
        pub const Hm = std.AutoArrayHashMapUnmanaged(K, V);
        pub const GetOrPutResult = Hm.GetOrPutResult;
        hm: Hm = .empty,

        pub fn put(self: *Self, k: K, v: V) void {
            self.hm.put(scAllocator(), k, v) catch oom();
        }
        pub fn get(self: *const Self, k: K) ?V {
            return self.hm.get(k);
        }
        pub fn getPtr(self: *const Self, k: K) ?*V {
            return self.hm.getPtr(k);
        }
        pub fn contains(self: *const Self, k: K) bool {
            return self.hm.contains(k);
        }
        pub fn orderedRemove(self: *Self, k: K) bool {
            return self.hm.orderedRemove(k);
        }
        pub fn count(self: *const Self) usize {
            return self.hm.count();
        }
        pub fn getOrPut(self: *Self, k: K) GetOrPutResult {
            return self.hm.getOrPut(scAllocator(), k) catch oom();
        }
        pub fn keys(self: *const Self) []K {
            return self.hm.keys();
        }
        pub fn values(self: *const Self) []V {
            return self.hm.values();
        }
        pub fn clear(self: *Self) void {
            self.hm.clearRetainingCapacity();
        }
    };
}

/// Hash set (a Map without values); the iteration order is unspecified, like Map.
pub fn Set(comptime K: type) type {
    return struct {
        const Self = @This();
        m: Map(K, void) = .{},

        /// Returns true when `k` was not present before.
        pub fn insert(self: *Self, k: K) bool {
            const r: Map(K, void).GetOrPutResult = self.m.getOrPut(k);
            return !r.found_existing;
        }
        pub fn contains(self: *const Self, k: K) bool {
            return self.m.contains(k);
        }
        pub fn remove(self: *Self, k: K) bool {
            return self.m.remove(k);
        }
        pub fn count(self: *const Self) usize {
            return self.m.count();
        }
        pub fn clear(self: *Self) void {
            self.m.clear();
        }
        pub fn iterator(self: *const Self) Map(K, void).Hm.Iterator {
            return self.m.iterator();
        }
    };
}

/// Dense set of small unsigned integers (utils::BitVector): one bit per value, grown on demand. Scratch memory only.
pub const BitSet = struct {
    words: List(u64) = .{},

    /// Returns true when `i` was not in the set before.
    pub fn insert(self: *BitSet, i: u32) bool {
        const w: usize = i >> 6;
        self.words.growFilled(w + 1, 0);
        const bit: u64 = @as(u64, 1) << @truncate(i);
        const was_set: bool = self.words.items[w] & bit != 0;
        self.words.items[w] |= bit;
        return !was_set;
    }

    pub fn contains(self: *const BitSet, i: u32) bool {
        const w: usize = i >> 6;
        return w < self.words.len() and self.words.items[w] & (@as(u64, 1) << @truncate(i)) != 0;
    }
};

/// FIFO queue (std::queue / std::deque used as a worklist). Scratch memory only.
pub fn Queue(comptime T: type) type {
    return struct {
        const Self = @This();
        buf: List(T) = .{},
        head: usize = 0,

        pub fn push(self: *Self, x: T) void {
            self.buf.push(x);
        }
        pub fn pop(self: *Self) ?T {
            if (self.head >= self.buf.items.len) return null;
            const x: T = self.buf.items[self.head];
            self.head += 1;
            if (self.head == self.buf.items.len) {
                self.buf.clear();
                self.head = 0;
            }
            return x;
        }
        pub fn front(self: *const Self) T {
            check(self.head < self.buf.items.len, "Queue.front on empty queue");
            return self.buf.items[self.head];
        }
        pub fn len(self: *const Self) usize {
            return self.buf.items.len - self.head;
        }
        pub fn isEmpty(self: *const Self) bool {
            return self.len() == 0;
        }
    };
}

/// `ascending(u32)` etc.: natural-order comparator usable as the `lessThan` parameter of SortedMap/SortedSet.
pub fn ascending(comptime T: type) fn (T, T) bool {
    return struct {
        fn f(a: T, b: T) bool {
            return a < b;
        }
    }.f;
}

/// Ordered map (std::map): sorted arrays + binary search. O(n) insert/remove, O(log n) lookup, iteration in
/// key order. Use only for modest sizes; for big id->value tables use Map and sort the keys when needed.
pub fn SortedMap(comptime K: type, comptime V: type, comptime lessThan: fn (K, K) bool) type {
    return struct {
        const Self = @This();
        ks: List(K) = .{},
        vs: List(V) = .{},

        /// Index of the first key that is not less than `k`.
        fn lowerBound(self: *const Self, k: K) usize {
            var lo: usize = 0;
            var hi: usize = self.ks.items.len;
            while (lo < hi) {
                const mid: usize = lo + (hi - lo) / 2;
                if (lessThan(self.ks.items[mid], k)) lo = mid + 1 else hi = mid;
            }
            return lo;
        }
        fn indexOfKey(self: *const Self, k: K) ?usize {
            const i: usize = self.lowerBound(k);
            if (i < self.ks.items.len and !lessThan(k, self.ks.items[i])) return i;
            return null;
        }
        pub fn put(self: *Self, k: K, v: V) void {
            const i: usize = self.lowerBound(k);
            if (i < self.ks.items.len and !lessThan(k, self.ks.items[i])) {
                self.vs.items[i] = v;
                return;
            }
            self.ks.insert(i, k);
            self.vs.insert(i, v);
        }
        pub fn get(self: *const Self, k: K) ?V {
            const i: usize = self.indexOfKey(k) orelse return null;
            return self.vs.items[i];
        }
        pub fn getPtr(self: *const Self, k: K) ?*V {
            const i: usize = self.indexOfKey(k) orelse return null;
            return &self.vs.items[i];
        }
        pub fn contains(self: *const Self, k: K) bool {
            return self.indexOfKey(k) != null;
        }
        pub fn remove(self: *Self, k: K) bool {
            const i: usize = self.indexOfKey(k) orelse return false;
            _ = self.ks.orderedRemove(i);
            _ = self.vs.orderedRemove(i);
            return true;
        }
        pub fn count(self: *const Self) usize {
            return self.ks.items.len;
        }
        pub fn keys(self: *const Self) []K {
            return self.ks.items;
        }
        pub fn values(self: *const Self) []V {
            return self.vs.items;
        }
        pub fn clear(self: *Self) void {
            self.ks.clear();
            self.vs.clear();
        }
    };
}

/// Ordered set (std::set): see SortedMap.
pub fn SortedSet(comptime K: type, comptime lessThan: fn (K, K) bool) type {
    return struct {
        const Self = @This();
        m: SortedMap(K, void, lessThan) = .{},

        /// Returns true when `k` was not present before.
        pub fn insert(self: *Self, k: K) bool {
            if (self.m.contains(k)) return false;
            self.m.put(k, {});
            return true;
        }
        pub fn contains(self: *const Self, k: K) bool {
            return self.m.contains(k);
        }
        pub fn remove(self: *Self, k: K) bool {
            return self.m.remove(k);
        }
        pub fn count(self: *const Self) usize {
            return self.m.count();
        }
        pub fn items(self: *const Self) []K {
            return self.m.keys();
        }
        pub fn clear(self: *Self) void {
            self.m.clear();
        }
    };
}

// SPIR-V words and opcode predicates: the header constants and the opcode / operand-kind predicates of spirv-opt
// (source/opcode.cpp, source/opt/reflect.h). Names are the grammar's primary opcode names.

/// The first word of every SPIR-V binary.
pub const spv_magic: u32 = 0x07230203;
/// Number of words of the header of a binary: magic, version, generator, id bound, schema.
pub const spv_header_words: usize = 5;
/// The largest id bound spirv-opt allows by default.
pub const default_max_id_bound: u32 = 0x3FFFFF;

pub fn opcodeValue(op: Op) u32 {
    return @intFromEnum(op);
}

pub fn opGeneratesType(op: Op) bool {
    return switch (op) {
        .OpTypeVoid, .OpTypeBool, .OpTypeInt, .OpTypeFloat, .OpTypeVector, .OpTypeMatrix, .OpTypeImage,
        .OpTypeSampler, .OpTypeSampledImage, .OpTypeArray, .OpTypeRuntimeArray, .OpTypeStruct,
        .OpTypeOpaque, .OpTypePointer, .OpTypeFunction, .OpTypeEvent, .OpTypeDeviceEvent,
        .OpTypeReserveId, .OpTypeQueue, .OpTypePipe, .OpTypePipeStorage, .OpTypeNamedBarrier,
        .OpTypeAccelerationStructureNV, .OpTypeCooperativeMatrixNV, .OpTypeCooperativeMatrixKHR,
        .OpTypeVectorIdEXT, .OpTypeRayQueryKHR, .OpTypeHitObjectNV, .OpTypeHitObjectEXT,
        .OpTypeUntypedPointerKHR, .OpTypeNodePayloadArrayAMDX, .OpTypeTensorLayoutNV,
        .OpTypeTensorViewNV, .OpTypeTensorARM, .OpTypeTaskSequenceINTEL, .OpTypeGraphARM,
        .OpTypeBufferEXT,
        => true,
        else => false,
    };
}

pub fn opIsTypeInst(op: Op) bool {
    return opGeneratesType(op) or op == .OpTypeForwardPointer;
}

pub fn opIsConstant(op: Op) bool {
    return switch (op) {
        .OpConstantTrue, .OpConstantFalse, .OpConstant, .OpConstantComposite,
        .OpConstantCompositeReplicateEXT, .OpConstantSampler, .OpConstantNull,
        .OpConstantFunctionPointerINTEL, .OpConstantStringAMDX, .OpSpecConstantTrue,
        .OpSpecConstantFalse, .OpSpecConstant, .OpSpecConstantComposite,
        .OpSpecConstantCompositeReplicateEXT, .OpSpecConstantOp, .OpSpecConstantStringAMDX,
        .OpGraphConstantARM, .OpAsmTargetINTEL, .OpAsmINTEL, .OpSpecConstantArchitectureINTEL,
        .OpSpecConstantTargetINTEL, .OpSpecConstantCapabilitiesINTEL, .OpConstantSizeOfEXT,
        .OpConstantDataKHR, .OpSpecConstantDataKHR,
        => true,
        else => false,
    };
}

pub fn opIsBranch(op: Op) bool {
    return op == .OpBranch or op == .OpBranchConditional or op == .OpSwitch;
}

pub fn opIsReturn(op: Op) bool {
    return op == .OpReturn or op == .OpReturnValue;
}

pub fn opIsAbort(op: Op) bool {
    return switch (op) {
        .OpKill, .OpUnreachable, .OpTerminateInvocation, .OpTerminateRayKHR,
        .OpIgnoreIntersectionKHR, .OpEmitMeshTasksEXT, .OpAbortKHR,
        => true,
        else => false,
    };
}

pub fn opIsReturnOrAbort(op: Op) bool {
    return opIsReturn(op) or opIsAbort(op);
}

pub fn opIsBlockTerminator(op: Op) bool {
    return opIsBranch(op) or opIsReturnOrAbort(op);
}

pub fn opIsDecoration(op: Op) bool {
    return switch (op) {
        .OpDecorate, .OpDecorateId, .OpMemberDecorate, .OpMemberDecorateIdEXT, .OpGroupDecorate,
        .OpGroupMemberDecorate, .OpDecorateString, .OpMemberDecorateString,
        => true,
        else => false,
    };
}

pub fn opIsDebug1(op: Op) bool {
    const v: u32 = opcodeValue(op);
    return (v >= opcodeValue(.OpSourceContinued) and v <= opcodeValue(.OpSourceExtension)) or op == .OpString;
}

pub fn opIsDebug2(op: Op) bool {
    return op == .OpName or op == .OpMemberName;
}

pub fn opIsDebug3(op: Op) bool {
    return op == .OpModuleProcessed;
}

pub fn opIsOpLine(op: Op) bool {
    return op == .OpLine or op == .OpNoLine;
}

pub fn opIsAnnotation(op: Op) bool {
    const v: u32 = opcodeValue(op);
    return (v >= opcodeValue(.OpDecorate) and v <= opcodeValue(.OpGroupMemberDecorate)) or
        op == .OpDecorateId or op == .OpDecorateString or op == .OpMemberDecorateString or
        op == .OpMemberDecorateIdEXT;
}

pub fn opIsExtendedInstruction(op: Op) bool {
    return op == .OpExtInst or op == .OpExtInstWithForwardRefsKHR;
}

/// Mirrors spvIsIdType: kinds whose single word is an <id>.
pub fn kindIsId(k: Kind) bool {
    return switch (k) {
        .IdResultType, .IdResult, .IdRef, .IdScope, .IdMemorySemantics => true,
        else => false,
    };
}

