    return switch (op) {
        .OpImageSampleImplicitLod, .OpImageSampleExplicitLod, .OpImageSampleDrefImplicitLod,
        .OpImageSampleDrefExplicitLod, .OpImageSampleProjImplicitLod, .OpImageSampleProjExplicitLod,
        .OpImageSampleProjDrefImplicitLod, .OpImageSampleProjDrefExplicitLod,
        .OpImageSparseSampleImplicitLod, .OpImageSparseSampleExplicitLod,
        .OpImageSparseSampleDrefImplicitLod, .OpImageSparseSampleDrefExplicitLod,
        .OpImageSampleFootprintNV,
        => true,
        else => false,
    };
}

pub fn opIsAccessChain(op: Op) bool {
    return switch (op) {
        .OpAccessChain, .OpInBoundsAccessChain, .OpPtrAccessChain, .OpInBoundsPtrAccessChain,
        .OpRawAccessChainNV,
        => true,
        else => false,
    };
}

pub fn opIsBit(op: Op) bool {
    return switch (op) {
        .OpShiftRightLogical, .OpShiftRightArithmetic, .OpShiftLeftLogical, .OpBitwiseOr,
        .OpBitwiseXor, .OpBitwiseAnd, .OpNot, .OpBitReverse, .OpBitCount,
        => true,
        else => false,
    };
}

pub fn opGeneratesUntypedPointer(op: Op) bool {
    return switch (op) {
        .OpUntypedVariableKHR, .OpUntypedAccessChainKHR, .OpUntypedInBoundsAccessChainKHR,
        .OpUntypedPtrAccessChainKHR, .OpUntypedInBoundsPtrAccessChainKHR,
        => true,
        else => false,
    };
}

pub fn opIsCodeMotionSafe(op: Op) bool {
    return switch (op) {
        .OpNop, .OpUndef, .OpLoad, .OpAccessChain, .OpInBoundsAccessChain, .OpArrayLength,
        .OpVectorExtractDynamic, .OpVectorInsertDynamic, .OpVectorShuffle, .OpCompositeConstruct,
        .OpCompositeExtract, .OpCompositeInsert, .OpCopyObject, .OpTranspose, .OpConvertFToU,
        .OpConvertFToS, .OpConvertSToF, .OpConvertUToF, .OpUConvert, .OpSConvert, .OpFConvert,
        .OpQuantizeToF16, .OpBitcast, .OpSNegate, .OpFNegate, .OpIAdd, .OpFAdd, .OpISub, .OpFSub,
        .OpIMul, .OpFMul, .OpUDiv, .OpSDiv, .OpFDiv, .OpUMod, .OpSRem, .OpSMod, .OpFRem, .OpFMod,
        .OpVectorTimesScalar, .OpMatrixTimesScalar, .OpVectorTimesMatrix, .OpMatrixTimesVector,
        .OpMatrixTimesMatrix, .OpOuterProduct, .OpDot, .OpIAddCarry, .OpISubBorrow, .OpUMulExtended,
        .OpSMulExtended, .OpAny, .OpAll, .OpIsNan, .OpIsInf, .OpLogicalEqual, .OpLogicalNotEqual,
        .OpLogicalOr, .OpLogicalAnd, .OpLogicalNot, .OpSelect, .OpIEqual, .OpINotEqual,
        .OpUGreaterThan, .OpSGreaterThan, .OpUGreaterThanEqual, .OpSGreaterThanEqual, .OpULessThan,
        .OpSLessThan, .OpULessThanEqual, .OpSLessThanEqual, .OpFOrdEqual, .OpFUnordEqual,
        .OpFOrdNotEqual, .OpFUnordNotEqual, .OpFOrdLessThan, .OpFUnordLessThan, .OpFOrdGreaterThan,
        .OpFUnordGreaterThan, .OpFOrdLessThanEqual, .OpFUnordLessThanEqual, .OpFOrdGreaterThanEqual,
        .OpFUnordGreaterThanEqual, .OpShiftRightLogical, .OpShiftRightArithmetic, .OpShiftLeftLogical,
        .OpBitwiseOr, .OpBitwiseXor, .OpBitwiseAnd, .OpNot, .OpBitFieldInsert, .OpBitFieldSExtract,
        .OpBitFieldUExtract, .OpBitReverse, .OpBitCount, .OpSizeOf,
        => true,
        else => false,
    };
}

pub fn opIsConstantOrUndef(op: Op) bool {
    return op == .OpUndef or op == .OpPoisonKHR or opIsConstant(op);
}

/// IsConstantInst(op) && !IsSpecConstantInst(op), the body of Instruction::IsConstant.
pub fn opIsNonSpecConstant(op: Op) bool {
    return opIsConstant(op) and !opIsSpecConstant(op);
}

pub fn opIsAtomicOp(op: Op) bool {
    return opIsAtomicWithLoad(op) or op == .OpAtomicStore or op == .OpAtomicFlagClear;
}

/// Indices (counted over all operands, like spvOpcodeMemorySemanticsOperandIndices) of memory-semantics ids.
pub fn opMemorySemanticsOperandIndices(op: Op) []const u32 {
    return switch (op) {
        .OpMemoryBarrier => &[_]u32{1},
        .OpAtomicStore, .OpControlBarrier, .OpAtomicFlagClear, .OpMemoryNamedBarrier => &[_]u32{2},
        .OpAtomicLoad, .OpAtomicExchange, .OpAtomicIIncrement, .OpAtomicIDecrement, .OpAtomicIAdd, .OpAtomicFAddEXT,
        .OpAtomicISub, .OpAtomicSMin, .OpAtomicUMin, .OpAtomicSMax, .OpAtomicUMax, .OpAtomicAnd, .OpAtomicOr,
        .OpAtomicXor, .OpAtomicFlagTestAndSet,
        => &[_]u32{4},
        .OpAtomicCompareExchange, .OpAtomicCompareExchangeWeak => &[_]u32{ 4, 5 },
        else => &[_]u32{},
    };
}

/// The opcode switch of Instruction::IsOpcodeSafeToDelete that follows the combinator check.
pub fn opIsSafeToDeleteExtra(op: Op) bool {
    return switch (op) {
        .OpDPdx, .OpDPdy, .OpFwidth, .OpDPdxFine, .OpDPdyFine, .OpFwidthFine, .OpDPdxCoarse, .OpDPdyCoarse,
        .OpFwidthCoarse, .OpImageQueryLod,
        => true,
        else => false,
    };
}

// Operand and instruction model: Operand, Block, Func, InstList and Inst. Instructions are heap objects in intrusive
// doubly linked lists, owned by a block or by a section of the module; every IR object lives in the `ir` arena.

/// One operand of an instruction: its kind and one to many words (up to two words are stored inline, longer ones in
/// the IR arena).
pub const Operand = struct {
    kind: Kind,
    n: u32, // number of words
    w: [2]u32 = .{ 0, 0 }, // inline storage when n <= 2
    heap: ?[*]u32 = null, // storage when n > 2 (IR arena)

    pub fn single(kind: Kind, word: u32) Operand {
        return .{ .kind = kind, .n = 1, .w = .{ word, 0 } };
    }

    pub fn id(kind: Kind, the_id: u32) Operand {
        check(kindIsId(kind), "Operand.id with a non-id kind");
        return single(kind, the_id);
    }

    pub fn fromWords(kind: Kind, ws: []const u32) Operand {
        var o: Operand = .{ .kind = kind, .n = @intCast(ws.len) };
        if (ws.len <= 2) {
            for (ws, 0..) |x, i| o.w[i] = x;
        } else {
            const mem = irAllocator().alloc(u32, ws.len) catch oom();
            @memcpy(mem, ws);
            o.heap = mem.ptr;
        }
        return o;
    }

    /// A LiteralString operand: the bytes, a NUL terminator, zero padding up to a whole number of words.
    pub fn string(s: []const u8) Operand {
        const nwords: usize = s.len / 4 + 1;
        var tmp: List(u32) = .{};
        tmp.reserve(nwords);
        tmp.items = tmp.items.ptr[0..nwords];
        @memset(tmp.items, 0);
        @memcpy(std.mem.sliceAsBytes(tmp.items)[0..s.len], s);
        return fromWords(.LiteralString, tmp.items);
    }

    pub fn words(self: *const Operand) []const u32 {
        if (self.n <= 2) return self.w[0..self.n];
        return self.heap.?[0..self.n];
    }

    pub fn wordsMut(self: *Operand) []u32 {
        if (self.n <= 2) return self.w[0..self.n];
        return self.heap.?[0..self.n];
    }

    pub fn word0(self: *const Operand) u32 {
        check(self.n >= 1, "operand has no words");
        return self.words()[0];
    }

    pub fn asId(self: *const Operand) u32 {
        check(kindIsId(self.kind) and self.n == 1, "operand is not a single id");
        return self.w[0];
    }

    pub fn setWords(self: *Operand, ws: []const u32) void {
        const fresh = Operand.fromWords(self.kind, ws);
        self.* = fresh;
    }

    /// String view of a LiteralString operand (bytes up to the NUL terminator).
    pub fn asString(self: *const Operand) []const u8 {
        check(self.kind == .LiteralString, "operand is not a string");
        const bytes: []align(4) const u8 = std.mem.sliceAsBytes(self.words());
        const end: usize = std.mem.indexOfScalar(u8, bytes, 0) orelse bytes.len;
        return bytes[0..end];
    }

    pub fn asLiteralUint64(self: *const Operand) u64 {
        check(self.n >= 1 and self.n <= 2, "literal does not fit 64 bits");
        const ws: []const u32 = self.words();
        var r: u64 = ws[0];
        if (ws.len > 1) r |= @as(u64, ws[1]) << 32;
        return r;
    }

    pub fn eql(a: *const Operand, b: *const Operand) bool {
        return a.kind == b.kind and std.mem.eql(u32, a.words(), b.words());
    }
};

/// Source of `Inst.unique_id`, the creation order of instructions. Several algorithms order instructions by it, like the C++
/// ones order them by `Instruction::unique_id()`.
var g_next_unique_id: u32 = 1;

/// Intrusive doubly-linked list of instructions. `owner` is the Block that owns the list (null for
/// module-level lists); linking an instruction into a block list sets `inst.block`.
pub const InstList = struct {
    first: ?*Inst = null,
    last: ?*Inst = null,
    owner: ?*Block = null,

    pub fn isEmpty(self: *const InstList) bool {
        return self.first == null;
    }

    pub fn pushBack(self: *InstList, i: *Inst) void {
        check(i.list == null, "instruction is already in a list");
        i.prev = self.last;
        i.next = null;
        if (self.last) |l| l.next = i else self.first = i;
        self.last = i;
        i.list = self;
        i.block = self.owner;
    }

    pub fn pushFront(self: *InstList, i: *Inst) void {
        check(i.list == null, "instruction is already in a list");
        i.prev = null;
        i.next = self.first;
        if (self.first) |f| f.prev = i else self.last = i;
        self.first = i;
        i.list = self;
        i.block = self.owner;
    }

    pub fn insertBefore(self: *InstList, pos: *Inst, i: *Inst) void {
        check(pos.list == self, "insertBefore: position is not in this list");
        check(i.list == null, "instruction is already in a list");
        i.prev = pos.prev;
        i.next = pos;
        if (pos.prev) |p| p.next = i else self.first = i;
        pos.prev = i;
        i.list = self;
        i.block = self.owner;
    }

    pub fn insertAfter(self: *InstList, pos: *Inst, i: *Inst) void {
        check(pos.list == self, "insertAfter: position is not in this list");
        check(i.list == null, "instruction is already in a list");
        i.next = pos.next;
        i.prev = pos;
        if (pos.next) |n| n.prev = i else self.last = i;
        pos.next = i;
        i.list = self;
        i.block = self.owner;
    }

    /// Moves the instructions of `src` in [first, stop) (stop == null: to the end) in front of `before`
    /// (null: at the end of this list), keeping their order. Like the ilist Splice used by the C++.
    pub fn splice(self: *InstList, before: ?*Inst, src: *InstList, first: ?*Inst, stop: ?*Inst) void {
        var it: ?*Inst = first;
        while (it) |i| {
            if (stop) |st| {
                if (i == st) break;
            }
            const nxt: ?*Inst = i.next;
            src.unlink(i);
            if (before) |b| self.insertBefore(b, i) else self.pushBack(i);
            it = nxt;
        }
    }

    pub fn count(self: *const InstList) usize {
        var n: usize = 0;
        var it: ?*Inst = self.first;
        while (it) |i| : (it = i.next) n += 1;
        return n;
    }

    pub fn unlink(self: *InstList, i: *Inst) void {
        check(i.list == self, "unlink: instruction is not in this list");
        if (i.prev) |p| p.next = i.next else self.first = i.next;
        if (i.next) |n| n.prev = i.prev else self.last = i.prev;
        i.prev = null;
        i.next = null;
        i.list = null;
        i.block = null;
    }
};

/// One SPIR-V instruction. `ops` holds every operand, result type id and result id included (like spirv-opt's
/// Instruction), and instructions sit in intrusive doubly linked lists (`prev` / `next`) owned by a block or by a
/// module section.
pub const Inst = struct {
    op: Op,
    unique_id: u32,
    has_type: bool,
    has_result: bool,
    ext_set: ExtSet = .none, // for OpExtInst / OpExtInstWithForwardRefsKHR: the set of the instruction
    ops: IrList(Operand) = .{}, // all operands including result type id and result id (as in spirv-opt)
    dbg_lines: IrList(*Inst) = .{}, // OpLine/OpNoLine attached in front of this instruction
    prev: ?*Inst = null,
    next: ?*Inst = null,
    list: ?*InstList = null,
    block: ?*Block = null, // owning block, maintained by InstList

    pub fn create(op: Op, has_type: bool, has_result: bool) *Inst {
        const i = irAllocator().create(Inst) catch oom();
        i.* = .{ .op = op, .unique_id = g_next_unique_id, .has_type = has_type, .has_result = has_result };
        g_next_unique_id += 1;
        return i;
    }

    /// Builds an instruction from grammar knowledge; `in_ops` are the operands after type/result id.
    pub fn make(op: Op, type_id: u32, result_id: u32, in_ops: []const Operand) *Inst {
        const d: *const InstDesc = lookupInst(opcodeValue(op)) orelse fatal("Inst.make: unknown opcode {d}", .{opcodeValue(op)});
        const i: *Inst = Inst.create(op, d.has_type, d.has_result);
        if (d.has_type) i.ops.push(Operand.id(.IdResultType, type_id));
        if (d.has_result) i.ops.push(Operand.id(.IdResult, result_id));
        i.ops.pushSlice(in_ops);
        return i;
    }

    pub fn typeResultIdCount(self: *const Inst) usize {
        return @as(usize, @intFromBool(self.has_type)) + @as(usize, @intFromBool(self.has_result));
    }

    pub fn typeId(self: *const Inst) u32 {
        if (!self.has_type) return 0;
        return self.ops.items[0].w[0];
    }

    pub fn resultId(self: *const Inst) u32 {
        if (!self.has_result) return 0;
        return self.ops.items[@intFromBool(self.has_type)].w[0];
    }

    pub fn numOperands(self: *const Inst) usize {
        return self.ops.items.len;
    }

    pub fn numInOperands(self: *const Inst) usize {
        return self.ops.items.len - self.typeResultIdCount();
    }

    pub fn getOperand(self: *const Inst, i: usize) *Operand {
        return &self.ops.items[i];
    }

    pub fn getInOperand(self: *const Inst, i: usize) *Operand {
        return &self.ops.items[i + self.typeResultIdCount()];
    }

    pub fn getSingleWordInOperand(self: *const Inst, i: usize) u32 {
        const o: *Operand = self.getInOperand(i);
        check(o.n == 1, "getSingleWordInOperand: operand is not single-word");
        return o.w[0];
    }

    pub fn getSingleWordOperand(self: *const Inst, i: usize) u32 {
        const o: *Operand = self.getOperand(i);
        check(o.n == 1, "getSingleWordOperand: operand is not single-word");
        return o.w[0];
    }

    pub fn setInOperand(self: *Inst, i: usize, ws: []const u32) void {
        self.getInOperand(i).setWords(ws);
    }

    pub fn setResultId(self: *Inst, new_id: u32) void {
        check(self.has_result, "setResultId on an instruction without a result");
        self.ops.items[@intFromBool(self.has_type)].w[0] = new_id;
    }

    pub fn addOperand(self: *Inst, o: Operand) void {
        self.ops.push(o);
    }

    pub fn isNop(self: *const Inst) bool {
        return self.op == .OpNop;
    }

    pub fn isLine(self: *const Inst) bool {
        return self.op == .OpLine;
    }

    pub fn isNoLine(self: *const Inst) bool {
        return self.op == .OpNoLine;
    }

    pub fn isLineInst(self: *const Inst) bool {
        return self.op == .OpLine or self.op == .OpNoLine;
    }

    pub fn isDecoration(self: *const Inst) bool {
        return opIsDecoration(self.op);
    }

    pub fn isBlockTerminator(self: *const Inst) bool {
        return opIsBlockTerminator(self.op);
    }

    /// Deep copy (new unique id, no list membership). Debug-line instructions are cloned too.
    pub fn clone(self: *const Inst) *Inst {
        const c: *Inst = Inst.create(self.op, self.has_type, self.has_result);
        c.ext_set = self.ext_set;
        for (self.ops.items) |*o| c.ops.push(Operand.fromWords(o.kind, o.words()));
        for (self.dbg_lines.items) |l| c.dbg_lines.push(l.clone());
        return c;
    }

    /// Number of words the instruction occupies in a binary (without attached line instructions).
    pub fn wordCount(self: *const Inst) usize {
        var n: usize = 1;
        for (self.ops.items) |o| n += o.n;
        return n;
    }

    // ---- opcode predicates that need no context ----------------------------------------------

    pub fn isBranch(self: *const Inst) bool {
        return opIsBranch(self.op);
    }

    pub fn isReturn(self: *const Inst) bool {
        return opIsReturn(self.op);
    }

    pub fn isReturnOrAbort(self: *const Inst) bool {
        return opIsReturnOrAbort(self.op);
    }

    pub fn isLoad(self: *const Inst) bool {
        return opIsLoad(self.op);
    }

    pub fn isAtomicWithLoad(self: *const Inst) bool {
        return opIsAtomicWithLoad(self.op);
    }

    pub fn isAtomicOp(self: *const Inst) bool {
        return opIsAtomicOp(self.op);
    }

    /// IsConstantInst(op) && !IsSpecConstantInst(op) (Instruction::IsConstant).
    pub fn isConstant(self: *const Inst) bool {
        return opIsNonSpecConstant(self.op);
    }

    pub fn isOpcodeCodeMotionSafe(self: *const Inst) bool {
        return opIsCodeMotionSafe(self.op);
    }

    pub fn hasLabels(self: *const Inst) bool {
        return switch (self.op) {
            .OpSelectionMerge, .OpBranch, .OpLoopMerge, .OpBranchConditional, .OpSwitch, .OpPhi => true,
            else => false,
        };
    }

    pub fn hasBranchWeights(self: *const Inst) bool {
        return self.op == .OpBranchConditional and self.numOperands() == 5;
    }

    pub fn numOperandWords(self: *const Inst) u32 {
        var n: u32 = 0;
        for (self.ops.items) |o| n += o.n;
        return n;
    }

    pub fn numInOperandWords(self: *const Inst) u32 {
        var n: u32 = 0;
        var k: usize = self.typeResultIdCount();
        while (k < self.ops.items.len) : (k += 1) n += self.ops.items[k].n;
        return n;
    }

    // ---- changing an instruction: opcode, operands, position ----------------------------------

    /// Changes the opcode; has_type / has_result follow the grammar of the new opcode, like the C++ where
    /// they are derived from the opcode on every call. The caller fixes the operand list.
    pub fn setOpcode(self: *Inst, new_op: Op) void {
        const d: *const InstDesc = lookupInst(opcodeValue(new_op)) orelse fatal("setOpcode: unknown opcode {d}", .{opcodeValue(new_op)});
        self.op = new_op;
        self.has_type = d.has_type;
        self.has_result = d.has_result;
    }

    /// Replaces every in-operand (type id and result id are kept). `new_ops` are deep-copied, so it may alias
    /// this instruction's own operand storage.
    pub fn setInOperands(self: *Inst, new_ops: []const Operand) void {
        var tmp: List(Operand) = .{};
        for (new_ops) |o| tmp.push(Operand.fromWords(o.kind, o.words()));
        self.ops.truncate(self.typeResultIdCount());
        self.ops.pushSlice(tmp.items);
    }

    /// Replaces ALL operands, result type and result id included.
    pub fn replaceOperands(self: *Inst, new_ops: []const Operand) void {
        var tmp: List(Operand) = .{};
        for (new_ops) |o| tmp.push(Operand.fromWords(o.kind, o.words()));
        self.ops.clear();
        self.ops.pushSlice(tmp.items);
    }

    /// Inst::RemoveInOperand: erases the in-operand at `index` (counted after type and result id).
    pub fn removeInOperand(self: *Inst, index: usize) void {
        check(index < self.numInOperands(), "removeInOperand: index out of range");
        _ = self.ops.orderedRemove(index + self.typeResultIdCount());
    }

    pub fn setResultType(self: *Inst, id: u32) void {
        check(self.has_type, "setResultType on an instruction without a result type");
        self.ops.items[0].w[0] = id;
    }

    pub fn toNop(self: *Inst) void {
        self.op = .OpNop;
        self.has_type = false;
        self.has_result = false;
        self.ops.clear();
    }

    pub fn isInAList(self: *const Inst) bool {
        return self.list != null;
    }

    pub fn nextNode(self: *const Inst) ?*Inst {
        return self.next;
    }

    pub fn prevNode(self: *const Inst) ?*Inst {
        return self.prev;
    }

    /// Inserts `i` before this instruction (which must be linked in a list). Returns `i`.
    pub fn insertBefore(self: *Inst, i: *Inst) *Inst {
        const l: *InstList = self.list orelse fatal("insertBefore: instruction is not in a list", .{});
        l.insertBefore(self, i);
        return i;
    }

    /// Inserts `new` (in order) before this instruction. Returns the first inserted instruction.
    pub fn insertBeforeMany(self: *Inst, new: []const *Inst) *Inst {
        check(new.len > 0, "insertBeforeMany with an empty list");
        for (new) |i| _ = self.insertBefore(i);
        return new[0];
    }

    pub fn insertAfter(self: *Inst, i: *Inst) *Inst {
        const l: *InstList = self.list orelse fatal("insertAfter: instruction is not in a list", .{});
        l.insertAfter(self, i);
        return i;
    }

    pub fn removeFromList(self: *Inst) *Inst {
        const l: *InstList = self.list orelse fatal("removeFromList: instruction is not in a list", .{});
        l.unlink(self);
        return self;
    }

    pub fn moveBefore(self: *Inst, pos: *Inst) void {
        _ = self.removeFromList();
        _ = pos.insertBefore(self);
    }

    /// Visits every id operand (result type and result id included, like spvIsIdType). `f` may rewrite the id.
    /// Return false from `f` to stop; the method then returns false.
    pub fn whileEachId(self: *Inst, ctx: anytype, comptime f: fn (@TypeOf(ctx), *u32) bool) bool {
        for (self.ops.items) |*o| {
            if (kindIsId(o.kind)) {
                if (!f(ctx, &o.w[0])) return false;
            }
        }
        return true;
    }

    pub fn forEachId(self: *Inst, ctx: anytype, comptime f: fn (@TypeOf(ctx), *u32) void) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), p: *u32) bool {
                f(c, p);
                return true;
            }
        };
        _ = self.whileEachId(ctx, Adapter.call);
    }

    /// Like whileEachId but only over in-operands (skips result type and result id).
    pub fn whileEachInId(self: *Inst, ctx: anytype, comptime f: fn (@TypeOf(ctx), *u32) bool) bool {
        var k: usize = self.typeResultIdCount();
        while (k < self.ops.items.len) : (k += 1) {
            const o: *Operand = &self.ops.items[k];
            if (kindIsId(o.kind)) {
                if (!f(ctx, &o.w[0])) return false;
            }
        }
        return true;
    }

    pub fn forEachInId(self: *Inst, ctx: anytype, comptime f: fn (@TypeOf(ctx), *u32) void) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), p: *u32) bool {
                f(c, p);
                return true;
            }
        };
        _ = self.whileEachInId(ctx, Adapter.call);
    }

    /// Visits the first word of every in-operand (ids, literals, enums alike).
    pub fn whileEachInOperand(self: *Inst, ctx: anytype, comptime f: fn (@TypeOf(ctx), *u32) bool) bool {
        var k: usize = self.typeResultIdCount();
        while (k < self.ops.items.len) : (k += 1) {
            if (!f(ctx, &self.ops.items[k].wordsMut()[0])) return false;
        }
        return true;
    }

    pub fn forEachInOperand(self: *Inst, ctx: anytype, comptime f: fn (@TypeOf(ctx), *u32) void) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), p: *u32) bool {
                f(c, p);
                return true;
            }
        };
        _ = self.whileEachInOperand(ctx, Adapter.call);
    }
};

/// Visits `i` (preceded by its attached line instructions when `lines` is set); returns false when `f` asked to stop.
fn whileEachInOne(i: *Inst, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) bool, lines: bool) bool {
    if (lines) {
        for (i.dbg_lines.items) |l| {
            if (!f(ctx, l)) return false;
        }
    }
    return f(ctx, i);
}

/// A function: the OpFunction instruction, its parameters and blocks, the OpFunctionEnd, and the non-semantic
/// instructions that follow it.
pub const Func = struct {
    def: *Inst, // OpFunction
    params: IrList(*Inst) = .{},
    blocks: IrList(*Block) = .{},
    end: ?*Inst = null, // OpFunctionEnd
    nonsemantic: IrList(*Inst) = .{}, // non-semantic ext insts that follow this function

    pub fn new(def: *Inst) *Func {
        const f = irAllocator().create(Func) catch oom();
        f.* = .{ .def = def };
        return f;
    }

    pub fn id(self: *const Func) u32 {
        return self.def.resultId();
    }

    pub fn addBlock(self: *Func, b: *Block) void {
        b.parent = self;
        self.blocks.push(b);
    }

    pub fn typeId(self: *const Func) u32 {
        return self.def.typeId();
    }

    pub fn controlMask(self: *const Func) u32 {
        return self.def.getSingleWordInOperand(0);
    }

    pub fn entry(self: *const Func) *Block {
        check(self.blocks.len() > 0, "Func.entry on a function without blocks");
        return self.blocks.items[0];
    }

    pub fn tail(self: *const Func) *Block {
        check(self.blocks.len() > 0, "Func.tail on a function without blocks");
        return self.blocks.items[self.blocks.len() - 1];
    }

    pub fn isDeclaration(self: *const Func) bool {
        return self.blocks.len() == 0;
    }

    pub fn addParameter(self: *Func, p: *Inst) void {
        self.params.push(p);
    }

    pub fn setFunctionEnd(self: *Func, e: *Inst) void {
        self.end = e;
    }

    pub fn addNonSemanticInstruction(self: *Func, i: *Inst) void {
        self.nonsemantic.push(i);
    }

    pub fn removeParameter(self: *Func, rid: u32) void {
        var k: usize = 0;
        while (k < self.params.len()) {
            if (self.params.items[k].resultId() == rid) {
                _ = self.params.orderedRemove(k);
            } else k += 1;
        }
    }

    /// Index of the block with label id `bb_id` (Function::FindBlock returned an iterator).
    pub fn findBlockIndex(self: *const Func, bb_id: u32) ?usize {
        for (self.blocks.items, 0..) |b, k| {
            if (b.id() == bb_id) return k;
        }
        return null;
    }

    pub fn findBlock(self: *const Func, bb_id: u32) ?*Block {
        const k: usize = self.findBlockIndex(bb_id) orelse return null;
        return self.blocks.items[k];
    }

    fn indexOfBlock(self: *const Func, b: *const Block) usize {
        for (self.blocks.items, 0..) |x, k| {
            if (x == b) return k;
        }
        fatal("Could not find insertion point for block %{d}", .{b.id()});
    }

    /// Function::AddBasicBlock(b, iterator): inserts before position `index`.
    pub fn addBasicBlockAt(self: *Func, b: *Block, index: usize) void {
        b.parent = self;
        self.blocks.insert(index, b);
    }

    pub fn insertBasicBlockAfter(self: *Func, new_block: *Block, position: *const Block) *Block {
        const k: usize = self.indexOfBlock(position);
        new_block.parent = self;
        self.blocks.insert(k + 1, new_block);
        return new_block;
    }

    pub fn insertBasicBlockBefore(self: *Func, new_block: *Block, position: *const Block) *Block {
        const k: usize = self.indexOfBlock(position);
        new_block.parent = self;
        self.blocks.insert(k, new_block);
        return new_block;
    }

    pub fn moveBasicBlockToAfter(self: *Func, bb_id: u32, ip: *const Block) void {
        const k: usize = self.findBlockIndex(bb_id) orelse fatal("moveBasicBlockToAfter: no block %{d}", .{bb_id});
        const b: *Block = self.blocks.orderedRemove(k);
        check(b.parent == ip.parent, "Both blocks have to be in the same function.");
        _ = self.insertBasicBlockAfter(b, ip);
    }

    /// Removes blocks whose label has become an OpNop (Function::RemoveEmptyBlocks).
    pub fn removeEmptyBlocks(self: *Func) void {
        var k: usize = 0;
        while (k < self.blocks.len()) {
            if (self.blocks.items[k].label.op == .OpNop) {
                _ = self.blocks.orderedRemove(k);
            } else k += 1;
        }
    }

    /// Replaces the block order; `order` must contain exactly the blocks of the function.
    pub fn reorderBasicBlocks(self: *Func, order: []const *Block) void {
        check(order.len == self.blocks.len(), "reorderBasicBlocks: wrong number of blocks");
        for (self.blocks.items) |b| {
            var found: bool = false;
            for (order) |o| {
                if (o == b) found = true;
            }
            check(found, "reorderBasicBlocks: block missing from the new order");
        }
        for (order, 0..) |b, k| self.blocks.items[k] = b;
    }

    pub fn whileEachInst(self: *Func, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) bool, lines: bool, nonsemantic: bool) bool {
        if (!whileEachInOne(self.def, ctx, f, lines)) return false;
        for (self.params.items) |p| {
            if (!whileEachInOne(p, ctx, f, lines)) return false;
        }
        for (self.blocks.items) |b| {
            if (!b.whileEachInst(ctx, f, lines)) return false;
        }
        if (self.end) |e| {
            if (!whileEachInOne(e, ctx, f, lines)) return false;
        }
        if (nonsemantic) {
            for (self.nonsemantic.items) |n| {
                if (!whileEachInOne(n, ctx, f, lines)) return false;
            }
        }
        return true;
    }

    pub fn forEachInst(self: *Func, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) void, lines: bool, nonsemantic: bool) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), i: *Inst) bool {
                f(c, i);
                return true;
            }
        };
        _ = self.whileEachInst(ctx, Adapter.call, lines, nonsemantic);
    }

    pub fn whileEachParam(self: *Func, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) bool, lines: bool) bool {
        for (self.params.items) |p| {
            if (!whileEachInOne(p, ctx, f, lines)) return false;
        }
        return true;
    }

    pub fn forEachParam(self: *Func, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) void, lines: bool) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), i: *Inst) bool {
                f(c, i);
                return true;
            }
        };
        _ = self.whileEachParam(ctx, Adapter.call, lines);
    }

    /// Deep copy in the order of Function::Clone: definition, parameters, blocks, end, non-semantic.
    pub fn clone(self: *const Func) *Func {
        const f: *Func = Func.new(self.def.clone());
        for (self.params.items) |p| f.params.push(p.clone());
        for (self.blocks.items) |b| f.addBlock(b.clone());
        if (self.end) |e| f.end = e.clone();
        for (self.nonsemantic.items) |n| f.nonsemantic.push(n.clone());
        return f;
    }
};

/// A basic block: the OpLabel instruction that names it, its instructions, and the function it belongs to.
pub const Block = struct {
    label: *Inst,
    insts: InstList = .{},
    parent: ?*Func = null,

    pub fn new(label: *Inst) *Block {
        const b = irAllocator().create(Block) catch oom();
        b.* = .{ .label = label };
        b.insts.owner = b;
        label.block = b; // like IRContext::get_instr_block(label): the label belongs to its block
        return b;
    }

    pub fn id(self: *const Block) u32 {
        return self.label.resultId();
    }

    pub fn addInst(self: *Block, inst: *Inst) void {
        self.insts.pushBack(inst);
    }

    pub fn terminator(self: *const Block) ?*Inst {
        return self.insts.last;
    }

    /// The last instruction (BasicBlock::tail / terminator); a block without instructions is a bug.
    pub fn tail(self: *const Block) *Inst {
        return self.insts.last orelse fatal("Block.tail: block %{d} has no instructions", .{self.id()});
    }

    pub fn hasSuccessor(self: *const Block) bool {
        return self.tail().isBranch();
    }

    pub fn isReturn(self: *const Block) bool {
        return self.tail().isReturn();
    }

    pub fn isReturnOrAbort(self: *const Block) bool {
        return self.tail().isReturnOrAbort();
    }

    /// Moves every instruction of `other` to the end of this block (BasicBlock::AddInstructions).
    pub fn addInstructions(self: *Block, other: *Block) void {
        self.insts.splice(null, &other.insts, other.insts.first, null);
    }

    /// Label first, then the instructions; the next node is read before the callback runs, so the callback
    /// may unlink or kill the instruction it is given. `lines` also visits attached OpLine/OpNoLine.
    pub fn whileEachInst(self: *Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) bool, lines: bool) bool {
        if (!whileEachInOne(self.label, ctx, f, lines)) return false;
        var it: ?*Inst = self.insts.first;
        while (it) |i| {
            const nxt: ?*Inst = i.next;
            if (!whileEachInOne(i, ctx, f, lines)) return false;
            it = nxt;
        }
        return true;
    }

    pub fn forEachInst(self: *Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) void, lines: bool) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), i: *Inst) bool {
                f(c, i);
                return true;
            }
        };
        _ = self.whileEachInst(ctx, Adapter.call, lines);
    }

    /// Only the leading OpPhi instructions (stops at the first non-phi).
    pub fn whileEachPhiInst(self: *Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) bool, lines: bool) bool {
        var it: ?*Inst = self.insts.first;
        while (it) |i| {
            const nxt: ?*Inst = i.next;
            if (i.op != .OpPhi) break;
            if (!whileEachInOne(i, ctx, f, lines)) return false;
            it = nxt;
        }
        return true;
    }

    pub fn forEachPhiInst(self: *Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) void, lines: bool) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), i: *Inst) bool {
                f(c, i);
                return true;
            }
        };
        _ = self.whileEachPhiInst(ctx, Adapter.call, lines);
    }

    pub fn hasPhiInstructions(self: *const Block) bool {
        const first: *Inst = self.insts.first orelse return false;
        return first.op == .OpPhi;
    }

    /// The labels of the successors of the terminator, in operand order. Callback: return false to stop.
    pub fn whileEachSuccessorLabel(self: *const Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), u32) bool) bool {
        const br: *Inst = self.tail();
        switch (br.op) {
            .OpBranch => return f(ctx, br.getOperand(0).word0()),
            .OpBranchConditional, .OpSwitch => {
                var is_first: bool = true; // the first id is the condition / selector
                for (br.ops.items) |*o| {
                    if (!kindIsId(o.kind)) continue;
                    if (is_first) {
                        is_first = false;
                        continue;
                    }
                    if (!f(ctx, o.w[0])) return false;
                }
                return true;
            },
            else => return true,
        }
    }

    pub fn forEachSuccessorLabel(self: *const Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), u32) void) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), l: u32) bool {
                f(c, l);
                return true;
            }
        };
        _ = self.whileEachSuccessorLabel(ctx, Adapter.call);
    }

    /// The non-const C++ overload: the callback may rewrite the label in place.
    pub fn forEachSuccessorLabelMut(self: *Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), *u32) void) void {
        const br: *Inst = self.tail();
        switch (br.op) {
            .OpBranch => f(ctx, &br.ops.items[0].w[0]),
            .OpBranchConditional, .OpSwitch => {
                var is_first: bool = true;
                for (br.ops.items) |*o| {
                    if (!kindIsId(o.kind)) continue;
                    if (is_first) {
                        is_first = false;
                        continue;
                    }
                    f(ctx, &o.w[0]);
                }
            },
            else => {},
        }
    }

    pub fn isSuccessor(self: *const Block, other: *const Block) bool {
        const Cap = struct { target: u32, found: bool = false };
        const Cb = struct {
            fn visit(c: *Cap, l: u32) void {
                if (l == c.target) c.found = true;
            }
        };
        var cap: Cap = .{ .target = other.id() };
        self.forEachSuccessorLabel(&cap, Cb.visit);
        return cap.found;
    }

    /// OpLoopMerge / OpSelectionMerge directly before the terminator, or null.
    pub fn getMergeInst(self: *const Block) ?*Inst {
        const t: *Inst = self.tail();
        const p: *Inst = t.prev orelse return null;
        if (p.op == .OpLoopMerge or p.op == .OpSelectionMerge) return p;
        return null;
    }

    pub fn getLoopMergeInst(self: *const Block) ?*Inst {
        if (self.getMergeInst()) |m| {
            if (m.op == .OpLoopMerge) return m;
        }
        return null;
    }

    pub fn isLoopHeader(self: *const Block) bool {
        return self.getLoopMergeInst() != null;
    }

    /// Calls f with every id operand of the merge instruction (merge block, then continue target for loops).
    pub fn forMergeAndContinueLabel(self: *const Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), u32) void) void {
        if (self.getMergeInst()) |m| {
            for (m.ops.items) |*o| {
                if (kindIsId(o.kind)) f(ctx, o.w[0]);
            }
        }
    }

    pub fn mergeBlockIdIfAny(self: *const Block) u32 {
        const m: *Inst = self.getMergeInst() orelse return 0;
        return m.getSingleWordInOperand(0);
    }

    pub fn mergeBlockId(self: *const Block) u32 {
        const r: u32 = self.mergeBlockIdIfAny();
        check(r != 0, "Expected block to have a corresponding merge block");
        return r;
    }

    pub fn continueBlockIdIfAny(self: *const Block) u32 {
        const m: *Inst = self.getLoopMergeInst() orelse return 0;
        return m.getSingleWordInOperand(1);
    }

    pub fn continueBlockId(self: *const Block) u32 {
        const r: u32 = self.continueBlockIdIfAny();
        check(r != 0, "Expected block to have a corresponding continue target");
        return r;
    }

    /// Deep copy: label and instructions are cloned (new unique ids, in that order); the copy has no parent.
    pub fn clone(self: *const Block) *Block {
        const b: *Block = Block.new(self.label.clone());
        var it: ?*Inst = self.insts.first;
        while (it) |i| : (it = i.next) b.addInst(i.clone());
        return b;
    }
};

// Module: the instructions of a SPIR-V module grouped by logical section.

/// The five words that start a SPIR-V binary; `bound` is one more than the largest id in use.
pub const Header = struct {
    magic: u32 = spv_magic,
    version: u32 = 0,
    generator: u32 = 0,
    bound: u32 = 0,
    schema: u32 = 0,
};

/// Visits every instruction of `list`; the next node is read before `f` runs, so `f` may unlink the current one.
fn whileEachInList(list: *InstList, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) bool, lines: bool) bool {
    var it: ?*Inst = list.first;
    while (it) |i| {
        const nxt: ?*Inst = i.next; // callers may unlink `i` from within f
        if (!whileEachInOne(i, ctx, f, lines)) return false;
        it = nxt;
    }
    return true;
}

/// Visits the instructions of a function in binary order: OpFunction, parameters, blocks, OpFunctionEnd, then the
/// non-semantic instructions that follow it.
fn whileEachInFunc(fun: *Func, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) bool, lines: bool) bool {
    if (!whileEachInOne(fun.def, ctx, f, lines)) return false;
    for (fun.params.items) |p| {
        if (!whileEachInOne(p, ctx, f, lines)) return false;
    }
    for (fun.blocks.items) |b| {
        if (!whileEachInOne(b.label, ctx, f, lines)) return false;
        if (!whileEachInList(&b.insts, ctx, f, lines)) return false;
    }
    if (fun.end) |e| {
        if (!whileEachInOne(e, ctx, f, lines)) return false;
    }
    for (fun.nonsemantic.items) |n| {
        if (!whileEachInOne(n, ctx, f, lines)) return false;
    }
    return true;
}

/// A whole module, with its instructions grouped by logical section in the order the SPIR-V specification requires.
pub const Module = struct {
    header: Header = .{},
    capabilities: InstList = .{},
    extensions: InstList = .{},
    ext_inst_imports: InstList = .{},
    memory_model: ?*Inst = null,
    sampled_image_address_mode: ?*Inst = null,
    entry_points: InstList = .{},
    execution_modes: InstList = .{},
    debugs1: InstList = .{},
    debugs2: InstList = .{},
    debugs3: InstList = .{},
    annotations: InstList = .{},
    types_values: InstList = .{},
    functions: IrList(*Func) = .{},
    graph_entry_points: InstList = .{},
    graph_insts: InstList = .{}, // OpGraphARM ... OpGraphEndARM, kept flat in original order
    trailing_dbg_lines: IrList(*Inst) = .{},
    max_id_bound: u32 = default_max_id_bound,

    pub fn new() *Module {
        const m = irAllocator().create(Module) catch oom();
        m.* = .{};
        return m;
    }

    pub fn takeNextId(self: *Module) u32 {
        if (self.header.bound >= self.max_id_bound) {
            fatal("ID overflow: id bound 0x{x} reached (limit 0x{x})", .{ self.header.bound, self.max_id_bound });
        }
        const r: u32 = self.header.bound;
        self.header.bound += 1;
        return r;
    }

    pub fn idBound(self: *const Module) u32 {
        return self.header.bound;
    }

    pub fn setIdBound(self: *Module, bound: u32) void {
        check(bound != 0, "setIdBound(0)");
        self.header.bound = bound;
    }

    pub fn addCapability(self: *Module, i: *Inst) void {
        self.capabilities.pushBack(i);
    }

    pub fn addExtension(self: *Module, i: *Inst) void {
        self.extensions.pushBack(i);
    }

    pub fn addExtInstImport(self: *Module, i: *Inst) void {
        self.ext_inst_imports.pushBack(i);
    }

    pub fn setMemoryModel(self: *Module, i: *Inst) void {
        self.memory_model = i;
    }

    pub fn setSampledImageAddressMode(self: *Module, i: *Inst) void {
        self.sampled_image_address_mode = i;
    }

    pub fn addEntryPoint(self: *Module, i: *Inst) void {
        self.entry_points.pushBack(i);
    }

    pub fn addExecutionMode(self: *Module, i: *Inst) void {
        self.execution_modes.pushBack(i);
    }

    pub fn addDebug1Inst(self: *Module, i: *Inst) void {
        self.debugs1.pushBack(i);
    }

    pub fn addDebug2Inst(self: *Module, i: *Inst) void {
        self.debugs2.pushBack(i);
    }

    pub fn addDebug3Inst(self: *Module, i: *Inst) void {
        self.debugs3.pushBack(i);
    }

    pub fn addAnnotationInst(self: *Module, i: *Inst) void {
        self.annotations.pushBack(i);
    }

    pub fn addType(self: *Module, i: *Inst) void {
        self.types_values.pushBack(i);
    }

    pub fn addGlobalValue(self: *Module, i: *Inst) void {
        self.types_values.pushBack(i);
    }

    /// Module::AddGlobalValue(opcode, result_id, type_id): an operand-less global such as OpConstantNull's shell.
    pub fn addGlobalValueOp(self: *Module, op: Op, result_id: u32, type_id: u32) void {
        self.types_values.pushBack(Inst.make(op, type_id, result_id, &.{}));
    }

    pub fn addFunction(self: *Module, f: *Func) void {
        self.functions.push(f);
    }

    pub fn addFunctionDeclaration(self: *Module, f: *Func) void {
        self.functions.insert(0, f);
    }

    /// Type instructions of the types/values section, in order (scratch list).
    pub fn getTypes(self: *const Module) List(*Inst) {
        var r: List(*Inst) = .{};
        var it: ?*Inst = self.types_values.first;
        while (it) |i| : (it = i.next) {
            if (opIsTypeInst(i.op)) r.push(i);
        }
        return r;
    }

    pub fn getConstants(self: *const Module) List(*Inst) {
        var r: List(*Inst) = .{};
        var it: ?*Inst = self.types_values.first;
        while (it) |i| : (it = i.next) {
            if (opIsConstant(i.op)) r.push(i);
        }
        return r;
    }

    /// Result id of the first global value with this opcode, or 0.
    pub fn getGlobalValue(self: *const Module, op: Op) u32 {
        var it: ?*Inst = self.types_values.first;
        while (it) |i| : (it = i.next) {
            if (i.op == op) return i.resultId();
        }
        return 0;
    }

    pub fn hasExplicitCapability(self: *const Module, cap: u32) bool {
        var it: ?*Inst = self.capabilities.first;
        while (it) |i| : (it = i.next) {
            if (i.getSingleWordOperand(0) == cap) return true;
        }
        return false;
    }

    /// Result id of the OpExtInstImport named `name`, or 0.
    pub fn getExtInstImportId(self: *const Module, name: []const u8) u32 {
        var it: ?*Inst = self.ext_inst_imports.first;
        while (it) |i| : (it = i.next) {
            if (std.mem.eql(u8, i.getInOperand(0).asString(), name)) return i.resultId();
        }
        return 0;
    }

    /// Highest id used by any operand (attached lines included) plus one.
    pub fn computeIdBound(self: *Module) u32 {
        const Cb = struct {
            fn visit(highest: *u32, inst: *Inst) void {
                for (inst.ops.items) |*o| {
                    if (kindIsId(o.kind)) highest.* = @max(highest.*, o.w[0]);
                }
            }
        };
        var highest: u32 = 0;
        self.forEachInst(&highest, Cb.visit, true);
        return highest + 1;
    }

    /// Visits every instruction in binary order. With `lines` the attached OpLine/OpNoLine
    /// instructions are visited immediately before the instruction that owns them.
    /// `f(ctx, inst) bool`: return false to stop early. Returns false if stopped early.
    pub fn whileEachInst(self: *Module, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) bool, lines: bool) bool {
        if (!whileEachInList(&self.capabilities, ctx, f, lines)) return false;
        if (!whileEachInList(&self.extensions, ctx, f, lines)) return false;
        if (!whileEachInList(&self.ext_inst_imports, ctx, f, lines)) return false;
        if (self.memory_model) |i| if (!whileEachInOne(i, ctx, f, lines)) return false;
        if (self.sampled_image_address_mode) |i| if (!whileEachInOne(i, ctx, f, lines)) return false;
        if (!whileEachInList(&self.entry_points, ctx, f, lines)) return false;
        if (!whileEachInList(&self.execution_modes, ctx, f, lines)) return false;
        if (!whileEachInList(&self.debugs1, ctx, f, lines)) return false;
        if (!whileEachInList(&self.debugs2, ctx, f, lines)) return false;
        if (!whileEachInList(&self.debugs3, ctx, f, lines)) return false;
        if (!whileEachInList(&self.annotations, ctx, f, lines)) return false;
        if (!whileEachInList(&self.types_values, ctx, f, lines)) return false;
        for (self.functions.items) |fun| {
            if (!whileEachInFunc(fun, ctx, f, lines)) return false;
        }
        if (!whileEachInList(&self.graph_entry_points, ctx, f, lines)) return false;
        if (!whileEachInList(&self.graph_insts, ctx, f, lines)) return false;
        if (lines) {
            for (self.trailing_dbg_lines.items) |l| {
                if (!f(ctx, l)) return false;
            }
        }
        return true;
    }

    pub fn forEachInst(self: *Module, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) void, lines: bool) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), i: *Inst) bool {
                f(c, i);
                return true;
            }
        };
        _ = self.whileEachInst(ctx, Adapter.call, lines);
    }
};

// Binary parser (port of the Parser of source/binary.cpp) and IR loader (port of source/opt/ir_loader.cpp): the words
// of a SPIR-V binary become a Module. Operand layouts come from the grammar tables; the loader attaches OpLine /
// OpNoLine to the instruction that follows them and sorts instructions into module sections and functions.

/// What the loader does with extended debug info instructions: reject the module (`fail`) or drop them while loading
/// (`strip`).
pub const DebugExtPolicy = enum { fail, strip };

/// What the parser has to remember between instructions to lay out the operands of the next one.
const ParseState = struct {
    id_to_type: Map(u32, u32) = .{}, // result id -> type id (type-generating instructions map to themselves)
    type_width: Map(u32, u32) = .{}, // numeric type id -> bit width (0 = valid type but not numeric)
    import_to_set: Map(u32, ExtSet) = .{},
};

/// The result of parsing one instruction.
const ParsedInst = struct {
    inst: *Inst,
};

/// Pushes `specs` so that the first operand specification ends up on top of the stack.
fn pushSpecsReversed(stack: *List(OperandSpec), specs: []const OperandSpec) void {
    var i: usize = specs.len;
    while (i > 0) {
        i -= 1;
        stack.push(specs[i]);
    }
}

/// True for operand specifications that may match zero words or many (`?` and `*` in the grammar).
fn specIsOptionalOrVariable(s: OperandSpec) bool {
    return s.quant != .one;
}

/// Port of spvTakeFirstMatchableOperand + spvExpandOperandSequenceOnce using (kind, quantifier) pairs.
fn takeFirstMatchable(stack: *List(OperandSpec)) OperandSpec {
    while (true) {
        const e: OperandSpec = stack.pop() orelse fatal("internal: operand pattern stack is empty", .{});
        switch (e.quant) {
            .one => {
                if (kindCategory(e.kind) == .composite) fatal("unsupported non-repeated composite operand kind", .{});
                return e;
            },
            .opt => {
                if (kindCategory(e.kind) == .composite) fatal("unsupported optional composite operand kind", .{});
                return e;
            },
            .rep => switch (e.kind) {
                // VARIABLE_ID_LITERAL_INTEGER: pairs (id, literal)
                .PairIdRefLiteralInteger => {
                    stack.push(e);
                    stack.push(.{ .kind = .LiteralInteger, .quant = .one });
                    return .{ .kind = .IdRef, .quant = .opt };
                },
                // VARIABLE_LITERAL_INTEGER_ID: pairs (typed literal, id)
                .PairLiteralIntegerIdRef => {
                    stack.push(e);
                    stack.push(.{ .kind = .IdRef, .quant = .one });
                    return .{ .kind = .LiteralContextDependentNumber, .quant = .opt };
                },
                // OpPhi's pairs are two ids: SPIRV-Tools' grammar table generator maps PairIdRefIdRef* to VARIABLE_ID
                .PairIdRefIdRef => {
                    stack.push(e);
                    return .{ .kind = .IdRef, .quant = .opt };
                },
                else => {
                    stack.push(e);
                    return .{ .kind = e.kind, .quant = .opt };
                },
            },
        }
    }
}

/// Longest literal string the parser accepts, in words (the limit of the SPIR-V word count field).
const max_string_words: usize = 65535;

/// The words ended in the middle of an operand: the binary is malformed.
fn exhausted(desc: *const InstDesc, offset: usize) noreturn {
    fatal("End of input reached while decoding Op{s} starting at word {d}: expected more operands", .{ desc.name, offset });
}

/// Decodes one operand of kind `kind` from the words at `*wi_ptr` and pushes the operands that follow from it (the
/// enumerants of a bit mask or value enum bring their own parameters).
fn parseOperand(ps: *ParseState, desc: *const InstDesc, inst: *Inst, iw: []const u32, wi_ptr: *usize, kind: Kind, stack: *List(OperandSpec), offset: usize) void {
    const wi: usize = wi_ptr.*;
    if (wi >= iw.len) exhausted(desc, offset);
    const word: u32 = iw[wi];
    var nwords: usize = 1;
    switch (kindCategory(kind)) {
        .id => {
            if (word == 0) fatal("Op{s} at word {d}: id operand is 0", .{ desc.name, offset });
            switch (kind) {
                .IdResultType => {},
                .IdResult => {
                    if (ps.id_to_type.contains(word)) fatal("Id {d} is defined more than once", .{word});
                    const tid: u32 = if (opGeneratesType(desc.op)) word else inst.typeId();
                    ps.id_to_type.put(word, tid);
                },
                .IdRef => {
                    if (opIsExtendedInstruction(desc.op) and wi == 3) {
                        inst.ext_set = ps.import_to_set.get(word) orelse
                            fatal("OpExtInst set Id {d} does not reference an OpExtInstImport result Id", .{word});
                    }
                },
                else => {},
            }
        },
        .literal => switch (kind) {
            .LiteralInteger, .LiteralFloat => {},
            .LiteralExtInstInteger => {
                check(opIsExtendedInstruction(desc.op), "ext inst number outside OpExtInst");
                const set: ExtSet = inst.ext_set;
                if (lookupExtInst(set, word)) |ed| {
                    if (extSetIsNonSemantic(set)) stack.push(.{ .kind = .IdRef, .quant = .rep });
                    pushSpecsReversed(stack, ed.operands);
                } else {
                    if (!extSetIsNonSemantic(set)) fatal("Invalid extended instruction number: {d}", .{word});
                    stack.push(.{ .kind = .IdRef, .quant = .rep });
                }
            },
            .LiteralSpecConstantOpInteger => {
                check(desc.op == .OpSpecConstantOp, "spec-constant-op number outside OpSpecConstantOp");
                if (word > 0xFFFF) fatal("Invalid OpSpecConstantOp opcode: {d}", .{word});
                const inner: *const InstDesc = lookupInst(word) orelse fatal("Invalid OpSpecConstantOp opcode: {d}", .{word});
                if (!inner.has_type or !inner.has_result or inner.operands.len < 2) fatal("Invalid OpSpecConstantOp opcode: {d}", .{word});
                pushSpecsReversed(stack, inner.operands[2..]);
            },
            .LiteralContextDependentNumber => {
                var type_id: u32 = 0;
                if (desc.op == .OpSwitch) {
                    const selector: u32 = iw[1];
                    const sel_type: u32 = ps.id_to_type.get(selector) orelse fatal("Invalid OpSwitch: selector id {d} has no type", .{selector});
                    if (sel_type == 0 or sel_type == selector) fatal("Invalid OpSwitch: selector id {d} is not a value", .{selector});
                    type_id = sel_type;
                } else {
                    check(desc.op == .OpConstant or desc.op == .OpSpecConstant, "typed literal outside OpConstant/OpSpecConstant/OpSwitch");
                    type_id = inst.typeId();
                }
                const width: u32 = ps.type_width.get(type_id) orelse fatal("Type Id {d} is not a type", .{type_id});
                if (width == 0) fatal("Type Id {d} is not a scalar numeric type", .{type_id});
                nwords = (width + 31) / 32;
            },
            .LiteralString => {
                const rest: []align(4) const u8 = std.mem.sliceAsBytes(iw[wi..]);
                const nul: usize = std.mem.indexOfScalar(u8, rest, 0) orelse exhausted(desc, offset);
                nwords = nul / 4 + 1;
                if (nwords > max_string_words) fatal("Literal string is longer than {d} words", .{max_string_words});
                if (desc.op == .OpExtInstImport) {
                    const s: []align(4) const u8 = rest[0..nul];
                    const set: ExtSet = extSetFromImportName(s);
                    if (set == .none) fatal("Invalid extended instruction import '{s}'", .{s});
                    ps.import_to_set.put(inst.resultId(), set);
                }
            },
            else => fatal("internal: unhandled literal operand kind {s}", .{@tagName(kind)}),
        },
        .value_enum => {
            const e: *const Enumerant = lookupEnumerant(kind, word) orelse fatal("Invalid {s} operand: {d}", .{ @tagName(kind), word });
            pushSpecsReversed(stack, e.params);
        },
        .bit_enum => {
            // Scan MSB -> LSB so operands of lower bits are consumed first (stack is LIFO).
            var remaining: u32 = word;
            var mask: u32 = 1 << 31;
            while (remaining != 0) : (mask >>= 1) {
                if (remaining & mask != 0) {
                    const e: *const Enumerant = lookupEnumerant(kind, mask) orelse
                        fatal("Invalid {s} operand: {d} has invalid mask component {d}", .{ @tagName(kind), word, mask });
                    remaining ^= mask;
                    pushSpecsReversed(stack, e.params);
                }
            }
            if (word == 0) {
                if (lookupEnumerant(kind, 0)) |e| pushSpecsReversed(stack, e.params);
            }
        },
        .composite => fatal("internal: composite operand reached parseOperand", .{}),
    }
    if (wi + nwords > iw.len) exhausted(desc, offset);
    inst.ops.push(Operand.fromWords(kind, iw[wi .. wi + nwords]));
    wi_ptr.* = wi + nwords;
}

/// Decodes the instruction that starts at `offset` of `iw` (the words of one instruction) into an Inst, operand by
/// operand according to the grammar entry `desc`.
fn parseOneInstruction(ps: *ParseState, desc: *const InstDesc, iw: []const u32, offset: usize) *Inst {
    const inst: *Inst = Inst.create(desc.op, desc.has_type, desc.has_result);
    var stack: List(OperandSpec) = .{};
    pushSpecsReversed(&stack, desc.operands);
    var wi: usize = 1;
    while (wi < iw.len) {
        if (stack.len() == 0) {
            fatal("Invalid instruction Op{s} at word {d}: expected no more operands after {d} words, but stated word count is {d}", .{ desc.name, offset, wi, iw.len });
        }
        const spec: OperandSpec = takeFirstMatchable(&stack);
        parseOperand(ps, desc, inst, iw, &wi, spec.kind, &stack, offset);
    }
    if (stack.len() > 0 and !specIsOptionalOrVariable(stack.last())) {
        fatal("End of input reached while decoding Op{s} starting at word {d}: expected more operands after {d} words", .{ desc.name, offset, iw.len });
    }
    return inst;
}

/// State of the binary-to-IR loader: the module being filled and the function / block currently open.
pub const Loader = struct {
    module: *Module,
    policy: DebugExtPolicy,
    func: ?*Func = null,
    block: ?*Block = null,
    in_graph: bool = false,
    pending_lines: IrList(*Inst) = .{},
    last_line: ?*Inst = null,
    removed_ids: Set(u32) = .{},
    ps: ParseState = .{},
};

/// True for an instruction of one of the extended debug info sets, which this port does not support.
fn isDebugExtInst(inst: *const Inst) bool {
    return opIsExtendedInstruction(inst.op) and extSetIsDebugInfo(inst.ext_set);
}

/// Adds a parsed instruction to the module. Extended debug info is rejected or dropped according to the policy,
/// OpLine / OpNoLine are held back and attached to the next instruction, and the instruction goes to the open block or
/// function, or to the module section its opcode belongs to.
fn loaderAdd(ld: *Loader, inst: *Inst) void {
    const m: *Module = ld.module;
    const op: Op = inst.op;

    if (op == .OpExtInstImport) {
        const set: ExtSet = extSetFromImportName(inst.getInOperand(0).asString());
        if (extSetIsDebugInfo(set)) {
            if (ld.policy == .fail) {
                fatal("module imports extended debug info set '{s}'; re-run with --strip-debug-ext to remove it", .{inst.getInOperand(0).asString()});
            }
            _ = ld.removed_ids.insert(inst.resultId());
            return;
        }
    }
    if (isDebugExtInst(inst)) {
        if (ld.policy == .fail) {
            fatal("module uses extended debug info instructions; re-run with --strip-debug-ext to remove them", .{});
        }
        if (inst.has_result) _ = ld.removed_ids.insert(inst.resultId());
        return;
    }

    // OpLine / OpNoLine are attached to the next real instruction (ir_loader.cpp IsLineInst path).
    if (inst.isLineInst()) {
        ld.last_line = null;
        ld.pending_lines.push(inst);
        return;
    }

    // Attach pending line info, with extra line tracking (BuildModule default).
    if (ld.pending_lines.len() > 0) {
        inst.dbg_lines.pushSlice(ld.pending_lines.items);
        const back: *Inst = inst.dbg_lines.last();
        if (!back.isNoLine()) ld.last_line = back.clone();
        ld.pending_lines.clear();
    } else if (ld.last_line) |ll| {
        inst.dbg_lines.push(ll);
        ld.last_line = ll.clone();
    }

    if (op == .OpFunction) {
        if (ld.func != null) fatal("function inside function", .{});
        ld.func = Func.new(inst);
    } else if (op == .OpFunctionEnd) {
        const f: *Func = ld.func orelse fatal("OpFunctionEnd without corresponding OpFunction", .{});
        if (ld.block != null) fatal("OpFunctionEnd inside basic block", .{});
        f.end = inst;
        m.functions.push(f);
        ld.func = null;
    } else if (op == .OpLabel) {
        if (ld.func == null) fatal("OpLabel outside function", .{});
        if (ld.block != null) fatal("OpLabel inside basic block", .{});
        ld.block = Block.new(inst);
    } else if (opIsBlockTerminator(op)) {
        const f: *Func = ld.func orelse fatal("terminator instruction outside function", .{});
        const b: *Block = ld.block orelse fatal("terminator instruction outside basic block", .{});
        b.addInst(inst);
        f.addBlock(b);
        ld.block = null;
        ld.last_line = null;
        ld.pending_lines.clear();
    } else if (op == .OpGraphARM) {
        if (ld.in_graph) fatal("graph inside graph", .{});
        ld.in_graph = true;
        m.graph_insts.pushBack(inst);
    } else if (op == .OpGraphEndARM) {
        if (!ld.in_graph) fatal("OpGraphEndARM without corresponding OpGraphARM", .{});
        m.graph_insts.pushBack(inst);
        ld.in_graph = false;
    } else if (op == .OpGraphConstantARM) {
        m.types_values.pushBack(inst);
    } else if (ld.in_graph) {
        m.graph_insts.pushBack(inst);
    } else if (ld.func) |f| {
        if (ld.block) |b| {
            b.addInst(inst);
        } else {
            if (op != .OpFunctionParameter) {
                fatal("Non-OpFunctionParameter (opcode: {d}) found inside function but outside basic block", .{opcodeValue(op)});
            }
            f.params.push(inst);
        }
    } else {
        check(ld.block == null, "loader: block without function");
        if (op == .OpCapability or op == .OpConditionalCapabilityINTEL) {
            m.capabilities.pushBack(inst);
        } else if (op == .OpExtension or op == .OpConditionalExtensionINTEL) {
            m.extensions.pushBack(inst);
        } else if (op == .OpExtInstImport) {
            m.ext_inst_imports.pushBack(inst);
        } else if (op == .OpMemoryModel) {
            m.memory_model = inst;
        } else if (op == .OpSamplerImageAddressingModeNV) {
            m.sampled_image_address_mode = inst;
        } else if (op == .OpEntryPoint) {
            m.entry_points.pushBack(inst);
        } else if (op == .OpGraphEntryPointARM) {
            m.graph_entry_points.pushBack(inst);
        } else if (op == .OpExecutionMode or op == .OpExecutionModeId) {
            m.execution_modes.pushBack(inst);
        } else if (opIsDebug1(op)) {
            m.debugs1.pushBack(inst);
        } else if (opIsDebug2(op)) {
            m.debugs2.pushBack(inst);
        } else if (opIsDebug3(op)) {
            m.debugs3.pushBack(inst);
        } else if (opIsAnnotation(op)) {
            m.annotations.pushBack(inst);
        } else if (opIsTypeInst(op)) {
            m.types_values.pushBack(inst);
        } else if (opIsConstant(op) or op == .OpVariable or op == .OpUntypedVariableKHR or op == .OpUndef) {
            m.types_values.pushBack(inst);
        } else if (opIsExtendedInstruction(op) and extSetIsNonSemantic(inst.ext_set)) {
            // After the last function (or graph) if there is one, else among the global values.
            if (m.graph_insts.last != null) {
                m.graph_insts.pushBack(inst);
            } else if (m.functions.len() > 0) {
                m.functions.last().nonsemantic.push(inst);
            } else {
                m.types_values.pushBack(inst);
            }
        } else {
            fatal("Unhandled inst type (opcode: {d}) found outside function definition.", .{opcodeValue(op)});
        }
    }
}

/// State of the check that no instruction refers to an id that --strip-debug-ext removed.
const StripCtx = struct {
    removed: *Set(u32),
    bad: ?*Inst = null,
};

/// Records the first instruction that refers to a removed id (other than the OpName / OpMemberName that name it).
fn stripCheckInst(c: *StripCtx, inst: *Inst) bool {
    for (inst.ops.items) |*o| {
        if (kindIsId(o.kind) and o.kind != .IdResult and c.removed.contains(o.w[0])) {
            c.bad = inst;
            return false;
        }
    }
    return true;
}

/// After --strip-debug-ext: OpName/OpMemberName that name removed ids are dropped; any other remaining
/// reference to a removed id is a hard error (loud failure instead of a dangling id).
fn stripRemovedReferences(m: *Module, removed: *Set(u32)) void {
    var it: ?*Inst = m.debugs2.first;
    while (it) |i| {
        const nxt: ?*Inst = i.next;
        if (removed.contains(i.getInOperand(0).w[0])) m.debugs2.unlink(i);
        it = nxt;
    }
    var c: StripCtx = .{ .removed = removed };
    if (!m.whileEachInst(&c, stripCheckInst, true)) {
        fatal("--strip-debug-ext: instruction Op{s} still references a removed debug-info id", .{@tagName(c.bad.?.op)[2..]});
    }
}

/// Parses `words` (a complete SPIR-V binary in native word order) into a Module.
pub fn loadModule(words: []const u32, policy: DebugExtPolicy) *Module {
    if (words.len < spv_header_words) fatal("input is too small to be a SPIR-V module ({d} words)", .{words.len});
    if (words[0] != spv_magic) {
        if (@byteSwap(words[0]) == spv_magic) fatal("byte-swapped (opposite-endian) SPIR-V is not supported", .{});
        fatal("invalid SPIR-V magic number 0x{x}", .{words[0]});
    }
    const m: *Module = Module.new();
    m.header = .{ .magic = words[0], .version = words[1], .generator = words[2], .bound = words[3], .schema = words[4] };
    if (m.header.bound == 0) fatal("invalid id bound 0", .{});

    var ld: Loader = .{ .module = m, .policy = policy };
    var pos: usize = spv_header_words;
    while (pos < words.len) {
        const w0: u32 = words[pos];
        const wc: usize = w0 >> 16;
        const opcode: u32 = w0 & 0xFFFF;
        if (wc < 1) fatal("Invalid instruction word count: {d}", .{wc});
        const desc: *const InstDesc = lookupInst(opcode) orelse fatal("Invalid opcode: {d}", .{opcode});
        if (pos + wc > words.len) fatal("Truncated binary: instruction at word {d} claims {d} words but the binary ends at {d}", .{ pos, wc, words.len });
        const inst: *Inst = parseOneInstruction(&ld.ps, desc, words[pos .. pos + wc], pos);
        // Record the numeric width of type instructions (used to size typed literals).
        if (opGeneratesType(desc.op)) {
            const width: u32 = switch (desc.op) {
                .OpTypeInt, .OpTypeFloat => inst.getSingleWordInOperand(0),
                else => 0,
            };
            ld.ps.type_width.put(inst.resultId(), width);
        }
        loaderAdd(&ld, inst);
        pos += wc;
    }

    // EndModule: missing terminator / OpFunctionEnd are tolerated like spirv-opt does.
    if (ld.block != null and ld.func != null) {
        ld.func.?.addBlock(ld.block.?);
        ld.block = null;
    }
    if (ld.func) |f| {
        m.functions.push(f);
        ld.func = null;
    }
    if (ld.in_graph) fatal("OpGraphARM without OpGraphEndARM", .{});
    m.trailing_dbg_lines.pushSlice(ld.pending_lines.items);

    if (ld.removed_ids.count() > 0) stripRemovedReferences(m, &ld.removed_ids);
    return m;
}

// Binary writer (port of Module::ToBinary, without DebugScope handling): a Module becomes the words of a binary.

/// Hash and equality of a list of words, the key of the duplicate-decoration filter of the writer.
const SliceCtx = struct {
    pub fn hash(_: SliceCtx, k: []const u32) u64 {
        return std.hash.Wyhash.hash(0, std.mem.sliceAsBytes(k));
    }
    pub fn eql(_: SliceCtx, a: []const u32, b: []const u32) bool {
        return std.mem.eql(u32, a, b);
    }
};

/// State of the binary writer: the output words, the options, the decorations already written (for the duplicate
/// filter) and the line tracking that decides which OpLine / OpNoLine instructions are written.
const Writer = struct {
    out: *List(u32),
    skip_nop: bool,
    filter_dup_decorations: bool,
    last_line: ?*Inst = null,
    between_merge_and_branch: bool = false,
    seen: std.HashMapUnmanaged([]const u32, void, SliceCtx, 80) = .empty,
};

/// Appends the words of `i`: the word count and opcode word, then every operand.
fn instWords(out: *List(u32), i: *const Inst) void {
    out.push((@as(u32, @intCast(i.wordCount())) << 16) | @as(u32, @intFromEnum(i.op)));
    for (i.ops.items) |*o| out.pushSlice(o.words());
}

/// Writes one instruction. Line instructions are visited as instructions of their own: an OpLine equal to the current
/// one is not repeated, an OpNoLine is written when an instruction without line information follows a line, the line
/// state ends at a block terminator, and line instructions between a merge instruction and its branch are dropped.
/// OpNop and duplicate decorations are skipped when the options ask for it.
fn writeInst(w: *Writer, i: *Inst) bool {
    if (w.filter_dup_decorations and i.isDecoration()) {
        var tmp: List(u32) = .{};
        instWords(&tmp, i);
        const gop: std.HashMapUnmanaged([]const u32, void, SliceCtx, 80).GetOrPutResult = w.seen.getOrPut(scAllocator(), tmp.items) catch oom();
        if (gop.found_existing) return true;
    }
    if (w.between_merge_and_branch and i.isLineInst()) return true;
    if (w.last_line) |ll| {
        if (i.isLine()) {
            var same: bool = true;
            const n: usize = ll.numInOperands();
            for (0..n) |k| {
                if (i.numInOperands() <= k or !std.mem.eql(u32, ll.getInOperand(k).words(), i.getInOperand(k).words())) {
                    same = false;
                    break;
                }
            }
            if (same) return true;
        } else if (!i.isNoLine() and i.dbg_lines.len() == 0) {
            w.out.push((1 << 16) | @as(u32, @intFromEnum(Op.OpNoLine)));
            w.last_line = null;
        }
    }
    if (!(w.skip_nop and i.isNop())) instWords(w.out, i);
    w.between_merge_and_branch = false;
    if (opIsBlockTerminator(i.op) or i.isNoLine()) {
        w.last_line = null;
    } else if (i.op == .OpLoopMerge or i.op == .OpSelectionMerge) {
        w.between_merge_and_branch = true;
        w.last_line = null;
    } else if (i.isLine()) {
        w.last_line = i;
    }
    return true;
}

/// Serializes `m`: the header, then every instruction in binary order. `skip_nop` drops OpNop and
/// `filter_dup_decorations` drops a decoration that was already written with the same words.
pub fn moduleToBinary(m: *Module, out: *List(u32), skip_nop: bool, filter_dup_decorations: bool) void {
    out.push(m.header.magic);
    out.push(m.header.version);
    out.push(m.header.generator);
    out.push(m.header.bound);
    out.push(m.header.schema);
    var w: Writer = .{ .out = out, .skip_nop = skip_nop, .filter_dup_decorations = filter_dup_decorations };
    _ = m.whileEachInst(&w, writeInst, true);
}

// Round-trip command line: parse a binary and write it back, a check of the parser and the writer.

/// Prints the usage of the round-trip command line.
fn foundationUsage() noreturn {
    std.debug.print(
        \\usage: spirvopt [options] <input.spv> [-o <output.spv>]
        \\  -o <file>            output file (default: no output, parse + verify only)
        \\  --strip-debug-ext    remove OpenCL.DebugInfo.100 / NonSemantic.Shader.DebugInfo / DebugInfo
        \\                       instructions instead of failing when they are present
        \\  --keep-nops          do not drop OpNop when writing
        \\  --keep-dup-decorations
        \\                       do not drop duplicate decorations when writing (test aid)
        \\
    , .{});
    std.process.exit(2);
}

/// Reads a binary, writes it back without optimizing, and exits. The optimizer's entry point is `main` in the driver.
pub fn foundationMain(init: std.process.Init) !void {
    const gpa: std.mem.Allocator = init.gpa;
    const io: std.Io = init.io;
    memInit(std.heap.page_allocator);
    defer memDeinit();

    var in_path: ?[]const u8 = null;
    var out_path: ?[]const u8 = null;
    var policy: DebugExtPolicy = .fail;
    var skip_nop: bool = true;
    var dedup_decorations: bool = true;
    var it: std.process.Args.Iterator = init.minimal.args.iterate();
    _ = it.next();
    while (it.next()) |arg| {
        if (std.mem.eql(u8, arg, "-o")) {
            out_path = it.next() orelse foundationUsage();
        } else if (std.mem.eql(u8, arg, "--strip-debug-ext")) {
            policy = .strip;
        } else if (std.mem.eql(u8, arg, "--keep-nops")) {
            skip_nop = false;
        } else if (std.mem.eql(u8, arg, "--keep-dup-decorations")) {
            dedup_decorations = false;
        } else if (arg.len > 0 and arg[0] == '-') {
            foundationUsage();
        } else if (in_path == null) {
            in_path = arg;
        } else {
            foundationUsage();
        }
    }
    const path: []const u8 = in_path orelse foundationUsage();

    const bytes: []align(4) u8 = std.Io.Dir.cwd().readFileAllocOptions(io, path, gpa, .limited(1 << 30), .of(u32), null) catch |e|
        fatal("cannot read '{s}': {t}", .{ path, e });
    defer gpa.free(bytes);
    if (bytes.len % 4 != 0) fatal("input size {d} is not a multiple of 4", .{bytes.len});
    const words: []const u32 = std.mem.bytesAsSlice(u32, bytes);

    const m: *Module = loadModule(words, policy);

    var out: List(u32) = .{};
    moduleToBinary(m, &out, skip_nop, dedup_decorations);

    if (out_path) |op| {
        const buf = gpa.alloc(u8, out.items.len * 4) catch oom();
        defer gpa.free(buf);
        for (out.items, 0..) |wd, k| std.mem.writeInt(u32, buf[k * 4 ..][0..4], wd, .little);
        std.Io.Dir.cwd().writeFile(io, .{ .sub_path = op, .data = buf }) catch |e|
            fatal("cannot write '{s}': {t}", .{ op, e });
    }
}

// Tests (zig test spirvopt.zig). They double as executable documentation of the container API.

test "foundation: every declaration compiles" {
    const t = std.testing;
    t.refAllDecls(@This());
    t.refAllDecls(List(u32));
    t.refAllDecls(IrList(*Inst));
    t.refAllDecls(Map(u32, u32));
    t.refAllDecls(OrderedMap(u32, u32));
    t.refAllDecls(Set(u32));
    t.refAllDecls(Queue(u32));
    t.refAllDecls(SortedMap(u32, u32, ascending(u32)));
    t.refAllDecls(SortedSet(u32, ascending(u32)));
    t.refAllDecls(Operand);
    t.refAllDecls(Inst);
    t.refAllDecls(InstList);
    t.refAllDecls(Block);
    t.refAllDecls(Func);
