pub const max_result_id: u32 = 0x400000; // kMaxResultId of cfg.cpp: the id of the pseudo exit block

// Ctx, the IRContext (ports of ir_context.h / ir_context.cpp): the module plus every analysis built over it. Analyses
// are built lazily on first use, a pass reports which ones it keeps valid (`Analysis` flags), and all of them are
// dropped at the end of a pass together with the scratch arena. Ctx also holds the operations that have to keep several
// analyses consistent: replaceAllUsesWith, killInst, instruction insertion, id allocation.

/// Bit flags naming the analyses a pass can preserve; the values are those of the C++ `IRContext::Analysis` enum.
pub const Analysis = struct { // bit flags: the values are those of the C++ enum
    pub const none: u32 = 0;
    pub const def_use: u32 = 1 << 0;
    pub const instr_to_block: u32 = 1 << 1; // always valid in this port (Inst.block is maintained by InstList)
    pub const decorations: u32 = 1 << 2;
    pub const combinators: u32 = 1 << 3;
    pub const cfg: u32 = 1 << 4;
    pub const dominator: u32 = 1 << 5;
    pub const loops: u32 = 1 << 6;
    pub const name_map: u32 = 1 << 7;
    pub const scalar_evolution: u32 = 1 << 8;
    pub const register_pressure: u32 = 1 << 9;
    pub const value_number_table: u32 = 1 << 10;
    pub const structured_cfg: u32 = 1 << 11;
    pub const builtin_var_id: u32 = 1 << 12;
    pub const id_to_func: u32 = 1 << 13;
    pub const constants: u32 = 1 << 14;
    pub const types: u32 = 1 << 15;
    pub const debug_info: u32 = 1 << 16; // never set: extended debug info is not supported
    pub const liveness: u32 = 1 << 17;
    pub const id_to_graph: u32 = 1 << 18;
    pub const all_but_end: u32 = (1 << 19) - 1;
};

pub const NameMap = Map(u32, List(*Inst)); // std::multimap<uint32_t, Instruction*>: one list per key, insertion order

pub const stage_max: u32 = 0x7fffffff; // spv::ExecutionModel::Max

/// Instruction::IsNonSemanticInstruction: an OpExtInst of a NonSemantic.* set.
fn isNonSemanticInst(inst: *const Inst) bool {
    if (inst.op != .OpExtInst) return false;
    return inst.ext_set == .nonsemantic_shader_debuginfo_100 or inst.ext_set == .nonsemantic_graph_debuginfo or
        inst.ext_set == .nonsemantic_clspvreflection or inst.ext_set == .nonsemantic_vkspreflection or
        inst.ext_set == .nonsemantic_debugprintf or inst.ext_set == .nonsemantic_unknown;
}

// Type (port of source/opt/types.h, types.cpp)
//
// The C++ class hierarchy becomes one tagged union. Types live in the scratch arena (the TypeMgr that owns
// them is dropped at every pass boundary). Child types are `*const Type`; the few in-place fix-ups the
// C++ does during TypeMgr analysis go through the payload pointers of a mutable `*Type`.
// Not ported: Type::str() / GetDecorationStr() (debug output only).

