/// Array::LengthInfo: `id` is the id of the length instruction, `words` is [case, ...] (see ArrayLength).
pub const ArrayLengthInfo = struct { id: u32, words: List(u32) };

/// Decorations of the members of a struct: member index -> list of decorations, each one the words [decoration, parameters...].
pub const MemberDecorations = SortedMap(u32, List(List(u32)), ascending(u32));

/// Kind of a type: one value per family of OpType* instructions, in the order of Type::Kind of types.h.
pub const TypeKind = enum(u8) { // same order as Type::Kind
    void_,
    bool_,
    integer,
    float,
    vector,
    matrix,
    image,
    sampler,
    sampled_image,
    array,
    runtime_array,
    node_payload_array_amdx,
    struct_,
    opaque_,
    pointer,
    function,
    event,
    device_event,
    reserve_id,
    queue,
    pipe,
    forward_pointer,
    pipe_storage,
    named_barrier,
    acceleration_structure_nv,
    cooperative_matrix_nv,
    cooperative_matrix_khr,
    cooperative_vector_nv,
    ray_query_khr,
    hit_object_nv,
    hit_object_ext,
    tensor_layout_nv,
    tensor_view_nv,
    tensor_arm,
    graph_arm,
    buffer_ext,
};

/// OpTypeInt.
pub const TyInteger = struct { width: u32, is_signed: bool };
/// OpTypeFloat. `encoding` is the optional encoding operand, `fp_encoding_max` when there is none.
pub const TyFloat = struct { width: u32, encoding: u32 };

/// The three forms of `ArrayLengthInfo.words`; the first word says which one it is.
pub const ArrayLength = struct {
    pub const constant: u32 = 0; // words = {0, value words...}
    pub const constant_with_spec_id: u32 = 1; // words = {1, spec id, value words...}
    pub const defining_id: u32 = 2; // words = {2, id}
};

/// OpTypeOpaque.
pub const TyOpaque = struct { name: []const u8 };

/// OpTypePipe.
pub const TyPipe = struct { access: u32 };

/// OpTypeTensorLayoutNV.
pub const TyTensorLayoutNV = struct { dim_id: u32, clamp_mode_id: u32 };
/// OpTypeTensorViewNV.
pub const TyTensorViewNV = struct { dim_id: u32, has_dimensions_id: u32, perm: List(u32) };

/// OpTypeBufferEXT.
pub const TyBufferEXT = struct { storage_class: u32 };

/// Mixes `v` into the hash `seed` (boost::hash_combine; the arithmetic wraps like the C++).
fn hashCombine(seed: u64, v: u64) u64 {
    return seed ^ (v +% 0x9e3779b9 +% (seed << 6) +% (seed >> 2));
}

/// Mixes every word of `ws` into the hash `h_in`.
fn hashWordList(h_in: u64, ws: []const u32) u64 {
    var h: u64 = h_in;
    for (ws) |w| h = hashCombine(h, w);
    return h;
}

/// Stable insertion sort of the indices `idx` by the first word of the list each one names.
fn insertionSortByFront(idx: []u32, lists: []const List(u32)) void {
    var i: usize = 1;
    while (i < idx.len) : (i += 1) {
        const v: u32 = idx[i];
        var j: usize = i;
        while (j > 0 and lists[v].items[0] < lists[idx[j - 1]].items[0]) : (j -= 1) idx[j] = idx[j - 1];
        idx[j] = v;
    }
}

/// CompareTwoVectors: equal as multisets ordered by the first word of each vector.
fn compareDecorationLists(a: []const List(u32), b: []const List(u32)) bool {
    if (a.len != b.len) return false;
    if (a.len == 0) return true;
    if (a.len == 1) return std.mem.eql(u32, a[0].items, b[0].items);
    var ia: List(u32) = .{};
    var ib: List(u32) = .{};
    for (0..a.len) |k| {
        ia.push(@intCast(k));
        ib.push(@intCast(k));
    }
    // stable insertion sort by the first word (std::sort uses insertion sort for the small sizes seen here)
    insertionSortByFront(ia.items, a);
    insertionSortByFront(ib.items, b);
    for (ia.items, ib.items) |x, y| {
        if (!std.mem.eql(u32, a[x].items, b[y].items)) return false;
    }
    return true;
}

/// Copy of a list of words.
fn cloneWords(src: []const u32) List(u32) {
    var r: List(u32) = .{};
    r.pushSlice(src);
    return r;
}

/// Deep copy of a list of decorations.
fn cloneDecorationLists(src: []const List(u32)) List(List(u32)) {
    var r: List(List(u32)) = .{};
    for (src) |d| r.push(cloneWords(d.items));
    return r;
}

/// OpTypeVector.
pub const TyVector = struct { element: *const Type, count: u32 };
/// OpTypeMatrix. `element` is the column type and `count` the number of columns.
pub const TyMatrix = struct { element: *const Type, count: u32 };
/// OpTypeImage: the operands of the instruction after the sampled type, in the same order.
pub const TyImage = struct {
    sampled_type: *const Type,
    dim: u32,
    depth: u32,
    arrayed: bool,
    ms: bool,
    sampled: u32,
    format: u32,
    access: u32,
};
/// OpTypeSampledImage.
pub const TySampledImage = struct { image: *const Type };

/// OpTypeArray.
pub const TyArray = struct { element: *const Type, length: ArrayLengthInfo };
/// OpTypeRuntimeArray.
pub const TyRuntimeArray = struct { element: *const Type };
/// OpTypeNodePayloadArrayAMDX.
pub const TyNodePayloadArray = struct { element: *const Type };

/// OpTypeStruct. The decorations of its members are kept here, not in `Type.decorations`.
pub const TyStruct = struct { elements: List(*const Type), member_decorations: MemberDecorations };

/// OpTypePointer, or OpTypeUntypedPointerKHR when `pointee` is null.
pub const TyPointer = struct { pointee: ?*const Type, storage_class: u32 }; // pointee == null: untyped pointer
/// OpTypeFunction.
pub const TyFunction = struct { ret: *const Type, params: List(*const Type) };

/// OpTypeForwardPointer: `target_id` is the id of the pointer type that is declared later; `pointer` is that type once it
/// has been seen.
pub const TyForwardPointer = struct { target_id: u32, storage_class: u32, pointer: ?*const Type };
/// OpTypeCooperativeMatrixNV; the scope, rows and columns are ids of constants.
pub const TyCoopMatNV = struct { component: *const Type, scope_id: u32, rows_id: u32, columns_id: u32 };
/// OpTypeCooperativeMatrixKHR; the scope, rows, columns and use are ids of constants.
pub const TyCoopMatKHR = struct { component: *const Type, scope_id: u32, rows_id: u32, columns_id: u32, use_id: u32 };
/// OpTypeCooperativeVectorNV.
pub const TyCoopVecNV = struct { component: *const Type, components: u32 };

/// OpTypeTensorARM.
pub const TyTensorARM = struct { element: *const Type, rank_id: u32, shape_id: u32 };
/// OpTypeGraphARM: the first `num_inputs` entries of `io_types` are the inputs, the others the outputs.
pub const TyGraphARM = struct { num_inputs: u32, io_types: List(*const Type) };

/// Two types that are being compared (see IsSameCache).
const SamePair = struct { a: *const Type, b: *const Type };
/// Type::IsSameCache: the (pointer, pointer) pairs currently being compared (a handful at most: linear set).
pub const IsSameCache = List(SamePair);
/// The types already visited by a recursive walk over types (the hash computation), so that a cycle through a forward
/// pointer ends the walk.
pub const SeenTypes = List(*const Type);

/// Copy of a list of type pointers (the types themselves are shared).
fn cloneTypePtrs(src: []const *const Type) List(*const Type) {
    var r: List(*const Type) = .{};
    r.pushSlice(src);
    return r;
}

/// A SPIR-V type as the optimizer sees it: a tagged union over the type kinds plus its decorations. Types live in the
/// scratch arena of the TypeMgr.
pub const Type = struct {
    decorations: List(List(u32)) = .{},
    data: Data,

    pub const Data = union(TypeKind) {
        void_: void,
        bool_: void,
        integer: TyInteger,
        float: TyFloat,
        vector: TyVector,
        matrix: TyMatrix,
        image: TyImage,
        sampler: void,
        sampled_image: TySampledImage,
        array: TyArray,
        runtime_array: TyRuntimeArray,
        node_payload_array_amdx: TyNodePayloadArray,
        struct_: TyStruct,
        opaque_: TyOpaque,
        pointer: TyPointer,
        function: TyFunction,
        event: void,
        device_event: void,
        reserve_id: void,
        queue: void,
        pipe: TyPipe,
        forward_pointer: TyForwardPointer,
        pipe_storage: void,
        named_barrier: void,
        acceleration_structure_nv: void,
        cooperative_matrix_nv: TyCoopMatNV,
        cooperative_matrix_khr: TyCoopMatKHR,
        cooperative_vector_nv: TyCoopVecNV,
        ray_query_khr: void,
        hit_object_nv: void,
        hit_object_ext: void,
        tensor_layout_nv: TyTensorLayoutNV,
        tensor_view_nv: TyTensorViewNV,
        tensor_arm: TyTensorARM,
        graph_arm: TyGraphARM,
        buffer_ext: TyBufferEXT,
    };

    // ---- constructors (values; use boxed() or TypeMgr.registerType to keep one) ------------------

    pub fn simple(k: TypeKind) Type {
        return switch (k) {
            .void_ => .{ .data = .void_ },
            .bool_ => .{ .data = .bool_ },
            .sampler => .{ .data = .sampler },
            .event => .{ .data = .event },
            .device_event => .{ .data = .device_event },
            .reserve_id => .{ .data = .reserve_id },
            .queue => .{ .data = .queue },
            .pipe_storage => .{ .data = .pipe_storage },
            .named_barrier => .{ .data = .named_barrier },
            .acceleration_structure_nv => .{ .data = .acceleration_structure_nv },
            .ray_query_khr => .{ .data = .ray_query_khr },
            .hit_object_nv => .{ .data = .hit_object_nv },
            .hit_object_ext => .{ .data = .hit_object_ext },
            else => fatal("Type.simple: {s} has a payload", .{@tagName(k)}),
        };
    }

    pub fn integer(width: u32, is_signed: bool) Type {
        return .{ .data = .{ .integer = .{ .width = width, .is_signed = is_signed } } };
    }

    pub fn float(width: u32, encoding: u32) Type {
        return .{ .data = .{ .float = .{ .width = width, .encoding = encoding } } };
    }

    // The C++ constructors only assert on their arguments (debug builds); like the release build, none of that is checked.
    pub fn vector(element: *const Type, count: u32) Type {
        return .{ .data = .{ .vector = .{ .element = element, .count = count } } };
    }

    pub fn matrix(column: *const Type, count: u32) Type {
        return .{ .data = .{ .matrix = .{ .element = column, .count = count } } };
    }

    pub fn image(sampled_type: *const Type, dim: u32, depth: u32, arrayed: bool, ms: bool, sampled: u32, format: u32, access: u32) Type {
        return .{ .data = .{ .image = .{ .sampled_type = sampled_type, .dim = dim, .depth = depth, .arrayed = arrayed, .ms = ms, .sampled = sampled, .format = format, .access = access } } };
    }

    pub fn sampledImage(img: *const Type) Type {
        return .{ .data = .{ .sampled_image = .{ .image = img } } };
    }

    pub fn array(element: *const Type, length: ArrayLengthInfo) Type {
        return .{ .data = .{ .array = .{ .element = element, .length = length } } };
    }

    pub fn runtimeArray(element: *const Type) Type {
        return .{ .data = .{ .runtime_array = .{ .element = element } } };
    }

    pub fn nodePayloadArray(element: *const Type) Type {
        return .{ .data = .{ .node_payload_array_amdx = .{ .element = element } } };
    }

    pub fn structOf(elements: []const *const Type) Type {
        return .{ .data = .{ .struct_ = .{ .elements = cloneTypePtrs(elements), .member_decorations = .{} } } };
    }

    pub fn opaqueNamed(name: []const u8) Type {
        return .{ .data = .{ .opaque_ = .{ .name = name } } };
    }

    pub fn pointer(pointee: ?*const Type, storage_class: u32) Type {
        return .{ .data = .{ .pointer = .{ .pointee = pointee, .storage_class = storage_class } } };
    }

    pub fn function(ret: *const Type, params: []const *const Type) Type {
        return .{ .data = .{ .function = .{ .ret = ret, .params = cloneTypePtrs(params) } } };
    }

    pub fn pipe(access: u32) Type {
        return .{ .data = .{ .pipe = .{ .access = access } } };
    }

    pub fn forwardPointer(target_id: u32, storage_class: u32) Type {
        return .{ .data = .{ .forward_pointer = .{ .target_id = target_id, .storage_class = storage_class, .pointer = null } } };
    }

    /// Moves a value type into the scratch arena.
    pub fn boxed(self: Type) *Type {
        const p = scAllocator().create(Type) catch oom();
        p.* = self;
        return p;
    }

    // ---- accessors ------------------------------------------------------------------------------

    pub fn kind(self: *const Type) TypeKind {
        return std.meta.activeTag(self.data);
    }

    /// The C++ AsXxx(): the payload when the kind matches, else null.  `ty.as(.vector)` -> ?*const TyVector.
    pub fn as(self: *const Type, comptime k: TypeKind) ?*const @FieldType(Data, @tagName(k)) {
        if (self.data != k) return null;
        return &@field(self.data, @tagName(k));
    }

    pub fn asMut(self: *Type, comptime k: TypeKind) ?*@FieldType(Data, @tagName(k)) {
        if (self.data != k) return null;
        return &@field(self.data, @tagName(k));
    }

    pub fn isCooperativeMatrix(self: *const Type) bool {
        return self.data == .cooperative_matrix_khr or self.data == .cooperative_matrix_nv;
    }

    pub fn addDecoration(self: *Type, d: List(u32)) void {
        self.decorations.push(d);
    }

    pub fn addMemberDecoration(self: *Type, index: u32, d: List(u32)) void {
        const s: *TyStruct = self.asMut(.struct_) orelse fatal("Type.addMemberDecoration: not a struct", .{});
        if (index >= s.elements.len()) return; // C++: assert(0 && "index out of bound"); return; (the assert vanishes in release builds)
        if (s.member_decorations.getPtr(index)) |l| {
            l.push(d);
        } else {
            var l: List(List(u32)) = .{};
            l.push(d);
            s.member_decorations.put(index, l);
        }
    }

    /// Type::decoration_empty (Struct also looks at member decorations).
    pub fn decorationEmpty(self: *const Type) bool {
        if (self.data == .struct_) return self.decorations.len() == 0 and self.data.struct_.member_decorations.count() == 0;
        return self.decorations.len() == 0;
    }

    pub fn hasSameDecorations(self: *const Type, that: *const Type) bool {
        return compareDecorationLists(self.decorations.items, that.decorations.items);
    }

    pub fn isUniqueType(self: *const Type) bool {
        return switch (self.data) {
            .pointer, .struct_, .array, .runtime_array, .node_payload_array_amdx => false,
            else => true,
        };
    }

    // ---- equality -------------------------------------------------------------------------------

    pub fn isSame(self: *const Type, that: *const Type) bool {
        var seen: IsSameCache = .{};
        return self.isSameImpl(that, &seen);
    }

    pub fn isSameImpl(self: *const Type, that: *const Type, seen: *IsSameCache) bool {
        if (self.kind() != that.kind()) return false;
        switch (self.data) {
            .void_, .bool_, .sampler, .event, .device_event, .reserve_id, .queue, .pipe_storage, .named_barrier, .acceleration_structure_nv, .ray_query_khr, .hit_object_nv, .hit_object_ext => {
                return self.hasSameDecorations(that);
            },
            .integer => |a| {
                const b: TyInteger = that.data.integer;
                return a.width == b.width and a.is_signed == b.is_signed and self.hasSameDecorations(that);
            },
            .float => |a| {
                const b: TyFloat = that.data.float;
                return a.width == b.width and a.encoding == b.encoding and self.hasSameDecorations(that);
            },
            .vector => |a| {
                const b: TyVector = that.data.vector;
                return a.count == b.count and a.element.isSameImpl(b.element, seen) and self.hasSameDecorations(that);
            },
            .matrix => |a| {
                const b: TyMatrix = that.data.matrix;
                return a.count == b.count and a.element.isSameImpl(b.element, seen) and self.hasSameDecorations(that);
            },
            .image => |a| {
                const b: TyImage = that.data.image;
                return a.dim == b.dim and a.depth == b.depth and a.arrayed == b.arrayed and a.ms == b.ms and a.sampled == b.sampled and
                    a.format == b.format and a.access == b.access and a.sampled_type.isSameImpl(b.sampled_type, seen) and self.hasSameDecorations(that);
            },
            .sampled_image => |a| {
                return a.image.isSameImpl(that.data.sampled_image.image, seen) and self.hasSameDecorations(that);
            },
            .array => |a| {
                const b: TyArray = that.data.array;
                var same: bool = a.element.isSameImpl(b.element, seen);
                same = same and self.hasSameDecorations(that);
                same = same and std.mem.eql(u32, a.length.words.items, b.length.words.items);
                return same;
            },
            .runtime_array => |a| {
                return a.element.isSameImpl(that.data.runtime_array.element, seen) and self.hasSameDecorations(that);
            },
            .node_payload_array_amdx => |a| {
                return a.element.isSameImpl(that.data.node_payload_array_amdx.element, seen) and self.hasSameDecorations(that);
            },
            .struct_ => |*a| {
                const b: *const TyStruct = &that.data.struct_;
                if (a.elements.len() != b.elements.len()) return false;
                if (a.member_decorations.count() != b.member_decorations.count()) return false;
                if (!self.hasSameDecorations(that)) return false;
                for (a.elements.items, b.elements.items) |x, y| {
                    if (!x.isSameImpl(y, seen)) return false;
                }
                for (a.member_decorations.keys(), a.member_decorations.values()) |key, list| {
                    const other: *List(List(u32)) = b.member_decorations.getPtr(key) orelse return false;
                    if (!compareDecorationLists(list.items, other.items)) return false;
                }
                return true;
            },
            .opaque_ => |a| {
                return std.mem.eql(u8, a.name, that.data.opaque_.name) and self.hasSameDecorations(that);
            },
            .pointer => |a| {
                const b: TyPointer = that.data.pointer;
                if (a.storage_class != b.storage_class) return false;
                const pair: SamePair = .{ .a = self, .b = that };
                for (seen.items) |p| {
                    if (p.a == pair.a and p.b == pair.b) return true;
                }
                seen.push(pair);
                if (a.pointee != null and b.pointee != null) {
                    const same_pointee: bool = a.pointee.?.isSameImpl(b.pointee.?, seen);
                    _ = seen.pop();
                    if (!same_pointee) return false;
                } else {
                    _ = seen.pop();
                    if (a.pointee != b.pointee) return false;
                }
                return self.hasSameDecorations(that);
            },
            .function => |*a| {
                const b: *const TyFunction = &that.data.function;
                if (!a.ret.isSameImpl(b.ret, seen)) return false;
                if (a.params.len() != b.params.len()) return false;
                for (a.params.items, b.params.items) |x, y| {
                    if (!x.isSameImpl(y, seen)) return false;
                }
                return self.hasSameDecorations(that);
            },
            .pipe => |a| return a.access == that.data.pipe.access and self.hasSameDecorations(that),
            .forward_pointer => |a| {
                const b: TyForwardPointer = that.data.forward_pointer;
                const same_target: bool = if (a.pointer != null and b.pointer != null) a.pointer.?.isSame(b.pointer.?) else a.target_id == b.target_id;
                return same_target and a.storage_class == b.storage_class and self.hasSameDecorations(that);
            },
            .cooperative_matrix_nv => |a| {
                const b: TyCoopMatNV = that.data.cooperative_matrix_nv;
                return a.component.isSameImpl(b.component, seen) and a.scope_id == b.scope_id and a.rows_id == b.rows_id and
                    a.columns_id == b.columns_id and self.hasSameDecorations(that);
            },
            .cooperative_matrix_khr => |a| {
                const b: TyCoopMatKHR = that.data.cooperative_matrix_khr;
                return a.component.isSameImpl(b.component, seen) and a.scope_id == b.scope_id and a.rows_id == b.rows_id and
                    a.columns_id == b.columns_id and a.use_id == b.use_id and self.hasSameDecorations(that);
            },
            .cooperative_vector_nv => |a| {
                const b: TyCoopVecNV = that.data.cooperative_vector_nv;
                return a.component.isSameImpl(b.component, seen) and a.components == b.components and self.hasSameDecorations(that);
            },
            // these four do not compare decorations in the C++
            .tensor_layout_nv => |a| {
                const b: TyTensorLayoutNV = that.data.tensor_layout_nv;
                return a.dim_id == b.dim_id and a.clamp_mode_id == b.clamp_mode_id;
            },
            .tensor_view_nv => |*a| {
                const b: *const TyTensorViewNV = &that.data.tensor_view_nv;
                return a.dim_id == b.dim_id and a.has_dimensions_id == b.has_dimensions_id and std.mem.eql(u32, a.perm.items, b.perm.items);
            },
            .tensor_arm => |a| {
                const b: TyTensorARM = that.data.tensor_arm;
                return a.element.isSameImpl(b.element, seen) and a.rank_id == b.rank_id and a.shape_id == b.shape_id and self.hasSameDecorations(that);
            },
            .graph_arm => |*a| {
                const b: *const TyGraphARM = &that.data.graph_arm;
                if (a.num_inputs != b.num_inputs) return false;
                if (a.io_types.len() != b.io_types.len()) return false;
                for (a.io_types.items, b.io_types.items) |x, y| {
                    if (!x.isSameImpl(y, seen)) return false;
                }
                return true;
            },
            .buffer_ext => |a| return a.storage_class == that.data.buffer_ext.storage_class,
        }
    }

    // ---- hashing (the structure of Type::ComputeHashValue; the numbers differ, they are only compared inside this program) ---------

    pub fn hashValue(self: *const Type) u64 {
        var seen: SeenTypes = .{};
        return self.computeHashValue(0, &seen);
    }

    pub fn computeHashValue(self: *const Type, hash_in: u64, seen: *SeenTypes) u64 {
        for (seen.items) |s| {
            if (s == self) return hash_in;
        }
        seen.push(self);
        var h: u64 = hashCombine(hash_in, @intFromEnum(self.kind()));
        for (self.decorations.items) |d| h = hashWordList(h, d.items);
        switch (self.data) {
            .void_, .bool_, .sampler, .event, .device_event, .reserve_id, .queue, .pipe_storage, .named_barrier, .acceleration_structure_nv, .ray_query_khr, .hit_object_nv, .hit_object_ext => {},
            .integer => |a| {
                h = hashCombine(h, a.width);
                h = hashCombine(h, @intFromBool(a.is_signed));
            },
            .float => |a| {
                h = hashCombine(h, a.width);
                h = hashCombine(h, a.encoding);
            },
            .vector => |a| {
                h = hashCombine(h, a.count);
                h = a.element.computeHashValue(h, seen);
            },
            .matrix => |a| {
                h = hashCombine(h, a.count);
                h = a.element.computeHashValue(h, seen);
            },
            .image => |a| {
                h = hashCombine(h, a.dim);
                h = hashCombine(h, a.depth);
                h = hashCombine(h, @intFromBool(a.arrayed));
                h = hashCombine(h, @intFromBool(a.ms));
                h = hashCombine(h, a.sampled);
                h = hashCombine(h, a.format);
                h = hashCombine(h, a.access);
                h = a.sampled_type.computeHashValue(h, seen);
            },
            .sampled_image => |a| h = a.image.computeHashValue(h, seen),
            .array => |a| {
                h = hashWordList(h, a.length.words.items);
                h = a.element.computeHashValue(h, seen);
            },
            .runtime_array => |a| h = a.element.computeHashValue(h, seen),
            .node_payload_array_amdx => |a| h = a.element.computeHashValue(h, seen),
            .struct_ => |*a| {
                for (a.elements.items) |t| h = t.computeHashValue(h, seen);
                for (a.member_decorations.keys(), a.member_decorations.values()) |key, list| {
                    h = hashCombine(h, key);
                    for (list.items) |d| h = hashWordList(h, d.items);
                }
            },
            .opaque_ => |a| h = hashCombine(h, std.hash.Wyhash.hash(0, a.name)),
            .pointer => |a| {
                h = hashCombine(h, a.storage_class);
                if (a.pointee) |p| h = p.computeHashValue(h, seen);
            },
            .function => |*a| {
                for (a.params.items) |t| h = t.computeHashValue(h, seen);
                h = a.ret.computeHashValue(h, seen);
            },
            .pipe => |a| h = hashCombine(h, a.access),
            .forward_pointer => |a| {
                h = hashCombine(h, a.target_id);
                h = hashCombine(h, a.storage_class);
                if (a.pointer) |p| h = p.computeHashValue(h, seen);
            },
            .cooperative_matrix_nv => |a| {
                h = hashCombine(h, a.scope_id);
                h = hashCombine(h, a.rows_id);
                h = hashCombine(h, a.columns_id);
                h = a.component.computeHashValue(h, seen);
            },
            .cooperative_matrix_khr => |a| {
                h = hashCombine(h, a.scope_id);
                h = hashCombine(h, a.rows_id);
                h = hashCombine(h, a.columns_id);
                h = hashCombine(h, a.use_id);
                h = a.component.computeHashValue(h, seen);
            },
            .cooperative_vector_nv => |a| {
                h = hashCombine(h, a.components);
                h = a.component.computeHashValue(h, seen);
            },
            .tensor_layout_nv => |a| {
                h = hashCombine(h, a.dim_id);
                h = hashCombine(h, a.clamp_mode_id);
            },
            .tensor_view_nv => |*a| {
                h = hashCombine(h, a.dim_id);
                h = hashCombine(h, a.has_dimensions_id);
                h = hashWordList(h, a.perm.items);
            },
            .tensor_arm => |a| {
                h = hashCombine(h, a.rank_id);
                h = hashCombine(h, a.shape_id);
                h = a.element.computeHashValue(h, seen);
            },
            .graph_arm => |*a| {
                h = hashCombine(h, a.num_inputs);
                for (a.io_types.items) |t| h = t.computeHashValue(h, seen);
            },
            .buffer_ext => |a| h = hashCombine(h, a.storage_class),
        }
        _ = seen.pop();
        return h;
    }

    // ---- copies ---------------------------------------------------------------------------------

    /// Type::Clone: a deep copy (decorations included). Child type pointers are shared, as in C++.
    pub fn clone(self: *const Type) *Type {
        var t: Type = .{ .decorations = cloneDecorationLists(self.decorations.items), .data = self.data };
        switch (self.data) {
            .array => |a| t.data.array.length.words = cloneWords(a.length.words.items),
            .struct_ => |*a| {
                t.data.struct_.elements = cloneTypePtrs(a.elements.items);
                var md: MemberDecorations = .{};
                for (a.member_decorations.keys(), a.member_decorations.values()) |key, list| {
                    md.put(key, cloneDecorationLists(list.items));
                }
                t.data.struct_.member_decorations = md;
            },
            .function => |*a| t.data.function.params = cloneTypePtrs(a.params.items),
            .tensor_view_nv => |*a| t.data.tensor_view_nv.perm = cloneWords(a.perm.items),
            .graph_arm => |*a| t.data.graph_arm.io_types = cloneTypePtrs(a.io_types.items),
            else => {},
        }
        return t.boxed();
    }

    pub fn removeDecorations(self: *const Type) *Type {
        const t: *Type = self.clone();
        t.decorations = .{};
        if (t.data == .struct_) t.data.struct_.member_decorations = .{};
        return t;
    }

    // ---- queries --------------------------------------------------------------------------------

    /// Type::NumberOfComponents (UINT64_MAX when unknown/unbounded).
    pub fn numberOfComponents(self: *const Type) u64 {
        switch (self.data) {
            .vector => |a| return a.count,
            .matrix => |a| return a.count,
            .array => |a| {
                const w: []u32 = a.length.words.items;
                if (w[0] != ArrayLength.constant) return std.math.maxInt(u64);
                check(w.len <= 3, "The size of the array could not fit size_t.");
                var length: u64 = w[1];
                if (w.len > 2) length |= @as(u64, w[2]) << 32;
                return length;
            },
            .runtime_array => return std.math.maxInt(u64),
            .struct_ => |*a| return a.elements.len(),
            else => return 0,
        }
    }

    /// Type::GetByteOffset (u32 arithmetic wraps like the C++).
    pub fn getByteOffset(self: *const Type, access_chain: []const u32) ?u32 {
        var offset: u32 = 0;
        var current: *const Type = self;
        for (access_chain) |index| {
            switch (current.data) {
                .struct_ => |*s| {
                    var member_offset: ?u32 = null;
                    for (s.member_decorations.keys(), s.member_decorations.values()) |key, list| {
                        if (key != index) continue;
                        for (list.items) |inst| {
                            if (inst.items[0] == @intFromEnum(Decoration.Offset)) {
                                member_offset = inst.items[1];
                                break;
                            }
                        }
                    }
                    const mo: u32 = member_offset orelse return null;
                    offset +%= mo;
                    current = s.elements.items[index];
                },
                .array => |a| {
                    const stride: u32 = decorationOperand(current, @intFromEnum(Decoration.ArrayStride)) orelse return null;
                    offset +%= stride *% index;
                    current = a.element;
                },
                .runtime_array => |a| {
                    const stride: u32 = decorationOperand(current, @intFromEnum(Decoration.ArrayStride)) orelse return null;
                    offset +%= stride *% index;
                    current = a.element;
                },
                .matrix => |a| {
                    const stride: u32 = decorationOperand(current, @intFromEnum(Decoration.MatrixStride)) orelse return null;
                    offset +%= stride *% index;
                    current = a.element;
                },
                .vector => |a| {
                    const comp: *const Type = a.element;
                    var component_size: u32 = 0;
                    if (comp.data == .integer) {
                        component_size = comp.data.integer.width / 8;
                    } else if (comp.data == .float) {
                        component_size = comp.data.float.width / 8;
                    } else {
                        return null;
                    }
                    offset +%= component_size *% index;
                    current = comp;
                },
                else => return null,
            }
        }
        return offset;
    }
};

/// The first operand word of the first decoration of `t` whose decoration kind is `which`.
fn decorationOperand(t: *const Type, which: u32) ?u32 {
    for (t.decorations.items) |d| {
        if (d.items[0] == which) return d.items[1];
    }
    return null;
}

/// Replaces the pointee/element/member/return/parameter types of an incomplete type that equal `from` with `to`
/// (the body shared by TypeManager::ReplaceType and ReplaceForwardPointers).
fn typeSubstituteChildren(t: *Type, from: *const Type, to: *const Type) void {
    switch (t.data) {
        .array => |*a| {
            if (a.element == from) a.element = to;
        },
        .runtime_array => |*a| {
            if (a.element == from) a.element = to;
        },
        .struct_ => |*a| {
            for (a.elements.items) |*m| {
                if (m.* == from) m.* = to;
            }
        },
        .pointer => |*a| {
            if (a.pointee != null and a.pointee.? == from) a.pointee = to;
        },
        .function => |*a| {
            if (a.ret == from) a.ret = to;
            for (a.params.items) |*p| {
                if (p.* == from) p.* = to;
            }
        },
        else => {},
    }
}

// TypeMgr: the types of the module, found by id or by structure (port of source/opt/type_manager.h, type_manager.cpp)
//
// Everything lives in the scratch arena and is rebuilt after the manager is dropped (see Ctx.getTypeMgr).
// Deliberate divergence: TypeManager::RemoveId picks the replacement id for a non-unique type by scanning the
// id->type map in libstdc++ hash order; here the scan is in registration order (deterministic).

// libstdc++ caches the hash code of every node of std::unordered_map/set when the hash functor is not noexcept
// (HashTypePointer is not) and reuses the cached code on rehash and on lookup comparison. A type whose hash changes
// after insertion (a decoration attached to a pointee later in AnalyzeTypes) therefore keeps a stale entry that is
// no longer found by GetId. The keys below capture the hash at insertion time to reproduce exactly that.
const TypeKey = struct { hash: u64, ty: *const Type };

/// The key of a type: its hash at this moment, and the type.
fn typeKeyOf(t: *const Type) TypeKey {
    return .{ .hash = t.hashValue(), .ty = t };
}

/// Hash and equality of TypeKey: the stored hash, then structural equality (Type.isSame).
const TypeHashCtx = struct {
    pub fn hash(_: TypeHashCtx, k: TypeKey) u64 {
        return k.hash;
    }
    pub fn eql(_: TypeHashCtx, a: TypeKey, b: TypeKey) bool {
        return a.hash == b.hash and a.ty.isSame(b.ty);
    }
};
/// type -> id of the instruction that defines it.
const TypeToIdMap = std.HashMapUnmanaged(TypeKey, u32, TypeHashCtx, 80);
/// The types registered so far, by structure: one representative per distinct type.
const TypePoolMap = std.HashMapUnmanaged(TypeKey, void, TypeHashCtx, 80);

/// A type that still refers to a pointer type declared later (through OpTypeForwardPointer), with its id. It is completed
/// once all the types have been seen.
const UnresolvedType = struct { id: u32, type: ?*Type };

/// A type and a pointer to it; both are null when the id is not a type.
pub const TypeAndPointer = struct { ty: ?*Type, ptr: ?*Type };

/// The pointer type declared by a forward pointer once it is known; null for any other type.
fn forwardPointerTarget(t: *const Type) ?*const Type {
    if (t.data != .forward_pointer) return null;
    return t.data.forward_pointer.pointer;
}

// Constant and ConstMgr: the constants of the module as values, found by id or by value (port of source/opt/constants.h,
// constants.cpp)
//
// Constants are interned (one object per distinct (type pointer, value)), so a `*const Constant` can be compared
// by pointer. They live in the scratch arena with the manager; never keep one across a pass boundary.
// C++ overloads that differ only in their argument kinds get distinct names:
//   FindDeclaredConstant(id) -> findDeclaredConstant,   FindDeclaredConstant(c, type_id) -> findDeclaredConstantId.
// `Module::inst_iterator* pos` parameters become `before: ?*Inst` (insert before it; null = end of types_values).

pub const ConstKind = enum { null_, bool_, int, float, struct_, vector, matrix, array, tensor };

fn signExtendValue(value: u64, bits: u32) u64 {
    if (bits == 64) return value;
    const neg: bool = ((value >> @intCast(bits - 1)) & 1) != 0;
    const high: u64 = ~@as(u64, 0) << @intCast(bits);
    return if (neg) (value | high) else (value & ~high);
}

fn zeroExtendValue(value: u64, bits: u32) u64 {
    if (bits == 64) return value;
    const high: u64 = ~@as(u64, 0) << @intCast(bits);
    return value & ~high;
}

// InstBuilder: creates instructions and inserts them into blocks (port of the InstructionBuilder class of
// source/opt/ir_builder.h).
//
// Like the C++ builder it never invalidates analyses. It updates the def-use manager of the new
// instruction only when the caller says def-use is preserved (`preserved & Analysis.def_use`) and it is valid.
// Block membership (`inst.block`) is maintained by the intrusive instruction list, so the instr-to-block
// mapping is always up to date.  Every `Add*` returns null when the id bound is exhausted.

pub const invalid_id: u32 = std.math.maxInt(u32);

pub const SwitchTarget = struct { literal: []const u32, label: u32 };

// StructuredCFGAnalysis (struct_cfg_analysis.*)
// For each reachable block: the innermost containing merge construct, loop and switch, and whether it is in the
// continue construct of that loop. Built lazily by Ctx.getStructuredCfgAnalysis; scratch lifetime.

pub const ConstructInfo = struct {
    containing_construct: u32 = 0,
    containing_loop: u32 = 0,
    containing_switch: u32 = 0,
    in_continue: bool = false,
};

// StdUSet32: iteration-order emulation of libstdc++'s std::unordered_set<uint32_t>
//
// A few passes iterate a std::unordered_set<uint32_t> and the order they visit the ids in changes the output (it
// decides which instruction takes which fresh id). The order of libstdc++'s hashtable is deterministic: this
// container reproduces it exactly (identity hash, prime bucket counts from `__prime_list`, new nodes go to the
// front of the node list when their bucket is empty and in front of the first node of their bucket otherwise,
// rehash re-inserts the nodes in the old order with the same rule).

