    2557710269, 2767159799, 2993761039, 3238918481, 3504151727, 3791104843, 4101556399,
};

fn stdhashNextBkt(n: u64, next_resize: *u64) u64 {
    const fast_bkt = [_]u8{ 2, 2, 2, 3, 5, 5, 7, 7, 11, 11, 11, 11, 13, 13 };
    if (n < fast_bkt.len) {
        if (n == 0) return 1;
        next_resize.* = fast_bkt[@intCast(n)];
        return fast_bkt[@intCast(n)];
    }
    var lo: usize = 0;
    var hi: usize = stdhash_primes.len;
    while (lo < hi) {
        const mid: usize = lo + (hi - lo) / 2;
        if (stdhash_primes[mid] < n) lo = mid + 1 else hi = mid;
    }
    if (lo >= stdhash_primes.len) fatal("StdUSet32: bucket count beyond the emulated prime list", .{});
    next_resize.* = stdhash_primes[lo];
    return stdhash_primes[lo];
}

pub const StdUSet32 = struct {
    /// keys in libstdc++ iteration order
    order: List(u32) = .{},
    members: Set(u32) = .{},
    bucket_count: u64 = 1,
    next_resize: u64 = 0,

    fn place(order: *List(u32), bucket_count: u64, k: u32) void {
        const b = @as(u64, k) % bucket_count;
        var at: usize = 0;
        for (order.items, 0..) |x, i| {
            if (@as(u64, x) % bucket_count == b) {
                at = i;
                break;
            }
        }
        order.insert(at, k);
    }

    fn rehash(self: *StdUSet32, new_count: u64) void {
        var old: List(u32) = self.order;
        self.order = .{};
        self.bucket_count = new_count;
        for (old.items) |k| place(&self.order, new_count, k);
        old.clear();
    }

    /// std::unordered_set::insert; true when the key was new.
    pub fn insert(self: *StdUSet32, k: u32) bool {
        if (self.members.contains(k)) return false;
        const n_elt: u64 = self.order.len();
        if (n_elt + 1 > self.next_resize) {
            const min_bkts: u64 = @max(n_elt + 1, if (self.next_resize != 0) @as(u64, 0) else 11);
            if (min_bkts >= self.bucket_count) {
                const want: u64 = @max(min_bkts + 1, self.bucket_count * 2);
                self.rehash(stdhashNextBkt(want, &self.next_resize));
            } else {
                self.next_resize = self.bucket_count;
            }
        }
        place(&self.order, self.bucket_count, k);
        _ = self.members.insert(k);
        return true;
    }

    pub fn contains(self: *const StdUSet32, k: u32) bool {
        return self.members.contains(k);
    }

    /// std::unordered_set::erase(key): unlinks the node; the bucket count and the rehash threshold never shrink.
    pub fn erase(self: *StdUSet32, k: u32) bool {
        if (!self.members.contains(k)) return false;
        const at: usize = self.order.indexOf(k) orelse fatal("StdUSet32.erase: internal inconsistency", .{});
        _ = self.order.orderedRemove(at);
        _ = self.members.remove(k);
        return true;
    }

    /// std::unordered_set::clear(): drops the nodes, keeps the bucket count and the rehash threshold.
    pub fn clear(self: *StdUSet32) void {
        self.order = .{};
        self.members = .{};
    }

    /// Copy construction/assignment: same node order, same bucket count (libstdc++ _M_assign keeps both).
    pub fn copy(self: *const StdUSet32) StdUSet32 {
        var c: StdUSet32 = .{ .bucket_count = self.bucket_count, .next_resize = self.next_resize };
        c.order.pushSlice(self.order.items);
        for (self.order.items) |k| _ = c.members.insert(k);
        return c;
    }

    pub fn count(self: *const StdUSet32) usize {
        return self.order.len();
    }

    /// the keys in iteration order
    pub fn items(self: *const StdUSet32) []const u32 {
        return self.order.items;
    }
};

const kTypeImageDimIndex = 1;
const kTypeImageSampledIndex = 5;

fn firstNonPhi(block: *Block) ?*Inst {
    var it: ?*Inst = block.insts.first;
    while (it) |i| : (it = i.next) {
        if (i.op != .OpPhi) return i;
    }
    return null;
}

const LatchRedirect = struct { old_id: u32, new_id: u32 };

fn latchRedirectCb(c: LatchRedirect, id: *u32) void {
    if (id.* == c.old_id) id.* = c.new_id;
}

/// Pass::Status of the C++ code.
pub const PassStatus = enum { failure, success_with_change, success_without_change };

// ScalarEvolutionAnalysis: describes the integer values of a loop as expressions of the iteration count (constants,
// sums, products and recurrences such as `{0,+,4}`), which the loop passes use to compare accesses and count iterations.
// Port of source/opt/scalar_analysis.{h,cpp}, scalar_analysis_nodes.h and scalar_analysis_simplification.cpp.
//
// SENode DAG with a structural cache (a node is identified by its kind, literal value, result id, loop, coefficient/offset
// and child pointers, exactly like SENodeHash/operator==). Children of every node are kept sorted by decreasing unique id
// (SENode::AddChild), so node objects must be created at the same moments as in the C++ (the unique ids order the children).
//
// C++ `SExpression` (a node that simplifies itself on construction, with overloaded operators) becomes the `sx*` helpers
// of ScalarEvolutionAnalysis: sx(n) is `SExpression(n)`, sxAdd/sxSub/sxMul/sxMulInt/sxNeg/sxDiv are the operators.
//
// Ordering notes (std::map keyed by pointers in the C++): `accumulators_` iterates by SENode* (heap address order) and
// `loops_to_recurrent` by Loop*; here they iterate by unique id / by address of the (scratch-arena) Loop. Both orders only
// decide the creation order of freshly built terms, which is not observable except through FoldRecurrentAddExpressions'
// early return when several loops each fold to a zero coefficient (an upstream quirk of the C++ as well).
// int64 arithmetic wraps (the C++ relies on it).

/// The kinds of node of a scalar expression. `cant_compute` stands for any value the analysis cannot express.
pub const SENodeKind = enum { constant, recurrent_add_expr, add, multiply, negative, value_unknown, cant_compute };

// ---- signedness lattice of IsGreaterThanZero ------------------------------------------------------------------------

/// What is known about the sign of an expression, from `positive_or_negative` (nothing) to `strictly_positive`.
const SeSign = enum { positive_or_negative, strictly_negative, negative, strictly_positive, positive };

/// The sign of a sum of two expressions of the given signs.
fn seAddCombine(lhs: SeSign, rhs: SeSign) SeSign {
    switch (lhs) {
        .positive_or_negative => {},
        .strictly_negative => {
            if (rhs == .strictly_negative or rhs == .negative) return lhs;
        },
        .negative => {
            if (rhs == .strictly_negative) return .strictly_negative;
            if (rhs == .negative) return .negative;
        },
        .strictly_positive => {
            if (rhs == .strictly_positive or rhs == .positive) return .strictly_positive;
        },
        .positive => {
            if (rhs == .strictly_positive) return .strictly_positive;
            if (rhs == .positive) return .positive;
        },
    }
    return .positive_or_negative;
}

/// The sign of a product of two expressions of the given signs.
fn seMulCombine(lhs: SeSign, rhs: SeSign) SeSign {
    switch (lhs) {
        .positive_or_negative => {},
        .strictly_negative => switch (rhs) {
            .positive_or_negative => {},
            .strictly_negative => return .strictly_positive,
            .negative => return .positive,
            .strictly_positive => return .strictly_negative,
            .positive => return .negative,
        },
        .negative => switch (rhs) {
            .positive_or_negative => {},
            .strictly_negative, .negative => return .positive,
            .strictly_positive, .positive => return .negative,
        },
        .strictly_positive => return rhs,
        .positive => switch (rhs) {
            .positive_or_negative => {},
            .strictly_negative, .negative => return .negative,
            .strictly_positive, .positive => return .positive,
        },
    }
    return .positive_or_negative;
}

/// Number of nodes created so far in the process; it numbers the nodes (SENode::NumberOfNodes).
var se_number_of_nodes: u32 = 0; // SENode::NumberOfNodes (static, process wide)

// Register pressure analysis. Port of source/opt/register_pressure.{h,cpp} (IRContext::GetLivenessAnalysis, i.e.
// Analysis.register_pressure; not the interface-variable LivenessManager).
//
// Per function: the live-in / live-out sets of every basic block (Boissinot et al., ignoring back edges, then the loop forest
// propagates the loop-carried values) and the maximal number of simultaneously live SSA registers per block (`used_registers`).
// LoopFissionPass and LoopFusionPass only look at `used_registers`, so the per register class break-down of the C++
// (RegisterClass / registers_classes_ / AddRegisterClass: a vector of (type, uniform) counters filled in unordered_set order that
// no pass reads) and the library-only SimulateFission are not ported. The unordered_set<Instruction*> live sets are plain Sets:
// only membership and sizes are ever observed.

pub const RegionRegisterLiveness = struct {
    /// SSA register live when entering the basic block.
    live_in: Set(*Inst) = .{},
    /// SSA register live when exiting the basic block.
    live_out: Set(*Inst) = .{},
    /// Maximum number of required registers.
    used_registers: usize = 0,

    pub fn clear(self: *RegionRegisterLiveness) void {
        self.live_out.clear();
        self.live_in.clear();
        self.used_registers = 0;
    }
};

fn rpCopySet(src: *const Set(*Inst)) Set(*Inst) {
    var dst: Set(*Inst) = .{};
    var it: Map(*Inst, void).Hm.Iterator = src.iterator();
    while (it.next()) |e| _ = dst.insert(e.key_ptr.*);
    return dst;
}

/// Returns true if |insn| generates a SSA register that is likely to require a physical register.
fn rpCreatesRegisterUsage(insn: *const Inst) bool {
    if (!insn.has_result) return false;
    if (insn.op == .OpUndef) return false;
    if (opIsConstant(insn.op)) return false;
    if (insn.op == .OpLabel) return false;
    return true;
}

fn rpUnionInto(dst: *Set(*Inst), src: *const Set(*Inst)) void {
    var it: Map(*Inst, void).Hm.Iterator = src.iterator();
    while (it.next()) |e| _ = dst.insert(e.key_ptr.*);
}

// LivenessMgr (analysis::LivenessManager, source/opt/liveness.{h,cpp}), AnalyzeLiveInputPass
// (analyze_live_input_pass.{h,cpp}) and EliminateDeadOutputStoresPass (eliminate_dead_output_stores_pass.{h,cpp}).
//
// The two passes are reachable only through the C++ library API (CreateAnalyzeLiveInputPass /
// CreateEliminateDeadOutputStoresPass take the std::unordered_set<uint32_t>* live-location / live-builtin sets of the
// consumer stage): `--eliminate-dead-output-stores=<consumer.spv>` of the driver runs AnalyzeLiveInput on the consumer
// module and then EliminateDeadOutputStores on the input module (an addition to spirv-opt's flags).
// Release-build (NDEBUG) behaviour: the C++ asserts are no-ops; null dereferences are fatal here.

const builtin_max: u32 = 0x7fffffff; // spv::BuiltIn::Max

/// The caller owned std::unordered_set<uint32_t> pair of the library API. IR lifetime (survives scratch resets).
pub const LiveIoSets = struct {
    locs: std.AutoHashMapUnmanaged(u32, void) = .empty,
    builtins: std.AutoHashMapUnmanaged(u32, void) = .empty,

    fn containsLoc(self: *const LiveIoSets, loc: u32) bool {
        return self.locs.contains(loc);
    }

    fn containsBuiltin(self: *const LiveIoSets, bi: u32) bool {
        return self.builtins.contains(bi);
    }
};

/// The IRContext: owns the module, builds each analysis lazily on first use and drops them all (with the scratch
/// arena) after every pass. Also the home of the operations that must keep several analyses consistent:
/// replaceAllUsesWith, killInst, ...
pub const Ctx = struct {
    module: *Module,
    valid: u32 = Analysis.instr_to_block, // bits of analyses currently valid
    preserve_bindings: bool = false,
    preserve_spec_constants: bool = false,
    pseudo_entry: ?*Block = null, // IR arena, created once, shared by every Cfg
    pseudo_exit: ?*Block = null,

    // ---- analyses: scratch lifetime, reset by invalidateAnalyses ----
    def_use: ?*DefUseMgr = null,
    decor: ?*DecorMgr = null,
    feature: ?*FeatureMgr = null, // FeatureManager is not an Analysis flag in C++; dropped at pass boundaries too
    cfg_: ?*Cfg = null,
    dom_trees: Map(*Func, *DominatorAnalysis) = .{},
    post_dom_trees: Map(*Func, *DominatorAnalysis) = .{},
    name_map: ?*NameMap = null,
    id_to_func: Map(u32, *Func) = .{},
    builtin_var_ids: Map(u32, u32) = .{},
    type_mgr: ?*TypeMgr = null,
    const_mgr: ?*ConstMgr = null,
    struct_cfg: ?*StructCfg = null,
    loop_descs: Map(*Func, *LoopDescriptor) = .{}, // IRContext::loop_descriptors_
    scev: ?*ScalarEvolutionAnalysis = null, // IRContext::scalar_evolution_analysis_
    reg_pressure: ?*LivenessAnalysis = null, // IRContext::reg_pressure_ (Analysis.register_pressure)
    liveness_mgr: ?*LivenessMgr = null, // IRContext::liveness_mgr_ (Analysis.liveness)
    combinator_shader: bool = false, // combinator_ops_[0] is the Shader opcode list
    combinator_glsl: Set(u32) = .{}, // result ids of GLSL.std.450 imports (combinator_ops_[id] is the GLSL list)
    // InstructionFolder state: the C++ builds its rule tables once, capturing the GLSL.std.450 import id at that time
    // (a GLSL import added to the module later is never matched). IR lifetime: the folder is never dropped.
    folder_built: bool = false,
    folder_glsl_id: u32 = 0,
    // InterpFixupPass builds its own InstructionFolder (no const-folding rules, only the InterpolateAt* rule): set while it runs.
    fold_interp: bool = false,
    // AmdExtensionToKhrPass likewise builds its own folder (empty constant rules + the AMD rules keyed on the three
    // AMD OpExtInstImport ids that existed when it was built: ballot, trinary_minmax, gcn_shader).
    fold_amd: bool = false,
    amd_ext_ids: [3]u32 = .{ 0, 0, 0 },

    pub fn init(m: *Module) *Ctx {
        const c = irAllocator().create(Ctx) catch oom();
        c.* = .{ .module = m };
        g_ctx = c;
        return c;
    }

    // ---- validity bookkeeping --------------------------------------------------------------------

    pub fn areAnalysesValid(self: *const Ctx, set: u32) bool {
        return (set & self.valid) == set;
    }

    pub fn invalidateAnalysesExceptFor(self: *Ctx, preserved: u32) void {
        self.invalidateAnalyses(self.valid & ~preserved);
    }

    pub fn invalidateAnalyses(self: *Ctx, set_in: u32) void {
        var set: u32 = set_in;
        if (set & Analysis.types != 0) {
            set |= Analysis.constants;
            set |= Analysis.debug_info;
        }
        if (set & Analysis.cfg != 0) {
            set |= Analysis.dominator;
            set |= Analysis.structured_cfg;
        }
        if (set & Analysis.loops != 0) {
            set |= Analysis.scalar_evolution;
            set |= Analysis.liveness;
        }
        if (set & Analysis.def_use != 0) self.def_use = null;
        // instr_to_block: nothing to clear (Inst.block is intrinsic) and the bit stays valid, see below
        if (set & Analysis.decorations != 0) self.decor = null;
        if (set & Analysis.combinators != 0) {
            self.combinator_shader = false;
            self.combinator_glsl = .{};
        }
        if (set & Analysis.builtin_var_id != 0) self.builtin_var_ids = .{};
        if (set & Analysis.cfg != 0) self.cfg_ = null;
        if (set & Analysis.dominator != 0) {
            self.dom_trees = .{};
            self.post_dom_trees = .{};
        }
        if (set & Analysis.name_map != 0) self.name_map = null;
        if (set & Analysis.id_to_func != 0) self.id_to_func = .{};
        if (set & Analysis.constants != 0) self.const_mgr = null;
        if (set & Analysis.types != 0) self.type_mgr = null;
        if (set & Analysis.structured_cfg != 0) self.struct_cfg = null;
        if (set & Analysis.liveness != 0) self.liveness_mgr = null;
        // (the value number table is built and owned by the redundancy-elimination pass, Ctx holds no state for it)
        if (set & Analysis.loops != 0) self.loop_descs = .{};
        if (set & Analysis.scalar_evolution != 0) self.scev = null;
        if (set & Analysis.register_pressure != 0) self.reg_pressure = null;
        self.valid &= ~set;
        self.valid |= Analysis.instr_to_block;
    }

    /// Pass boundary: forget everything (scratch memory is reset right after this).
    pub fn dropAllAnalyses(self: *Ctx) void {
        self.invalidateAnalyses(Analysis.all_but_end);
        self.feature = null;
        // `folder_built` / `folder_glsl_id` are deliberately kept: the folder captures the GLSL import once per process
    }

    pub fn buildInvalidAnalyses(self: *Ctx, set_in: u32) void {
        const set: u32 = set_in & ~self.valid;
        if (set & Analysis.def_use != 0) _ = self.getDefUseMgr();
        if (set & Analysis.decorations != 0) _ = self.getDecorationMgr();
        if (set & Analysis.cfg != 0) _ = self.cfg();
        if (set & Analysis.dominator != 0) self.resetDominatorAnalysis();
        if (set & Analysis.builtin_var_id != 0) self.resetBuiltinAnalysis();
        if (set & Analysis.name_map != 0) self.buildIdToNameMap();
        if (set & Analysis.id_to_func != 0) self.buildIdToFuncMapping();
        if (set & Analysis.constants != 0) _ = self.getConstantMgr();
        if (set & Analysis.types != 0) _ = self.getTypeMgr();
        if (set & Analysis.structured_cfg != 0) _ = self.getStructuredCfgAnalysis();
        if (set & Analysis.loops != 0) self.resetLoopAnalysis();
        if (set & Analysis.scalar_evolution != 0) _ = self.getScalarEvolutionAnalysis();
        if (set & Analysis.register_pressure != 0) _ = self.getRegPressureAnalysis();
        if (set & Analysis.liveness != 0) _ = self.getLivenessMgr();
        const later: u32 = Analysis.value_number_table | Analysis.id_to_graph;
        if (set & later != 0) fatal("buildInvalidAnalyses: analysis set 0x{x} is not ported yet", .{set & later});
    }

    // ---- ids -----------------------------------------------------------------------------------

    pub fn takeNextId(self: *Ctx) u32 {
        return self.module.takeNextId();
    }

    pub fn idBound(self: *const Ctx) u32 {
        return self.module.idBound();
    }

    // ---- lazily built analyses -------------------------------------------------------------------

    pub fn getDefUseMgr(self: *Ctx) *DefUseMgr {
        if (!self.areAnalysesValid(Analysis.def_use)) {
            self.def_use = DefUseMgr.init(self.module);
            self.valid |= Analysis.def_use;
        }
        return self.def_use.?;
    }

    pub fn getDecorationMgr(self: *Ctx) *DecorMgr {
        if (!self.areAnalysesValid(Analysis.decorations)) {
            self.decor = DecorMgr.init(self);
            self.valid |= Analysis.decorations;
        }
        return self.decor.?;
    }

    pub fn getFeatureMgr(self: *Ctx) *FeatureMgr {
        if (self.feature == null) self.feature = FeatureMgr.init(self.module);
        return self.feature.?;
    }

    pub fn resetFeatureManager(self: *Ctx) void {
        self.feature = null;
    }

    pub fn getTypeMgr(self: *Ctx) *TypeMgr {
        if (!self.areAnalysesValid(Analysis.types)) {
            self.type_mgr = TypeMgr.init(self);
            self.valid |= Analysis.types;
        }
        return self.type_mgr.?;
    }

    pub fn getConstantMgr(self: *Ctx) *ConstMgr {
        if (!self.areAnalysesValid(Analysis.constants)) {
            self.const_mgr = ConstMgr.init(self);
            self.valid |= Analysis.constants;
        }
        return self.const_mgr.?;
    }

    pub fn cfg(self: *Ctx) *Cfg {
        if (!self.areAnalysesValid(Analysis.cfg)) {
            self.cfg_ = Cfg.init(self);
            self.valid |= Analysis.cfg;
        }
        return self.cfg_.?;
    }

    pub fn getStructuredCfgAnalysis(self: *Ctx) *StructCfg {
        if (!self.areAnalysesValid(Analysis.structured_cfg)) {
            self.struct_cfg = StructCfg.init(self);
            self.valid |= Analysis.structured_cfg;
        }
        return self.struct_cfg.?;
    }

    pub fn pseudoEntryBlock(self: *Ctx) *Block {
        if (self.pseudo_entry) |b| return b;
        const b: *Block = Block.new(Inst.make(.OpLabel, 0, 0, &.{}));
        self.pseudo_entry = b;
        return b;
    }

    pub fn pseudoExitBlock(self: *Ctx) *Block {
        if (self.pseudo_exit) |b| return b;
        const b: *Block = Block.new(Inst.make(.OpLabel, 0, max_result_id, &.{}));
        self.pseudo_exit = b;
        return b;
    }

    fn resetDominatorAnalysis(self: *Ctx) void {
        self.dom_trees = .{};
        self.post_dom_trees = .{};
        self.valid |= Analysis.dominator;
    }

    pub fn getDominatorAnalysis(self: *Ctx, f: *Func) *DominatorAnalysis {
        if (!self.areAnalysesValid(Analysis.dominator)) self.resetDominatorAnalysis();
        if (self.dom_trees.get(f)) |d| return d;
        const d = scAllocator().create(DominatorAnalysis) catch oom();
        d.* = DominatorAnalysis.init(false);
        self.dom_trees.put(f, d);
        d.initializeTree(self, self.cfg(), f);
        return d;
    }

    /// IRContext::ResetLoopAnalysis
    pub fn resetLoopAnalysis(self: *Ctx) void {
        self.loop_descs = .{};
        self.valid |= Analysis.loops;
    }

    /// IRContext::GetLoopDescriptor: the (cached) loop descriptor of `f`.
    pub fn getLoopDescriptor(self: *Ctx, f: *Func) *LoopDescriptor {
        if (!self.areAnalysesValid(Analysis.loops)) self.resetLoopAnalysis();
        if (self.loop_descs.get(f)) |d| return d;
        const d: *LoopDescriptor = LoopDescriptor.create(self, f);
        self.loop_descs.put(f, d);
        return d;
    }

    /// IRContext::GetScalarEvolutionAnalysis: the (cached) scalar evolution analysis of the module.
    pub fn getScalarEvolutionAnalysis(self: *Ctx) *ScalarEvolutionAnalysis {
        if (!self.areAnalysesValid(Analysis.scalar_evolution)) {
            self.scev = ScalarEvolutionAnalysis.create(self);
            self.valid |= Analysis.scalar_evolution;
        }
        return self.scev.?;
    }

    /// IRContext::get_liveness_mgr: the (cached) input/output location liveness manager.
    pub fn getLivenessMgr(self: *Ctx) *LivenessMgr {
        if (!self.areAnalysesValid(Analysis.liveness)) {
            self.liveness_mgr = LivenessMgr.init(self);
            self.valid |= Analysis.liveness;
        }
        return self.liveness_mgr.?;
    }

    /// IRContext::GetLivenessAnalysis: the (cached) register pressure analysis of the module.
    pub fn getRegPressureAnalysis(self: *Ctx) *LivenessAnalysis {
        if (!self.areAnalysesValid(Analysis.register_pressure)) {
            const la = scAllocator().create(LivenessAnalysis) catch oom();
            la.* = .{ .ctx = self };
            self.reg_pressure = la;
            self.valid |= Analysis.register_pressure;
        }
        return self.reg_pressure.?;
    }

    pub fn getPostDominatorAnalysis(self: *Ctx, f: *Func) *PostDominatorAnalysis {
        if (!self.areAnalysesValid(Analysis.dominator)) self.resetDominatorAnalysis();
        if (self.post_dom_trees.get(f)) |d| return d;
        const d: *DominatorAnalysis = scAllocator().create(PostDominatorAnalysis) catch oom();
        d.* = PostDominatorAnalysis.init(true);
        self.post_dom_trees.put(f, d);
        d.initializeTree(self, self.cfg(), f);
        return d;
    }

    pub fn removeDominatorAnalysis(self: *Ctx, f: *Func) void {
        _ = self.dom_trees.remove(f);
    }

    pub fn removePostDominatorAnalysis(self: *Ctx, f: *Func) void {
        _ = self.post_dom_trees.remove(f);
    }

    fn resetBuiltinAnalysis(self: *Ctx) void {
        self.builtin_var_ids = .{};
        self.valid |= Analysis.builtin_var_id;
    }

    /// IRContext::FindBuiltinInputVar: the id of an Input variable decorated with BuiltIn `builtin`, or 0.
    fn findBuiltinInputVar(self: *Ctx, builtin: u32) u32 {
        var it: ?*Inst = self.module.annotations.first;
        while (it) |a| : (it = a.next) {
            if (a.op != .OpDecorate) continue;
            if (a.getSingleWordInOperand(1) != @intFromEnum(Decoration.BuiltIn)) continue;
            if (a.getSingleWordInOperand(2) != builtin) continue;
            const target_id: u32 = a.getSingleWordInOperand(0);
            const b_var: *Inst = self.getDefUseMgr().getDef(target_id) orelse fatal("findBuiltinInputVar: %{d} is not defined", .{target_id});
            if (b_var.op != .OpVariable) continue;
            if (b_var.getSingleWordInOperand(0) != @intFromEnum(StorageClass.Input)) continue;
            return target_id;
        }
        return 0;
    }

    /// IRContext::AddVarToEntryPoints. The operand counter is shared by all entry points, exactly like the C++.
    fn addVarToEntryPoints(self: *Ctx, var_id: u32) void {
        var ocnt: u32 = 0;
        var it: ?*Inst = self.module.entry_points.first;
        while (it) |e| : (it = e.next) {
            var found: bool = false;
            var k: usize = e.typeResultIdCount();
            while (k < e.ops.items.len) : (k += 1) {
                if (ocnt >= 3) { // kEntryPointInterfaceInIdx
                    if (e.ops.items[k].words()[0] == var_id) found = true;
                }
                ocnt += 1;
            }
            if (!found) {
                e.addOperand(Operand.id(.IdRef, var_id));
                self.getDefUseMgr().analyzeInstDefUse(e);
            }
        }
    }

    /// IRContext::GetBuiltinInputVarId: the Input variable for a BuiltIn, created (and added to every entry point
    /// interface) when the module has none. 0 on failure.
    pub fn getBuiltinInputVarId(self: *Ctx, builtin: u32) u32 {
        if (!self.areAnalysesValid(Analysis.builtin_var_id)) self.resetBuiltinAnalysis();
        if (self.builtin_var_ids.get(builtin)) |v| return v;
        var var_id: u32 = self.findBuiltinInputVar(builtin);
        if (var_id == 0) {
            const tm: *TypeMgr = self.getTypeMgr();
            var reg_type: ?*Type = null;
            const B = BuiltIn;
            if (builtin == @intFromEnum(B.FragCoord)) {
                const f = Type.float(32, fp_encoding_max);
                const reg_float: *Type = tm.getRegisteredType(&f).?;
                const v4 = Type.vector(reg_float, 4);
                reg_type = tm.getRegisteredType(&v4);
            } else if (builtin == @intFromEnum(B.VertexIndex) or builtin == @intFromEnum(B.InstanceIndex) or builtin == @intFromEnum(B.PrimitiveId) or
                builtin == @intFromEnum(B.InvocationId) or builtin == @intFromEnum(B.SubgroupLocalInvocationId))
            {
                const u = Type.integer(32, false);
                reg_type = tm.getRegisteredType(&u);
            } else if (builtin == @intFromEnum(B.GlobalInvocationId) or builtin == @intFromEnum(B.LaunchIdNV)) {
                const u = Type.integer(32, false);
                const reg_uint: *Type = tm.getRegisteredType(&u).?;
                const v3 = Type.vector(reg_uint, 3);
                reg_type = tm.getRegisteredType(&v3);
            } else if (builtin == @intFromEnum(B.TessCoord)) {
                const f = Type.float(32, fp_encoding_max);
                const reg_float: *Type = tm.getRegisteredType(&f).?;
                const v3 = Type.vector(reg_float, 3);
                reg_type = tm.getRegisteredType(&v3);
            } else if (builtin == @intFromEnum(B.SubgroupLtMask)) {
                const u = Type.integer(32, false);
                const reg_uint: *Type = tm.getRegisteredType(&u).?;
                const v4 = Type.vector(reg_uint, 4);
                reg_type = tm.getRegisteredType(&v4);
            } else {
                fatal("getBuiltinInputVarId: unhandled builtin {d}", .{builtin});
            }
            const rt: *Type = reg_type orelse return 0;
            const type_id: u32 = tm.getTypeInstruction(rt);
            const var_ty_ptr_id: u32 = tm.findPointerToType(type_id, @intFromEnum(StorageClass.Input));
            var_id = self.takeNextId();
            if (var_id == 0) return 0;
            const new_var: *Inst = Inst.make(.OpVariable, var_ty_ptr_id, var_id, &.{Operand.single(.StorageClass, @intFromEnum(StorageClass.Input))});
            self.getDefUseMgr().analyzeInstDefUse(new_var);
            self.module.addGlobalValue(new_var);
            self.getDecorationMgr().addDecorationVal(var_id, @intFromEnum(Decoration.BuiltIn), builtin);
            self.addVarToEntryPoints(var_id);
        }
        self.builtin_var_ids.put(builtin, var_id);
        return var_id;
    }

    fn buildIdToFuncMapping(self: *Ctx) void {
        self.id_to_func = .{};
        for (self.module.functions.items) |fun| self.id_to_func.put(fun.id(), fun);
        self.valid |= Analysis.id_to_func;
    }

    pub fn getFunction(self: *Ctx, id: u32) ?*Func {
        if (!self.areAnalysesValid(Analysis.id_to_func)) self.buildIdToFuncMapping();
        return self.id_to_func.get(id);
    }

    pub fn getFunctionOfInst(self: *Ctx, inst: *const Inst) ?*Func {
        if (inst.op != .OpFunction) return null;
        return self.getFunction(inst.resultId());
    }

    /// get_instr_block(Instruction*): the block that owns `inst` (null for module-level instructions).
    pub fn getInstrBlock(self: *Ctx, inst: *const Inst) ?*Block {
        _ = self;
        return inst.block;
    }

    /// get_instr_block(uint32_t id)
    pub fn getInstrBlockById(self: *Ctx, id: u32) ?*Block {
        const def: *Inst = self.getDefUseMgr().getDef(id) orelse return null;
        return def.block;
    }

    // ---- names -------------------------------------------------------------------------------------

    fn buildIdToNameMap(self: *Ctx) void {
        const nm: *Map(u32, List(*Inst)) = scAllocator().create(NameMap) catch oom();
        nm.* = .{};
        var it: ?*Inst = self.module.debugs2.first;
        while (it) |d| : (it = d.next) {
            if (d.op == .OpMemberName or d.op == .OpName) nameMapInsert(nm, d.getSingleWordInOperand(0), d);
        }
        self.name_map = nm;
        self.valid |= Analysis.name_map;
    }

    fn nameMapInsert(nm: *NameMap, id: u32, inst: *Inst) void {
        const gop: Map(u32, List(*Inst)).GetOrPutResult = nm.getOrPut(id);
        if (!gop.found_existing) gop.value_ptr.* = .{};
        gop.value_ptr.push(inst);
    }

    /// GetNames: the OpName / OpMemberName instructions of `id`, in insertion order (a view).
    pub fn getNames(self: *Ctx, id: u32) []const *Inst {
        if (!self.areAnalysesValid(Analysis.name_map)) self.buildIdToNameMap();
        const l: *List(*Inst) = self.name_map.?.getPtr(id) orelse return &.{};
        return l.items;
    }

    pub fn getMemberName(self: *Ctx, struct_type_id: u32, index: u32) ?*Inst {
        for (self.getNames(struct_type_id)) |n| {
            if (n.op == .OpMemberName and n.getSingleWordInOperand(1) == index) return n;
        }
        return null;
    }

    fn removeFromIdToName(self: *Ctx, inst: *const Inst) void {
        const nm: *Map(u32, List(*Inst)) = self.name_map orelse return;
        if (inst.op != .OpName and inst.op != .OpMemberName) return;
        const l: *List(*Inst) = nm.getPtr(inst.getSingleWordInOperand(0)) orelse return;
        for (l.items, 0..) |x, k| {
            if (x == inst) {
                _ = l.orderedRemove(k);
                break;
            }
        }
    }

    pub fn cloneNames(self: *Ctx, old_id: u32, new_id: u32, max_member_index: u32) void {
        var names_to_add: List(*Inst) = .{};
        for (self.getNames(old_id)) |old_name_inst| {
            if (old_name_inst.op == .OpMemberName) {
                const midx: u32 = old_name_inst.getSingleWordInOperand(1);
                if (midx >= max_member_index) continue;
            }
            const n: *Inst = old_name_inst.clone();
            n.setInOperand(0, &.{new_id});
            names_to_add.push(n);
        }
        for (names_to_add.items) |n| self.addDebug2Inst(n);
    }

    // ---- combinators -------------------------------------------------------------------------------

    fn addCombinatorsForCapability(self: *Ctx, cap: u32) void {
        if (cap == @intFromEnum(Capability.Shader)) self.combinator_shader = true;
    }

    fn addCombinatorsForExtension(self: *Ctx, ext: *Inst) void {
        check(ext.op == .OpExtInstImport, "Expecting an import of an extension's instruction set.");
        if (std.mem.eql(u8, ext.getInOperand(0).asString(), "GLSL.std.450")) _ = self.combinator_glsl.insert(ext.resultId());
    }

    fn initializeCombinators(self: *Ctx) void {
        for (self.getFeatureMgr().capabilities.items()) |cap| self.addCombinatorsForCapability(cap);
        var it: ?*Inst = self.module.ext_inst_imports.first;
        while (it) |e| : (it = e.next) self.addCombinatorsForExtension(e);
        self.valid |= Analysis.combinators;
    }

    pub fn isCombinatorInstruction(self: *Ctx, inst: *const Inst) bool {
        if (!self.areAnalysesValid(Analysis.combinators)) self.initializeCombinators();
        if (inst.op != .OpExtInst) return self.combinator_shader and opIsShaderCombinator(inst.op);
        const set: u32 = inst.getSingleWordInOperand(0);
        const op: u32 = inst.getSingleWordInOperand(1);
        return self.combinator_glsl.contains(set) and glslIsCombinator(op);
    }

    // ---- module additions that keep the analyses current ----------------------------------------------

    fn capabilityInst(cap: u32) *Inst {
        return Inst.make(.OpCapability, 0, 0, &.{Operand.single(.Capability, cap)});
    }

    /// AddCapability(spv::Capability): adds OpCapability unless the feature manager already has it.
    pub fn addCapability(self: *Ctx, cap: Capability) void {
        if (!self.getFeatureMgr().hasCapability(cap)) self.addCapabilityInst(capabilityInst(@intFromEnum(cap)));
    }

    pub fn addCapabilityInst(self: *Ctx, c: *Inst) void {
        self.addCombinatorsForCapability(c.getSingleWordInOperand(0));
        if (self.feature) |fm| fm.addCapability(c.getSingleWordInOperand(0));
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().analyzeInstDefUse(c);
        self.module.addCapability(c);
    }

    pub fn addExtension(self: *Ctx, ext_name: []const u8) void {
        self.addExtensionInst(Inst.make(.OpExtension, 0, 0, &.{Operand.string(ext_name)}));
    }

    pub fn addExtensionInst(self: *Ctx, e: *Inst) void {
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().analyzeInstDefUse(e);
        if (self.feature) |fm| fm.addExtension(e);
        self.module.addExtension(e);
    }

    pub fn addExtInstImport(self: *Ctx, name: []const u8) void {
        const id: u32 = self.takeNextId();
        self.addExtInstImportInst(Inst.make(.OpExtInstImport, 0, id, &.{Operand.string(name)}));
    }

    pub fn addExtInstImportInst(self: *Ctx, e: *Inst) void {
        self.addCombinatorsForExtension(e);
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().analyzeInstDefUse(e);
        self.module.addExtInstImport(e);
        if (self.feature) |fm| fm.addExtInstImportIds(self.module);
    }

    pub fn setMemoryModel(self: *Ctx, m: *Inst) void {
        self.module.setMemoryModel(m);
    }

    pub fn addEntryPoint(self: *Ctx, e: *Inst) void {
        self.module.addEntryPoint(e);
    }

    pub fn addExecutionMode(self: *Ctx, e: *Inst) void {
        self.module.addExecutionMode(e);
    }

    pub fn addDebug1Inst(self: *Ctx, d: *Inst) void {
        self.module.addDebug1Inst(d);
    }

    pub fn addDebug2Inst(self: *Ctx, d: *Inst) void {
        if (self.areAnalysesValid(Analysis.name_map)) {
            if (d.op == .OpName or d.op == .OpMemberName) nameMapInsert(self.name_map.?, d.getSingleWordInOperand(0), d);
        }
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().analyzeInstDefUse(d);
        self.module.addDebug2Inst(d);
    }

    pub fn addDebug3Inst(self: *Ctx, d: *Inst) void {
        self.module.addDebug3Inst(d);
    }

    pub fn addAnnotationInst(self: *Ctx, a: *Inst) void {
        if (self.areAnalysesValid(Analysis.decorations)) self.getDecorationMgr().addDecorationInst(a);
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().analyzeInstDefUse(a);
        self.module.addAnnotationInst(a);
    }

    pub fn addType(self: *Ctx, t: *Inst) void {
        self.module.addType(t);
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().analyzeInstDefUse(t);
    }

    pub fn addGlobalValue(self: *Ctx, v: *Inst) void {
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().analyzeInstDefUse(v);
        self.module.addGlobalValue(v);
    }

    pub fn addFunctionDeclaration(self: *Ctx, f: *Func) void {
        self.module.addFunctionDeclaration(f);
    }

    pub fn addFunction(self: *Ctx, f: *Func) void {
        self.module.addFunction(f);
    }

    pub fn analyzeDefUse(self: *Ctx, inst: *Inst) void {
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().analyzeInstDefUse(inst);
    }

    pub fn updateDefUse(self: *Ctx, inst: *Inst) void {
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().updateDefUse(inst);
    }

    // ---- uses --------------------------------------------------------------------------------------

    pub fn forgetUses(self: *Ctx, inst: *Inst) void {
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().eraseUseRecordsOfOperandIds(inst);
        if (self.areAnalysesValid(Analysis.decorations)) {
            if (inst.isDecoration()) self.getDecorationMgr().removeDecoration(inst);
        }
        self.removeFromIdToName(inst);
    }

    /// `forgetUses` for a caller that changes `inst` and then calls `analyzeUses(inst)` right away: the def-use records are
    /// left in place, because `DefUseMgr.analyzeInstUse` erases the ones that went away and inserts the new ones, which
    /// ends with the same lists as erasing everything first but touches only the lists of the operands that changed.
    pub fn forgetUsesBeforeReanalysis(self: *Ctx, inst: *Inst) void {
        check(self.areAnalysesValid(Analysis.def_use), "forgetUsesBeforeReanalysis: def-use analysis is not valid");
        if (self.areAnalysesValid(Analysis.decorations)) {
            if (inst.isDecoration()) self.getDecorationMgr().removeDecoration(inst);
        }
        self.removeFromIdToName(inst);
    }

    pub fn analyzeUses(self: *Ctx, inst: *Inst) void {
        if (self.areAnalysesValid(Analysis.def_use)) self.getDefUseMgr().analyzeInstUse(inst);
        if (self.areAnalysesValid(Analysis.decorations)) {
            if (inst.isDecoration()) self.getDecorationMgr().addDecorationInst(inst);
        }
        if (self.name_map) |nm| {
            if (inst.op == .OpName or inst.op == .OpMemberName) nameMapInsert(nm, inst.getSingleWordInOperand(0), inst);
        }
    }

    // ---- killing -----------------------------------------------------------------------------------

    pub fn killNamesAndDecoratesId(self: *Ctx, id: u32) void {
        _ = self.getDecorationMgr().removeAllDecorationsFrom(id);
        var name_to_kill: List(*Inst) = .{};
        name_to_kill.pushSlice(self.getNames(id));
        for (name_to_kill.items) |n| _ = self.killInst(n);
    }

    pub fn killNamesAndDecorates(self: *Ctx, inst: *const Inst) void {
        const r: u32 = inst.resultId();
        if (r == 0) return;
        self.killNamesAndDecoratesId(r);
    }

    /// IRContext::KillInst: removes `inst` from the module and from every analysis. Returns the instruction that
    /// followed it in its list (null when it was not in a list). Instructions that are not list members
    /// (OpLabel, OpFunction, OpFunctionParameter, OpFunctionEnd, OpMemoryModel) become OpNop.
    pub fn killInst(self: *Ctx, inst: *Inst) ?*Inst {
        self.killNamesAndDecorates(inst);
        // KillOperandFromDebugInstructions / KillRelatedDebugScopes: DBGINFO-DROP

        if (self.areAnalysesValid(Analysis.def_use)) {
            const du: *DefUseMgr = self.getDefUseMgr();
            du.clearInst(inst);
            for (inst.dbg_lines.items) |l| du.clearInst(l);
        }
        if (self.areAnalysesValid(Analysis.decorations)) {
            if (inst.isDecoration()) self.getDecorationMgr().removeDecoration(inst);
        }
        if (self.type_mgr) |tm| {
            if (opIsTypeInst(inst.op)) tm.removeId(inst.resultId());
        }
        if (self.const_mgr) |cm| {
            if (opIsConstant(inst.op)) cm.removeId(inst.resultId());
        }
        switch (inst.op) {
            .OpCapability, .OpConditionalCapabilityINTEL, .OpExtension, .OpConditionalExtensionINTEL, .OpExtInstImport => self.resetFeatureManager(),
            else => {},
        }
        self.removeFromIdToName(inst);

        var next_instruction: ?*Inst = null;
        if (inst.isInAList()) {
            next_instruction = inst.next;
            _ = inst.removeFromList();
        } else {
            inst.toNop();
        }
        return next_instruction;
    }

    /// KillInstructionIf over one module instruction list. Returns true when something was removed.
    pub fn killInstructionIf(self: *Ctx, list: *InstList, pctx: anytype, comptime pred: fn (@TypeOf(pctx), *Inst) bool) bool {
        var removed: bool = false;
        var it: ?*Inst = list.first;
        while (it) |i| {
            const nxt: ?*Inst = i.next;
            if (pred(pctx, i)) {
                removed = true;
                _ = self.killInst(i);
            }
            it = nxt;
        }
        return removed;
    }

    pub fn killDef(self: *Ctx, id: u32) bool {
        const def: *Inst = self.getDefUseMgr().getDef(id) orelse return false;
        _ = self.killInst(def);
        return true;
    }

    pub fn removeCapability(self: *Ctx, capability: u32) bool {
        const Pred = struct {
            fn f(cap: u32, inst: *Inst) bool {
                return inst.getSingleWordOperand(0) == cap;
            }
        };
        const removed: bool = self.killInstructionIf(&self.module.capabilities, capability, Pred.f);
        if (removed) {
            if (self.feature) |fm| fm.removeCapability(capability);
        }
        return removed;
    }

    pub fn removeExtension(self: *Ctx, extension: Extension) bool {
        const Pred = struct {
            fn f(name: []const u8, inst: *Inst) bool {
                return std.mem.eql(u8, inst.getOperand(0).asString(), name);
            }
        };
        const removed: bool = self.killInstructionIf(&self.module.extensions, @as([]const u8, @tagName(extension)), Pred.f);
        if (removed) {
            if (self.feature) |fm| fm.removeExtension(extension);
        }
        return removed;
    }

    /// CollectNonSemanticTree: every non-semantic instruction that (transitively) uses `inst`.
    pub fn collectNonSemanticTree(self: *Ctx, inst: *Inst, to_kill: *Set(*Inst)) void {
        if (inst.resultId() == 0) return;
        if (inst.isLineInst()) return;
        var work_list: List(*Inst) = .{};
        var seen: Set(*Inst) = .{};
        work_list.push(inst);
        const du: *DefUseMgr = self.getDefUseMgr();
        while (work_list.pop()) |i| {
            for (du.usersOf(i)) |user| {
                if (isNonSemanticInst(user) and !user.isLineInst() and seen.insert(user)) {
                    work_list.push(user);
                    _ = to_kill.insert(user);
                }
            }
        }
    }

    // ---- replace all uses ------------------------------------------------------------------------------

    pub fn replaceAllUsesWith(self: *Ctx, before: u32, after: u32) bool {
        const Always = struct {
            fn f(_: void, _: *Inst) bool {
                return true;
            }
        };
        return self.replaceAllUsesWithPredicate(before, after, {}, Always.f);
    }

    /// Rewrites every use of `before` accepted by `pred` to `after`. Returns false when before == after.
    pub fn replaceAllUsesWithPredicate(self: *Ctx, before: u32, after: u32, pctx: anytype, comptime pred: fn (@TypeOf(pctx), *Inst) bool) bool {
        if (before == after) return false;
        const du: *DefUseMgr = self.getDefUseMgr();
        check(du.getDef(after) != null, "replaceAllUsesWith: 'after' is not a registered def.");

        var uses_to_update: List(UseRec) = .{};
        var all_uses: DefUseMgr.UseIter = du.usesOfId(before);
        while (all_uses.next()) |use| {
            if (pred(pctx, use.user)) uses_to_update.push(use);
        }

        var prev: ?*Inst = null;
        for (uses_to_update.items) |p| {
            const user: *Inst = p.user;
            const index: u32 = p.index;
            if (prev == null or prev.? != user) {
                self.forgetUsesBeforeReanalysis(user);
                prev = user;
            }
            const type_result_id_count: u32 = @intCast(user.typeResultIdCount());
            if (index < type_result_id_count) {
                if (user.typeId() != 0 and index == 0) {
                    user.setResultType(after);
                } else if (user.typeId() == 0) {
                    fatal("Result type id considered as use while the instruction doesn't have a result type id.", .{});
                } else {
                    fatal("Trying setting the immutable result id.", .{});
                }
            } else {
                user.setInOperand(index - type_result_id_count, &.{after});
            }
            self.analyzeUses(user);
        }
        return true;
    }

    // ---- call tree -------------------------------------------------------------------------------------

    pub fn addCalls(self: *Ctx, func: *const Func, todo: *Queue(u32)) void {
        _ = self;
        for (func.blocks.items) |bb| {
            var ii: ?*Inst = bb.insts.first;
            while (ii) |i| : (ii = i.next) {
                switch (i.op) {
                    .OpFunctionCall => todo.push(i.getSingleWordInOperand(0)),
                    .OpCooperativeMatrixPerElementOpEXT => todo.push(i.getSingleWordInOperand(1)),
                    .OpCooperativeMatrixReduceEXT => todo.push(i.getSingleWordInOperand(2)),
                    .OpCooperativeMatrixLoadTensorNV => {
                        const memory_operands_index: u32 = 3;
                        var mask: u32 = i.getSingleWordInOperand(memory_operands_index);
                        var count: u32 = 1;
                        if (mask & 0x2 != 0) count += 1; // Aligned
                        if (mask & 0x8 != 0) count += 1; // MakePointerAvailableKHR
                        if (mask & 0x10 != 0) count += 1; // MakePointerVisibleKHR
                        const tensor_operands_index: u32 = memory_operands_index + count;
                        mask = i.getSingleWordInOperand(tensor_operands_index);
                        count = 1;
                        if (mask & 0x1 != 0) count += 1; // TensorView
                        if (mask & 0x2 != 0) { // DecodeFunc
                            todo.push(i.getSingleWordInOperand(tensor_operands_index + count));
                            count += 1;
                        }
                        if (mask & 0x4 != 0) { // DecodeVectorFunc
                            todo.push(i.getSingleWordInOperand(tensor_operands_index + count));
                        }
                    },
                    else => {},
                }
            }
        }
    }

    pub fn processCallTreeFromRoots(self: *Ctx, cctx: anytype, comptime pfn: fn (@TypeOf(cctx), *Func) bool, roots: *Queue(u32)) bool {
        var modified: bool = false;
        var done: Set(u32) = .{};
        while (roots.pop()) |fi| {
            if (done.insert(fi)) {
                const fun: *Func = self.getFunction(fi) orelse fatal("Trying to process a function that does not exist: %{d}", .{fi});
                modified = pfn(cctx, fun) or modified;
                self.addCalls(fun, roots);
            }
        }
        return modified;
    }

    pub fn processEntryPointCallTree(self: *Ctx, cctx: anytype, comptime pfn: fn (@TypeOf(cctx), *Func) bool) bool {
        var roots: Queue(u32) = .{};
        var it: ?*Inst = self.module.entry_points.first;
        while (it) |e| : (it = e.next) roots.push(e.getSingleWordInOperand(1));
        return self.processCallTreeFromRoots(cctx, pfn, &roots);
    }

    pub fn processReachableCallTree(self: *Ctx, cctx: anytype, comptime pfn: fn (@TypeOf(cctx), *Func) bool) bool {
        var roots: Queue(u32) = .{};
        var it: ?*Inst = self.module.entry_points.first;
        while (it) |e| : (it = e.next) roots.push(e.getSingleWordInOperand(1));
        var ia: ?*Inst = self.module.annotations.first;
        while (ia) |a| : (ia = a.next) {
            if (a.op == .OpDecorate) {
                if (a.getSingleWordOperand(1) == @intFromEnum(Decoration.LinkageAttributes)) {
                    const last_operand: usize = a.numOperands() - 1;
                    if (a.getSingleWordOperand(last_operand) == @intFromEnum(LinkageType.Export)) {
                        const id: u32 = a.getSingleWordOperand(0);
                        if (self.getFunction(id) != null) roots.push(id);
                    }
                }
            }
        }
        return self.processCallTreeFromRoots(cctx, pfn, &roots);
    }

    /// CollectCallTreeFromRoots
    pub fn collectCallTreeFromRoots(self: *Ctx, entry_id: u32, funcs: *Set(u32)) void {
        var roots: Queue(u32) = .{};
        roots.push(entry_id);
        while (roots.pop()) |fi| {
            _ = funcs.insert(fi);
            const fun: *Func = self.getFunction(fi) orelse fatal("collectCallTreeFromRoots: no function %{d}", .{fi});
            self.addCalls(fun, &roots);
        }
    }

    // ---- misc ------------------------------------------------------------------------------------------

    /// EmitErrorMessage: the C++ consumer prints to stderr; processing continues.
    pub fn emitErrorMessage(self: *Ctx, message: []const u8, inst: ?*Inst) void {
        _ = self;
        if (inst) |i| {
            std.debug.print("error: {s}\n  {s}\n", .{ message, @tagName(i.op) });
        } else {
            std.debug.print("error: {s}\n", .{message});
        }
    }

    pub fn isReachable(self: *Ctx, bb: *Block) bool {
        const f: *Func = bb.parent orelse fatal("isReachable: block %{d} has no parent function", .{bb.id()});
        return self.getDominatorAnalysis(f).dominates(f.entry(), bb);
    }

    /// GetStage: the execution model of the entry points (stage_max when there are none).
    pub fn getStage(self: *Ctx) u32 {
        const first: *Inst = self.module.entry_points.first orelse return stage_max;
        const stage: u32 = first.getSingleWordInOperand(0);
        var it: ?*Inst = self.module.entry_points.first;
        while (it) |e| : (it = e.next) {
            if (e.getSingleWordInOperand(0) != stage) {
                self.emitErrorMessage("Mixed stage shader module not supported", e);
                break;
            }
        }
        return stage;
    }
};

/// Decoration analysis: for every id, the decoration instructions that target it (directly, or through a decoration
/// group).
pub const DecorMgr = struct {
    ctx: *Ctx,
    module: *Module,
    /// std::unordered_map<uint32_t, TargetData>; C++ references into the map survive rehashing, so values are heap objects
    id_to_decoration_insts: Map(u32, *TargetData) = .{},

    pub fn init(ctx: *Ctx) *DecorMgr {
        const self = scAllocator().create(DecorMgr) catch oom();
        self.* = .{ .ctx = ctx, .module = ctx.module };
        self.analyzeDecorations();
        return self;
    }

    fn targetData(self: *DecorMgr, id: u32) *TargetData {
        const gop: Map(u32, *TargetData).GetOrPutResult = self.id_to_decoration_insts.getOrPut(id);
        if (!gop.found_existing) {
            const td = scAllocator().create(TargetData) catch oom();
            td.* = .{};
            gop.value_ptr.* = td;
        }
        return gop.value_ptr.*;
    }

    fn analyzeDecorations(self: *DecorMgr) void {
        var it: ?*Inst = self.module.annotations.first;
        while (it) |i| : (it = i.next) self.addDecorationInst(i);
    }

    /// AddDecoration(Instruction*): registers an annotation instruction that is already in the module.
    pub fn addDecorationInst(self: *DecorMgr, inst: *Inst) void {
        switch (inst.op) {
            .OpDecorate, .OpDecorateId, .OpDecorateStringGOOGLE, .OpMemberDecorate => {
                const target_id: u32 = inst.getSingleWordInOperand(0);
                self.targetData(target_id).direct.push(inst);
            },
            .OpGroupDecorate, .OpGroupMemberDecorate => {
                const start: u32 = if (inst.op == .OpGroupDecorate) 1 else 2;
                const stride: u32 = start;
                var i: u32 = start;
                while (i < inst.numInOperands()) : (i += stride) {
                    const target_id: u32 = inst.getSingleWordInOperand(i);
                    self.targetData(target_id).indirect.push(inst);
                }
                const group_id: u32 = inst.getSingleWordInOperand(0);
                self.targetData(group_id).decorate_insts.push(inst);
            },
            else => {},
        }
    }

    /// AddDecoration(opcode, operands): creates the instruction and adds it to the module through the context.
    pub fn addDecorationOp(self: *DecorMgr, opcode: Op, opnds: []const Operand) void {
        const inst: *Inst = Inst.make(opcode, 0, 0, opnds);
        self.ctx.addAnnotationInst(inst);
    }

    /// AddDecoration(uint32_t inst_id, uint32_t decoration)
    pub fn addDecorationVal0(self: *DecorMgr, inst_id: u32, decoration: u32) void {
        self.addDecorationOp(.OpDecorate, &.{
            Operand.id(.IdRef, inst_id),
            Operand.single(.LiteralInteger, decoration),
        });
    }

    /// AddDecorationVal(inst_id, decoration, decoration_value)
    pub fn addDecorationVal(self: *DecorMgr, inst_id: u32, decoration: u32, decoration_value: u32) void {
        self.addDecorationOp(.OpDecorate, &.{
            Operand.id(.IdRef, inst_id),
            Operand.single(.LiteralInteger, decoration),
            Operand.single(.LiteralInteger, decoration_value),
        });
    }

    pub fn addMemberDecoration(self: *DecorMgr, inst_id: u32, member: u32, decoration: u32, decoration_value: u32) void {
        self.addDecorationOp(.OpMemberDecorate, &.{
            Operand.id(.IdRef, inst_id),
            Operand.single(.LiteralInteger, member),
            Operand.single(.LiteralInteger, decoration),
            Operand.single(.LiteralInteger, decoration_value),
        });
    }

    /// RemoveDecoration(Instruction*): forgets a decoration instruction that is about to leave the module.
    pub fn removeDecoration(self: *DecorMgr, inst: *Inst) void {
        switch (inst.op) {
            .OpDecorate, .OpDecorateId, .OpDecorateStringGOOGLE, .OpMemberDecorate => {
                const target_id: u32 = inst.getSingleWordInOperand(0);
                const td: *TargetData = self.id_to_decoration_insts.get(target_id) orelse return;
                removeAllFromList(&td.direct, inst);
            },
            .OpGroupDecorate, .OpGroupMemberDecorate => {
                const stride: u32 = if (inst.op == .OpGroupDecorate) 1 else 2;
                var i: u32 = 1;
                while (i < inst.numInOperands()) : (i += stride) {
                    const target_id: u32 = inst.getSingleWordInOperand(i);
                    const td: *TargetData = self.id_to_decoration_insts.get(target_id) orelse continue;
                    removeAllFromList(&td.indirect, inst);
                }
                const group_id: u32 = inst.getSingleWordInOperand(0);
                const td: *TargetData = self.id_to_decoration_insts.get(group_id) orelse return;
                removeAllFromList(&td.decorate_insts, inst);
            },
            else => {},
        }
    }

    /// InternalGetDecorationsFor: direct decorations first, then those reached through decoration groups.
    pub fn getDecorationsFor(self: *DecorMgr, id: u32, include_linkage: bool) List(*Inst) {
        var out: List(*Inst) = .{};
        const td: *TargetData = self.id_to_decoration_insts.get(id) orelse return out;
        const link: u32 = @intFromEnum(Decoration.LinkageAttributes);
        for (td.direct.items) |inst| {
            const is_linkage: bool = inst.op == .OpDecorate and inst.getSingleWordInOperand(1) == link;
            if (include_linkage or !is_linkage) out.push(inst);
        }
        for (td.indirect.items) |inst| {
            const group_id: u32 = inst.getSingleWordInOperand(0);
            const gd: *TargetData = self.id_to_decoration_insts.get(group_id) orelse fatal("DecorMgr: unknown decoration group %{d}", .{group_id});
            for (gd.direct.items) |d| {
                const is_linkage: bool = d.op == .OpDecorate and d.getSingleWordInOperand(1) == link;
                if (include_linkage or !is_linkage) out.push(d);
            }
        }
        return out;
    }

    pub fn whileEachDecoration(self: *DecorMgr, id: u32, decoration: u32, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) bool) bool {
        const decos: List(*Inst) = self.getDecorationsFor(id, true);
        for (decos.items) |inst| {
            switch (inst.op) {
                .OpMemberDecorate => {
                    if (inst.getSingleWordInOperand(2) == decoration) {
                        if (!f(ctx, inst)) return false;
                    }
                },
                .OpDecorate, .OpDecorateId, .OpDecorateStringGOOGLE => {
                    if (inst.getSingleWordInOperand(1) == decoration) {
                        if (!f(ctx, inst)) return false;
                    }
                },
                else => {}, // C++: assert(false && "Unexpected decoration instruction") (a no-op in release builds)
            }
        }
        return true;
    }

    pub fn forEachDecoration(self: *DecorMgr, id: u32, decoration: u32, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) void) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), i: *Inst) bool {
                f(c, i);
                return true;
            }
        };
        _ = self.whileEachDecoration(id, decoration, ctx, Adapter.call);
    }

    pub fn hasDecoration(self: *DecorMgr, id: u32, decoration: u32) bool {
        const Mark = struct {
            fn f(found: *bool, _: *Inst) void {
                found.* = true;
            }
        };
        var found: bool = false;
        self.forEachDecoration(id, decoration, &found, Mark.f);
        return found;
    }

    /// FindDecoration: true if `f` returned true for some decoration of `id` with the given decoration value.
    pub fn findDecoration(self: *DecorMgr, id: u32, decoration: u32, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Inst) bool) bool {
        const Neg = struct {
            fn call(c: @TypeOf(ctx), i: *Inst) bool {
                return !f(c, i);
            }
        };
        return !self.whileEachDecoration(id, decoration, ctx, Neg.call);
    }

    pub fn haveTheSameDecorations(self: *DecorMgr, id1: u32, id2: u32) bool {
        const d1: List(*Inst) = self.getDecorationsFor(id1, false);
        const d2: List(*Inst) = self.getDecorationsFor(id2, false);
        var s1: DecoPayloadSets = .{};
        var s2: DecoPayloadSets = .{};
        s1.fill(d1.items);
        s2.fill(d2.items);
        for (0..4) |k| {
            const a: [][]const u32 = s1.sets[k].items;
            const b: [][]const u32 = s2.sets[k].items;
            if (a.len != b.len) return false;
            for (a, b) |x, y| {
                if (!std.mem.eql(u32, x, y)) return false;
            }
        }
        return true;
    }

    pub fn haveSubsetOfDecorations(self: *DecorMgr, id1: u32, id2: u32) bool {
        const d1: List(*Inst) = self.getDecorationsFor(id1, false);
        const d2: List(*Inst) = self.getDecorationsFor(id2, false);
        var s1: DecoPayloadSets = .{};
        var s2: DecoPayloadSets = .{};
        s1.fill(d1.items);
        s2.fill(d2.items);
        for (0..4) |k| {
            if (!payloadIsSubset(s1.sets[k].items, s2.sets[k].items)) return false;
        }
        return true;
    }

    pub fn areDecorationsTheSame(self: *const DecorMgr, inst1: *const Inst, inst2: *const Inst, ignore_target: bool) bool {
        _ = self;
        switch (inst1.op) {
            .OpDecorate, .OpMemberDecorate, .OpDecorateId, .OpDecorateStringGOOGLE => {},
            else => return false,
        }
        if (inst1.op != inst2.op or inst1.numInOperands() != inst2.numInOperands()) return false;
        var i: usize = if (ignore_target) 1 else 0;
        while (i < inst1.numInOperands()) : (i += 1) {
            if (!inst1.getInOperand(i).eql(inst2.getInOperand(i))) return false;
        }
        return true;
    }

    /// CloneDecorations(from, to): copies direct decorations, appends `to` to the groups that decorate `from`.
    pub fn cloneDecorations(self: *DecorMgr, from: u32, to: u32) void {
        const td: *TargetData = self.id_to_decoration_insts.get(from) orelse return;
        const ctx: *Ctx = self.ctx;
        // the loop below adds clones that analyzeUses may register under `to`; `from`'s list is not touched unless
        // from == to, so iterate a snapshot of its length like the C++ range-for does
        const n_direct: usize = td.direct.len();
        for (0..n_direct) |k| {
            const inst: *Inst = td.direct.items[k];
            const new_inst: *Inst = inst.clone();
            new_inst.setInOperand(0, &.{to});
            self.module.addAnnotationInst(new_inst);
            ctx.analyzeUses(new_inst);
        }
        // C++ copies the vector first
        var indirect: List(*Inst) = .{};
        indirect.pushSlice(td.indirect.items);
        for (indirect.items) |inst| {
            switch (inst.op) {
                .OpGroupDecorate => {
                    ctx.forgetUses(inst);
                    inst.addOperand(Operand.id(.IdRef, to));
                    ctx.analyzeUses(inst);
                },
                .OpGroupMemberDecorate => {
                    ctx.forgetUses(inst);
                    const num_operands: usize = inst.numOperands();
                    var i: usize = 1;
                    while (i < num_operands) : (i += 2) {
                        const op: Operand = inst.getOperand(i).*;
                        if (op.n != 0 and op.words()[0] == from) { // add new pair of operands: (to, literal)
                            inst.addOperand(Operand.id(.IdRef, to));
                            const lit: Operand = inst.getOperand(i + 1).*;
                            inst.addOperand(lit);
                        }
                    }
                    ctx.analyzeUses(inst);
                },
                else => fatal("DecorMgr.cloneDecorations: unexpected decoration instruction {s}", .{@tagName(inst.op)}),
            }
        }
    }

    pub fn cloneDecorationsSubset(self: *DecorMgr, from: u32, to: u32, decorations_to_copy: []const Decoration) void {
        const td: *TargetData = self.id_to_decoration_insts.get(from) orelse return;
        const ctx: *Ctx = self.ctx;
        const n_direct: usize = td.direct.len();
        for (0..n_direct) |k| {
            const inst: *Inst = td.direct.items[k];
            const dec_value: u32 = inst.getSingleWordInOperand(1);
            var wanted: bool = false;
            for (decorations_to_copy) |d| {
                if (@intFromEnum(d) == dec_value) wanted = true;
            }
            if (!wanted) continue;
            const new_inst: *Inst = inst.clone();
            new_inst.setInOperand(0, &.{to});
            self.module.addAnnotationInst(new_inst);
            ctx.analyzeUses(new_inst);
        }
        var indirect: List(*Inst) = .{};
        indirect.pushSlice(td.indirect.items);
        for (indirect.items) |inst| {
            switch (inst.op) {
                .OpGroupDecorate => self.cloneDecorationsSubset(inst.getSingleWordInOperand(0), to, decorations_to_copy),
                // C++: assert(false) in both cases; release builds ignore them
                .OpGroupMemberDecorate => {},
                else => {},
            }
        }
    }

    /// RemoveDecorationsFrom(id, pred): removes every decoration of `id` accepted by `pred` (also from groups).
    /// Returns true when something changed.
    pub fn removeDecorationsFrom(self: *DecorMgr, id: u32, pctx: anytype, comptime pred: fn (@TypeOf(pctx), *Inst) bool) bool {
        var was_modified: bool = false;
        const info: *TargetData = self.id_to_decoration_insts.get(id) orelse return was_modified;
        const ctx: *Ctx = self.ctx;
        var insts_to_kill: List(*Inst) = .{};
        const is_group: bool = info.decorate_insts.len() != 0;

        for (info.direct.items) |inst| {
            if (pred(pctx, inst)) insts_to_kill.push(inst);
        }

        var indirect_to_remove: Set(*const Inst) = .{};
        // C++ iterates `indirect_decorations` with a range-for (end fixed at loop entry) while ForgetUses/AnalyzeUses
        // erase and re-append the current element; an index loop over the original length reproduces that.
        const n_indirect: usize = info.indirect.len();
        for (0..n_indirect) |k| {
            const inst: *Inst = info.indirect.items[k];
            check(inst.op == .OpGroupDecorate or inst.op == .OpGroupMemberDecorate, "DecorMgr.removeDecorationsFrom: bad indirect decoration");
            var group_decorations_to_keep: List(*Inst) = .{};
            const group_id: u32 = inst.getSingleWordInOperand(0);
            const group_data: *TargetData = self.id_to_decoration_insts.get(group_id) orelse fatal("DecorMgr: unknown decoration group %{d}", .{group_id});
            const group_decorations: []*Inst = group_data.direct.items;
            for (group_decorations) |decoration| {
                if (!pred(pctx, decoration)) group_decorations_to_keep.push(decoration);
            }
            if (group_decorations_to_keep.len() == group_decorations.len and group_decorations.len != 0) continue;

            const stride: u32 = if (inst.op == .OpGroupDecorate) 1 else 2;
            var i: u32 = 1;
            while (i < inst.numInOperands()) {
                if (inst.getSingleWordInOperand(i) != id) {
                    i += stride;
                    continue;
                }
                const last_operand_index: u32 = @intCast(inst.numInOperands() - stride);
                if (i < last_operand_index) inst.getInOperand(i).* = inst.getInOperand(last_operand_index).*;
                if (stride == 2) {
                    if (i < last_operand_index) inst.getInOperand(i + 1).* = inst.getInOperand(last_operand_index + 1).*;
                    inst.removeInOperand(last_operand_index + 1);
                }
                inst.removeInOperand(last_operand_index);
                was_modified = true;
            }

            if (inst.numInOperands() == 1) {
                _ = indirect_to_remove.insert(inst);
                insts_to_kill.push(inst);
            } else if (was_modified) {
                ctx.forgetUses(inst);
                _ = indirect_to_remove.insert(inst);
                ctx.analyzeUses(inst);
            }

            if (group_decorations_to_keep.len() != 0) {
                for (group_decorations_to_keep.items) |decoration| {
                    const new_inst: *Inst = decoration.clone();
                    new_inst.setInOperand(0, &.{id});
                    self.module.addAnnotationInst(new_inst);
                    ctx.analyzeUses(new_inst);
                }
            }
        }

        {
            var w: usize = 0;
            for (info.indirect.items) |x| {
                if (!indirect_to_remove.contains(x)) {
                    info.indirect.items[w] = x;
                    w += 1;
                }
            }
            info.indirect.truncate(w);
        }

        was_modified = was_modified or insts_to_kill.len() != 0;
        for (insts_to_kill.items) |inst| _ = ctx.killInst(inst);
        insts_to_kill.clear();

        if (is_group and info.direct.len() == 0 and info.indirect.len() == 0) {
            for (info.decorate_insts.items) |inst| insts_to_kill.push(inst);
        }
        was_modified = was_modified or insts_to_kill.len() != 0;
        for (insts_to_kill.items) |inst| _ = ctx.killInst(inst);

        if (info.direct.len() == 0 and info.indirect.len() == 0 and info.decorate_insts.len() == 0) {
            _ = self.id_to_decoration_insts.remove(id);
        }
        return was_modified;
    }

    /// RemoveDecorationsFrom(id) with the default predicate (everything).
    pub fn removeAllDecorationsFrom(self: *DecorMgr, id: u32) bool {
        const All = struct {
            fn f(_: void, _: *Inst) bool {
                return true;
            }
        };
        return self.removeDecorationsFrom(id, {}, All.f);
    }
};

/// Control-flow graph of the module: predecessors per block label, the structured successors, and the pseudo entry /
/// exit blocks.
pub const Cfg = struct {
    ctx: *Ctx,
    module: *Module,
    block2structured_succs: Map(*Block, List(*Block)) = .{},
    pseudo_entry_block: *Block,
    pseudo_exit_block: *Block,
    label2preds: Map(u32, List(u32)) = .{},
    id2block: Map(u32, *Block) = .{},

    pub fn init(ctx: *Ctx) *Cfg {
        const self = scAllocator().create(Cfg) catch oom();
        self.* = .{
            .ctx = ctx,
            .module = ctx.module,
            .pseudo_entry_block = ctx.pseudoEntryBlock(),
            .pseudo_exit_block = ctx.pseudoExitBlock(),
        };
        for (ctx.module.functions.items) |fun| {
            for (fun.blocks.items) |blk| self.registerBlock(blk);
        }
        return self;
    }

    /// CFG::preds: the recorded predecessors of the block with label `blk_id` (a view: copy before mutating the CFG).
    pub fn preds(self: *const Cfg, blk_id: u32) []const u32 {
        const l: *List(u32) = self.label2preds.getPtr(blk_id) orelse fatal("Cfg.preds: no predecessor record for %{d}", .{blk_id});
        return l.items;
    }

    pub fn block(self: *const Cfg, blk_id: u32) *Block {
        return self.id2block.get(blk_id) orelse fatal("Cfg.block: no block %{d}", .{blk_id});
    }

    pub fn isPseudoEntryBlock(self: *const Cfg, b: *const Block) bool {
        return b == self.pseudo_entry_block;
    }

    pub fn isPseudoExitBlock(self: *const Cfg, b: *const Block) bool {
        return b == self.pseudo_exit_block;
    }

    pub fn registerBlock(self: *Cfg, blk: *Block) void {
        // The C++ asserts a terminator here in debug builds only; a release build registers the block, and a tail that is
        // not a branch has no successors. An entirely empty block is rejected loudly.
        check(blk.insts.first != null, "Basic blocks must have a terminator before registering.");
        self.id2block.put(blk.id(), blk);
        self.addEdges(blk);
    }

    pub fn forgetBlock(self: *Cfg, blk: *const Block) void {
        _ = self.id2block.remove(blk.id());
        _ = self.label2preds.remove(blk.id());
        self.removeSuccessorEdges(blk);
    }

    pub fn removeEdge(self: *Cfg, pred_blk_id: u32, succ_blk_id: u32) void {
        const list: *List(u32) = self.label2preds.getPtr(succ_blk_id) orelse return;
        if (list.indexOf(pred_blk_id)) |at| _ = list.orderedRemove(at);
    }

    pub fn addEdge(self: *Cfg, pred_blk_id: u32, succ_blk_id: u32) void {
        const gop: Map(u32, List(u32)).GetOrPutResult = self.label2preds.getOrPut(succ_blk_id);
        if (!gop.found_existing) gop.value_ptr.* = .{};
        gop.value_ptr.push(pred_blk_id);
    }

    const EdgeCap = struct { cfg: *Cfg, from: u32 };

    fn addEdgeCb(c: *const EdgeCap, succ_id: u32) void {
        c.cfg.addEdge(c.from, succ_id);
    }

    fn removeEdgeCb(c: *const EdgeCap, succ_id: u32) void {
        c.cfg.removeEdge(c.from, succ_id);
    }

    pub fn addEdges(self: *Cfg, blk: *const Block) void {
        const blk_id: u32 = blk.id();
        const gop: Map(u32, List(u32)).GetOrPutResult = self.label2preds.getOrPut(blk_id); // `label2preds_[blk_id];`
        if (!gop.found_existing) gop.value_ptr.* = .{};
        const cap: EdgeCap = .{ .cfg = self, .from = blk_id };
        blk.forEachSuccessorLabel(&cap, addEdgeCb);
    }

    pub fn removeSuccessorEdges(self: *Cfg, bb: *const Block) void {
        const cap: EdgeCap = .{ .cfg = self, .from = bb.id() };
        bb.forEachSuccessorLabel(&cap, removeEdgeCb);
    }

    const HasCap = struct { target: u32, found: bool };

    fn hasSuccCb(c: *HasCap, succ: u32) void {
        if (succ == c.target) c.found = true;
    }

    pub fn removeNonExistingEdges(self: *Cfg, blk_id: u32) void {
        var updated: List(u32) = .{};
        for (self.preds(blk_id)) |id| {
            const pred_blk: *Block = self.block(id);
            var cap: HasCap = .{ .target = blk_id, .found = false };
            pred_blk.forEachSuccessorLabel(&cap, hasSuccCb);
            if (cap.found) updated.push(id);
        }
        const slot: *List(u32) = self.label2preds.getPtr(blk_id) orelse fatal("Cfg.removeNonExistingEdges: no record for %{d}", .{blk_id});
        slot.* = updated;
    }

    // ---- structured order ---------------------------------------------------------------------

    const StructCap = struct { cfg: *Cfg, from: *Block };

    fn structSuccCb(c: *const StructCap, sbid: u32) void {
        c.cfg.structuredSuccsOf(c.from).push(c.cfg.block(sbid));
    }

    fn computeStructuredSuccessors(self: *Cfg, func: *Func) void {
        self.block2structured_succs.clear();
        for (func.blocks.items) |blk| {
            const pr: Map(u32, List(u32)).GetOrPutResult = self.label2preds.getOrPut(blk.id());
            if (!pr.found_existing) pr.value_ptr.* = .{};
            if (pr.value_ptr.len() == 0) self.structuredSuccsOf(self.pseudo_entry_block).push(blk);
            const mbid: u32 = blk.mergeBlockIdIfAny();
            if (mbid != 0) {
                self.structuredSuccsOf(blk).push(self.block(mbid));
                const cbid: u32 = blk.continueBlockIdIfAny();
                if (cbid != 0) self.structuredSuccsOf(blk).push(self.block(cbid));
            }
            const cap: StructCap = .{ .cfg = self, .from = blk };
            blk.forEachSuccessorLabel(&cap, structSuccCb);
        }
    }

    /// `block2structured_succs_[b]` (operator[] creates an empty entry)
    fn structuredSuccsOf(self: *Cfg, b: *Block) *List(*Block) {
        const gop: Map(*Block, List(*Block)).GetOrPutResult = self.block2structured_succs.getOrPut(b);
        if (!gop.found_existing) gop.value_ptr.* = .{};
        return gop.value_ptr;
    }

    /// ComputeStructuredOrder: reverse post order of the structured CFG (merge and continue blocks count as
    /// successors of their header, before its branch targets), prepended to `order`. `end` stops a branch of the walk.
    pub fn computeStructuredOrder(self: *Cfg, func: *Func, root: *Block, end: ?*Block, order: *List(*Block)) void {
        self.computeStructuredSuccessors(func);
        const Walk = struct {
            cfg: *Cfg,
            end: ?*Block,
            post: List(*Block) = .{},
            fn succ(w: *@This(), b: *Block) []const *Block {
                return w.cfg.structuredSuccsOf(b).items;
            }
            fn pre(_: *@This(), _: *Block) void {}
            fn postFn(w: *@This(), b: *Block) void {
                w.post.push(b);
            }
            fn term(w: *@This(), b: *Block) bool {
                return if (w.end) |e| b == e else false;
            }
        };
        var w: Walk = .{ .cfg = self, .end = end };
        BlockCfa.depthFirstTraversal(root, &w, Walk.succ, Walk.pre, Walk.postFn, Walk.term);
        // `order->push_front(b)` for every post-order block == the reversed post order in front of the old content
        var merged: List(*Block) = .{};
        var k: usize = w.post.len();
        while (k > 0) {
            k -= 1;
            merged.push(w.post.items[k]);
        }
        merged.pushSlice(order.items);
        order.* = merged;
    }

    pub fn computeStructuredOrderNoEnd(self: *Cfg, func: *Func, root: *Block, order: *List(*Block)) void {
        self.computeStructuredOrder(func, root, null, order);
    }

    // ---- post order / reverse post order ------------------------------------------------------

    fn computePostOrderTraversal(self: *Cfg, start: *Block, order: *List(*Block), seen: *Set(*Block)) void {
        var stack: List(*Block) = .{};
        stack.push(start);
        const Cap = struct {
            cfg: *Cfg,
            seen: *Set(*Block),
            stack: *List(*Block),
            fn f(c: *@This(), sbid: u32) bool {
                const succ_bb: *Block = c.cfg.id2block.get(sbid) orelse fatal("Cfg: no block %{d} (successor)", .{sbid});
                if (!c.seen.contains(succ_bb)) {
                    c.stack.push(succ_bb);
                    return false;
                }
                return true;
            }
        };
        while (stack.len() > 0) {
            const bb: *Block = stack.last();
            _ = seen.insert(bb);
            var cap: Cap = .{ .cfg = self, .seen = seen, .stack = &stack };
            _ = bb.whileEachSuccessorLabel(&cap, Cap.f);
            if (stack.last() == bb) {
                order.push(bb);
                _ = stack.pop();
            }
        }
    }

    pub fn forEachBlockInPostOrder(self: *Cfg, bb: *Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Block) void) void {
        var po: List(*Block) = .{};
        var seen: Set(*Block) = .{};
        self.computePostOrderTraversal(bb, &po, &seen);
        for (po.items) |cur| {
            if (!self.isPseudoExitBlock(cur) and !self.isPseudoEntryBlock(cur)) f(ctx, cur);
        }
    }

    pub fn whileEachBlockInReversePostOrder(self: *Cfg, bb: *Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Block) bool) bool {
        var po: List(*Block) = .{};
        var seen: Set(*Block) = .{};
        self.computePostOrderTraversal(bb, &po, &seen);
        var k: usize = po.len();
        while (k > 0) {
            k -= 1;
            const cur: *Block = po.items[k];
            if (!self.isPseudoExitBlock(cur) and !self.isPseudoEntryBlock(cur)) {
                if (!f(ctx, cur)) return false;
            }
        }
        return true;
    }

    pub fn forEachBlockInReversePostOrder(self: *Cfg, bb: *Block, ctx: anytype, comptime f: fn (@TypeOf(ctx), *Block) void) void {
        const Adapter = struct {
            fn call(c: @TypeOf(ctx), b: *Block) bool {
                f(c, b);
                return true;
            }
        };
        _ = self.whileEachBlockInReversePostOrder(bb, ctx, Adapter.call);
    }

    // CFG::SplitLoopHeader is `cfgSplitLoopHeader` in the loop code: it needs InstBuilder and LoopDescriptor.
};

/// BasicBlockSuccessorHelper of dominator_tree.cpp: successor and predecessor lists of one function, with a
/// placeholder start node (pseudo entry for dominators, pseudo exit for post-dominators).
const SuccHelper = struct {
    successors: Map(*Block, List(*Block)) = .{},
    predecessors: Map(*Block, List(*Block)) = .{},

    fn listOf(map: *Map(*Block, List(*Block)), b: *Block) *List(*Block) {
        const gop: Map(*Block, List(*Block)).GetOrPutResult = map.getOrPut(b);
        if (!gop.found_existing) gop.value_ptr.* = .{};
        return gop.value_ptr;
    }

    fn succFn(self: *SuccHelper, b: *Block) []const *Block {
        return listOf(&self.successors, b).items;
    }

    fn predFn(self: *SuccHelper, b: *Block) []const *Block {
        return listOf(&self.predecessors, b).items;
    }

    const SuccCap = struct { helper: *SuccHelper, ctx: *Ctx, bb: *Block, invert: bool };

    fn visitSucc(c: *const SuccCap, successor_id: u32) void {
        const succ: *Block = c.ctx.getInstrBlockById(successor_id) orelse fatal("dominators: no block for label %{d}", .{successor_id});
        if (c.invert) {
            listOf(&c.helper.successors, succ).push(c.bb);
            listOf(&c.helper.predecessors, c.bb).push(succ);
        } else {
            listOf(&c.helper.successors, c.bb).push(succ);
            listOf(&c.helper.predecessors, succ).push(c.bb);
        }
    }

    fn create(ctx: *Ctx, f: *Func, placeholder: *Block, invert: bool) SuccHelper {
        var h: SuccHelper = .{};
        if (invert) {
            for (f.blocks.items) |bb| {
                if (bb.hasSuccessor()) {
                    _ = listOf(&h.predecessors, bb); // `predecessors_[&bb]`
                    const cap: SuccCap = .{ .helper = &h, .ctx = ctx, .bb = bb, .invert = true };
                    bb.forEachSuccessorLabel(&cap, visitSucc);
                } else {
                    listOf(&h.successors, placeholder).push(bb);
                    listOf(&h.predecessors, bb).push(placeholder);
                }
            }
        } else {
            listOf(&h.successors, placeholder).push(f.entry());
            listOf(&h.predecessors, f.entry()).push(placeholder);
            for (f.blocks.items) |bb| {
                _ = listOf(&h.successors, bb); // `succ_list = successors_[&bb]`
                const cap: SuccCap = .{ .helper = &h, .ctx = ctx, .bb = bb, .invert = false };
                bb.forEachSuccessorLabel(&cap, visitSucc);
            }
        }
        return h;
    }
};

const PostOrderCap = struct {
    helper: *SuccHelper,
    po: List(*Block) = .{},

    fn succ(c: *PostOrderCap, b: *Block) []const *Block {
        return c.helper.succFn(b);
    }
    fn pre(_: *PostOrderCap, _: *Block) void {}
    fn post(c: *PostOrderCap, b: *Block) void {
        c.po.push(b);
    }
    fn terminal(_: *PostOrderCap, _: *Block) bool {
        return false;
    }
};

/// A dominator (or post-dominator) tree of one function.
pub const DomTree = struct {
    roots: List(*DomNode) = .{},
    nodes: Map(u32, *DomNode) = .{},
    postdominator: bool = false,

    pub fn init(post: bool) DomTree {
        return .{ .postdominator = post };
    }

    pub fn clearTree(self: *DomTree) void {
        self.nodes = .{};
        self.roots = .{};
    }

    pub fn isPostDominator(self: *const DomTree) bool {
        return self.postdominator;
    }

    /// The single root (the pseudo entry / exit block's node).
    pub fn getRoot(self: *const DomTree) *DomNode {
        check(self.roots.len() == 1, "DomTree.getRoot: expected exactly one root");
        return self.roots.items[0];
    }

    pub fn getTreeNode(self: *const DomTree, id: u32) ?*DomNode {
        return self.nodes.get(id);
    }

    pub fn getTreeNodeOf(self: *const DomTree, bb: *const Block) ?*DomNode {
        return self.nodes.get(bb.id());
    }

    pub fn getOrInsertNode(self: *DomTree, bb: *Block) *DomNode {
        if (self.nodes.get(bb.id())) |n| return n;
        const n = scAllocator().create(DomNode) catch oom();
        n.* = .{ .bb = bb };
        self.nodes.put(bb.id(), n);
        return n;
    }

    pub fn initializeTree(self: *DomTree, ctx: *Ctx, cfg: *Cfg, f: *Func) void {
        self.clearTree();
        if (f.blocks.len() == 0) return;
        const placeholder: *Block = if (self.postdominator) cfg.pseudo_exit_block else cfg.pseudo_entry_block;

        // GetDominatorEdges
        var helper = SuccHelper.create(ctx, f, placeholder, self.postdominator);
        var pc: PostOrderCap = .{ .helper = &helper };
        BlockCfa.depthFirstTraversal(placeholder, &pc, PostOrderCap.succ, PostOrderCap.pre, PostOrderCap.post, PostOrderCap.terminal);
        const edges: List(Cfa(Block).Edge) = BlockCfa.calculateDominators(pc.po.items, &helper, SuccHelper.predFn);

        for (edges.items) |edge| {
            const first: *DomNode = self.getOrInsertNode(edge.block);
            if (edge.block == edge.idom) {
                if (!self.roots.contains(first)) self.roots.push(first);
                continue;
            }
            const second: *DomNode = self.getOrInsertNode(edge.idom);
            first.parent = second;
            second.children.push(first);
        }
        self.resetDFNumbering();
    }

    pub fn resetDFNumbering(self: *DomTree) void {
        var c: DfsNumCap = .{};
        for (self.roots.items) |root| {
            DomCfa.depthFirstTraversal(root, &c, DfsNumCap.succ, DfsNumCap.pre, DfsNumCap.post, DfsNumCap.terminal);
        }
    }

    pub fn dominatesNode(self: *const DomTree, a: ?*const DomNode, b: ?*const DomNode) bool {
        _ = self;
        const an: *const DomNode = a orelse return false;
        const bn: *const DomNode = b orelse return false;
        if (an == bn) return true;
        return an.dfs_num_pre < bn.dfs_num_pre and an.dfs_num_post > bn.dfs_num_post;
    }

    pub fn dominatesId(self: *const DomTree, a: u32, b: u32) bool {
        const an: *DomNode = self.getTreeNode(a) orelse return false;
        const bn: *DomNode = self.getTreeNode(b) orelse return false;
        return self.dominatesNode(an, bn);
    }

    pub fn dominates(self: *const DomTree, a: *const Block, b: *const Block) bool {
        return self.dominatesId(a.id(), b.id());
    }

    pub fn strictlyDominatesId(self: *const DomTree, a: u32, b: u32) bool {
        if (a == b) return false;
        return self.dominatesId(a, b);
    }

    pub fn strictlyDominates(self: *const DomTree, a: *const Block, b: *const Block) bool {
        return self.strictlyDominatesId(a.id(), b.id());
    }

    pub fn strictlyDominatesNode(self: *const DomTree, a: ?*const DomNode, b: ?*const DomNode) bool {
        if (a == b) return false;
        return self.dominatesNode(a, b);
    }

    /// The immediate dominator; for a child of the root this is the pseudo entry (exit) block, for unreachable
    /// blocks and for the root itself null.
    pub fn immediateDominatorId(self: *const DomTree, a: u32) ?*Block {
        const node: *DomNode = self.getTreeNode(a) orelse return null;
        const p: *DomNode = node.parent orelse return null;
        return p.bb;
    }

    pub fn immediateDominator(self: *const DomTree, a: *const Block) ?*Block {
        return self.immediateDominatorId(a.id());
    }

    pub fn reachableFromRootsId(self: *const DomTree, a: u32) bool {
        return self.getTreeNode(a) != null;
    }

    /// `for (auto& node : tree)`: pre-order over the tree without the root.
    pub fn nodesPreOrder(self: *const DomTree) List(*DomNode) {
        var all: List(*DomNode) = .{};
        treeDfsPreOrder(self.getRoot(), &all);
        var out: List(*DomNode) = .{};
        if (all.len() > 1) out.pushSlice(all.items[1..]);
        return out;
    }

    /// `post_begin()..post_end()` of the tree: post-order without the root.
    pub fn nodesPostOrder(self: *const DomTree) List(*DomNode) {
        var all: List(*DomNode) = .{};
        treeDfsPostOrder(self.getRoot(), &all);
        all.truncate(all.len() - 1);
        return all;
    }

    pub fn whileEachNode(self: *const DomTree, ctx: anytype, comptime f: fn (@TypeOf(ctx), *DomNode) bool) bool {
        const nodes: List(*DomNode) = self.nodesPreOrder();
        for (nodes.items) |n| {
            if (!f(ctx, n)) return false;
        }
        return true;
    }
};

/// The dominator tree of a function plus the queries passes ask of it.
pub const DominatorAnalysis = struct {
    tree: DomTree,

    pub fn init(post: bool) DominatorAnalysis {
        return .{ .tree = DomTree.init(post) };
    }

    pub fn initializeTree(self: *DominatorAnalysis, ctx: *Ctx, cfg: *Cfg, f: *Func) void {
        self.tree.initializeTree(ctx, cfg, f);
    }

    pub fn getDomTree(self: *DominatorAnalysis) *DomTree {
        return &self.tree;
    }

    pub fn isPostDominator(self: *const DominatorAnalysis) bool {
        return self.tree.isPostDominator();
    }

    pub fn clearTree(self: *DominatorAnalysis) void {
        self.tree.clearTree();
    }

    /// Dominates(const BasicBlock*, const BasicBlock*): null on either side is false
    pub fn dominates(self: *const DominatorAnalysis, a: ?*const Block, b: ?*const Block) bool {
        const ab: *const Block = a orelse return false;
        const bb: *const Block = b orelse return false;
        return self.tree.dominates(ab, bb);
    }

    pub fn dominatesId(self: *const DominatorAnalysis, a: u32, b: u32) bool {
        return self.tree.dominatesId(a, b);
    }

    pub fn dominatesInst(self: *const DominatorAnalysis, a: ?*Inst, b: ?*Inst) bool {
        const ia: *Inst = a orelse return false;
        const ib: *Inst = b orelse return false;
        if (ia == ib) return true;
        const bb_a: *Block = ia.block orelse fatal("dominates: instruction {s} is not in a basic block", .{@tagName(ia.op)});
        const bb_b: *Block = ib.block orelse fatal("dominates: instruction {s} is not in a basic block", .{@tagName(ib.op)});
        if (bb_a != bb_b) return self.tree.dominates(bb_a, bb_b);
        var current: *const Inst = ia;
        var other: *const Inst = ib;
        if (self.tree.isPostDominator()) {
            const t: *const Inst = current;
            current = other;
            other = t;
        }
        if (current.op == .OpLabel) return true;
        var it: ?*Inst = current.next;
        while (it) |c| : (it = c.next) {
            if (c == other) return true;
        }
        return false;
    }

    pub fn strictlyDominates(self: *const DominatorAnalysis, a: ?*const Block, b: ?*const Block) bool {
        const ab: *const Block = a orelse return false;
        const bb: *const Block = b orelse return false;
        return self.tree.strictlyDominates(ab, bb);
    }

    pub fn strictlyDominatesId(self: *const DominatorAnalysis, a: u32, b: u32) bool {
        return self.tree.strictlyDominatesId(a, b);
    }

    pub fn immediateDominator(self: *const DominatorAnalysis, node: ?*const Block) ?*Block {
        const n: *const Block = node orelse return null;
        return self.tree.immediateDominator(n);
    }

    pub fn immediateDominatorId(self: *const DominatorAnalysis, node_id: u32) ?*Block {
        return self.tree.immediateDominatorId(node_id);
    }

    pub fn isReachable(self: *const DominatorAnalysis, node: ?*const Block) bool {
        const n: *const Block = node orelse return false;
        return self.tree.reachableFromRootsId(n.id());
    }

    pub fn isReachableId(self: *const DominatorAnalysis, node_id: u32) bool {
        return self.tree.reachableFromRootsId(node_id);
    }

    pub fn commonDominator(self: *const DominatorAnalysis, b1: ?*Block, b2: ?*Block) ?*Block {
        const x1: *Block = b1 orelse return null;
        const x2: *Block = b2 orelse return null;
        var seen: Set(*Block) = .{};
        var block: ?*Block = x1;
        while (block) |b| {
            if (!seen.insert(b)) break;
            block = self.immediateDominator(b);
        }
        block = x2;
        while (block) |b| {
            if (seen.contains(b)) break;
            block = self.immediateDominator(b);
        }
        return block;
    }
};

pub const PostDominatorAnalysis = DominatorAnalysis;

var g_ctx: ?*Ctx = null;

/// Type analysis: the `Type` of every type id, and the id of every registered `Type`, with structural uniquing.
pub const TypeMgr = struct {
    ctx: *Ctx,
    id_to_type: OrderedMap(u32, *Type) = .{},
    type_to_id: TypeToIdMap = .empty,
    type_pool: TypePoolMap = .empty,
    incomplete_types: List(UnresolvedType) = .{},
    id_to_incomplete_type: Map(u32, *Type) = .{},
    id_to_constant_inst: Map(u32, *const Inst) = .{},

    pub fn init(ctx: *Ctx) *TypeMgr {
        const self = scAllocator().create(TypeMgr) catch oom();
        self.* = .{ .ctx = ctx };
        self.analyzeTypes();
        return self;
    }

    // ---- lookups ----------------------------------------------------------------------------------

    pub fn getType(self: *const TypeMgr, id: u32) ?*Type {
        if (self.id_to_type.get(id)) |t| return t;
        if (self.id_to_incomplete_type.get(id)) |t| return t;
        return null;
    }

    pub fn getTypeAndPointerType(self: *const TypeMgr, id: u32, sc: u32) TypeAndPointer {
        const t: ?*Type = self.getType(id);
        if (t) |ty| return .{ .ty = ty, .ptr = Type.pointer(ty, sc).boxed() };
        return .{ .ty = null, .ptr = null };
    }

    pub fn getId(self: *const TypeMgr, t: ?*const Type) u32 {
        const ty: *const Type = t orelse return 0;
        return self.type_to_id.get(typeKeyOf(ty)) orelse 0;
    }

    pub fn numTypes(self: *const TypeMgr) usize {
        return self.id_to_type.count();
    }

    // ---- analysis of an existing module -------------------------------------------------------------

    fn poolInsert(self: *TypeMgr, t: *Type) *Type {
        const key: TypeKey = typeKeyOf(t);
        const gop: std.HashMapUnmanaged(TypeKey, void, TypeHashCtx, 80).GetOrPutResult = self.type_pool.getOrPut(scAllocator(), key) catch oom();
        if (!gop.found_existing) gop.key_ptr.* = key;
        return @constCast(gop.key_ptr.ty);
    }

    fn mapTypeToId(self: *TypeMgr, t: *const Type, id: u32) void {
        self.type_to_id.put(scAllocator(), typeKeyOf(t), id) catch oom();
    }

    fn analyzeTypes(self: *TypeMgr) void {
        const module: *Module = self.ctx.module;
        for (module.getConstants().items) |inst| self.id_to_constant_inst.put(inst.resultId(), inst);
        for (module.getTypes().items) |inst| _ = self.recordIfTypeDefinition(inst);
        if (self.incomplete_types.len() == 0) return;

        // 1. forward pointers learn their target pointer
        for (self.incomplete_types.items) |u| {
            const t: *Type = u.type.?;
            if (t.data == .forward_pointer) {
                const target: *Type = self.getType(u.id) orelse fatal("TypeMgr: forward pointer target %{d} is not a type", .{u.id});
                // C++: t->AsPointer() is null for a non-pointer target (the asserts vanish in release builds)
                t.data.forward_pointer.pointer = if (target.data == .pointer) target else null;
            }
        }
        // 2. types that mention a forward pointer mention its target pointer instead
        for (self.incomplete_types.items) |u| self.replaceForwardPointers(u.type.?);
        for (self.incomplete_types.items) |*u| {
            if (u.type.?.data == .forward_pointer) u.type = null;
        }
        // 3. merge structurally equal incomplete types
        var restart: bool = true;
        while (restart) {
            restart = false;
            var ia: usize = 0;
            while (ia < self.incomplete_types.len()) : (ia += 1) {
                const type1: *Type = self.incomplete_types.items[ia].type orelse continue;
                var ib: usize = ia + 1;
                while (ib < self.incomplete_types.len()) : (ib += 1) {
                    const type2: *Type = self.incomplete_types.items[ib].type orelse continue;
                    if (type1.isSame(type2)) {
                        self.replaceType(type1, type2);
                        self.incomplete_types.items[ib].type = null;
                        self.id_to_incomplete_type.put(self.incomplete_types.items[ib].id, type1);
                        restart = true;
                    }
                }
            }
        }
        // 4. decorate and register the now complete types
        for (self.incomplete_types.items) |*u| {
            const t: *Type = u.type orelse continue;
            if (t.data == .forward_pointer) continue;
            const decorations: List(*Inst) = self.ctx.getDecorationMgr().getDecorationsFor(u.id, true);
            for (decorations.items) |dec| self.attachDecoration(dec, t);
            u.type = null; // ReleaseType
            const rep: *Type = self.poolInsert(t);
            self.id_to_type.put(u.id, rep);
            self.mapTypeToId(rep, u.id);
            _ = self.id_to_incomplete_type.remove(u.id);
        }
        var it: Map(u32, *Type).Hm.Iterator = self.id_to_incomplete_type.iterator();
        while (it.next()) |kv| self.id_to_type.put(kv.key_ptr.*, kv.value_ptr.*);
    }

    fn replaceForwardPointers(self: *TypeMgr, t: *Type) void {
        _ = self;
        switch (t.data) {
            .array => |*a| {
                if (forwardPointerTarget(a.element)) |tp| a.element = tp;
            },
            .runtime_array => |*a| {
                if (forwardPointerTarget(a.element)) |tp| a.element = tp;
            },
            .struct_ => |*s| {
                for (s.elements.items) |*m| {
                    if (m.*.data == .forward_pointer) m.* = m.*.data.forward_pointer.pointer orelse fatal("TypeMgr: unresolved forward pointer", .{});
                }
            },
            .pointer => |*p| {
                if (p.pointee) |pe| {
                    if (forwardPointerTarget(pe)) |tp| p.pointee = tp;
                }
            },
            .function => |*f| {
                if (forwardPointerTarget(f.ret)) |tp| f.ret = tp;
                for (f.params.items) |*p| {
                    if (p.*.data == .forward_pointer) p.* = p.*.data.forward_pointer.pointer orelse fatal("TypeMgr: unresolved forward pointer", .{});
                }
            },
            else => {},
        }
    }

    fn replaceType(self: *TypeMgr, new_type: *Type, original: *Type) void {
        check(new_type.kind() == original.kind(), "Types must be the same for replacement.");
        for (self.incomplete_types.items) |u| {
            const t: *Type = u.type orelse continue;
            typeSubstituteChildren(t, original, new_type);
        }
    }

    // ---- registration of one type instruction ---------------------------------------------------------

    fn typeOfOperand(self: *TypeMgr, inst: *const Inst, in_index: usize) *Type {
        const id: u32 = inst.getSingleWordInOperand(in_index);
        return self.getType(id) orelse fatal("TypeMgr: %{d} used by {s} is not a known type", .{ id, @tagName(inst.op) });
    }

    fn recordIncomplete(self: *TypeMgr, inst: *const Inst, t: *Type) *Type {
        self.incomplete_types.push(.{ .id = inst.resultId(), .type = t });
        self.id_to_incomplete_type.put(inst.resultId(), t);
        return t;
    }

    fn recordIfTypeDefinition(self: *TypeMgr, inst: *const Inst) ?*Type {
        if (!opIsTypeInst(inst.op)) return null;
        var type_value: Type = undefined;
        switch (inst.op) {
            .OpTypeVoid => type_value = Type.simple(.void_),
            .OpTypeBool => type_value = Type.simple(.bool_),
            .OpTypeInt => type_value = Type.integer(inst.getSingleWordInOperand(0), inst.getSingleWordInOperand(1) != 0),
            .OpTypeFloat => {
                const enc: u32 = if (inst.numInOperands() > 1) inst.getSingleWordInOperand(1) else fp_encoding_max;
                type_value = Type.float(inst.getSingleWordInOperand(0), enc);
            },
            .OpTypeVector => type_value = Type.vector(self.typeOfOperand(inst, 0), inst.getSingleWordInOperand(1)),
            .OpTypeMatrix => type_value = Type.matrix(self.typeOfOperand(inst, 0), inst.getSingleWordInOperand(1)),
            .OpTypeImage => {
                const access: u32 = if (inst.numInOperands() < 8) @intFromEnum(AccessQualifier.ReadOnly) else inst.getSingleWordInOperand(7);
                type_value = Type.image(
                    self.typeOfOperand(inst, 0),
                    inst.getSingleWordInOperand(1),
                    inst.getSingleWordInOperand(2),
                    inst.getSingleWordInOperand(3) == 1,
                    inst.getSingleWordInOperand(4) == 1,
                    inst.getSingleWordInOperand(5),
                    inst.getSingleWordInOperand(6),
                    access,
                );
            },
            .OpTypeSampler => type_value = Type.simple(.sampler),
            .OpTypeSampledImage => type_value = Type.sampledImage(self.typeOfOperand(inst, 0)),
            .OpTypeArray => {
                const length_id: u32 = inst.getSingleWordInOperand(1);
                const length_inst: *const Inst = self.id_to_constant_inst.get(length_id) orelse fatal("TypeMgr: array length %{d} is not a constant", .{length_id});
                var words: List(u32) = .{};
                words.push(ArrayLength.defining_id);
                var spec_id: u32 = 0;
                var has_spec_id: bool = false;
                if (length_inst.op == .OpSpecConstant) {
                    var cap: SpecIdCapture = .{};
                    self.ctx.getDecorationMgr().forEachDecoration(length_id, @intFromEnum(Decoration.SpecId), &cap, SpecIdCapture.f);
                    spec_id = cap.spec_id;
                    has_spec_id = cap.found;
                }
                if (has_spec_id) words.push(spec_id);
                if (length_inst.op == .OpConstant or length_inst.op == .OpSpecConstant) {
                    words.pushSlice(length_inst.getOperand(2).words());
                    words.items[0] = if (has_spec_id) ArrayLength.constant_with_spec_id else ArrayLength.constant;
                } else {
                    words.push(length_id);
                }
                check(words.len() >= 2, "array length info too short");
                const elem_id: u32 = inst.getSingleWordInOperand(0);
                type_value = Type.array(self.typeOfOperand(inst, 0), .{ .id = length_id, .words = words });
                if (self.id_to_incomplete_type.contains(elem_id)) return self.recordIncomplete(inst, type_value.boxed());
            },
            .OpTypeRuntimeArray => {
                type_value = Type.runtimeArray(self.typeOfOperand(inst, 0));
                if (self.id_to_incomplete_type.contains(inst.getSingleWordInOperand(0))) return self.recordIncomplete(inst, type_value.boxed());
            },
            .OpTypeNodePayloadArrayAMDX => {
                type_value = Type.nodePayloadArray(self.typeOfOperand(inst, 0));
                if (self.id_to_incomplete_type.contains(inst.getSingleWordInOperand(0))) return self.recordIncomplete(inst, type_value.boxed());
            },
            .OpTypeStruct => {
                var elems: List(*const Type) = .{};
                var incomplete: bool = false;
                var i: usize = 0;
                while (i < inst.numInOperands()) : (i += 1) {
                    const tid: u32 = inst.getSingleWordInOperand(i);
                    elems.push(self.typeOfOperand(inst, i));
                    if (self.id_to_incomplete_type.contains(tid)) incomplete = true;
                }
                type_value = Type.structOf(elems.items);
                if (incomplete) return self.recordIncomplete(inst, type_value.boxed());
            },
            .OpTypeOpaque => type_value = Type.opaqueNamed(scAllocator().dupe(u8, inst.getInOperand(0).asString()) catch oom()),
            .OpTypePointer => {
                const pointee_id: u32 = inst.getSingleWordInOperand(1);
                type_value = Type.pointer(self.typeOfOperand(inst, 1), inst.getSingleWordInOperand(0));
                if (self.id_to_incomplete_type.contains(pointee_id)) return self.recordIncomplete(inst, type_value.boxed());
                _ = self.id_to_incomplete_type.remove(inst.resultId());
            },
            .OpTypeUntypedPointerKHR => {
                type_value = Type.pointer(null, inst.getSingleWordInOperand(0));
                _ = self.id_to_incomplete_type.remove(inst.resultId());
            },
            .OpTypeFunction => {
                var incomplete: bool = false;
                const ret_id: u32 = inst.getSingleWordInOperand(0);
                if (self.id_to_incomplete_type.contains(ret_id)) incomplete = true;
                const ret: *Type = self.typeOfOperand(inst, 0);
                var params: List(*const Type) = .{};
                var i: usize = 1;
                while (i < inst.numInOperands()) : (i += 1) {
                    const pid: u32 = inst.getSingleWordInOperand(i);
                    params.push(self.typeOfOperand(inst, i));
                    if (self.id_to_incomplete_type.contains(pid)) incomplete = true;
                }
                type_value = Type.function(ret, params.items);
                if (incomplete) return self.recordIncomplete(inst, type_value.boxed());
            },
            .OpTypeEvent => type_value = Type.simple(.event),
            .OpTypeDeviceEvent => type_value = Type.simple(.device_event),
            .OpTypeReserveId => type_value = Type.simple(.reserve_id),
            .OpTypeQueue => type_value = Type.simple(.queue),
            .OpTypePipe => type_value = Type.pipe(inst.getSingleWordInOperand(0)),
            .OpTypeForwardPointer => {
                const target_id: u32 = inst.getSingleWordInOperand(0);
                const t: *Type = Type.forwardPointer(target_id, inst.getSingleWordInOperand(1)).boxed();
                self.incomplete_types.push(.{ .id = target_id, .type = t });
                self.id_to_incomplete_type.put(target_id, t);
                return t;
            },
            .OpTypePipeStorage => type_value = Type.simple(.pipe_storage),
            .OpTypeNamedBarrier => type_value = Type.simple(.named_barrier),
            .OpTypeAccelerationStructureNV => type_value = Type.simple(.acceleration_structure_nv),
            .OpTypeCooperativeMatrixNV => type_value = .{ .data = .{ .cooperative_matrix_nv = .{
                .component = self.typeOfOperand(inst, 0),
                .scope_id = inst.getSingleWordInOperand(1),
                .rows_id = inst.getSingleWordInOperand(2),
                .columns_id = inst.getSingleWordInOperand(3),
            } } },
            .OpTypeCooperativeMatrixKHR => type_value = .{ .data = .{ .cooperative_matrix_khr = .{
                .component = self.typeOfOperand(inst, 0),
                .scope_id = inst.getSingleWordInOperand(1),
                .rows_id = inst.getSingleWordInOperand(2),
                .columns_id = inst.getSingleWordInOperand(3),
                .use_id = inst.getSingleWordInOperand(4),
            } } },
            .OpTypeVectorIdEXT => type_value = .{ .data = .{ .cooperative_vector_nv = .{
                .component = self.typeOfOperand(inst, 0),
                .components = inst.getSingleWordInOperand(1),
            } } },
            .OpTypeRayQueryKHR => type_value = Type.simple(.ray_query_khr),
            .OpTypeHitObjectNV => type_value = Type.simple(.hit_object_nv),
            .OpTypeHitObjectEXT => type_value = Type.simple(.hit_object_ext),
            .OpTypeTensorLayoutNV => type_value = .{ .data = .{ .tensor_layout_nv = .{
                .dim_id = inst.getSingleWordInOperand(0),
                .clamp_mode_id = inst.getSingleWordInOperand(1),
            } } },
            .OpTypeTensorViewNV => {
                var perm: List(u32) = .{};
                var i: usize = 2;
                while (i < inst.numOperands()) : (i += 1) perm.push(inst.getSingleWordOperand(i));
                type_value = .{ .data = .{ .tensor_view_nv = .{
                    .dim_id = inst.getSingleWordInOperand(0),
                    .has_dimensions_id = inst.getSingleWordInOperand(1),
                    .perm = perm,
                } } };
            },
            .OpTypeTensorARM => {
                const element: *Type = self.typeOfOperand(inst, 0);
                const rank: u32 = if (inst.numInOperands() >= 2) inst.getSingleWordInOperand(1) else 0;
                const shape: u32 = if (inst.numInOperands() >= 3) inst.getSingleWordInOperand(2) else 0;
                type_value = .{ .data = .{ .tensor_arm = .{ .element = element, .rank_id = rank, .shape_id = shape } } };
            },
            .OpTypeGraphARM => {
                var io: List(*const Type) = .{};
                var i: usize = 1;
                while (i < inst.numInOperands()) : (i += 1) io.push(self.typeOfOperand(inst, i));
                type_value = .{ .data = .{ .graph_arm = .{ .num_inputs = inst.getSingleWordInOperand(0), .io_types = io } } };
            },
            .OpTypeBufferEXT => type_value = .{ .data = .{ .buffer_ext = .{ .storage_class = inst.getSingleWordInOperand(0) } } },
            else => fatal("Type not handled by the type manager: {s}", .{@tagName(inst.op)}),
        }
        const id: u32 = inst.resultId();
        check(id != 0, "instruction without result id found");
        const t: *Type = type_value.boxed();
        const decorations: List(*Inst) = self.ctx.getDecorationMgr().getDecorationsFor(id, true);
        for (decorations.items) |dec| self.attachDecoration(dec, t);
        const rep: *Type = self.poolInsert(t);
        self.id_to_type.put(id, rep);
        self.mapTypeToId(rep, id);
        return t;
    }

    const SpecIdCapture = struct {
        spec_id: u32 = 0,
        found: bool = false,
        fn f(self: *SpecIdCapture, decoration: *Inst) void {
            check(decoration.op == .OpDecorate, "SpecId decoration is not an OpDecorate");
            self.spec_id = decoration.getSingleWordOperand(2);
            self.found = true;
        }
    };

    pub fn attachDecoration(self: *TypeMgr, inst: *const Inst, t: *Type) void {
        _ = self;
        if (!opIsAnnotation(inst.op)) return;
        switch (inst.op) {
            .OpDecorate, .OpDecorateId => {
                var data: List(u32) = .{};
                var i: usize = 1;
                while (i < inst.numOperands()) : (i += 1) data.pushSlice(inst.getOperand(i).words());
                t.addDecoration(data);
            },
            .OpMemberDecorate => {
                const index: u32 = inst.getSingleWordOperand(1);
                var data: List(u32) = .{};
                var i: usize = 2;
                while (i < inst.numOperands()) : (i += 1) data.push(inst.getSingleWordOperand(i));
                if (t.data == .struct_) t.addMemberDecoration(index, data);
            },
            else => {}, // the C++ asserts (debug builds only); other annotation opcodes are ignored
        }
    }

    // ---- removal ------------------------------------------------------------------------------------

    pub fn removeId(self: *TypeMgr, id: u32) void {
        const type_ptr: *Type = self.id_to_type.get(id) orelse return;
        if (!type_ptr.isUniqueType()) {
            if (self.type_to_id.get(typeKeyOf(type_ptr))) |mapped| {
                if (mapped == id) {
                    var found: bool = false;
                    for (self.id_to_type.keys(), self.id_to_type.values()) |k, v| {
                        if (k != id and v.isSame(type_ptr)) {
                            _ = self.type_to_id.remove(typeKeyOf(type_ptr));
                            self.mapTypeToId(v, k);
                            found = true;
                            break;
                        }
                    }
                    if (!found) _ = self.type_to_id.remove(typeKeyOf(type_ptr));
                }
            }
        } else {
            _ = self.type_to_id.remove(typeKeyOf(type_ptr));
        }
        _ = self.id_to_type.orderedRemove(id);
    }

    // ---- rebuilding a type inside the pool -----------------------------------------------------------

    fn rebuildChild(self: *TypeMgr, child: *const Type) *const Type {
        return self.rebuildType(self.getId(child), child);
    }

    /// TypeManager::RebuildType: returns the pooled type equal to `t` (with children pooled too).
    fn rebuildType(self: *TypeMgr, type_id: u32, t: *const Type) *Type {
        if (self.getType(type_id)) |pool_ty| {
            if (type_id != 0) return pool_ty;
        }
        var rebuilt: *Type = undefined;
        switch (t.data) {
            .void_, .bool_, .integer, .float, .sampler, .opaque_, .event, .device_event, .reserve_id, .queue, .pipe, .pipe_storage, .named_barrier, .acceleration_structure_nv, .ray_query_khr, .hit_object_nv, .hit_object_ext => {
                return self.poolInsert(t.clone());
            },
            .vector => |a| rebuilt = Type.vector(self.rebuildChild(a.element), a.count).boxed(),
            .matrix => |a| rebuilt = Type.matrix(self.rebuildChild(a.element), a.count).boxed(),
            .image => |a| rebuilt = Type.image(self.rebuildChild(a.sampled_type), a.dim, a.depth, a.arrayed, a.ms, a.sampled, a.format, a.access).boxed(),
            .sampled_image => |a| rebuilt = Type.sampledImage(self.rebuildChild(a.image)).boxed(),
            .array => |a| rebuilt = Type.array(self.rebuildChild(a.element), .{ .id = a.length.id, .words = cloneWords(a.length.words.items) }).boxed(),
            .runtime_array => |a| rebuilt = Type.runtimeArray(self.rebuildChild(a.element)).boxed(),
            .node_payload_array_amdx => |a| rebuilt = Type.nodePayloadArray(self.rebuildChild(a.element)).boxed(),
            .struct_ => |*s| {
                var subtypes: List(*const Type) = .{};
                for (s.elements.items) |e| subtypes.push(self.rebuildChild(e));
                rebuilt = Type.structOf(subtypes.items).boxed();
                for (s.member_decorations.keys(), s.member_decorations.values()) |index, list| {
                    for (list.items) |d| rebuilt.addMemberDecoration(index, cloneWords(d.items));
                }
            },
            .pointer => |p| {
                if (p.pointee) |pe| {
                    rebuilt = Type.pointer(self.rebuildChild(pe), p.storage_class).boxed();
                } else {
                    rebuilt = Type.pointer(null, p.storage_class).boxed();
                }
            },
            .function => |*f| {
                var params: List(*const Type) = .{};
                for (f.params.items) |p| params.push(self.rebuildChild(p));
                rebuilt = Type.function(self.rebuildChild(f.ret), params.items).boxed();
            },
            .forward_pointer => |fp| {
                var nt = Type.forwardPointer(fp.target_id, fp.storage_class);
                if (fp.pointer) |tp| nt.data.forward_pointer.pointer = self.rebuildChild(tp);
                rebuilt = nt.boxed();
            },
            .cooperative_matrix_nv => |a| rebuilt = (Type{ .data = .{ .cooperative_matrix_nv = .{
                .component = self.rebuildChild(a.component),
                .scope_id = a.scope_id,
                .rows_id = a.rows_id,
                .columns_id = a.columns_id,
            } } }).boxed(),
            .cooperative_matrix_khr => |a| rebuilt = (Type{ .data = .{ .cooperative_matrix_khr = .{
                .component = self.rebuildChild(a.component),
                .scope_id = a.scope_id,
                .rows_id = a.rows_id,
                .columns_id = a.columns_id,
                .use_id = a.use_id,
            } } }).boxed(),
            .cooperative_vector_nv => |a| rebuilt = (Type{ .data = .{ .cooperative_vector_nv = .{
                .component = self.rebuildChild(a.component),
                .components = a.components,
            } } }).boxed(),
            .tensor_layout_nv => |a| rebuilt = (Type{ .data = .{ .tensor_layout_nv = a } }).boxed(),
            .tensor_view_nv => |*a| rebuilt = (Type{ .data = .{ .tensor_view_nv = .{
                .dim_id = a.dim_id,
                .has_dimensions_id = a.has_dimensions_id,
                .perm = cloneWords(a.perm.items),
            } } }).boxed(),
            .tensor_arm => |a| rebuilt = (Type{ .data = .{ .tensor_arm = .{
                .element = self.rebuildChild(a.element),
                .rank_id = a.rank_id,
                .shape_id = a.shape_id,
            } } }).boxed(),
            .graph_arm => |*a| {
                var io: List(*const Type) = .{};
                for (a.io_types.items) |x| io.push(self.rebuildChild(x));
                rebuilt = (Type{ .data = .{ .graph_arm = .{ .num_inputs = a.num_inputs, .io_types = io } } }).boxed();
            },
            .buffer_ext => |a| rebuilt = (Type{ .data = .{ .buffer_ext = a } }).boxed(),
        }
        for (t.decorations.items) |d| rebuilt.addDecoration(cloneWords(d.items));
        return self.poolInsert(rebuilt);
    }

    pub fn registerType(self: *TypeMgr, id: u32, t: *const Type) void {
        const rebuilt: *Type = self.rebuildType(id, t);
        check(rebuilt.isSame(t), "TypeMgr.registerType: rebuilt type differs");
        self.id_to_type.put(id, rebuilt);
        if (self.getId(rebuilt) == 0) self.mapTypeToId(rebuilt, id);
    }

    pub fn getRegisteredType(self: *TypeMgr, t: *const Type) ?*Type {
        const id: u32 = self.getTypeInstruction(t);
        if (id == 0) return null;
        return self.getType(id);
    }

    // ---- creating declarations ---------------------------------------------------------------------

    fn idOp(v: u32) Operand {
        return Operand.id(.IdRef, v);
    }

    fn litOp(v: u32) Operand {
        return Operand.single(.LiteralInteger, v);
    }

    /// TypeManager::GetTypeInstruction: the id of the declaration of `t`, creating it (and its decorations) when
    /// the module has none yet. Returns 0 only when a child type cannot be declared.
    pub fn getTypeInstruction(self: *TypeMgr, t: *const Type) u32 {
        var id: u32 = self.getId(t);
        if (id != 0) return id;
        id = self.ctx.takeNextId();
        if (id == 0) return 0;
        self.registerType(id, t);
        var inst: *Inst = undefined;
        switch (t.data) {
            .void_ => inst = Inst.make(.OpTypeVoid, 0, id, &.{}),
            .bool_ => inst = Inst.make(.OpTypeBool, 0, id, &.{}),
            .sampler => inst = Inst.make(.OpTypeSampler, 0, id, &.{}),
            .event => inst = Inst.make(.OpTypeEvent, 0, id, &.{}),
            .device_event => inst = Inst.make(.OpTypeDeviceEvent, 0, id, &.{}),
            .reserve_id => inst = Inst.make(.OpTypeReserveId, 0, id, &.{}),
            .queue => inst = Inst.make(.OpTypeQueue, 0, id, &.{}),
            .pipe_storage => inst = Inst.make(.OpTypePipeStorage, 0, id, &.{}),
            .named_barrier => inst = Inst.make(.OpTypeNamedBarrier, 0, id, &.{}),
            .acceleration_structure_nv => inst = Inst.make(.OpTypeAccelerationStructureNV, 0, id, &.{}),
            .ray_query_khr => inst = Inst.make(.OpTypeRayQueryKHR, 0, id, &.{}),
            .hit_object_nv => inst = Inst.make(.OpTypeHitObjectNV, 0, id, &.{}),
            .hit_object_ext => inst = Inst.make(.OpTypeHitObjectEXT, 0, id, &.{}),
            .integer => |a| inst = Inst.make(.OpTypeInt, 0, id, &.{ litOp(a.width), litOp(if (a.is_signed) 1 else 0) }),
            .float => |a| {
                if (a.encoding == fp_encoding_max) {
                    inst = Inst.make(.OpTypeFloat, 0, id, &.{litOp(a.width)});
                } else {
                    inst = Inst.make(.OpTypeFloat, 0, id, &.{ litOp(a.width), Operand.single(.FPEncoding, a.encoding) });
                }
            },
            .vector => |a| {
                const sub: u32 = self.getTypeInstruction(a.element);
                if (sub == 0) return 0;
                inst = Inst.make(.OpTypeVector, 0, id, &.{ idOp(sub), litOp(a.count) });
            },
            .matrix => |a| {
                const sub: u32 = self.getTypeInstruction(a.element);
                if (sub == 0) return 0;
                inst = Inst.make(.OpTypeMatrix, 0, id, &.{ idOp(sub), litOp(a.count) });
            },
            .image => |a| {
                const sub: u32 = self.getTypeInstruction(a.sampled_type);
                if (sub == 0) return 0;
                inst = Inst.make(.OpTypeImage, 0, id, &.{
                    idOp(sub),
                    Operand.single(.Dim, a.dim),
                    litOp(a.depth),
                    litOp(if (a.arrayed) 1 else 0),
                    litOp(if (a.ms) 1 else 0),
                    litOp(a.sampled),
                    Operand.single(.ImageFormat, a.format),
                    Operand.single(.AccessQualifier, a.access),
                });
            },
            .sampled_image => |a| {
                const sub: u32 = self.getTypeInstruction(a.image);
                if (sub == 0) return 0;
                inst = Inst.make(.OpTypeSampledImage, 0, id, &.{idOp(sub)});
            },
            .array => |a| {
                const sub: u32 = self.getTypeInstruction(a.element);
                if (sub == 0) return 0;
                inst = Inst.make(.OpTypeArray, 0, id, &.{ idOp(sub), idOp(a.length.id) });
            },
            .runtime_array => |a| {
                const sub: u32 = self.getTypeInstruction(a.element);
                if (sub == 0) return 0;
                inst = Inst.make(.OpTypeRuntimeArray, 0, id, &.{idOp(sub)});
            },
            .node_payload_array_amdx => |a| {
                const sub: u32 = self.getTypeInstruction(a.element);
                if (sub == 0) return 0;
                inst = Inst.make(.OpTypeNodePayloadArrayAMDX, 0, id, &.{idOp(sub)});
            },
            .struct_ => |*s| {
                var ops: List(Operand) = .{};
                for (s.elements.items) |e| {
                    const mid: u32 = self.getTypeInstruction(e);
                    if (mid == 0) return 0;
                    ops.push(idOp(mid));
                }
                inst = Inst.make(.OpTypeStruct, 0, id, ops.items);
            },
            .opaque_ => |a| inst = Inst.make(.OpTypeOpaque, 0, id, &.{Operand.string(a.name)}),
            .pointer => |p| {
                if (p.pointee == null) {
                    inst = Inst.make(.OpTypeUntypedPointerKHR, 0, id, &.{Operand.single(.StorageClass, p.storage_class)});
                } else {
                    const sub: u32 = self.getTypeInstruction(p.pointee.?);
                    inst = Inst.make(.OpTypePointer, 0, id, &.{ Operand.single(.StorageClass, p.storage_class), idOp(sub) });
                }
            },
            .function => |*f| {
                var ops: List(Operand) = .{};
                const rid: u32 = self.getTypeInstruction(f.ret);
                if (rid == 0) return 0;
                ops.push(idOp(rid));
                for (f.params.items) |p| {
                    const pid: u32 = self.getTypeInstruction(p);
                    if (pid == 0) return 0;
                    ops.push(idOp(pid));
                }
                inst = Inst.make(.OpTypeFunction, 0, id, ops.items);
            },
            .pipe => |a| inst = Inst.make(.OpTypePipe, 0, id, &.{Operand.single(.AccessQualifier, a.access)}),
            .forward_pointer => |a| inst = Inst.make(.OpTypeForwardPointer, 0, 0, &.{ idOp(a.target_id), Operand.single(.StorageClass, a.storage_class) }),
            .cooperative_matrix_nv => |a| {
                const comp: u32 = self.getTypeInstruction(a.component);
                if (comp == 0) return 0;
                inst = Inst.make(.OpTypeCooperativeMatrixNV, 0, id, &.{ idOp(comp), Operand.id(.IdScope, a.scope_id), idOp(a.rows_id), idOp(a.columns_id) });
            },
            .cooperative_matrix_khr => |a| {
                const comp: u32 = self.getTypeInstruction(a.component);
                if (comp == 0) return 0;
                inst = Inst.make(.OpTypeCooperativeMatrixKHR, 0, id, &.{ idOp(comp), Operand.id(.IdScope, a.scope_id), idOp(a.rows_id), idOp(a.columns_id), idOp(a.use_id) });
            },
            .tensor_layout_nv => |a| inst = Inst.make(.OpTypeTensorLayoutNV, 0, id, &.{ idOp(a.dim_id), idOp(a.clamp_mode_id) }),
            .tensor_view_nv => |*a| {
                var ops: List(Operand) = .{};
                ops.push(idOp(a.dim_id));
                ops.push(idOp(a.has_dimensions_id));
                for (a.perm.items) |p| ops.push(idOp(p));
                inst = Inst.make(.OpTypeTensorViewNV, 0, id, ops.items);
            },
            .cooperative_vector_nv => |a| {
                const comp: u32 = self.getTypeInstruction(a.component);
                if (comp == 0) return 0;
                inst = Inst.make(.OpTypeVectorIdEXT, 0, id, &.{ idOp(comp), idOp(a.components) });
            },
            .tensor_arm => |a| {
                const elem: u32 = self.getTypeInstruction(a.element);
                if (elem == 0) return 0;
                if (a.rank_id != 0) {
                    if (a.shape_id != 0) {
                        inst = Inst.make(.OpTypeTensorARM, 0, id, &.{ idOp(elem), idOp(a.rank_id), idOp(a.shape_id) });
                    } else {
                        inst = Inst.make(.OpTypeTensorARM, 0, id, &.{ idOp(elem), idOp(a.rank_id) });
                    }
                } else {
                    inst = Inst.make(.OpTypeTensorARM, 0, id, &.{idOp(elem)});
                }
            },
            .graph_arm => |*a| {
                var ops: List(Operand) = .{};
                ops.push(litOp(a.num_inputs));
                for (a.io_types.items) |x| ops.push(idOp(self.getTypeInstruction(x)));
                inst = Inst.make(.OpTypeGraphARM, 0, id, ops.items);
            },
            .buffer_ext => |a| inst = Inst.make(.OpTypeBufferEXT, 0, id, &.{Operand.single(.StorageClass, a.storage_class)}),
        }
        self.ctx.addType(inst);
        self.ctx.analyzeDefUse(self.ctx.module.types_values.last.?);
        self.attachDecorations(id, t);
        return id;
    }

    /// TypeManager::FindPointerToType: an existing OpTypePointer with this pointee/storage class, else a new one.
    pub fn findPointerToType(self: *TypeMgr, type_id: u32, storage_class: u32) u32 {
        const pointee: ?*Type = self.getType(type_id);
        const pointer_ty = Type.pointer(pointee, storage_class);
        var it: ?*Inst = self.ctx.module.types_values.first;
        while (it) |ti| : (it = ti.next) {
            if (ti.op == .OpTypePointer and ti.getSingleWordOperand(2) == type_id and ti.getSingleWordOperand(1) == storage_class) return ti.resultId();
        }
        const result_id: u32 = self.ctx.takeNextId();
        if (result_id == 0) return 0;
        const inst: *Inst = Inst.make(.OpTypePointer, 0, result_id, &.{ Operand.single(.StorageClass, storage_class), idOp(type_id) });
        self.ctx.addType(inst);
        self.ctx.getTypeMgr().registerType(result_id, &pointer_ty);
        return result_id;
    }

    fn attachDecorations(self: *TypeMgr, id: u32, t: *const Type) void {
        for (t.decorations.items) |d| self.createDecoration(id, d.items, false, 0);
        if (t.data == .struct_) {
            const s: *const TyStruct = &t.data.struct_;
            for (s.member_decorations.keys(), s.member_decorations.values()) |element, list| {
                for (list.items) |d| self.createDecoration(id, d.items, true, element);
            }
        }
    }

    fn createDecoration(self: *TypeMgr, target: u32, decoration: []const u32, is_member: bool, element: u32) void {
        var ops: List(Operand) = .{};
        ops.push(idOp(target));
        if (is_member) ops.push(litOp(element));
        ops.push(Operand.single(.Decoration, decoration[0]));
        for (decoration[1..]) |w| ops.push(litOp(w));
        const inst: *Inst = Inst.make(if (is_member) .OpMemberDecorate else .OpDecorate, 0, 0, ops.items);
        self.ctx.addAnnotationInst(inst);
        self.ctx.getDefUseMgr().analyzeInstUse(self.ctx.module.annotations.last.?);
    }

    pub fn getMemberType(self: *TypeMgr, parent: *const Type, access_chain: []const u32) *const Type {
        _ = self;
        var p: *const Type = parent;
        for (access_chain) |element_index| {
            p = switch (p.data) {
                .struct_ => |*s| s.elements.items[element_index],
                .array => |a| a.element,
                .runtime_array => |a| a.element,
                .vector => |a| a.element,
                .matrix => |a| a.element,
                else => fatal("Trying to get a member of a type without members.", .{}),
            };
        }
        return p;
    }

    // ---- convenience getters (each registers the type in the module when it is missing) --------------------

    pub fn getIntType(self: *TypeMgr, bit_width: u32, is_signed: bool) ?*Type {
        const t = Type.integer(bit_width, is_signed);
        return self.getRegisteredType(&t);
    }
    pub fn getUIntType(self: *TypeMgr) ?*Type {
        return self.getIntType(32, false);
    }
    pub fn getUIntTypeId(self: *TypeMgr) u32 {
        return self.getTypeInstruction(self.getUIntType().?);
    }
    pub fn getSIntType(self: *TypeMgr) ?*Type {
        return self.getIntType(32, true);
    }
    pub fn getSIntTypeId(self: *TypeMgr) u32 {
        return self.getTypeInstruction(self.getSIntType().?);
    }
    pub fn getFloatType(self: *TypeMgr) ?*Type {
        const t = Type.float(32, fp_encoding_max);
        return self.getRegisteredType(&t);
    }
    pub fn getFloatTypeId(self: *TypeMgr) u32 {
        return self.getTypeInstruction(self.getFloatType().?);
    }
    pub fn getDoubleType(self: *TypeMgr) ?*Type {
        const t = Type.float(64, fp_encoding_max);
        return self.getRegisteredType(&t);
    }
    pub fn getDoubleTypeId(self: *TypeMgr) u32 {
        return self.getTypeInstruction(self.getDoubleType().?);
    }
    pub fn getUIntVectorType(self: *TypeMgr, size: u32) ?*Type {
        const t = Type.vector(self.getUIntType().?, size);
        return self.getRegisteredType(&t);
    }
    pub fn getUIntVectorTypeId(self: *TypeMgr, size: u32) u32 {
        return self.getTypeInstruction(self.getUIntVectorType(size).?);
    }
    pub fn getSIntVectorType(self: *TypeMgr, size: u32) ?*Type {
        const t = Type.vector(self.getSIntType().?, size);
        return self.getRegisteredType(&t);
    }
    pub fn getSIntVectorTypeId(self: *TypeMgr, size: u32) u32 {
        return self.getTypeInstruction(self.getSIntVectorType(size).?);
    }
    pub fn getFloatVectorType(self: *TypeMgr, size: u32) ?*Type {
        const t = Type.vector(self.getFloatType().?, size);
        return self.getRegisteredType(&t);
    }
    pub fn getFloatVectorTypeId(self: *TypeMgr, size: u32) u32 {
        return self.getTypeInstruction(self.getFloatVectorType(size).?);
    }
    pub fn getBoolType(self: *TypeMgr) ?*Type {
        const t = Type.simple(.bool_);
        return self.getRegisteredType(&t);
    }
    pub fn getBoolTypeId(self: *TypeMgr) u32 {
        const b: *Type = self.getBoolType() orelse return 0;
        return self.getTypeInstruction(b);
    }
    pub fn getVoidType(self: *TypeMgr) ?*Type {
        const t = Type.simple(.void_);
        return self.getRegisteredType(&t);
    }
    pub fn getVoidTypeId(self: *TypeMgr) u32 {
        return self.getTypeInstruction(self.getVoidType().?);
    }
};

/// An interned constant value (null, bool, int, float or composite) with its type; compare by pointer.
pub const Constant = struct {
    ty: *const Type,
    kind: ConstKind,
    words: List(u32) = .{}, // bool_/int/float
    components: List(*const Constant) = .{}, // struct_/vector/matrix/array/tensor

    pub fn isScalar(self: *const Constant) bool {
        return self.kind == .bool_ or self.kind == .int or self.kind == .float;
    }

    pub fn isComposite(self: *const Constant) bool {
        return switch (self.kind) {
            .struct_, .vector, .matrix, .array, .tensor => true,
            else => false,
        };
    }

    pub fn isNull(self: *const Constant) bool {
        return self.kind == .null_;
    }

    pub fn boolValue(self: *const Constant) bool {
        check(self.kind == .bool_, "Constant.boolValue: not a bool constant");
        return self.words.items[0] != 0;
    }

    pub fn isZero(self: *const Constant) bool {
        if (self.kind == .null_) return true;
        if (self.isScalar()) {
            for (self.words.items) |w| {
                if (w != 0) return false;
            }
            return true;
        }
        for (self.components.items) |c| {
            if (!c.isZero()) return false;
        }
        return true;
    }

    pub fn getU32BitValue(self: *const Constant) u32 {
        check(self.words.len() >= 1, "Constant.getU32BitValue: no words"); // the C++ only asserts size()==1 (release: words()[0])
        return self.words.items[0];
    }

    pub fn getU64BitValue(self: *const Constant) u64 {
        check(self.words.len() == 2, "Constant.getU64BitValue: expected two words");
        return (@as(u64, self.words.items[1]) << 32) | @as(u64, self.words.items[0]);
    }

    pub fn getS32BitValue(self: *const Constant) i32 {
        return @bitCast(self.getU32BitValue());
    }

    pub fn getS64BitValue(self: *const Constant) i64 {
        return @bitCast(self.getU64BitValue());
    }

    fn floatWidth(self: *const Constant) u32 {
        const f: *const TyFloat = self.ty.as(.float) orelse fatal("Constant: not a floating point constant", .{});
        return f.width;
    }

    fn intWidth(self: *const Constant) u32 {
        const i: *const TyInteger = self.ty.as(.integer) orelse fatal("Constant: not an integer constant", .{});
        return i.width;
    }

    pub fn getFloat(self: *const Constant) f32 {
        check(self.floatWidth() == 32, "Constant.getFloat: not a 32-bit float");
        if (self.kind == .float) return @bitCast(self.words.items[0]);
        check(self.kind == .null_, "Must be a floating point constant.");
        return 0.0;
    }

    pub fn getDouble(self: *const Constant) f64 {
        check(self.floatWidth() == 64, "Constant.getDouble: not a 64-bit float");
        if (self.kind == .float) return @bitCast((@as(u64, self.words.items[1]) << 32) | @as(u64, self.words.items[0]));
        check(self.kind == .null_, "Must be a floating point constant.");
        return 0.0;
    }

    pub fn getValueAsDouble(self: *const Constant) f64 {
        if (self.floatWidth() == 32) return self.getFloat();
        check(self.floatWidth() == 64, "Constant.getValueAsDouble: unsupported float width");
        return self.getDouble();
    }

    pub fn getU32(self: *const Constant) u32 {
        _ = self.intWidth(); // must be an integer type; the width is only asserted in the C++
        if (self.kind == .int) return self.getU32BitValue();
        check(self.kind == .null_, "Must be an integer constant.");
        return 0;
    }

    pub fn getU64(self: *const Constant) u64 {
        check(self.intWidth() == 64, "Constant.getU64: not a 64-bit integer");
        if (self.kind == .int) return self.getU64BitValue();
        check(self.kind == .null_, "Must be an integer constant.");
        return 0;
    }

    pub fn getS32(self: *const Constant) i32 {
        _ = self.intWidth(); // must be an integer type; the width is only asserted in the C++
        if (self.kind == .int) return self.getS32BitValue();
        check(self.kind == .null_, "Must be an integer constant.");
        return 0;
    }

    pub fn getS64(self: *const Constant) i64 {
        check(self.intWidth() == 64, "Constant.getS64: not a 64-bit integer");
        if (self.kind == .int) return self.getS64BitValue();
        check(self.kind == .null_, "Must be an integer constant.");
        return 0;
    }

    pub fn getZeroExtendedValue(self: *const Constant) u64 {
        const width: u32 = self.intWidth();
        check(width <= 64, "Constant.getZeroExtendedValue: wider than 64 bits");
        if (self.kind == .int) return if (width <= 32) self.getU32BitValue() else self.getU64BitValue();
        check(self.kind == .null_, "Must be an integer constant.");
        return 0;
    }

    pub fn getSignExtendedValue(self: *const Constant) i64 {
        const width: u32 = self.intWidth();
        check(width <= 64, "Constant.getSignExtendedValue: wider than 64 bits");
        if (self.kind == .int) return if (width <= 32) @as(i64, self.getS32BitValue()) else self.getS64BitValue();
        check(self.kind == .null_, "Must be an integer constant.");
        return 0;
    }

    /// Constant::GetVectorComponents: the components of a vector constant (a null vector yields null scalars).
    pub fn getVectorComponents(self: *const Constant, const_mgr: *ConstMgr) List(*const Constant) {
        var out: List(*const Constant) = .{};
        const vt: *const TyVector = self.ty.as(.vector) orelse fatal("Constant.getVectorComponents: not a vector type", .{});
        if (self.kind == .vector) {
            var i: u32 = 0;
            while (i < vt.count) : (i += 1) out.push(self.components.items[i]);
        } else {
            const element_null: *const Constant = const_mgr.getConstant(vt.element, &.{}) orelse fatal("Constant.getVectorComponents: no null element", .{});
            var i: u32 = 0;
            while (i < vt.count) : (i += 1) out.push(element_null);
        }
        return out;
    }
};

const ConstHashCtx = struct {
    pub fn hash(_: ConstHashCtx, c: *const Constant) u64 {
        var h: std.hash.Wyhash = std.hash.Wyhash.init(0);
        h.update(std.mem.asBytes(&@intFromPtr(c.ty)));
        switch (c.kind) {
            .null_ => h.update(&.{ 0, 0, 0, 0 }),
            .bool_, .int, .float => h.update(std.mem.sliceAsBytes(c.words.items)),
            else => {
                for (c.components.items) |x| h.update(std.mem.asBytes(&@intFromPtr(x)));
            },
        }
        return h.final();
    }

    pub fn eql(_: ConstHashCtx, a: *const Constant, b: *const Constant) bool {
        if (a.ty != b.ty) return false;
        if (a.isScalar()) return b.isScalar() and std.mem.eql(u32, a.words.items, b.words.items);
        if (a.isComposite()) return b.isComposite() and std.mem.eql(*const Constant, a.components.items, b.components.items);
        return b.isNull();
    }
};
const ConstPoolMap = std.HashMapUnmanaged(*const Constant, void, ConstHashCtx, 80);

/// Constant analysis: the constant every constant id declares, and the ids of every constant value.
pub const ConstMgr = struct {
    ctx: *Ctx,
    /// id -> the constant the id declares (C++ unordered_map); ids are small integers, so a dense table indexed by id (null: none)
    id_to_const_val: List(?*const Constant) = .{},
    const_val_to_id: Map(*const Constant, List(u32)) = .{}, // std::multimap<const Constant*, uint32_t>: insertion order per key
    const_pool: ConstPoolMap = .empty,

    pub fn init(ctx: *Ctx) *ConstMgr {
        const self = scAllocator().create(ConstMgr) catch oom();
        self.* = .{ .ctx = ctx };
        self.id_to_const_val.growFilled(ctx.module.header.bound, null);
        for (ctx.module.getConstants().items) |inst| _ = self.mapInst(inst);
        return self;
    }

    pub fn getType(self: *ConstMgr, inst: *const Inst) ?*Type {
        return self.ctx.getTypeMgr().getType(inst.typeId());
    }

    // ---- lookups ----------------------------------------------------------------------------------

    pub fn findDeclaredConstant(self: *const ConstMgr, id: u32) ?*const Constant {
        if (id >= self.id_to_const_val.len()) return null;
        return self.id_to_const_val.items[id];
    }

    pub fn findConstant(self: *const ConstMgr, c: *const Constant) ?*const Constant {
        const key: *const Constant = self.const_pool.getKey(c) orelse return null;
        return key;
    }

    /// FindDeclaredConstant(c, type_id): the id of a declaration of `c` (of result type `type_id` unless it is 0), or 0.
    pub fn findDeclaredConstantId(self: *ConstMgr, c_in: ?*const Constant, type_id: u32) u32 {
        const c0: *const Constant = c_in orelse return 0;
        const c: *const Constant = self.findConstant(c0) orelse return 0;
        const ids: List(u32) = self.const_val_to_id.get(c) orelse return 0;
        for (ids.items) |id| {
            const const_def: *Inst = self.ctx.getDefUseMgr().getDef(id) orelse fatal("ConstMgr: constant %{d} has no definition", .{id});
            if (type_id == 0 or const_def.typeId() == type_id) return id;
        }
        return 0;
    }

    pub fn getConstantsFromIds(self: *const ConstMgr, ids: []const u32) List(*const Constant) {
        var out: List(*const Constant) = .{};
        for (ids) |id| {
            if (self.findDeclaredConstant(id)) |c| {
                out.push(c);
            } else {
                return .{};
            }
        }
        return out;
    }

    /// One entry per in-operand: the declared constant when the operand is a plain id (IdRef), else null.
    pub fn getOperandConstants(self: *const ConstMgr, inst: *const Inst) List(?*const Constant) {
        var out: List(?*const Constant) = .{};
        for (0..inst.numInOperands()) |i| {
            const o: *Operand = inst.getInOperand(i);
            if (o.kind != .IdRef) {
                out.push(null);
            } else {
                out.push(self.findDeclaredConstant(o.words()[0]));
            }
        }
        return out;
    }

    // ---- registration ---------------------------------------------------------------------------------

    pub fn registerConstant(self: *ConstMgr, cst: *Constant) *const Constant {
        const gop: std.HashMapUnmanaged(*const Constant, void, ConstHashCtx, 80).GetOrPutResult = self.const_pool.getOrPut(scAllocator(), cst) catch oom();
        if (!gop.found_existing) gop.key_ptr.* = cst;
        return gop.key_ptr.*;
    }

    pub fn mapConstantToInst(self: *ConstMgr, c: *const Constant, inst: *Inst) void {
        const rid: u32 = inst.resultId();
        if (self.findDeclaredConstant(rid) != null) return;
        self.id_to_const_val.growFilled(@as(usize, rid) + 1, null);
        self.id_to_const_val.items[rid] = c;
        const ids: Map(*const Constant, List(u32)).GetOrPutResult = self.const_val_to_id.getOrPut(c);
        if (!ids.found_existing) ids.value_ptr.* = .{};
        ids.value_ptr.push(inst.resultId());
    }

    pub fn mapInst(self: *ConstMgr, inst: *Inst) bool {
        if (self.getConstantFromInst(inst)) |c| {
            self.mapConstantToInst(c, inst);
            return true;
        }
        return false;
    }

    pub fn removeId(self: *ConstMgr, id: u32) void {
        const c: *const Constant = self.findDeclaredConstant(id) orelse return;
        _ = self.const_val_to_id.remove(c);
        self.id_to_const_val.items[id] = null;
    }

    // ---- creation ---------------------------------------------------------------------------------------

    fn createConstant(self: *ConstMgr, ty: *const Type, words: []const u32) ?*Constant {
        if (words.len == 0) return newConstant(ty, .null_, &.{}, &.{});
        switch (ty.data) {
            .bool_ => {
                check(words.len == 1, "Bool constant should be declared with one operand");
                return newConstant(ty, .bool_, &.{if (words[0] != 0) 1 else 0}, &.{});
            },
            .integer => return newConstant(ty, .int, words, &.{}),
            .float => return newConstant(ty, .float, words, &.{}),
            .vector => {
                const comps: List(*const Constant) = self.getConstantsFromIds(words);
                if (comps.len() == 0) return null;
                for (comps.items) |c| {
                    if (!(c.ty.data == .bool_ or c.ty.data == .integer or c.ty.data == .float)) return null;
                }
                const component_type: *const Type = comps.items[0].ty;
                for (comps.items) |c| {
                    if (c.ty != component_type) return null;
                }
                return newConstant(ty, .vector, &.{}, comps.items);
            },
            .matrix => {
                const comps: List(*const Constant) = self.getConstantsFromIds(words);
                if (comps.len() == 0) return null;
                return newConstant(ty, .matrix, &.{}, comps.items);
            },
            .struct_ => {
                const comps: List(*const Constant) = self.getConstantsFromIds(words);
                if (comps.len() == 0) return null;
                return newConstant(ty, .struct_, &.{}, comps.items);
            },
            .array => {
                const comps: List(*const Constant) = self.getConstantsFromIds(words);
                if (comps.len() == 0) return null;
                return newConstant(ty, .array, &.{}, comps.items);
            },
            .tensor_arm => {
                const comps: List(*const Constant) = self.getConstantsFromIds(words);
                if (comps.len() == 0) return null;
                return newConstant(ty, .tensor, &.{}, comps.items);
            },
            else => return null,
        }
    }

    fn newConstant(ty: *const Type, k: ConstKind, words: []const u32, comps: []const *const Constant) *Constant {
        const c = scAllocator().create(Constant) catch oom();
        c.* = .{ .ty = ty, .kind = k };
        c.words.pushSlice(words);
        c.components.pushSlice(comps);
        return c;
    }

    /// ConstantManager::GetConstant: `words` are literal words for scalars and ids of declared constants for composites.
    pub fn getConstant(self: *ConstMgr, ty: ?*const Type, words: []const u32) ?*const Constant {
        const t: *const Type = ty orelse return null;
        const cst: *Constant = self.createConstant(t, words) orelse return null;
        return self.registerConstant(cst);
    }

    pub fn getConstantFromInst(self: *ConstMgr, inst: *const Inst) ?*const Constant {
        var words: List(u32) = .{};
        var i: usize = 0;
        while (i < inst.numInOperands()) : (i += 1) words.pushSlice(inst.getInOperand(i).words());
        const ty: ?*Type = self.getType(inst);
        switch (inst.op) {
            .OpConstantTrue => words.push(1),
            .OpConstantFalse => words.push(0),
            .OpConstantNull, .OpConstant, .OpConstantComposite, .OpSpecConstantComposite => {},
            .OpConstantCompositeReplicateEXT, .OpSpecConstantCompositeReplicateEXT => {
                const value: u32 = words.items[0];
                const t: *Type = ty orelse fatal("ConstMgr: replicated composite without a type", .{});
                var component_count: u64 = t.numberOfComponents();
                if (t.as(.tensor_arm)) |tensor_type| {
                    if (tensor_type.shape_id == 0) return null;
                    const shape_inst: *Inst = self.ctx.getDefUseMgr().getDef(tensor_type.shape_id) orelse return null;
                    const shape_cst: *const Constant = self.getConstantFromInst(shape_inst) orelse return null;
                    if (shape_cst.kind != .array) return null;
                    const shape_components: []*const Constant = shape_cst.components.items;
                    if (shape_components.len == 0) return null;
                    const outer: *const Constant = shape_components[0];
                    if (outer.kind != .int) return null;
                    component_count = outer.getZeroExtendedValue();
                }
                if (component_count == 0) return null;
                words.clear();
                var k: u64 = 0;
                while (k < component_count) : (k += 1) words.push(value);
            },
            else => return null,
        }
        return self.getConstant(ty, words.items);
    }

    // ---- instructions ------------------------------------------------------------------------------------

    fn createInstruction(self: *ConstMgr, id: u32, c: *const Constant, type_id: u32) ?*Inst {
        const type_: u32 = if (type_id == 0) self.ctx.getTypeMgr().getId(c.ty) else type_id;
        switch (c.kind) {
            .null_ => return Inst.make(.OpConstantNull, type_, id, &.{}),
            .bool_ => return Inst.make(if (c.boolValue()) .OpConstantTrue else .OpConstantFalse, type_, id, &.{}),
            .int, .float => return Inst.make(.OpConstant, type_, id, &.{Operand.fromWords(.LiteralContextDependentNumber, c.words.items)}),
            .struct_, .vector, .matrix, .array, .tensor => return self.createCompositeInstruction(id, c, type_id),
        }
    }

    fn createCompositeInstruction(self: *ConstMgr, result_id: u32, cc: *const Constant, type_id: u32) ?*Inst {
        var operands: List(Operand) = .{};
        const type_inst: ?*Inst = if (type_id != 0) self.ctx.getDefUseMgr().getDef(type_id) else null;
        var component_index: u32 = 0;
        for (cc.components.items) |component_const| {
            var component_type_id: u32 = 0;
            if (type_inst) |ti| {
                if (ti.op == .OpTypeStruct) {
                    component_type_id = ti.getSingleWordInOperand(component_index);
                } else if (ti.op == .OpTypeArray) {
                    component_type_id = ti.getSingleWordInOperand(0);
                } else if (ti.op == .OpTypeTensorARM) {
                    component_type_id = self.ctx.getTypeMgr().getId(component_const.ty);
                    if (component_type_id == 0) return null;
                }
            }
            const id: u32 = self.findDeclaredConstantId(component_const, component_type_id);
            if (id == 0) return null;
            operands.push(Operand.id(.IdRef, id));
            component_index += 1;
        }
        const type_: u32 = if (type_id == 0) self.ctx.getTypeMgr().getId(cc.ty) else type_id;
        return Inst.make(.OpConstantComposite, type_, result_id, operands.items);
    }

    pub fn buildInstructionAndAddToModule(self: *ConstMgr, new_const: ?*const Constant, before: ?*Inst, type_id: u32) ?*Inst {
        const nc: *const Constant = new_const orelse return null;
        const new_id: u32 = self.ctx.takeNextId();
        if (new_id == 0) return null;
        const new_inst: *Inst = self.createInstruction(new_id, nc, type_id) orelse return null;
        if (before) |b| {
            _ = b.insertBefore(new_inst);
        } else {
            self.ctx.module.types_values.pushBack(new_inst);
        }
        if (self.ctx.areAnalysesValid(Analysis.def_use)) self.ctx.getDefUseMgr().analyzeInstDefUse(new_inst);
        self.mapConstantToInst(nc, new_inst);
        return new_inst;
    }

    /// ConstantManager::GetDefiningInstruction: the declaration of `c`, created (before `before`, default: at the end
    /// of types_values) when there is none yet.
    pub fn getDefiningInstruction(self: *ConstMgr, c: ?*const Constant, type_id: u32, before: ?*Inst) ?*Inst {
        const cc: *const Constant = c orelse return null;
        const decl_id: u32 = self.findDeclaredConstantId(cc, type_id);
        if (decl_id == 0) return self.buildInstructionAndAddToModule(cc, before, type_id);
        const def: *Inst = self.ctx.getDefUseMgr().getDef(decl_id) orelse fatal("ConstMgr: declared constant %{d} has no definition", .{decl_id});
        check(type_id == 0 or def.typeId() == type_id, "This constant already has an instruction with a different type.");
        return def;
    }

    // ---- derived constants -------------------------------------------------------------------------------

    pub fn getNullCompositeConstant(self: *ConstMgr, ty_in: ?*const Type) ?*const Constant {
        const ty: *const Type = ty_in orelse return null;
        var ids: List(u32) = .{};
        switch (ty.data) {
            .vector => |v| {
                const null_id: u32 = self.getNullConstId(v.element);
                var i: u32 = 0;
                while (i < v.count) : (i += 1) ids.push(null_id);
            },
            .matrix => |m| {
                const null_id: u32 = self.getNullConstId(m.element);
                var i: u32 = 0;
                while (i < m.count) : (i += 1) ids.push(null_id);
            },
            .struct_ => return null,
            .array => |a| {
                const null_id: u32 = self.getNullConstId(a.element);
                check(a.length.words.items[0] == ArrayLength.constant, "unexpected array length");
                // the C++ reads words[0] (the case tag, 0) here, not the length: kept for identical behaviour
                const element_count: u32 = a.length.words.items[0];
                var i: u32 = 0;
                while (i < element_count) : (i += 1) ids.push(null_id);
            },
            .tensor_arm => |ttype| return self.getNullTensorConstant(ty, &ttype),
            else => return null,
        }
        return self.getConstant(ty, ids.items);
    }

    fn getNullTensorConstant(self: *ConstMgr, ty: *const Type, ttype: *const TyTensorARM) ?*const Constant {
        check(ttype.shape_id != 0, "Only shaped tensors are composites");
        const du: *DefUseMgr = self.ctx.getDefUseMgr();
        const shape_inst: *Inst = du.getDef(ttype.shape_id) orelse return null;
        const shape_cst: *const Constant = self.getConstantFromInst(shape_inst) orelse return null;
        if (shape_cst.kind != .array) return null;
        const shape_components: []*const Constant = shape_cst.components.items;
        if (shape_components.len == 0) return null;
        const outer_dim_cst: *const Constant = shape_components[0];
        if (outer_dim_cst.kind != .int) return null;
        const element_count: u64 = outer_dim_cst.getZeroExtendedValue();
        var components: List(*const Constant) = .{};
        if (shape_components.len == 1) {
            const element_null: *const Constant = self.getConstant(ttype.element, &.{}) orelse return null;
            var i: u64 = 0;
            while (i < element_count) : (i += 1) components.push(element_null);
            return self.registerConstant(newConstant(ty, .tensor, &.{}, components.items));
        }
        var rank_cst: ?*const Constant = null;
        if (ttype.rank_id != 0) {
            if (du.getDef(ttype.rank_id)) |rank_inst| rank_cst = self.getConstantFromInst(rank_inst);
        }
        var rank_value: u64 = shape_components.len;
        if (rank_cst) |rc| {
            if (rc.kind == .int) rank_value = rc.getZeroExtendedValue();
        }
        if (rank_value <= 1) {
            const element_null: *const Constant = self.getConstant(ttype.element, &.{}) orelse return null;
            var i: u64 = 0;
            while (i < element_count) : (i += 1) components.push(element_null);
            return self.registerConstant(newConstant(ty, .tensor, &.{}, components.items));
        }
        const inner_rank: u64 = rank_value - 1;
        var rank_int_type: ?*const TyInteger = if (rank_cst) |rc| rc.ty.as(.integer) else null;
        if (rank_int_type == null) rank_int_type = outer_dim_cst.ty.as(.integer);
        if (rank_int_type == null) return null;
        const rank_int_ty_ptr: *const Type = if (rank_cst) |rc| (if (rc.ty.data == .integer) rc.ty else outer_dim_cst.ty) else outer_dim_cst.ty;
        const inner_rank_cst: ?*const Constant = self.generateIntegerConstant(rank_int_ty_ptr, inner_rank);
        const inner_rank_id: u32 = (self.getDefiningInstruction(inner_rank_cst, 0, null) orelse return null).resultId();
        const shape_elem_type: *const Type = shape_components[1].ty;
        if (shape_elem_type.data != .integer) return null;
        const inner_shape_len_cst: ?*const Constant = self.generateIntegerConstant(shape_elem_type, inner_rank);
        const inner_shape_len_id: u32 = (self.getDefiningInstruction(inner_shape_len_cst, 0, null) orelse return null).resultId();
        var len_words: List(u32) = .{};
        len_words.push(ArrayLength.constant);
        len_words.push(@intCast(inner_rank));
        const inner_shape_type = Type.array(shape_elem_type, .{ .id = inner_shape_len_id, .words = len_words });
        const inner_shape_reg_type: *Type = self.ctx.getTypeMgr().getRegisteredType(&inner_shape_type) orelse return null;
        var inner_shape_ids: List(u32) = .{};
        var i: usize = 1;
        while (i < shape_components.len) : (i += 1) {
            inner_shape_ids.push((self.getDefiningInstruction(shape_components[i], 0, null) orelse return null).resultId());
        }
        const inner_shape_cst: ?*const Constant = self.getConstant(inner_shape_reg_type, inner_shape_ids.items);
        const inner_shape_id: u32 = (self.getDefiningInstruction(inner_shape_cst, 0, null) orelse return null).resultId();
        const inner_tensor_type: Type = .{ .data = .{ .tensor_arm = .{ .element = ttype.element, .rank_id = inner_rank_id, .shape_id = inner_shape_id } } };
        const inner_tensor_reg_type: *Type = self.ctx.getTypeMgr().getRegisteredType(&inner_tensor_type) orelse return null;
        const inner_null_tensor: *const Constant = self.getNullCompositeConstant(inner_tensor_reg_type) orelse return null;
        var k: u64 = 0;
        while (k < element_count) : (k += 1) components.push(inner_null_tensor);
        return self.registerConstant(newConstant(ty, .tensor, &.{}, components.items));
    }

    pub fn getNumericVectorConstantWithWords(self: *ConstMgr, ty: *const Type, literal_words: []const u32) ?*const Constant {
        const vt: *const TyVector = ty.as(.vector) orelse fatal("getNumericVectorConstantWithWords: not a vector type", .{});
        const element_type: *const Type = vt.element;
        var words_per_element: u32 = 0;
        switch (element_type.data) {
            .float => |f| words_per_element = f.width / 32,
            .integer => |n| words_per_element = n.width / 32,
            .bool_ => words_per_element = 1,
            else => {},
        }
        if (words_per_element != 1 and words_per_element != 2) return null;
        if (words_per_element * vt.count != literal_words.len) return null;
        var element_ids: List(u32) = .{};
        var i: u32 = 0;
        while (i < vt.count) : (i += 1) {
            const first: u32 = words_per_element * i;
            const element_constant: *const Constant = self.getConstant(element_type, literal_words[first .. first + words_per_element]) orelse return null;
            const element_inst: *Inst = self.getDefiningInstruction(element_constant, 0, null) orelse return null;
            element_ids.push(element_inst.resultId());
        }
        return self.getConstant(ty, element_ids.items);
    }

    pub fn getFloatConst(self: *ConstMgr, val: f32) ?*const Constant {
        const float_type: ?*Type = self.ctx.getTypeMgr().getFloatType();
        const w: [1]u32 = .{@bitCast(val)};
        return self.getConstant(float_type, &w);
    }

    pub fn getFloatConstId(self: *ConstMgr, val: f32) u32 {
        const c: ?*const Constant = self.getFloatConst(val);
        const inst: *Inst = self.getDefiningInstruction(c, 0, null) orelse return 0;
        return inst.resultId();
    }

    pub fn getDoubleConst(self: *ConstMgr, val: f64) ?*const Constant {
        const float_type: ?*Type = self.ctx.getTypeMgr().getDoubleType();
        const bits: u64 = @bitCast(val);
        const w: [2]u32 = .{ @truncate(bits), @truncate(bits >> 32) };
        return self.getConstant(float_type, &w);
    }

    pub fn getDoubleConstId(self: *ConstMgr, val: f64) u32 {
        const c: ?*const Constant = self.getDoubleConst(val);
        const inst: *Inst = self.getDefiningInstruction(c, 0, null) orelse return 0;
        return inst.resultId();
    }

    pub fn getSIntConstId(self: *ConstMgr, val: i32) u32 {
        const sint_type: ?*Type = self.ctx.getTypeMgr().getSIntType();
        const w: [1]u32 = .{@bitCast(val)};
        const c: *const Constant = self.getConstant(sint_type, &w) orelse return 0;
        const inst: *Inst = self.getDefiningInstruction(c, 0, null) orelse return 0;
        return inst.resultId();
    }

    pub fn getUIntConstId(self: *ConstMgr, val: u32) u32 {
        const uint_type: ?*Type = self.ctx.getTypeMgr().getUIntType();
        const w: [1]u32 = .{val};
        const c: *const Constant = self.getConstant(uint_type, &w) orelse return 0;
        const inst: *Inst = self.getDefiningInstruction(c, 0, null) orelse return 0;
        return inst.resultId();
    }

    pub fn getNullConstId(self: *ConstMgr, ty: ?*const Type) u32 {
        const c: *const Constant = self.getConstant(ty, &.{}) orelse return 0;
        const inst: *Inst = self.getDefiningInstruction(c, 0, null) orelse return 0;
        return inst.resultId();
    }

    /// ConstantManager::GetIntConst: wraps `val` to the width and signedness (sign extension for signed types).
    pub fn getIntConst(self: *ConstMgr, val_in: u64, bit_width: u32, is_signed: bool) ?*const Constant {
        const int_type: ?*Type = self.ctx.getTypeMgr().getIntType(bit_width, is_signed);
        var val: u64 = val_in;
        if (is_signed) {
            const num_of_bit_to_ignore: u6 = @intCast(64 - bit_width);
            const shifted: i64 = @bitCast(val << num_of_bit_to_ignore);
            val = @bitCast(shifted >> num_of_bit_to_ignore);
        } else if (bit_width < 64) {
            const mask: u64 = (@as(u64, 1) << @intCast(bit_width)) - 1;
            val &= mask;
        }
        if (bit_width <= 32) {
            const w: [1]u32 = .{@truncate(val)};
            return self.getConstant(int_type, &w);
        }
        const w: [2]u32 = .{ @truncate(val), @truncate(val >> 32) };
        return self.getConstant(int_type, &w);
    }

    pub fn generateIntegerConstant(self: *ConstMgr, integer_type: *const Type, result_in: u64) ?*const Constant {
        const it: *const TyInteger = integer_type.as(.integer) orelse fatal("generateIntegerConstant: not an integer type", .{});
        var result: u64 = result_in;
        if (it.width == 64) {
            const w: [2]u32 = .{ @truncate(result), @truncate(result >> 32) };
            return self.getConstant(integer_type, &w);
        }
        check(it.width <= 32, "generateIntegerConstant: width above 32 and not 64");
        if (it.is_signed) {
            result = signExtendValue(result, it.width);
        } else {
            result = zeroExtendValue(result, it.width);
        }
        const w: [1]u32 = .{@truncate(result)};
        return self.getConstant(integer_type, &w);
    }
};

/// Creates instructions at an insertion point (InstructionBuilder of the C++). It updates analyses only as far as the
/// `preserved` flags the caller passes say.
pub const InstBuilder = struct {
    ctx: *Ctx,
    parent: ?*Block,
    insert_before: ?*Inst, // null: append at the end of `parent`
    preserved: u32,

    /// Builder inserting before `insert_before` (InstructionBuilder(context, insert_before, preserved)).
    pub fn init(ctx: *Ctx, insert_before: *Inst, preserved: u32) InstBuilder {
        check(preserved & ~(Analysis.def_use | Analysis.instr_to_block) == 0, "InstBuilder: only def-use and instr-to-block may be preserved");
        return .{ .ctx = ctx, .parent = insert_before.block, .insert_before = insert_before, .preserved = preserved };
    }

    /// Builder appending at the end of `parent_block` (InstructionBuilder(context, parent_block, preserved)).
    pub fn initAtBlockEnd(ctx: *Ctx, parent_block: *Block, preserved: u32) InstBuilder {
        check(preserved & ~(Analysis.def_use | Analysis.instr_to_block) == 0, "InstBuilder: only def-use and instr-to-block may be preserved");
        return .{ .ctx = ctx, .parent = parent_block, .insert_before = null, .preserved = preserved };
    }

    pub fn setInsertPoint(self: *InstBuilder, insert_before: *Inst) void {
        self.parent = insert_before.block;
        self.insert_before = insert_before;
    }

    pub fn setInsertPointBlockEnd(self: *InstBuilder, parent_block: *Block) void {
        self.parent = parent_block;
        self.insert_before = null;
    }

    pub fn getInsertPoint(self: *const InstBuilder) ?*Inst {
        return self.insert_before;
    }

    pub fn getContext(self: *const InstBuilder) *Ctx {
        return self.ctx;
    }

    pub fn getPreservedAnalysis(self: *const InstBuilder) u32 {
        return self.preserved;
    }

    // ---- core ------------------------------------------------------------------------------------------

    pub fn addInstruction(self: *const InstBuilder, inst: *Inst) *Inst {
        if (self.insert_before) |b| {
            _ = b.insertBefore(inst);
        } else {
            const p: *Block = self.parent orelse fatal("InstBuilder: no insertion point", .{});
            p.insts.pushBack(inst);
        }
        if (self.ctx.areAnalysesValid(Analysis.def_use) and (self.preserved & Analysis.def_use) != 0) {
            self.ctx.getDefUseMgr().analyzeInstDefUse(inst);
        }
        return inst;
    }

    fn idOp(v: u32) Operand {
        return Operand.id(.IdRef, v);
    }

    fn litOp(v: u32) Operand {
        return Operand.single(.LiteralInteger, v);
    }

    /// The result id for an instruction with a result type (0 when `type_id` is 0), or null when ids ran out.
    fn resultIdFor(self: *const InstBuilder, type_id: u32) ?u32 {
        if (type_id == 0) return 0;
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return r;
    }

    fn build(self: *const InstBuilder, op: Op, type_id: u32, result_id: u32, ops: []const Operand) *Inst {
        return self.addInstruction(Inst.make(op, type_id, result_id, ops));
    }

    /// The ExtSet of the OpExtInstImport with result id `set_id` (what the loader stores in `Inst.ext_set`).
    fn extSetOfImport(self: *const InstBuilder, set_id: u32) ExtSet {
        var it: ?*Inst = self.ctx.module.ext_inst_imports.first;
        while (it) |i| : (it = i.next) {
            if (i.resultId() == set_id) return extSetFromImportName(i.getInOperand(0).asString());
        }
        fatal("InstBuilder: %{d} is not an OpExtInstImport", .{set_id});
    }

    // ---- generic operations -------------------------------------------------------------------------

    pub fn addNullaryOp(self: *const InstBuilder, type_id: u32, op: Op) ?*Inst {
        const r: u32 = self.resultIdFor(type_id) orelse return null;
        return self.build(op, type_id, r, &.{});
    }

    pub fn addUnaryOp(self: *const InstBuilder, type_id: u32, op: Op, operand1: u32) ?*Inst {
        const r: u32 = self.resultIdFor(type_id) orelse return null;
        return self.build(op, type_id, r, &.{idOp(operand1)});
    }

    pub fn addBinaryOp(self: *const InstBuilder, type_id: u32, op: Op, operand1: u32, operand2: u32) ?*Inst {
        const r: u32 = self.resultIdFor(type_id) orelse return null;
        return self.build(op, type_id, if (op == .OpStore) 0 else r, &.{ idOp(operand1), idOp(operand2) });
    }

    pub fn addTernaryOp(self: *const InstBuilder, type_id: u32, op: Op, operand1: u32, operand2: u32, operand3: u32) ?*Inst {
        const r: u32 = self.resultIdFor(type_id) orelse return null;
        return self.build(op, type_id, r, &.{ idOp(operand1), idOp(operand2), idOp(operand3) });
    }

    pub fn addQuadOp(self: *const InstBuilder, type_id: u32, op: Op, operand1: u32, operand2: u32, operand3: u32, operand4: u32) ?*Inst {
        const r: u32 = self.resultIdFor(type_id) orelse return null;
        return self.build(op, type_id, r, &.{ idOp(operand1), idOp(operand2), idOp(operand3), idOp(operand4) });
    }

    pub fn addIdLiteralOp(self: *const InstBuilder, type_id: u32, op: Op, id: u32, uliteral: u32) ?*Inst {
        const r: u32 = self.resultIdFor(type_id) orelse return null;
        return self.build(op, type_id, r, &.{ idOp(id), litOp(uliteral) });
    }

    /// AddNaryOp: all operands are ids; a result id is taken unless `result` is given.
    pub fn addNaryOp(self: *const InstBuilder, type_id: u32, op: Op, operands: []const u32, result_in: u32) ?*Inst {
        var ops: List(Operand) = .{};
        for (operands) |o| ops.push(idOp(o));
        var result: u32 = result_in;
        if (result == 0) {
            result = self.ctx.takeNextId();
            if (result == 0) return null;
        }
        return self.build(op, type_id, result, ops.items);
    }

    // ---- control flow ---------------------------------------------------------------------------------

    pub fn addSelectionMerge(self: *const InstBuilder, merge_id: u32, selection_control: u32) *Inst {
        return self.build(.OpSelectionMerge, 0, 0, &.{ idOp(merge_id), Operand.single(.SelectionControl, selection_control) });
    }

    pub fn addLoopMerge(self: *const InstBuilder, merge_id: u32, continue_id: u32, loop_control: u32) *Inst {
        return self.build(.OpLoopMerge, 0, 0, &.{ idOp(merge_id), idOp(continue_id), Operand.single(.LoopControl, loop_control) });
    }

    pub fn addBranch(self: *const InstBuilder, label_id: u32) *Inst {
        return self.build(.OpBranch, 0, 0, &.{idOp(label_id)});
    }

    /// `merge_id == invalid_id`: no OpSelectionMerge is added in front.
    pub fn addConditionalBranch(self: *const InstBuilder, cond_id: u32, true_id: u32, false_id: u32, merge_id: u32, selection_control: u32) *Inst {
        if (merge_id != invalid_id) _ = self.addSelectionMerge(merge_id, selection_control);
        return self.build(.OpBranchConditional, 0, 0, &.{ idOp(cond_id), idOp(true_id), idOp(false_id) });
    }

    pub fn addSwitch(self: *const InstBuilder, selector_id: u32, default_id: u32, targets: []const SwitchTarget, merge_id: u32, selection_control: u32) *Inst {
        if (merge_id != invalid_id) _ = self.addSelectionMerge(merge_id, selection_control);
        var ops: List(Operand) = .{};
        ops.push(idOp(selector_id));
        ops.push(idOp(default_id));
        for (targets) |t| {
            ops.push(Operand.fromWords(.LiteralContextDependentNumber, t.literal));
            ops.push(idOp(t.label));
        }
        return self.build(.OpSwitch, 0, 0, ops.items);
    }

    pub fn addPhi(self: *const InstBuilder, type_id: u32, incomings: []const u32, result: u32) ?*Inst {
        check(incomings.len % 2 == 0, "A sequence of pairs is expected");
        return self.addNaryOp(type_id, .OpPhi, incomings, result);
    }

    pub fn addUnreachable(self: *const InstBuilder) *Inst {
        return self.build(.OpUnreachable, 0, 0, &.{});
    }

    // ---- arithmetic and logic ---------------------------------------------------------------------------

    pub fn addIAdd(self: *const InstBuilder, type_id: u32, op1: u32, op2: u32) ?*Inst {
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(.OpIAdd, type_id, r, &.{ idOp(op1), idOp(op2) });
    }

    fn addCompare(self: *const InstBuilder, op: Op, op1: u32, op2: u32) ?*Inst {
        const bool_type = Type.simple(.bool_);
        const type_id: u32 = self.ctx.getTypeMgr().getId(&bool_type); // GetId, not GetTypeInstruction: 0 when the module has no bool
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(op, type_id, r, &.{ idOp(op1), idOp(op2) });
    }

    pub fn addULessThan(self: *const InstBuilder, op1: u32, op2: u32) ?*Inst {
        return self.addCompare(.OpULessThan, op1, op2);
    }

    pub fn addSLessThan(self: *const InstBuilder, op1: u32, op2: u32) ?*Inst {
        return self.addCompare(.OpSLessThan, op1, op2);
    }

    /// AddLessThan: signed or unsigned comparison depending on the (integer) type of `op1`.
    pub fn addLessThan(self: *const InstBuilder, op1: u32, op2: u32) ?*Inst {
        const op1_insn: *Inst = self.ctx.getDefUseMgr().getDef(op1) orelse fatal("InstBuilder.addLessThan: %{d} is not defined", .{op1});
        const ty: *Type = self.ctx.getTypeMgr().getType(op1_insn.typeId()) orelse fatal("InstBuilder.addLessThan: operand has no type", .{});
        const it: *const TyInteger = ty.as(.integer) orelse fatal("Operand is not of int type", .{});
        if (it.is_signed) return self.addSLessThan(op1, op2);
        return self.addULessThan(op1, op2);
    }

    pub fn addSelect(self: *const InstBuilder, type_id: u32, cond: u32, true_value: u32, false_value: u32) ?*Inst {
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(.OpSelect, type_id, r, &.{ idOp(cond), idOp(true_value), idOp(false_value) });
    }

    // ---- composites ---------------------------------------------------------------------------------------

    pub fn addCompositeConstruct(self: *const InstBuilder, type_id: u32, ids: []const u32) ?*Inst {
        var ops: List(Operand) = .{};
        for (ids) |id| ops.push(idOp(id));
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(.OpCompositeConstruct, type_id, r, ops.items);
    }

    pub fn addCompositeExtract(self: *const InstBuilder, type_id: u32, id_of_composite: u32, index_list: []const u32) ?*Inst {
        var ops: List(Operand) = .{};
        ops.push(idOp(id_of_composite));
        for (index_list) |index| ops.push(litOp(index));
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(.OpCompositeExtract, type_id, r, ops.items);
    }

    pub fn addVectorShuffle(self: *const InstBuilder, result_type: u32, vec1: u32, vec2: u32, components: []const u32) ?*Inst {
        var ops: List(Operand) = .{};
        ops.push(idOp(vec1));
        ops.push(idOp(vec2));
        for (components) |c| ops.push(litOp(c));
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(.OpVectorShuffle, result_type, r, ops.items);
    }

    // ---- memory ---------------------------------------------------------------------------------------------

    pub fn addOpcodeAccessChain(self: *const InstBuilder, op: Op, type_id: u32, base_ptr_id: u32, ids: []const u32) ?*Inst {
        check(op == .OpAccessChain or op == .OpInBoundsAccessChain, "addOpcodeAccessChain: not an access chain opcode");
        var ops: List(Operand) = .{};
        ops.push(idOp(base_ptr_id));
        for (ids) |id| ops.push(idOp(id));
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(op, type_id, r, ops.items);
    }

    pub fn addAccessChain(self: *const InstBuilder, type_id: u32, base_ptr_id: u32, ids: []const u32) ?*Inst {
        return self.addOpcodeAccessChain(.OpAccessChain, type_id, base_ptr_id, ids);
    }

    pub fn addInBoundsAccessChain(self: *const InstBuilder, type_id: u32, base_ptr_id: u32, ids: []const u32) ?*Inst {
        return self.addOpcodeAccessChain(.OpInBoundsAccessChain, type_id, base_ptr_id, ids);
    }

    pub fn addLoad(self: *const InstBuilder, type_id: u32, base_ptr_id: u32, alignment: u32) ?*Inst {
        var ops: List(Operand) = .{};
        ops.push(idOp(base_ptr_id));
        if (alignment != 0) {
            ops.push(Operand.single(.MemoryAccess, MemoryAccessMask.Aligned));
            ops.push(litOp(alignment));
        }
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(.OpLoad, type_id, r, ops.items);
    }

    pub fn addStore(self: *const InstBuilder, ptr_id: u32, obj_id: u32) *Inst {
        return self.build(.OpStore, 0, 0, &.{ idOp(ptr_id), idOp(obj_id) });
    }

    pub fn addCopyObject(self: *const InstBuilder, type_id: u32, value_id: u32) ?*Inst {
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(.OpCopyObject, type_id, r, &.{idOp(value_id)});
    }

    pub fn addVariable(self: *const InstBuilder, type_id: u32, storage_class: u32) ?*Inst {
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(.OpVariable, type_id, r, &.{Operand.single(.StorageClass, storage_class)});
    }

    pub fn addFunctionCall(self: *const InstBuilder, result_type: u32, function: u32, parameters: []const u32) ?*Inst {
        var ops: List(Operand) = .{};
        ops.push(idOp(function));
        for (parameters) |p| ops.push(idOp(p));
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(.OpFunctionCall, result_type, r, ops.items);
    }

    pub fn addSampledImage(self: *const InstBuilder, sampled_image_type_id: u32, image_id: u32, sampler_id: u32) ?*Inst {
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        return self.build(.OpSampledImage, sampled_image_type_id, r, &.{ idOp(image_id), idOp(sampler_id) });
    }

    pub fn addNaryExtendedInstruction(self: *const InstBuilder, result_type: u32, set: u32, instruction: u32, ext_operands: []const u32) ?*Inst {
        var ops: List(Operand) = .{};
        ops.push(idOp(set));
        ops.push(Operand.single(.LiteralExtInstInteger, instruction));
        for (ext_operands) |id| ops.push(idOp(id));
        const r: u32 = self.ctx.takeNextId();
        if (r == 0) return null;
        const inst: *Inst = Inst.make(.OpExtInst, result_type, r, ops.items);
        inst.ext_set = self.extSetOfImport(set);
        return self.addInstruction(inst);
    }

    /// AddDecoration: adds an OpDecorate to the annotations (through the context, which keeps its managers in sync).
    pub fn addDecoration(self: *const InstBuilder, target_id: u32, decoration: u32, literals: []const u32) *Inst {
        var ops: List(Operand) = .{};
        ops.push(idOp(target_id));
        ops.push(Operand.single(.Decoration, decoration));
        for (literals) |l| ops.push(litOp(l));
        const inst: *Inst = Inst.make(.OpDecorate, 0, 0, ops.items);
        self.ctx.addAnnotationInst(inst);
        return inst;
    }

    // ---- constants --------------------------------------------------------------------------------------------

    /// GetIntConstant<T>: a 32-bit integer constant given as its word (`@bitCast` an i32 for signed values).
    pub fn getIntConstant(self: *const InstBuilder, word: u32, sign: bool) ?*Inst {
        const int_type = Type.integer(32, sign);
        const tm: *TypeMgr = self.ctx.getTypeMgr();
        const type_id: u32 = tm.getTypeInstruction(&int_type);
        if (type_id == 0) return null;
        const rebuilt: ?*Type = tm.getType(type_id);
        const cm: *ConstMgr = self.ctx.getConstantMgr();
        const w: [1]u32 = .{word};
        return cm.getDefiningInstruction(cm.getConstant(rebuilt, &w), 0, null);
    }

    pub fn getSintConstant(self: *const InstBuilder, value: i32) ?*Inst {
        return self.getIntConstant(@bitCast(value), true);
    }

    pub fn getUintConstant(self: *const InstBuilder, value: u32) ?*Inst {
        return self.getIntConstant(value, false);
    }

    pub fn getUintConstantId(self: *const InstBuilder, value: u32) u32 {
        const i: *Inst = self.getUintConstant(value) orelse return 0;
        return i.resultId();
    }

    pub fn getBoolConstant(self: *const InstBuilder, value: bool) ?*Inst {
        const bool_type = Type.simple(.bool_);
        const tm: *TypeMgr = self.ctx.getTypeMgr();
        const type_id: u32 = tm.getTypeInstruction(&bool_type);
        const rebuilt: ?*Type = tm.getType(type_id);
        const cm: *ConstMgr = self.ctx.getConstantMgr();
        const w: [1]u32 = .{@intFromBool(value)};
        return cm.getDefiningInstruction(cm.getConstant(rebuilt, &w), 0, null);
    }

    pub fn getBoolConstantId(self: *const InstBuilder, value: bool) u32 {
        const i: *Inst = self.getBoolConstant(value) orelse return 0;
        return i.resultId();
    }
};

/// Structured CFG analysis: the innermost merge construct, loop and switch around every reachable block.
pub const StructCfg = struct {
    ctx: *Ctx,
    bb_to_construct: Map(u32, ConstructInfo) = .{},
    merge_blocks: Set(u32) = .{},

    const TraversalInfo = struct {
        cinfo: ConstructInfo = .{},
        merge_node: u32 = 0,
        continue_node: u32 = 0,
    };

    pub fn init(ctx: *Ctx) *StructCfg {
        const self = scAllocator().create(StructCfg) catch oom();
        self.* = .{ .ctx = ctx };
        // If this is not a shader there are no merge instructions and no structured CFG to analyze.
        if (!ctx.getFeatureMgr().hasCapability(.Shader)) return self;
        for (ctx.module.functions.items) |f| self.addBlocksInFunction(f);
        return self;
    }

    fn addBlocksInFunction(self: *StructCfg, func: *Func) void {
        if (func.blocks.len() == 0) return;
        const cfg: *Cfg = self.ctx.cfg();
        var order: List(*Block) = .{};
        cfg.computeStructuredOrderNoEnd(func, func.blocks.items[0], &order);

        var state: List(TraversalInfo) = .{};
        state.push(.{});

        for (order.items) |block| {
            if (cfg.isPseudoEntryBlock(block) or cfg.isPseudoExitBlock(block)) continue;

            if (block.id() == state.last().merge_node) _ = state.pop();

            // The structured order keeps the blocks of the continue construct between the continue header and the
            // merge node.
            if (block.id() == state.last().continue_node) state.items[state.len() - 1].cinfo.in_continue = true;

            // std::unordered_map::emplace: keeps the first entry when the block is visited twice
            const gop: Map(u32, ConstructInfo).GetOrPutResult = self.bb_to_construct.getOrPut(block.id());
            if (!gop.found_existing) gop.value_ptr.* = state.last().cinfo;

            if (block.getMergeInst()) |merge_inst| {
                var new_state: TraversalInfo = .{};
                new_state.merge_node = merge_inst.getSingleWordInOperand(0);
                new_state.cinfo.containing_construct = block.id();

                if (merge_inst.op == .OpLoopMerge) {
                    new_state.cinfo.containing_loop = block.id();
                    new_state.cinfo.containing_switch = 0;
                    new_state.continue_node = merge_inst.getSingleWordInOperand(1);
                    if (block.id() == new_state.continue_node) {
                        new_state.cinfo.in_continue = true;
                        self.bb_to_construct.getPtr(block.id()).?.in_continue = true;
                    } else {
                        new_state.cinfo.in_continue = false;
                    }
                } else {
                    new_state.cinfo.containing_loop = state.last().cinfo.containing_loop;
                    new_state.cinfo.in_continue = state.last().cinfo.in_continue;
                    new_state.continue_node = state.last().continue_node;
                    if (merge_inst.nextNode().?.op == .OpSwitch) {
                        new_state.cinfo.containing_switch = block.id();
                    } else {
                        new_state.cinfo.containing_switch = state.last().cinfo.containing_switch;
                    }
                }
                state.push(new_state);
                _ = self.merge_blocks.insert(new_state.merge_node);
            }
        }
    }

    pub fn containingConstruct(self: *const StructCfg, bb_id: u32) u32 {
        const it: *ConstructInfo = self.bb_to_construct.getPtr(bb_id) orelse return 0;
        return it.containing_construct;
    }

    pub fn containingConstructOfInst(self: *const StructCfg, inst: *const Inst) u32 {
        const bb: *Block = inst.block orelse fatal("StructCfg.containingConstructOfInst: instruction is not in a block", .{});
        return self.containingConstruct(bb.id());
    }

    pub fn mergeBlock(self: *const StructCfg, bb_id: u32) u32 {
        const header_id: u32 = self.containingConstruct(bb_id);
        if (header_id == 0) return 0;
        const header: *Block = self.ctx.cfg().block(header_id);
        const merge_inst: *Inst = header.getMergeInst().?;
        return merge_inst.getSingleWordInOperand(0);
    }

    pub fn nestingDepth(self: *const StructCfg, bb_id: u32) u32 {
        var result: u32 = 0;
        var m: u32 = self.mergeBlock(bb_id);
        while (m != 0) : (m = self.mergeBlock(m)) result += 1;
        return result;
    }

    pub fn containingLoop(self: *const StructCfg, bb_id: u32) u32 {
        const it: *ConstructInfo = self.bb_to_construct.getPtr(bb_id) orelse return 0;
        return it.containing_loop;
    }

    pub fn loopMergeBlock(self: *const StructCfg, bb_id: u32) u32 {
        const header_id: u32 = self.containingLoop(bb_id);
        if (header_id == 0) return 0;
        const header: *Block = self.ctx.cfg().block(header_id);
        return header.getMergeInst().?.getSingleWordInOperand(0);
    }

    pub fn loopContinueBlock(self: *const StructCfg, bb_id: u32) u32 {
        const header_id: u32 = self.containingLoop(bb_id);
        if (header_id == 0) return 0;
        const header: *Block = self.ctx.cfg().block(header_id);
        return header.getMergeInst().?.getSingleWordInOperand(1);
    }

    pub fn loopNestingDepth(self: *const StructCfg, bb_id: u32) u32 {
        var result: u32 = 0;
        var m: u32 = self.loopMergeBlock(bb_id);
        while (m != 0) : (m = self.loopMergeBlock(m)) result += 1;
        return result;
    }

    pub fn containingSwitch(self: *const StructCfg, bb_id: u32) u32 {
        const it: *ConstructInfo = self.bb_to_construct.getPtr(bb_id) orelse return 0;
        return it.containing_switch;
    }

    pub fn switchMergeBlock(self: *const StructCfg, bb_id: u32) u32 {
        const header_id: u32 = self.containingSwitch(bb_id);
        if (header_id == 0) return 0;
        const header: *Block = self.ctx.cfg().block(header_id);
        return header.getMergeInst().?.getSingleWordInOperand(0);
    }

    pub fn isContinueBlock(self: *const StructCfg, bb_id: u32) bool {
        return self.loopContinueBlock(bb_id) == bb_id;
    }

    pub fn isInContainingLoopsContinueConstruct(self: *const StructCfg, bb_id: u32) bool {
        const it: *ConstructInfo = self.bb_to_construct.getPtr(bb_id) orelse return false;
        return it.in_continue;
    }

    pub fn isInContinueConstruct(self: *const StructCfg, bb_id_in: u32) bool {
        var bb_id: u32 = bb_id_in;
        while (bb_id != 0) {
            if (self.isInContainingLoopsContinueConstruct(bb_id)) return true;
            bb_id = self.containingLoop(bb_id);
        }
        return false;
    }

    pub fn isMergeBlock(self: *const StructCfg, bb_id: u32) bool {
        return self.merge_blocks.contains(bb_id);
    }

    /// FindFuncsCalledFromContinue: ids of the functions called, directly or indirectly, from a continue construct,
    /// as a std::unordered_set (iteration order of libstdc++, see StdUSet32).
    pub fn findFuncsCalledFromContinue(self: *const StructCfg) StdUSet32 {
        const ctx: *Ctx = self.ctx;
        var called_from_continue: StdUSet32 = .{};
        var todo: Queue(u32) = .{};
        for (ctx.module.functions.items) |func| {
            for (func.blocks.items) |bb| {
                if (self.isInContainingLoopsContinueConstruct(bb.id())) {
                    var it: ?*Inst = bb.insts.first;
                    while (it) |inst| : (it = inst.next) {
                        if (inst.op == .OpFunctionCall) todo.push(inst.getSingleWordInOperand(0));
                    }
                }
            }
        }
        while (todo.pop()) |func_id| {
            const func: *Func = ctx.getFunction(func_id) orelse fatal("FindFuncsCalledFromContinue: no function %{d}", .{func_id});
            if (called_from_continue.insert(func_id)) ctx.addCalls(func, &todo);
        }
        return called_from_continue;
    }
};

// Instruction helpers that need the context (instruction.cpp).
// These are free functions taking the Ctx (Inst itself knows nothing about analyses in this port).

/// Instruction::GetBaseAddress: follows access chains, texel pointers and copies down to the base pointer definition.
pub fn instGetBaseAddress(ctx: *Ctx, inst: *const Inst) *Inst {
    const du: *DefUseMgr = ctx.getDefUseMgr();
    var base: u32 = inst.getSingleWordInOperand(0);
    var base_inst: *Inst = du.getDef(base) orelse fatal("GetBaseAddress: id %{d} is not defined", .{base});
    while (true) {
        switch (base_inst.op) {
            .OpAccessChain,
            .OpInBoundsAccessChain,
            .OpUntypedAccessChainKHR,
            .OpPtrAccessChain,
            .OpInBoundsPtrAccessChain,
            .OpImageTexelPointer,
            .OpCopyObject,
            => {
                base = base_inst.getSingleWordInOperand(0);
                base_inst = du.getDef(base) orelse fatal("GetBaseAddress: id %{d} is not defined", .{base});
            },
            else => return base_inst,
        }
    }
}

/// The image/array/struct type behind a pointer type, with one optional array layer removed.
fn instPointeeUnarrayed(ctx: *Ctx, ptr_type: *const Inst) *Inst {
    const du: *DefUseMgr = ctx.getDefUseMgr();
    const pid: u32 = ptr_type.getSingleWordInOperand(1);
    var base_type: *Inst = du.getDef(pid) orelse fatal("pointee type %{d} is not defined", .{pid});
    if (base_type.op == .OpTypeArray or base_type.op == .OpTypeRuntimeArray) {
        const eid: u32 = base_type.getSingleWordInOperand(0);
        base_type = du.getDef(eid) orelse fatal("element type %{d} is not defined", .{eid});
    }
    return base_type;
}

/// Instruction::IsVulkanStorageImage (called on an OpTypePointer)
pub fn instIsVulkanStorageImage(ctx: *Ctx, inst: *const Inst) bool {
    if (inst.op != .OpTypePointer) return false;
    if (inst.getSingleWordInOperand(0) != @intFromEnum(StorageClass.UniformConstant)) return false;
    const base_type: *Inst = instPointeeUnarrayed(ctx, inst);
    if (base_type.op != .OpTypeImage) return false;
    if (base_type.getSingleWordInOperand(kTypeImageDimIndex) == @intFromEnum(Dim.Buffer)) return false;
    // If we do not know for sure that the image is sampled, assume it is a storage image.
    return base_type.getSingleWordInOperand(kTypeImageSampledIndex) != 1;
}

/// Instruction::IsVulkanStorageTexelBuffer
pub fn instIsVulkanStorageTexelBuffer(ctx: *Ctx, inst: *const Inst) bool {
    if (inst.op != .OpTypePointer) return false;
    if (inst.getSingleWordInOperand(0) != @intFromEnum(StorageClass.UniformConstant)) return false;
    const base_type: *Inst = instPointeeUnarrayed(ctx, inst);
    if (base_type.op != .OpTypeImage) return false;
    if (base_type.getSingleWordInOperand(kTypeImageDimIndex) != @intFromEnum(Dim.Buffer)) return false;
    return base_type.getSingleWordInOperand(kTypeImageSampledIndex) != 1;
}

/// Instruction::IsVulkanStorageBuffer
pub fn instIsVulkanStorageBuffer(ctx: *Ctx, inst: *const Inst) bool {
    if (inst.op != .OpTypePointer) return false;
    const base_type: *Inst = instPointeeUnarrayed(ctx, inst);
    if (base_type.op != .OpTypeStruct) return false;
    const sc: u32 = inst.getSingleWordInOperand(0);
    if (sc == @intFromEnum(StorageClass.Uniform)) {
        return ctx.getDecorationMgr().hasDecoration(base_type.resultId(), @intFromEnum(Decoration.BufferBlock));
    } else if (sc == @intFromEnum(StorageClass.StorageBuffer)) {
        return ctx.getDecorationMgr().hasDecoration(base_type.resultId(), @intFromEnum(Decoration.Block));
    }
    return false;
}

/// Instruction::IsReadOnlyPointerShaders
fn instIsReadOnlyPointerShaders(ctx: *Ctx, inst: *const Inst) bool {
    if (inst.typeId() == 0) return false;
    const type_def: *Inst = ctx.getDefUseMgr().getDef(inst.typeId()) orelse fatal("IsReadOnlyPointer: type %{d} is not defined", .{inst.typeId()});
    if (type_def.op != .OpTypePointer) return false;
    const sc: u32 = type_def.getSingleWordInOperand(0);
    if (sc == @intFromEnum(StorageClass.UniformConstant)) {
        if (!instIsVulkanStorageImage(ctx, type_def) and !instIsVulkanStorageTexelBuffer(ctx, type_def)) return true;
    } else if (sc == @intFromEnum(StorageClass.Uniform)) {
        if (!instIsVulkanStorageBuffer(ctx, type_def)) return true;
    } else if (sc == @intFromEnum(StorageClass.PushConstant) or sc == @intFromEnum(StorageClass.Input)) {
        return true;
    }
    return ctx.getDecorationMgr().hasDecoration(inst.resultId(), @intFromEnum(Decoration.NonWritable));
}

/// Instruction::IsReadOnlyPointerKernel
fn instIsReadOnlyPointerKernel(ctx: *Ctx, inst: *const Inst) bool {
    if (inst.typeId() == 0) return false;
    const type_def: *Inst = ctx.getDefUseMgr().getDef(inst.typeId()) orelse fatal("IsReadOnlyPointer: type %{d} is not defined", .{inst.typeId()});
    if (type_def.op != .OpTypePointer) return false;
    return type_def.getSingleWordInOperand(0) == @intFromEnum(StorageClass.UniformConstant);
}

/// Instruction::IsReadOnlyPointer
pub fn instIsReadOnlyPointer(ctx: *Ctx, inst: *const Inst) bool {
    if (ctx.getFeatureMgr().hasCapability(.Shader)) return instIsReadOnlyPointerShaders(ctx, inst);
    return instIsReadOnlyPointerKernel(ctx, inst);
}

/// Instruction::IsReadOnlyLoad
pub fn instIsReadOnlyLoad(ctx: *Ctx, inst: *const Inst) bool {
    if (!inst.isLoad()) return false;
    const address_def: *Inst = instGetBaseAddress(ctx, inst);
    if (address_def.op == .OpVariable) {
        if (instIsReadOnlyPointer(ctx, address_def)) return true;
    }
    if (address_def.op == .OpLoad) {
        const address_type: *Type = ctx.getTypeMgr().getType(address_def.typeId()) orelse fatal("IsReadOnlyLoad: type %{d} is unknown", .{address_def.typeId()});
        if (address_type.as(.sampled_image)) |si| {
            const image_type: *const TyImage = si.image.as(.image) orelse fatal("IsReadOnlyLoad: sampled image of a non-image", .{});
            if (image_type.sampled == 1) return true;
        }
    }
    return false;
}

// Block surgery that needs the context: BasicBlock::SplitBasicBlock (basic_block.cpp) and
// CFG::SplitLoopHeader (cfg.cpp). Free functions: neither Block nor Cfg is allowed to know about the Ctx here.

const SplitPhiCtx = struct { ctx: *Ctx, old_id: u32, new_id: u32 };

fn splitFixPhi(c: SplitPhiCtx, phi_inst: *Inst) void {
    var changed: bool = false;
    var i: usize = 1;
    while (i < phi_inst.numInOperands()) : (i += 2) {
        if (phi_inst.getSingleWordInOperand(i) == c.old_id) {
            changed = true;
            phi_inst.setInOperand(i, &.{c.new_id});
        }
    }
    if (changed) c.ctx.updateDefUse(phi_inst);
}

fn splitFixSuccessor(c: SplitPhiCtx, label: u32) void {
    const target_bb: *Block = c.ctx.getInstrBlockById(label) orelse fatal("SplitBasicBlock: successor %{d} is not in a block", .{label});
    target_bb.forEachPhiInst(c, splitFixPhi, false);
}

/// BasicBlock::SplitBasicBlock: moves the instructions from `iter` (null: none) to the end of `block` into a new
/// block labelled `label_id` placed right after `block`. Phi nodes in the successors of the new block that referred
/// to `block` now refer to the new block. Returns the new block.
pub fn blockSplit(ctx: *Ctx, block: *Block, label_id: u32, iter: ?*Inst) *Block {
    check(block.insts.first != null, "SplitBasicBlock: the block is empty");
    const func: *Func = block.parent orelse fatal("SplitBasicBlock: block %{d} has no parent function", .{block.id()});
    const new_block: *Block = Block.new(Inst.make(.OpLabel, 0, label_id, &.{}));
    _ = func.insertBasicBlockAfter(new_block, block);

    new_block.insts.splice(null, &block.insts, iter, null);

    ctx.analyzeDefUse(new_block.label);

    // Update the phi nodes in the successor blocks to reference the new block id.
    new_block.forEachSuccessorLabel(SplitPhiCtx{ .ctx = ctx, .old_id = block.id(), .new_id = new_block.id() }, splitFixSuccessor);

    // (instr-to-block mapping: maintained by the intrusive lists)
    return new_block;
}

// Loop infrastructure and the loop unroller. Loop and LoopDescriptor (loop_descriptor.{h,cpp}) describe the loops of a
// function: header, pre-header, latch, merge and continue blocks, nesting, induction variables and iteration counts.
// The LoopUnroller pass (loop_unroller.cpp together with the unrolling half of loop_utils.cpp: LoopUtils::CanPerformUnroll /
// FullyUnroll / PartiallyUnroll) copies the body of a loop to unroll it. Flags: --loop-unroll,
// --loop-unroll-partial=<factor>.
//
// Loop::loop_basic_blocks_ is a std::unordered_set<uint32_t> in the C++: its iteration order is the libstdc++ one, so it
// is a StdUSet32 (see there). Debug-info paths (DebugDeclare, DebugScope) are omitted: extended debug info is rejected.

/// The instruction that defines `id`.
fn lpDef(ctx: *Ctx, id: u32) *Inst {
    return ctx.getDefUseMgr().getDef(id) orelse fatal("loop analysis: id %{d} is not defined", .{id});
}

/// A natural loop of a function: its header, continue target, merge block, pre-header and latch, the loop that contains it
/// and the loops nested in it.
pub const Loop = struct {
    ctx: *Ctx,
    loop_header: ?*Block = null,
    loop_continue: ?*Block = null,
    loop_merge: ?*Block = null,
    loop_preheader: ?*Block = null,
    loop_latch: ?*Block = null,
    parent: ?*Loop = null,
    nested_loops: List(*Loop) = .{},
    loop_basic_blocks: StdUSet32 = .{},
    loop_is_marked_for_removal: bool = false,

    /// Loop(IRContext*)
    pub fn create(ctx: *Ctx) *Loop {
        const l = scAllocator().create(Loop) catch oom();
        l.* = .{ .ctx = ctx };
        return l;
    }

    /// Loop(IRContext*, DominatorAnalysis*, header, continue, merge)
    pub fn createFull(ctx: *Ctx, dom: *DominatorAnalysis, header_block: *Block, continue_target: *Block, merge_target: *Block) *Loop {
        const l: *Loop = Loop.create(ctx);
        l.loop_header = header_block;
        l.loop_continue = continue_target;
        l.loop_merge = merge_target;
        l.loop_preheader = l.findLoopPreheader(dom);
        l.loop_latch = l.findLatchBlock();
        return l;
    }

    /// The implicit copy constructor (containers are deep-copied, node order and bucket count of the set are kept).
    pub fn copyOf(self: *const Loop) *Loop {
        const l = scAllocator().create(Loop) catch oom();
        l.* = self.*;
        l.nested_loops = .{};
        l.nested_loops.pushSlice(self.nested_loops.items);
        l.loop_basic_blocks = self.loop_basic_blocks.copy();
        return l;
    }

    pub fn header(self: *const Loop) *Block {
        return self.loop_header orelse fatal("Loop: no header block", .{});
    }

    pub fn mergeBlock(self: *const Loop) *Block {
        return self.loop_merge orelse fatal("Loop: no merge block", .{});
    }

    pub fn hasParent(self: *const Loop) bool {
        return self.parent != null;
    }

    pub fn hasNestedLoops(self: *const Loop) bool {
        return self.nested_loops.len() != 0;
    }

    pub fn updateLoopMergeInst(self: *Loop) void {
        const merge_inst: *Inst = self.header().getLoopMergeInst() orelse fatal("The loop is not structured", .{});
        merge_inst.setInOperand(0, &.{self.mergeBlock().id()});
    }

    pub fn setLatchBlock(self: *Loop, latch: *Block) void {
        self.loop_latch = latch;
    }

    pub fn setContinueBlock(self: *Loop, continue_block: *Block) void {
        self.loop_continue = continue_block;
    }

    /// Sets the merge block and updates the OpLoopMerge of the header when there is one.
    pub fn setMergeBlock(self: *Loop, merge: *Block) void {
        self.loop_merge = merge;
        if (self.header().getLoopMergeInst() != null) self.updateLoopMergeInst();
    }

    pub fn setPreHeaderBlock(self: *Loop, preheader: ?*Block) void {
        self.loop_preheader = preheader;
    }

    pub fn getOrCreatePreHeaderBlock(self: *Loop) ?*Block {
        if (self.loop_preheader) |p| return p;
        self.loop_header = cfgSplitLoopHeader(self.ctx, self.header());
        if (self.loop_header == null) return null;
        return self.loop_preheader;
    }

    pub fn addNestedLoop(self: *Loop, nested: *Loop) void {
        self.nested_loops.push(nested);
        nested.parent = self;
    }

    pub fn removeChildLoop(self: *Loop, loop: *Loop) void {
        const at: usize = self.nested_loops.indexOf(loop) orelse fatal("Loop.removeChildLoop: not a child", .{});
        _ = self.nested_loops.orderedRemove(at);
        loop.parent = null;
    }

    pub fn isInsideLoopId(self: *const Loop, bb_id: u32) bool {
        return self.loop_basic_blocks.contains(bb_id);
    }

    pub fn isInsideLoopBlock(self: *const Loop, bb: *const Block) bool {
        return self.isInsideLoopId(bb.id());
    }

    pub fn isInsideLoopInst(self: *const Loop, inst: *Inst) bool {
        const parent_block: *Block = self.ctx.getInstrBlock(inst) orelse return false;
        return self.isInsideLoopBlock(parent_block);
    }

    pub fn addBasicBlock(self: *Loop, id: u32) void {
        var loop: ?*Loop = self;
        while (loop) |l| : (loop = l.parent) _ = l.loop_basic_blocks.insert(id);
    }

    pub fn removeBasicBlock(self: *Loop, bb_id: u32) void {
        var loop: ?*Loop = self;
        while (loop) |l| : (loop = l.parent) _ = l.loop_basic_blocks.erase(bb_id);
    }

    pub fn clearBlocks(self: *Loop) void {
        self.loop_basic_blocks.clear();
    }

    pub fn markLoopForRemoval(self: *Loop) void {
        self.loop_is_marked_for_removal = true;
    }

    pub fn isMarkedForRemoval(self: *const Loop) bool {
        return self.loop_is_marked_for_removal;
    }

    pub fn areAllChildrenMarkedForRemoval(self: *const Loop) bool {
        for (self.nested_loops.items) |child| {
            if (!child.isMarkedForRemoval()) return false;
        }
        return true;
    }

    pub fn getDepth(self: *const Loop) usize {
        var lvl: usize = 1;
        var l: ?*Loop = self.parent;
        while (l) |p| : (l = p.parent) lvl += 1;
        return lvl;
    }

    /// HasUnrollLoopControl: the OpLoopMerge control operand is exactly Unroll.
    pub fn hasUnrollLoopControl(self: *const Loop) bool {
        const merge: *Inst = self.header().getLoopMergeInst() orelse return false;
        return merge.getSingleWordOperand(2) == 1;
    }

    // ---- preheader / latch discovery ------------------------------------------------------------------------------

    fn findLoopPreheader(self: *Loop, dom_analysis: *DominatorAnalysis) ?*Block {
        const cfg: *Cfg = self.ctx.cfg();
        const dom_tree: *DomTree = dom_analysis.getDomTree();
        const header_node: ?*DomNode = dom_tree.getTreeNodeOf(self.header());

        // The loop predecessor.
        var loop_pred: ?*Block = null;
        for (cfg.preds(self.header().id())) |p_id| {
            const node: *DomNode = dom_tree.getTreeNode(p_id) orelse continue;
            if (!dom_tree.dominatesNode(header_node, node)) {
                // The predecessor is not part of the loop, so potential loop preheader.
                if (loop_pred != null and node.bb != loop_pred.?) {
                    // If we saw 2 distinct predecessors that are outside the loop, we don't have a loop preheader.
                    return null;
                }
                loop_pred = node.bb;
            }
        }
        const pred: *Block = loop_pred orelse fatal("Loop: the loop header %{d} has no predecessor outside the loop", .{self.header().id()});

        // So we have a unique basic block that can enter this loop. If this loop is the unique successor of this
        // block, then it is a loop preheader.
        const Chk = struct { header_id: u32, is_preheader: bool = true };
        const Cb = struct {
            fn f(c: *Chk, id: u32) void {
                if (id != c.header_id) c.is_preheader = false;
            }
        };
        var chk: Chk = .{ .header_id = self.header().id() };
        pred.forEachSuccessorLabel(&chk, Cb.f);
        if (chk.is_preheader) return pred;
        return null;
    }

    /// FindLatchBlock: the predecessor of the header that is dominated by the continue target (null when not found).
    pub fn findLatchBlock(self: *Loop) ?*Block {
        const cfg: *Cfg = self.ctx.cfg();
        const dominator_analysis: *DominatorAnalysis = self.ctx.getDominatorAnalysis(self.header().parent orelse fatal("Loop: header without a function", .{}));
        const continue_id: u32 = (self.loop_continue orelse fatal("Loop: no continue block", .{})).id();
        for (cfg.preds(self.header().id())) |block_id| {
            if (dominator_analysis.dominatesId(continue_id, block_id)) return cfg.block(block_id);
        }
        return null;
    }

    // ---- exits / merging blocks / safety -----------------------------------------------------------------------

    /// GetExitBlocks: blocks outside the loop with at least one predecessor inside it (libstdc++ set order).
    pub fn getExitBlocks(self: *const Loop) StdUSet32 {
        const cfg: *Cfg = self.ctx.cfg();
        var exit_blocks: StdUSet32 = .{};
        const Cap = struct { loop: *const Loop, out: *StdUSet32 };
        const Cb = struct {
            fn f(c: Cap, succ: u32) void {
                if (!c.loop.isInsideLoopId(succ)) _ = c.out.insert(succ);
            }
        };
        for (self.loop_basic_blocks.items()) |bb_id| {
            const bb: *Block = cfg.block(bb_id);
            bb.forEachSuccessorLabel(Cap{ .loop = self, .out = &exit_blocks }, Cb.f);
        }
        return exit_blocks;
    }

    /// GetMergingBlocks: all blocks that are post-dominated by the merge block (the merge block must exist).
    pub fn getMergingBlocks(self: *const Loop) StdUSet32 {
        const cfg: *Cfg = self.ctx.cfg();
        var merging_blocks: StdUSet32 = .{};
        var to_visit: List(*Block) = .{};
        to_visit.push(self.mergeBlock());
        while (to_visit.pop()) |bb| {
            _ = merging_blocks.insert(bb.id());
            for (cfg.preds(bb.id())) |pred_id| {
                if (!self.isInsideLoopId(pred_id) and !merging_blocks.contains(pred_id)) {
                    to_visit.push(cfg.block(pred_id));
                }
            }
        }
        return merging_blocks;
    }

    fn isBasicBlockSafeToClone(ctx: *Ctx, bb: *Block) bool {
        var it: ?*Inst = bb.insts.first;
        while (it) |inst| : (it = inst.next) {
            if (!inst.isBranch() and !ctx.isCombinatorInstruction(inst)) return false;
        }
        return true;
    }

    pub fn isSafeToClone(self: *const Loop) bool {
        const cfg: *Cfg = self.ctx.cfg();
        for (self.loop_basic_blocks.items()) |bb_id| {
            if (!isBasicBlockSafeToClone(self.ctx, cfg.block(bb_id))) return false;
        }

        // Look at the merge construct.
        if (self.header().getLoopMergeInst() != null) {
            var blocks: StdUSet32 = self.getMergingBlocks();
            _ = blocks.erase(self.mergeBlock().id());
            for (blocks.items()) |bb_id| {
                if (!isBasicBlockSafeToClone(self.ctx, cfg.block(bb_id))) return false;
            }
        }
        return true;
    }
    pub fn isLCSSA(self: *const Loop) bool {
        const cfg: *Cfg = self.ctx.cfg();
        const def_use_mgr: *DefUseMgr = self.ctx.getDefUseMgr();
        const exit_blocks: StdUSet32 = self.getExitBlocks();
        for (self.loop_basic_blocks.items()) |bb_id| {
            var it: ?*Inst = cfg.block(bb_id).insts.first;
            while (it) |insn| : (it = insn.next) {
                // All uses must be either in the loop or in an exit block and in a phi instruction.
                for (def_use_mgr.registeredUsers(insn)) |use| {
                    const parent: *Block = self.ctx.getInstrBlock(use) orelse fatal("Invalid analysis", .{});
                    if (self.isInsideLoopBlock(parent)) continue;
                    if (use.op != .OpPhi) return false;
                    if (!exit_blocks.contains(parent.id())) return false;
                }
            }
        }
        return true;
    }

    // ---- hoisting helpers ---------------------------------------------------------------------------------------

    const OutsideCap = struct { loop: *const Loop, ctx: *Ctx };
    fn operandOutsideLoop(c: OutsideCap, id: *u32) bool {
        return !c.loop.isInsideLoopInst(lpDef(c.ctx, id.*));
    }

    pub fn areAllOperandsOutsideLoop(self: *const Loop, inst: *Inst) bool {
        return inst.whileEachInId(OutsideCap{ .loop = self, .ctx = self.ctx }, operandOutsideLoop);
    }

    pub fn shouldHoistInstruction(self: *const Loop, inst: *Inst) bool {
        return inst.isOpcodeCodeMotionSafe() and self.areAllOperandsOutsideLoop(inst) and
            (!inst.isLoad() or instIsReadOnlyLoad(self.ctx, inst));
    }

    // ---- structured order ---------------------------------------------------------------------------------------

    pub fn computeLoopStructuredOrder(self: *const Loop, ordered_loop_blocks: *List(*Block), include_pre_header: bool, include_merge: bool) void {
        const ctx: *Ctx = self.ctx;
        const cfg: *Cfg = ctx.cfg();
        if (include_pre_header) {
            if (self.loop_preheader) |p| ordered_loop_blocks.push(p);
        }

        const is_shader: bool = ctx.getFeatureMgr().hasCapability(.Shader);
        if (!is_shader) {
            const Cap = struct { loop: *const Loop, out: *List(*Block) };
            const Cb = struct {
                fn f(c: Cap, bb: *Block) void {
                    if (c.loop.isInsideLoopBlock(bb)) c.out.push(bb);
                }
            };
            cfg.forEachBlockInReversePostOrder(self.header(), Cap{ .loop = self, .out = ordered_loop_blocks }, Cb.f);
        } else {
            // If this is a shader, it is possible that there are unreachable merge and continue blocks that must be
            // copied to retain the structured order. The structured order will include these.
            var order: List(*Block) = .{};
            cfg.computeStructuredOrder(self.header().parent orelse fatal("Loop: header without a function", .{}), self.header(), self.loop_merge, &order);
            for (order.items) |bb| {
                if (self.loop_merge != null and bb == self.loop_merge.?) break;
                ordered_loop_blocks.push(bb);
            }
        }
        if (include_merge) {
            if (self.loop_merge) |m| ordered_loop_blocks.push(m);
        }
    }

    // ---- induction variables and trip count -------------------------------------------------------------------------

    pub fn isSupportedStepOp(_: *const Loop, step: Op) bool {
        return step == .OpISub or step == .OpIAdd;
    }

    pub fn isSupportedCondition(_: *const Loop, condition: Op) bool {
        return switch (condition) {
            .OpULessThan, .OpSLessThan, .OpUGreaterThan, .OpSGreaterThan, .OpSGreaterThanEqual, .OpUGreaterThanEqual, .OpSLessThanEqual, .OpULessThanEqual => true,
            else => false,
        };
    }

    pub fn getInductionStepOperation(self: *const Loop, induction: *const Inst) ?*Inst {
        const ctx: *Ctx = self.ctx;
        const def_use_manager: *DefUseMgr = ctx.getDefUseMgr();
        var step: ?*Inst = null;

        // Traverse the incoming operands of the phi instruction.
        var operand_id: usize = 1;
        while (operand_id < induction.numInOperands()) : (operand_id += 2) {
            // Incoming edge.
            const incoming_block: *Block = ctx.cfg().block(induction.getSingleWordInOperand(operand_id));
            // Check if the block is dominated by header, and thus coming from within the loop.
            if (self.isInsideLoopBlock(incoming_block)) {
                step = def_use_manager.getDef(induction.getSingleWordInOperand(operand_id - 1));
                break;
            }
        }

        const st: *Inst = step orelse return null;
        if (!self.isSupportedStepOp(st.op)) return null;

        // The induction variable which binds the loop must only be modified once.
        const lhs: u32 = st.getSingleWordInOperand(0);
        const rhs: u32 = st.getSingleWordInOperand(1);

        // One of the left hand side or right hand side of the step instruction must be the induction phi and the other
        // must be an OpConstant.
        if (lhs != induction.resultId() and rhs != induction.resultId()) return null;

        if (lpDef(ctx, lhs).op != .OpConstant and lpDef(ctx, rhs).op != .OpConstant) return null;

        return st;
    }

    pub fn getInductionInitValue(self: *const Loop, induction: *const Inst, value: ?*i64) bool {
        const ctx: *Ctx = self.ctx;
        var constant_instruction: ?*Inst = null;
        var operand_id: usize = 0;
        while (operand_id < induction.numInOperands()) : (operand_id += 2) {
            const bb: *Block = ctx.cfg().block(induction.getSingleWordInOperand(operand_id + 1));
            if (!self.isInsideLoopBlock(bb)) {
                constant_instruction = ctx.getDefUseMgr().getDef(induction.getSingleWordInOperand(operand_id));
            }
        }
        const ci: *Inst = constant_instruction orelse return false;
        const constant: *const Constant = ctx.getConstantMgr().findDeclaredConstant(ci.resultId()) orelse return false;
        if (value) |v| {
            const ty: *const TyInteger = constant.ty.as(.integer) orelse return false;
            v.* = if (ty.is_signed) constant.getSignExtendedValue() else @bitCast(constant.getZeroExtendedValue());
        }
        return true;
    }

    /// GetResidualConditionValue
    pub fn getResidualConditionValue(condition: Op, initial_value: i64, step_value: i64, number_of_iterations: usize, factor: usize) i64 {
        const rem: i64 = @intCast(number_of_iterations % factor);
        var remainder: i64 = initial_value +% rem *% step_value;
        // We subtract or add one as the above formula calculates the remainder if the loop where just less than or
        // greater than. Adding or subtracting one should give a functionally equivalent value.
        switch (condition) {
            .OpSGreaterThanEqual, .OpUGreaterThanEqual => remainder -%= 1,
            .OpSLessThanEqual, .OpULessThanEqual => remainder +%= 1,
            else => {},
        }
        return remainder;
    }

    fn llabs(x: i64) i64 {
        return if (x < 0) 0 -% x else x;
    }

    /// GetIterations: number of iterations given the condition, bound, initial value and step (0 when unknown).
    fn getIterations(_: *const Loop, condition: Op, condition_value: i64, init_value: i64, step_value_in: i64) i64 {
        var step_value: i64 = step_value_in;
        if (step_value == 0) return 0;

        var diff: i64 = 0;
        switch (condition) {
            .OpSLessThan, .OpULessThan => {
                // If the condition is not met to begin with the loop will never iterate.
                if (!(init_value < condition_value)) return 0;
                diff = condition_value -% init_value;
                // The diff and step must have the same sign otherwise the induction will never cross the condition.
                if ((diff < 0 and step_value > 0) or (diff > 0 and step_value < 0)) return 0;
            },
            .OpSGreaterThan, .OpUGreaterThan => {
                if (!(init_value > condition_value)) return 0;
                diff = init_value -% condition_value;
                // The diff and step must have opposite signs.
                if ((diff < 0 and step_value < 0) or (diff > 0 and step_value > 0)) return 0;
            },
            .OpSGreaterThanEqual, .OpUGreaterThanEqual => {
                if (!(init_value >= condition_value)) return 0;
                // We subtract one to make it the same as OpGreaterThan as it is functionally equivalent.
                diff = init_value -% (condition_value -% 1);
                if ((diff > 0 and step_value > 0) or (diff < 0 and step_value < 0)) return 0;
            },
            .OpSLessThanEqual, .OpULessThanEqual => {
                if (!(init_value <= condition_value)) return 0;
                // We add one to make it the same as OpLessThan as it is functionally equivalent.
                diff = (condition_value +% 1) -% init_value;
                if ((diff < 0 and step_value > 0) or (diff > 0 and step_value < 0)) return 0;
            },
            else => {}, // assert(false) in the C++; release continues with diff == 0
        }

        // Take the abs of - step values.
        step_value = llabs(step_value);
        diff = llabs(diff);
        var result: i64 = @divTrunc(diff, step_value);
        if (@rem(diff, step_value) != 0) result +%= 1;
        return result;
    }

    pub fn findNumberOfIterations(self: *const Loop, induction: *const Inst, branch_inst: *const Inst, iterations_out: ?*usize, step_value_out: ?*i64, init_value_out: ?*i64) bool {
        const ctx: *Ctx = self.ctx;
        // Condition instruction from the OpConditionalBranch.
        const condition: *Inst = lpDef(ctx, branch_inst.getSingleWordOperand(0));
        const const_manager: *ConstMgr = ctx.getConstantMgr();

        // Find the constant value used by the condition variable. Exit out if it isn't a constant int.
        const upper_bound: *const Constant = const_manager.findDeclaredConstant(condition.getSingleWordOperand(3)) orelse return false;

        // Must be integer because of the opcode on the condition.
        const ty: *const TyInteger = upper_bound.ty.as(.integer) orelse return false;
        if (ty.width > 64) return false;

        const condition_value: i64 = if (ty.is_signed) upper_bound.getSignExtendedValue() else @bitCast(upper_bound.getZeroExtendedValue());

        // Find the instruction which is stepping through the loop.
        const step_inst: *Inst = self.getInductionStepOperation(induction) orelse return false;

        // Find the constant value used by the condition variable.
        const step_constant: *const Constant = const_manager.findDeclaredConstant(step_inst.getSingleWordOperand(3)) orelse return false;
        check(step_constant.kind == .int, "Loop: the induction step constant is not an integer constant");
        const step_type: *const TyInteger = step_constant.ty.as(.integer) orelse fatal("Loop: the induction step constant is not an integer", .{});

        var step_value: i64 = 0;
        if (step_type.is_signed) {
            step_value = step_constant.getS32BitValue();
        } else {
            step_value = step_constant.getU32BitValue();
        }

        // If this is a subtraction step we should negate the step value.
        if (step_inst.op == .OpISub) step_value = 0 -% step_value;

        // Find the initial value of the loop and make sure it is a constant integer.
        var init_value: i64 = 0;
        if (!self.getInductionInitValue(induction, &init_value)) return false;

        const num_itrs: i64 = self.getIterations(condition.op, condition_value, init_value, step_value);

        // If the loop body will not be reached return false.
        if (num_itrs <= 0) return false;

        if (iterations_out) |o| o.* = @intCast(num_itrs);
        if (step_value_out) |o| o.* = step_value;
        if (init_value_out) |o| o.* = init_value;
        return true;
    }

    pub fn getInductionVariables(self: *const Loop) List(*Inst) {
        var out: List(*Inst) = .{};
        var it: ?*Inst = self.header().insts.first;
        while (it) |inst| : (it = inst.next) {
            if (inst.op == .OpPhi) out.push(inst);
        }
        return out;
    }

    /// FindConditionBlock: the block with a branch to the merge block and the continue block within the loop body.
    pub fn findConditionBlock(self: *const Loop) ?*Block {
        const merge: *Block = self.loop_merge orelse return null;
        var in_loop_pred: u32 = 0;
        for (self.ctx.cfg().preds(merge.id())) |p| {
            if (self.isInsideLoopId(p)) {
                if (in_loop_pred != 0) return null; // 2 in-loop predecessors.
                in_loop_pred = p;
            }
        }
        if (in_loop_pred == 0) return null; // Merge block is unreachable.

        const bb: *Block = self.ctx.cfg().block(in_loop_pred);
        const branch: *Inst = bb.tail();

        // Make sure the branch is a conditional branch.
        if (branch.op != .OpBranchConditional) return null;

        // Make sure one of the two possible branches is to the merge block.
        if (branch.getSingleWordInOperand(1) == merge.id() or branch.getSingleWordInOperand(2) == merge.id()) return bb;
        return null;
    }

    /// FindConditionVariable: the induction phi that bounds the loop through `condition_block`, or null.
    pub fn findConditionVariable(self: *const Loop, condition_block: *const Block) ?*Inst {
        const ctx: *Ctx = self.ctx;
        const branch_inst: *Inst = condition_block.tail();
        // Verify that the branch instruction is a conditional branch.
        if (branch_inst.op != .OpBranchConditional) return null;

        // Find the instruction representing the condition used in the conditional branch.
        const condition: *Inst = ctx.getDefUseMgr().getDef(branch_inst.getSingleWordOperand(0)) orelse return null;

        // Ensure that the condition is a less than operation.
        if (!self.isSupportedCondition(condition.op)) return null;

        // The left hand side operand of the operation.
        const variable_inst: *Inst = ctx.getDefUseMgr().getDef(condition.getSingleWordOperand(2)) orelse return null;

        // Make sure the variable instruction used is a phi.
        if (variable_inst.op != .OpPhi) return null;

        // Make sure the phi instruction only has two incoming blocks: one from the preheader, one from the latch.
        const max_supported_operands: usize = 4;
        if (variable_inst.numInOperands() == max_supported_operands) {
            const operand_label_1: usize = 1;
            const operand_label_2: usize = 3;

            // Make sure one of them is the preheader.
            if (!self.isInsideLoopId(variable_inst.getSingleWordInOperand(operand_label_1)) and
                !self.isInsideLoopId(variable_inst.getSingleWordInOperand(operand_label_2)))
            {
                return null;
            }

            // And make sure that the other is the latch block.
            const latch_id: u32 = (self.loop_latch orelse fatal("Loop: no latch block", .{})).id();
            if (variable_inst.getSingleWordInOperand(operand_label_1) != latch_id and
                variable_inst.getSingleWordInOperand(operand_label_2) != latch_id)
            {
                return null;
            }
        } else {
            return null;
        }

        if (!self.findNumberOfIterations(variable_inst, branch_inst, null, null, null)) return null;
        return variable_inst;
    }

    /// GetConditionInst: the condition of the loop entry branch, or null.
    pub fn getConditionInst(self: *const Loop) ?*Inst {
        const condition_block: *Block = self.findConditionBlock() orelse return null;
        const branch_conditional: *Inst = condition_block.tail();
        if (branch_conditional.op != .OpBranchConditional) return null;
        const condition_inst: *Inst = lpDef(self.ctx, branch_conditional.getSingleWordInOperand(0));
        if (self.isSupportedCondition(condition_inst.op)) return condition_inst;
        return null;
    }
};

/// The nodes of the tree rooted at |root| in post-order (root last), like PostOrderTreeDFIterator<Loop>::begin(root).
fn loopPostOrder(root: *Loop, out: *List(*Loop)) void {
    for (root.nested_loops.items) |child| loopPostOrder(child, out);
    out.push(root);
}

/// A loop created by a pass, waiting to be added to the descriptor under its parent.
const LoopToAdd = struct { parent: ?*Loop, loop: *Loop };

/// The loops of one function, found from its structured control flow: the nesting, and the innermost loop of each block.
pub const LoopDescriptor = struct {
    ctx: *Ctx,
    loops: List(*Loop) = .{},
    placeholder_top_loop: *Loop,
    basic_block_to_loop: Map(u32, ?*Loop) = .{},
    loops_to_add: List(LoopToAdd) = .{},

    pub fn create(ctx: *Ctx, f: *Func) *LoopDescriptor {
        const d = scAllocator().create(LoopDescriptor) catch oom();
        d.* = .{ .ctx = ctx, .placeholder_top_loop = Loop.create(ctx) };
        d.populateList(f);
        return d;
    }

    fn populateList(self: *LoopDescriptor, f: *Func) void {
        const ctx: *Ctx = self.ctx;
        const dom_analysis: *DominatorAnalysis = ctx.getDominatorAnalysis(f);
        const cfg: *Cfg = ctx.cfg();

        self.loops.clear();

        // Post-order traversal of the dominator tree to find all the OpLoopMerge instructions.
        const dom_tree: *DomTree = dom_analysis.getDomTree();
        const post_nodes: List(*DomNode) = dom_tree.nodesPostOrder();
        for (post_nodes.items) |node| {
            const merge_inst: *Inst = node.bb.getLoopMergeInst() orelse continue;
            var all_backedge_unreachable: bool = true;
            for (cfg.preds(node.bb.id())) |pid| {
                if (dom_analysis.isReachableId(pid) and dom_analysis.dominatesId(node.bb.id(), pid)) {
                    all_backedge_unreachable = false;
                    break;
                }
            }
            if (all_backedge_unreachable) continue; // ignore this one, we actually never branch back.

            // The id of the merge basic block of this loop.
            const merge_bb_id: u32 = merge_inst.getSingleWordOperand(0);
            // The id of the continue basic block of this loop.
            const continue_bb_id: u32 = merge_inst.getSingleWordOperand(1);
            // The merge target of this loop.
            const merge_bb: *Block = cfg.block(merge_bb_id);
            // The continue target of this loop.
            const continue_bb: *Block = cfg.block(continue_bb_id);
            // The basic block containing the merge instruction.
            const header_bb: *Block = ctx.getInstrBlock(merge_inst) orelse fatal("LoopDescriptor: OpLoopMerge outside a block", .{});

            // Add the loop to the list of all the loops in the function.
            const current_loop: *Loop = Loop.createFull(ctx, dom_analysis, header_bb, continue_bb, merge_bb);
            self.loops.push(current_loop);

            // We have a bottom-up construction, so if this loop has nested-loops, they are by construction at the
            // tail of the loop list.
            var k: usize = self.loops.len() - 1;
            while (k > 0) {
                k -= 1;
                const previous_loop: *Loop = self.loops.items[k];

                // If the loop already has a parent, then it has been processed.
                if (previous_loop.hasParent()) continue;

                // If the current loop does not dominates the previous loop then it is not nested loop.
                if (!dom_analysis.dominates(header_bb, previous_loop.header())) continue;
                // If the current loop merge dominates the previous loop then it is not nested loop.
                if (dom_analysis.dominates(merge_bb, previous_loop.header())) continue;

                current_loop.addNestedLoop(previous_loop);
            }
            const dom_merge_node: ?*DomNode = dom_tree.getTreeNodeOf(merge_bb);
            var subtree: List(*DomNode) = .{};
            treeDfsPreOrder(node, &subtree);
            for (subtree.items) |loop_node| {
                // Check if we are in the loop.
                if (dom_tree.dominatesNode(dom_merge_node, loop_node)) continue;
                current_loop.addBasicBlock(loop_node.bb.id());
                const gop: Map(u32, ?*Loop).GetOrPutResult = self.basic_block_to_loop.getOrPut(loop_node.bb.id());
                if (!gop.found_existing) gop.value_ptr.* = current_loop;
            }
        }
        for (self.loops.items) |loop| {
            if (!loop.hasParent()) self.placeholder_top_loop.nested_loops.push(loop);
        }
    }

    pub fn numLoops(self: *const LoopDescriptor) usize {
        return self.loops.len();
    }

    pub fn getLoopByIndex(self: *const LoopDescriptor, index: usize) *Loop {
        return self.loops.items[index];
    }

    /// The loops in the order their headers appear in the binary.
    pub fn getLoopsInBinaryLayoutOrder(self: *const LoopDescriptor) List(*Loop) {
        var loops: List(*Loop) = .{};
        if (self.loops.len() == 0) return loops;
        const function: *Func = self.getLoopByIndex(0).header().parent orelse fatal("LoopDescriptor: header without a function", .{});
        for (function.blocks.items) |block| {
            for (self.loops.items) |l| {
                if (l.header().id() == block.id()) {
                    loops.push(l);
                    break;
                }
            }
        }
        return loops;
    }

    /// The innermost loop that contains the basic block id (operator[]).
    pub fn findLoopForBasicBlock(self: *const LoopDescriptor, block_id: u32) ?*Loop {
        const e: ?*Loop = self.basic_block_to_loop.get(block_id) orelse return null;
        return e;
    }

    fn postOrderFrom(node: *Loop, out: *List(*Loop)) void {
        for (node.nested_loops.items) |c| {
            postOrderFrom(c, out);
            out.push(c);
        }
    }

    /// The loops in depth first post-order (innermost first), without the placeholder root (begin()..end()).
    pub fn postOrderLoops(self: *const LoopDescriptor, out: *List(*Loop)) void {
        postOrderFrom(self.placeholder_top_loop, out);
    }

    pub fn setBasicBlockToLoop(self: *LoopDescriptor, bb_id: u32, loop: ?*Loop) void {
        self.basic_block_to_loop.put(bb_id, loop);
    }

    pub fn forgetBasicBlock(self: *LoopDescriptor, bb_id: u32) void {
        _ = self.basic_block_to_loop.remove(bb_id);
    }

    pub fn addLoop(self: *LoopDescriptor, loop_to_add: *Loop, parent: ?*Loop) void {
        self.loops_to_add.push(.{ .parent = parent, .loop = loop_to_add });
    }

    /// AddLoopNest: registers |new_loop| and its nested loops (post-order, inner loops first); blocks already mapped to a loop
    /// keep their mapping (std::unordered_map::insert does not overwrite).
    pub fn addLoopNest(self: *LoopDescriptor, new_loop: *Loop) void {
        if (new_loop.parent == null) self.placeholder_top_loop.nested_loops.push(new_loop);
        var order: List(*Loop) = .{};
        loopPostOrder(new_loop, &order);
        for (order.items) |current_loop| {
            self.loops.push(current_loop);
            for (current_loop.loop_basic_blocks.items()) |bb_id| {
                const gop: Map(u32, ?*Loop).GetOrPutResult = self.basic_block_to_loop.getOrPut(bb_id);
                if (!gop.found_existing) gop.value_ptr.* = current_loop;
            }
        }
    }

    /// CreatePreHeaderBlocksIfMissing
    pub fn createPreHeaderBlocksIfMissing(self: *LoopDescriptor) PassStatus {
        var modified: bool = false;
        var order: List(*Loop) = .{};
        self.postOrderLoops(&order);
        for (order.items) |loop| {
            if (loop.loop_preheader == null) {
                if (loop.getOrCreatePreHeaderBlock() == null) return .failure;
                modified = true;
            }
        }
        return if (modified) .success_with_change else .success_without_change;
    }

    /// PostModificationCleanup: adds and removes the loops marked for addition and removal.
    pub fn postModificationCleanup(self: *LoopDescriptor) void {
        var loops_to_remove: List(*Loop) = .{};
        for (self.loops.items) |loop| {
            if (loop.isMarkedForRemoval()) {
                loops_to_remove.push(loop);
                if (loop.parent) |p| p.removeChildLoop(loop);
            }
        }

        for (loops_to_remove.items) |loop| {
            const at: usize = self.loops.indexOf(loop) orelse fatal("LoopDescriptor: loop to remove is not registered", .{});
            _ = self.loops.orderedRemove(at);
        }

        for (self.loops_to_add.items) |pair| {
            const loop: *Loop = pair.loop;
            if (pair.parent) |parent| {
                loop.parent = null;
                parent.addNestedLoop(loop);
                for (loop.loop_basic_blocks.items()) |block_id| parent.addBasicBlock(block_id);
            }
            self.loops.push(loop);
        }
        self.loops_to_add.clear();
    }

    /// RemoveLoop
    pub fn removeLoop(self: *LoopDescriptor, loop: *Loop) void {
        const parent: *Loop = loop.parent orelse self.placeholder_top_loop;
        const at: usize = parent.nested_loops.indexOf(loop) orelse fatal("LoopDescriptor.removeLoop: loop is not a child of its parent", .{});
        _ = parent.nested_loops.orderedRemove(at);
        for (loop.nested_loops.items) |sub_loop| sub_loop.parent = loop.parent;
        parent.nested_loops.pushSlice(loop.nested_loops.items);
        for (loop.loop_basic_blocks.items()) |bb_id| {
            const l: ?*Loop = self.findLoopForBasicBlock(bb_id);
            if (l != null and l.? == loop) {
                self.setBasicBlockToLoop(bb_id, loop.parent);
            } else {
                self.forgetBasicBlock(bb_id);
            }
        }
        const it: usize = self.loops.indexOf(loop) orelse fatal("LoopDescriptor.removeLoop: loop is not registered", .{});
        _ = self.loops.orderedRemove(it);
    }
};

/// CFG::SplitLoopHeader: splits the loop header `bb` so that `bb` becomes the pre-header (keeps only a copy of the
/// phis and a branch) and the new header (returned) holds the loop body start, the merge instruction and the
/// back-edge phi inputs.
pub fn cfgSplitLoopHeader(ctx: *Ctx, bb: *Block) ?*Block {
    check(bb.getLoopMergeInst() != null, "Expecting bb to be the header of a loop.");
    const cfg: *Cfg = ctx.cfg();
    const fn_: *Func = bb.parent orelse fatal("SplitLoopHeader: block has no parent", .{});

    // Get the new header id up front (id overflow is fatal in this port).
    const new_header_id: u32 = ctx.takeNextId();

    // Find the insertion point for the new bb and the latch block.
    var header_idx: usize = 0;
    while (header_idx < fn_.blocks.len() and fn_.blocks.items[header_idx] != bb) header_idx += 1;
    check(header_idx < fn_.blocks.len(), "SplitLoopHeader: header not found in its function");

    const pred: []const u32 = cfg.preds(bb.id());
    // Find the back edge. If blocks are in the proper order, the only branch that appears after the header is the latch.
    var latch_idx: usize = header_idx;
    while (latch_idx < fn_.blocks.len()) : (latch_idx += 1) {
        var found: bool = false;
        for (pred) |p| {
            if (p == fn_.blocks.items[latch_idx].id()) found = true;
        }
        if (found) break;
    }
    check(latch_idx < fn_.blocks.len(), "Could not find the latch.");
    var latch_block: *Block = fn_.blocks.items[latch_idx];

    cfg.removeSuccessorEdges(bb);

    // Create the new header bb. Leave the phi instructions behind.
    const iter: ?*Inst = firstNonPhi(bb);
    const new_header: *Block = blockSplit(ctx, bb, new_header_id, iter);
    ctx.analyzeDefUse(new_header.label);

    // Update cfg
    cfg.registerBlock(new_header);

    // If |bb| was the latch block, the branch back to the header is not in |new_header|.
    if (latch_block == bb) {
        if (new_header.continueBlockId() == bb.id()) {
            new_header.getLoopMergeInst().?.setInOperand(1, &.{new_header_id});
        }
        latch_block = new_header;
    }

    // Adjust the OpPhi instructions as needed.
    var it: ?*Inst = bb.insts.first;
    while (it) |phi| {
        const nxt: ?*Inst = phi.next;
        if (phi.op != .OpPhi) break;
        var preheader_phi_ops: List(u32) = .{};
        var header_phi_ops: List(Operand) = .{};

        // Identify where the original inputs to the original OpPhi belong: header or preheader.
        var i: usize = 0;
        while (i < phi.numInOperands()) : (i += 2) {
            const def_id: u32 = phi.getSingleWordInOperand(i);
            const branch_id: u32 = phi.getSingleWordInOperand(i + 1);
            if (branch_id == latch_block.id()) {
                header_phi_ops.push(Operand.id(.IdRef, def_id));
                header_phi_ops.push(Operand.id(.IdRef, branch_id));
            } else {
                preheader_phi_ops.push(def_id);
                preheader_phi_ops.push(branch_id);
            }
        }

        // Create a phi instruction if and only if the preheader_phi_ops has more than one pair.
        if (preheader_phi_ops.len() > 2) {
            const builder = InstBuilder.init(ctx, bb.insts.first.?, Analysis.def_use | Analysis.instr_to_block);
            const new_phi: *Inst = builder.addPhi(phi.typeId(), preheader_phi_ops.items, 0) orelse return null;
            // Add the OpPhi to the header bb.
            header_phi_ops.push(Operand.id(.IdRef, new_phi.resultId()));
            header_phi_ops.push(Operand.id(.IdRef, bb.id()));
        } else {
            // An OpPhi with a single entry is just a copy: use the same value in the new header.
            check(preheader_phi_ops.len() > 0, "SplitLoopHeader: loop header phi without a pre-header input");
            header_phi_ops.push(Operand.id(.IdRef, preheader_phi_ops.items[0]));
            header_phi_ops.push(Operand.id(.IdRef, bb.id()));
        }

        _ = phi.removeFromList();
        phi.setInOperands(header_phi_ops.items);
        _ = new_header.insts.first.?.insertBefore(phi);
        ctx.analyzeUses(phi);
        it = nxt;
    }

    // Add a branch to the new header.
    const br: *Inst = Inst.make(.OpBranch, 0, 0, &.{Operand.id(.IdRef, new_header.id())});
    bb.addInst(br);
    ctx.analyzeUses(br);
    cfg.addEdge(bb.id(), new_header.id());

    // Update the latch to branch to the new header.
    latch_block.forEachSuccessorLabelMut(LatchRedirect{ .old_id = bb.id(), .new_id = new_header_id }, latchRedirectCb);
    ctx.analyzeUses(latch_block.tail());
    cfg.addEdge(latch_block.id(), new_header.id());

    const block_preds: *List(u32) = cfg.label2preds.getPtr(bb.id()) orelse fatal("SplitLoopHeader: the cfg was invalid", .{});
    const latch_pos: usize = block_preds.indexOf(latch_block.id()) orelse fatal("SplitLoopHeader: the cfg was invalid (latch not a predecessor)", .{});
    _ = block_preds.orderedRemove(latch_pos);

    // Update the loop descriptors
    if (ctx.areAnalysesValid(Analysis.loops)) {
        const loop_desc: *LoopDescriptor = ctx.getLoopDescriptor(bb.parent orelse fatal("SplitLoopHeader: block has no parent", .{}));
        const loop: *Loop = loop_desc.findLoopForBasicBlock(bb.id()) orelse fatal("SplitLoopHeader: the header is not in a loop of the descriptor", .{});

        loop.addBasicBlock(new_header_id);
        loop.loop_header = new_header;
        loop_desc.setBasicBlockToLoop(new_header_id, loop);

        loop.removeBasicBlock(bb.id());
        loop.setPreHeaderBlock(bb);

        if (loop.parent) |parent_loop| {
            parent_loop.addBasicBlock(bb.id());
            loop_desc.setBasicBlockToLoop(bb.id(), parent_loop);
        } else {
            loop_desc.setBasicBlockToLoop(bb.id(), null);
        }
    }
    return new_header;
}

/// One node of a scalar expression (a DAG): a constant, a recurrence `{offset,+,coefficient}` over a loop, a sum, a product,
/// a negation, an unknown value (`result_id`) or `cant_compute`. The children of a node are sorted by decreasing unique id.
pub const SENode = struct {
    kind: SENodeKind,
    unique_id: u32,
    parent: *ScalarEvolutionAnalysis,
    children: List(*SENode) = .{},
    value: i64 = 0, // constant
    result_id: u32 = 0, // value unknown
    loop: ?*const Loop = null, // recurrent
    coefficient: ?*SENode = null, // recurrent
    offset: ?*SENode = null, // recurrent

    /// SENode::AddChild: keep the children sorted by decreasing unique id (equal ids: after the existing ones).
    pub fn addChild(self: *SENode, child: *SENode) void {
        if (self.kind == .constant) return; // assert(false) in the C++ (no-op in release); constants have no children
        var pos: usize = 0;
        while (pos < self.children.len() and child.unique_id <= self.children.items[pos].unique_id) pos += 1;
        self.children.insert(pos, child);
    }

    pub fn addCoefficient(self: *SENode, child: *SENode) void {
        self.coefficient = child;
        self.addChild(child);
    }

    pub fn addOffset(self: *SENode, child: *SENode) void {
        self.offset = child;
        self.addChild(child);
    }

    pub fn getChild(self: *const SENode, index: usize) *SENode {
        return self.children.items[index];
    }

    pub fn isCantCompute(self: *const SENode) bool {
        return self.kind == .cant_compute;
    }

    pub fn asConstant(self: *const SENode) ?i64 {
        if (self.kind == .constant) return self.value;
        return null;
    }

    pub fn coeff(self: *const SENode) *SENode {
        return self.coefficient orelse fatal("scalar evolution: recurrent node without coefficient", .{});
    }

    pub fn off(self: *const SENode) *SENode {
        return self.offset orelse fatal("scalar evolution: recurrent node without offset", .{});
    }

    /// SENode::operator== (children compared by pointer; recurrent nodes by loop, coefficient and offset).
    pub fn structurallyEqual(self: *const SENode, other: *const SENode) bool {
        if (self.kind != other.kind) return false;
        if (other.children.len() != self.children.len()) return false;
        if (self.kind != .recurrent_add_expr) {
            for (self.children.items, 0..) |c, i| {
                if (other.children.items[i] != c) return false;
            }
        } else {
            if (self.coefficient != other.coefficient) return false;
            if (self.offset != other.offset) return false;
            if (self.loop != other.loop) return false;
        }
        if (self.kind == .value_unknown and self.result_id != other.result_id) return false;
        if (self.kind == .constant and self.value != other.value) return false;
        return true;
    }

    /// Pre-order walk of the DAG rooted here (TreeDFIterator: shared nodes are visited once per path). `f` returns false
    /// to stop; the result is false when it was stopped.
    pub fn walk(self: *SENode, ctx: anytype, comptime f: fn (@TypeOf(ctx), *SENode) bool) bool {
        if (!f(ctx, self)) return false;
        for (self.children.items) |c| {
            if (!c.walk(ctx, f)) return false;
        }
        return true;
    }
};

/// Hash and equality of the node cache: two nodes are the same when their kind, value, children (and loop, coefficient and
/// offset for a recurrence) are the same.
const SeCacheCtx = struct {
    pub fn hash(_: SeCacheCtx, n: *SENode) u64 {
        var h: std.hash.Wyhash = std.hash.Wyhash.init(0);
        h.update(std.mem.asBytes(&@as(u32, @intFromEnum(n.kind))));
        if (n.kind == .constant) h.update(std.mem.asBytes(&n.value));
        if (n.kind == .recurrent_add_expr) {
            h.update(std.mem.asBytes(&@intFromPtr(n.loop)));
            h.update(std.mem.asBytes(&@intFromPtr(n.coefficient)));
            h.update(std.mem.asBytes(&@intFromPtr(n.offset)));
            return h.final();
        }
        if (n.kind == .value_unknown) h.update(std.mem.asBytes(&n.result_id));
        for (n.children.items) |c| h.update(std.mem.asBytes(&@intFromPtr(c)));
        return h.final();
    }

    pub fn eql(_: SeCacheCtx, a: *SENode, b: *SENode) bool {
        return a.structurallyEqual(b);
    }
};

/// The nodes created so far, by structure: building an expression twice gives the same node.
const SeNodeCache = std.HashMapUnmanaged(*SENode, void, SeCacheCtx, 80);

/// Decides whether an expression is greater than (or equal to) zero, from the signs of its parts.
const SeIsGreaterThanZero = struct {
    ctx: *Ctx,

    /// IsGreaterThanZero::Eval: true when the sign could be determined (the answer is in `result`).
    fn eval(self: SeIsGreaterThanZero, node: *const SENode, or_equal_zero: bool, result: *bool) bool {
        result.* = false;
        switch (self.visit(node)) {
            .positive_or_negative => return false,
            .strictly_negative => result.* = false,
            .negative => {
                if (!or_equal_zero) return false;
                result.* = false;
            },
            .strictly_positive => result.* = true,
            .positive => {
                if (!or_equal_zero) return false;
                result.* = true;
            },
        }
        return true;
    }

    fn visit(self: SeIsGreaterThanZero, node: *const SENode) SeSign {
        switch (node.kind) {
            .constant => {
                if (node.value == 0) return .positive;
                if (node.value > 0) return .strictly_positive;
                return .strictly_negative;
            },
            .recurrent_add_expr => {
                var coeff_sign: SeSign = self.visit(node.coeff());
                // SERecurrentNode represent an affine expression in the range [0, loop_bound], so the result cannot be
                // strictly positive or negative.
                switch (coeff_sign) {
                    .strictly_negative => coeff_sign = .negative,
                    .strictly_positive => coeff_sign = .positive,
                    else => {},
                }
                return seAddCombine(coeff_sign, self.visit(node.off()));
            },
            .negative => {
                return switch (self.visit(node.children.items[0])) {
                    .positive_or_negative => .positive_or_negative,
                    .strictly_negative => .strictly_positive,
                    .negative => .positive,
                    .strictly_positive => .strictly_negative,
                    .positive => .negative,
                };
            },
            .cant_compute => return .positive_or_negative,
            .value_unknown => {
                const insn: *Inst = self.ctx.getDefUseMgr().getDef(node.result_id) orelse fatal("SE: value unknown %{d} has no definition", .{node.result_id});
                const ty: *Type = self.ctx.getTypeMgr().getType(insn.typeId()) orelse fatal("SE: no type for %{d}", .{node.result_id});
                const int_type: *const TyInteger = ty.as(.integer) orelse fatal("SE: %{d} is not an integer (the C++ dereferences null)", .{node.result_id});
                return if (int_type.is_signed) .positive_or_negative else .positive;
            },
            .add => return self.visitExpr(node, seAddCombine),
            .multiply => return self.visitExpr(node, seMulCombine),
        }
    }

    fn visitExpr(self: SeIsGreaterThanZero, node: *const SENode, comptime reduce: fn (SeSign, SeSign) SeSign) SeSign {
        var result: SeSign = self.visit(node.children.items[0]);
        for (node.children.items[1..]) |operand| {
            if (result == .positive_or_negative) return .positive_or_negative;
            result = reduce(result, self.visit(operand));
        }
        return result;
    }
};

/// RemoveOneNodeFromMultiplyChain (anonymous namespace of scalar_analysis.cpp), including its asymmetric rhs branch.
fn seRemoveOneNodeFromMultiplyChain(mul: *SENode, node: *const SENode) *SENode {
    const lhs: *SENode = mul.children.items[0];
    const rhs: *SENode = mul.children.items[1];
    if (lhs == node) return rhs;
    if (rhs == node) return lhs;
    if (lhs.kind == .multiply) {
        const res: *SENode = seRemoveOneNodeFromMultiplyChain(lhs, node);
        if (res != lhs) return mul.parent.createMultiplyNode(res, rhs);
    }
    if (rhs.kind == .multiply) {
        const res: *SENode = seRemoveOneNodeFromMultiplyChain(rhs, node);
        if (res != rhs) return mul.parent.createMultiplyNode(res, rhs);
    }
    return mul;
}

/// The result of dividing an expression by a constant: the quotient and the remainder.
pub const SeDivResult = struct { node: *SENode, remainder: i64 };

/// Builds and caches the scalar expression of each id of a loop nest, with the operators that combine expressions
/// (sxAdd, sxMul, ...) and the comparisons that the loop passes ask for.
pub const ScalarEvolutionAnalysis = struct {
    ctx: *Ctx,
    recurrent_node_map: Map(*const Inst, *SENode) = .{},
    cached_cant_compute: *SENode = undefined,
    node_cache: SeNodeCache = .empty,
    pretend_equal: Map(*const Loop, *const Loop) = .{},

    const Self = @This();

    pub fn create(ctx: *Ctx) *Self {
        const a: *ScalarEvolutionAnalysis = scAllocator().create(Self) catch oom();
        a.* = .{ .ctx = ctx };
        // Create and cache the CantComputeNode.
        a.cached_cant_compute = a.getCachedOrAdd(a.newNode(.cant_compute));
        return a;
    }

    /// `new SEXxxNode(this)`: the unique id is taken here.
    pub fn newNode(self: *Self, kind: SENodeKind) *SENode {
        const n = scAllocator().create(SENode) catch oom();
        se_number_of_nodes += 1;
        n.* = .{ .kind = kind, .unique_id = se_number_of_nodes, .parent = self };
        return n;
    }

    pub fn newConstantNode(self: *Self, value: i64) *SENode {
        const n: *SENode = self.newNode(.constant);
        n.value = value;
        return n;
    }

    pub fn newRecurrentNode(self: *Self, loop: ?*const Loop) *SENode {
        const n: *SENode = self.newNode(.recurrent_add_expr);
        n.loop = loop;
        return n;
    }

    /// Add the created node into the cache of nodes. If it already exists return the cached one.
    pub fn getCachedOrAdd(self: *Self, prospective_node: *SENode) *SENode {
        const r: std.HashMapUnmanaged(*SENode, void, SeCacheCtx, 80).GetOrPutResult = self.node_cache.getOrPutContext(scAllocator(), prospective_node, SeCacheCtx{}) catch oom();
        if (!r.found_existing) r.key_ptr.* = prospective_node; // the key slot is undefined for a new entry
        return r.key_ptr.*;
    }

    pub fn createNegation(self: *Self, operand: *SENode) *SENode {
        // If operand is can't compute then the whole graph is can't compute.
        if (operand.isCantCompute()) return self.createCantComputeNode();
        if (operand.kind == .constant) return self.createConstant(0 -% operand.value);
        const negation_node: *SENode = self.newNode(.negative);
        negation_node.addChild(operand);
        return self.getCachedOrAdd(negation_node);
    }

    pub fn createConstant(self: *Self, integer: i64) *SENode {
        return self.getCachedOrAdd(self.newConstantNode(integer));
    }

    pub fn createRecurrentExpression(self: *Self, loop: *const Loop, offset: *SENode, coefficient: *SENode) *SENode {
        // If operands are can't compute then the whole graph is can't compute.
        if (offset.isCantCompute() or coefficient.isCantCompute()) return self.createCantComputeNode();

        const loop_to_use: *const Loop = self.pretend_equal.get(loop) orelse loop;

        const phi_node: *SENode = self.newRecurrentNode(loop_to_use);
        phi_node.addOffset(offset);
        phi_node.addCoefficient(coefficient);

        return self.getCachedOrAdd(phi_node);
    }

    pub fn createMultiplyNode(self: *Self, operand_1: *SENode, operand_2: *SENode) *SENode {
        // If operands are can't compute then the whole graph is can't compute.
        if (operand_1.isCantCompute() or operand_2.isCantCompute()) return self.createCantComputeNode();

        if (operand_1.kind == .constant and operand_2.kind == .constant) {
            return self.createConstant(operand_1.value *% operand_2.value);
        }

        const multiply_node: *SENode = self.newNode(.multiply);
        multiply_node.addChild(operand_1);
        multiply_node.addChild(operand_2);
        return self.getCachedOrAdd(multiply_node);
    }

    pub fn createSubtraction(self: *Self, operand_1: *SENode, operand_2: *SENode) *SENode {
        // Fold if both operands are constant.
        if (operand_1.kind == .constant and operand_2.kind == .constant) {
            return self.createConstant(operand_1.value -% operand_2.value);
        }
        return self.createAddNode(operand_1, self.createNegation(operand_2));
    }

    pub fn createAddNode(self: *Self, operand_1: *SENode, operand_2: *SENode) *SENode {
        // Fold if both operands are constant.
        if (operand_1.kind == .constant and operand_2.kind == .constant) {
            return self.createConstant(operand_1.value +% operand_2.value);
        }

        // If operands are can't compute then the whole graph is can't compute.
        if (operand_1.isCantCompute() or operand_2.isCantCompute()) return self.createCantComputeNode();

        const add_node: *SENode = self.newNode(.add);
        add_node.addChild(operand_1);
        add_node.addChild(operand_2);
        return self.getCachedOrAdd(add_node);
    }

    pub fn createValueUnknownNode(self: *Self, inst: *const Inst) *SENode {
        const load_node: *SENode = self.newNode(.value_unknown);
        load_node.result_id = inst.resultId();
        return self.getCachedOrAdd(load_node);
    }

    pub fn createCantComputeNode(self: *Self) *SENode {
        return self.cached_cant_compute;
    }

    // ---- instruction analysis -------------------------------------------------------------------------------------

    pub fn analyzeInstruction(self: *Self, inst: *const Inst) *SENode {
        if (self.recurrent_node_map.get(inst)) |n| return n;

        return switch (inst.op) {
            .OpPhi => self.analyzePhiInstruction(inst),
            .OpConstant, .OpConstantNull => self.analyzeConstant(inst),
            .OpISub, .OpIAdd => self.analyzeAddOp(inst),
            .OpIMul => self.analyzeMultiplyOp(inst),
            else => self.createValueUnknownNode(inst),
        };
    }

    fn defOf(self: *Self, id: u32) *Inst {
        return self.ctx.getDefUseMgr().getDef(id) orelse fatal("scalar evolution: %{d} has no definition", .{id});
    }

    fn analyzeConstant(self: *Self, inst: *const Inst) *SENode {
        if (inst.op == .OpConstantNull) return self.createConstant(0);

        // Look up the instruction in the constant manager.
        const constant: *const Constant = self.ctx.getConstantMgr().findDeclaredConstant(inst.resultId()) orelse return self.createCantComputeNode();

        // Exit out if it is a 64 bit integer.
        if (constant.kind != .int or constant.words.len() != 1) return self.createCantComputeNode();

        const int_type: *const TyInteger = constant.ty.as(.integer) orelse fatal("scalar evolution: integer constant of a non integer type", .{});
        const value: i64 = if (int_type.is_signed) constant.getS32BitValue() else constant.getU32BitValue();
        return self.createConstant(value);
    }

    /// Handles both addition and subtraction.
    fn analyzeAddOp(self: *Self, inst: *const Inst) *SENode {
        const op1: *SENode = self.analyzeInstruction(self.defOf(inst.getSingleWordInOperand(0)));
        var op2: *SENode = self.analyzeInstruction(self.defOf(inst.getSingleWordInOperand(1)));

        // To handle subtraction we wrap the second operand in a unary negation node.
        if (inst.op == .OpISub) op2 = self.createNegation(op2);

        return self.createAddNode(op1, op2);
    }

    fn analyzeMultiplyOp(self: *Self, multiply: *const Inst) *SENode {
        const op1: *SENode = self.analyzeInstruction(self.defOf(multiply.getSingleWordInOperand(0)));
        const op2: *SENode = self.analyzeInstruction(self.defOf(multiply.getSingleWordInOperand(1)));
        return self.createMultiplyNode(op1, op2);
    }

    fn analyzePhiInstruction(self: *Self, phi: *const Inst) *SENode {
        // The phi should only have two incoming value pairs.
        if (phi.numInOperands() != 4) return self.createCantComputeNode();

        // Get the basic block this instruction belongs to, then its function and the function's loop descriptor.
        const basic_block: *Block = self.ctx.getInstrBlock(phi) orelse fatal("scalar evolution: phi %{d} is not in a block", .{phi.resultId()});
        const function: *Func = basic_block.parent orelse fatal("scalar evolution: block %{d} is not in a function", .{basic_block.id()});
        const loop_descriptor: *LoopDescriptor = self.ctx.getLoopDescriptor(function);

        // Get the innermost loop which this block belongs to.
        const loop: ?*Loop = loop_descriptor.findLoopForBasicBlock(basic_block.id());

        // If the loop doesn't exist or doesn't have a preheader or latch block, exit out.
        if (loop == null or loop.?.loop_latch == null or loop.?.loop_preheader == null or loop.?.header() != basic_block) {
            const cc: *SENode = self.createCantComputeNode();
            self.recurrent_node_map.put(phi, cc);
            return cc;
        }
        const lp: *Loop = loop.?;

        const loop_to_use: *const Loop = self.pretend_equal.get(lp) orelse lp;
        const phi_node: *SENode = self.newRecurrentNode(loop_to_use);

        // We add the node to this map to allow it to be returned before the node is fully built (the analysis of the
        // operands can lead back to this |phi|).
        self.recurrent_node_map.put(phi, phi_node);

        // Traverse the operands of the instruction and create new nodes for each one.
        var i: u32 = 0;
        while (i < phi.numInOperands()) : (i += 2) {
            const value_id: u32 = phi.getSingleWordInOperand(i);
            const incoming_label_id: u32 = phi.getSingleWordInOperand(i + 1);

            const value_inst: *Inst = self.defOf(value_id);
            const value_node: *SENode = self.analyzeInstruction(value_inst);

            // If any operand is CantCompute then the whole graph is CantCompute.
            if (value_node.isCantCompute()) return self.phiCantCompute(phi);

            if (incoming_label_id == lp.loop_preheader.?.id()) {
                // If the value is coming from the preheader block then the value is the initial value of the phi.
                phi_node.addOffset(value_node);
            } else if (incoming_label_id == lp.loop_latch.?.id()) {
                // Assumed to be in the form of step + phi.
                if (value_node.kind != .add) return self.phiCantCompute(phi);

                var step_node: ?*SENode = null;
                var phi_operand: ?*SENode = null;
                const operand_1: *SENode = value_node.getChild(0);
                const operand_2: *SENode = value_node.getChild(1);

                // Find which node is the step term.
                if (operand_1.kind != .recurrent_add_expr) {
                    step_node = operand_1;
                } else if (operand_2.kind != .recurrent_add_expr) {
                    step_node = operand_2;
                }

                // Find which node is the recurrent expression.
                if (operand_1.kind == .recurrent_add_expr) {
                    phi_operand = operand_1;
                } else if (operand_2.kind == .recurrent_add_expr) {
                    phi_operand = operand_2;
                }

                // If it is not in the form step + phi exit out.
                if (step_node == null or phi_operand == null) return self.phiCantCompute(phi);

                // If the phi operand is not the same phi node exit out.
                if (phi_operand.? != phi_node) return self.phiCantCompute(phi);

                if (!self.isLoopInvariant(lp, step_node.?)) return self.phiCantCompute(phi);

                phi_node.addCoefficient(step_node.?);
            }
        }

        // Once the node is fully built we update the map with the version from the cache (if it was already added).
        const cached: *SENode = self.getCachedOrAdd(phi_node);
        self.recurrent_node_map.put(phi, cached);
        return cached;
    }

    fn phiCantCompute(self: *Self, phi: *const Inst) *SENode {
        const cc: *SENode = self.createCantComputeNode();
        self.recurrent_node_map.put(phi, cc);
        return cc;
    }

    // ---- queries --------------------------------------------------------------------------------------------------

    const InvariantCap = struct { loop: *const Loop };

    fn invariantVisit(c: InvariantCap, n: *SENode) bool {
        if (n.kind == .recurrent_add_expr) {
            const header: *Block = n.loop.?.header();
            // If the loop which the recurrent expression belongs to is either |loop| or a nested loop inside |loop| then
            // we assume it is variant.
            if (c.loop.isInsideLoopBlock(header)) return false;
        } else if (n.kind == .value_unknown) {
            // If the instruction is inside the loop we conservatively assume it is loop variant.
            if (c.loop.isInsideLoopId(n.result_id)) return false;
        }
        return true;
    }

    pub fn isLoopInvariant(self: *Self, loop: *const Loop, node: *SENode) bool {
        _ = self;
        return node.walk(InvariantCap{ .loop = loop }, invariantVisit);
    }

    pub fn isAlwaysGreaterThanZero(self: *Self, node: *const SENode, is_gt_zero: *bool) bool {
        return (SeIsGreaterThanZero{ .ctx = self.ctx }).eval(node, false, is_gt_zero);
    }

    pub fn isAlwaysGreaterOrEqualToZero(self: *Self, node: *const SENode, is_ge_zero: *bool) bool {
        return (SeIsGreaterThanZero{ .ctx = self.ctx }).eval(node, true, is_ge_zero);
    }

    const RecFindCap = struct { loop: *const Loop, found: ?*SENode = null };

    fn recFindVisit(c: *RecFindCap, n: *SENode) bool {
        if (n.kind == .recurrent_add_expr and n.loop == c.loop) {
            c.found = n;
            return false;
        }
        return true;
    }

    /// Return the recurrent term belonging to |loop| if it appears in the graph starting at |node| or null.
    pub fn getRecurrentTerm(self: *Self, node: *SENode, loop: *const Loop) ?*SENode {
        _ = self;
        var cap: ScalarEvolutionAnalysis.RecFindCap = RecFindCap{ .loop = loop };
        _ = node.walk(&cap, recFindVisit);
        return cap.found;
    }

    pub fn getCoefficientFromRecurrentTerm(self: *Self, node: *SENode, loop: *const Loop) *SENode {
        if (self.getRecurrentTerm(node, loop)) |rec| return rec.coeff();
        return self.createConstant(0);
    }

    pub fn updateChildNode(self: *Self, parent: *SENode, old_child: *SENode, new_child: *SENode) *SENode {
        // Only handles add.
        if (parent.kind != .add) return parent;

        var new_children: List(*SENode) = .{};
        for (parent.children.items) |child| {
            if (child == old_child) new_children.push(new_child) else new_children.push(child);
        }

        const add_node: *SENode = self.newNode(.add);
        for (new_children.items) |child| add_node.addChild(child);

        return self.simplifyExpression(self.getCachedOrAdd(add_node));
    }

    /// Rebuild the |node| eliminating, if it exists, the recurrent term which belongs to the |loop|.
    pub fn buildGraphWithoutRecurrentTerm(self: *Self, node: *SENode, loop: *const Loop) *SENode {
        // If the node is already a recurrent expression belonging to loop then just return the offset.
        if (node.kind == .recurrent_add_expr) {
            if (node.loop == loop) return node.off();
            return node;
        }

        var new_children: List(*SENode) = .{};
        // Otherwise find the recurrent node in the children of this node.
        for (node.children.items) |itr| {
            if (itr.kind == .recurrent_add_expr and itr.loop == loop) {
                new_children.push(itr.off());
            } else {
                new_children.push(itr);
            }
        }

        const add_node: *SENode = self.newNode(.add);
        for (new_children.items) |child| add_node.addChild(child);

        return self.simplifyExpression(self.getCachedOrAdd(add_node));
    }

    pub fn addLoopsToPretendAreTheSame(self: *Self, first: *const Loop, second: *const Loop) void {
        self.pretend_equal.put(second, first);
    }

    // ---- SExpression ----------------------------------------------------------------------------------------------

    pub fn simplifyExpression(self: *Self, node: *SENode) *SENode {
        var impl = SeSimplifier{ .analysis = self, .node = node };
        return impl.simplify();
    }

    /// SExpression(node): the node simplified.
    pub fn sx(self: *Self, node: *SENode) *SENode {
        return self.simplifyExpression(node);
    }

    pub fn sxAdd(self: *Self, lhs: *SENode, rhs: *SENode) *SENode {
        return self.sx(self.createAddNode(lhs, rhs));
    }

    pub fn sxNeg(self: *Self, node: *SENode) *SENode {
        return self.sx(self.createNegation(node));
    }

    /// SExpression::operator-(SExpression): lhs + (-rhs).
    pub fn sxSub(self: *Self, lhs: *SENode, rhs: *SENode) *SENode {
        const neg: *SENode = self.createNegation(rhs);
        return self.sxAdd(lhs, neg);
    }

    pub fn sxMul(self: *Self, lhs: *SENode, rhs: *SENode) *SENode {
        return self.sx(self.createMultiplyNode(lhs, rhs));
    }

    pub fn sxMulInt(self: *Self, lhs: *SENode, integer: i64) *SENode {
        const c: *SENode = self.createConstant(integer);
        return self.sxMul(lhs, c);
    }

    pub fn sxAddInt(self: *Self, lhs: *SENode, integer: i64) *SENode {
        const c: *SENode = self.createConstant(integer);
        return self.sxAdd(lhs, c);
    }

    /// SExpression::operator/(SExpression): the quotient and the remainder (0 unless both operands are constants). The pair's
    /// first member is an SExpression, so the quotient node is simplified like any other SExpression.
    pub fn sxDiv(self: *Self, lhs: *SENode, rhs: *SENode) SeDivResult {
        // Check for division by 0.
        if (rhs.kind == .constant and rhs.value == 0) return .{ .node = self.sx(self.createCantComputeNode()), .remainder = 0 };

        // Trivial case.
        if (lhs.kind == .constant and rhs.kind == .constant) {
            if (lhs.value == std.math.minInt(i64) and rhs.value == -1) fatal("scalar evolution: INT64_MIN / -1 (SIGFPE in the C++)", .{});
            return .{ .node = self.sx(self.createConstant(@divTrunc(lhs.value, rhs.value))), .remainder = @rem(lhs.value, rhs.value) };
        }

        // look for a "c U / U" pattern.
        if (lhs.kind == .multiply) {
            const res: *SENode = seRemoveOneNodeFromMultiplyChain(lhs, rhs);
            if (res != lhs) return .{ .node = self.sx(res), .remainder = 0 };
        }

        return .{ .node = self.sx(self.createCantComputeNode()), .remainder = 0 };
    }
};

// ---- SENodeSimplifyImpl ------------------------------------------------------------------------------------------------

/// A term of a sum being simplified: the node and how many times it occurs.
const SeAccum = struct { node: *SENode, count: i64 };
/// A recurrence found in a sum, and whether it is negated.
const SeRecEntry = struct { rec: *SENode, negation: bool };
/// The recurrences of one loop found in a sum.
const SeLoopRecs = struct { loop: *const Loop, recs: List(SeRecEntry) = .{} };

/// Simplifies a sum: collects equal terms with their counts, adds the constants, and merges the recurrences of the same
/// loop.
const SeSimplifier = struct {
    analysis: *ScalarEvolutionAnalysis,
    node: *SENode,
    constant_accumulator: i64 = 0,
    accumulators: List(SeAccum) = .{}, // ordered by unique id (std::map<SENode*, int64_t> iterates by address)

    const Self = @This();

    fn findAccum(self: *Self, n: *SENode) ?*SeAccum {
        for (self.accumulators.items) |*a| {
            if (a.node == n) return a;
        }
        return null;
    }

    fn insertAccum(self: *Self, n: *SENode, count: i64) void {
        var pos: usize = 0;
        while (pos < self.accumulators.len() and self.accumulators.items[pos].node.unique_id < n.unique_id) pos += 1;
        self.accumulators.insert(pos, .{ .node = n, .count = count });
    }

    fn accumulate(self: *Self, n: *SENode, delta: i64) void {
        if (self.findAccum(n)) |a| {
            a.count +%= delta;
        } else {
            self.insertAccum(n, delta);
        }
    }

    /// From a |multiply| build up the accumulator objects.
    fn accumulatorsFromMultiply(self: *Self, multiply: *SENode, negation: bool) bool {
        if (multiply.children.len() != 2 or multiply.kind != .multiply) return false;

        const operand_1: *SENode = multiply.getChild(0);
        const operand_2: *SENode = multiply.getChild(1);

        var value_unknown: ?*SENode = null;
        var constant: ?*SENode = null;

        // Work out which operand is the unknown value.
        if (operand_1.kind == .value_unknown or operand_1.kind == .recurrent_add_expr) {
            value_unknown = operand_1;
        } else if (operand_2.kind == .value_unknown or operand_2.kind == .recurrent_add_expr) {
            value_unknown = operand_2;
        }

        // Work out which operand is the constant coefficient.
        if (operand_1.kind == .constant) {
            constant = operand_1;
        } else if (operand_2.kind == .constant) {
            constant = operand_2;
        }

        // If the expression is not a variable multiplied by a constant coefficient, exit out.
        if (value_unknown == null or constant == null) return false;

        const sign: i64 = if (negation) -1 else 1;
        const new_value: i64 = constant.?.value *% sign;
        // Add the result of the multiplication to the accumulators.
        self.accumulate(value_unknown.?, new_value);
        return true;
    }

    fn simplify(self: *Self) *SENode {
        // We only handle graphs with an addition, multiplication, or negation, at the root.
        if (self.node.kind != .add and self.node.kind != .multiply and self.node.kind != .negative) return self.node;

        var simplified_polynomial: *SENode = self.simplifyPolynomial();

        var recurrent_expr: ?*SENode = null;
        self.node = simplified_polynomial;

        // Fold recurrent expressions which are with respect to the same loop into a single recurrent expression.
        simplified_polynomial = self.foldRecurrentAddExpressions(simplified_polynomial);

        simplified_polynomial = self.eliminateZeroCoefficientRecurrents(simplified_polynomial);

        // Traverse the immediate children of the new node to find the recurrent expression. If there is more than one
        // there is nothing further we can do.
        for (simplified_polynomial.children.items) |child| {
            if (child.kind == .recurrent_add_expr) recurrent_expr = child;
        }

        // We need to count the number of unique recurrent expressions in the DAG to ensure there is only one.
        var cap: SeSimplifier.OtherRecCap = OtherRecCap{ .allowed = recurrent_expr };
        if (!simplified_polynomial.walk(&cap, otherRecVisit)) return simplified_polynomial;

        if (recurrent_expr) |r| return self.simplifyRecurrentAddExpression(r);

        return simplified_polynomial;
    }

    const OtherRecCap = struct { allowed: ?*SENode };

    /// false when a recurrent node other than `allowed` is found
    fn otherRecVisit(c: *OtherRecCap, n: *SENode) bool {
        if (n.kind == .recurrent_add_expr and c.allowed != n) return false;
        return true;
    }

    /// Traverse the graph to build up the accumulator objects.
    fn gatherAccumulatorsFromChildNodes(self: *Self, new_node: *SENode, child: *SENode, negation: bool) void {
        const sign: i64 = if (negation) -1 else 1;

        switch (child.kind) {
            .constant => {
                // Collect all the constants and add them together.
                self.constant_accumulator +%= child.value *% sign;
            },
            .value_unknown, .recurrent_add_expr => {
                // To rebuild the graph of X+X+X*2 into 4*X we count the occurrences of X.
                self.accumulate(child, sign);
            },
            .multiply => {
                if (!self.accumulatorsFromMultiply(child, negation)) new_node.addChild(child);
            },
            .add => {
                for (child.children.items) |next_child| self.gatherAccumulatorsFromChildNodes(new_node, next_child, negation);
            },
            .negative => {
                const negated_node: *SENode = child.getChild(0);
                self.gatherAccumulatorsFromChildNodes(new_node, negated_node, !negation);
            },
            else => {
                // If we can't work out how to fold the expression just add it back into the graph.
                new_node.addChild(child);
            },
        }
    }

    fn updateCoefficient(self: *Self, recurrent: *SENode, coefficient_update: i64) *SENode {
        const a: *ScalarEvolutionAnalysis = self.analysis;
        const new_recurrent_node: *SENode = a.newRecurrentNode(recurrent.loop);

        var new_coefficient: *SENode = a.createMultiplyNode(recurrent.coeff(), a.createConstant(coefficient_update));

        // See if the node can be simplified.
        const simplified: *SENode = a.simplifyExpression(new_coefficient);
        if (simplified.kind != .cant_compute) new_coefficient = simplified;

        if (coefficient_update < 0) {
            new_recurrent_node.addOffset(a.createNegation(recurrent.off()));
        } else {
            new_recurrent_node.addOffset(recurrent.off());
        }

        new_recurrent_node.addCoefficient(new_coefficient);

        return a.getCachedOrAdd(new_recurrent_node);
    }

    /// Simplify all the terms in the polynomial function.
    fn simplifyPolynomial(self: *Self) *SENode {
        const a: *ScalarEvolutionAnalysis = self.analysis;
        const new_add: *SENode = a.newNode(.add);

        // Traverse the graph and gather the accumulators from it.
        self.gatherAccumulatorsFromChildNodes(new_add, self.node, false);

        // Fold all the constants into a single constant node.
        if (self.constant_accumulator != 0) {
            new_add.addChild(a.createConstant(self.constant_accumulator));
        }

        for (self.accumulators.items) |pair| {
            const term: *SENode = pair.node;
            const count: i64 = pair.count;

            // We can eliminate the term completely.
            if (count == 0) continue;

            if (count == 1) {
                new_add.addChild(term);
            } else if (count == -1 and term.kind != .recurrent_add_expr) {
                // If the count is -1 we can just add a negative version of that node, unless it is a recurrent expression
                // as we would rather the negative goes on the recurrent expressions children.
                new_add.addChild(a.createNegation(term));
            } else {
                // Output value unknown terms as count*term and output recurrent expression terms as
                // rec(offset, coefficient + count).
                if (term.kind == .value_unknown) {
                    const count_as_constant: *SENode = a.createConstant(count);
                    new_add.addChild(a.createMultiplyNode(count_as_constant, term));
                } else {
                    check(term.kind == .recurrent_add_expr, "We only handle value unknowns or recurrent expressions");
                    // Create a new recurrent expression by adding the count to the coefficient of the old one.
                    new_add.addChild(self.updateCoefficient(term, count));
                }
            }
        }

        // If there is only one term in the addition left just return that term.
        if (new_add.children.len() == 1) return new_add.getChild(0);

        // If there are no terms left in the addition just return 0.
        if (new_add.children.len() == 0) return a.createConstant(0);

        return a.getCachedOrAdd(new_add);
    }

    fn findLoopRecs(list: *List(SeLoopRecs), loop: *const Loop) ?*SeLoopRecs {
        for (list.items) |*e| {
            if (e.loop == loop) return e;
        }
        return null;
    }

    fn foldRecurrentAddExpressions(self: *Self, root: *SENode) *SENode {
        const a: *ScalarEvolutionAnalysis = self.analysis;
        const new_node: *SENode = a.newNode(.add);

        // A mapping of loops to the list of recurrent expressions which are with respect to those loops
        // (std::map<const Loop*, ...>: ordered by address).
        var loops_to_recurrent: List(SeLoopRecs) = .{};

        var has_multiple_same_loop_recurrent_terms: bool = false;

        for (root.children.items) |child_in| {
            var child: *SENode = child_in;
            var negation: bool = false;

            if (child.kind == .negative) {
                child = child.getChild(0);
                negation = true;
            }

            if (child.kind == .recurrent_add_expr) {
                const loop: *const Loop = child.loop.?;
                if (findLoopRecs(&loops_to_recurrent, loop)) |e| {
                    e.recs.push(.{ .rec = child, .negation = negation });
                    has_multiple_same_loop_recurrent_terms = true;
                } else {
                    var pos: usize = 0;
                    while (pos < loops_to_recurrent.len() and @intFromPtr(loops_to_recurrent.items[pos].loop) < @intFromPtr(loop)) pos += 1;
                    var entry = SeLoopRecs{ .loop = loop };
                    entry.recs.push(.{ .rec = child, .negation = negation });
                    loops_to_recurrent.insert(pos, entry);
                }
            } else {
                new_node.addChild(child);
            }
        }

        if (!has_multiple_same_loop_recurrent_terms) return root;

        for (loops_to_recurrent.items) |pair| {
            const loop: *const Loop = pair.loop;

            const new_coefficient: *SENode = a.newNode(.add);
            const new_offset: *SENode = a.newNode(.add);

            for (pair.recs.items) |node_pair| {
                const node: *SENode = node_pair.rec;
                if (!node_pair.negation) {
                    new_coefficient.addChild(node.coeff());
                    new_offset.addChild(node.off());
                } else {
                    new_coefficient.addChild(a.createNegation(node.coeff()));
                    new_offset.addChild(a.createNegation(node.off()));
                }
            }

            const new_recurrent: *SENode = a.newRecurrentNode(loop);

            const new_coefficient_simplified: *SENode = a.simplifyExpression(new_coefficient);
            const new_offset_simplified: *SENode = a.simplifyExpression(new_offset);

            if (new_coefficient_simplified.kind == .constant and new_coefficient_simplified.value == 0) {
                return new_offset_simplified;
            }

            new_recurrent.addCoefficient(new_coefficient_simplified);
            new_recurrent.addOffset(new_offset_simplified);

            new_node.addChild(a.getCachedOrAdd(new_recurrent));
        }

        // If we only have one child in the add just return that.
        if (new_node.children.len() == 1) return new_node.getChild(0);

        return a.getCachedOrAdd(new_node);
    }

    fn eliminateZeroCoefficientRecurrents(self: *Self, node: *SENode) *SENode {
        if (node.kind != .add) return node;

        var has_change: bool = false;

        var new_children: List(*SENode) = .{};
        for (node.children.items) |child| {
            if (child.kind == .recurrent_add_expr) {
                const coefficient: *SENode = child.coeff();
                // If coefficient is zero then we can eliminate the recurrent expression entirely and just return the offset.
                if (coefficient.kind == .constant and coefficient.value == 0) {
                    new_children.push(child.off());
                    has_change = true;
                } else {
                    new_children.push(child);
                }
            } else {
                new_children.push(child);
            }
        }

        if (!has_change) return node;

        const new_add: *SENode = self.analysis.newNode(.add);
        for (new_children.items) |child| new_add.addChild(child);

        return self.analysis.getCachedOrAdd(new_add);
    }

    fn simplifyRecurrentAddExpression(self: *Self, recurrent_expr: *SENode) *SENode {
        const a: *ScalarEvolutionAnalysis = self.analysis;
        const children: []*SENode = self.node.children.items;

        const recurrent_node: *SENode = a.newRecurrentNode(recurrent_expr.loop);

        // Create and simplify the new offset node.
        const new_offset: *SENode = a.newNode(.add);
        new_offset.addChild(recurrent_expr.off());

        for (children) |child| {
            if (child.kind != .recurrent_add_expr) new_offset.addChild(child);
        }

        // Simplify the new offset.
        const simplified_child: *SENode = a.simplifyExpression(new_offset);

        // If the child can be simplified, add the simplified form. (The C++ otherwise mutates the cached recurrent node
        // and then hashes a recurrent node whose offset is uninitialised: undefined behaviour.)
        if (simplified_child.kind == .cant_compute) fatal("scalar evolution: SimplifyRecurrentAddExpression offset cannot be computed (undefined behaviour in the C++)", .{});
        recurrent_node.addOffset(simplified_child);

        recurrent_node.addCoefficient(recurrent_expr.coeff());

        return a.getCachedOrAdd(recurrent_node);
    }
};

fn rpDef(ctx: *Ctx, id: u32) *Inst {
    return ctx.getDefUseMgr().getDef(id) orelse fatal("register pressure: id %{d} is not defined", .{id});
}

/// Computes the register liveness for each basic block of a function (class ComputeRegisterLiveness).
const RpCompute = struct {
    reg_pressure: *RegisterLiveness,
    ctx: *Ctx,
    function: *Func,
    cfg: *Cfg,
    dom_tree: *DomTree,
    loop_desc: *LoopDescriptor,

    const Self = @This();

    fn init(rp: *RegisterLiveness, f: *Func) Self {
        const ctx: *Ctx = rp.ctx;
        return .{
            .reg_pressure = rp,
            .ctx = ctx,
            .function = f,
            .cfg = ctx.cfg(),
            .dom_tree = ctx.getDominatorAnalysis(f).getDomTree(),
            .loop_desc = ctx.getLoopDescriptor(f),
        };
    }

    fn postVisit(self: *Self, bb: *Block) void {
        if (self.reg_pressure.get(bb.id()) == null) self.computePartialLiveness(bb);
    }

    /// Computes the register liveness for |function| and then estimates the register usage. The liveness algorithm works in
    /// 2 steps: first the liveness of each basic block ignoring back-edges, then the loop forest is walked to propagate the
    /// registers crossing back-edges.
    fn compute(self: *Self) void {
        for (self.function.blocks.items) |start_bb| {
            if (self.reg_pressure.get(start_bb.id()) != null) continue;
            self.cfg.forEachBlockInPostOrder(start_bb, self, postVisit);
        }
        self.doLoopLivenessUnificationAll();
        self.evaluateRegisterRequirements();
    }

    // ---- ComputePhiUses -----------------------------------------------------------------------------------------------

    const PhiUseCap = struct { self: *Self, bb_id: u32, live: *Set(*Inst) };

    fn phiUse(c: PhiUseCap, phi: *Inst) void {
        var i: usize = 0;
        while (i < phi.numInOperands()) : (i += 2) {
            if (phi.getSingleWordInOperand(i + 1) == c.bb_id) {
                const insn_op: *Inst = rpDef(c.self.ctx, phi.getSingleWordInOperand(i));
                if (rpCreatesRegisterUsage(insn_op)) {
                    _ = c.live.insert(insn_op);
                    break;
                }
            }
        }
    }

    fn phiUseSucc(c: PhiUseCap, sid: u32) void {
        const succ_bb: *Block = c.self.cfg.block(sid);
        succ_bb.forEachPhiInst(c, phiUse, false);
    }

    /// Registers all SSA register used by successors of |bb| in their phi instructions.
    fn computePhiUses(self: *Self, bb: *const Block, live: *Set(*Inst)) void {
        bb.forEachSuccessorLabel(PhiUseCap{ .self = self, .bb_id = bb.id(), .live = live }, phiUseSucc);
    }

    // ---- ComputePartialLiveness ---------------------------------------------------------------------------------------

    const PartialCap = struct { self: *Self, bb: *const Block, live_inout: *RegionRegisterLiveness };

    fn partialSucc(c: PartialCap, sid: u32) void {
        // Skip back edges.
        if (c.self.dom_tree.dominatesId(sid, c.bb.id())) return;

        const succ_bb: *Block = c.self.cfg.block(sid);
        const succ_live_inout: *RegionRegisterLiveness = c.self.reg_pressure.get(succ_bb.id()) orelse fatal("register pressure: successor liveness analysis was not performed", .{});

        // ExcludePhiDefinedInBlock
        var it: Map(*Inst, void).Hm.Iterator = succ_live_inout.live_in.iterator();
        while (it.next()) |e| {
            const insn: *Inst = e.key_ptr.*;
            if (insn.op == .OpPhi and c.self.ctx.getInstrBlock(insn) == succ_bb) continue;
            _ = c.live_inout.live_out.insert(insn);
        }
    }

    const UseCap = struct { self: *Self, live_inout: *RegionRegisterLiveness };

    fn markUse(c: UseCap, id: *u32) void {
        const insn_op: *Inst = rpDef(c.self.ctx, id.*);
        if (rpCreatesRegisterUsage(insn_op)) _ = c.live_inout.live_in.insert(insn_op);
    }

    /// Computes register liveness for each basic blocks but ignores all back-edges.
    fn computePartialLiveness(self: *Self, bb: *Block) void {
        check(self.reg_pressure.get(bb.id()) == null, "Basic block already processed");

        const live_inout: *RegionRegisterLiveness = self.reg_pressure.getOrInsert(bb.id());
        self.computePhiUses(bb, &live_inout.live_out);

        bb.forEachSuccessorLabel(PartialCap{ .self = self, .bb = bb, .live_inout = live_inout }, partialSucc);

        live_inout.live_in = rpCopySet(&live_inout.live_out);
        var it: ?*Inst = bb.insts.last;
        while (it) |insn| : (it = insn.prev) {
            if (insn.op == .OpPhi) {
                _ = live_inout.live_in.insert(insn);
                break;
            }
            _ = live_inout.live_in.remove(insn);
            insn.forEachInId(UseCap{ .self = self, .live_inout = live_inout }, markUse);
        }
    }

    // ---- loop liveness unification ------------------------------------------------------------------------------------

    fn doLoopLivenessUnificationAll(self: *Self) void {
        for (self.loop_desc.placeholder_top_loop.nested_loops.items) |loop| {
            self.doLoopLivenessUnification(loop);
        }
    }

    /// Propagates the register liveness information of loop iterators through-out the loop body.
    fn doLoopLivenessUnification(self: *Self, loop: *const Loop) void {
        const header: *Block = loop.header();
        const header_live_inout: *RegionRegisterLiveness = self.reg_pressure.get(header.id()) orelse fatal("register pressure: liveness analysis was not performed for the loop header", .{});

        // live_loop: the header's live-in set without the phis defined in the header (the set is not modified below).
        var live_loop: List(*Inst) = .{};
        var hit: Map(*Inst, void).Hm.Iterator = header_live_inout.live_in.iterator();
        while (hit.next()) |e| {
            const insn: *Inst = e.key_ptr.*;
            if (insn.op == .OpPhi and self.ctx.getInstrBlock(insn) == header) continue;
            live_loop.push(insn);
        }

        for (loop.loop_basic_blocks.items()) |bb_id| {
            if (bb_id == header.id()) continue;
            const owner: ?*Loop = self.loop_desc.findLoopForBasicBlock(bb_id);
            if (owner == null or owner.? != loop) continue;
            const bb: *Block = self.cfg.block(bb_id);

            const live_inout: *RegionRegisterLiveness = self.reg_pressure.get(bb.id()) orelse fatal("register pressure: block %{d} not processed", .{bb.id()});
            for (live_loop.items) |insn| {
                _ = live_inout.live_in.insert(insn);
                _ = live_inout.live_out.insert(insn);
            }
        }

        for (loop.nested_loops.items) |inner_loop| {
            const live_inout: *RegionRegisterLiveness = self.reg_pressure.get(inner_loop.header().id()) orelse fatal("register pressure: inner loop header not processed", .{});
            for (live_loop.items) |insn| {
                _ = live_inout.live_in.insert(insn);
                _ = live_inout.live_out.insert(insn);
            }

            self.doLoopLivenessUnification(inner_loop);
        }
    }

    // ---- EvaluateRegisterRequirements -------------------------------------------------------------------------------

    const DieCap = struct { self: *Self, live_inout: *RegionRegisterLiveness, die_in_block: *Set(u32), reg_count: *usize };

    fn dieOperand(c: DieCap, id: *u32) void {
        const op_insn: *Inst = rpDef(c.self.ctx, id.*);
        if (!rpCreatesRegisterUsage(op_insn) or c.live_inout.live_out.contains(op_insn)) {
            // already taken into account.
            return;
        }
        if (!c.die_in_block.contains(id.*)) {
            c.reg_count.* +%= 1;
            _ = c.die_in_block.insert(id.*);
        }
    }

    /// Get the number of required registers for this each basic block.
    fn evaluateRegisterRequirements(self: *Self) void {
        for (self.function.blocks.items) |bb| {
            const live_inout: *RegionRegisterLiveness = self.reg_pressure.get(bb.id()) orelse fatal("register pressure: basic block not processed", .{});

            var reg_count: usize = live_inout.live_out.count();
            live_inout.used_registers = reg_count;

            var die_in_block: Set(u32) = .{};
            var it: ?*Inst = bb.insts.last;
            while (it) |insn| : (it = insn.prev) {
                // If it is a phi instruction, the register pressure will not change anymore.
                if (insn.op == .OpPhi) break;

                insn.forEachInId(DieCap{ .self = self, .live_inout = live_inout, .die_in_block = &die_in_block, .reg_count = &reg_count }, dieOperand);
                live_inout.used_registers = @max(live_inout.used_registers, reg_count);
                if (rpCreatesRegisterUsage(insn)) reg_count -%= 1;
            }
        }
    }
};

/// Handles the register pressure of a function for different regions (function, loop, basic block).
pub const RegisterLiveness = struct {
    ctx: *Ctx,
    block_pressure: Map(u32, *RegionRegisterLiveness) = .{},

    pub fn create(ctx: *Ctx, f: *Func) *RegisterLiveness {
        const rl = scAllocator().create(RegisterLiveness) catch oom();
        rl.* = .{ .ctx = ctx };
        rl.analyze(f);
        return rl;
    }

    fn analyze(self: *RegisterLiveness, f: *Func) void {
        self.block_pressure.clear();
        var c = RpCompute.init(self, f);
        c.compute();
    }

    /// Liveness and register information for the basic block id |bb_id|; null if no entry exists.
    pub fn get(self: *const RegisterLiveness, bb_id: u32) ?*RegionRegisterLiveness {
        return self.block_pressure.get(bb_id);
    }

    /// Liveness and register information for the basic block id |bb_id| or a new empty entry.
    pub fn getOrInsert(self: *RegisterLiveness, bb_id: u32) *RegionRegisterLiveness {
        const gop: Map(u32, *RegionRegisterLiveness).GetOrPutResult = self.block_pressure.getOrPut(bb_id);
        if (!gop.found_existing) {
            const r = scAllocator().create(RegionRegisterLiveness) catch oom();
            r.* = .{};
            gop.value_ptr.* = r;
        }
        return gop.value_ptr.*;
    }

    fn mustGet(self: *const RegisterLiveness, bb_id: u32) *RegionRegisterLiveness {
        return self.get(bb_id) orelse fatal("register pressure: basic block %{d} not processed", .{bb_id});
    }

    /// Compute the register pressure for the |loop| and store the result into |loop_reg_pressure|. The live-in set corresponds
    /// to the live-in set of the header block, the live-out set of the loop corresponds to the union of the live-in sets of each
    /// exit basic block.
    pub fn computeLoopRegisterPressure(self: *const RegisterLiveness, loop: *const Loop, loop_reg_pressure: *RegionRegisterLiveness) void {
        loop_reg_pressure.clear();

        const header_live_inout: *RegionRegisterLiveness = self.mustGet(loop.header().id());
        loop_reg_pressure.live_in = rpCopySet(&header_live_inout.live_in);

        const exit_blocks: StdUSet32 = loop.getExitBlocks();
        for (exit_blocks.items()) |bb_id| {
            const live_inout: *RegionRegisterLiveness = self.mustGet(bb_id);
            rpUnionInto(&loop_reg_pressure.live_out, &live_inout.live_in);
        }

        loop_reg_pressure.used_registers = 0;
        for (loop.loop_basic_blocks.items()) |bb_id| {
            const live_inout: *RegionRegisterLiveness = self.mustGet(bb_id);
            loop_reg_pressure.used_registers = @max(loop_reg_pressure.used_registers, live_inout.used_registers);
        }
    }

    /// Estimate the register pressure for the |l1| and |l2| as if they were making one unique loop. The result is stored into
    /// |sim_result|.
    pub fn simulateFusion(self: *const RegisterLiveness, l1: *const Loop, l2: *const Loop, sim_result: *RegionRegisterLiveness) void {
        sim_result.clear();

        // Compute the live-in state: sim_result.live_in = l1.live_in U l2.live_in
        const l1_header_live_inout: *RegionRegisterLiveness = self.mustGet(l1.header().id());
        sim_result.live_in = rpCopySet(&l1_header_live_inout.live_in);

        const l2_header_live_inout: *RegionRegisterLiveness = self.mustGet(l2.header().id());
        rpUnionInto(&sim_result.live_in, &l2_header_live_inout.live_in);

        // The live-out set of the fused loop is the l2 live-out set.
        const exit_blocks: StdUSet32 = l2.getExitBlocks();
        for (exit_blocks.items()) |bb_id| {
            const live_inout: *RegionRegisterLiveness = self.mustGet(bb_id);
            rpUnionInto(&sim_result.live_out, &live_inout.live_in);
        }

        sim_result.used_registers = 0;

        // The loop fusion is injecting the l1 before the l2, the latch of l1 will be connected to the header of l2. To compute
        // the register usage, we inject the loop live-in (union of l1 and l2 live-in header blocks) into the live in/out of each
        // basic block of l1 to get the peak register usage. We then repeat the operation to for l2 basic blocks but in this case
        // we inject the live-out of the latch of l1.
        var live_loop: List(*Inst) = .{};
        var it: Map(*Inst, void).Hm.Iterator = sim_result.live_in.iterator();
        while (it.next()) |e| {
            const insn: *Inst = e.key_ptr.*;
            const bb: ?*Block = self.ctx.getInstrBlock(insn);
            if (insn.has_result and !(insn.op == .OpPhi and (bb == l1.header() or bb == l2.header()))) live_loop.push(insn);
        }

        for (l1.loop_basic_blocks.items()) |bb_id| {
            const live_inout_info: *RegionRegisterLiveness = self.mustGet(bb_id);
            var live_out: Set(*Inst) = rpCopySet(&live_inout_info.live_out);
            for (live_loop.items) |insn| _ = live_out.insert(insn);
            sim_result.used_registers = @max(sim_result.used_registers, live_inout_info.used_registers +% live_out.count() -% live_inout_info.live_out.count());
        }

        const l1_latch: *Block = l1.loop_latch orelse fatal("register pressure: the first loop has no latch block", .{});
        const l1_latch_live_inout_info: *RegionRegisterLiveness = self.mustGet(l1_latch.id());
        var l1_latch_live_out: Set(*Inst) = rpCopySet(&l1_latch_live_inout_info.live_out);
        for (live_loop.items) |insn| _ = l1_latch_live_out.insert(insn);

        for (l2.loop_basic_blocks.items()) |bb_id| {
            const live_inout_info: *RegionRegisterLiveness = self.mustGet(bb_id);
            var live_out: Set(*Inst) = rpCopySet(&live_inout_info.live_out);
            rpUnionInto(&live_out, &l1_latch_live_out);
            sim_result.used_registers = @max(sim_result.used_registers, live_inout_info.used_registers +% live_out.count() -% live_inout_info.live_out.count());
        }
    }
};

/// Handles the register pressure of a module's functions (cache of RegisterLiveness per function).
pub const LivenessAnalysis = struct {
    ctx: *Ctx,
    analysis_cache: Map(*Func, *RegisterLiveness) = .{},

    /// Computes the liveness analysis for the function |f| and caches the result.
    pub fn get(self: *LivenessAnalysis, f: *Func) *RegisterLiveness {
        if (self.analysis_cache.get(f)) |rl| return rl;
        const rl: *RegisterLiveness = RegisterLiveness.create(self.ctx, f);
        self.analysis_cache.put(f, rl);
        return rl;
    }
};

pub const LivenessMgr = struct {
    ctx: *Ctx,
    computed: bool = false,
    live_locs: Set(u32) = .{},
    live_builtins: Set(u32) = .{},

    const kDecorationLocationInIdx = 2;
    const kOpDecorateMemberMemberInIdx = 1;
    const kOpDecorateMemberLocationInIdx = 3;
    const kOpDecorateBuiltInLiteralInIdx = 2;
    const kOpDecorateMemberBuiltInLiteralInIdx = 3;

    pub fn init(ctx: *Ctx) *LivenessMgr {
        const self = scAllocator().create(LivenessMgr) catch oom();
        self.* = .{ .ctx = ctx };
        return self;
    }

    fn initializeAnalysis(self: *LivenessMgr) void {
        self.live_locs.clear();
        self.live_builtins.clear();
        // Mark all builtins live for frag shader.
        if (self.ctx.getStage() == @intFromEnum(ExecutionModel.Fragment)) {
            _ = self.live_builtins.insert(@intFromEnum(BuiltIn.PointSize));
            _ = self.live_builtins.insert(@intFromEnum(BuiltIn.ClipDistance));
            _ = self.live_builtins.insert(@intFromEnum(BuiltIn.CullDistance));
        }
    }

    /// There are only three builtins that can be analyzed and removed between two stages: PointSize, ClipDistance and
    /// CullDistance. All others are always consumed implicitly by the downstream stage.
    pub fn isAnalyzedBuiltin(self: *const LivenessMgr, bi: u32) bool {
        _ = self;
        return bi == @intFromEnum(BuiltIn.PointSize) or bi == @intFromEnum(BuiltIn.ClipDistance) or
            bi == @intFromEnum(BuiltIn.CullDistance);
    }

    const BuiltInCapture = struct {
        mgr: *LivenessMgr,
        saw_builtin: bool = false,
        fn f(c: *BuiltInCapture, deco_inst: *Inst) void {
            c.saw_builtin = true;
            // No need to process builtins in frag shader. All assumed used.
            if (c.mgr.ctx.getStage() == @intFromEnum(ExecutionModel.Fragment)) return;
            var builtin: u32 = builtin_max;
            if (deco_inst.op == .OpDecorate) {
                builtin = deco_inst.getSingleWordInOperand(kOpDecorateBuiltInLiteralInIdx);
            } else if (deco_inst.op == .OpMemberDecorate) {
                builtin = deco_inst.getSingleWordInOperand(kOpDecorateMemberBuiltInLiteralInIdx);
            }
            if (c.mgr.isAnalyzedBuiltin(builtin)) _ = c.mgr.live_builtins.insert(builtin);
        }
    };

    /// Analyze |id| for builtin var and struct members. Return true if builtins found.
    fn analyzeBuiltIn(self: *LivenessMgr, id: u32) bool {
        var cap: LivenessMgr.BuiltInCapture = BuiltInCapture{ .mgr = self };
        self.ctx.getDecorationMgr().forEachDecoration(id, @intFromEnum(Decoration.BuiltIn), &cap, BuiltInCapture.f);
        return cap.saw_builtin;
    }

    fn markLocsLive(self: *LivenessMgr, start: u32, count: u32) void {
        const finish: u32 = start +% count;
        var u: u32 = start;
        while (u < finish) : (u += 1) _ = self.live_locs.insert(u);
    }

    /// Return size of |type| in units of locations.
    pub fn getLocSize(self: *const LivenessMgr, t: ?*const Type) u32 {
        const ty: *const Type = t orelse fatal("LivenessMgr.getLocSize: null type (null dereference in the C++)", .{});
        if (ty.as(.array)) |arr_type| {
            // (C++ asserts the length is a constant; the release build reads the second word whatever the case)
            return arr_type.length.words.items[1] *% self.getLocSize(arr_type.element);
        }
        if (ty.as(.struct_)) |struct_type| {
            var size: u32 = 0;
            for (struct_type.elements.items) |el_type| size +%= self.getLocSize(el_type);
            return size;
        }
        if (ty.as(.matrix)) |mat_type| return mat_type.count *% self.getLocSize(mat_type.element);
        if (ty.as(.vector)) |vec_type| {
            const comp_type: *const Type = vec_type.element;
            if (comp_type.as(.integer) != null) return 1;
            const float_type: *const TyFloat = comp_type.as(.float) orelse fatal("LivenessMgr.getLocSize: vector component is not numeric (null dereference in the C++)", .{});
            const width: u32 = float_type.width;
            if (width == 32 or width == 16) return 1;
            return if (vec_type.count > 2) 2 else 1;
        }
        return 1;
    }

    fn getComponentType(self: *const LivenessMgr, index: u32, agg_type_id: u32) u32 {
        const agg_type_inst: *Inst = self.ctx.getDefUseMgr().getDef(agg_type_id) orelse fatal("LivenessMgr: id %{d} is not defined", .{agg_type_id});
        switch (agg_type_inst.op) {
            .OpTypeArray, .OpTypeMatrix, .OpTypeVector => return agg_type_inst.getSingleWordInOperand(0),
            .OpTypeStruct => {
                if (index >= agg_type_inst.numInOperands()) fatal("LivenessMgr: member index {d} out of range", .{index});
                return agg_type_inst.getSingleWordInOperand(index);
            },
            else => return 0,
        }
    }

    fn getLocOffset(self: *LivenessMgr, index: u32, agg_type_id: u32) u32 {
        const agg_type: *Type = self.ctx.getTypeMgr().getType(agg_type_id) orelse fatal("LivenessMgr: %{d} is not a type", .{agg_type_id});
        if (agg_type.as(.array)) |arr_type| return index *% self.getLocSize(arr_type.element);
        if (agg_type.as(.struct_)) |struct_type| {
            var offset: u32 = 0;
            var cnt: u32 = 0;
            for (struct_type.elements.items) |el_type| {
                if (cnt == index) break;
                offset +%= self.getLocSize(el_type);
                cnt += 1;
            }
            return offset;
        }
        if (agg_type.as(.matrix)) |mat_type| return index *% self.getLocSize(mat_type.element);
        const vec_type: *const TyVector = agg_type.as(.vector) orelse fatal("LivenessMgr: non-aggregate type (null dereference in the C++)", .{});
        if (vec_type.element.as(.float)) |flt_type| {
            if (flt_type.width == 64 and index >= 2) return 1;
        }
        return 0;
    }

    const AcCapture = struct {
        mgr: *LivenessMgr,
        ocnt: u32 = 0,
        curr_type_id: u32,
        offset: *u32,
        no_loc: *bool,
        skip_first_index: bool,

        const MemberLoc = struct {
            loc: u32 = 0,
            index: u32,
            no_loc: *bool,
            fn f(c: *MemberLoc, deco: *Inst) bool {
                if (deco.getSingleWordInOperand(kOpDecorateMemberMemberInIdx) == c.index) {
                    c.loc = deco.getSingleWordInOperand(kOpDecorateMemberLocationInIdx);
                    c.no_loc.* = false;
                    return false;
                }
                return true;
            }
        };

        fn f(c: *AcCapture, opnd: *u32) bool {
            const def_use_mgr: *DefUseMgr = c.mgr.ctx.getDefUseMgr();
            if (c.ocnt >= 1) {
                // Skip first index's contribution to offset if indicated
                const curr_type_inst: *Inst = def_use_mgr.getDef(c.curr_type_id) orelse fatal("LivenessMgr: id %{d} is not defined", .{c.curr_type_id});
                if (c.ocnt == 1 and c.skip_first_index) {
                    c.curr_type_id = curr_type_inst.getSingleWordInOperand(0);
                    c.ocnt += 1;
                    return true;
                }
                // If any non-constant index, mark the entire current object and return.
                const idx_inst: *Inst = def_use_mgr.getDef(opnd.*) orelse fatal("LivenessMgr: id %{d} is not defined", .{opnd.*});
                if (idx_inst.op != .OpConstant) return false;
                // If current type is struct, look for location decoration on member and reset offset if found.
                const index: u32 = idx_inst.getSingleWordInOperand(0);
                if (curr_type_inst.op == .OpTypeStruct) {
                    var ml: LivenessMgr.AcCapture.MemberLoc = MemberLoc{ .index = index, .no_loc = c.no_loc };
                    const no_mem_loc: bool = c.mgr.ctx.getDecorationMgr().whileEachDecoration(c.curr_type_id, @intFromEnum(Decoration.Location), &ml, MemberLoc.f);
                    if (!no_mem_loc) {
                        c.offset.* = ml.loc;
                        if (index >= curr_type_inst.numInOperands()) fatal("LivenessMgr: member index {d} out of range", .{index});
                        c.curr_type_id = curr_type_inst.getSingleWordInOperand(index);
                        c.ocnt += 1;
                        return true;
                    }
                }
                // Update offset and current type based on constant index.
                c.offset.* +%= c.mgr.getLocOffset(index, c.curr_type_id);
                c.curr_type_id = c.mgr.getComponentType(index, c.curr_type_id);
            }
            c.ocnt += 1;
            return true;
        }
    };

    /// Return the result type of |ac| when applied to |curr_type_id|. Set |no_loc| to true if no loc found. |is_patch|
    /// indicates if the variable is a patch variable. |input| is set for an input variable; otherwise it is assumed to be an
    /// output variable.
    pub fn analyzeAccessChainLoc(self: *LivenessMgr, ac: *Inst, curr_type_id: u32, offset: *u32, no_loc: *bool, is_patch: bool, input: bool) u32 {
        // For tesc, tese and geom input variables, and tesc output variables, first array index does not contribute to offset.
        const stage: u32 = self.ctx.getStage();
        const tesc: u32 = @intFromEnum(ExecutionModel.TessellationControl);
        const tese: u32 = @intFromEnum(ExecutionModel.TessellationEvaluation);
        const geom: u32 = @intFromEnum(ExecutionModel.Geometry);
        var skip_first_index: bool = false;
        if ((input and (stage == tesc or stage == tese or stage == geom)) or (!input and stage == tesc))
            skip_first_index = !is_patch;
        var cap: LivenessMgr.AcCapture = AcCapture{
            .mgr = self,
            .curr_type_id = curr_type_id,
            .offset = offset,
            .no_loc = no_loc,
            .skip_first_index = skip_first_index,
        };
        _ = ac.whileEachInOperand(&cap, AcCapture.f);
        return cap.curr_type_id;
    }

    const LocDeco = struct {
        loc: u32 = 0,
        fn f(c: *LocDeco, deco: *Inst) bool {
            c.loc = deco.getSingleWordInOperand(kDecorationLocationInIdx);
            return false;
        }
    };

    const PatchDeco = struct {
        fn f(_: *PatchDeco, _: *Inst) bool {
            return false;
        }
    };

    fn markRefLive(self: *LivenessMgr, ref: *Inst, v: *Inst) void {
        const type_mgr: *TypeMgr = self.ctx.getTypeMgr();
        const deco_mgr: *DecorMgr = self.ctx.getDecorationMgr();
        // Find variable location if present.
        var ld: LivenessMgr.LocDeco = LocDeco{};
        const var_id: u32 = v.resultId();
        var no_loc: bool = deco_mgr.whileEachDecoration(var_id, @intFromEnum(Decoration.Location), &ld, LocDeco.f);
        const loc: u32 = ld.loc;
        // Find patch decoration if present
        var pd: LivenessMgr.PatchDeco = PatchDeco{};
        const is_patch: bool = !deco_mgr.whileEachDecoration(var_id, @intFromEnum(Decoration.Patch), &pd, PatchDeco.f);
        // If use is a load, mark all locations of var
        const var_ty: *Type = type_mgr.getType(v.typeId()) orelse fatal("LivenessMgr: unknown variable type", .{});
        const ptr_type: *const TyPointer = var_ty.as(.pointer) orelse fatal("LivenessMgr: variable type is not a pointer (null dereference in the C++)", .{});
        const pointee: *const Type = ptr_type.pointee orelse fatal("LivenessMgr: untyped pointer", .{});
        if (ref.op == .OpLoad) {
            self.markLocsLive(loc, self.getLocSize(pointee));
            return;
        }
        // Mark just those locations indicated by access chain: traverse the access chain, compute location offset and
        // type of reference through constant indices and mark those locs live.
        var offset: u32 = loc;
        const ptr_type_inst: *Inst = self.ctx.getDefUseMgr().getDef(v.typeId()) orelse fatal("LivenessMgr: id %{d} is not defined", .{v.typeId()});
        const var_type_id: u32 = ptr_type_inst.getSingleWordInOperand(1);
        const curr_type_id: u32 = self.analyzeAccessChainLoc(ref, var_type_id, &offset, &no_loc, is_patch, true);
        const curr_type: ?*Type = type_mgr.getType(curr_type_id);
        self.markLocsLive(offset, self.getLocSize(curr_type));
    }

    fn computeLiveness(self: *LivenessMgr) void {
        self.initializeAnalysis();
        const def_use_mgr: *DefUseMgr = self.ctx.getDefUseMgr();
        // Process all input variables
        var it: ?*Inst = self.ctx.module.types_values.first;
        while (it) |v| : (it = v.next) {
            if (v.op != .OpVariable) continue;
            const var_type_inst: *Inst = def_use_mgr.getDef(v.typeId()) orelse fatal("LivenessMgr: id %{d} is not defined", .{v.typeId()});
            const sc: u32 = var_type_inst.getSingleWordInOperand(0);
            if (sc != @intFromEnum(StorageClass.Input)) continue;
            // If var is builtin, mark live if analyzed and continue to next variable
            const var_id: u32 = v.resultId();
            if (self.analyzeBuiltIn(var_id)) continue;
            // If interface block with builtin members, mark live if analyzed and continue to next variable. Input
            // interface blocks will only appear in tesc, tese and geom shaders. Will need to strip off one level of
            // arrayness to get to block type.
            const pte_type_id: u32 = var_type_inst.getSingleWordInOperand(1);
            const pte_type_inst: *Inst = def_use_mgr.getDef(pte_type_id) orelse fatal("LivenessMgr: id %{d} is not defined", .{pte_type_id});
            if (pte_type_inst.op == .OpTypeArray) {
                const array_elt_type_id: u32 = pte_type_inst.getSingleWordInOperand(0);
                const arr_elt_type: *Inst = def_use_mgr.getDef(array_elt_type_id) orelse fatal("LivenessMgr: id %{d} is not defined", .{array_elt_type_id});
                if (arr_elt_type.op == .OpTypeStruct) {
                    if (self.analyzeBuiltIn(array_elt_type_id)) continue;
                }
            }
            // Mark all used locations of var live
            for (def_use_mgr.registeredUsersOfId(var_id)) |user| {
                const op: Op = user.op;
                if (op == .OpEntryPoint or op == .OpName or op == .OpDecorate or isNonSemanticInst(user)) continue;
                self.markRefLive(user, v);
            }
        }
    }

    /// Copy liveness info into |sets| (the std::unordered_set<uint32_t> assignment replaces their contents).
    pub fn getLiveness(self: *LivenessMgr, sets: *LiveIoSets) void {
        if (!self.computed) {
            self.computeLiveness();
            self.computed = true;
        }
        const a: std.mem.Allocator = irAllocator();
        sets.locs.clearRetainingCapacity();
        sets.builtins.clearRetainingCapacity();
        var li: Map(u32, void).Hm.Iterator = self.live_locs.iterator();
        while (li.next()) |kv| sets.locs.put(a, kv.key_ptr.*, {}) catch oom();
        var bi: Map(u32, void).Hm.Iterator = self.live_builtins.iterator();
        while (bi.next()) |kv| sets.builtins.put(a, kv.key_ptr.*, {}) catch oom();
    }
};

/// The one IRContext of the process (Instruction::context()).
pub fn theCtx() *Ctx {
    return g_ctx orelse fatal("internal: no Ctx has been created", .{});
}

// ---- text number parsing (source/util/parse_number.{h,cpp} and the parsing half of util/hex_float.h) ----
//
// What the C++ does with std::istringstream is reproduced here for the cases the optimizer can reach:
//   * integers: libstdc++ num_get with std::setbase(0) (decimal, 0x hex, leading-0 octal), sign accepted
//     for signed and unsigned types, whole text must be consumed;
//   * IEEE 16/32/64-bit floats: HexFloat<>::operator>> (hex floats `0x1.8p3`, `p` lower case only, the
//     exponent is mandatory, out-of-range hex exponents saturate to infinity) and the decimal path
//     (libstdc++ float extraction, overflow to infinity is a failure, 16-bit floats are parsed as a
//     32-bit float and truncated toward zero).
// Other float encodings (bfloat16, fp8, ...) are unsupported, like the C++ for an unknown encoding.

/// The kind of number a literal is read as.
pub const NumKind = enum { none, unsigned_int, signed_int, floating };

/// How a literal is read: its kind and its width in bits.
pub const NumberType = struct {
    bitwidth: u32,
    kind: NumKind,
};

/// Result of reading a literal: `unsupported` for a width or float encoding that is not handled, `invalid_usage` for a type
/// that cannot be read this way (a negative number for an unsigned type, no number kind), `invalid_text` when the text is
/// not a number of that type or does not fit it.
pub const EncodeStatus = enum { success, unsupported, invalid_usage, invalid_text };

/// C isspace() for ASCII.
fn npIsSpace(c: u8) bool {
    return c == ' ' or (c >= 9 and c <= 13);
}

/// The character at `i`, or -1 past the end (like the end of an istream).
fn npAt(text: []const u8, i: usize) i32 {
    return if (i < text.len) @as(i32, text[i]) else -1;
}

/// The value of a hexadecimal digit, or null.
fn npDigitValue(c: u8) ?u32 {
    if (c >= '0' and c <= '9') return c - '0';
    if (c >= 'a' and c <= 'f') return c - 'a' + 10;
    if (c >= 'A' and c <= 'F') return c - 'A' + 10;
    return null;
}

/// ParseNumber(text, T*) for an integer type T (u32, u64 or i64).
pub fn parseNumberInt(comptime T: type, text: []const u8) ?T {
    if (text.len == 0) return null;
    const is_signed: bool = @typeInfo(T).int.signedness == .signed;
    const U = @Int(.unsigned, @typeInfo(T).int.bits);
    const max_pos: u64 = std.math.maxInt(T);
    const max_neg: u64 = if (is_signed) max_pos + 1 else max_pos;

    var i: usize = 0;
    while (i < text.len and npIsSpace(text[i])) i += 1;
    var negative: bool = false;
    if (i < text.len and (text[i] == '+' or text[i] == '-')) {
        negative = text[i] == '-';
        i += 1;
    }
    var base: u64 = 10;
    var found_zero: bool = false;
    if (i < text.len and text[i] == '0') {
        found_zero = true;
        i += 1;
        if (i < text.len and (text[i] == 'x' or text[i] == 'X')) {
            base = 16;
            i += 1;
            found_zero = false;
        } else {
            base = 8;
        }
    }
    const max: u64 = if (negative) max_neg else max_pos;
    var mag: u64 = 0;
    var ndigits: usize = 0;
    var overflow: bool = false;
    while (i < text.len) {
        const d: u32 = npDigitValue(text[i]) orelse break;
        if (d >= base) break;
        if (mag > (max - d) / base) overflow = true;
        if (!overflow) mag = mag * base + d;
        ndigits += 1;
        i += 1;
    }
    if (ndigits == 0 and !found_zero) return null;
    if (overflow) return null;
    if (i != text.len) return null; // the stream must reach eof
    var value: T = undefined;
    if (negative) {
        const wrapped: U = @truncate(0 -% mag);
        value = @bitCast(wrapped);
    } else {
        const wrapped: U = @truncate(mag);
        value = @bitCast(wrapped);
    }
    // ClampToZeroIfUnsignedType: a leading '-' on an unsigned target only succeeds for zero.
    if (!is_signed and text[0] == '-' and value != 0) return null;
    return value;
}

/// True when `value` fits the type. For hexadecimal text, a value that has the sign bit of the type set is sign-extended
/// into `updated`.
fn npCheckRangeAndIfHexThenSignExtend(comptime T: type, value: T, ty: NumberType, is_hex: bool, updated: *T) bool {
    const bit_width: u32 = ty.bitwidth;
    var magnitude_mask: u64 = if (bit_width == 64) ~@as(u64, 0) else ((@as(u64, 1) << @intCast(bit_width)) - 1);
    var sign_mask: u64 = 0;
    const overflow_mask: u64 = ~magnitude_mask;
    const type_is_signed: bool = ty.kind == .floating or ty.kind == .signed_int;
    const value_bits: u64 = if (@typeInfo(T).int.signedness == .signed) @bitCast(value) else value;
    const is_neg: bool = @typeInfo(T).int.signedness == .signed and value < 0;
    if (is_neg or type_is_signed) {
        magnitude_mask >>= 1;
        sign_mask = magnitude_mask + 1;
    }
    var failed: bool = false;
    if (is_neg) {
        failed = ((value_bits & overflow_mask) != overflow_mask) or ((value_bits & sign_mask) != sign_mask);
    } else if (is_hex) {
        failed = (value_bits & overflow_mask) != 0;
    } else {
        failed = (value_bits & magnitude_mask) != value_bits;
    }
    if (failed) return false;
    if (is_hex and (value_bits & sign_mask) != 0) {
        const nv: u64 = value_bits | overflow_mask;
        updated.* = if (@typeInfo(T).int.signedness == .signed) @bitCast(nv) else nv;
    }
    return true;
}

/// Reads an integer literal of the given type and appends its words, low word first.
fn npParseAndEncodeInteger(text: []const u8, ty: NumberType, out: *List(u32)) EncodeStatus {
    if (ty.kind != .unsigned_int and ty.kind != .signed_int) return .invalid_usage;
    const bit_width: u32 = ty.bitwidth;
    if (bit_width > 64) return .unsupported;
    const is_negative: bool = text.len > 0 and text[0] == '-';
    const can_be_signed: bool = ty.kind == .signed_int;
    if (is_negative and !can_be_signed) return .invalid_usage;
    const is_hex: bool = text.len > 1 and text[0] == '0' and (text[1] == 'x' or text[1] == 'X');
    var decoded_bits: u64 = undefined;
    if (is_negative) {
        var decoded_signed = parseNumberInt(i64, text) orelse return .invalid_text;
        if (!npCheckRangeAndIfHexThenSignExtend(i64, decoded_signed, ty, is_hex, &decoded_signed)) return .invalid_text;
        decoded_bits = @bitCast(decoded_signed);
    } else {
        decoded_bits = parseNumberInt(u64, text) orelse return .invalid_text;
        if (!npCheckRangeAndIfHexThenSignExtend(u64, decoded_bits, ty, is_hex, &decoded_bits)) return .invalid_text;
    }
    if (bit_width > 32) {
        out.push(@truncate(decoded_bits));
        out.push(@truncate(decoded_bits >> 32));
    } else {
        out.push(@truncate(decoded_bits));
    }
    return .success;
}

// ---- floating point ----------------------------------------------------------------------------------

/// The grammar libstdc++'s float extraction accepts for the text that follows an already consumed sign:
/// digits [. digits] [(e|E) [sign] digits] with at least one mantissa digit, and nothing after it.
fn npIsDecimalFloatText(s: []const u8) bool {
    var i: usize = 0;
    var mantissa: bool = false;
    while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) mantissa = true;
    if (i < s.len and s[i] == '.') {
        i += 1;
        while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) mantissa = true;
    }
    if (!mantissa) return false;
    if (i < s.len and (s[i] == 'e' or s[i] == 'E')) {
        i += 1;
        if (i < s.len and (s[i] == '+' or s[i] == '-')) i += 1;
        var exp_digits: bool = false;
        while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) exp_digits = true;
        if (!exp_digits) return false;
    }
    return i == s.len;
}

/// float -> IEEE half bits, rounding toward zero (HexFloat::castTo with round_direction::kToZero).
/// Returns null when the value overflows the half range (the C++ then reports a parse failure).
fn npF32ToHalfTruncate(f: f32) ?u16 {
    const bits: u32 = @bitCast(f);
    const sign: u16 = @truncate((bits >> 16) & 0x8000);
    const exp_field: u32 = (bits >> 23) & 0xFF;
    const frac: u32 = bits & 0x7FFFFF;
    if (exp_field == 0xFF) return null; // inf / nan never get here, kept as a guard
    if (exp_field == 0) return sign; // zero or an f32 denormal: far below the smallest half denormal
    const e: i32 = @as(i32, @intCast(exp_field)) - 127;
    if (e > 15) return null;
    if (e >= -14) {
        const half_exp: u16 = @intCast(e + 15);
        const half_frac: u16 = @truncate(frac >> 13);
        return sign | (half_exp << 10) | half_frac;
    }
    // half denormal: trunc((1.frac) * 2^(e + 24)) as a 10-bit integer
    const shift: i32 = -e - 1;
    if (shift >= 32) return sign;
    const sig: u32 = (1 << 23) | frac;
    const half_frac: u16 = @truncate(sig >> @intCast(shift));
    return sign | half_frac;
}

/// Sets the bit `n` places below the most significant one, when `bit` is not 0.
fn npSetNthMsb(comptime UInt: type, value: UInt, bit: UInt, n: UInt) UInt {
    const max_position: UInt = @bitSizeOf(UInt) - 1;
    if (bit != 0 and n <= max_position) {
        return value | (bit << @intCast(max_position - n));
    }
    return value;
}

/// Increments `v`; false (and no change) at the maximum.
fn npSatInc(comptime T: type, v: *T) bool {
    if (v.* == std.math.maxInt(T)) return false;
    v.* += 1;
    return true;
}

/// Decrements `v`; false (and no change) at the minimum.
fn npSatDec(comptime T: type, v: *T) bool {
    if (v.* == std.math.minInt(T)) return false;
    v.* -= 1;
    return true;
}

/// The body of HexFloat<T>::operator>> after the "0x" prefix and the sign have been consumed.
/// `rest` is the text after the prefix. Returns the encoded bits, null on a parse failure.
fn npParseHexFloatBits(comptime UInt: type, comptime Int: type, comptime exp_bits: u32, comptime frac_bits: u32, rest: []const u8, negative: bool) ?UInt {
    const used_bits: u32 = 1 + exp_bits + frac_bits;
    const exponent_bias: Int = (1 << (exp_bits - 1)) - 1;
    const top_bit_left_shift: u32 = used_bits - 1;
    const fraction_encode_mask: UInt = @intCast((@as(u64, 1) << frac_bits) - 1);
    const exponent_mask: UInt = @intCast(((@as(u64, 1) << exp_bits) - 1) << frac_bits);
    const exponent_left_shift: u32 = frac_bits;
    const fraction_right_shift: u32 = @bitSizeOf(UInt) - frac_bits;
    const max_exponent: Int = @intCast((@as(u64, 1) << exp_bits) - 1);

    var pos: usize = 0;
    var seen_p: bool = false;
    var seen_dot: bool = false;
    var fraction: UInt = 0;
    var fraction_index: UInt = 0;
    var exponent: Int = exponent_bias;

    while (npAt(rest, pos) == '0') pos += 1;
    var next_char: i32 = npAt(rest, pos);

    var has_integer_part: bool = false;
    var bits_written: bool = false;
    while (!seen_p and !seen_dot) {
        if (next_char == '.') {
            seen_dot = true;
        } else if (next_char == 'p') {
            seen_p = true;
        } else if (next_char >= 0 and std.ascii.isHex(@intCast(next_char))) {
            has_integer_part = true;
            var number: u32 = npDigitValue(@intCast(next_char)).?;
            var k: u32 = 0;
            while (k < 4) : ({
                k += 1;
                number <<= 1;
            }) {
                const write_bit: UInt = if ((number & 0x8) != 0) 1 else 0;
                if (bits_written) {
                    fraction = npSetNthMsb(UInt, fraction, write_bit, fraction_index);
                    _ = npSatInc(UInt, &fraction_index);
                    if (!npSatInc(Int, &exponent)) return null;
                }
                bits_written = bits_written or write_bit != 0;
            }
        } else {
            return null;
        }
        pos += 1;
        next_char = npAt(rest, pos);
    }

    bits_written = false;
    while (seen_dot and !seen_p) {
        if (next_char == 'p') {
            seen_p = true;
        } else if (next_char >= 0 and std.ascii.isHex(@intCast(next_char))) {
            var number: u32 = npDigitValue(@intCast(next_char)).?;
            var k: u32 = 0;
            while (k < 4) : ({
                k += 1;
                number <<= 1;
            }) {
                const write_bit: UInt = if ((number & 0x8) != 0) 1 else 0;
                bits_written = bits_written or write_bit != 0;
                if (!has_integer_part and !bits_written) {
                    if (!npSatDec(Int, &exponent)) return null;
                } else {
                    fraction = npSetNthMsb(UInt, fraction, write_bit, fraction_index);
                    _ = npSatInc(UInt, &fraction_index);
                }
            }
        } else {
            return null;
        }
        pos += 1;
        next_char = npAt(rest, pos);
    }

    var seen_exponent_sign: bool = false;
    var exponent_sign: Int = 1;
    var seen_written_exponent_digits: bool = false;
    var written_exponent: Int = 0;
    const written_exponent_overflow: Int = std.math.maxInt(Int) - 1;
    while (true) {
        if (!seen_written_exponent_digits and (next_char == '-' or next_char == '+')) {
            if (seen_exponent_sign) return null;
            seen_exponent_sign = true;
            exponent_sign = if (next_char == '-') -1 else 1;
        } else if (next_char >= '0' and next_char <= '9') {
            seen_written_exponent_digits = true;
            const digit: Int = @intCast(next_char - '0');
            if (written_exponent >= @divTrunc(written_exponent_overflow - digit, 10)) {
                written_exponent = written_exponent_overflow;
            } else {
                written_exponent = written_exponent * 10 + digit;
            }
        } else {
            break;
        }
        pos += 1;
        next_char = npAt(rest, pos);
    }
    if (!seen_written_exponent_digits) return null;
    if (pos != rest.len) return null; // trailing text: the stream is not at eof
    written_exponent = written_exponent *% exponent_sign;

    if (written_exponent >= 0 and exponent >= 0) {
        if (written_exponent_overflow - exponent > written_exponent) {
            exponent = written_exponent + exponent;
        } else {
            exponent = written_exponent_overflow;
        }
    } else if (written_exponent < 0 and exponent < 0) {
        if (written_exponent_overflow + exponent > -written_exponent) {
            exponent = written_exponent + exponent;
        } else {
            exponent = -written_exponent_overflow;
        }
    } else {
        exponent = written_exponent + exponent;
    }

    var is_zero: bool = (!has_integer_part) and (fraction == 0);
    if ((!has_integer_part) and !is_zero) {
        fraction = fraction << 1;
        exponent -%= 1;
    } else if (is_zero) {
        exponent = 0;
    }
    if (exponent <= 0 and !is_zero) {
        fraction = fraction >> 1;
        fraction |= @as(UInt, 1) << @intCast(top_bit_left_shift);
    }
    fraction = (fraction >> @intCast(fraction_right_shift)) & fraction_encode_mask;
    while (exponent < 0 and !is_zero) {
        fraction = fraction >> 1;
        exponent += 1;
        fraction &= fraction_encode_mask;
        if (fraction == 0) {
            is_zero = true;
            exponent = 0;
        }
    }
    if (exponent > max_exponent) {
        exponent = max_exponent;
        fraction = 0;
    }
    var output_bits: UInt = @as(UInt, if (negative) 1 else 0) << @intCast(top_bit_left_shift);
    output_bits |= fraction;
    const shifted_exponent: UInt = @as(UInt, @truncate(@as(u64, @bitCast(@as(i64, exponent))) << @intCast(exponent_left_shift))) & exponent_mask;
    output_bits |= shifted_exponent;
    return output_bits;
}

/// Parses `text` as the literal of an IEEE float of `width` bits (16, 32 or 64), as ParseNumber on a
/// HexFloat<FloatProxy<...>> does. Returns the bit pattern, or null when the C++ reports failure.
fn npParseFloatBits(text: []const u8, width: u32) ?u64 {
    var i: usize = 0;
    while (i < text.len and npIsSpace(text[i])) i += 1;
    if (text.len == 0) return null;
    var negative: bool = false;
    var have_sign: bool = false;
    var c: i32 = npAt(text, i);
    var hex_rest: ?[]const u8 = null;
    if (c == '-' or c == '0' or c == '+') {
        if (c == '-' or c == '+') {
            negative = c == '-';
            have_sign = true;
            i += 1;
            c = npAt(text, i);
        }
        if (c == '0') {
            const maybe_x: i32 = npAt(text, i + 1);
            if (maybe_x == 'x' or maybe_x == 'X') hex_rest = text[i + 2 ..];
        }
    }
    if (hex_rest) |rest| {
        return switch (width) {
            16 => if (npParseHexFloatBits(u16, i16, 5, 10, rest, negative)) |b| @as(u64, b) else null,
            32 => if (npParseHexFloatBits(u32, i32, 8, 23, rest, negative)) |b| @as(u64, b) else null,
            64 => npParseHexFloatBits(u64, i64, 11, 52, rest, negative),
            else => null,
        };
    }
    // decimal path: ParseNormalFloat
    const body: []const u8 = text[i..];
    if (have_sign and body.len > 0 and (body[0] == '-' or body[0] == '+')) return null; // RejectParseDueToLeadingSign
    if (!npIsDecimalFloatText(body)) return null;
    switch (width) {
        64 => {
            var v = std.fmt.parseFloat(f64, body) catch return null;
            if (std.math.isInf(v)) return null;
            if (negative) v = -v;
            return @as(u64, @bitCast(v));
        },
        32, 16 => {
            var v = std.fmt.parseFloat(f32, body) catch return null;
            if (std.math.isInf(v)) return null;
            if (negative) v = -v;
            if (width == 32) return @as(u64, @as(u32, @bitCast(v)));
            const h: u16 = npF32ToHalfTruncate(v) orelse return null;
            return @as(u64, h);
        },
        else => return null,
    }
}

/// Reads a floating point literal of a 16, 32 or 64-bit type and appends its words, low word first.
fn npParseAndEncodeFloat(text: []const u8, ty: NumberType, out: *List(u32)) EncodeStatus {
    if (ty.kind != .floating) return .invalid_usage;
    switch (ty.bitwidth) {
        16, 32, 64 => {},
        else => return .unsupported,
    }
    const bits: u64 = npParseFloatBits(text, ty.bitwidth) orelse return .invalid_text;
    if (ty.bitwidth == 64) {
        out.push(@truncate(bits));
        out.push(@truncate(bits >> 32));
    } else {
        out.push(@truncate(bits));
    }
    return .success;
}

/// utils::ParseAndEncodeNumber with an unknown float encoding (the width decides it).
/// On success the encoded words are appended to `out`.
pub fn parseAndEncodeNumber(text: []const u8, ty: NumberType, out: *List(u32)) EncodeStatus {
    if (ty.kind == .none) return .invalid_usage;
    if (ty.kind == .floating) return npParseAndEncodeFloat(text, ty, out);
    return npParseAndEncodeInteger(text, ty, out);
}

// InstructionFolder: folds an instruction to a constant or rewrites it into a simpler one (port of source/opt/fold.cpp,
// fold.h).
//
// The C++ InstructionFolder owns two rule tables built once per IRContext. Here the tables are comptime switches
// (constFoldingRulesFor / foldingRulesFor) and the folder is a namespace of functions taking the Ctx;
// the only runtime state is the GLSL.std.450 import id captured when the folder is first used (Ctx.folder_glsl_id).
//
// The behaviour of a release build is kept on purpose: the `default` arms of the C++ unary/binary/ternary switches assert
// false and return 0 in a release build, so they return 0 here too (FoldScalars of OpIAdd & co. reaches them when the
// constant folding rules decline, e.g. a division by zero, and the C++ then folds to the constant 0).

/// A rule that rewrites an instruction in place from the constant values of its operands; true when it changed it.
pub const FoldingRule = *const fn (ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool;
/// A rule that computes the constant that an instruction evaluates to from the constant values of its operands, or null.
pub const ConstFoldingRule = *const fn (ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant;

/// The identity id map for the folder entry points that take one.
pub const FoldIdentityMap = struct {
    pub fn map(_: void, id: u32) u32 {
        return id;
    }
};

// ---- Instruction helpers that need the context (Instruction::IsFoldableBy*, IsFloatingPointFoldingAllowed) -------

/// Fold.getGlslId(): the GLSL.std.450 import id the rule tables are keyed on (captured on first use, like the C++).
pub fn foldGlslId(ctx: *Ctx) u32 {
    if (!ctx.folder_built) {
        ctx.folder_built = true;
        ctx.folder_glsl_id = ctx.getFeatureMgr().extinst_importid_glsl_std_450;
    }
    return ctx.folder_glsl_id;
}

// ---- composite rules ----------------------------------------------------------------------------------------

fn cfrFoldExtractWithConstants(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    var c: *const Constant = constants[0] orelse return null;
    var i: usize = 1;
    while (i < inst.numInOperands()) : (i += 1) {
        const element_index: u32 = inst.getSingleWordInOperand(i);
        if (c.isNull()) {
            const cm: *ConstMgr = ctx.getConstantMgr();
            const tm: *TypeMgr = ctx.getTypeMgr();
            return cm.getConstant(tm.getType(inst.typeId()), &.{});
        }
        check(c.isComposite(), "FoldExtractWithConstants: not a composite constant");
        if (element_index >= c.components.len()) return null;
        c = c.components.items[element_index];
    }
    return c;
}

fn cfrDef(cm: *ConstMgr, c: ?*const Constant) ?*Inst {
    return cm.getDefiningInstruction(c, 0, null);
}

fn cfrFoldInsertWithConstants(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    const cm: *ConstMgr = ctx.getConstantMgr();
    const object: *const Constant = constants[0] orelse return null;
    var composite: *const Constant = constants[1] orelse return null;
    var chain: List(*const Constant) = .{};
    var components: []const *const Constant = &.{};
    var ty: ?*const Type = null;
    const final_index: usize = inst.numInOperands() - 1;
    var i: usize = 2;
    while (i < inst.numInOperands()) : (i += 1) {
        ty = composite.ty;
        if (composite.isNull()) {
            if (cm.getNullCompositeConstant(ty)) |new_composite| {
                if (i != final_index) chain.push(new_composite);
                components = new_composite.components.items;
            } else {
                return null;
            }
        } else {
            if (i != final_index) chain.push(composite);
            components = composite.components.items;
        }
        const index: u32 = inst.getSingleWordInOperand(i);
        if (index >= components.len) return null;
        composite = components[index];
    }
    const final_operand: u32 = inst.getSingleWordInOperand(final_index);
    var ids: List(u32) = .{};
    for (components, 0..) |comp, k| {
        const constant: *const Constant = if (k == final_operand) object else comp;
        const member_inst: *Inst = cfrDef(cm, constant) orelse return null;
        ids.push(member_inst.resultId());
    }
    var new_constant: ?*const Constant = cm.getConstant(ty, ids.items);
    var ci: usize = chain.len();
    while (ci > 0) : (ci -= 1) {
        _ = cm.buildInstructionAndAddToModule(new_constant, null, 0);
        composite = chain.items[ci - 1];
        components = composite.components.items;
        ty = composite.ty;
        ids.items.len = 0;
        for (components, 0..) |comp, k| {
            const index: u32 = inst.getSingleWordInOperand(1 + ci);
            const constant: ?*const Constant = if (k == index) new_constant else comp;
            const constant_id: u32 = cm.findDeclaredConstantId(constant, 0);
            ids.push(constant_id);
        }
        new_constant = cm.getConstant(ty, ids.items);
    }
    return new_constant;
}

fn cfrFoldVectorShuffleWithConstants(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    check(inst.op == .OpVectorShuffle, "FoldVectorShuffleWithConstants: not a shuffle");
    const c1: *const Constant = constants[0] orelse return null;
    const c2: *const Constant = constants[1] orelse return null;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const c1_vec: *const TyVector = c1.ty.as(.vector) orelse fatal("FoldVectorShuffleWithConstants: not a vector", .{});
    const element_type: *const Type = c1_vec.element;
    var c1_components: List(*const Constant) = .{};
    if (c1.kind == .vector) {
        c1_components.pushSlice(c1.components.items);
    } else {
        const element: *const Constant = cm.getConstant(element_type, &.{}) orelse return null;
        var k: u32 = 0;
        while (k < c1_vec.count) : (k += 1) c1_components.push(element);
    }
    const c2_vec: *const TyVector = c2.ty.as(.vector) orelse fatal("FoldVectorShuffleWithConstants: not a vector", .{});
    var c2_components: List(*const Constant) = .{};
    if (c2.kind == .vector) {
        c2_components.pushSlice(c2.components.items);
    } else {
        const element: *const Constant = cm.getConstant(element_type, &.{}) orelse return null;
        var k: u32 = 0;
        while (k < c2_vec.count) : (k += 1) c2_components.push(element);
    }
    var ids: List(u32) = .{};
    const undef_literal_value: u32 = 0xffffffff;
    var i: usize = 2;
    while (i < inst.numInOperands()) : (i += 1) {
        const index: u32 = inst.getSingleWordInOperand(i);
        if (index == undef_literal_value) {
            return null;
        } else if (index < c1_components.len()) {
            const member_inst: *Inst = cfrDef(cm, c1_components.items[index]) orelse return null;
            ids.push(member_inst.resultId());
        } else {
            const member_inst: *Inst = cfrDef(cm, c2_components.items[index - c1_components.len()]) orelse return null;
            ids.push(member_inst.resultId());
        }
    }
    return cm.getConstant(ctx.getTypeMgr().getType(inst.typeId()), ids.items);
}

fn cfrFoldCompositeWithConstants(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    const cm: *ConstMgr = ctx.getConstantMgr();
    const new_type: ?*Type = ctx.getTypeMgr().getType(inst.typeId());
    const type_inst: *Inst = ctx.getDefUseMgr().getDef(inst.typeId()) orelse fatal("FoldCompositeWithConstants: no type instruction", .{});
    var ids: List(u32) = .{};
    for (constants, 0..) |element_opt, i| {
        const element_const: *const Constant = element_opt orelse return null;
        var component_type_id: u32 = 0;
        if (type_inst.op == .OpTypeStruct) {
            component_type_id = type_inst.getSingleWordInOperand(i);
        } else if (type_inst.op == .OpTypeArray) {
            component_type_id = type_inst.getSingleWordInOperand(0);
        }
        const element_id: u32 = cm.findDeclaredConstantId(element_const, component_type_id);
        if (element_id == 0) return null;
        ids.push(element_id);
    }
    return cm.getConstant(new_type, ids.items);
}

const InstNoContractionFound = struct {
    found: *bool,

    fn visit(self: InstNoContractionFound, _: *Inst) bool {
        self.found.* = true;
        return false;
    }
};

pub fn instIsFloatingPointFoldingAllowed(ctx: *Ctx, inst: *const Inst) bool {
    // The C++ leaves kernels unhandled here: it is pessimistic and does not support SPV_KHR_float_controls. So is this.
    const fm: *FeatureMgr = ctx.getFeatureMgr();
    if (!fm.hasCapability(.Shader) or
        fm.hasCapability(.DenormPreserve) or
        fm.hasCapability(.DenormFlushToZero) or
        fm.hasCapability(.SignedZeroInfNanPreserve) or
        fm.hasCapability(.RoundingModeRTZ) or
        fm.hasCapability(.RoundingModeRTE))
    {
        return false;
    }
    var is_nocontract: bool = false;
    _ = ctx.getDecorationMgr().whileEachDecoration(inst.resultId(), @intFromEnum(Decoration.NoContraction), InstNoContractionFound{ .found = &is_nocontract }, InstNoContractionFound.visit);
    return !is_nocontract;
}

/// utils::FloatProxy<float>(x).GetWords()
pub fn fpWordsF32(x: f32) [1]u32 {
    return .{@bitCast(x)};
}

/// utils::FloatProxy<double>(x).GetWords()
pub fn fpWordsF64(x: f64) [2]u32 {
    const b: u64 = @bitCast(x);
    return .{ @truncate(b), @truncate(b >> 32) };
}

fn cfrHasFloatingPoint(ty: *const Type) bool {
    if (ty.as(.float) != null) return true;
    if (ty.as(.vector)) |vt| return vt.element.as(.float) != null;
    return false;
}

// ---- vector / matrix products ----------------------------------------------------------------------------------

fn cfrFoldVectorTimesScalar(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    check(inst.op == .OpVectorTimesScalar, "FoldVectorTimesScalar: not OpVectorTimesScalar");
    const cm: *ConstMgr = ctx.getConstantMgr();
    const tm: *TypeMgr = ctx.getTypeMgr();
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) {
        if (cfrHasFloatingPoint(tm.getType(inst.typeId()).?)) return null;
    }
    const c1: ?*const Constant = constants[0];
    const c2: ?*const Constant = constants[1];
    if (c1) |c| {
        if (c.isZero()) return c;
    }
    if (c2) |c| {
        if (c.isZero()) return cm.getConstant(tm.getType(inst.typeId()), &.{});
    }
    if (c1 == null or c2 == null) return null;
    const result_type: *const Type = tm.getType(inst.typeId()).?;
    const vector_type: *const TyVector = result_type.as(.vector) orelse fatal("FoldVectorTimesScalar: not a vector result", .{});
    const element_type: *const Type = vector_type.element;
    const float_type: *const TyFloat = element_type.as(.float) orelse fatal("FoldVectorTimesScalar: not a float vector", .{});
    const c1_components: List(*const Constant) = c1.?.getVectorComponents(cm);
    var ids: List(u32) = .{};
    if (float_type.width == 32) {
        const scalar: f32 = c2.?.getFloat();
        for (c1_components.items) |comp| {
            const words: [1]u32 = fpWordsF32(comp.getFloat() * scalar);
            const new_elem: ?*const Constant = cm.getConstant(element_type, &words);
            const inst_elem: *Inst = cfrDef(cm, new_elem) orelse return null;
            ids.push(inst_elem.resultId());
        }
        return cm.getConstant(result_type, ids.items);
    } else if (float_type.width == 64) {
        const scalar: f64 = c2.?.getDouble();
        for (c1_components.items) |comp| {
            const words: [2]u32 = fpWordsF64(comp.getDouble() * scalar);
            const new_elem: ?*const Constant = cm.getConstant(element_type, &words);
            const inst_elem: *Inst = cfrDef(cm, new_elem) orelse return null;
            ids.push(inst_elem.resultId());
        }
        return cm.getConstant(result_type, ids.items);
    }
    return null;
}

fn cfrTransposeMatrix(matrix: *const Constant, result_type: *const Type, ctx: *Ctx) ?*const Constant {
    const cm: *ConstMgr = ctx.getConstantMgr();
    if (matrix.isNull()) return cm.getNullCompositeConstant(result_type);
    const columns: []*const Constant = matrix.components.items;
    const number_of_rows: u32 = columns[0].ty.as(.vector).?.count;
    var result_elements: List(List(u32)) = .{};
    var r: u32 = 0;
    while (r < number_of_rows) : (r += 1) result_elements.push(.{});
    for (columns) |column_in| {
        var column: *const Constant = column_in;
        if (column.isNull()) column = cm.getNullCompositeConstant(column.ty) orelse return null;
        const column_components: []*const Constant = column.components.items;
        var row: u32 = 0;
        while (row < number_of_rows) : (row += 1) {
            const def: *Inst = cfrDef(cm, column_components[row]) orelse return null;
            result_elements.items[row].push(def.resultId());
        }
    }
    const rm: *const TyMatrix = result_type.as(.matrix) orelse fatal("TransposeMatrix: not a matrix type", .{});
    var result_columns: List(u32) = .{};
    var col: u32 = 0;
    while (col < number_of_rows) : (col += 1) {
        const element: ?*const Constant = cm.getConstant(rm.element, result_elements.items[col].items);
        const def: *Inst = cfrDef(cm, element) orelse return null;
        result_columns.push(def.resultId());
    }
    return cm.getConstant(result_type, result_columns.items);
}

fn cfrFoldTranspose(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    check(inst.op == .OpTranspose, "FoldTranspose: not OpTranspose");
    const tm: *TypeMgr = ctx.getTypeMgr();
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) {
        if (cfrHasFloatingPoint(tm.getType(inst.typeId()).?)) return null;
    }
    const matrix: *const Constant = constants[0] orelse return null;
    const result_type: *const Type = tm.getType(inst.typeId()).?;
    check(result_type.as(.matrix) != null, "FoldTranspose: result is not a matrix");
    return cfrTransposeMatrix(matrix, result_type, ctx);
}

fn cfrFoldVectorTimesMatrix(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    check(inst.op == .OpVectorTimesMatrix, "FoldVectorTimesMatrix: not OpVectorTimesMatrix");
    const cm: *ConstMgr = ctx.getConstantMgr();
    const tm: *TypeMgr = ctx.getTypeMgr();
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) {
        if (cfrHasFloatingPoint(tm.getType(inst.typeId()).?)) return null;
    }
    const c1: *const Constant = constants[0] orelse return null;
    const c2: *const Constant = constants[1] orelse return null;
    const result_type: *const Type = tm.getType(inst.typeId()).?;
    const vector_type: *const TyVector = result_type.as(.vector) orelse fatal("FoldVectorTimesMatrix: not a vector result", .{});
    const element_type: *const Type = vector_type.element;
    const float_type: *const TyFloat = element_type.as(.float) orelse fatal("FoldVectorTimesMatrix: not a float vector", .{});
    const result_vector_size: u32 = vector_type.count;
    var ids: List(u32) = .{};
    if (c1.isZero() or c2.isZero()) {
        var words: List(u32) = .{};
        var w: u32 = 0;
        while (w < float_type.width / 32) : (w += 1) words.push(0);
        var i: u32 = 0;
        while (i < result_vector_size) : (i += 1) {
            const new_elem: ?*const Constant = cm.getConstant(element_type, words.items);
            const def: *Inst = cfrDef(cm, new_elem) orelse return null;
            ids.push(def.resultId());
        }
        return cm.getConstant(result_type, ids.items);
    }
    const c1_components: List(*const Constant) = c1.getVectorComponents(cm);
    const c2_components: []*const Constant = c2.components.items;
    if (float_type.width == 32) {
        var i: u32 = 0;
        while (i < result_vector_size) : (i += 1) {
            var result_scalar: f32 = 0.0;
            if (!c2_components[i].isNull()) {
                const c2_vec: *const Constant = c2_components[i];
                for (c2_vec.components.items, 0..) |c2c, j| {
                    const c1_scalar: f32 = c1_components.items[j].getFloat();
                    const c2_scalar: f32 = c2c.getFloat();
                    result_scalar += c1_scalar * c2_scalar;
                }
            }
            const words: [1]u32 = fpWordsF32(result_scalar);
            const new_elem: ?*const Constant = cm.getConstant(element_type, &words);
            const def: *Inst = cfrDef(cm, new_elem) orelse return null;
            ids.push(def.resultId());
        }
        return cm.getConstant(result_type, ids.items);
    } else if (float_type.width == 64) {
        for (0..c2_components.len) |i| {
            var result_scalar: f64 = 0.0;
            if (!c2_components[i].isNull()) {
                const c2_vec: *const Constant = c2_components[i];
                for (c2_vec.components.items, 0..) |c2c, j| {
                    const c1_scalar: f64 = c1_components.items[j].getDouble();
                    const c2_scalar: f64 = c2c.getDouble();
                    result_scalar += c1_scalar * c2_scalar;
                }
            }
            const words: [2]u32 = fpWordsF64(result_scalar);
            const new_elem: ?*const Constant = cm.getConstant(element_type, &words);
            const def: *Inst = cfrDef(cm, new_elem) orelse return null;
            ids.push(def.resultId());
        }
        return cm.getConstant(result_type, ids.items);
    }
    return null;
}

fn cfrFoldMatrixTimesVector(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    check(inst.op == .OpMatrixTimesVector, "FoldMatrixTimesVector: not OpMatrixTimesVector");
    const cm: *ConstMgr = ctx.getConstantMgr();
    const tm: *TypeMgr = ctx.getTypeMgr();
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) {
        if (cfrHasFloatingPoint(tm.getType(inst.typeId()).?)) return null;
    }
    const c1: *const Constant = constants[0] orelse return null;
    const c2: *const Constant = constants[1] orelse return null;
    const result_type: *const Type = tm.getType(inst.typeId()).?;
    const vector_type: *const TyVector = result_type.as(.vector) orelse fatal("FoldMatrixTimesVector: not a vector result", .{});
    const element_type: *const Type = vector_type.element;
    const float_type: *const TyFloat = element_type.as(.float) orelse fatal("FoldMatrixTimesVector: not a float vector", .{});
    const result_vector_size: u32 = vector_type.count;
    var ids: List(u32) = .{};
    if (c1.isZero() or c2.isZero()) {
        var words: List(u32) = .{};
        var w: u32 = 0;
        while (w < float_type.width / 32) : (w += 1) words.push(0);
        var i: u32 = 0;
        while (i < result_vector_size) : (i += 1) {
            const new_elem: ?*const Constant = cm.getConstant(element_type, words.items);
            const def: *Inst = cfrDef(cm, new_elem) orelse return null;
            ids.push(def.resultId());
        }
        return cm.getConstant(result_type, ids.items);
    }
    const c1_components: []*const Constant = c1.components.items;
    const c2_components: List(*const Constant) = c2.getVectorComponents(cm);
    if (float_type.width == 32) {
        var i: u32 = 0;
        while (i < result_vector_size) : (i += 1) {
            var result_scalar: f32 = 0.0;
            for (c1_components, 0..) |c1c, j| {
                if (!c1c.isNull()) {
                    const c1_scalar: f32 = c1c.components.items[i].getFloat();
                    const c2_scalar: f32 = c2_components.items[j].getFloat();
                    result_scalar += c1_scalar * c2_scalar;
                }
            }
            const words: [1]u32 = fpWordsF32(result_scalar);
            const new_elem: ?*const Constant = cm.getConstant(element_type, &words);
            const def: *Inst = cfrDef(cm, new_elem) orelse return null;
            ids.push(def.resultId());
        }
        return cm.getConstant(result_type, ids.items);
    } else if (float_type.width == 64) {
        var i: u32 = 0;
        while (i < result_vector_size) : (i += 1) {
            var result_scalar: f64 = 0.0;
            for (c1_components, 0..) |c1c, j| {
                if (!c1c.isNull()) {
                    const c1_scalar: f64 = c1c.components.items[i].getDouble();
                    const c2_scalar: f64 = c2_components.items[j].getDouble();
                    result_scalar += c1_scalar * c2_scalar;
                }
            }
            const words: [2]u32 = fpWordsF64(result_scalar);
            const new_elem: ?*const Constant = cm.getConstant(element_type, &words);
            const def: *Inst = cfrDef(cm, new_elem) orelse return null;
            ids.push(def.resultId());
        }
        return cm.getConstant(result_type, ids.items);
    }
    return null;
}

// Constant folding rules: how an opcode applied to constant operands folds to a constant (port of
// source/opt/const_folding_rules.cpp/.h)
//
// Every C++ rule factory (a function returning a lambda) is a comptime function returning a plain function pointer;
// the per-opcode lists are `comptime &[_]ConstFoldingRule{...}` in registration order (the first rule that
// returns a constant wins). Where the C++ passes `const analysis::Float*` / `Integer*` / `Vector*` as a `Type*`,
// the Zig keeps the original `*const Type` (the payload views from `ty.as(.k)` are not types).
// Floating point: native f32/f64 arithmetic; the libm calls of the C++ map to Zig builtins and std.math (results can
// differ from glibc in the last ulp of an f64 for transcendental functions; f32 results go through f64 first, like the C++).

pub const UnaryScalarFoldingRule = *const fn (result_type: *const Type, a: *const Constant, cm: *ConstMgr) ?*const Constant;

// ---- scalar-to-component lifting (FoldUnaryOp / FoldBinaryOp / FoldTernaryOp and the FP variants) ------------------

fn cfrVectorOfResults(cm: *ConstMgr, vector_type: *const Type, results: []const *const Constant) ?*const Constant {
    var ids: List(u32) = .{};
    for (results) |member| {
        const def: *Inst = cfrDef(cm, member) orelse return null;
        ids.push(def.resultId());
    }
    return cm.getConstant(vector_type, ids.items);
}

fn cfrFoldUnaryOp(comptime scalar_rule: UnaryScalarFoldingRule) ConstFoldingRule {
    return struct {
        fn rule(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
            const cm: *ConstMgr = ctx.getConstantMgr();
            const tm: *TypeMgr = ctx.getTypeMgr();
            const result_type: *const Type = tm.getType(inst.typeId()).?;
            const vector_type: ?*const TyVector = result_type.as(.vector);
            const arg: *const Constant = (if (inst.op == .OpExtInst) constants[1] else constants[0]) orelse return null;
            if (vector_type) |vt| {
                const a_components: List(*const Constant) = arg.getVectorComponents(cm);
                var results: List(*const Constant) = .{};
                for (a_components.items) |ac| {
                    const r: *const Constant = scalar_rule(vt.element, ac, cm) orelse return null;
                    results.push(r);
                }
                return cfrVectorOfResults(cm, result_type, results.items);
            }
            return scalar_rule(result_type, arg, cm);
        }
    }.rule;
}

pub const BinaryScalarFoldingRule = *const fn (result_type: *const Type, a: *const Constant, b: *const Constant, cm: *ConstMgr) ?*const Constant;

fn cfrFoldBinaryOp(comptime scalar_rule: BinaryScalarFoldingRule) ConstFoldingRule {
    return struct {
        fn rule(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
            const cm: *ConstMgr = ctx.getConstantMgr();
            const tm: *TypeMgr = ctx.getTypeMgr();
            const result_type: *const Type = tm.getType(inst.typeId()).?;
            const vector_type: ?*const TyVector = result_type.as(.vector);
            const arg1: *const Constant = (if (inst.op == .OpExtInst) constants[1] else constants[0]) orelse return null;
            const arg2: *const Constant = (if (inst.op == .OpExtInst) constants[2] else constants[1]) orelse return null;
            if (vector_type == null) return scalar_rule(result_type, arg1, arg2, cm);
            const a_components: List(*const Constant) = arg1.getVectorComponents(cm);
            const b_components: List(*const Constant) = arg2.getVectorComponents(cm);
            var results: List(*const Constant) = .{};
            for (a_components.items, 0..) |ac, i| {
                const r: *const Constant = scalar_rule(vector_type.?.element, ac, b_components.items[i], cm) orelse return null;
                results.push(r);
            }
            return cfrVectorOfResults(cm, result_type, results.items);
        }
    }.rule;
}

/// The function overload of FoldFPBinaryOp: `scalar_rule` is applied to the two constants (component-wise for vectors).
fn cfrFoldFPBinaryOpImpl(scalar_rule: BinaryScalarFoldingRule, result_type_id: u32, constants: []const ?*const Constant, ctx: *Ctx) ?*const Constant {
    const cm: *ConstMgr = ctx.getConstantMgr();
    const tm: *TypeMgr = ctx.getTypeMgr();
    const result_type: *const Type = tm.getType(result_type_id).?;
    const vector_type: ?*const TyVector = result_type.as(.vector);
    if (constants[0] == null or constants[1] == null) return null;
    if (vector_type) |vt| {
        const a_components: List(*const Constant) = constants[0].?.getVectorComponents(cm);
        const b_components: List(*const Constant) = constants[1].?.getVectorComponents(cm);
        var results: List(*const Constant) = .{};
        for (a_components.items, 0..) |ac, i| {
            const r: *const Constant = scalar_rule(vt.element, ac, b_components.items[i], cm) orelse return null;
            results.push(r);
        }
        return cfrVectorOfResults(cm, result_type, results.items);
    }
    return scalar_rule(result_type, constants[0].?, constants[1].?, cm);
}

fn cfrFoldFPBinaryOp(comptime scalar_rule: BinaryScalarFoldingRule) ConstFoldingRule {
    return struct {
        fn rule(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
            if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return null;
            if (inst.op == .OpExtInst) {
                const two: [2]?*const Constant = [2]?*const Constant{ constants[1], constants[2] };
                return cfrFoldFPBinaryOpImpl(scalar_rule, inst.typeId(), &two, ctx);
            }
            return cfrFoldFPBinaryOpImpl(scalar_rule, inst.typeId(), constants, ctx);
        }
    }.rule;
}

fn cfrFoldFPUnaryOp(comptime scalar_rule: UnaryScalarFoldingRule) ConstFoldingRule {
    const folding_rule: *const fn (*Ctx, *Inst, []const ?*const Constant) ?*const Constant = comptime cfrFoldUnaryOp(scalar_rule);
    return struct {
        fn rule(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
            if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return null;
            return folding_rule(ctx, inst, constants);
        }
    }.rule;
}

// C++ float -> integer conversions are undefined behaviour out of range. spirv-opt built for x86-64 yields INT32_MIN for
// every out-of-range or NaN signed conversion (cvttss2si / cvttsd2si "integer indefinite"), and for unsigned
// conversions goes through a 64-bit signed conversion (cvttss2si rax) and truncates to 32 bits; this reproduces that.
fn cfrFloatToI32(f: anytype) i32 {
    if (std.math.isNan(f) or f >= 2147483648.0 or f < -2147483648.0) return std.math.minInt(i32);
    return @intFromFloat(f);
}

fn cfrFloatToU32(f: anytype) u32 {
    if (std.math.isNan(f) or f >= 9223372036854775808.0 or f < -9223372036854775808.0) {
        return 0; // low 32 bits of INT64_MIN
    }
    const v: i64 = @intFromFloat(f);
    return @truncate(@as(u64, @bitCast(v)));
}

// ---- conversions -------------------------------------------------------------------------------------------------

fn cfrFoldFToIOpScalar(result_type: *const Type, a: *const Constant, cm: *ConstMgr) ?*const Constant {
    const integer_type: *const TyInteger = result_type.as(.integer) orelse fatal("FoldFToIOp: result is not an integer", .{});
    const float_type: *const TyFloat = a.ty.as(.float) orelse fatal("FoldFToIOp: operand is not a float", .{});
    if (integer_type.width != 32) return null;
    if (float_type.width == 32) {
        const fa: f32 = a.getFloat();
        const result: u32 = if (integer_type.is_signed) @bitCast(cfrFloatToI32(fa)) else cfrFloatToU32(fa);
        const words = [1]u32{result};
        return cm.getConstant(result_type, &words);
    } else if (float_type.width == 64) {
        const fa: f64 = a.getDouble();
        const result: u32 = if (integer_type.is_signed) @bitCast(cfrFloatToI32(fa)) else cfrFloatToU32(fa);
        const words = [1]u32{result};
        return cm.getConstant(result_type, &words);
    }
    return null;
}

fn cfrFoldFToI() ConstFoldingRule {
    return cfrFoldFPUnaryOp(cfrFoldFToIOpScalar);
}

fn cfrFoldIToFOpScalar(result_type: *const Type, a: *const Constant, cm: *ConstMgr) ?*const Constant {
    const integer_type: *const TyInteger = a.ty.as(.integer) orelse fatal("FoldIToFOp: operand is not an integer", .{});
    const float_type: *const TyFloat = result_type.as(.float) orelse fatal("FoldIToFOp: result is not a float", .{});
    if (integer_type.width != 32) return null;
    const ua: u32 = a.getU32();
    if (float_type.width == 32) {
        const result_val: f32 = if (integer_type.is_signed) @floatFromInt(@as(i32, @bitCast(ua))) else @floatFromInt(ua);
        const words: [1]u32 = fpWordsF32(result_val);
        return cm.getConstant(result_type, &words);
    } else if (float_type.width == 64) {
        const result_val: f64 = if (integer_type.is_signed) @floatFromInt(@as(i32, @bitCast(ua))) else @floatFromInt(ua);
        const words: [2]u32 = fpWordsF64(result_val);
        return cm.getConstant(result_type, &words);
    }
    return null;
}

fn cfrFoldIToF() ConstFoldingRule {
    return cfrFoldFPUnaryOp(cfrFoldIToFOpScalar);
}

/// float -> half (round toward zero, like HexFloat::castTo with kToZero) -> float, on the bits of the float.
pub fn cfrQuantizeToF16Bits(b: u32) u32 {
    const sign: u32 = b & 0x80000000;
    const mag: u32 = b & 0x7FFFFFFF;
    if (mag == 0) return b; // +-0
    const exp_bits: u32 = mag >> 23;
    const sig: u32 = mag & 0x7FFFFF;
    if (exp_bits == 0xFF) {
        if (sig == 0) return sign | 0x7F800000; // infinity
        // NaN: float -> half keeps the top 10 significand bits (at least 1). half -> float then computes
        // `significand << 13` in the half's 16-bit uint_type (the high bits are lost, so only the low 3 half bits survive,
        // or the pattern falls back to 1) and ORs it with the float NaN_pattern, whose C++ constant 0x7f80000 has seven
        // digits (0x07F80000).
        const half_sig: u32 = if ((sig >> 13) == 0) 1 else (sig >> 13);
        const widened: u32 = (half_sig << 13) & 0xFFFF;
        return 0x07F80000 | sign | 0x7F800000 | (if (widened == 0) @as(u32, 1) else widened);
    }
    if (exp_bits == 0) return sign; // float denormal: underflows to zero
    const e: i32 = @as(i32, @intCast(exp_bits)) - 127;
    if (e > 15) return sign | 0x7F800000; // overflow saturates to infinity
    if (e >= -14) return sign | (mag & ~@as(u32, 0x1FFF)); // normal half: drop the low 13 significand bits
    // half denormal range: the value in units of 2^-24 is (2^23 | sig) >> (-e - 1), truncated
    const shift: u32 = @intCast(-e - 1);
    if (shift >= 32) return sign;
    const h: u32 = ((@as(u32, 1) << 23) | sig) >> @intCast(shift);
    if (h == 0) return sign;
    const p: u32 = 31 - @clz(h);
    const out_exp: u32 = @intCast(@as(i32, @intCast(p)) - 24 + 127);
    const frac: u32 = (h << @intCast(23 - p)) & 0x7FFFFF;
    return sign | (out_exp << 23) | frac;
}

fn cfrFoldQuantizeToF16Scalar(result_type: *const Type, a: *const Constant, cm: *ConstMgr) ?*const Constant {
    const float_type: *const TyFloat = a.ty.as(.float) orelse fatal("FoldQuantizeToF16Scalar: operand is not a float", .{});
    if (float_type.width != 32) return null;
    const fa: f32 = a.getFloat();
    const words = [1]u32{cfrQuantizeToF16Bits(@bitCast(fa))};
    return cm.getConstant(result_type, &words);
}

fn cfrFoldQuantizeToF16() ConstFoldingRule {
    return cfrFoldFPUnaryOp(cfrFoldQuantizeToF16Scalar);
}

const CfrArithOp = enum { add, sub, mul, div };

/// FOLD_FPARITH_OP(op)
fn cfrFpArith(comptime op: CfrArithOp) BinaryScalarFoldingRule {
    return struct {
        fn apply(fa: anytype, fb: anytype) @TypeOf(fa) {
            return switch (op) {
                .add => fa + fb,
                .sub => fa - fb,
                .mul => fa * fb,
                .div => fa / fb,
            };
        }

        fn rule(result_type: *const Type, a: *const Constant, b: *const Constant, cm: *ConstMgr) ?*const Constant {
            const float_type: *const TyFloat = result_type.as(.float) orelse fatal("FOLD_FPARITH_OP: not a float type", .{});
            if (float_type.width == 32) {
                const words: [1]u32 = fpWordsF32(apply(a.getFloat(), b.getFloat()));
                return cm.getConstant(result_type, &words);
            } else if (float_type.width == 64) {
                const words: [2]u32 = fpWordsF64(apply(a.getDouble(), b.getDouble()));
                return cm.getConstant(result_type, &words);
            }
            return null;
        }
    }.rule;
}

fn cfrFoldFSub() ConstFoldingRule {
    return cfrFoldFPBinaryOp(cfrFpArith(.sub));
}
fn cfrFoldFAdd() ConstFoldingRule {
    return cfrFoldFPBinaryOp(cfrFpArith(.add));
}
fn cfrFoldFMul() ConstFoldingRule {
    return cfrFoldFPBinaryOp(cfrFpArith(.mul));
}

fn cfrFoldRedundantSub(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    _ = constants;
    check(inst.op == .OpFSub or inst.op == .OpISub, "FoldRedundantSub: not a subtraction");
    if (inst.getSingleWordInOperand(0) == inst.getSingleWordInOperand(1)) {
        const use_float: bool = inst.op == .OpFSub;
        if (use_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return null;
        const tm: *TypeMgr = ctx.getTypeMgr();
        const ty: *const Type = tm.getType(inst.typeId()).?;
        if (ty.isCooperativeMatrix()) return null;
        const cm: *ConstMgr = ctx.getConstantMgr();
        const null_id: u32 = cm.getNullConstId(ty);
        return cm.findDeclaredConstant(null_id);
    }
    return null;
}

fn cfrNegateFPConst(result_type: *const Type, val: *const Constant, cm: *ConstMgr) ?*const Constant {
    const ft: *const TyFloat = result_type.as(.float) orelse fatal("NegateFPConst: not a float type", .{});
    if (ft.width == 32) return cm.getFloatConst(-val.getFloat());
    if (ft.width == 64) return cm.getDoubleConst(-val.getDouble());
    return null;
}

// ---- helpers --------------------------------------------------------------------------------------------------

fn cfrGetNan(ty: *const Type, cm: *ConstMgr) ?*const Constant {
    const ft: *const TyFloat = ty.as(.float) orelse return null;
    return switch (ft.width) {
        32 => cm.getFloatConst(std.math.nan(f32)),
        64 => cm.getDoubleConst(std.math.nan(f64)),
        else => null,
    };
}

fn cfrGetInf(ty: *const Type, cm: *ConstMgr) ?*const Constant {
    const ft: *const TyFloat = ty.as(.float) orelse return null;
    return switch (ft.width) {
        32 => cm.getFloatConst(std.math.inf(f32)),
        64 => cm.getDoubleConst(std.math.inf(f64)),
        else => null,
    };
}

fn cfrFoldFPScalarDivideByZero(result_type: *const Type, numerator_opt: ?*const Constant, cm: *ConstMgr) ?*const Constant {
    const numerator: *const Constant = numerator_opt orelse return null;
    if (numerator.isZero()) return cfrGetNan(result_type, cm);
    var result: *const Constant = cfrGetInf(result_type, cm) orelse return null;
    if (numerator.kind == .float and numerator.getValueAsDouble() < 0.0) {
        result = cfrNegateFPConst(result_type, result, cm) orelse return null;
    }
    return result;
}

fn cfrFoldScalarFPDivide(result_type: *const Type, numerator: *const Constant, denominator: *const Constant, cm: *ConstMgr) ?*const Constant {
    if (denominator.isZero()) return cfrFoldFPScalarDivideByZero(result_type, numerator, cm);
    const width: u32 = denominator.ty.as(.float).?.width;
    if (width != 32 and width != 64) return null;
    if (denominator.kind == .float and denominator.getValueAsDouble() == -0.0) {
        var result: ?*const Constant = cfrFoldFPScalarDivideByZero(result_type, numerator, cm);
        if (result != null) result = cfrNegateFPConst(result_type, result.?, cm);
        return result;
    }
    return cfrFpArith(.div)(result_type, numerator, denominator, cm);
}

fn cfrFoldFDiv() ConstFoldingRule {
    return cfrFoldFPBinaryOp(cfrFoldScalarFPDivide);
}

fn cfrGetConstantUniformValue(cm: *ConstMgr, ty: *const Type, f: ?f64, i: ?u64) ?*const Constant {
    var uniform: ?*const Constant = null;
    var is_vector: bool = false;
    var base_type: *const Type = ty;
    if (ty.as(.vector)) |vt| {
        is_vector = true;
        base_type = vt.element;
    }
    if (f != null and base_type.as(.float) != null) {
        const w: u32 = base_type.as(.float).?.width;
        if (w == 32) {
            const words: [1]u32 = fpWordsF32(@floatCast(f.?));
            uniform = cm.getConstant(base_type, &words);
        } else if (w == 64) {
            const words: [2]u32 = fpWordsF64(f.?);
            uniform = cm.getConstant(base_type, &words);
        }
    } else if (i != null and base_type.as(.integer) != null) {
        uniform = cm.generateIntegerConstant(base_type, i.?);
    }
    if (uniform == null) return null;
    if (is_vector) {
        const uniform_inst: *Inst = cfrDef(cm, uniform) orelse return null;
        const uniform_id: u32 = uniform_inst.resultId();
        const count: u32 = ty.as(.vector).?.count;
        var ids: List(u32) = .{};
        var k: u32 = 0;
        while (k < count) : (k += 1) ids.push(uniform_id);
        uniform = cm.getConstant(ty, ids.items);
    }
    return uniform;
}

fn cfrFoldRedundantDiv(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    check(inst.op == .OpFDiv or inst.op == .OpSDiv or inst.op == .OpUDiv, "FoldRedundantDiv: not a division");
    if (constants[0] != null or constants[1] != null) return null;
    const tm: *TypeMgr = ctx.getTypeMgr();
    const ty: *const Type = tm.getType(inst.typeId()).?;
    if (ty.isCooperativeMatrix()) return null;
    const use_float: bool = inst.op == .OpFDiv;
    if (use_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return null;
    const cm: *ConstMgr = ctx.getConstantMgr();
    if (inst.getSingleWordInOperand(0) == inst.getSingleWordInOperand(1)) {
        return cfrGetConstantUniformValue(cm, ty, 1.0, 1);
    }
    if (inst.op == .OpUDiv) return null;
    const du: *DefUseMgr = ctx.getDefUseMgr();
    const lhs: *Inst = du.getDef(inst.getSingleWordInOperand(0)).?;
    if ((lhs.op == .OpSNegate or lhs.op == .OpFNegate) and
        lhs.getSingleWordInOperand(0) == inst.getSingleWordInOperand(1) and
        (!use_float or instIsFloatingPointFoldingAllowed(ctx, lhs)))
    {
        return cfrGetConstantUniformValue(cm, ty, -1.0, std.math.maxInt(u64));
    }
    const rhs: *Inst = du.getDef(inst.getSingleWordInOperand(1)).?;
    if ((rhs.op == .OpSNegate or rhs.op == .OpFNegate) and
        rhs.getSingleWordInOperand(0) == inst.getSingleWordInOperand(0) and
        (!use_float or instIsFloatingPointFoldingAllowed(ctx, rhs)))
    {
        return cfrGetConstantUniformValue(cm, ty, -1.0, std.math.maxInt(u64));
    }
    return null;
}

// ---- floating point comparisons --------------------------------------------------------------------------------

fn cfrCompareFloatingPoint(op_result: bool, op_unordered: bool, need_ordered: bool) bool {
    if (need_ordered) return !op_unordered and op_result;
    return op_unordered or op_result;
}

const CfrCmpOp = enum { eq, ne, lt, gt, le, ge };

fn cfrCmp(comptime op: CfrCmpOp, a: anytype, b: anytype) bool {
    return switch (op) {
        .eq => a == b,
        .ne => a != b,
        .lt => a < b,
        .gt => a > b,
        .le => a <= b,
        .ge => a >= b,
    };
}

/// FOLD_FPCMP_OP(op, ord)
fn cfrFpCmp(comptime op: CfrCmpOp, comptime ordered: bool) BinaryScalarFoldingRule {
    return struct {
        fn rule(result_type: *const Type, a: *const Constant, b: *const Constant, cm: *ConstMgr) ?*const Constant {
            const float_type: *const TyFloat = a.ty.as(.float) orelse fatal("FOLD_FPCMP_OP: not a float constant", .{});
            if (float_type.width == 32) {
                const fa: f32 = a.getFloat();
                const fb: f32 = b.getFloat();
                const result: bool = cfrCompareFloatingPoint(cfrCmp(op, fa, fb), std.math.isNan(fa) or std.math.isNan(fb), ordered);
                const words = [1]u32{@intFromBool(result)};
                return cm.getConstant(result_type, &words);
            } else if (float_type.width == 64) {
                const fa: f64 = a.getDouble();
                const fb: f64 = b.getDouble();
                const result: bool = cfrCompareFloatingPoint(cfrCmp(op, fa, fb), std.math.isNan(fa) or std.math.isNan(fb), ordered);
                const words = [1]u32{@intFromBool(result)};
                return cm.getConstant(result_type, &words);
            }
            return null;
        }
    }.rule;
}

fn cfrFoldInvariantSelect(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    _ = ctx;
    check(inst.op == .OpSelect, "FoldInvariantSelect: not OpSelect");
    const c1: *const Constant = constants[1] orelse return null;
    const c2: *const Constant = constants[2] orelse return null;
    if (c1 == c2) return c1;
    if (c1.isZero() and c2.isZero()) return c1;
    return null;
}

fn cfrFoldSelect(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    check(inst.op == .OpSelect, "FoldSelect: not OpSelect");
    const condition: *const Constant = constants[0] orelse return null;
    const object_1: *const Constant = constants[1] orelse return null;
    const object_2: *const Constant = constants[2] orelse return null;
    if (condition.ty.as(.vector) == null) {
        var cond_is_true: bool = false;
        if (condition.kind == .bool_) {
            cond_is_true = condition.boolValue();
        } else if (!condition.isNull()) {
            return null;
        }
        return if (cond_is_true) object_1 else object_2;
    }
    const cm: *ConstMgr = ctx.getConstantMgr();
    const tm: *TypeMgr = ctx.getTypeMgr();
    const result_type: *const Type = tm.getType(inst.typeId()).?;
    check(result_type.as(.vector) != null, "The result type of an OpSelect with a vector condition must be a vector");
    const cond_components: List(*const Constant) = condition.getVectorComponents(cm);
    const object_1_components: List(*const Constant) = object_1.getVectorComponents(cm);
    const object_2_components: List(*const Constant) = object_2.getVectorComponents(cm);
    var ids: List(u32) = .{};
    for (cond_components.items, 0..) |cc, i| {
        const cond_is_true: bool = cc.kind == .bool_ and cc.boolValue();
        const component: *const Constant = if (cond_is_true) object_1_components.items[i] else object_2_components.items[i];
        const component_inst: *Inst = cfrDef(cm, component) orelse return null;
        ids.push(component_inst.resultId());
    }
    return cm.getConstant(result_type, ids.items);
}

fn cfrFoldOpDotWithConstants(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    const cm: *ConstMgr = ctx.getConstantMgr();
    const tm: *TypeMgr = ctx.getTypeMgr();
    const new_type: *const Type = tm.getType(inst.typeId()).?;
    const float_type: *const TyFloat = new_type.as(.float) orelse fatal("OpDot should have a float return type.", .{});
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return null;
    var has_zero_operand: bool = false;
    for (0..2) |i| {
        if (constants[i]) |c| {
            if (c.isNull() or c.isZero()) {
                has_zero_operand = true;
                break;
            }
        }
    }
    if (has_zero_operand) {
        if (float_type.width == 32) {
            const words: [1]u32 = fpWordsF32(0.0);
            return cm.getConstant(new_type, &words);
        }
        if (float_type.width == 64) {
            const words: [2]u32 = fpWordsF64(0.0);
            return cm.getConstant(new_type, &words);
        }
        return null;
    }
    if (constants[0] == null or constants[1] == null) return null;
    const a_components: List(*const Constant) = constants[0].?.getVectorComponents(cm);
    const b_components: List(*const Constant) = constants[1].?.getVectorComponents(cm);
    const zero_words: [2]u32 = fpWordsF64(0.0);
    var result_const: ?*const Constant = cm.getConstant(new_type, &zero_words);
    var i: usize = 0;
    while (i < a_components.len() and result_const != null) : (i += 1) {
        const component: *const Constant = cfrFpArith(.mul)(new_type, a_components.items[i], b_components.items[i], cm) orelse return null;
        result_const = cfrFpArith(.add)(new_type, result_const.?, component, cm);
    }
    return result_const;
}

fn cfrFoldFNegate() ConstFoldingRule {
    return cfrFoldFPUnaryOp(cfrNegateFPConst);
}

fn cfrNegateIntConst(result_type: *const Type, val: *const Constant, cm: *ConstMgr) ?*const Constant {
    const it: *const TyInteger = result_type.as(.integer) orelse fatal("NegateIntConst: not an integer type", .{});
    if (val.isNull()) return val;
    const new_value: u64 = @bitCast(0 -% val.getSignExtendedValue());
    return cm.getIntConst(new_value, it.width, it.is_signed);
}

fn cfrFoldSNegate() ConstFoldingRule {
    return cfrFoldUnaryOp(cfrNegateIntConst);
}

fn glslNumLookup(comptime name: []const u8) u32 {
    @setEvalBranchQuota(1000000);
    for (ext_insts_glsl_std_450) |e| {
        if (std.mem.eql(u8, e.name, name)) return e.value;
    }
    @compileError("unknown GLSL.std.450 instruction " ++ name);
}

/// The value of GLSL.std.450 instruction `name`, from the generated grammar table.
pub fn glslNum(comptime name: []const u8) u32 {
    return comptime glslNumLookup(name);
}

// ---- FClamp feeding a comparison ------------------------------------------------------------------------------

fn cfrFoldFClampFeedingCompare(comptime cmp_opcode: Op) ConstFoldingRule {
    return struct {
        fn rule(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
            const cm: *ConstMgr = ctx.getConstantMgr();
            const du: *DefUseMgr = ctx.getDefUseMgr();
            if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return null;
            const non_const_idx: usize = if (constants[0] != null) 1 else 0;
            const operand_id: u32 = inst.getSingleWordInOperand(non_const_idx);
            const operand_inst: *Inst = du.getDef(operand_id).?;
            const tm: *TypeMgr = ctx.getTypeMgr();
            const operand_type: *const Type = tm.getType(operand_inst.typeId()).?;
            const operand_float: *const TyFloat = operand_type.as(.float) orelse return null;
            if (operand_float.width != 32 and operand_float.width != 64) return null;
            if (operand_inst.op != .OpExtInst) return null;
            if (operand_inst.getSingleWordInOperand(1) != glslNum("FClamp")) return null;
            if (constants[1] == null and constants[0] == null) return null;

            const max_id: u32 = operand_inst.getSingleWordInOperand(4);
            const max_const: ?*const Constant = cm.findDeclaredConstant(max_id);
            const min_id: u32 = operand_inst.getSingleWordInOperand(3);
            const min_const: ?*const Constant = cm.findDeclaredConstant(min_id);

            var found_result: bool = false;
            var result: bool = false;
            switch (cmp_opcode) {
                .OpFOrdLessThan, .OpFUnordLessThan, .OpFOrdGreaterThanEqual, .OpFUnordGreaterThanEqual => {
                    const is_less: bool = (cmp_opcode == .OpFOrdLessThan or cmp_opcode == .OpFUnordLessThan);
                    if (constants[0]) |c0| {
                        if (min_const) |mn| {
                            if (c0.getValueAsDouble() < mn.getValueAsDouble()) {
                                found_result = true;
                                result = is_less;
                            }
                        }
                        if (max_const) |mx| {
                            if (c0.getValueAsDouble() >= mx.getValueAsDouble()) {
                                found_result = true;
                                result = !is_less;
                            }
                        }
                    }
                    if (constants[1]) |c1| {
                        if (max_const) |mx| {
                            if (mx.getValueAsDouble() < c1.getValueAsDouble()) {
                                found_result = true;
                                result = is_less;
                            }
                        }
                        if (min_const) |mn| {
                            if (mn.getValueAsDouble() >= c1.getValueAsDouble()) {
                                found_result = true;
                                result = !is_less;
                            }
                        }
                    }
                },
                .OpFOrdGreaterThan, .OpFUnordGreaterThan, .OpFOrdLessThanEqual, .OpFUnordLessThanEqual => {
                    const is_le: bool = (cmp_opcode == .OpFOrdLessThanEqual or cmp_opcode == .OpFUnordLessThanEqual);
                    if (constants[0]) |c0| {
                        if (min_const) |mn| {
                            if (c0.getValueAsDouble() <= mn.getValueAsDouble()) {
                                found_result = true;
                                result = is_le;
                            }
                        }
                        if (max_const) |mx| {
                            if (c0.getValueAsDouble() > mx.getValueAsDouble()) {
                                found_result = true;
                                result = !is_le;
                            }
                        }
                    }
                    if (constants[1]) |c1| {
                        if (max_const) |mx| {
                            if (mx.getValueAsDouble() <= c1.getValueAsDouble()) {
                                found_result = true;
                                result = is_le;
                            }
                        }
                        if (min_const) |mn| {
                            if (mn.getValueAsDouble() > c1.getValueAsDouble()) {
                                found_result = true;
                                result = !is_le;
                            }
                        }
                    }
                },
                else => return null,
            }
            if (!found_result) return null;
            const bool_type: ?*Type = tm.getType(inst.typeId());
            const words = [1]u32{@intFromBool(result)};
            return cm.getConstant(bool_type, &words);
        }
    }.rule;
}

const CfrSign = enum { signed, unsigned };

fn cfrFoldBinaryIntegerOperation(comptime signedness: CfrSign, comptime op: *const fn (u64, u64) u64) BinaryScalarFoldingRule {
    return struct {
        fn rule(result_type: *const Type, a: *const Constant, b: *const Constant, cm: *ConstMgr) ?*const Constant {
            check(result_type.as(.integer) != null, "FoldBinaryIntegerOperation: result is not an integer");
            const ia: u64 = if (signedness == .signed) @bitCast(a.getSignExtendedValue()) else a.getZeroExtendedValue();
            const ib: u64 = if (signedness == .signed) @bitCast(b.getSignExtendedValue()) else b.getZeroExtendedValue();
            const result: u64 = op(ia, ib);
            return cm.generateIntegerConstant(result_type, result);
        }
    }.rule;
}

fn cfrFoldScalarSConvert(result_type: *const Type, a: *const Constant, cm: *ConstMgr) ?*const Constant {
    check(result_type.as(.integer) != null, "The result type of an SConvert");
    const value: i64 = a.getSignExtendedValue();
    return cm.generateIntegerConstant(result_type, @bitCast(value));
}

fn cfrFoldScalarUConvert(result_type: *const Type, a: *const Constant, cm: *ConstMgr) ?*const Constant {
    check(result_type.as(.integer) != null, "The result type of an UConvert");
    var value: u64 = a.getZeroExtendedValue();
    const operand_type: *const TyInteger = a.ty.as(.integer).?;
    const num_clear: u64 = 64 - operand_type.width; // utils::ClearHighBits(value, 64 - width)
    if (num_clear != 0) {
        value &= ~@as(u64, 0) >> @intCast(num_clear);
    }
    return cm.generateIntegerConstant(result_type, value);
}

fn cfrOpAdd(a: u64, b: u64) u64 {
    return a +% b;
}
fn cfrOpSub(a: u64, b: u64) u64 {
    return a -% b;
}
fn cfrOpMul(a: u64, b: u64) u64 {
    return a *% b;
}
fn cfrOpUDiv(a: u64, b: u64) u64 {
    return if (b != 0) a / b else 0;
}
fn cfrOpSDiv(a: u64, b: u64) u64 {
    if (b == 0) return 0;
    return @bitCast(@divTrunc(@as(i64, @bitCast(a)), @as(i64, @bitCast(b))));
}
fn cfrOpUMod(a: u64, b: u64) u64 {
    return if (b != 0) a % b else 0;
}
fn cfrOpSRem(a: u64, b: u64) u64 {
    if (b == 0) return 0;
    return @bitCast(@rem(@as(i64, @bitCast(a)), @as(i64, @bitCast(b))));
}
fn cfrOpSMod(a: u64, b: u64) u64 {
    if (b == 0) return 0;
    const signed_a: i64 = @bitCast(a);
    const signed_b: i64 = @bitCast(b);
    var result: i64 = @rem(signed_a, signed_b);
    if ((signed_b < 0) != (result < 0)) result +%= signed_b;
    return @bitCast(result);
}

pub const TernaryScalarFoldingRule = *const fn (result_type: *const Type, a: *const Constant, b: *const Constant, c: *const Constant, cm: *ConstMgr) ?*const Constant;

fn cfrFoldTernaryOp(comptime scalar_rule: TernaryScalarFoldingRule) ConstFoldingRule {
    return struct {
        fn rule(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
            const cm: *ConstMgr = ctx.getConstantMgr();
            const tm: *TypeMgr = ctx.getTypeMgr();
            const result_type: *const Type = tm.getType(inst.typeId()).?;
            const vector_type: ?*const TyVector = result_type.as(.vector);
            const arg1: *const Constant = (if (inst.op == .OpExtInst) constants[1] else constants[0]) orelse return null;
            const arg2: *const Constant = (if (inst.op == .OpExtInst) constants[2] else constants[1]) orelse return null;
            const arg3: *const Constant = (if (inst.op == .OpExtInst) constants[3] else constants[2]) orelse return null;
            if (vector_type == null) return scalar_rule(result_type, arg1, arg2, arg3, cm);
            const a_components: List(*const Constant) = arg1.getVectorComponents(cm);
            const b_components: List(*const Constant) = arg2.getVectorComponents(cm);
            const c_components: List(*const Constant) = arg3.getVectorComponents(cm);
            var results: List(*const Constant) = .{};
            for (a_components.items, 0..) |ac, i| {
                const r: *const Constant = scalar_rule(vector_type.?.element, ac, b_components.items[i], c_components.items[i], cm) orelse return null;
                results.push(r);
            }
            return cfrVectorOfResults(cm, result_type, results.items);
        }
    }.rule;
}

fn cfrFoldFPTernaryOp(comptime scalar_rule: TernaryScalarFoldingRule) ConstFoldingRule {
    const folding_rule: *const fn (*Ctx, *Inst, []const ?*const Constant) ?*const Constant = comptime cfrFoldTernaryOp(scalar_rule);
    return struct {
        fn rule(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
            if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return null;
            return folding_rule(ctx, inst, constants);
        }
    }.rule;
}

fn cfrFoldFMix(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    const cm: *ConstMgr = ctx.getConstantMgr();
    check(inst.op == .OpExtInst, "Expecting an extended instruction.");
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return null;
    var i: usize = 1;
    while (i < 4) : (i += 1) {
        if (constants[i] == null) return null;
    }
    var one: ?*const Constant = null;
    var is_vector: bool = false;
    const result_type: *const Type = constants[1].?.ty;
    var base_type: *const Type = result_type;
    if (base_type.as(.vector)) |vt| {
        is_vector = true;
        base_type = vt.element;
    }
    const base_float: *const TyFloat = base_type.as(.float) orelse fatal("FMix is suppose to act on floats or vectors of floats.", .{});
    if (base_float.width == 32) {
        const w: [1]u32 = fpWordsF32(1.0);
        one = cm.getConstant(base_type, &w);
    } else if (base_float.width == 64) {
        const w: [2]u32 = fpWordsF64(1.0);
        one = cm.getConstant(base_type, &w);
    } else {
        return null;
    }
    if (is_vector) {
        const one_inst: *Inst = cfrDef(cm, one) orelse return null;
        const one_id: u32 = one_inst.resultId();
        const count: u32 = result_type.as(.vector).?.count;
        var ids: List(u32) = .{};
        var k: u32 = 0;
        while (k < count) : (k += 1) ids.push(one_id);
        one = cm.getConstant(result_type, ids.items);
    }
    const sub_args: [2]?*const Constant = [2]?*const Constant{ one, constants[3] };
    const temp1: *const Constant = cfrFoldFPBinaryOpImpl(cfrFpArith(.sub), inst.typeId(), &sub_args, ctx) orelse return null;
    const mul1_args: [2]?*const Constant = [2]?*const Constant{ constants[1], temp1 };
    const temp2: *const Constant = cfrFoldFPBinaryOpImpl(cfrFpArith(.mul), inst.typeId(), &mul1_args, ctx) orelse return null;
    const mul2_args: [2]?*const Constant = [2]?*const Constant{ constants[2], constants[3] };
    const temp3: *const Constant = cfrFoldFPBinaryOpImpl(cfrFpArith(.mul), inst.typeId(), &mul2_args, ctx) orelse return null;
    const add_args: [2]?*const Constant = [2]?*const Constant{ temp2, temp3 };
    return cfrFoldFPBinaryOpImpl(cfrFpArith(.add), inst.typeId(), &add_args, ctx);
}

// ---- min / max / clamp -------------------------------------------------------------------------------------------

fn cfrNegZeroAwareLessThan(a: anytype, b: anytype) bool {
    if (a == 0.0 and b == 0.0) {
        const sba: bool = std.math.signbit(a);
        const sbb: bool = std.math.signbit(b);
        if (sba and !sbb) return true;
    }
    return a < b;
}

fn cfrFoldMin(result_type: *const Type, a: *const Constant, b: *const Constant, cm: *ConstMgr) ?*const Constant {
    _ = cm;
    if (result_type.as(.integer)) |int_type| {
        if (int_type.width <= 32) {
            if (int_type.is_signed) {
                const va: i32 = if (a.kind == .int) a.getS32BitValue() else 0;
                const vb: i32 = if (b.kind == .int) b.getS32BitValue() else 0;
                return if (va < vb) a else b;
            } else {
                const va: u32 = if (a.kind == .int) a.getU32BitValue() else 0;
                const vb: u32 = if (b.kind == .int) b.getU32BitValue() else 0;
                return if (va < vb) a else b;
            }
        } else if (int_type.width == 64) {
            if (int_type.is_signed) {
                return if (a.getS64() < b.getS64()) a else b;
            } else {
                return if (a.getU64() < b.getU64()) a else b;
            }
        }
    } else if (result_type.as(.float)) |float_type| {
        if (float_type.width == 32) {
            return if (cfrNegZeroAwareLessThan(a.getFloat(), b.getFloat())) a else b;
        } else if (float_type.width == 64) {
            return if (cfrNegZeroAwareLessThan(a.getDouble(), b.getDouble())) a else b;
        }
    }
    return null;
}

fn cfrFoldMax(result_type: *const Type, a: *const Constant, b: *const Constant, cm: *ConstMgr) ?*const Constant {
    _ = cm;
    if (result_type.as(.integer)) |int_type| {
        if (int_type.width <= 32) {
            if (int_type.is_signed) {
                const va: i32 = if (a.kind == .int) a.getS32BitValue() else 0;
                const vb: i32 = if (b.kind == .int) b.getS32BitValue() else 0;
                return if (va > vb) a else b;
            } else {
                const va: u32 = if (a.kind == .int) a.getU32BitValue() else 0;
                const vb: u32 = if (b.kind == .int) b.getU32BitValue() else 0;
                return if (va > vb) a else b;
            }
        } else if (int_type.width == 64) {
            if (int_type.is_signed) {
                return if (a.getS64() > b.getS64()) a else b;
            } else {
                return if (a.getU64() > b.getU64()) a else b;
            }
        }
    } else if (result_type.as(.float)) |float_type| {
        if (float_type.width == 32) {
            return if (cfrNegZeroAwareLessThan(b.getFloat(), a.getFloat())) a else b;
        } else if (float_type.width == 64) {
            return if (cfrNegZeroAwareLessThan(b.getDouble(), a.getDouble())) a else b;
        }
    }
    return null;
}

fn cfrFoldNMin(result_type: *const Type, a: *const Constant, b: *const Constant, cm: *ConstMgr) ?*const Constant {
    _ = cm;
    if (result_type.as(.float)) |float_type| {
        if (float_type.width == 32) {
            const va: f32 = a.getFloat();
            const vb: f32 = b.getFloat();
            if (std.math.isNan(va)) return b;
            if (std.math.isNan(vb)) return a;
            return if (cfrNegZeroAwareLessThan(va, vb)) a else b;
        } else if (float_type.width == 64) {
            const va: f64 = a.getDouble();
            const vb: f64 = b.getDouble();
            if (std.math.isNan(va)) return b;
            if (std.math.isNan(vb)) return a;
            return if (cfrNegZeroAwareLessThan(va, vb)) a else b;
        }
    }
    return null;
}

fn cfrFoldNMax(result_type: *const Type, a: *const Constant, b: *const Constant, cm: *ConstMgr) ?*const Constant {
    _ = cm;
    if (result_type.as(.float)) |float_type| {
        if (float_type.width == 32) {
            const va: f32 = a.getFloat();
            const vb: f32 = b.getFloat();
            if (std.math.isNan(va)) return b;
            if (std.math.isNan(vb)) return a;
            return if (cfrNegZeroAwareLessThan(vb, va)) a else b;
        } else if (float_type.width == 64) {
            const va: f64 = a.getDouble();
            const vb: f64 = b.getDouble();
            if (std.math.isNan(va)) return b;
            if (std.math.isNan(vb)) return a;
            return if (cfrNegZeroAwareLessThan(vb, va)) a else b;
        }
    }
    return null;
}

fn cfrFoldClamp1(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    check(inst.op == .OpExtInst, "Expecting an extended instruction.");
    var i: usize = 1;
    while (i < 4) : (i += 1) {
        if (constants[i] == null) return null;
    }
    const max_args: [2]?*const Constant = [2]?*const Constant{ constants[1], constants[2] };
    const temp: *const Constant = cfrFoldFPBinaryOpImpl(cfrFoldMax, inst.typeId(), &max_args, ctx) orelse return null;
    const min_args: [2]?*const Constant = [2]?*const Constant{ temp, constants[3] };
    return cfrFoldFPBinaryOpImpl(cfrFoldMin, inst.typeId(), &min_args, ctx);
}

fn cfrFoldClamp2(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    check(inst.op == .OpExtInst, "Expecting an extended instruction.");
    const x: ?*const Constant = constants[1];
    const min_val: ?*const Constant = constants[2];
    if (x == null or min_val == null) return null;
    const args: [2]?*const Constant = [2]?*const Constant{ x, min_val };
    const temp: ?*const Constant = cfrFoldFPBinaryOpImpl(cfrFoldMax, inst.typeId(), &args, ctx);
    if (temp == min_val) return min_val;
    return null;
}

fn cfrFoldClamp3(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) ?*const Constant {
    check(inst.op == .OpExtInst, "Expecting an extended instruction.");
    const x: ?*const Constant = constants[1];
    const max_val: ?*const Constant = constants[3];
    if (x == null or max_val == null) return null;
    const args: [2]?*const Constant = [2]?*const Constant{ x, max_val };
    const temp: ?*const Constant = cfrFoldFPBinaryOpImpl(cfrFoldMin, inst.typeId(), &args, ctx);
    if (temp == max_val) return max_val;
    return null;
}

