// ---- floating point / integer operations from function pointers ----------------------------------------------------

fn cfrFoldUnaryFloatingPointOperation(comptime fp: *const fn (f64) f64) UnaryScalarFoldingRule {
    return struct {
        fn rule(result_type: *const Type, a: *const Constant, cm: *ConstMgr) ?*const Constant {
            const float_type: *const TyFloat = a.ty.as(.float) orelse fatal("FoldUnaryFloatingPointOperation: not a float", .{});
            if (float_type.width == 32) {
                const fa: f32 = a.getFloat();
                const res: f32 = @floatCast(fp(fa));
                const words: [1]u32 = fpWordsF32(res);
                return cm.getConstant(result_type, &words);
            } else if (float_type.width == 64) {
                const fa: f64 = a.getDouble();
                const words: [2]u32 = fpWordsF64(fp(fa));
                return cm.getConstant(result_type, &words);
            }
            return null;
        }
    }.rule;
}

fn cfrFoldBinaryFloatingPointOperation(comptime fp: *const fn (f64, f64) f64) BinaryScalarFoldingRule {
    return struct {
        fn rule(result_type: *const Type, a: *const Constant, b: *const Constant, cm: *ConstMgr) ?*const Constant {
            const float_type: *const TyFloat = a.ty.as(.float) orelse fatal("FoldBinaryFloatingPointOperation: not a float", .{});
            if (float_type.width == 32) {
                const fa: f32 = a.getFloat();
                const fb: f32 = b.getFloat();
                const res: f32 = @floatCast(fp(fa, fb));
                const words: [1]u32 = fpWordsF32(res);
                return cm.getConstant(result_type, &words);
            } else if (float_type.width == 64) {
                const fa: f64 = a.getDouble();
                const fb: f64 = b.getDouble();
                const words: [2]u32 = fpWordsF64(fp(fa, fb));
                return cm.getConstant(result_type, &words);
            }
            return null;
        }
    }.rule;
}

fn cfrFoldTernaryFloatingPointOperation(comptime fp: *const fn (f64, f64, f64) f64) TernaryScalarFoldingRule {
    return struct {
        fn rule(result_type: *const Type, a: *const Constant, b: *const Constant, c: *const Constant, cm: *ConstMgr) ?*const Constant {
            const float_type: *const TyFloat = a.ty.as(.float) orelse fatal("FoldTernaryFloatingPointOperation: not a float", .{});
            if (float_type.width == 32) {
                const fa: f32 = a.getFloat();
                const fb: f32 = b.getFloat();
                const fc: f32 = c.getFloat();
                const res: f32 = @floatCast(fp(fa, fb, fc));
                const words: [1]u32 = fpWordsF32(res);
                return cm.getConstant(result_type, &words);
            } else if (float_type.width == 64) {
                const fa: f64 = a.getDouble();
                const fb: f64 = b.getDouble();
                const fc: f64 = c.getDouble();
                const words: [2]u32 = fpWordsF64(fp(fa, fb, fc));
                return cm.getConstant(result_type, &words);
            }
            return null;
        }
    }.rule;
}

fn cfrFoldUnaryIntegerOperation(comptime signedness: CfrSign, comptime op: *const fn (u64) u64) UnaryScalarFoldingRule {
    return struct {
        fn rule(result_type: *const Type, a: *const Constant, cm: *ConstMgr) ?*const Constant {
            check(result_type.as(.integer) != null, "FoldUnaryIntegerOperation: result is not an integer");
            const ia: u64 = if (signedness == .signed) @bitCast(a.getSignExtendedValue()) else a.getZeroExtendedValue();
            const result: u64 = op(ia);
            return cm.generateIntegerConstant(result_type, result);
        }
    }.rule;
}

// the std:: / libm functions of the C++ (see the file header about their accuracy)
fn cfrSin(v: f64) f64 {
    return @sin(v);
}
fn cfrCos(v: f64) f64 {
    return @cos(v);
}
fn cfrTan(v: f64) f64 {
    return @tan(v);
}
fn cfrAsin(v: f64) f64 {
    return std.math.asin(v);
}
fn cfrAcos(v: f64) f64 {
    return std.math.acos(v);
}
fn cfrAtan(v: f64) f64 {
    return std.math.atan(v);
}
fn cfrSinh(v: f64) f64 {
    return std.math.sinh(v);
}
fn cfrCosh(v: f64) f64 {
    return std.math.cosh(v);
}
fn cfrTanh(v: f64) f64 {
    return std.math.tanh(v);
}
fn cfrAsinh(v: f64) f64 {
    return std.math.asinh(v);
}
fn cfrAcosh(v: f64) f64 {
    return std.math.acosh(v);
}
fn cfrAtanh(v: f64) f64 {
    return if (v == 1.0 or v == -1.0) std.math.nan(f64) else std.math.atanh(v);
}
fn cfrInverseSqrt(v: f64) f64 {
    return 1.0 / @sqrt(v);
}
fn cfrExp(v: f64) f64 {
    return @exp(v);
}
fn cfrLog(v: f64) f64 {
    return @log(v);
}
fn cfrExp2(v: f64) f64 {
    return @exp2(v);
}
fn cfrLog2(v: f64) f64 {
    return @log2(v);
}
fn cfrSqrt(v: f64) f64 {
    return @sqrt(v);
}
fn cfrAtan2(y: f64, x: f64) f64 {
    return std.math.atan2(y, x);
}
fn cfrPow(x: f64, y: f64) f64 {
    return std.math.pow(f64, x, y);
}
fn cfrFabs(v: f64) f64 {
    return @abs(v);
}
fn cfrRound(v: f64) f64 {
    return @round(v);
}
fn cfrTrunc(v: f64) f64 {
    return @trunc(v);
}
fn cfrFloor(v: f64) f64 {
    return @floor(v);
}
fn cfrCeil(v: f64) f64 {
    return @ceil(v);
}
fn cfrFract(v: f64) f64 {
    return v - @floor(v);
}
fn cfrFSign(v: f64) f64 {
    if (v == 0.0) return v;
    return if (v < 0) -1.0 else 1.0;
}
fn cfrRadians(v: f64) f64 {
    const pi: f64 = 3.141592653589793;
    return v * pi / 180.0;
}
fn cfrDegrees(v: f64) f64 {
    const pi: f64 = 3.141592653589793;
    return v * 180.0 / pi;
}
fn cfrStep(edge: f64, x: f64) f64 {
    return if (x < edge) 0.0 else 1.0;
}
fn cfrSmoothStep(edge0: f64, edge1: f64, x: f64) f64 {
    const q: f64 = (x - edge0) / (edge1 - edge0);
    const t = if (q < 0.0) @as(f64, 0.0) else if (1.0 < q) @as(f64, 1.0) else q; // std::clamp(q, 0.0, 1.0)
    return t * t * (3.0 - 2.0 * t);
}
fn cfrFma(a: f64, b: f64, c: f64) f64 {
    return @mulAdd(f64, a, b, c);
}

fn cfrOpSAbs(a: u64) u64 {
    const value: i64 = @bitCast(a);
    return @bitCast(if (value >= 0) value else 0 -% value);
}
fn cfrOpSSign(a: u64) u64 {
    const value: i64 = @bitCast(a);
    if (value == 0) return 0;
    return @bitCast(@as(i64, if (value < 0) -1 else 1));
}

// ---- the rule tables (ConstantFoldingRules::AddFoldingRules, registration order kept) --------------------------

fn cfrExtRulesGlsl(num: u32) []const ConstFoldingRule {
    return switch (num) {
        glslNum("FMix") => comptime &[_]ConstFoldingRule{cfrFoldFMix},
        glslNum("SMin"), glslNum("UMin"), glslNum("FMin") => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFoldMin)},
        glslNum("NMin") => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFoldNMin)},
        glslNum("SMax"), glslNum("UMax"), glslNum("FMax") => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFoldMax)},
        glslNum("NMax") => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFoldNMax)},
        glslNum("UClamp"), glslNum("SClamp"), glslNum("FClamp") => comptime &[_]ConstFoldingRule{ cfrFoldClamp1, cfrFoldClamp2, cfrFoldClamp3 },
        glslNum("NClamp") => comptime &[_]ConstFoldingRule{ cfrFoldNClamp1, cfrFoldNClamp2, cfrFoldNClamp3 },
        glslNum("Sin") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrSin))},
        glslNum("Cos") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrCos))},
        glslNum("Tan") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrTan))},
        glslNum("Asin") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrAsin))},
        glslNum("Acos") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrAcos))},
        glslNum("Atan") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrAtan))},
        glslNum("Sinh") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrSinh))},
        glslNum("Cosh") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrCosh))},
        glslNum("Tanh") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrTanh))},
        glslNum("Asinh") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrAsinh))},
        glslNum("Acosh") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrAcosh))},
        glslNum("Atanh") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrAtanh))},
        glslNum("InverseSqrt") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrInverseSqrt))},
        glslNum("Exp") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrExp))},
        glslNum("Log") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrLog))},
        glslNum("Exp2") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrExp2))},
        glslNum("Log2") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrLog2))},
        glslNum("Sqrt") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrSqrt))},
        glslNum("Atan2") => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFoldBinaryFloatingPointOperation(cfrAtan2))},
        glslNum("Pow") => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFoldBinaryFloatingPointOperation(cfrPow))},
        glslNum("FAbs") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrFabs))},
        glslNum("SAbs") => comptime &[_]ConstFoldingRule{cfrFoldUnaryOp(cfrFoldUnaryIntegerOperation(.signed, cfrOpSAbs))},
        glslNum("Round") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrRound))},
        glslNum("Trunc") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrTrunc))},
        glslNum("Floor") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrFloor))},
        glslNum("Ceil") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrCeil))},
        glslNum("Fract") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrFract))},
        glslNum("FSign") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrFSign))},
        glslNum("SSign") => comptime &[_]ConstFoldingRule{cfrFoldUnaryOp(cfrFoldUnaryIntegerOperation(.signed, cfrOpSSign))},
        glslNum("Radians") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrRadians))},
        glslNum("Degrees") => comptime &[_]ConstFoldingRule{cfrFoldFPUnaryOp(cfrFoldUnaryFloatingPointOperation(cfrDegrees))},
        glslNum("Step") => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFoldBinaryFloatingPointOperation(cfrStep))},
        glslNum("SmoothStep") => comptime &[_]ConstFoldingRule{cfrFoldFPTernaryOp(cfrFoldTernaryFloatingPointOperation(cfrSmoothStep))},
        glslNum("Fma") => comptime &[_]ConstFoldingRule{cfrFoldFPTernaryOp(cfrFoldTernaryFloatingPointOperation(cfrFma))},
        else => &.{},
    };
}

/// ConstantFoldingRules::GetRulesForInstruction (the order of every list is the C++ registration order).
pub fn constFoldingRulesFor(ctx: *Ctx, inst: *const Inst) []const ConstFoldingRule {
    if (ctx.fold_interp or ctx.fold_amd) return &.{}; // InterpConstFoldingRules / AmdExtConstFoldingRules register nothing
    if (inst.op == .OpExtInst) {
        // the C++ registers the GLSL.std.450 rules under the import id seen when the folder was built (0: none)
        const glsl_id: u32 = foldGlslId(ctx);
        if (glsl_id == 0 or inst.getSingleWordInOperand(0) != glsl_id) return &.{};
        return cfrExtRulesGlsl(inst.getSingleWordInOperand(1));
    }
    return switch (inst.op) {
        .OpCompositeConstruct => comptime &[_]ConstFoldingRule{cfrFoldCompositeWithConstants},
        .OpCompositeExtract => comptime &[_]ConstFoldingRule{cfrFoldExtractWithConstants},
        .OpCompositeInsert => comptime &[_]ConstFoldingRule{cfrFoldInsertWithConstants},
        .OpConvertFToS, .OpConvertFToU => comptime &[_]ConstFoldingRule{cfrFoldFToI()},
        .OpConvertSToF, .OpConvertUToF => comptime &[_]ConstFoldingRule{cfrFoldIToF()},
        .OpSConvert => comptime &[_]ConstFoldingRule{cfrFoldUnaryOp(cfrFoldScalarSConvert)},
        .OpUConvert => comptime &[_]ConstFoldingRule{cfrFoldUnaryOp(cfrFoldScalarUConvert)},
        .OpDot => comptime &[_]ConstFoldingRule{cfrFoldOpDotWithConstants},
        .OpFAdd => comptime &[_]ConstFoldingRule{cfrFoldFAdd()},
        .OpFDiv => comptime &[_]ConstFoldingRule{ cfrFoldFDiv(), cfrFoldRedundantDiv },
        .OpFMul => comptime &[_]ConstFoldingRule{cfrFoldFMul()},
        .OpFSub => comptime &[_]ConstFoldingRule{ cfrFoldFSub(), cfrFoldRedundantSub },
        .OpSelect => comptime &[_]ConstFoldingRule{ cfrFoldInvariantSelect, cfrFoldSelect },
        .OpFOrdEqual => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFpCmp(.eq, true))},
        .OpFUnordEqual => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFpCmp(.eq, false))},
        .OpFOrdNotEqual => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFpCmp(.ne, true))},
        .OpFUnordNotEqual => comptime &[_]ConstFoldingRule{cfrFoldFPBinaryOp(cfrFpCmp(.ne, false))},
        .OpFOrdLessThan => comptime &[_]ConstFoldingRule{ cfrFoldFPBinaryOp(cfrFpCmp(.lt, true)), cfrFoldFClampFeedingCompare(.OpFOrdLessThan) },
        .OpFUnordLessThan => comptime &[_]ConstFoldingRule{ cfrFoldFPBinaryOp(cfrFpCmp(.lt, false)), cfrFoldFClampFeedingCompare(.OpFUnordLessThan) },
        .OpFOrdGreaterThan => comptime &[_]ConstFoldingRule{ cfrFoldFPBinaryOp(cfrFpCmp(.gt, true)), cfrFoldFClampFeedingCompare(.OpFOrdGreaterThan) },
        .OpFUnordGreaterThan => comptime &[_]ConstFoldingRule{ cfrFoldFPBinaryOp(cfrFpCmp(.gt, false)), cfrFoldFClampFeedingCompare(.OpFUnordGreaterThan) },
        .OpFOrdLessThanEqual => comptime &[_]ConstFoldingRule{ cfrFoldFPBinaryOp(cfrFpCmp(.le, true)), cfrFoldFClampFeedingCompare(.OpFOrdLessThanEqual) },
        .OpFUnordLessThanEqual => comptime &[_]ConstFoldingRule{ cfrFoldFPBinaryOp(cfrFpCmp(.le, false)), cfrFoldFClampFeedingCompare(.OpFUnordLessThanEqual) },
        .OpFOrdGreaterThanEqual => comptime &[_]ConstFoldingRule{ cfrFoldFPBinaryOp(cfrFpCmp(.ge, true)), cfrFoldFClampFeedingCompare(.OpFOrdGreaterThanEqual) },
        .OpFUnordGreaterThanEqual => comptime &[_]ConstFoldingRule{ cfrFoldFPBinaryOp(cfrFpCmp(.ge, false)), cfrFoldFClampFeedingCompare(.OpFUnordGreaterThanEqual) },
        .OpVectorShuffle => comptime &[_]ConstFoldingRule{cfrFoldVectorShuffleWithConstants},
        .OpVectorTimesScalar => comptime &[_]ConstFoldingRule{cfrFoldVectorTimesScalar},
        .OpVectorTimesMatrix => comptime &[_]ConstFoldingRule{cfrFoldVectorTimesMatrix},
        .OpMatrixTimesVector => comptime &[_]ConstFoldingRule{cfrFoldMatrixTimesVector},
        .OpTranspose => comptime &[_]ConstFoldingRule{cfrFoldTranspose},
        .OpFNegate => comptime &[_]ConstFoldingRule{cfrFoldFNegate()},
        .OpSNegate => comptime &[_]ConstFoldingRule{cfrFoldSNegate()},
        .OpQuantizeToF16 => comptime &[_]ConstFoldingRule{cfrFoldQuantizeToF16()},
        .OpIAdd => comptime &[_]ConstFoldingRule{cfrFoldBinaryOp(cfrFoldBinaryIntegerOperation(.unsigned, cfrOpAdd))},
        .OpISub => comptime &[_]ConstFoldingRule{ cfrFoldBinaryOp(cfrFoldBinaryIntegerOperation(.unsigned, cfrOpSub)), cfrFoldRedundantSub },
        .OpIMul => comptime &[_]ConstFoldingRule{cfrFoldBinaryOp(cfrFoldBinaryIntegerOperation(.unsigned, cfrOpMul))},
        .OpUDiv => comptime &[_]ConstFoldingRule{ cfrFoldBinaryOp(cfrFoldBinaryIntegerOperation(.unsigned, cfrOpUDiv)), cfrFoldRedundantDiv },
        .OpSDiv => comptime &[_]ConstFoldingRule{ cfrFoldBinaryOp(cfrFoldBinaryIntegerOperation(.signed, cfrOpSDiv)), cfrFoldRedundantDiv },
        .OpUMod => comptime &[_]ConstFoldingRule{cfrFoldBinaryOp(cfrFoldBinaryIntegerOperation(.unsigned, cfrOpUMod))},
        .OpSRem => comptime &[_]ConstFoldingRule{cfrFoldBinaryOp(cfrFoldBinaryIntegerOperation(.signed, cfrOpSRem))},
        .OpSMod => comptime &[_]ConstFoldingRule{cfrFoldBinaryOp(cfrFoldBinaryIntegerOperation(.signed, cfrOpSMod))},
        else => &.{},
    };
}

// Folding rules: algebraic simplifications that rewrite an instruction in place, with or without constant operands (port of
// source/opt/folding_rules.cpp, folding_rules.h)
//
// Every C++ rule factory (a function returning a capture-less lambda) becomes either a plain function (no factory
// parameters) or a comptime function returning a function pointer (factories with parameters, e.g.
// `ReassociateNestedGenericInt(spv::Op)`). The per-opcode lists in `foldingRulesFor` are `comptime &[_]FoldingRule{...}`
// in the exact registration order of FoldingRules::AddFoldingRules (the first rule that returns true wins).
// A rule rewrites `inst` in place (SetOpcode / SetInOperands) and returns true, or returns false.
// Rules never touch the def-use manager themselves: the caller (InstructionFolder users) updates it.
// Like a C++ release build, the rules do not check what the C++ only asserts.

const fr_extract_composite_id_in_idx: u32 = 0;

const fr_ext_inst_set_id_in_idx: u32 = 0;
const fr_ext_inst_instruction_in_idx: u32 = 1;
const fr_fmix_x_id_in_idx: u32 = 2;
const fr_fmix_y_id_in_idx: u32 = 3;
const fr_fmix_a_id_in_idx: u32 = 4;

fn frTypeOf(ctx: *Ctx, inst: *const Inst) *const Type {
    return ctx.getTypeMgr().getType(inst.typeId()) orelse fatal("folding rule: type of %{d} is not registered", .{inst.resultId()});
}

fn frDefOf(ctx: *Ctx, id: u32) *Inst {
    return ctx.getDefUseMgr().getDef(id) orelse fatal("folding rule: id %{d} has no definition", .{id});
}

fn frElementWidth(ty: *const Type) u32 {
    if (ty.as(.cooperative_vector_nv)) |cv| return frElementWidth(cv.component);
    if (ty.as(.vector)) |v| return frElementWidth(v.element);
    if (ty.as(.float)) |f| return f.width;
    const it: *const TyInteger = ty.as(.integer) orelse fatal("ElementWidth: not an integer, float or vector type", .{});
    return it.width;
}

// ---- small helpers ----------------------------------------------------------------------------------------------

fn frIdOp(id: u32) Operand {
    return Operand.id(.IdRef, id);
}

/// ConstInput: the first constant of the pair that is not null.
fn frConstInput(constants: []const ?*const Constant) ?*const Constant {
    return constants[0] orelse constants[1];
}

/// NonConstInput: the definition of the in-operand that is not the constant `c` (operand 1 when operand 0 is the constant).
fn frNonConstInput(ctx: *Ctx, c: ?*const Constant, inst: *const Inst) *Inst {
    const in_op: usize = if (c != null) 1 else 0;
    return frDefOf(ctx, inst.getSingleWordInOperand(in_op));
}

/// IRContext::kAnalysisDefUse | IRContext::kAnalysisInstrToBlockMapping, the analyses the rule-created instructions keep valid.
const fr_builder_analyses: u32 = Analysis.def_use | Analysis.instr_to_block;

const fr_merge_binary_op_select_ops = [_]Op{
    .OpLogicalEqual,       .OpLogicalNotEqual,     .OpLogicalAnd,          .OpLogicalOr,
    .OpIEqual,             .OpINotEqual,           .OpUGreaterThan,        .OpSGreaterThan,
    .OpUGreaterThanEqual,  .OpSGreaterThanEqual,   .OpULessThan,           .OpSLessThan,
    .OpULessThanEqual,     .OpSLessThanEqual,      .OpFOrdEqual,           .OpFUnordEqual,
    .OpFOrdNotEqual,       .OpFUnordNotEqual,      .OpFOrdLessThan,        .OpFUnordLessThan,
    .OpFOrdGreaterThan,    .OpFUnordGreaterThan,   .OpFOrdLessThanEqual,   .OpFUnordLessThanEqual,
    .OpFOrdGreaterThanEqual, .OpFUnordGreaterThanEqual, .OpIAdd,           .OpFAdd,
    .OpISub,               .OpFSub,                .OpIMul,                .OpFMul,
    .OpUDiv,               .OpSDiv,                .OpFDiv,                .OpVectorTimesScalar,
    .OpShiftRightLogical,  .OpShiftRightArithmetic, .OpShiftLeftLogical,   .OpBitwiseXor,
    .OpBitwiseOr,          .OpBitwiseAnd,
};

/// The id of the instruction defining constant `c` (creating it when needed), like `GetDefiningInstruction(c)->result_id()`.
fn frConstId(cm: *ConstMgr, c: ?*const Constant) u32 {
    const def: *Inst = cm.getDefiningInstruction(c, 0, null) orelse fatal("folding rule: could not create a defining instruction for a constant", .{});
    return def.resultId();
}

/// IsValidResult: false for NaN, infinity and subnormal values.
fn frIsValidResult(comptime T: type, val: T) bool {
    if (std.math.isNan(val) or std.math.isInf(val)) return false;
    if (val != 0 and !std.math.isNormal(val)) return false;
    return true;
}

fn frReciprocal(cm: *ConstMgr, c: *const Constant) u32 {
    if (c.isZero()) return 0;
    if (c.ty.as(.vector) != null) {
        var ids: List(u32) = .{};
        for (c.components.items) |comp| {
            const id: u32 = frReciprocal(cm, comp);
            if (id == 0) return 0;
            ids.push(id);
        }
        const reciprocal_const: ?*const Constant = cm.getConstant(c.ty, ids.items);
        return frConstId(cm, reciprocal_const);
    }
    const ft: *const TyFloat = c.ty.as(.float) orelse fatal("Reciprocal: not a float constant", .{});
    var result: ?*const Constant = null;
    if (ft.width == 64) {
        const r: f64 = 1.0 / c.getDouble();
        if (!frIsValidResult(f64, r)) return 0;
        result = cm.getConstant(c.ty, &fpWordsF64(r));
    } else {
        const r: f32 = 1.0 / c.getFloat();
        if (!frIsValidResult(f32, r)) return 0;
        result = cm.getConstant(c.ty, &fpWordsF32(r));
    }
    return frConstId(cm, result);
}

// ---- reciprocal and negate rules ----------------------------------------------------------------------------------

// Replaces x / c by x * (1 / c) when c is a nonzero float (or vector of nonzero floats) with a valid reciprocal.
fn frReciprocalFDiv(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const cm: *ConstMgr = ctx.getConstantMgr();
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    if (constants[1]) |c1| {
        var id: u32 = 0;
        if (c1.kind == .vector) {
            var neg_ids: List(u32) = .{};
            for (c1.components.items) |comp| {
                id = frReciprocal(cm, comp);
                if (id == 0) return false;
                neg_ids.push(id);
            }
            const negated_const: ?*const Constant = cm.getConstant(c1.ty, neg_ids.items);
            id = frConstId(cm, negated_const);
        } else if (c1.kind == .float) {
            id = frReciprocal(cm, c1);
            if (id == 0) return false;
        } else {
            return false;
        }
        inst.setOpcode(.OpFMul);
        inst.setInOperands(&.{ frIdOp(inst.getSingleWordInOperand(0)), frIdOp(id) });
        return true;
    }
    return false;
}

// Folds -(-x) to x.
fn frMergeNegateArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const ty: *const Type = frTypeOf(ctx, inst);
    if (cfrHasFloatingPoint(ty) and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const op_inst: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    if (cfrHasFloatingPoint(ty) and !instIsFloatingPointFoldingAllowed(ctx, op_inst)) return false;
    if (op_inst.op == inst.op) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(op_inst.getSingleWordInOperand(0))});
        return true;
    }
    return false;
}

fn frNegateFloatingPointConstant(cm: *ConstMgr, c: *const Constant) u32 {
    const ft: *const TyFloat = c.ty.as(.float) orelse fatal("NegateFloatingPointConstant: not a float constant", .{});
    var negated: ?*const Constant = null;
    if (ft.width == 64) {
        const r: f64 = c.getDouble() * -1.0;
        negated = cm.getConstant(c.ty, &fpWordsF64(r));
    } else {
        const r: f32 = c.getFloat() * -1.0;
        negated = cm.getConstant(c.ty, &fpWordsF32(r));
    }
    return frConstId(cm, negated);
}

fn frExtractInts(val: u64) [2]u32 {
    return .{ @truncate(val), @truncate(val >> 32) };
}

fn frNegateIntegerConstant(cm: *ConstMgr, c: *const Constant) u32 {
    const it: *const TyInteger = c.ty.as(.integer) orelse fatal("NegateIntegerConstant: not an integer constant", .{});
    var negated: ?*const Constant = null;
    if (it.width == 64) {
        const uval: u64 = 0 -% c.getU64();
        negated = cm.getConstant(c.ty, &frExtractInts(uval));
    } else {
        const w: [1]u32 = .{0 -% c.getU32()};
        negated = cm.getConstant(c.ty, &w);
    }
    return frConstId(cm, negated);
}

fn frNegateVectorConstant(cm: *ConstMgr, c: *const Constant) u32 {
    if (c.kind == .null_) return frConstId(cm, c);
    const vt: *const TyVector = c.ty.as(.vector) orelse fatal("NegateVectorConstant: not a vector constant", .{});
    var ids: List(u32) = .{};
    for (c.components.items) |comp| {
        if (vt.element.as(.float) != null) {
            ids.push(frNegateFloatingPointConstant(cm, comp));
        } else {
            ids.push(frNegateIntegerConstant(cm, comp));
        }
    }
    const negated: ?*const Constant = cm.getConstant(c.ty, ids.items);
    return frConstId(cm, negated);
}

fn frNegateConstant(cm: *ConstMgr, c: *const Constant) u32 {
    if (c.ty.as(.vector) != null) return frNegateVectorConstant(cm, c);
    if (c.ty.as(.float) != null) return frNegateFloatingPointConstant(cm, c);
    return frNegateIntegerConstant(cm, c);
}

// Folds -(x * c) to x * (-c) and -(x / c) to x / (-c).
fn frMergeNegateMulDivArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    if (cfrHasFloatingPoint(ty) and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const op_inst: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    if (cfrHasFloatingPoint(ty) and !instIsFloatingPointFoldingAllowed(ctx, op_inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const opcode: Op = op_inst.op;
    if (opcode != .OpFMul and opcode != .OpFDiv and opcode != .OpIMul and opcode != .OpSDiv) return false;
    const op_constants: List(?*const Constant) = cm.getOperandConstants(op_inst);
    if (op_constants.items[0] == null and op_constants.items[1] == null) return false;
    const zero_is_variable: bool = op_constants.items[0] == null;
    const c: *const Constant = frConstInput(op_constants.items).?;
    const neg_id: u32 = frNegateConstant(cm, c);
    const non_const_id: u32 = if (zero_is_variable) op_inst.getSingleWordInOperand(0) else op_inst.getSingleWordInOperand(1);
    inst.setOpcode(op_inst.op);
    if (opcode == .OpFDiv or opcode == .OpUDiv or opcode == .OpSDiv) {
        const op0: u32 = if (zero_is_variable) non_const_id else neg_id;
        const op1: u32 = if (zero_is_variable) neg_id else non_const_id;
        inst.setInOperands(&.{ frIdOp(op0), frIdOp(op1) });
    } else {
        inst.setInOperands(&.{ frIdOp(non_const_id), frIdOp(neg_id) });
    }
    return true;
}

// Folds -(x + c) to (-c) - x, -(x - c) to c - x and -(c - x) to x - c.
fn frMergeNegateAddSubArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    if (cfrHasFloatingPoint(ty) and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const op_inst: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    if (cfrHasFloatingPoint(ty) and !instIsFloatingPointFoldingAllowed(ctx, op_inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    if (op_inst.op == .OpFAdd or op_inst.op == .OpFSub or op_inst.op == .OpIAdd or op_inst.op == .OpISub) {
        const op_constants: List(?*const Constant) = cm.getOperandConstants(op_inst);
        if (op_constants.items[0] != null or op_constants.items[1] != null) {
            const zero_is_variable: bool = op_constants.items[0] == null;
            const is_add: bool = (op_inst.op == .OpFAdd) or (op_inst.op == .OpIAdd);
            const swap_operands: bool = !is_add or zero_is_variable;
            const negate_const: bool = is_add;
            const c: *const Constant = frConstInput(op_constants.items).?;
            var const_id: u32 = 0;
            if (negate_const) {
                const_id = frNegateConstant(cm, c);
            } else {
                const_id = if (zero_is_variable) op_inst.getSingleWordInOperand(1) else op_inst.getSingleWordInOperand(0);
            }
            var op0: u32 = if (zero_is_variable) op_inst.getSingleWordInOperand(0) else const_id;
            var op1: u32 = if (zero_is_variable) const_id else op_inst.getSingleWordInOperand(1);
            if (swap_operands) std.mem.swap(u32, &op0, &op1);
            inst.setOpcode(if (cfrHasFloatingPoint(ty)) .OpFSub else .OpISub);
            inst.setInOperands(&.{ frIdOp(op0), frIdOp(op1) });
            return true;
        }
    }
    return false;
}

// ---- constant arithmetic used by the merge rules ------------------------------------------------------------------

fn frHasZero(c: *const Constant) bool {
    if (c.kind == .null_) return true;
    if (c.kind == .vector) {
        for (c.components.items) |comp| {
            if (frHasZero(comp)) return true;
        }
    } else {
        return c.isZero();
    }
    return false;
}

const FrFpOp = enum { mul, div, add, sub };

fn frFpArith(comptime T: type, op: FrFpOp, a: T, b: T) T {
    return switch (op) {
        .mul => a * b,
        .div => a / b,
        .add => a + b,
        .sub => a - b,
    };
}

/// FOLD_OP of PerformFloatingPointOperation: false when the result is NaN, infinite or subnormal.
fn frFoldFpOp(op: FrFpOp, width: u32, a: *const Constant, b: *const Constant, words: *List(u32)) bool {
    if (width == 64) {
        const v = frFpArith(f64, op, a.getDouble(), b.getDouble());
        if (!frIsValidResult(f64, v)) return false;
        words.pushSlice(&fpWordsF64(v));
    } else {
        const v = frFpArith(f32, op, a.getFloat(), b.getFloat());
        if (!frIsValidResult(f32, v)) return false;
        words.pushSlice(&fpWordsF32(v));
    }
    return true;
}

fn frPerformFloatingPointOperation(cm: *ConstMgr, opcode: Op, input1: *const Constant, input2: *const Constant) u32 {
    const ty: *const Type = input1.ty;
    const ft: *const TyFloat = ty.as(.float) orelse fatal("PerformFloatingPointOperation: not a float constant", .{});
    var words: List(u32) = .{};
    switch (opcode) {
        .OpFMul => if (!frFoldFpOp(.mul, ft.width, input1, input2, &words)) return 0,
        .OpFDiv => {
            if (frHasZero(input2)) return 0;
            if (!frFoldFpOp(.div, ft.width, input1, input2, &words)) return 0;
        },
        .OpFAdd => if (!frFoldFpOp(.add, ft.width, input1, input2, &words)) return 0,
        .OpFSub => if (!frFoldFpOp(.sub, ft.width, input1, input2, &words)) return 0,
        else => {}, // the C++ asserts "Unexpected operation" and builds a null constant
    }
    const merged_const: ?*const Constant = cm.getConstant(ty, words.items);
    return frConstId(cm, merged_const);
}

fn frPerformIntegerOperation(cm: *ConstMgr, opcode: Op, input1: *const Constant, input2: *const Constant) u32 {
    const ty: *const Type = input1.ty;
    const it: *const TyInteger = ty.as(.integer) orelse fatal("PerformIntegerOperation: not an integer constant", .{});
    var words: List(u32) = .{};
    switch (opcode) {
        .OpIMul, .OpIAdd, .OpISub, .OpBitwiseXor, .OpBitwiseOr, .OpBitwiseAnd => {
            if (it.width == 64) {
                const a: u64 = input1.getU64();
                const b: u64 = input2.getU64();
                const v: u64 = switch (opcode) {
                    .OpIMul => a *% b,
                    .OpIAdd => a +% b,
                    .OpISub => a -% b,
                    .OpBitwiseXor => a ^ b,
                    .OpBitwiseOr => a | b,
                    .OpBitwiseAnd => a & b,
                    else => unreachable,
                };
                words.pushSlice(&frExtractInts(v));
            } else {
                const a: u32 = input1.getU32();
                const b: u32 = input2.getU32();
                const v: u32 = switch (opcode) {
                    .OpIMul => a *% b,
                    .OpIAdd => a +% b,
                    .OpISub => a -% b,
                    .OpBitwiseXor => a ^ b,
                    .OpBitwiseOr => a | b,
                    .OpBitwiseAnd => a & b,
                    else => unreachable,
                };
                words.push(v);
            }
        },
        else => {}, // OpSDiv/OpUDiv and anything else: the C++ asserts and builds a null constant
    }
    const merged_const: ?*const Constant = cm.getConstant(ty, words.items);
    return frConstId(cm, merged_const);
}

/// PerformOperation: applies `opcode` to two scalar or vector constants of the same type; 0 when it cannot be folded.
fn frPerformOperation(cm: *ConstMgr, opcode: Op, input1: *const Constant, input2: *const Constant) u32 {
    const ty: *const Type = input1.ty;
    if (ty.as(.vector)) |vector_type| {
        const ele_type: *const Type = vector_type.element;
        var words: List(u32) = .{};
        var i: u32 = 0;
        while (i != vector_type.count) : (i += 1) {
            const input1_comp: *const Constant = if (input1.kind == .vector) input1.components.items[i] else cm.getConstant(ele_type, &.{}).?;
            const input2_comp: *const Constant = if (input2.kind == .vector) input2.components.items[i] else cm.getConstant(ele_type, &.{}).?;
            var id: u32 = 0;
            if (ele_type.as(.float) != null) {
                id = frPerformFloatingPointOperation(cm, opcode, input1_comp, input2_comp);
            } else {
                id = frPerformIntegerOperation(cm, opcode, input1_comp, input2_comp);
            }
            if (id == 0) return 0;
            words.push(id);
        }
        const merged_const: ?*const Constant = cm.getConstant(ty, words.items);
        return frConstId(cm, merged_const);
    } else if (ty.as(.float) != null) {
        return frPerformFloatingPointOperation(cm, opcode, input1, input2);
    }
    return frPerformIntegerOperation(cm, opcode, input1, input2);
}

// ---- merge rules ----------------------------------------------------------------------------------------------------

// Merges consecutive multiplies where each contains one constant operand: (x * c1) * c2 -> x * (c1 * c2).
fn frMergeMulMulArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const cm: *ConstMgr = ctx.getConstantMgr();
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    if (cfrHasFloatingPoint(ty) and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (cfrHasFloatingPoint(ty) and !instIsFloatingPointFoldingAllowed(ctx, other_inst)) return false;
    if (other_inst.op == inst.op) {
        const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
        const const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
        const other_first_is_variable: bool = other_constants.items[0] == null;
        const merged_id: u32 = frPerformOperation(cm, inst.op, const_input1, const_input2);
        if (merged_id == 0) return false;
        const non_const_id: u32 = if (other_first_is_variable) other_inst.getSingleWordInOperand(0) else other_inst.getSingleWordInOperand(1);
        inst.setInOperands(&.{ frIdOp(non_const_id), frIdOp(merged_id) });
        return true;
    }
    return false;
}

// Merges a multiply feeding a divide (or the reverse) when one constant is on each side: (x / c1) * c2 and friends.
fn frMergeMulDivArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const cm: *ConstMgr = ctx.getConstantMgr();
    const du: *DefUseMgr = ctx.getDefUseMgr();
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    for (0..2) |i| {
        const op_id: u32 = inst.getSingleWordInOperand(i);
        const op_inst: *Inst = du.getDef(op_id) orelse fatal("MergeMulDivArithmetic: id %{d} has no definition", .{op_id});
        if (op_inst.op == .OpFDiv) {
            if (op_inst.getSingleWordInOperand(1) == inst.getSingleWordInOperand(1 - i)) {
                inst.setOpcode(.OpCopyObject);
                inst.setInOperands(&.{frIdOp(op_inst.getSingleWordInOperand(0))});
                return true;
            }
        }
    }
    const const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (!instIsFloatingPointFoldingAllowed(ctx, other_inst)) return false;
    if (other_inst.op == .OpFDiv) {
        const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
        const const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
        if (frHasZero(const_input2)) return false;
        const other_first_is_variable: bool = other_constants.items[0] == null;
        const merged_id: u32 = frPerformOperation(cm, if (other_first_is_variable) other_inst.op else inst.op, const_input1, const_input2);
        if (merged_id == 0) return false;
        const non_const_id: u32 = if (other_first_is_variable) other_inst.getSingleWordInOperand(0) else other_inst.getSingleWordInOperand(1);
        inst.setOpcode(if (other_first_is_variable) inst.op else other_inst.op);
        if (other_first_is_variable) {
            inst.setInOperands(&.{ frIdOp(non_const_id), frIdOp(merged_id) });
        } else {
            inst.setInOperands(&.{ frIdOp(merged_id), frIdOp(non_const_id) });
        }
        return true;
    }
    return false;
}

// Folds (-x) * c to x * (-c).
fn frMergeMulNegateArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const cm: *ConstMgr = ctx.getConstantMgr();
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, other_inst)) return false;
    if (other_inst.op == .OpFNegate or other_inst.op == .OpSNegate) {
        const neg_id: u32 = frNegateConstant(cm, const_input1);
        inst.setInOperands(&.{ frIdOp(other_inst.getSingleWordInOperand(0)), frIdOp(neg_id) });
        return true;
    }
    return false;
}

fn frIsFoldableNegation(ctx: *Ctx, inst: *const Inst) bool {
    return inst.op == .OpSNegate or (inst.op == .OpFNegate and instIsFloatingPointFoldingAllowed(ctx, inst));
}

// Folds (-x) * (-y) to x * y, and the same for divisions.
fn frMergeDivMulDoubleNegative(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const ty: *const Type = frTypeOf(ctx, inst);
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const lhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    const rhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(1));
    if (frIsFoldableNegation(ctx, lhs) and frIsFoldableNegation(ctx, rhs)) {
        inst.setInOperands(&.{ frIdOp(lhs.getSingleWordInOperand(0)), frIdOp(rhs.getSingleWordInOperand(0)) });
        return true;
    }
    return false;
}

// Merges consecutive divides where each contains one constant operand.
fn frMergeDivDivArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const cm: *ConstMgr = ctx.getConstantMgr();
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    var const_input1: *const Constant = frConstInput(constants) orelse return false;
    if (frHasZero(const_input1)) return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (!instIsFloatingPointFoldingAllowed(ctx, other_inst)) return false;
    const first_is_variable: bool = constants[0] == null;
    if (other_inst.op == inst.op) {
        const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
        var const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
        if (frHasZero(const_input2)) return false;
        const other_first_is_variable: bool = other_constants.items[0] == null;
        var merge_op: Op = inst.op;
        if (other_first_is_variable) merge_op = .OpFMul;
        if (first_is_variable) std.mem.swap(*const Constant, &const_input1, &const_input2);
        const merged_id: u32 = frPerformOperation(cm, merge_op, const_input1, const_input2);
        if (merged_id == 0) return false;
        const non_const_id: u32 = if (other_first_is_variable) other_inst.getSingleWordInOperand(0) else other_inst.getSingleWordInOperand(1);
        var op: Op = inst.op;
        if (!first_is_variable and !other_first_is_variable) op = .OpFMul;
        var op1: u32 = merged_id;
        var op2: u32 = non_const_id;
        if (first_is_variable and other_first_is_variable) std.mem.swap(u32, &op1, &op2);
        inst.setOpcode(op);
        inst.setInOperands(&.{ frIdOp(op1), frIdOp(op2) });
        return true;
    }
    return false;
}

// Merges a multiply feeding a divide: (x * c1) / c2 and (x * y) / y.
fn frMergeDivMulArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const du: *DefUseMgr = ctx.getDefUseMgr();
    const cm: *ConstMgr = ctx.getConstantMgr();
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const first_op_id: u32 = inst.getSingleWordInOperand(0);
    const first_op_inst: *Inst = du.getDef(first_op_id) orelse fatal("MergeDivMulArithmetic: id %{d} has no definition", .{first_op_id});
    if (first_op_inst.op == .OpFMul) {
        for (0..2) |i| {
            if (first_op_inst.getSingleWordInOperand(i) == inst.getSingleWordInOperand(1)) {
                inst.setOpcode(.OpCopyObject);
                inst.setInOperands(&.{frIdOp(first_op_inst.getSingleWordInOperand(1 - i))});
                return true;
            }
        }
    }
    var const_input1: *const Constant = frConstInput(constants) orelse return false;
    if (frHasZero(const_input1)) return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (!instIsFloatingPointFoldingAllowed(ctx, other_inst)) return false;
    const first_is_variable: bool = constants[0] == null;
    if (other_inst.op == .OpFMul) {
        const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
        var const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
        const other_first_is_variable: bool = other_constants.items[0] == null;
        if (first_is_variable) std.mem.swap(*const Constant, &const_input1, &const_input2);
        const merged_id: u32 = frPerformOperation(cm, inst.op, const_input1, const_input2);
        if (merged_id == 0) return false;
        const non_const_id: u32 = if (other_first_is_variable) other_inst.getSingleWordInOperand(0) else other_inst.getSingleWordInOperand(1);
        var op1: u32 = merged_id;
        var op2: u32 = non_const_id;
        if (first_is_variable) std.mem.swap(u32, &op1, &op2);
        if (first_is_variable) inst.setOpcode(other_inst.op);
        inst.setInOperands(&.{ frIdOp(op1), frIdOp(op2) });
        return true;
    }
    return false;
}

// Folds c / (-x) to (-c) / x and (-x) / c to x / (-c).
fn frMergeDivNegateArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const cm: *ConstMgr = ctx.getConstantMgr();
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (!instIsFloatingPointFoldingAllowed(ctx, other_inst)) return false;
    const first_is_variable: bool = constants[0] == null;
    if (other_inst.op == .OpFNegate) {
        const neg_id: u32 = frNegateConstant(cm, const_input1);
        if (first_is_variable) {
            inst.setInOperands(&.{ frIdOp(other_inst.getSingleWordInOperand(0)), frIdOp(neg_id) });
        } else {
            inst.setInOperands(&.{ frIdOp(neg_id), frIdOp(other_inst.getSingleWordInOperand(0)) });
        }
        return true;
    }
    return false;
}

fn frTrySubstituteAddNegate(inst: *Inst, ctx: *Ctx, uses_float: bool, first: *const Inst, second: *const Inst) bool {
    if (frIsFoldableNegation(ctx, first)) {
        inst.setOpcode(if (uses_float) .OpFSub else .OpISub);
        inst.setInOperands(&.{ frIdOp(second.resultId()), frIdOp(first.getSingleWordInOperand(0)) });
        return true;
    }
    return false;
}

// Folds x + (-y) and (-y) + x to x - y.
fn frMergeAddNegateArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const ty: *const Type = frTypeOf(ctx, inst);
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const lhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    const rhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(1));
    return frTrySubstituteAddNegate(inst, ctx, uses_float, lhs, rhs) or frTrySubstituteAddNegate(inst, ctx, uses_float, rhs, lhs);
}

// Folds x - (-y) to x + y and (-x) - c to (-c) - x.
fn frMergeSubNegateArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const ty: *const Type = frTypeOf(ctx, inst);
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const lhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    const rhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(1));
    if (frIsFoldableNegation(ctx, rhs)) {
        inst.setOpcode(if (uses_float) .OpFAdd else .OpIAdd);
        inst.setInOperands(&.{ frIdOp(lhs.resultId()), frIdOp(rhs.getSingleWordInOperand(0)) });
        return true;
    }
    if (ty.isCooperativeMatrix()) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    if (constants[1]) |c1| {
        if (frIsFoldableNegation(ctx, lhs)) {
            inst.setInOperands(&.{ frIdOp(frNegateConstant(ctx.getConstantMgr(), c1)), frIdOp(lhs.getSingleWordInOperand(0)) });
            return true;
        }
    }
    return false;
}

// Merges add/add pairs where each has one constant: (x + c1) + c2 -> x + (c1 + c2).
fn frMergeAddAddArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, other_inst)) return false;
    if (other_inst.op == .OpFAdd or other_inst.op == .OpIAdd) {
        const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
        const const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
        const non_const_input: *Inst = frNonConstInput(ctx, other_constants.items[0], other_inst);
        const merged_id: u32 = frPerformOperation(cm, inst.op, const_input1, const_input2);
        if (merged_id == 0) return false;
        inst.setInOperands(&.{ frIdOp(non_const_input.resultId()), frIdOp(merged_id) });
        return true;
    }
    return false;
}

// Merges an add feeding a sub (or the reverse) with a constant on each side: (x - c1) + c2 and friends.
fn frMergeAddSubArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, other_inst)) return false;
    if (other_inst.op == .OpFSub or other_inst.op == .OpISub) {
        const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
        const const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
        const first_is_variable: bool = other_constants.items[0] == null;
        var op: Op = inst.op;
        var op1: u32 = 0;
        var op2: u32 = 0;
        if (first_is_variable) {
            op1 = other_inst.getSingleWordInOperand(0);
            op2 = frPerformOperation(cm, other_inst.op, const_input1, const_input2);
        } else {
            op1 = frPerformOperation(cm, inst.op, const_input1, const_input2);
            op2 = other_inst.getSingleWordInOperand(1);
            op = other_inst.op;
        }
        if (op1 == 0 or op2 == 0) return false;
        inst.setOpcode(op);
        inst.setInOperands(&.{ frIdOp(op1), frIdOp(op2) });
        return true;
    }
    return false;
}

// Merges a sub feeding an add... (x + c1) - c2 and (c1 + x) - c2 and friends.
fn frMergeSubAddArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    var const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, other_inst)) return false;
    if (other_inst.op == .OpFAdd or other_inst.op == .OpIAdd) {
        const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
        var const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
        const non_const_input: *Inst = frNonConstInput(ctx, other_constants.items[0], other_inst);
        if (constants[0] == null) std.mem.swap(*const Constant, &const_input1, &const_input2);
        const merged_id: u32 = frPerformOperation(cm, inst.op, const_input1, const_input2);
        var op: Op = inst.op;
        var op1: u32 = 0;
        var op2: u32 = 0;
        if (constants[0] == null) {
            op1 = non_const_input.resultId();
            op2 = merged_id;
            op = other_inst.op;
        } else {
            op1 = merged_id;
            op2 = non_const_input.resultId();
        }
        if (op1 == 0 or op2 == 0) return false;
        inst.setOpcode(op);
        inst.setInOperands(&.{ frIdOp(op1), frIdOp(op2) });
        return true;
    }
    return false;
}

// Merges consecutive subs with one constant each: (x - c1) - c2, (c1 - x) - c2, c2 - (x - c1), c2 - (c1 - x).
fn frMergeSubSubArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    var const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, other_inst)) return false;
    if (other_inst.op == .OpFSub or other_inst.op == .OpISub) {
        const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
        var const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
        const non_const_input: *Inst = frNonConstInput(ctx, other_constants.items[0], other_inst);
        var merge_op: Op = inst.op;
        if (other_constants.items[0] == null) {
            merge_op = if (uses_float) .OpFAdd else .OpIAdd;
        } else if (constants[0] == null) {
            std.mem.swap(*const Constant, &const_input1, &const_input2);
        }
        const merged_id: u32 = frPerformOperation(cm, merge_op, const_input1, const_input2);
        if (merged_id == 0) return false;
        var op: Op = inst.op;
        if (constants[0] != null and other_constants.items[0] != null) {
            op = if (uses_float) .OpFAdd else .OpIAdd;
        }
        var op1: u32 = 0;
        var op2: u32 = 0;
        if ((constants[0] == null) != (other_constants.items[0] == null)) {
            op1 = merged_id;
            op2 = non_const_input.resultId();
        } else {
            op1 = non_const_input.resultId();
            op2 = merged_id;
        }
        inst.setOpcode(op);
        inst.setInOperands(&.{ frIdOp(op1), frIdOp(op2) });
        return true;
    }
    return false;
}

/// (x - y) + y and y + (x - y): folds to x. Updates the def-use manager itself, like the C++.
fn frMergeGenericAddendSub(ctx: *Ctx, addend: u32, sub: u32, inst: *Inst) bool {
    const sub_inst: *Inst = frDefOf(ctx, sub);
    if (sub_inst.op != .OpFSub and sub_inst.op != .OpISub) return false;
    if (sub_inst.op == .OpFSub and !instIsFloatingPointFoldingAllowed(ctx, sub_inst)) return false;
    if (addend != sub_inst.getSingleWordInOperand(1)) return false;
    inst.setOpcode(.OpCopyObject);
    inst.setInOperands(&.{frIdOp(sub_inst.getSingleWordInOperand(0))});
    ctx.updateDefUse(inst);
    return true;
}

fn frMergeGenericAddSubArithmetic(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const add_op0: u32 = inst.getSingleWordInOperand(0);
    const add_op1: u32 = inst.getSingleWordInOperand(1);
    if (frMergeGenericAddendSub(ctx, add_op0, add_op1, inst)) return true;
    return frMergeGenericAddendSub(ctx, add_op1, add_op0, inst);
}

/// a*x + a*y -> a*(x + y) when the first factors match; creates the inner add before `inst`.
fn frFactorAddSubMulsOpnds(ctx: *Ctx, factor0_0: u32, factor0_1: u32, factor1_0: u32, factor1_1: u32, inst: *Inst) bool {
    if (factor0_0 != factor1_0) return false;
    const ir_builder = InstBuilder.init(ctx, inst, fr_builder_analyses);
    const new_add_inst: *Inst = ir_builder.addBinaryOp(inst.typeId(), inst.op, factor0_1, factor1_1) orelse return false;
    const is_float: bool = inst.op == .OpFAdd or inst.op == .OpFSub;
    inst.setOpcode(if (is_float) .OpFMul else .OpIMul);
    inst.setInOperands(&.{ frIdOp(factor0_0), frIdOp(new_add_inst.resultId()) });
    ctx.updateDefUse(inst);
    return true;
}

fn frFactorAddSubMuls(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const du: *DefUseMgr = ctx.getDefUseMgr();
    const ty: *const Type = frTypeOf(ctx, inst);
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const add_op0: u32 = inst.getSingleWordInOperand(0);
    const add_op0_inst: *Inst = frDefOf(ctx, add_op0);
    if (add_op0_inst.op != .OpFMul and add_op0_inst.op != .OpIMul) return false;
    const add_op1: u32 = inst.getSingleWordInOperand(1);
    const add_op1_inst: *Inst = frDefOf(ctx, add_op1);
    if (add_op1_inst.op != .OpFMul and add_op1_inst.op != .OpIMul) return false;
    if (du.numUses(add_op0_inst) > 1) return false;
    if (du.numUses(add_op1_inst) > 1) return false;
    if (add_op0_inst.op == .OpFMul and (!instIsFloatingPointFoldingAllowed(ctx, add_op0_inst) or !instIsFloatingPointFoldingAllowed(ctx, add_op1_inst))) return false;
    for (0..2) |i| {
        for (0..2) |j| {
            if (frFactorAddSubMulsOpnds(
                ctx,
                add_op0_inst.getSingleWordInOperand(i),
                add_op0_inst.getSingleWordInOperand(1 - i),
                add_op1_inst.getSingleWordInOperand(j),
                add_op1_inst.getSingleWordInOperand(1 - j),
                inst,
            )) return true;
        }
    }
    return false;
}

// (x op c1) op (y op c2) -> (x op y) op (c1 op c2) for the integer ops IMul, BitwiseOr, BitwiseXor, BitwiseAnd.
fn frReassociateNestedGenericInt(comptime opcode: Op) FoldingRule {
    comptime {
        if (opcode != .OpIMul and opcode != .OpBitwiseOr and opcode != .OpBitwiseXor and opcode != .OpBitwiseAnd) {
            @compileError("ReassociateNestedGenericInt: wrong opcode");
        }
    }
    return struct {
        fn rule(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
            if (constants[0] != null or constants[1] != null) return false;
            if (inst.op != opcode) return false;
            const ty: *const Type = frTypeOf(ctx, inst);
            if (ty.isCooperativeMatrix()) return false;
            const width: u32 = frElementWidth(ty);
            if (width != 32 and width != 64) return false;
            const lhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
            const rhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(1));
            if (lhs.op != opcode or rhs.op != opcode) return false;
            const cm: *ConstMgr = ctx.getConstantMgr();
            const lhs_constants: List(?*const Constant) = cm.getOperandConstants(lhs);
            const lhs_const: *const Constant = frConstInput(lhs_constants.items) orelse return false;
            const rhs_constants: List(?*const Constant) = cm.getOperandConstants(rhs);
            const rhs_const: *const Constant = frConstInput(rhs_constants.items) orelse return false;
            const merged_constant: u32 = frPerformOperation(cm, opcode, lhs_const, rhs_const);
            if (merged_constant == 0) return false;
            const ir_builder = InstBuilder.init(ctx, inst, fr_builder_analyses);
            const new_rhs: *Inst = ir_builder.addBinaryOp(
                inst.typeId(),
                opcode,
                frNonConstInput(ctx, lhs_constants.items[0], lhs).resultId(),
                frNonConstInput(ctx, rhs_constants.items[0], rhs).resultId(),
            ) orelse return false;
            inst.setInOperands(&.{ frIdOp(merged_constant), frIdOp(new_rhs.resultId()) });
            return true;
        }
    }.rule;
}

// (x * c1) * (y * c2) and the divide variants: reassociates so the constants are merged.
fn frReassociateNestedMulDivFloat(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (constants[0] != null or constants[1] != null) return false;
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const lhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    const rhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(1));
    const lhs_is_mul: bool = lhs.op == .OpFMul;
    const lhs_is_div: bool = lhs.op == .OpFDiv;
    const rhs_is_mul: bool = rhs.op == .OpFMul;
    const rhs_is_div: bool = rhs.op == .OpFDiv;
    if (!(lhs_is_mul or lhs_is_div) or !(rhs_is_mul or rhs_is_div)) return false;
    if (!instIsFloatingPointFoldingAllowed(ctx, lhs) or !instIsFloatingPointFoldingAllowed(ctx, rhs)) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const lhs_constants: List(?*const Constant) = cm.getOperandConstants(lhs);
    if (lhs_constants.items[0] == null and lhs_constants.items[1] == null) return false;
    const rhs_constants: List(?*const Constant) = cm.getOperandConstants(rhs);
    if (rhs_constants.items[0] == null and rhs_constants.items[1] == null) return false;
    var lhs_const: *const Constant = lhs_constants.items[0] orelse lhs_constants.items[1].?;
    var rhs_const: *const Constant = rhs_constants.items[0] orelse rhs_constants.items[1].?;
    const const_lhs_rcp: bool = if (lhs_constants.items[0] != null) false else lhs_is_div;
    var const_rhs_rcp: bool = if (rhs_constants.items[0] != null) false else rhs_is_div;
    const non_const_lhs: u32 = if (lhs_constants.items[0] != null) lhs.getSingleWordInOperand(1) else lhs.getSingleWordInOperand(0);
    const non_const_lhs_rcp: bool = if (lhs_constants.items[0] != null) lhs_is_div else false;
    const non_const_rhs: u32 = if (rhs_constants.items[0] != null) rhs.getSingleWordInOperand(1) else rhs.getSingleWordInOperand(0);
    var non_const_rhs_rcp: bool = if (rhs_constants.items[0] != null) rhs_is_div else false;
    if (inst.op == .OpFDiv) {
        const_rhs_rcp = !const_rhs_rcp;
        non_const_rhs_rcp = !non_const_rhs_rcp;
    }
    if (const_lhs_rcp) {
        lhs_const = cm.findDeclaredConstant(frReciprocal(cm, lhs_const)) orelse return false;
    }
    if (const_rhs_rcp) {
        rhs_const = cm.findDeclaredConstant(frReciprocal(cm, rhs_const)) orelse return false;
    }
    const merged_constant: u32 = frPerformOperation(cm, .OpFMul, lhs_const, rhs_const);
    if (merged_constant == 0) return false;
    var op: Op = .OpNop;
    var new_rhs: ?*Inst = null;
    const ir_builder = InstBuilder.init(ctx, inst, fr_builder_analyses);
    if (!non_const_lhs_rcp and !non_const_rhs_rcp) {
        new_rhs = ir_builder.addBinaryOp(inst.typeId(), .OpFMul, non_const_lhs, non_const_rhs);
        op = .OpFMul;
    } else if (non_const_lhs_rcp and !non_const_rhs_rcp) {
        new_rhs = ir_builder.addBinaryOp(inst.typeId(), .OpFDiv, non_const_rhs, non_const_lhs);
        op = .OpFMul;
    } else if (!non_const_lhs_rcp and non_const_rhs_rcp) {
        new_rhs = ir_builder.addBinaryOp(inst.typeId(), .OpFDiv, non_const_lhs, non_const_rhs);
        op = .OpFMul;
    } else {
        new_rhs = ir_builder.addBinaryOp(inst.typeId(), .OpFMul, non_const_lhs, non_const_rhs);
        op = .OpFDiv;
    }
    const nr: *Inst = new_rhs orelse return false;
    inst.setOpcode(op);
    inst.setInOperands(&.{ frIdOp(merged_constant), frIdOp(nr.resultId()) });
    return true;
}

// (x + c1) + (y - c2) and friends: reassociates so the constants are merged.
fn frReassociateNestedAddSub(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (constants[0] != null or constants[1] != null) return false;
    const ty: *const Type = frTypeOf(ctx, inst);
    if (ty.isCooperativeMatrix()) return false;
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const uses_float: bool = cfrHasFloatingPoint(ty);
    if (uses_float and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const lhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    const rhs: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(1));
    const add_op: Op = if (uses_float) .OpFAdd else .OpIAdd;
    const sub_op: Op = if (uses_float) .OpFSub else .OpISub;
    const lhs_is_add: bool = lhs.op == add_op;
    const lhs_is_sub: bool = lhs.op == sub_op;
    const rhs_is_add: bool = rhs.op == add_op;
    const rhs_is_sub: bool = rhs.op == sub_op;
    if (!(lhs_is_add or lhs_is_sub) or !(rhs_is_add or rhs_is_sub)) return false;
    if (uses_float and (!instIsFloatingPointFoldingAllowed(ctx, lhs) or !instIsFloatingPointFoldingAllowed(ctx, rhs))) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const lhs_constants: List(?*const Constant) = cm.getOperandConstants(lhs);
    if (lhs_constants.items[0] == null and lhs_constants.items[1] == null) return false;
    const rhs_constants: List(?*const Constant) = cm.getOperandConstants(rhs);
    if (rhs_constants.items[0] == null and rhs_constants.items[1] == null) return false;
    var lhs_const: *const Constant = lhs_constants.items[0] orelse lhs_constants.items[1].?;
    var rhs_const: *const Constant = rhs_constants.items[0] orelse rhs_constants.items[1].?;
    const const_lhs_neg: bool = if (lhs_constants.items[0] != null) false else lhs_is_sub;
    var const_rhs_neg: bool = if (rhs_constants.items[0] != null) false else rhs_is_sub;
    const non_const_lhs: u32 = if (lhs_constants.items[0] != null) lhs.getSingleWordInOperand(1) else lhs.getSingleWordInOperand(0);
    const non_const_lhs_neg: bool = if (lhs_constants.items[0] != null) lhs_is_sub else false;
    const non_const_rhs: u32 = if (rhs_constants.items[0] != null) rhs.getSingleWordInOperand(1) else rhs.getSingleWordInOperand(0);
    var non_const_rhs_neg: bool = if (rhs_constants.items[0] != null) rhs_is_sub else false;
    if (inst.op == .OpFSub or inst.op == .OpISub) {
        const_rhs_neg = !const_rhs_neg;
        non_const_rhs_neg = !non_const_rhs_neg;
    }
    if (const_lhs_neg) {
        lhs_const = cm.findDeclaredConstant(frNegateConstant(cm, lhs_const)) orelse return false;
    }
    if (const_rhs_neg) {
        rhs_const = cm.findDeclaredConstant(frNegateConstant(cm, rhs_const)) orelse return false;
    }
    const merged_constant: u32 = frPerformOperation(cm, add_op, lhs_const, rhs_const);
    if (merged_constant == 0) return false;
    var op: Op = .OpNop;
    var new_rhs: ?*Inst = null;
    const ir_builder = InstBuilder.init(ctx, inst, fr_builder_analyses);
    if (!non_const_lhs_neg and !non_const_rhs_neg) {
        new_rhs = ir_builder.addBinaryOp(inst.typeId(), add_op, non_const_lhs, non_const_rhs);
        op = add_op;
    } else if (non_const_lhs_neg and !non_const_rhs_neg) {
        new_rhs = ir_builder.addBinaryOp(inst.typeId(), sub_op, non_const_rhs, non_const_lhs);
        op = add_op;
    } else if (!non_const_lhs_neg and non_const_rhs_neg) {
        new_rhs = ir_builder.addBinaryOp(inst.typeId(), sub_op, non_const_lhs, non_const_rhs);
        op = add_op;
    } else {
        new_rhs = ir_builder.addBinaryOp(inst.typeId(), add_op, non_const_lhs, non_const_rhs);
        op = sub_op;
    }
    const nr: *Inst = new_rhs orelse return false;
    inst.setOpcode(op);
    inst.setInOperands(&.{ frIdOp(merged_constant), frIdOp(nr.resultId()) });
    return true;
}

// x * 1 and 1 * x for integers.
fn frIntMultipleBy1(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = ctx;
    for (0..2) |i| {
        const c: *const Constant = constants[i] orelse continue;
        if (c.kind == .int) {
            const width: u32 = frElementWidth(c.ty);
            if (width != 32 and width != 64) return false;
            const is_one: bool = if (width == 32) c.getU32BitValue() == 1 else c.getU64BitValue() == 1;
            if (is_one) {
                inst.setOpcode(.OpCopyObject);
                inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(1 - i))});
                return true;
            }
        }
    }
    return false;
}

// OpCopyLogical of an OpCompositeConstruct: rebuilds the construct with per-field copies where the types differ.
fn frCompositeConstructFeedingCopyLogical(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const src_id: u32 = inst.getSingleWordInOperand(0);
    const src_inst: *Inst = frDefOf(ctx, src_id);
    if (src_inst.op != .OpCompositeConstruct) return false;
    const dst_type_inst: *Inst = frDefOf(ctx, inst.typeId());
    const num_constituents: usize = src_inst.numInOperands();
    var expected_type_ids: List(u32) = .{};
    if (dst_type_inst.op == .OpTypeStruct) {
        if (dst_type_inst.numInOperands() != num_constituents) return false;
        var i: usize = 0;
        while (i < num_constituents) : (i += 1) expected_type_ids.push(dst_type_inst.getSingleWordInOperand(i));
    } else if (dst_type_inst.op == .OpTypeArray) {
        const elem_type_id: u32 = dst_type_inst.getSingleWordInOperand(0);
        var i: usize = 0;
        while (i < num_constituents) : (i += 1) expected_type_ids.push(elem_type_id);
    } else {
        return false;
    }
    const ir_builder = InstBuilder.init(ctx, inst, fr_builder_analyses);
    var operands: List(Operand) = .{};
    for (0..num_constituents) |i| {
        const cid: u32 = src_inst.getSingleWordInOperand(i);
        const cdef: *Inst = frDefOf(ctx, cid);
        if (cdef.typeId() == expected_type_ids.items[i]) {
            operands.push(frIdOp(cid));
            continue;
        }
        const per_field_copy: *Inst = ir_builder.addUnaryOp(expected_type_ids.items[i], .OpCopyLogical, cid) orelse return false;
        operands.push(frIdOp(per_field_copy.resultId()));
    }
    inst.setOpcode(.OpCompositeConstruct);
    inst.setInOperands(operands.items);
    ctx.updateDefUse(inst);
    return true;
}

fn frGetNumOfElementsContributedByOperand(ctx: *Ctx, inst: *const Inst, index: usize) u32 {
    if (frTypeOf(ctx, inst).as(.vector) == null) return 1;
    const id: u32 = inst.getSingleWordInOperand(index);
    const def: *Inst = frDefOf(ctx, id);
    const vt: *const TyVector = frTypeOf(ctx, def).as(.vector) orelse return 1;
    return vt.count;
}

fn frGetExtractOperandsForElementOfCompositeConstruct(ctx: *Ctx, inst: *const Inst, result_index: u32) List(Operand) {
    var out: List(Operand) = .{};
    const result_type: *const Type = frTypeOf(ctx, inst);
    if (result_type.as(.vector) == null) {
        if (result_index < inst.numInOperands()) {
            out.push(frIdOp(inst.getSingleWordInOperand(result_index)));
        }
        return out;
    }
    var total_element_count: u32 = 0;
    var idx: usize = 0;
    while (idx < inst.numInOperands()) : (idx += 1) {
        const element_count: u32 = frGetNumOfElementsContributedByOperand(ctx, inst, idx);
        total_element_count += element_count;
        if (result_index < total_element_count) {
            const id: u32 = inst.getSingleWordInOperand(idx);
            const operand_def: *Inst = frDefOf(ctx, id);
            const operand_type: *const Type = frTypeOf(ctx, operand_def);
            out.push(frIdOp(id));
            if (operand_type.as(.vector) != null) {
                const start_index_of_id: u32 = total_element_count - element_count;
                const index_into_id: u32 = result_index - start_index_of_id;
                out.push(Operand.single(.LiteralInteger, index_into_id));
            }
            return out;
        }
    }
    return out;
}

// OpCompositeExtract of an OpCompositeConstruct: extracts from the constituent instead.
fn frCompositeConstructFeedingExtract(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    if (inst.numInOperands() <= 1) return false;
    const cid: u32 = inst.getSingleWordInOperand(fr_extract_composite_id_in_idx);
    const cinst: *Inst = frDefOf(ctx, cid);
    if (cinst.op != .OpCompositeConstruct) return false;
    const index_into_result: u32 = inst.getSingleWordInOperand(1);
    var operands: List(Operand) = frGetExtractOperandsForElementOfCompositeConstruct(ctx, cinst, index_into_result);
    if (operands.len() == 0) return false;
    var i: usize = 2;
    while (i < inst.numInOperands()) : (i += 1) {
        operands.push(Operand.single(.LiteralInteger, inst.getSingleWordInOperand(i)));
    }
    if (operands.len() == 1) inst.setOpcode(.OpCopyObject);
    inst.setInOperands(operands.items);
    return true;
}

/// GetElementType: follows the literal indices held by operands [start, end) of `inst` down from `type_id`; 0 on failure.
fn frGetElementType(du: *const DefUseMgr, type_id_in: u32, inst: *const Inst, start: usize, end: usize) u32 {
    var type_id: u32 = type_id_in;
    var i: usize = start;
    while (i < end) : (i += 1) {
        const type_inst: *Inst = du.getDef(type_id) orelse fatal("GetElementType: type %{d} has no definition", .{type_id});
        switch (type_inst.op) {
            .OpTypeArray, .OpTypeMatrix, .OpTypeVector, .OpTypeVectorIdEXT => type_id = type_inst.getSingleWordInOperand(0),
            .OpTypeStruct => type_id = type_inst.getSingleWordInOperand(inst.getSingleWordOperand(i)),
            else => return 0,
        }
    }
    return type_id;
}

// OpCompositeExtract of an OpCopyLogical: extracts from the original composite and copies.
fn frCopyLogicalFeedingExtract(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const du: *DefUseMgr = ctx.getDefUseMgr();
    const cid: u32 = inst.getSingleWordInOperand(fr_extract_composite_id_in_idx);
    const cinst: *Inst = frDefOf(ctx, cid);
    if (cinst.op != .OpCopyLogical) return false;
    const original_composite_id: u32 = cinst.getSingleWordInOperand(0);
    const original_composite_inst: *Inst = frDefOf(ctx, original_composite_id);
    var indices: List(u32) = .{};
    var i: usize = 1;
    while (i < inst.numInOperands()) : (i += 1) indices.push(inst.getSingleWordInOperand(i));
    const original_element_type_id: u32 = frGetElementType(du, original_composite_inst.typeId(), inst, 3, inst.numOperands());
    const ir_builder = InstBuilder.init(ctx, inst, fr_builder_analyses);
    const new_extract: *Inst = ir_builder.addCompositeExtract(original_element_type_id, original_composite_id, indices.items) orelse fatal("CopyLogicalFeedingExtract: ran out of ids", .{});
    if (original_element_type_id == inst.typeId()) {
        inst.setOpcode(.OpCopyObject);
    } else {
        inst.setOpcode(.OpCopyLogical);
    }
    inst.setInOperands(&.{frIdOp(new_extract.resultId())});
    return true;
}

// ---- composite rules ------------------------------------------------------------------------------------------------

/// A copy of an operand (the C++ copies Operand values; here the word storage of long operands is duplicated too).
fn frCopyOperand(op: *const Operand) Operand {
    return Operand.fromWords(op.kind, op.words());
}

// OpCompositeExtract of an OpLoad of a struct or array from memory: loads only the element through an access chain.
fn frLoadFeedingExtract(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const cid: u32 = inst.getSingleWordInOperand(fr_extract_composite_id_in_idx);
    const cinst: *Inst = frDefOf(ctx, cid);
    if (cinst.op != .OpLoad) return false;
    const composite_type_inst: *Inst = frDefOf(ctx, cinst.typeId());
    if (composite_type_inst.op != .OpTypeStruct and composite_type_inst.op != .OpTypeArray) return false;
    if (cinst.numInOperands() > 1) {
        const memory_access_mask: u32 = cinst.getSingleWordInOperand(1);
        if ((memory_access_mask & MemoryAccessMask.Volatile) != 0) return false;
    }
    const ptr_id: u32 = cinst.getSingleWordInOperand(0);
    const ptr_inst: *Inst = frDefOf(ctx, ptr_id);
    const ptr_type_inst: *Inst = frDefOf(ctx, ptr_inst.typeId());
    const storage_class: u32 = ptr_type_inst.getSingleWordInOperand(0);
    if (storage_class == @intFromEnum(StorageClass.Function) or storage_class == @intFromEnum(StorageClass.Private)) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const tm: *TypeMgr = ctx.getTypeMgr();
    var index_ids: List(u32) = .{};
    var i: usize = 1;
    while (i < inst.numInOperands()) : (i += 1) {
        const index: u32 = inst.getSingleWordInOperand(i);
        const index_const: ?*const Constant = cm.getConstant(tm.getUIntType(), &.{index});
        index_ids.push(frConstId(cm, index_const));
    }
    const ir_builder = InstBuilder.init(ctx, cinst, fr_builder_analyses);
    const element_ptr_type_id: u32 = tm.findPointerToType(inst.typeId(), storage_class);
    if (element_ptr_type_id == 0) return false;
    const access_chain: *Inst = ir_builder.addAccessChain(element_ptr_type_id, ptr_id, index_ids.items) orelse fatal("LoadFeedingExtract: ran out of ids", .{});
    var load_operands: List(Operand) = .{};
    load_operands.push(frIdOp(access_chain.resultId()));
    if (cinst.numInOperands() > 1) {
        const memory_access_mask: u32 = cinst.getSingleWordInOperand(1);
        load_operands.push(Operand.single(.MemoryAccess, memory_access_mask));
        var current_operand_index: usize = 2;
        if ((memory_access_mask & MemoryAccessMask.Aligned) != 0) {
            const original_alignment: u32 = cinst.getSingleWordInOperand(current_operand_index);
            var extract_indices: List(u32) = .{};
            var k: usize = 1;
            while (k < inst.numInOperands()) : (k += 1) extract_indices.push(inst.getSingleWordInOperand(k));
            const cinst_type: *Type = tm.getType(cinst.typeId()) orelse fatal("LoadFeedingExtract: load type is not registered", .{});
            const offset: u32 = cinst_type.getByteOffset(extract_indices.items) orelse return false;
            var new_alignment: u32 = original_alignment;
            if (offset != 0) {
                const offset_alignment: u32 = offset & ~(offset -% 1);
                new_alignment = @min(original_alignment, offset_alignment);
            }
            load_operands.push(Operand.single(.LiteralContextDependentNumber, new_alignment));
            current_operand_index += 1;
        }
        while (current_operand_index < cinst.numInOperands()) : (current_operand_index += 1) {
            load_operands.push(frCopyOperand(cinst.getInOperand(current_operand_index)));
        }
    }
    const load_result_id: u32 = ctx.takeNextId();
    if (load_result_id == 0) return false;
    const new_load_inst: *Inst = Inst.make(.OpLoad, inst.typeId(), load_result_id, load_operands.items);
    const new_load: *Inst = ir_builder.addInstruction(new_load_inst);
    inst.setOpcode(.OpCopyObject);
    inst.setInOperands(&.{frIdOp(new_load.resultId())});
    return true;
}

fn frHaveSameIndexesExceptForLast(inst_1: *const Inst, inst_2: *const Inst) bool {
    if (inst_1.numInOperands() != inst_2.numInOperands()) return false;
    const first_index_position: usize = if (inst_1.op == .OpCompositeInsert) 2 else 1;
    var i: usize = first_index_position;
    while (i < inst_1.numInOperands() - 1) : (i += 1) {
        if (inst_1.getSingleWordInOperand(i) != inst_2.getSingleWordInOperand(i)) return false;
    }
    return true;
}

// OpCompositeConstruct of consecutive OpCompositeExtracts of the same composite: the composite itself (or a sub-extract).
fn frCompositeExtractFeedingConstruct(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const du: *DefUseMgr = ctx.getDefUseMgr();
    var original_id: u32 = 0;
    if (inst.numInOperands() == 0) return false;
    var first_element_inst: ?*Inst = null;
    for (0..inst.numInOperands()) |i| {
        const element_id: u32 = inst.getSingleWordInOperand(i);
        const element_inst: *Inst = frDefOf(ctx, element_id);
        if (first_element_inst == null) first_element_inst = element_inst;
        if (element_inst.op != .OpCompositeExtract) return false;
        if (!frHaveSameIndexesExceptForLast(element_inst, first_element_inst.?)) return false;
        if (element_inst.getSingleWordInOperand(element_inst.numInOperands() - 1) != i) return false;
        if (i == 0) {
            original_id = element_inst.getSingleWordInOperand(fr_extract_composite_id_in_idx);
        } else if (original_id != element_inst.getSingleWordInOperand(fr_extract_composite_id_in_idx)) {
            return false;
        }
    }
    const first: *Inst = first_element_inst.?;
    const original_inst: *Inst = frDefOf(ctx, original_id);
    const original_type_id: u32 = frGetElementType(du, original_inst.typeId(), first, 3, first.numOperands() - 1);
    if (inst.typeId() != original_type_id) return false;
    if (first.numInOperands() == 2) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(original_id)});
        return true;
    }
    inst.setOpcode(.OpCompositeExtract);
    var new_ops: List(Operand) = .{};
    var k: usize = 2;
    while (k < first.numOperands() - 1) : (k += 1) new_ops.push(frCopyOperand(first.getOperand(k)));
    inst.setInOperands(new_ops.items);
    return true;
}

const fr_insert_object_id_in_idx: u32 = 0;
const fr_insert_composite_id_in_idx: u32 = 1;

// OpCompositeExtract of an OpCompositeInsert: the inserted object, or an extract from the inserted-into composite.
fn frInsertFeedingExtract(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const cid: u32 = inst.getSingleWordInOperand(fr_extract_composite_id_in_idx);
    const cinst: *Inst = frDefOf(ctx, cid);
    if (cinst.op != .OpCompositeInsert) return false;
    var i: usize = 1;
    while (i < inst.numInOperands()) : (i += 1) {
        if (i + 1 >= cinst.numInOperands()) break;
        if (inst.getSingleWordInOperand(i) != cinst.getSingleWordInOperand(i + 1)) break;
    }
    if (i == inst.numInOperands() and i + 1 == cinst.numInOperands()) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(cinst.getSingleWordInOperand(fr_insert_object_id_in_idx))});
        return true;
    }
    if (i == inst.numInOperands()) return false;
    if (i + 1 == cinst.numInOperands()) {
        var operands: List(Operand) = .{};
        operands.push(frIdOp(cinst.getSingleWordInOperand(fr_insert_object_id_in_idx)));
        while (i < inst.numInOperands()) : (i += 1) {
            operands.push(Operand.single(.LiteralInteger, inst.getSingleWordInOperand(i)));
        }
        inst.setInOperands(operands.items);
        return true;
    }
    var operands: List(Operand) = .{};
    operands.push(frIdOp(cinst.getSingleWordInOperand(fr_insert_composite_id_in_idx)));
    i = 1;
    while (i < inst.numInOperands()) : (i += 1) {
        operands.push(Operand.single(.LiteralInteger, inst.getSingleWordInOperand(i)));
    }
    inst.setInOperands(operands.items);
    return true;
}

// OpCompositeExtract of an OpVectorShuffle: extracts from the shuffle's source vector (or becomes OpUndef).
fn frVectorShuffleFeedingExtract(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const cid: u32 = inst.getSingleWordInOperand(fr_extract_composite_id_in_idx);
    const cinst: *Inst = frDefOf(ctx, cid);
    if (cinst.op != .OpVectorShuffle) return false;
    const first_input: *Inst = frDefOf(ctx, cinst.getSingleWordInOperand(0));
    const first_input_type: *const TyVector = frTypeOf(ctx, first_input).as(.vector) orelse fatal("VectorShuffleFeedingExtract: shuffle input is not a vector", .{});
    const first_input_size: u32 = first_input_type.count;
    var new_index: u32 = cinst.getSingleWordInOperand(2 + @as(usize, inst.getSingleWordInOperand(1)));
    const undef_literal_value: u32 = 0xffffffff;
    if (new_index == undef_literal_value) {
        inst.setOpcode(.OpUndef);
        inst.setInOperands(&.{});
        return true;
    }
    var new_vector: u32 = 0;
    if (new_index < first_input_size) {
        new_vector = cinst.getSingleWordInOperand(0);
    } else {
        new_vector = cinst.getSingleWordInOperand(1);
        new_index -= first_input_size;
    }
    inst.setInOperand(fr_extract_composite_id_in_idx, &.{new_vector});
    inst.setInOperand(1, &.{new_index});
    return true;
}

const FrInsertedValues = SortedMap(u32, u32, ascending(u32));

/// GetInsertedValues: element index -> inserted id, over the chain of OpCompositeInserts feeding `inst` (empty on a partial chain).
fn frGetInsertedValues(ctx: *Ctx, inst: *Inst) FrInsertedValues {
    var values_inserted: FrInsertedValues = .{};
    var current_inst: *Inst = inst;
    while (current_inst.op == .OpCompositeInsert) {
        if (current_inst.numInOperands() > inst.numInOperands()) {
            const partially_inserted_element_index: u32 = current_inst.getSingleWordInOperand(inst.numInOperands() - 1);
            if (!values_inserted.contains(partially_inserted_element_index)) return .{};
        }
        if (frHaveSameIndexesExceptForLast(inst, current_inst)) {
            const key: u32 = current_inst.getSingleWordInOperand(current_inst.numInOperands() - 1);
            if (!values_inserted.contains(key)) values_inserted.put(key, current_inst.getSingleWordInOperand(fr_insert_object_id_in_idx)); // std::map::insert keeps the first
        }
        current_inst = frDefOf(ctx, current_inst.getSingleWordInOperand(fr_insert_composite_id_in_idx));
    }
    return values_inserted;
}

fn frGetNumberOfElements(ty: *const Type) u32 {
    if (ty.as(.vector)) |vt| return vt.count;
    if (ty.as(.matrix)) |mt| return mt.count;
    if (ty.as(.struct_)) |st| return @intCast(st.elements.len());
    if (ty.as(.array)) |at| {
        if (at.length.words.items[0] == ArrayLength.constant and at.length.words.len() == 2) return at.length.words.items[1];
        return std.math.maxInt(u32);
    }
    return 0;
}

fn frDoInsertedValuesCoverEntireObject(ty: *const Type, values_inserted: *const FrInsertedValues) bool {
    const container_size: u32 = frGetNumberOfElements(ty);
    if (container_size != values_inserted.count()) return false;
    if (values_inserted.count() == 0) return false; // the C++ dereferences rbegin() of an empty map here (undefined); nothing to cover
    const ks: []u32 = values_inserted.keys();
    if (ks[ks.len - 1] >= container_size) return false;
    return true;
}

fn frGetContainerTypeId(ctx: *Ctx, inst: *const Inst) u32 {
    return frGetElementType(ctx.getDefUseMgr(), inst.typeId(), inst, 4, inst.numOperands() - 1);
}

fn frBuildCompositeConstruct(ctx: *Ctx, type_id: u32, values_inserted: *const FrInsertedValues, insert_before: *Inst) *Inst {
    const ir_builder = InstBuilder.init(ctx, insert_before, fr_builder_analyses);
    return ir_builder.addCompositeConstruct(type_id, values_inserted.values()) orelse fatal("BuildCompositeConstruct: ran out of ids", .{});
}

fn frInsertConstructedObject(inst: *Inst, construct: *const Inst) void {
    if (inst.numInOperands() == 3) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(construct.resultId())});
    } else {
        inst.setInOperand(fr_insert_object_id_in_idx, &.{construct.resultId()});
        inst.removeInOperand(inst.numInOperands() - 1);
    }
}

// A chain of OpCompositeInserts that overwrites every element becomes an OpCompositeConstruct.
fn frCompositeInsertToCompositeConstruct(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    if (inst.numInOperands() < 3) return false;
    const values_inserted: FrInsertedValues = frGetInsertedValues(ctx, inst);
    const container_type_id: u32 = frGetContainerTypeId(ctx, inst);
    if (container_type_id == 0) return false;
    const container_type: *Type = ctx.getTypeMgr().getType(container_type_id) orelse fatal("CompositeInsertToCompositeConstruct: container type %{d} is not registered", .{container_type_id});
    if (!frDoInsertedValuesCoverEntireObject(container_type, &values_inserted)) return false;
    const construct: *Inst = frBuildCompositeConstruct(ctx, container_type_id, &values_inserted, inst);
    frInsertConstructedObject(inst, construct);
    return true;
}

// ---- phi, bitcast, select and logical rules -------------------------------------------------------------------------

// An OpPhi whose incoming values are all the same (ignoring itself) is that value.
fn frRedundantPhi(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = ctx;
    _ = constants;
    var incoming_value: u32 = 0;
    var i: usize = 0;
    while (i < inst.numInOperands()) : (i += 2) {
        const op_id: u32 = inst.getSingleWordInOperand(i);
        if (op_id == inst.resultId()) continue;
        if (incoming_value == 0) {
            incoming_value = op_id;
        } else if (op_id != incoming_value) {
            return false;
        }
    }
    if (incoming_value == 0) return false;
    inst.setOpcode(.OpCopyObject);
    inst.setInOperands(&.{frIdOp(incoming_value)});
    return true;
}

fn frGetWordsFromScalarIntConstant(c: *const Constant) List(u32) {
    const it: *const TyInteger = c.ty.as(.integer) orelse fatal("GetWordsFromScalarIntConstant: not an integer constant", .{});
    var out: List(u32) = .{};
    if (it.width == 64) {
        out.pushSlice(&frExtractInts(c.getU64()));
        return out;
    }
    out.push(c.getU32BitValue());
    return out;
}

fn frGetWordsFromScalarFloatConstant(c: *const Constant) List(u32) {
    const ft: *const TyFloat = c.ty.as(.float) orelse fatal("GetWordsFromScalarFloatConstant: not a float constant", .{});
    var out: List(u32) = .{};
    if (ft.width == 64) {
        out.pushSlice(&fpWordsF64(c.getDouble()));
        return out;
    }
    out.push(c.getU32BitValue());
    return out;
}

fn frGetWordsFromNumericScalarOrVectorConstant(cm: *ConstMgr, c: *const Constant) List(u32) {
    var words: List(u32) = .{};
    switch (c.kind) {
        .float => return frGetWordsFromScalarFloatConstant(c),
        .int => return frGetWordsFromScalarIntConstant(c),
        .vector => {
            for (c.components.items) |comp| {
                const comp_in_words: List(u32) = frGetWordsFromNumericScalarOrVectorConstant(cm, comp);
                words.pushSlice(comp_in_words.items);
            }
            const ew: u32 = frElementWidth(c.ty);
            if (ew >= 32) return words;
            if (ew == 8) {
                var compacted_word: u32 = 0;
                var i: usize = words.len();
                while (i > 0) {
                    i -= 1;
                    compacted_word <<= 8;
                    compacted_word |= (words.items[i] & 0xFF);
                }
                var one: List(u32) = .{};
                one.push(compacted_word);
                return one;
            } else if (ew == 16) {
                var compacted_words: List(u32) = .{};
                var i: usize = 0;
                while (i < words.len()) : (i += 2) {
                    const word1: u32 = words.items[i];
                    const word2: u32 = if (i + 1 < words.len()) words.items[i + 1] else 0;
                    compacted_words.push((word2 << 16) | (word1 & 0xFFFF));
                }
                return compacted_words;
            }
            // unhandled element width: the C++ asserts and falls through to the empty result
        },
        .null_ => {
            var num_elements: u32 = 1;
            if (c.ty.as(.vector)) |vt| num_elements = vt.count;
            const element_width: u32 = frElementWidth(c.ty);
            if (element_width < 32) {
                num_elements = (num_elements + 1) / 2;
            } else if (element_width == 64) {
                num_elements = num_elements * 2;
            }
            var k: u32 = 0;
            while (k < num_elements) : (k += 1) words.push(0);
            return words;
        },
        else => {},
    }
    return .{};
}

fn frConvertWordsToNumericScalarOrVectorConstant(cm: *ConstMgr, words: []const u32, ty: *const Type) ?*const Constant {
    if (ty.as(.integer)) |int_type| {
        if (int_type.width <= 32) return cm.generateIntegerConstant(ty, words[0]);
    }
    if (ty.as(.integer) != null or ty.as(.float) != null) return cm.getConstant(ty, words);
    if (ty.as(.vector) != null) return cm.getNumericVectorConstantWithWords(ty, words);
    return null;
}

// OpBitcast of a numeric scalar or vector constant becomes the constant of the target type.
fn frBitCastScalarOrVector(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const c0: *const Constant = constants[0] orelse return false;
    const ty: *const Type = frTypeOf(ctx, inst);
    if (cfrHasFloatingPoint(ty) and !instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const words: List(u32) = frGetWordsFromNumericScalarOrVectorConstant(cm, c0);
    if (words.len() == 0) return false;
    const bitcasted_constant: *const Constant = frConvertWordsToNumericScalarOrVectorConstant(cm, words.items, ty) orelse return false;
    const def: *Inst = cm.getDefiningInstruction(bitcasted_constant, inst.typeId(), null) orelse fatal("BitCastScalarOrVector: could not create the constant", .{});
    inst.setOpcode(.OpCopyObject);
    inst.setInOperands(&.{frIdOp(def.resultId())});
    return true;
}

// Bitcast of a bitcast, or of a value that already has the result type.
fn frRedundantBitcast(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const child: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    if (inst.typeId() == child.typeId()) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(child.resultId())});
        return true;
    }
    if (child.op != .OpBitcast) return false;
    if (frDefOf(ctx, child.getSingleWordInOperand(0)).typeId() == inst.typeId()) {
        inst.setOpcode(.OpCopyObject);
    }
    inst.setInOperands(&.{frIdOp(child.getSingleWordInOperand(0))});
    return true;
}

// OpBitReverse of a 32-bit integer scalar or vector constant.
fn frBitReverseScalarOrVector(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const c0: *const Constant = constants[0] orelse return false;
    const ty: *const Type = frTypeOf(ctx, inst);
    const cm: *ConstMgr = ctx.getConstantMgr();
    var words: List(u32) = frGetWordsFromNumericScalarOrVectorConstant(cm, c0);
    if (words.len() == 0) return false;
    for (words.items) |*w| {
        var word: u32 = w.*;
        word = ((word & 0x55555555) << 1) | ((word >> 1) & 0x55555555);
        word = ((word & 0x33333333) << 2) | ((word >> 2) & 0x33333333);
        word = ((word & 0x0F0F0F0F) << 4) | ((word >> 4) & 0x0F0F0F0F);
        word = ((word & 0x00FF00FF) << 8) | ((word >> 8) & 0x00FF00FF);
        word = (word << 16) | (word >> 16);
        w.* = word;
    }
    const bitreversed_constant: *const Constant = frConvertWordsToNumericScalarOrVectorConstant(cm, words.items, ty) orelse return false;
    const def: *Inst = cm.getDefiningInstruction(bitreversed_constant, inst.typeId(), null) orelse fatal("BitReverseScalarOrVector: could not create the constant", .{});
    inst.setOpcode(.OpCopyObject);
    inst.setInOperands(&.{frIdOp(def.resultId())});
    return true;
}

// OpSelect with identical arms, or with a constant condition (scalar bool or vector of bool).
fn frRedundantSelect(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = ctx;
    const true_id: u32 = inst.getSingleWordInOperand(1);
    const false_id: u32 = inst.getSingleWordInOperand(2);
    if (true_id == false_id) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(true_id)});
        return true;
    } else if (constants[0]) |c0| {
        if (c0.ty.as(.bool_) != null) {
            inst.setOpcode(.OpCopyObject);
            if (c0.kind == .null_ or !c0.boolValue()) {
                inst.setInOperands(&.{frIdOp(false_id)});
            } else {
                inst.setInOperands(&.{frIdOp(true_id)});
            }
            return true;
        } else {
            if (c0.kind == .null_) {
                inst.setOpcode(.OpCopyObject);
                inst.setInOperands(&.{frIdOp(false_id)});
                return true;
            } else {
                var ops: List(Operand) = .{};
                ops.push(frIdOp(true_id));
                ops.push(frIdOp(false_id));
                const size: u32 = @intCast(c0.components.len());
                var i: u32 = 0;
                while (i != size) : (i += 1) {
                    const component: *const Constant = c0.components.items[i];
                    if (component.kind == .null_ or !component.boolValue()) {
                        ops.push(Operand.single(.LiteralInteger, i + size));
                    } else {
                        ops.push(Operand.single(.LiteralInteger, i));
                    }
                }
                inst.setOpcode(.OpVectorShuffle);
                inst.setInOperands(ops.items);
                return true;
            }
        }
    }
    return false;
}

/// GetBoolConstantKind: the common boolean value of a (composite of) bool constant(s), or null when mixed or not boolean.
fn frGetBoolConstantKind(c_in: ?*const Constant) ?bool {
    const c: *const Constant = c_in orelse return null;
    if (c.isComposite()) {
        const components: []*const Constant = c.components.items;
        if (components.len == 0) return null;
        const first: bool = frGetBoolConstantKind(components[0]) orelse return null;
        for (components[1..]) |c2| {
            const k: bool = frGetBoolConstantKind(c2) orelse return null;
            if (k != first) return null;
        }
        return first;
    } else if (c.kind == .null_) {
        return false;
    } else if (c.kind == .bool_) {
        return c.boolValue();
    }
    return null;
}

// Select between constant true and false values: the condition itself or its negation.
fn frFoldConstantBooleanSelect(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (constants[1] == null or constants[2] == null) return false;
    if (inst.typeId() != frDefOf(ctx, inst.getSingleWordInOperand(0)).typeId()) return false;
    const uniform_true: bool = frGetBoolConstantKind(constants[1]) orelse return false;
    const uniform_false: bool = frGetBoolConstantKind(constants[2]) orelse return false;
    if (uniform_true and !uniform_false) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(0))});
        return true;
    } else if (!uniform_true and uniform_false) {
        inst.setOpcode(.OpLogicalNot);
        inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(0))});
        return true;
    }
    return false;
}

// x && true -> x
fn frRedundantLogicalAnd(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (frGetBoolConstantKind(frConstInput(constants)) == true) {
        const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(other_inst.resultId())});
        return true;
    }
    return false;
}

// x || false -> x
fn frRedundantLogicalOr(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (frGetBoolConstantKind(frConstInput(constants)) == false) {
        const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(other_inst.resultId())});
        return true;
    }
    return false;
}

// !!x -> x
fn frRedundantLogicalNot(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const child: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    if (child.op == .OpLogicalNot) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(child.getSingleWordInOperand(0))});
        return true;
    }
    return false;
}

/// The comparison opcode that is the logical negation of `op`, or OpNop.
fn frNegatedComparison(op: Op) Op {
    return switch (op) {
        .OpIEqual => .OpINotEqual,
        .OpINotEqual => .OpIEqual,
        .OpFOrdEqual => .OpFUnordNotEqual,
        .OpFOrdNotEqual => .OpFUnordEqual,
        .OpFUnordEqual => .OpFOrdNotEqual,
        .OpFUnordNotEqual => .OpFOrdEqual,
        .OpLogicalEqual => .OpLogicalNotEqual,
        .OpLogicalNotEqual => .OpLogicalEqual,
        .OpUGreaterThan => .OpULessThanEqual,
        .OpULessThanEqual => .OpUGreaterThan,
        .OpSGreaterThan => .OpSLessThanEqual,
        .OpSLessThanEqual => .OpSGreaterThan,
        .OpFOrdGreaterThan => .OpFUnordLessThanEqual,
        .OpFOrdLessThanEqual => .OpFUnordGreaterThan,
        .OpFUnordGreaterThan => .OpFOrdLessThanEqual,
        .OpFUnordLessThanEqual => .OpFOrdGreaterThan,
        .OpULessThan => .OpUGreaterThanEqual,
        .OpUGreaterThanEqual => .OpULessThan,
        .OpSLessThan => .OpSGreaterThanEqual,
        .OpSGreaterThanEqual => .OpSLessThan,
        .OpFOrdLessThan => .OpFUnordGreaterThanEqual,
        .OpFOrdGreaterThanEqual => .OpFUnordLessThan,
        .OpFUnordLessThan => .OpFOrdGreaterThanEqual,
        .OpFUnordGreaterThanEqual => .OpFOrdLessThan,
        else => .OpNop,
    };
}

// !(a < b) -> a >= b and the other comparisons (when the comparison has no other use).
fn frFoldLogicalNotComparison(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const du: *DefUseMgr = ctx.getDefUseMgr();
    const child: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    if (du.numUses(child) > 1) return false;
    const new_opcode: Op = frNegatedComparison(child.op);
    if (new_opcode == .OpNop) return false;
    inst.setOpcode(new_opcode);
    inst.setInOperands(&.{ frIdOp(child.getSingleWordInOperand(0)), frIdOp(child.getSingleWordInOperand(1)) });
    return true;
}

// x == true -> x, x == false -> !x, x != true -> !x, x != false -> x
fn frRedundantLogicalEqual(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const const_input: *const Constant = frConstInput(constants) orelse return false;
    if (inst.typeId() != frDefOf(ctx, inst.getSingleWordInOperand(0)).typeId()) return false;
    const uniform_const: bool = frGetBoolConstantKind(const_input) orelse return false;
    const direct_copy: bool = if (inst.op == .OpLogicalEqual) uniform_const else !uniform_const;
    inst.setOpcode(if (direct_copy) .OpCopyObject else .OpLogicalNot);
    inst.setInOperands(&.{frIdOp(frNonConstInput(ctx, constants[0], inst).resultId())});
    return true;
}

const FrFloatKind = enum { unknown, zero, one };

fn frGetFloatConstantKind(constant: ?*const Constant) FrFloatKind {
    const c: *const Constant = constant orelse return .unknown;
    if (c.kind == .null_) return .zero;
    if (c.kind == .vector) {
        const components: []*const Constant = c.components.items;
        const kind: FrFloatKind = frGetFloatConstantKind(components[0]);
        for (components[1..]) |comp| {
            if (frGetFloatConstantKind(comp) != kind) return .unknown;
        }
        return kind;
    } else if (c.kind == .float) {
        if (c.isZero()) return .zero;
        const ft: *const TyFloat = c.ty.as(.float) orelse fatal("getFloatConstantKind: not a float constant", .{});
        if (ft.width != 32 and ft.width != 64) return .unknown;
        const value: f64 = if (ft.width == 64) c.getDouble() else c.getFloat();
        if (value == 0.0) return .zero;
        if (value == 1.0) return .one;
        return .unknown;
    }
    return .unknown;
}

// ---- redundant floating point operations ------------------------------------------------------------------------------

// x + 0 and 0 + x
fn frRedundantFAdd(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const kind0: FrFloatKind = frGetFloatConstantKind(constants[0]);
    const kind1: FrFloatKind = frGetFloatConstantKind(constants[1]);
    if (kind0 == .zero or kind1 == .zero) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(if (kind0 == .zero) 1 else 0))});
        return true;
    }
    return false;
}

// x - 0 and 0 - x
fn frRedundantFSub(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const kind0: FrFloatKind = frGetFloatConstantKind(constants[0]);
    const kind1: FrFloatKind = frGetFloatConstantKind(constants[1]);
    if (kind0 == .zero) {
        inst.setOpcode(.OpFNegate);
        inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(1))});
        return true;
    }
    if (kind1 == .zero) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(0))});
        return true;
    }
    return false;
}

// x * 0, 0 * x (the zero operand), x * 1 and 1 * x
fn frRedundantFMul(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const kind0: FrFloatKind = frGetFloatConstantKind(constants[0]);
    const kind1: FrFloatKind = frGetFloatConstantKind(constants[1]);
    if (kind0 == .zero or kind1 == .zero) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(if (kind0 == .zero) 0 else 1))});
        return true;
    }
    if (kind0 == .one or kind1 == .one) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(if (kind0 == .one) 1 else 0))});
        return true;
    }
    return false;
}

// 0 / x and x / 1
fn frRedundantFDiv(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const kind0: FrFloatKind = frGetFloatConstantKind(constants[0]);
    const kind1: FrFloatKind = frGetFloatConstantKind(constants[1]);
    if (kind0 == .zero or kind1 == .one) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(0))});
        return true;
    }
    return false;
}

// 0 % x
fn frRedundantFMod(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const kind0: FrFloatKind = frGetFloatConstantKind(constants[0]);
    if (kind0 == .zero) {
        inst.setOpcode(.OpCopyObject);
        inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(0))});
        return true;
    }
    return false;
}

// GLSL FMix(x, y, 0) -> x and FMix(x, y, 1) -> y
fn frRedundantFMix(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    const inst_set_id: u32 = ctx.getFeatureMgr().extinst_importid_glsl_std_450;
    if (inst.getSingleWordInOperand(fr_ext_inst_set_id_in_idx) == inst_set_id and
        inst.getSingleWordInOperand(fr_ext_inst_instruction_in_idx) == glslNum("FMix"))
    {
        const kind4: FrFloatKind = frGetFloatConstantKind(constants[4]);
        if (kind4 == .zero or kind4 == .one) {
            inst.setOpcode(.OpCopyObject);
            inst.setInOperands(&.{frIdOp(inst.getSingleWordInOperand(if (kind4 == .zero) fr_fmix_x_id_in_idx else fr_fmix_y_id_in_idx))});
            return true;
        }
    }
    return false;
}

// ---- redundant integer operations -------------------------------------------------------------------------------------

// Operand `arg` is a zero constant: the instruction folds to operand `fold_to_arg` (copy or bitcast depending on the types).
fn frRedundantBinaryOpWithZeroOperand(comptime arg: usize, comptime fold_to_arg: usize) FoldingRule {
    return struct {
        fn rule(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
            if (constants[arg]) |ca| {
                if (ca.isZero()) {
                    const operand: u32 = inst.getSingleWordInOperand(fold_to_arg);
                    const operand_type: *const Type = ca.ty;
                    const inst_type: *const Type = frTypeOf(ctx, inst);
                    if (inst_type.isSame(operand_type)) {
                        inst.setOpcode(.OpCopyObject);
                    } else {
                        inst.setOpcode(.OpBitcast);
                    }
                    inst.setInOperands(&.{frIdOp(operand)});
                    return true;
                }
            }
            return false;
        }
    }.rule;
}

fn frOpInList(comptime op: Op, comptime list: []const Op) bool {
    inline for (list) |o| {
        if (o == op) return true;
    }
    return false;
}

fn frRedundantBinaryRhs0(comptime op: Op) FoldingRule {
    comptime {
        if (!frOpInList(op, &.{ .OpBitwiseOr, .OpBitwiseXor, .OpShiftRightLogical, .OpShiftRightArithmetic, .OpShiftLeftLogical, .OpIAdd, .OpISub })) @compileError("RedundantBinaryRhs0: wrong opcode");
    }
    return frRedundantBinaryOpWithZeroOperand(1, 0);
}

fn frRedundantBinaryLhs0(comptime op: Op) FoldingRule {
    comptime {
        if (!frOpInList(op, &.{ .OpBitwiseOr, .OpBitwiseXor, .OpIAdd })) @compileError("RedundantBinaryLhs0: wrong opcode");
    }
    return frRedundantBinaryOpWithZeroOperand(0, 1);
}

fn frRedundantBinaryLhs0To0(comptime op: Op) FoldingRule {
    comptime {
        if (!frOpInList(op, &.{ .OpShiftRightLogical, .OpShiftRightArithmetic, .OpShiftLeftLogical, .OpSDiv, .OpUDiv, .OpSMod, .OpUMod })) @compileError("RedundantBinaryLhs0To0: wrong opcode");
    }
    return frRedundantBinaryOpWithZeroOperand(0, 0);
}

// (x op c1) op c2 -> x op (c1 op c2) for 32-bit commutative integer ops.
fn frReassociateCommutiveOp(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const ty: *const Type = frTypeOf(ctx, inst);
    const width: u32 = frElementWidth(ty);
    if (width != 32) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (other_inst.op == inst.op) {
        const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
        const const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
        const non_const_input: *Inst = frNonConstInput(ctx, other_constants.items[0], other_inst);
        const merged_id: u32 = frPerformOperation(cm, inst.op, const_input1, const_input2);
        if (merged_id == 0) return false;
        inst.setInOperands(&.{ frIdOp(non_const_input.resultId()), frIdOp(merged_id) });
        return true;
    }
    return false;
}

fn frReassociateCommutiveBitwise(comptime op: Op) FoldingRule {
    comptime {
        if (!frOpInList(op, &.{ .OpBitwiseOr, .OpBitwiseXor, .OpBitwiseAnd })) @compileError("ReassociateCommutiveBitwise: wrong opcode");
    }
    return frReassociateCommutiveOp;
}

fn frIsAllInt1(c: *const Constant) bool {
    if (c.isComposite()) {
        for (c.components.items) |comp| {
            if (!frIsAllInt1(comp)) return false;
        }
        return true;
    } else if (c.kind == .int) {
        return c.getSignExtendedValue() == 1;
    }
    return false;
}

// x / 1 (signed or unsigned)
fn frRedundantSUDiv(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (constants[1]) |c1| {
        if (frIsAllInt1(c1)) {
            const operand: u32 = inst.getSingleWordInOperand(0);
            const operand_type: *const Type = c1.ty;
            const inst_type: *const Type = frTypeOf(ctx, inst);
            if (inst_type.isSame(operand_type)) {
                inst.setOpcode(.OpCopyObject);
            } else {
                inst.setOpcode(.OpBitcast);
            }
            inst.setInOperands(&.{frIdOp(operand)});
            return true;
        }
    }
    return false;
}

// x % 1 (signed or unsigned) is zero
fn frRedundantSUMod(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    if (constants[1]) |c1| {
        if (frIsAllInt1(c1)) {
            const ty: *const Type = frTypeOf(ctx, inst);
            const zero_id: u32 = ctx.getConstantMgr().getNullConstId(ty);
            inst.setOpcode(.OpCopyObject);
            inst.setInOperands(&.{frIdOp(zero_id)});
            return true;
        }
    }
    return false;
}

fn frDispatchIntegerPair(state: anytype, comptime callback: anytype, lhs: *const Constant, rhs: *const Constant) void {
    const it: *const TyInteger = lhs.ty.as(.integer) orelse fatal("ForEachIntegerConstantPair: not an integer constant", .{});
    if (it.width == 32) {
        callback(state, lhs.getU32(), rhs.getU32());
    } else {
        callback(state, lhs.getU64(), rhs.getU64());
    }
}

/// ForEachIntegerConstantPair: calls `callback(state, lhs, rhs)` on the (u32 or u64) values of each component pair.
fn frForEachIntegerConstantPair(cm: *ConstMgr, input1: *const Constant, input2: *const Constant, state: anytype, comptime callback: anytype) void {
    const ty: *const Type = input1.ty;
    if (ty.as(.vector)) |vector_type| {
        const ele_type: *const Type = vector_type.element;
        var i: u32 = 0;
        while (i != vector_type.count) : (i += 1) {
            const input1_comp: *const Constant = if (input1.kind == .vector) input1.components.items[i] else cm.getConstant(ele_type, &.{}).?;
            const input2_comp: *const Constant = if (input2.kind == .vector) input2.components.items[i] else cm.getConstant(ele_type, &.{}).?;
            frDispatchIntegerPair(state, callback, input1_comp, input2_comp);
        }
    } else {
        frDispatchIntegerPair(state, callback, input1, input2);
    }
}

const FrAndOrXorState = struct { can_remove_inner: bool, can_convert_to_const: bool };

fn frAndOrXorPair(st: *FrAndOrXorState, lhs: anytype, rhs: anytype) void {
    st.can_convert_to_const = st.can_convert_to_const and ((lhs & rhs) == lhs);
    st.can_remove_inner = st.can_remove_inner and ((lhs & rhs) == 0);
}

// (x | c1) & c2 -> c2 when c2 is covered by c1; (x ^ c1) & c2 and (x | c1) & c2 -> x & c2 when c1 & c2 == 0.
fn frRedundantAndOrXor(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const ty: *const Type = frTypeOf(ctx, inst);
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (other_inst.op == .OpBitwiseOr or other_inst.op == .OpBitwiseXor) {
        const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
        const const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
        var st: FrAndOrXorState = .{ .can_remove_inner = true, .can_convert_to_const = other_inst.op == .OpBitwiseOr };
        frForEachIntegerConstantPair(cm, const_input1, const_input2, &st, frAndOrXorPair);
        if (st.can_convert_to_const) {
            const const_inst: *Inst = cm.getDefiningInstruction(const_input1, 0, null) orelse fatal("RedundantAndOrXor: could not create the constant", .{});
            inst.setOpcode(.OpCopyObject);
            inst.setInOperands(&.{frIdOp(const_inst.resultId())});
            return true;
        } else if (st.can_remove_inner) {
            const non_const_input: *Inst = frNonConstInput(ctx, other_constants.items[0], other_inst);
            const const_inst: *Inst = cm.getDefiningInstruction(const_input1, 0, null) orelse fatal("RedundantAndOrXor: could not create the constant", .{});
            inst.setInOperands(&.{ frIdOp(non_const_input.resultId()), frIdOp(const_inst.resultId()) });
            return true;
        }
    }
    return false;
}

const FrAndAddSubState = struct { can_remove_inner: bool };

/// utils::LSB: the least significant set bit of `value` as a value.
fn frLsb(value: anytype) @TypeOf(value) {
    return value & (~value +% 1);
}

fn frAndAddSubPair(st: *FrAndAddSubState, and_op: anytype, add_op: anytype) void {
    if (st.can_remove_inner) st.can_remove_inner = frLsb(add_op) > and_op;
}

// (x + c1) & c2 -> x & c2 when the low bits of c1 lie above every bit of c2 (same for subtraction of a constant).
fn frRedundantAndAddSub(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const ty: *const Type = frTypeOf(ctx, inst);
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    if (other_inst.op != .OpIAdd and other_inst.op != .OpISub) return false;
    const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
    const const_input2: *const Constant = frConstInput(other_constants.items) orelse return false;
    if (other_inst.op == .OpISub and other_constants.items[0] != null) return false;
    var st: FrAndAddSubState = .{ .can_remove_inner = true };
    frForEachIntegerConstantPair(cm, const_input1, const_input2, &st, frAndAddSubPair);
    if (st.can_remove_inner) {
        const non_const_input: *Inst = frNonConstInput(ctx, other_constants.items[0], other_inst);
        const const_inst: *Inst = cm.getDefiningInstruction(const_input1, 0, null) orelse fatal("RedundantAndAddSub: could not create the constant", .{});
        inst.setInOperands(&.{ frIdOp(non_const_input.resultId()), frIdOp(const_inst.resultId()) });
        return true;
    }
    return false;
}

fn frGetValueU64(c: ?*const Constant) ?u64 {
    const cc: *const Constant = c orelse return null;
    if (cc.ty.as(.integer) == null) return null;
    return cc.getZeroExtendedValue();
}

const FrAndShiftCtx = struct {
    width: u32,
    width_mask: u64,
    other_op: Op,

    /// can_fold_component: whether (mask op shift) is provably zero for this component; null when a value is unknown.
    fn canFoldComponent(self: *const FrAndShiftCtx, mask_const: ?*const Constant, shift_const: ?*const Constant) ?bool {
        const lhs: u64 = frGetValueU64(mask_const) orelse return null;
        const rhs: u64 = frGetValueU64(shift_const) orelse return null;
        if (rhs >= self.width) return false;
        const lhs_masked: u64 = lhs & self.width_mask;
        const sh: u6 = @intCast(rhs);
        if (self.other_op == .OpShiftRightLogical) {
            return ((lhs_masked << sh) & self.width_mask) == 0;
        }
        return ((lhs_masked >> sh) & self.width_mask) == 0;
    }
};

// (x << c1) & c2 and (x >> c1) & c2 are zero when no bit of c2 can survive the shift.
fn frRedundantAndShift(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const ty: *const Type = frTypeOf(ctx, inst);
    const width: u32 = frElementWidth(ty);
    if (width != 8 and width != 16 and width != 32 and width != 64) return false;
    const width_mask: u64 = if (width == 64) ~@as(u64, 0) else (@as(u64, 1) << @intCast(width)) - 1;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const const_input1: *const Constant = frConstInput(constants) orelse return false;
    const other_inst: *Inst = frNonConstInput(ctx, constants[0], inst);
    const other_op: Op = other_inst.op;
    if (other_op != .OpShiftLeftLogical and other_op != .OpShiftRightLogical) return false;
    const other_constants: List(?*const Constant) = cm.getOperandConstants(other_inst);
    if (other_constants.items[0] != null) return false;
    const const_input2: *const Constant = other_constants.items[1] orelse return false;
    const sctx: FrAndShiftCtx = .{ .width = width, .width_mask = width_mask, .other_op = other_op };
    if (ty.as(.vector)) |mask_vec| {
        const shift_vec: *const TyVector = const_input2.ty.as(.vector) orelse return false;
        if (shift_vec.count != mask_vec.count) return false;
        const mask_components: List(*const Constant) = const_input1.getVectorComponents(cm);
        const shift_components: List(*const Constant) = const_input2.getVectorComponents(cm);
        var i: u32 = 0;
        while (i != mask_vec.count) : (i += 1) {
            const result: bool = sctx.canFoldComponent(mask_components.items[i], shift_components.items[i]) orelse return false;
            if (!result) return false;
        }
    } else {
        if (const_input2.ty.as(.vector) != null) return false;
        const result: bool = sctx.canFoldComponent(const_input1, const_input2) orelse return false;
        if (!result) return false;
    }
    const zero_id: u32 = cm.getNullConstId(ty);
    inst.setOpcode(.OpCopyObject);
    inst.setInOperands(&.{frIdOp(zero_id)});
    return true;
}

// ---- dot product, store, shuffle, entry point and image rules ---------------------------------------------------------

// OpDot with a unit vector (one 1.0, all other components 0.0) extracts a component of the other operand.
fn frDotProductDoingExtract(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    const cm: *ConstMgr = ctx.getConstantMgr();
    if (!instIsFloatingPointFoldingAllowed(ctx, inst)) return false;
    for (0..2) |i| {
        const ci: *const Constant = constants[i] orelse continue;
        const vector_type: *const TyVector = ci.ty.as(.vector) orelse fatal("DotProductDoingExtract: OpDot input is not a vector", .{});
        const element_type: *const TyFloat = vector_type.element.as(.float) orelse fatal("DotProductDoingExtract: OpDot input is not a float vector", .{});
        const element_width: u32 = element_type.width;
        if (element_width != 32 and element_width != 64) return false;
        const components: List(*const Constant) = ci.getVectorComponents(cm);
        const not_found: u32 = std.math.maxInt(u32);
        var component_with_one: u32 = not_found;
        var all_others_zero: bool = true;
        var j: u32 = 0;
        while (j < components.len()) : (j += 1) {
            const element: *const Constant = components.items[j];
            const value: f64 = if (element_width == 32) element.getFloat() else element.getDouble();
            if (value == 0.0) {
                continue;
            } else if (value == 1.0) {
                if (component_with_one == not_found) {
                    component_with_one = j;
                } else {
                    component_with_one = not_found;
                    break;
                }
            } else {
                all_others_zero = false;
                break;
            }
        }
        if (!all_others_zero or component_with_one == not_found) continue;
        inst.setOpcode(.OpCompositeExtract);
        inst.setInOperands(&.{ frIdOp(inst.getSingleWordInOperand(1 - i)), Operand.single(.LiteralInteger, component_with_one) });
        return true;
    }
    return false;
}

const fr_store_object_in_idx: u32 = 1;

// A store of an undefined value does nothing (unless the store is volatile).
fn frStoringUndef(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    if (inst.numInOperands() == 3) {
        if ((inst.getSingleWordInOperand(2) & MemoryAccessMask.Volatile) != 0) return false;
    }
    const object_id: u32 = inst.getSingleWordInOperand(fr_store_object_in_idx);
    const object_inst: *Inst = frDefOf(ctx, object_id);
    if (object_inst.op == .OpUndef) {
        inst.toNop();
        return true;
    }
    return false;
}

// A shuffle with a shuffle as one input: flattens when only one source of the feeding shuffle is used.
fn frVectorShuffleFeedingShuffle(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const du: *DefUseMgr = ctx.getDefUseMgr();
    var feeding_shuffle_inst: *Inst = frDefOf(ctx, inst.getSingleWordInOperand(0));
    const op0_type: *const TyVector = frTypeOf(ctx, feeding_shuffle_inst).as(.vector) orelse fatal("VectorShuffleFeedingShuffle: shuffle input is not a vector", .{});
    const op0_length: u32 = op0_type.count;
    var feeder_is_op0: bool = true;
    if (feeding_shuffle_inst.op != .OpVectorShuffle) {
        feeding_shuffle_inst = frDefOf(ctx, inst.getSingleWordInOperand(1));
        feeder_is_op0 = false;
    }
    if (feeding_shuffle_inst.op != .OpVectorShuffle) return false;
    const feeder2: *Inst = frDefOf(ctx, feeding_shuffle_inst.getSingleWordInOperand(0));
    const feeder_op0_type: *const TyVector = frTypeOf(ctx, feeder2).as(.vector) orelse fatal("VectorShuffleFeedingShuffle: feeder input is not a vector", .{});
    const feeder_op0_length: u32 = feeder_op0_type.count;
    var new_feeder_id: u32 = 0;
    // new_operands[0] and [1] are the two vector ids, the rest are literal component indices
    var new_words: List(u32) = .{};
    new_words.push(0);
    new_words.push(0);
    const undef_literal: u32 = 0xffffffff;
    var op: usize = 2;
    while (op < inst.numInOperands()) : (op += 1) {
        var component_index: u32 = inst.getSingleWordInOperand(op);
        if (component_index != undef_literal and feeder_is_op0 == (component_index < op0_length)) {
            if (component_index >= op0_length) component_index -= op0_length;
            component_index = feeding_shuffle_inst.getSingleWordInOperand(@as(usize, component_index) + 2);
            if (component_index < feeder_op0_length) {
                if (new_feeder_id == 0) {
                    new_feeder_id = feeding_shuffle_inst.getSingleWordInOperand(0);
                } else if (new_feeder_id != feeding_shuffle_inst.getSingleWordInOperand(0)) {
                    return false;
                }
            } else if (component_index != undef_literal) {
                if (new_feeder_id == 0) {
                    new_feeder_id = feeding_shuffle_inst.getSingleWordInOperand(1);
                } else if (new_feeder_id != feeding_shuffle_inst.getSingleWordInOperand(1)) {
                    return false;
                }
                component_index -= feeder_op0_length;
            }
            if (!feeder_is_op0 and component_index != undef_literal) component_index += op0_length;
        }
        new_words.push(component_index);
    }
    if (new_feeder_id == 0) {
        const cm: *ConstMgr = ctx.getConstantMgr();
        const ty: *const Type = frTypeOf(ctx, feeding_shuffle_inst);
        const null_const: ?*const Constant = cm.getConstant(ty, &.{});
        new_feeder_id = frConstId(cm, null_const);
    }
    if (feeder_is_op0) {
        const new_feeder_inst: *Inst = frDefOf(ctx, new_feeder_id);
        const new_feeder_type: *const TyVector = frTypeOf(ctx, new_feeder_inst).as(.vector) orelse fatal("VectorShuffleFeedingShuffle: new feeder is not a vector", .{});
        const new_op0_size: u32 = new_feeder_type.count;
        const adjustment: u32 = op0_length -% new_op0_size;
        if (adjustment != 0) {
            var i: usize = 2;
            while (i < new_words.len()) : (i += 1) {
                const operand: u32 = inst.getSingleWordInOperand(i);
                if (operand >= op0_length and operand != undef_literal) {
                    new_words.items[i] -%= adjustment;
                }
            }
        }
        new_words.items[0] = new_feeder_id;
        new_words.items[1] = inst.getSingleWordInOperand(1);
    } else {
        new_words.items[1] = new_feeder_id;
        new_words.items[0] = inst.getSingleWordInOperand(0);
    }
    var new_operands: List(Operand) = .{};
    new_operands.push(frIdOp(new_words.items[0]));
    new_operands.push(frIdOp(new_words.items[1]));
    var k: usize = 2;
    while (k < new_words.len()) : (k += 1) new_operands.push(Operand.single(.LiteralInteger, new_words.items[k]));
    inst.setInOperands(new_operands.items);
    _ = du;
    return true;
}

// OpEntryPoint: drops repeated interface ids.
fn frRemoveRedundantOperands(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = ctx;
    _ = constants;
    var has_redundant_operand: bool = false;
    var seen_operands: Set(u32) = .{};
    var new_operands: List(Operand) = .{};
    new_operands.push(frCopyOperand(inst.getOperand(0)));
    new_operands.push(frCopyOperand(inst.getOperand(1)));
    new_operands.push(frCopyOperand(inst.getOperand(2)));
    var i: usize = 3;
    while (i < inst.numOperands()) : (i += 1) {
        if (seen_operands.insert(inst.getSingleWordOperand(i))) {
            new_operands.push(frCopyOperand(inst.getOperand(i)));
        } else {
            has_redundant_operand = true;
        }
    }
    if (!has_redundant_operand) return false;
    inst.setInOperands(new_operands.items);
    return true;
}

/// ImageOperandsMaskInOperandIndex: the in-operand index of the image operands mask, or -1.
fn frImageOperandsMaskInOperandIndex(inst: *const Inst) i32 {
    return switch (inst.op) {
        .OpImageSampleImplicitLod,
        .OpImageSampleExplicitLod,
        .OpImageSampleProjImplicitLod,
        .OpImageSampleProjExplicitLod,
        .OpImageFetch,
        .OpImageRead,
        .OpImageSparseSampleImplicitLod,
        .OpImageSparseSampleExplicitLod,
        .OpImageSparseSampleProjImplicitLod,
        .OpImageSparseSampleProjExplicitLod,
        .OpImageSparseFetch,
        .OpImageSparseRead,
        => if (inst.numOperands() > 4) 2 else -1,
        .OpImageSampleDrefImplicitLod,
        .OpImageSampleDrefExplicitLod,
        .OpImageSampleProjDrefImplicitLod,
        .OpImageSampleProjDrefExplicitLod,
        .OpImageGather,
        .OpImageDrefGather,
        .OpImageSparseSampleDrefImplicitLod,
        .OpImageSparseSampleDrefExplicitLod,
        .OpImageSparseSampleProjDrefImplicitLod,
        .OpImageSparseSampleProjDrefExplicitLod,
        .OpImageSparseGather,
        .OpImageSparseDrefGather,
        => if (inst.numOperands() > 5) 3 else -1,
        .OpImageWrite => if (inst.numOperands() > 3) 3 else -1,
        else => -1,
    };
}

// Image instructions: an Offset operand that is a constant becomes ConstOffset (or disappears when it is zero).
fn frUpdateImageOperands(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = ctx;
    const operand_index: i32 = frImageOperandsMaskInOperandIndex(inst);
    if (operand_index >= 0) {
        const oi: usize = @intCast(operand_index);
        var image_operands: u32 = inst.getSingleWordInOperand(oi);
        if ((image_operands & ImageOperandsMask.Offset) != 0) {
            var offset_operand_index: usize = oi + 1;
            if ((image_operands & ImageOperandsMask.Bias) != 0) offset_operand_index += 1;
            if ((image_operands & ImageOperandsMask.Lod) != 0) offset_operand_index += 1;
            if ((image_operands & ImageOperandsMask.Grad) != 0) offset_operand_index += 2;
            if (offset_operand_index < inst.numOperands()) {
                if (constants[offset_operand_index]) |offset_const| {
                    if (offset_const.isZero()) {
                        inst.removeInOperand(offset_operand_index);
                    } else {
                        image_operands = image_operands | ImageOperandsMask.ConstOffset;
                    }
                    image_operands = image_operands & ~ImageOperandsMask.Offset;
                    inst.setInOperand(oi, &.{image_operands});
                    return true;
                }
            }
        }
    }
    return false;
}

// ---- the folder ---------------------------------------------------------------------------------------------------

/// The instruction folder (the C++ InstructionFolder): folds an instruction to a constant, or rewrites it with the folding
/// rules, and evaluates the operations on constant words.
pub const Fold = struct {
    // ---- word-level operations (UnaryOperate / BinaryOperate / TernaryOperate / OperateWords) ----------------

    pub fn unaryOperate(opcode: Op, operand: u32) u32 {
        return switch (opcode) {
            .OpSNegate => 0 -% operand, // INT32_MIN maps to itself, like the C++
            .OpNot => ~operand,
            .OpLogicalNot => @intFromBool(operand == 0),
            .OpUConvert => operand,
            .OpSConvert => operand,
            else => 0, // C++: assert(false) then return 0
        };
    }

    pub fn binaryOperate(opcode: Op, a: u32, b: u32) u32 {
        const sa: i32 = @bitCast(a);
        const sb: i32 = @bitCast(b);
        return switch (opcode) {
            .OpShiftRightLogical => if (b >= 32) 0 else a >> @as(u5, @intCast(b)),
            .OpShiftRightArithmetic => blk: {
                if (b > 32) break :blk 0;
                if (b == 32) {
                    if (sa >= 0) break :blk 0;
                    break :blk 0xFFFFFFFF;
                }
                break :blk @as(u32, @bitCast(sa >> @as(u5, @intCast(b))));
            },
            .OpShiftLeftLogical => if (b >= 32) 0 else a << @as(u5, @intCast(b)),
            .OpBitwiseOr => a | b,
            .OpBitwiseAnd => a & b,
            .OpBitwiseXor => a ^ b,
            .OpLogicalEqual => @intFromBool((a != 0) == (b != 0)),
            .OpLogicalNotEqual => @intFromBool((a != 0) != (b != 0)),
            .OpLogicalOr => @intFromBool((a != 0) or (b != 0)),
            .OpLogicalAnd => @intFromBool((a != 0) and (b != 0)),
            .OpIEqual => @intFromBool(a == b),
            .OpINotEqual => @intFromBool(a != b),
            .OpULessThan => @intFromBool(a < b),
            .OpSLessThan => @intFromBool(sa < sb),
            .OpUGreaterThan => @intFromBool(a > b),
            .OpSGreaterThan => @intFromBool(sa > sb),
            .OpULessThanEqual => @intFromBool(a <= b),
            .OpSLessThanEqual => @intFromBool(sa <= sb),
            .OpUGreaterThanEqual => @intFromBool(a >= b),
            .OpSGreaterThanEqual => @intFromBool(sa >= sb),
            else => 0, // C++: assert(false) then return 0
        };
    }

    pub fn ternaryOperate(opcode: Op, a: u32, b: u32, c: u32) u32 {
        return switch (opcode) {
            .OpSelect => if (a != 0) b else c,
            else => 0, // C++: assert(false) then return 0
        };
    }

    pub fn operateWords(opcode: Op, operand_words: []const u32) u32 {
        return switch (operand_words.len) {
            1 => unaryOperate(opcode, operand_words[0]),
            2 => binaryOperate(opcode, operand_words[0], operand_words[1]),
            3 => ternaryOperate(opcode, operand_words[0], operand_words[1], operand_words[2]),
            else => 0, // C++: assert(false && "Invalid number of operands")
        };
    }

    // ---- scalar and vector folding -----------------------------------------------------------------------------

    /// FoldScalars: the operands are scalar or null constants (callers have checked that no operand is missing).
    pub fn foldScalars(opcode: Op, operands: []const ?*const Constant) u32 {
        // The C++ asserts IsFoldableOpcode(opcode) in debug builds only; a release build goes on and OperateWords
        // returns 0 for the opcodes it does not know. The same goes for a constant that is neither scalar nor null:
        // nothing is pushed, so OperateWords sees a shorter operand list.
        var words: List(u32) = .{};
        for (operands) |operand_opt| {
            const operand: *const Constant = operand_opt orelse fatal("FoldScalars: missing operand constant", .{});
            if (operand.isScalar()) {
                words.push(operand.words.items[0]);
            } else if (operand.isNull()) {
                words.push(0);
            }
        }
        return operateWords(opcode, words.items);
    }

    /// FoldVectors: one result word per dimension.
    pub fn foldVectors(opcode: Op, num_dims: u32, operands: []const ?*const Constant) List(u32) {
        // (C++: assert(IsFoldableOpcode) is a debug-only check; a release build folds unknown opcodes to 0.)
        var result: List(u32) = .{};
        var d: u32 = 0;
        while (d < num_dims) : (d += 1) {
            var words: List(u32) = .{};
            for (operands) |operand_opt| {
                const operand: *const Constant = operand_opt orelse fatal("FoldVectors: missing operand constant", .{});
                if (operand.kind == .vector) {
                    const component: *const Constant = operand.components.items[d];
                    if (component.isScalar()) {
                        words.push(component.words.items[0]);
                    }
                    // else: the C++ asserts (a null component of a vector constant) and, in a release build,
                    // pushes nothing, so OperateWords sees a shorter operand list. Same here.
                } else if (operand.isNull()) {
                    words.push(0);
                } else {
                    // C++: assert(false); nothing pushed
                }
            }
            result.push(operateWords(opcode, words.items));
        }
        return result;
    }

    // ---- predicates ------------------------------------------------------------------------------------------------

    pub fn isFoldableOpcode(opcode: Op) bool {
        return switch (opcode) {
            .OpBitwiseAnd,
            .OpBitwiseOr,
            .OpBitwiseXor,
            .OpIAdd,
            .OpIEqual,
            .OpIMul,
            .OpINotEqual,
            .OpISub,
            .OpLogicalAnd,
            .OpLogicalEqual,
            .OpLogicalNot,
            .OpLogicalNotEqual,
            .OpLogicalOr,
            .OpNot,
            .OpSDiv,
            .OpSelect,
            .OpSGreaterThan,
            .OpSGreaterThanEqual,
            .OpShiftLeftLogical,
            .OpShiftRightArithmetic,
            .OpShiftRightLogical,
            .OpSLessThan,
            .OpSLessThanEqual,
            .OpSMod,
            .OpSNegate,
            .OpSRem,
            .OpSConvert,
            .OpUConvert,
            .OpUDiv,
            .OpUGreaterThan,
            .OpUGreaterThanEqual,
            .OpULessThan,
            .OpULessThanEqual,
            .OpUMod,
            => true,
            else => false,
        };
    }

    pub fn isFoldableConstant(cst: *const Constant) bool {
        if (cst.isScalar()) return cst.words.len() == 1;
        return cst.isNull();
    }

    pub fn isFoldableType(ctx: *Ctx, type_inst: *Inst) bool {
        return isFoldableScalarType(type_inst) or isFoldableVectorType(ctx, type_inst);
    }

    pub fn isFoldableScalarType(type_inst: *const Inst) bool {
        if (type_inst.op == .OpTypeInt) return type_inst.getSingleWordInOperand(0) == 32;
        if (type_inst.op == .OpTypeBool) return true;
        return false;
    }

    pub fn isFoldableVectorType(ctx: *Ctx, type_inst: *const Inst) bool {
        if (type_inst.op == .OpTypeVector) {
            const component_type_id: u32 = type_inst.getSingleWordInOperand(0);
            const def_component_type: ?*Inst = ctx.getDefUseMgr().getDef(component_type_id);
            return def_component_type != null and isFoldableScalarType(def_component_type.?);
        }
        return false;
    }

    pub fn hasConstFoldingRule(ctx: *Ctx, inst: *const Inst) bool {
        return constFoldingRulesFor(ctx, inst).len != 0;
    }

    // ---- constant-operand shortcuts (FoldBinaryIntegerOpToConstant & co.) ----------------------------------------

    fn foldBinaryIntegerOpToConstant(ctx: *Ctx, inst: *Inst, id_map: anytype, comptime f: fn (@TypeOf(id_map), u32) u32, result: *u32) bool {
        const opcode: Op = inst.op;
        const cm: *ConstMgr = ctx.getConstantMgr();
        var constants: [2]?*const Constant = .{ null, null };
        for (0..2) |i| {
            const operand: *Operand = inst.getInOperand(i);
            if (operand.kind != .IdRef) return false;
            const id: u32 = f(id_map, operand.words()[0]);
            const constant: ?*const Constant = cm.findDeclaredConstant(id);
            constants[i] = if (constant != null and constant.?.kind == .int) constant else null;
        }
        const c0: ?*const Constant = constants[0];
        const c1: ?*const Constant = constants[1];
        switch (opcode) {
            .OpIMul => {
                for (constants) |c| {
                    if (c != null and c.?.isZero()) {
                        result.* = 0;
                        return true;
                    }
                }
            },
            .OpUDiv, .OpSDiv, .OpSRem, .OpSMod, .OpUMod => {
                for (constants) |c| {
                    if (c != null and c.?.isZero()) {
                        result.* = 0;
                        return true;
                    }
                }
            },
            .OpShiftRightLogical, .OpShiftLeftLogical => {
                if (c1) |c| {
                    const shift_amount: u32 = c.getU32BitValue();
                    if (shift_amount >= 32) {
                        result.* = 0;
                        return true;
                    }
                }
            },
            .OpBitwiseOr => {
                for (constants) |c| {
                    if (c) |cc| {
                        const mask: u32 = cc.getU32BitValue();
                        if (mask == 0xFFFFFFFF) {
                            result.* = 0xFFFFFFFF;
                            return true;
                        }
                    }
                }
            },
            .OpBitwiseAnd => {
                for (constants) |c| {
                    if (c) |cc| {
                        if (cc.isZero()) {
                            result.* = 0;
                            return true;
                        }
                    }
                }
            },
            .OpULessThan => {
                if (c0) |c| {
                    if (c.getU32BitValue() == 0xFFFFFFFF) {
                        result.* = 0;
                        return true;
                    }
                }
                if (c1) |c| {
                    if (c.getU32BitValue() == 0) {
                        result.* = 0;
                        return true;
                    }
                }
            },
            .OpSLessThan => {
                if (c0) |c| {
                    if (c.getS32BitValue() == std.math.maxInt(i32)) {
                        result.* = 0;
                        return true;
                    }
                }
                if (c1) |c| {
                    if (c.getS32BitValue() == std.math.minInt(i32)) {
                        result.* = 0;
                        return true;
                    }
                }
            },
            .OpUGreaterThan => {
                if (c0) |c| {
                    if (c.isZero()) {
                        result.* = 0;
                        return true;
                    }
                }
                if (c1) |c| {
                    if (c.getU32BitValue() == 0xFFFFFFFF) {
                        result.* = 0;
                        return true;
                    }
                }
            },
            .OpSGreaterThan => {
                if (c0) |c| {
                    if (c.getS32BitValue() == std.math.minInt(i32)) {
                        result.* = 0;
                        return true;
                    }
                }
                if (c1) |c| {
                    if (c.getS32BitValue() == std.math.maxInt(i32)) {
                        result.* = 0;
                        return true;
                    }
                }
            },
            .OpULessThanEqual => {
                if (c0) |c| {
                    if (c.isZero()) {
                        result.* = 1;
                        return true;
                    }
                }
                if (c1) |c| {
                    if (c.getU32BitValue() == 0xFFFFFFFF) {
                        result.* = 1;
                        return true;
                    }
                }
            },
            .OpSLessThanEqual => {
                if (c0) |c| {
                    if (c.getS32BitValue() == std.math.minInt(i32)) {
                        result.* = 1;
                        return true;
                    }
                }
                if (c1) |c| {
                    if (c.getS32BitValue() == std.math.maxInt(i32)) {
                        result.* = 1;
                        return true;
                    }
                }
            },
            .OpUGreaterThanEqual => {
                if (c0) |c| {
                    if (c.getU32BitValue() == 0xFFFFFFFF) {
                        result.* = 1;
                        return true;
                    }
                }
                if (c1) |c| {
                    if (c.getU32BitValue() == 0) {
                        result.* = 1;
                        return true;
                    }
                }
            },
            .OpSGreaterThanEqual => {
                if (c0) |c| {
                    if (c.getS32BitValue() == std.math.maxInt(i32)) {
                        result.* = 1;
                        return true;
                    }
                }
                if (c1) |c| {
                    if (c.getS32BitValue() == std.math.minInt(i32)) {
                        result.* = 1;
                        return true;
                    }
                }
            },
            else => {},
        }
        return false;
    }

    fn foldBinaryBooleanOpToConstant(ctx: *Ctx, inst: *Inst, id_map: anytype, comptime f: fn (@TypeOf(id_map), u32) u32, result: *u32) bool {
        const opcode: Op = inst.op;
        const cm: *ConstMgr = ctx.getConstantMgr();
        var constants: [2]?*const Constant = .{ null, null };
        for (0..2) |i| {
            const operand: *Operand = inst.getInOperand(i);
            if (operand.kind != .IdRef) return false;
            const id: u32 = f(id_map, operand.words()[0]);
            const constant: ?*const Constant = cm.findDeclaredConstant(id);
            constants[i] = if (constant != null and constant.?.kind == .bool_) constant else null;
        }
        switch (opcode) {
            .OpLogicalOr => {
                for (constants) |c| {
                    if (c) |cc| {
                        if (cc.boolValue()) {
                            result.* = 1;
                            return true;
                        }
                    }
                }
            },
            .OpLogicalAnd => {
                for (constants) |c| {
                    if (c) |cc| {
                        if (!cc.boolValue()) {
                            result.* = 0;
                            return true;
                        }
                    }
                }
            },
            else => {},
        }
        return false;
    }

    fn foldIntegerOpToConstant(ctx: *Ctx, inst: *Inst, id_map: anytype, comptime f: fn (@TypeOf(id_map), u32) u32, result: *u32) bool {
        check(isFoldableOpcode(inst.op), "Unhandled instruction opcode in FoldScalars");
        return switch (inst.numInOperands()) {
            2 => foldBinaryIntegerOpToConstant(ctx, inst, id_map, f, result) or
                foldBinaryBooleanOpToConstant(ctx, inst, id_map, f, result),
            else => false,
        };
    }

    // ---- the entry points ----------------------------------------------------------------------------------------

    /// FoldInstructionToConstant: the constant instruction `inst` folds to (declared in the module, created when
    /// needed), or null. `id_map` rewrites every id operand before its constant is looked up.
    pub fn foldInstructionToConstant(ctx: *Ctx, inst: *Inst, id_map: anytype, comptime f: fn (@TypeOf(id_map), u32) u32) ?*Inst {
        const cm: *ConstMgr = ctx.getConstantMgr();
        const by_scalar: bool = instIsFoldableByFoldScalar(ctx, inst);
        const by_vector: bool = instIsFoldableByFoldVector(ctx, inst);
        if (!by_scalar and !by_vector and !hasConstFoldingRule(ctx, inst)) return null;

        const Collect = struct {
            list: *List(?*const Constant),
            missing: *bool,
            cm: *ConstMgr,
            map_ctx: @TypeOf(id_map),

            fn visit(self: *const @This(), op_id: *u32) void {
                const id: u32 = f(self.map_ctx, op_id.*);
                const const_op: ?*const Constant = self.cm.findDeclaredConstant(id);
                if (const_op == null) {
                    self.list.push(null);
                    self.missing.* = true;
                } else {
                    self.list.push(const_op);
                }
            }
        };
        var constants: List(?*const Constant) = .{};
        var missing_constants: bool = false;
        const collect: Collect = .{ .list = &constants, .missing = &missing_constants, .cm = cm, .map_ctx = id_map };
        inst.forEachInId(&collect, Collect.visit);

        for (constFoldingRulesFor(ctx, inst)) |rule| {
            // C++: `if (folded_const == nullptr && inst->context()->id_overflow()) return nullptr;` -- id overflow is fatal here.
            const folded_const: ?*const Constant = rule(ctx, inst, constants.items);
            if (folded_const != null) {
                const const_inst: *Inst = cm.getDefiningInstruction(folded_const, inst.typeId(), null) orelse return null;
                ctx.updateDefUse(const_inst);
                return const_inst;
            }
        }

        var successful: bool = false;
        if (by_scalar) {
            var result_val: u32 = 0;
            if (!missing_constants) {
                result_val = foldScalars(inst.op, constants.items);
                successful = true;
            }
            if (!successful) {
                successful = foldIntegerOpToConstant(ctx, inst, id_map, f, &result_val);
            }
            if (successful) {
                const w: [1]u32 = .{result_val};
                const result_const: *const Constant = cm.getConstant(cm.getType(inst), &w) orelse return null;
                return cm.getDefiningInstruction(result_const, inst.typeId(), null);
            }
        } else if (by_vector) {
            var result_val: List(u32) = .{};
            if (!missing_constants) {
                if (ctx.getDefUseMgr().getDef(inst.typeId())) |inst_type| {
                    result_val = foldVectors(inst.op, inst_type.getSingleWordInOperand(1), constants.items);
                    successful = true;
                }
            }
            if (successful) {
                const vt: *Type = cm.getType(inst) orelse return null;
                const result_const: *const Constant = cm.getNumericVectorConstantWithWords(vt, result_val.items) orelse return null;
                return cm.getDefiningInstruction(result_const, inst.typeId(), null);
            }
        }
        return null;
    }

    fn foldInstructionInternal(ctx: *Ctx, inst: *Inst) bool {
        if (foldInstructionToConstant(ctx, inst, {}, FoldIdentityMap.map)) |folded_inst| {
            inst.setOpcode(.OpCopyObject);
            inst.setInOperands(&.{Operand.id(.IdRef, folded_inst.resultId())});
            return true;
        }
        const cm: *ConstMgr = ctx.getConstantMgr();
        const constants: List(?*const Constant) = cm.getOperandConstants(inst);
        for (foldingRulesFor(ctx, inst)) |rule| {
            if (rule(ctx, inst, constants.items)) return true;
        }
        return false;
    }

    /// FoldInstruction: folds `inst` in place until it becomes an OpCopyObject or no rule applies.
    pub fn foldInstruction(ctx: *Ctx, inst: *Inst) bool {
        var modified: bool = false;
        while (inst.op != .OpCopyObject and foldInstructionInternal(ctx, inst)) {
            modified = true;
        }
        return modified;
    }
};

const InstFoldTypeCheck = struct {
    ctx: *Ctx,
    vector: bool,

    fn visit(self: *const InstFoldTypeCheck, op_id: *u32) bool {
        const du: *DefUseMgr = self.ctx.getDefUseMgr();
        const def_inst: *Inst = du.getDef(op_id.*) orelse fatal("IsFoldableBy: operand %{d} is not defined", .{op_id.*});
        const def_inst_type: *Inst = du.getDef(def_inst.typeId()) orelse fatal("IsFoldableBy: operand %{d} has no type", .{op_id.*});
        if (self.vector) return Fold.isFoldableVectorType(self.ctx, def_inst_type);
        return Fold.isFoldableScalarType(def_inst_type);
    }
};

pub fn instIsFoldableByFoldScalar(ctx: *Ctx, inst: *Inst) bool {
    if (!Fold.isFoldableOpcode(inst.op)) return false;
    const ty: *Inst = ctx.getDefUseMgr().getDef(inst.typeId()) orelse fatal("IsFoldableByFoldScalar: instruction has no type", .{});
    if (!Fold.isFoldableScalarType(ty)) return false;
    // Even if the type of the instruction is foldable, its operands may not be (e.g. comparisons of 64-bit types).
    const chk: InstFoldTypeCheck = .{ .ctx = ctx, .vector = false };
    return inst.whileEachInId(&chk, InstFoldTypeCheck.visit);
}

pub fn instIsFoldableByFoldVector(ctx: *Ctx, inst: *Inst) bool {
    if (!Fold.isFoldableOpcode(inst.op)) return false;
    const ty: *Inst = ctx.getDefUseMgr().getDef(inst.typeId()) orelse fatal("IsFoldableByFoldVector: instruction has no type", .{});
    if (!Fold.isFoldableVectorType(ctx, ty)) return false;
    const chk: InstFoldTypeCheck = .{ .ctx = ctx, .vector = true };
    return inst.whileEachInId(&chk, InstFoldTypeCheck.visit);
}

// OpCompositeExtract of GLSL FMix whose `a` operand is 0 or 1: extracts from x or y.
fn frFMixFeedingExtract(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
    _ = constants;
    const cm: *ConstMgr = ctx.getConstantMgr();
    const composite_id: u32 = inst.getSingleWordInOperand(fr_extract_composite_id_in_idx);
    const composite_inst: *Inst = frDefOf(ctx, composite_id);
    if (composite_inst.op != .OpExtInst) return false;
    const inst_set_id: u32 = ctx.getFeatureMgr().extinst_importid_glsl_std_450;
    if (composite_inst.getSingleWordInOperand(fr_ext_inst_set_id_in_idx) != inst_set_id or
        composite_inst.getSingleWordInOperand(fr_ext_inst_instruction_in_idx) != glslNum("FMix"))
    {
        return false;
    }
    const a_id: u32 = composite_inst.getSingleWordInOperand(fr_fmix_a_id_in_idx);
    const a: *Inst = inst.clone();
    a.setInOperand(fr_extract_composite_id_in_idx, &.{a_id});
    _ = Fold.foldInstruction(ctx, a);
    if (a.op != .OpCopyObject) return false;
    const a_const: *const Constant = cm.findDeclaredConstant(a.getSingleWordInOperand(0)) orelse return false;
    const ty: *const Type = frTypeOf(ctx, inst);
    const width: u32 = frElementWidth(ty);
    if (width != 32 and width != 64) return false;
    const element_value: f64 = a_const.getValueAsDouble();
    var use_x: bool = false;
    if (element_value == 0.0) {
        use_x = true;
    } else if (element_value == 1.0) {
        use_x = false;
    } else {
        return false;
    }
    const new_vector: u32 = if (use_x) composite_inst.getSingleWordInOperand(fr_fmix_x_id_in_idx) else composite_inst.getSingleWordInOperand(fr_fmix_y_id_in_idx);
    inst.setInOperand(fr_extract_composite_id_in_idx, &.{new_vector});
    return true;
}

// op(select(c, a, b), k) -> select(c, op(a, k), op(b, k)) when a, b and k are constants.
fn frMergeBinaryOpSelect(comptime opcode: Op) FoldingRule {
    comptime {
        @setEvalBranchQuota(100000);
        var found: bool = false;
        for (fr_merge_binary_op_select_ops) |o| {
            if (o == opcode) found = true;
        }
        if (!found) @compileError("MergeBinaryOpSelect: wrong opcode");
    }
    return struct {
        fn rule(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
            const cm: *ConstMgr = ctx.getConstantMgr();
            const du: *DefUseMgr = ctx.getDefUseMgr();
            if (frConstInput(constants) == null) return false;
            const non_const: *Inst = frNonConstInput(ctx, constants[0], inst);
            if (non_const.op != .OpSelect) return false;
            const select_constants: List(?*const Constant) = cm.getOperandConstants(non_const);
            if (select_constants.items[1] == null or select_constants.items[2] == null) return false;
            // The C++ refuses scalar-condition vector selects when the target environment is older than SPIR-V 1.4;
            // this port always targets environment 1.6, so that check never fires here.
            const ir_builder = InstBuilder.init(ctx, inst, fr_builder_analyses);
            var lhs: ?*Inst = null;
            var rhs: ?*Inst = null;
            if (constants[0] != null) {
                lhs = ir_builder.addBinaryOp(inst.typeId(), opcode, inst.getSingleWordInOperand(0), non_const.getSingleWordInOperand(1));
                rhs = ir_builder.addBinaryOp(inst.typeId(), opcode, inst.getSingleWordInOperand(0), non_const.getSingleWordInOperand(2));
            } else {
                lhs = ir_builder.addBinaryOp(inst.typeId(), opcode, non_const.getSingleWordInOperand(1), inst.getSingleWordInOperand(1));
                rhs = ir_builder.addBinaryOp(inst.typeId(), opcode, non_const.getSingleWordInOperand(2), inst.getSingleWordInOperand(1));
            }
            if (lhs == null or rhs == null) return false;
            var l: *Inst = lhs.?;
            var r: *Inst = rhs.?;
            if (Fold.foldInstruction(ctx, l)) {
                ctx.analyzeDefUse(l);
                while (l.op == .OpCopyObject) {
                    l = du.getDef(l.getSingleWordInOperand(0)) orelse fatal("MergeBinaryOpSelect: dangling copy", .{});
                }
            }
            if (Fold.foldInstruction(ctx, r)) {
                ctx.analyzeDefUse(r);
                while (r.op == .OpCopyObject) {
                    r = du.getDef(r.getSingleWordInOperand(0)) orelse fatal("MergeBinaryOpSelect: dangling copy", .{});
                }
            }
            inst.setOpcode(.OpSelect);
            inst.setInOperands(&.{ frIdOp(non_const.getSingleWordInOperand(0)), frIdOp(l.resultId()), frIdOp(r.resultId()) });
            return true;
        }
    }.rule;
}

// ---------------------------------------------------------------------------------------------
// InterpFixupPass: replaces the loaded interpolant operand of the GLSL.std.450 InterpolateAt* instructions by the pointer
// that was loaded.
// ---------------------------------------------------------------------------------------------

pub const InterpFixup = struct {
    pub const name = "interp-fixup";
    pub const preserved: u32 = Analysis.instr_to_block | Analysis.decorations | Analysis.combinators | Analysis.cfg |
        Analysis.dominator | Analysis.loops | Analysis.name_map | Analysis.scalar_evolution | Analysis.register_pressure |
        Analysis.liveness | Analysis.def_use | Analysis.constants | Analysis.types;

    /// ReplaceInternalInterpolate: folding rule replacing |op(OpLoad(a),...)| by |op(a,...)| for the GLSL.std.450
    /// InterpolateAt* instructions.
    pub fn replaceInternalInterpolate(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
        _ = constants;
        const glsl450_ext_inst_id: u32 = ctx.getFeatureMgr().extinst_importid_glsl_std_450;
        check(glsl450_ext_inst_id != 0, "interp-fixup: no GLSL.std.450 import");

        const ext_opcode: u32 = inst.getSingleWordInOperand(1);

        const op1_id: u32 = inst.getSingleWordInOperand(2);

        const load_inst: *Inst = ctx.getDefUseMgr().getDef(op1_id) orelse fatal("interp-fixup: id %{d} is not defined", .{op1_id});
        if (load_inst.op != .OpLoad) return false;

        // (C++: USE_ASSERT on the base address being an Input OpVariable; no side effects.)

        const ptr_id: u32 = load_inst.getSingleWordInOperand(0);
        const op2_id: u32 = if (ext_opcode != glslNum("InterpolateAtCentroid")) inst.getSingleWordInOperand(3) else 0;

        var new_operands: List(Operand) = .{};
        new_operands.push(Operand.id(.IdRef, glsl450_ext_inst_id));
        new_operands.push(Operand.single(.LiteralExtInstInteger, ext_opcode));
        new_operands.push(Operand.id(.IdRef, ptr_id));
        if (op2_id != 0) new_operands.push(Operand.id(.IdRef, op2_id));

        inst.setInOperands(new_operands.items);
        ctx.updateDefUse(inst);
        return true;
    }

    const Visit = struct { changed: *bool, ctx: *Ctx };

    fn visit(v: Visit, inst: *Inst) void {
        if (Fold.foldInstruction(v.ctx, inst)) v.changed.* = true;
    }

    pub fn run(self: *InterpFixup, ctx: *Ctx) PassStatus {
        _ = self;
        var changed: bool = false;

        // Traverse the body of the functions to replace instructions that require the extensions.
        ctx.fold_interp = true;
        defer ctx.fold_interp = false;
        for (ctx.module.functions.items) |func| {
            func.forEachInst(Visit{ .changed = &changed, .ctx = ctx }, visit, false, false);
        }

        return if (changed) .success_with_change else .success_without_change;
    }
};

// AmdExtensionToKhrPass (--amd-ext-to-khr): replaces the instructions of the AMD shader extensions (ballot,
// trinary_minmax, gcn_shader, ...) by the equivalent KHR or core instructions. Port of source/opt/amd_ext_to_khr.cpp.
//
// The C++ pass drives an InstructionFolder that has its own folding-rule table (the AMD rules) and an EMPTY constant
// folding table, exactly like InterpFixupPass. The port uses the same mechanism: while the pass runs `ctx.fold_amd`
// is set, `constFoldingRulesFor` returns nothing and `foldingRulesFor` defers to `amdFoldingRulesFor` below. The rule
// table is keyed on the OpExtInstImport ids that exist when the folder is built (ctx.amd_ext_ids).

pub const AmdExtensionToKhr = struct {
    pub const name = "amd-ext-to-khr";
    pub const preserved: u32 = Analysis.instr_to_block | Analysis.decorations | Analysis.combinators | Analysis.cfg |
        Analysis.dominator | Analysis.loops | Analysis.name_map | Analysis.scalar_evolution | Analysis.register_pressure |
        Analysis.value_number_table | Analysis.structured_cfg | Analysis.builtin_var_id | Analysis.id_to_func |
        Analysis.types | Analysis.def_use | Analysis.constants;

    const amd_ballot_swizzle_invocations = 1;
    const amd_ballot_swizzle_invocations_masked = 2;
    const amd_ballot_write_invocation = 3;
    const amd_ballot_mbcnt = 4;

    const amd_fmin3 = 1;
    const amd_umin3 = 2;
    const amd_smin3 = 3;
    const amd_fmax3 = 4;
    const amd_umax3 = 5;
    const amd_smax3 = 6;
    const amd_fmid3 = 7;
    const amd_umid3 = 8;
    const amd_smid3 = 9;

    const amd_cube_face_index = 1;
    const amd_cube_face_coord = 2;
    const amd_time = 3;

    const builder_analyses: u32 = Analysis.def_use | Analysis.instr_to_block;

    fn getUIntType(ctx: *Ctx) ?*Type {
        const t = Type.integer(32, false);
        return ctx.getTypeMgr().getRegisteredType(&t);
    }

    /// The GLSL.std.450 import id, adding the import when the module has none.
    fn glslImportId(ctx: *Ctx) u32 {
        var id: u32 = ctx.getFeatureMgr().extinst_importid_glsl_std_450;
        if (id == 0) {
            ctx.addExtInstImport("GLSL.std.450");
            id = ctx.getFeatureMgr().extinst_importid_glsl_std_450;
        }
        return id;
    }

    fn defOf(ctx: *Ctx, id: u32) ?*Inst {
        return ctx.getDefUseMgr().getDef(id);
    }

    // ---- ReplaceTrinaryMinMax<opcode> / ReplaceTrinaryMid<min, max, clamp> -------------------------------

    pub fn replaceTrinaryMinMax(comptime opcode: u32) FoldingRule {
        return struct {
            fn f(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
                _ = constants;
                const glsl_id: u32 = glslImportId(ctx);
                const ir_builder = InstBuilder.init(ctx, inst, builder_analyses);

                const op1: u32 = inst.getSingleWordInOperand(2);
                const op2: u32 = inst.getSingleWordInOperand(3);
                const op3: u32 = inst.getSingleWordInOperand(4);

                const temp: *Inst = ir_builder.addNaryExtendedInstruction(inst.typeId(), glsl_id, opcode, &.{ op1, op2 }) orelse return false;

                const new_operands = [_]Operand{
                    Operand.id(.IdRef, glsl_id),
                    Operand.single(.LiteralExtInstInteger, opcode),
                    Operand.id(.IdRef, temp.resultId()),
                    Operand.id(.IdRef, op3),
                };
                inst.setInOperands(&new_operands);
                ctx.updateDefUse(inst);
                return true;
            }
        }.f;
    }

    pub fn replaceTrinaryMid(comptime min_opcode: u32, comptime max_opcode: u32, comptime clamp_opcode: u32) FoldingRule {
        return struct {
            fn f(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
                _ = constants;
                const glsl_id: u32 = glslImportId(ctx);
                const ir_builder = InstBuilder.init(ctx, inst, builder_analyses);

                const op1: u32 = inst.getSingleWordInOperand(2);
                const op2: u32 = inst.getSingleWordInOperand(3);
                const op3: u32 = inst.getSingleWordInOperand(4);

                const min: *Inst = ir_builder.addNaryExtendedInstruction(inst.typeId(), glsl_id, min_opcode, &.{ op2, op3 }) orelse return false;
                const max: *Inst = ir_builder.addNaryExtendedInstruction(inst.typeId(), glsl_id, max_opcode, &.{ op2, op3 }) orelse return false;

                const new_operands = [_]Operand{
                    Operand.id(.IdRef, glsl_id),
                    Operand.single(.LiteralExtInstInteger, clamp_opcode),
                    Operand.id(.IdRef, op1),
                    Operand.id(.IdRef, min.resultId()),
                    Operand.id(.IdRef, max.resultId()),
                };
                inst.setInOperands(&new_operands);
                ctx.updateDefUse(inst);
                return true;
            }
        }.f;
    }

    // ---- ReplaceGroupNonuniformOperationOpCode<new_opcode> ----------------------------------------------

    pub fn replaceGroupNonuniformOperationOpCode(comptime new_opcode: Op) FoldingRule {
        return struct {
            fn f(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
                _ = constants;
                ctx.addCapability(.GroupNonUniformArithmetic);
                inst.setOpcode(new_opcode);
                return true;
            }
        }.f;
    }

    // ---- SwizzleInvocationsAMD --------------------------------------------------------------------------

    fn replaceSwizzleInvocations(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
        _ = constants;
        const type_mgr: *TypeMgr = ctx.getTypeMgr();
        const const_mgr: *ConstMgr = ctx.getConstantMgr();

        ctx.addExtension("SPV_KHR_shader_ballot");
        ctx.addCapability(.GroupNonUniformBallot);
        ctx.addCapability(.GroupNonUniformShuffle);

        const ir_builder = InstBuilder.init(ctx, inst, builder_analyses);

        const data_id: u32 = inst.getSingleWordInOperand(2);
        const offset_id: u32 = inst.getSingleWordInOperand(3);

        // Get the subgroup invocation id.
        const var_id: u32 = ctx.getBuiltinInputVarId(@intFromEnum(BuiltIn.SubgroupLocalInvocationId));
        if (var_id == 0) return false;
        const var_inst: *Inst = defOf(ctx, var_id) orelse return false;
        const var_ptr_type: *Inst = defOf(ctx, var_inst.typeId()) orelse return false;
        const uint_type_id: u32 = var_ptr_type.getSingleWordInOperand(1);
        if (uint_type_id == 0) return false;

        const id: *Inst = ir_builder.addLoad(uint_type_id, var_id, 0) orelse return false;

        const quad_mask: u32 = ir_builder.getUintConstantId(3);
        if (quad_mask == 0) return false;

        // This gives the offset in the group of 4 of this invocation.
        const quad_idx: *Inst = ir_builder.addBinaryOp(uint_type_id, .OpBitwiseAnd, id.resultId(), quad_mask) orelse return false;

        // Get the invocation id of the first invocation in the group of 4.
        const quad_ldr: *Inst = ir_builder.addBinaryOp(uint_type_id, .OpBitwiseXor, id.resultId(), quad_idx.resultId()) orelse return false;

        // Get the offset of the target invocation from the offset vector.
        const my_offset: *Inst = ir_builder.addBinaryOp(uint_type_id, .OpVectorExtractDynamic, offset_id, quad_idx.resultId()) orelse return false;

        // Determine the index of the invocation to read from.
        const target_inv: *Inst = ir_builder.addBinaryOp(uint_type_id, .OpIAdd, quad_ldr.resultId(), my_offset.resultId()) orelse return false;

        // Do the group operations.
        const uint_max_id: u32 = ir_builder.getUintConstantId(0xFFFFFFFF);
        if (uint_max_id == 0) return false;
        const subgroup_scope: u32 = ir_builder.getUintConstantId(@intFromEnum(Scope.Subgroup));
        if (subgroup_scope == 0) return false;
        const vec_type: *Type = type_mgr.getUIntVectorType(4) orelse return false;
        const ballot_value_const: *const Constant = const_mgr.getConstant(vec_type, &.{ uint_max_id, uint_max_id, uint_max_id, uint_max_id }) orelse return false;
        const ballot_value: *Inst = const_mgr.getDefiningInstruction(ballot_value_const, 0, null) orelse return false;
        const bool_type_id: u32 = type_mgr.getBoolTypeId();
        if (bool_type_id == 0) return false;
        const is_active: *Inst = ir_builder.addNaryOp(bool_type_id, .OpGroupNonUniformBallotBitExtract, &.{ subgroup_scope, ballot_value.resultId(), target_inv.resultId() }, 0) orelse return false;
        const shuffle: *Inst = ir_builder.addNaryOp(inst.typeId(), .OpGroupNonUniformShuffle, &.{ subgroup_scope, data_id, target_inv.resultId() }, 0) orelse return false;

        // Create the null constant to use in the select.
        const result_type: *Type = type_mgr.getType(inst.typeId()) orelse return false;
        const null_c: *const Constant = const_mgr.getConstant(result_type, &.{}) orelse return false;
        const null_inst: *Inst = const_mgr.getDefiningInstruction(null_c, 0, null) orelse return false;

        // Build the select.
        inst.setOpcode(.OpSelect);
        const new_operands = [_]Operand{
            Operand.id(.IdRef, is_active.resultId()),
            Operand.id(.IdRef, shuffle.resultId()),
            Operand.id(.IdRef, null_inst.resultId()),
        };
        inst.setInOperands(&new_operands);
        ctx.updateDefUse(inst);
        return true;
    }

    // ---- SwizzleInvocationsMaskedAMD --------------------------------------------------------------------

    fn replaceSwizzleInvocationsMasked(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
        _ = constants;
        const type_mgr: *TypeMgr = ctx.getTypeMgr();
        const const_mgr: *ConstMgr = ctx.getConstantMgr();

        ctx.addCapability(.GroupNonUniformBallot);
        ctx.addCapability(.GroupNonUniformShuffle);

        const ir_builder = InstBuilder.init(ctx, inst, builder_analyses);

        // Get the operands to inst, and the components of the mask.
        const data_id: u32 = inst.getSingleWordInOperand(2);

        const mask_inst: *Inst = defOf(ctx, inst.getSingleWordInOperand(3)) orelse return false;
        // (C++ asserts: OpConstantComposite with 3 components.)

        const uint_x: u32 = mask_inst.getSingleWordInOperand(0);
        if (uint_x == 0) return false;
        const uint_y: u32 = mask_inst.getSingleWordInOperand(1);
        if (uint_y == 0) return false;
        const uint_z: u32 = mask_inst.getSingleWordInOperand(2);
        if (uint_z == 0) return false;

        // Get the subgroup invocation id.
        const var_id: u32 = ctx.getBuiltinInputVarId(@intFromEnum(BuiltIn.SubgroupLocalInvocationId));
        if (var_id == 0) return false;
        ctx.addExtension("SPV_KHR_shader_ballot");
        const var_inst: *Inst = defOf(ctx, var_id) orelse return false;
        const var_ptr_type: *Inst = defOf(ctx, var_inst.typeId()) orelse return false;
        const uint_type_id: u32 = var_ptr_type.getSingleWordInOperand(1);
        if (uint_type_id == 0) return false;

        const id: *Inst = ir_builder.addLoad(uint_type_id, var_id, 0) orelse return false;

        // Do the bitwise operations.
        const mask_extended: u32 = ir_builder.getUintConstantId(0xFFFFFFE0);
        if (mask_extended == 0) return false;
        const and_mask: *Inst = ir_builder.addBinaryOp(uint_type_id, .OpBitwiseOr, uint_x, mask_extended) orelse return false;
        const and_result: *Inst = ir_builder.addBinaryOp(uint_type_id, .OpBitwiseAnd, id.resultId(), and_mask.resultId()) orelse return false;
        const or_result: *Inst = ir_builder.addBinaryOp(uint_type_id, .OpBitwiseOr, and_result.resultId(), uint_y) orelse return false;
        const target_inv: *Inst = ir_builder.addBinaryOp(uint_type_id, .OpBitwiseXor, or_result.resultId(), uint_z) orelse return false;

        // Do the group operations.
        const uint_max_id: u32 = ir_builder.getUintConstantId(0xFFFFFFFF);
        if (uint_max_id == 0) return false;
        const subgroup_scope: u32 = ir_builder.getUintConstantId(@intFromEnum(Scope.Subgroup));
        if (subgroup_scope == 0) return false;
        const vec_type: *Type = type_mgr.getUIntVectorType(4) orelse return false;
        const ballot_value_const: *const Constant = const_mgr.getConstant(vec_type, &.{ uint_max_id, uint_max_id, uint_max_id, uint_max_id }) orelse return false;
        const ballot_value: *Inst = const_mgr.getDefiningInstruction(ballot_value_const, 0, null) orelse return false;
        const bool_type_id: u32 = type_mgr.getBoolTypeId();
        if (bool_type_id == 0) return false;
        const is_active: *Inst = ir_builder.addNaryOp(bool_type_id, .OpGroupNonUniformBallotBitExtract, &.{ subgroup_scope, ballot_value.resultId(), target_inv.resultId() }, 0) orelse return false;
        const shuffle: *Inst = ir_builder.addNaryOp(inst.typeId(), .OpGroupNonUniformShuffle, &.{ subgroup_scope, data_id, target_inv.resultId() }, 0) orelse return false;

        // Create the null constant to use in the select.
        const result_type: *Type = type_mgr.getType(inst.typeId()) orelse return false;
        const null_c: *const Constant = const_mgr.getConstant(result_type, &.{}) orelse return false;
        const null_inst: *Inst = const_mgr.getDefiningInstruction(null_c, 0, null) orelse return false;

        // Build the select.
        inst.setOpcode(.OpSelect);
        const new_operands = [_]Operand{
            Operand.id(.IdRef, is_active.resultId()),
            Operand.id(.IdRef, shuffle.resultId()),
            Operand.id(.IdRef, null_inst.resultId()),
        };
        inst.setInOperands(&new_operands);
        ctx.updateDefUse(inst);
        return true;
    }

    // ---- WriteInvocationAMD -----------------------------------------------------------------------------

    fn replaceWriteInvocation(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
        _ = constants;
        const var_id: u32 = ctx.getBuiltinInputVarId(@intFromEnum(BuiltIn.SubgroupLocalInvocationId));
        if (var_id == 0) return false;
        const var_inst: *Inst = defOf(ctx, var_id) orelse return false;
        const var_ptr_type: *Inst = defOf(ctx, var_inst.typeId()) orelse return false;
        ctx.addCapability(.SubgroupBallotKHR);
        ctx.addExtension("SPV_KHR_shader_ballot");

        const ir_builder = InstBuilder.init(ctx, inst, builder_analyses);
        const t: *Inst = ir_builder.addLoad(var_ptr_type.getSingleWordInOperand(1), var_id, 0) orelse return false;
        const bool_type = Type.simple(.bool_);
        const bool_type_id: u32 = ctx.getTypeMgr().getTypeInstruction(&bool_type);
        if (bool_type_id == 0) return false;
        const cmp: *Inst = ir_builder.addBinaryOp(bool_type_id, .OpIEqual, t.resultId(), inst.getSingleWordInOperand(4)) orelse return false;

        // Build a select.
        inst.setOpcode(.OpSelect);
        const new_operands = [_]Operand{
            Operand.id(.IdRef, cmp.resultId()),
            inst.getInOperand(3).*,
            inst.getInOperand(2).*,
        };
        inst.setInOperands(&new_operands);
        ctx.updateDefUse(inst);
        return true;
    }

    // ---- MbcntAMD ---------------------------------------------------------------------------------------

    fn replaceMbcnt(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
        _ = constants;
        const type_mgr: *TypeMgr = ctx.getTypeMgr();
        const def_use_mgr: *DefUseMgr = ctx.getDefUseMgr();

        const var_id: u32 = ctx.getBuiltinInputVarId(@intFromEnum(BuiltIn.SubgroupLtMask));
        if (var_id == 0) return false;

        ctx.addCapability(.GroupNonUniformBallot);
        const var_inst: *Inst = def_use_mgr.getDef(var_id) orelse fatal("amd-ext-to-khr: id %{d} is not defined", .{var_id});
        const var_ptr_type: *Inst = def_use_mgr.getDef(var_inst.typeId()) orelse fatal("amd-ext-to-khr: id %{d} is not defined", .{var_inst.typeId()});
        const var_type: *Inst = def_use_mgr.getDef(var_ptr_type.getSingleWordInOperand(1)) orelse fatal("amd-ext-to-khr: the pointee type is not defined", .{});
        // (C++ asserts: the variable is a vector of 4 ints.)

        // Get the type for the shuffle.
        const uint_type: *Type = getUIntType(ctx) orelse fatal("amd-ext-to-khr: cannot register the uint type", .{});
        const temp_type = Type.vector(uint_type, 2);
        const shuffle_type: *Type = type_mgr.getRegisteredType(&temp_type) orelse return false;
        const shuffle_type_id: u32 = type_mgr.getTypeInstruction(shuffle_type);

        const mask_id: u32 = inst.getSingleWordInOperand(2);
        const mask_inst: *Inst = def_use_mgr.getDef(mask_id) orelse fatal("amd-ext-to-khr: id %{d} is not defined", .{mask_id});
        // (C++ asserts: the mask is a 64-bit integer.)

        const ir_builder = InstBuilder.init(ctx, inst, builder_analyses);
        const load: *Inst = ir_builder.addLoad(var_type.resultId(), var_id, 0) orelse return false;
        const shuffle: *Inst = ir_builder.addVectorShuffle(shuffle_type_id, load.resultId(), load.resultId(), &.{ 0, 1 }) orelse return false;
        const bitcast: *Inst = ir_builder.addUnaryOp(mask_inst.typeId(), .OpBitcast, shuffle.resultId()) orelse return false;
        const t: *Inst = ir_builder.addBinaryOp(mask_inst.typeId(), .OpBitwiseAnd, bitcast.resultId(), mask_id) orelse return false;

        inst.setOpcode(.OpBitCount);
        const new_operands = [_]Operand{Operand.id(.IdRef, t.resultId())};
        inst.setInOperands(&new_operands);
        ctx.updateDefUse(inst);
        return true;
    }

    // ---- CubeFaceCoordAMD -------------------------------------------------------------------------------

    fn replaceCubeFaceCoord(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
        _ = constants;
        const type_mgr: *TypeMgr = ctx.getTypeMgr();
        const const_mgr: *ConstMgr = ctx.getConstantMgr();

        const float_type_id: u32 = type_mgr.getFloatTypeId();
        if (float_type_id == 0) return false;
        const v2_float_type: *Type = type_mgr.getFloatVectorType(2) orelse return false;
        const v2_float_type_id: u32 = type_mgr.getId(v2_float_type);
        if (v2_float_type_id == 0) return false;
        const bool_id: u32 = type_mgr.getBoolTypeId();
        if (bool_id == 0) return false;

        const ir_builder = InstBuilder.init(ctx, inst, builder_analyses);

        const input_id: u32 = inst.getSingleWordInOperand(2);
        const glsl405_ext_inst_id: u32 = glslImportId(ctx);
        if (glsl405_ext_inst_id == 0) return false;

        // Get the constants that will be used.
        const f0_const_id: u32 = const_mgr.getFloatConstId(0.0);
        if (f0_const_id == 0) return false;
        const f2_const_id: u32 = const_mgr.getFloatConstId(2.0);
        if (f2_const_id == 0) return false;
        const f0_5_const_id: u32 = const_mgr.getFloatConstId(0.5);
        if (f0_5_const_id == 0) return false;
        const vec_const: *const Constant = const_mgr.getConstant(v2_float_type, &.{ f0_5_const_id, f0_5_const_id }) orelse return false;
        const vec_const_inst: *Inst = const_mgr.getDefiningInstruction(vec_const, 0, null) orelse return false;
        const vec_const_id: u32 = vec_const_inst.resultId();

        // Extract the input values.
        const x: *Inst = ir_builder.addCompositeExtract(float_type_id, input_id, &.{0}) orelse return false;
        const y: *Inst = ir_builder.addCompositeExtract(float_type_id, input_id, &.{1}) orelse return false;
        const z: *Inst = ir_builder.addCompositeExtract(float_type_id, input_id, &.{2}) orelse return false;

        // Negate the input values.
        const nx: ?*Inst = ir_builder.addUnaryOp(float_type_id, .OpFNegate, x.resultId());
        const ny: ?*Inst = ir_builder.addUnaryOp(float_type_id, .OpFNegate, y.resultId());
        const nz: ?*Inst = ir_builder.addUnaryOp(float_type_id, .OpFNegate, z.resultId());
        if (nx == null) return false;
        if (ny == null) return false;
        if (nz == null) return false;

        // Get the absolute values of the inputs.
        const fabs: u32 = glslNum("FAbs");
        const fmax: u32 = glslNum("FMax");
        const ax: *Inst = ir_builder.addNaryExtendedInstruction(float_type_id, glsl405_ext_inst_id, fabs, &.{x.resultId()}) orelse return false;
        const ay: *Inst = ir_builder.addNaryExtendedInstruction(float_type_id, glsl405_ext_inst_id, fabs, &.{y.resultId()}) orelse return false;
        const az: *Inst = ir_builder.addNaryExtendedInstruction(float_type_id, glsl405_ext_inst_id, fabs, &.{z.resultId()}) orelse return false;

        // Find which values are negative. Used in later computations.
        const is_z_neg: *Inst = ir_builder.addBinaryOp(bool_id, .OpFOrdLessThan, z.resultId(), f0_const_id) orelse return false;
        const is_y_neg: *Inst = ir_builder.addBinaryOp(bool_id, .OpFOrdLessThan, y.resultId(), f0_const_id) orelse return false;
        const is_x_neg: *Inst = ir_builder.addBinaryOp(bool_id, .OpFOrdLessThan, x.resultId(), f0_const_id) orelse return false;

        // Compute cubema.
        const amax_x_y: *Inst = ir_builder.addNaryExtendedInstruction(float_type_id, glsl405_ext_inst_id, fmax, &.{ ax.resultId(), ay.resultId() }) orelse return false;
        const amax: *Inst = ir_builder.addNaryExtendedInstruction(float_type_id, glsl405_ext_inst_id, fmax, &.{ az.resultId(), amax_x_y.resultId() }) orelse return false;
        const cubema: *Inst = ir_builder.addBinaryOp(float_type_id, .OpFMul, f2_const_id, amax.resultId()) orelse return false;

        // Do the comparisons needed for computing cubesc and cubetc.
        const is_z_max: *Inst = ir_builder.addBinaryOp(bool_id, .OpFOrdGreaterThanEqual, az.resultId(), amax_x_y.resultId()) orelse return false;
        const not_is_z_max: *Inst = ir_builder.addUnaryOp(bool_id, .OpLogicalNot, is_z_max.resultId()) orelse return false;
        const y_gr_x: *Inst = ir_builder.addBinaryOp(bool_id, .OpFOrdGreaterThanEqual, ay.resultId(), ax.resultId()) orelse return false;
        const is_y_max: *Inst = ir_builder.addBinaryOp(bool_id, .OpLogicalAnd, not_is_z_max.resultId(), y_gr_x.resultId()) orelse return false;

        // Select the correct value for cubesc.
        const cubesc_case_1: *Inst = ir_builder.addSelect(float_type_id, is_z_neg.resultId(), nx.?.resultId(), x.resultId()) orelse return false;
        const cubesc_case_2: *Inst = ir_builder.addSelect(float_type_id, is_x_neg.resultId(), z.resultId(), nz.?.resultId()) orelse return false;
        const sel: *Inst = ir_builder.addSelect(float_type_id, is_y_max.resultId(), x.resultId(), cubesc_case_2.resultId()) orelse return false;
        const cubesc: *Inst = ir_builder.addSelect(float_type_id, is_z_max.resultId(), cubesc_case_1.resultId(), sel.resultId()) orelse return false;

        // Select the correct value for cubetc.
        const cubetc_case_1: *Inst = ir_builder.addSelect(float_type_id, is_y_neg.resultId(), nz.?.resultId(), z.resultId()) orelse return false;
        const cubetc: *Inst = ir_builder.addSelect(float_type_id, is_y_max.resultId(), cubetc_case_1.resultId(), ny.?.resultId()) orelse return false;

        // Do the division.
        const cube: *Inst = ir_builder.addCompositeConstruct(v2_float_type_id, &.{ cubesc.resultId(), cubetc.resultId() }) orelse return false;
        const denom: *Inst = ir_builder.addCompositeConstruct(v2_float_type_id, &.{ cubema.resultId(), cubema.resultId() }) orelse return false;
        const div: *Inst = ir_builder.addBinaryOp(v2_float_type_id, .OpFDiv, cube.resultId(), denom.resultId()) orelse return false;

        // Get the final result by adding 0.5 to |div|.
        inst.setOpcode(.OpFAdd);
        const new_operands = [_]Operand{
            Operand.id(.IdRef, div.resultId()),
            Operand.id(.IdRef, vec_const_id),
        };
        inst.setInOperands(&new_operands);
        ctx.updateDefUse(inst);
        return true;
    }

    // ---- CubeFaceIndexAMD -------------------------------------------------------------------------------

    fn replaceCubeFaceIndex(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
        _ = constants;
        const type_mgr: *TypeMgr = ctx.getTypeMgr();
        const const_mgr: *ConstMgr = ctx.getConstantMgr();

        const float_type_id: u32 = type_mgr.getFloatTypeId();
        if (float_type_id == 0) return false;
        const bool_id: u32 = type_mgr.getBoolTypeId();
        if (bool_id == 0) return false;

        const ir_builder = InstBuilder.init(ctx, inst, builder_analyses);

        const input_id: u32 = inst.getSingleWordInOperand(2);
        // (C++ does not check the import id here.)
        const glsl405_ext_inst_id: u32 = glslImportId(ctx);

        // Get the constants that will be used.
        const f0_const_id: u32 = const_mgr.getFloatConstId(0.0);
        if (f0_const_id == 0) return false;
        const f1_const_id: u32 = const_mgr.getFloatConstId(1.0);
        if (f1_const_id == 0) return false;
        const f2_const_id: u32 = const_mgr.getFloatConstId(2.0);
        if (f2_const_id == 0) return false;
        const f3_const_id: u32 = const_mgr.getFloatConstId(3.0);
        if (f3_const_id == 0) return false;
        const f4_const_id: u32 = const_mgr.getFloatConstId(4.0);
        if (f4_const_id == 0) return false;
        const f5_const_id: u32 = const_mgr.getFloatConstId(5.0);
        if (f5_const_id == 0) return false;

        // Extract the input values.
        const x: *Inst = ir_builder.addCompositeExtract(float_type_id, input_id, &.{0}) orelse return false;
        const y: *Inst = ir_builder.addCompositeExtract(float_type_id, input_id, &.{1}) orelse return false;
        const z: *Inst = ir_builder.addCompositeExtract(float_type_id, input_id, &.{2}) orelse return false;

        // Get the absolute values of the inputs.
        const fabs: u32 = glslNum("FAbs");
        const fmax: u32 = glslNum("FMax");
        const ax: *Inst = ir_builder.addNaryExtendedInstruction(float_type_id, glsl405_ext_inst_id, fabs, &.{x.resultId()}) orelse return false;
        const ay: *Inst = ir_builder.addNaryExtendedInstruction(float_type_id, glsl405_ext_inst_id, fabs, &.{y.resultId()}) orelse return false;
        const az: *Inst = ir_builder.addNaryExtendedInstruction(float_type_id, glsl405_ext_inst_id, fabs, &.{z.resultId()}) orelse return false;

        // Find which values are negative. Used in later computations.
        const is_z_neg: *Inst = ir_builder.addBinaryOp(bool_id, .OpFOrdLessThan, z.resultId(), f0_const_id) orelse return false;
        const is_y_neg: *Inst = ir_builder.addBinaryOp(bool_id, .OpFOrdLessThan, y.resultId(), f0_const_id) orelse return false;
        const is_x_neg: *Inst = ir_builder.addBinaryOp(bool_id, .OpFOrdLessThan, x.resultId(), f0_const_id) orelse return false;

        // Find the max value.
        const amax_x_y: *Inst = ir_builder.addNaryExtendedInstruction(float_type_id, glsl405_ext_inst_id, fmax, &.{ ax.resultId(), ay.resultId() }) orelse return false;
        const is_z_max: *Inst = ir_builder.addBinaryOp(bool_id, .OpFOrdGreaterThanEqual, az.resultId(), amax_x_y.resultId()) orelse return false;
        const y_gr_x: *Inst = ir_builder.addBinaryOp(bool_id, .OpFOrdGreaterThanEqual, ay.resultId(), ax.resultId()) orelse return false;

        // Get the value for each case.
        const case_z: *Inst = ir_builder.addSelect(float_type_id, is_z_neg.resultId(), f5_const_id, f4_const_id) orelse return false;
        const case_y: *Inst = ir_builder.addSelect(float_type_id, is_y_neg.resultId(), f3_const_id, f2_const_id) orelse return false;
        const case_x: *Inst = ir_builder.addSelect(float_type_id, is_x_neg.resultId(), f1_const_id, f0_const_id) orelse return false;

        // Select the correct case.
        const sel: *Inst = ir_builder.addSelect(float_type_id, y_gr_x.resultId(), case_y.resultId(), case_x.resultId()) orelse return false;

        // Build the final select.
        inst.setOpcode(.OpSelect);
        const new_operands = [_]Operand{
            Operand.id(.IdRef, is_z_max.resultId()),
            Operand.id(.IdRef, case_z.resultId()),
            Operand.id(.IdRef, sel.resultId()),
        };
        inst.setInOperands(&new_operands);
        ctx.updateDefUse(inst);
        return true;
    }

    // ---- TimeAMD ----------------------------------------------------------------------------------------

    fn replaceTimeAmd(ctx: *Ctx, inst: *Inst, constants: []const ?*const Constant) bool {
        _ = constants;
        const ir_builder = InstBuilder.init(ctx, inst, builder_analyses);
        ctx.addExtension("SPV_KHR_shader_clock");
        ctx.addCapability(.ShaderClockKHR);

        inst.setOpcode(.OpReadClockKHR);
        const subgroup_scope_id: u32 = ir_builder.getUintConstantId(@intFromEnum(Scope.Subgroup));
        const args = [_]Operand{Operand.id(.IdRef, subgroup_scope_id)};
        inst.setInOperands(&args);
        ctx.updateDefUse(inst);

        return true;
    }

    // ---- the rule table (AmdExtFoldingRules::AddFoldingRules) -------------------------------------------

    pub fn foldingRulesFor(ctx: *Ctx, inst: *const Inst) []const FoldingRule {
        if (inst.op != .OpExtInst) {
            return switch (inst.op) {
                .OpGroupIAddNonUniformAMD => comptime &[_]FoldingRule{replaceGroupNonuniformOperationOpCode(.OpGroupNonUniformIAdd)},
                .OpGroupFAddNonUniformAMD => comptime &[_]FoldingRule{replaceGroupNonuniformOperationOpCode(.OpGroupNonUniformFAdd)},
                .OpGroupUMinNonUniformAMD => comptime &[_]FoldingRule{replaceGroupNonuniformOperationOpCode(.OpGroupNonUniformUMin)},
                .OpGroupSMinNonUniformAMD => comptime &[_]FoldingRule{replaceGroupNonuniformOperationOpCode(.OpGroupNonUniformSMin)},
                .OpGroupFMinNonUniformAMD => comptime &[_]FoldingRule{replaceGroupNonuniformOperationOpCode(.OpGroupNonUniformFMin)},
                .OpGroupUMaxNonUniformAMD => comptime &[_]FoldingRule{replaceGroupNonuniformOperationOpCode(.OpGroupNonUniformUMax)},
                .OpGroupSMaxNonUniformAMD => comptime &[_]FoldingRule{replaceGroupNonuniformOperationOpCode(.OpGroupNonUniformSMax)},
                .OpGroupFMaxNonUniformAMD => comptime &[_]FoldingRule{replaceGroupNonuniformOperationOpCode(.OpGroupNonUniformFMax)},
                else => &.{},
            };
        }

        const set_id: u32 = inst.getSingleWordInOperand(0);
        const num: u32 = inst.getSingleWordInOperand(1);
        if (ctx.amd_ext_ids[0] != 0 and set_id == ctx.amd_ext_ids[0]) {
            return switch (num) {
                amd_ballot_swizzle_invocations => comptime &[_]FoldingRule{replaceSwizzleInvocations},
                amd_ballot_swizzle_invocations_masked => comptime &[_]FoldingRule{replaceSwizzleInvocationsMasked},
                amd_ballot_write_invocation => comptime &[_]FoldingRule{replaceWriteInvocation},
                amd_ballot_mbcnt => comptime &[_]FoldingRule{replaceMbcnt},
                else => &.{},
            };
        }
        if (ctx.amd_ext_ids[1] != 0 and set_id == ctx.amd_ext_ids[1]) {
            return switch (num) {
                amd_fmin3 => comptime &[_]FoldingRule{replaceTrinaryMinMax(glslNum("FMin"))},
                amd_umin3 => comptime &[_]FoldingRule{replaceTrinaryMinMax(glslNum("UMin"))},
                amd_smin3 => comptime &[_]FoldingRule{replaceTrinaryMinMax(glslNum("SMin"))},
                amd_fmax3 => comptime &[_]FoldingRule{replaceTrinaryMinMax(glslNum("FMax"))},
                amd_umax3 => comptime &[_]FoldingRule{replaceTrinaryMinMax(glslNum("UMax"))},
                amd_smax3 => comptime &[_]FoldingRule{replaceTrinaryMinMax(glslNum("SMax"))},
                amd_fmid3 => comptime &[_]FoldingRule{replaceTrinaryMid(glslNum("FMin"), glslNum("FMax"), glslNum("FClamp"))},
                amd_umid3 => comptime &[_]FoldingRule{replaceTrinaryMid(glslNum("UMin"), glslNum("UMax"), glslNum("UClamp"))},
                amd_smid3 => comptime &[_]FoldingRule{replaceTrinaryMid(glslNum("SMin"), glslNum("SMax"), glslNum("SClamp"))},
                else => &.{},
            };
        }
        if (ctx.amd_ext_ids[2] != 0 and set_id == ctx.amd_ext_ids[2]) {
            return switch (num) {
                amd_cube_face_coord => comptime &[_]FoldingRule{replaceCubeFaceCoord},
                amd_cube_face_index => comptime &[_]FoldingRule{replaceCubeFaceIndex},
                amd_time => comptime &[_]FoldingRule{replaceTimeAmd},
                else => &.{},
            };
        }
        return &.{};
    }

    // ---- the pass ---------------------------------------------------------------------------------------

    const Visit = struct { changed: *bool, ctx: *Ctx };

    fn visit(v: Visit, inst: *Inst) void {
        if (Fold.foldInstruction(v.ctx, inst)) v.changed.* = true;
    }

    fn isRemovedName(s: []const u8) bool {
        return std.mem.eql(u8, s, "SPV_AMD_shader_ballot") or std.mem.eql(u8, s, "SPV_AMD_shader_trinary_minmax") or
            std.mem.eql(u8, s, "SPV_AMD_gcn_shader");
    }

    pub fn run(self: *AmdExtensionToKhr, ctx: *Ctx) PassStatus {
        _ = self;
        var changed: bool = false;

        // The folder is built here: the rules are keyed on the import ids that exist now.
        ctx.amd_ext_ids = .{
            ctx.module.getExtInstImportId("SPV_AMD_shader_ballot"),
            ctx.module.getExtInstImportId("SPV_AMD_shader_trinary_minmax"),
            ctx.module.getExtInstImportId("SPV_AMD_gcn_shader"),
        };
        ctx.fold_amd = true;
        defer ctx.fold_amd = false;

        // Traverse the body of the functions to replace instructions that require the extensions.
        for (ctx.module.functions.items) |func| {
            func.forEachInst(Visit{ .changed = &changed, .ctx = ctx }, visit, false, false);
        }

        // Now that instructions that require the extensions have been removed, remove the extension instructions.
        var to_be_killed: List(*Inst) = .{};
        var ex: ?*Inst = ctx.module.extensions.first;
        while (ex) |inst| : (ex = inst.next) {
            if (inst.op == .OpExtension) {
                if (isRemovedName(inst.getInOperand(0).asString())) to_be_killed.push(inst);
            }
        }
        var im: ?*Inst = ctx.module.ext_inst_imports.first;
        while (im) |inst| : (im = inst.next) {
            if (inst.op == .OpExtInstImport) {
                if (isRemovedName(inst.getInOperand(0).asString())) to_be_killed.push(inst);
            }
        }
        for (to_be_killed.items) |inst| {
            _ = ctx.killInst(inst);
            changed = true;
        }

        // The replacements use instructions that are missing before SPIR-V 1.3: make sure the version is at least 1.3.
        if (changed) {
            if (ctx.module.header.version < 0x00010300) ctx.module.header.version = 0x00010300;
        }
        return if (changed) .success_with_change else .success_without_change;
    }
};

// ---- the rule table (FoldingRules::AddFoldingRules) ---------------------------------------------------------------------
//
// The C++ builds `rules_[opcode]` by pushing rules in a fixed order: first the loops over the op arrays
// (RedundantBinaryRhs0, RedundantBinaryLhs0, RedundantBinaryLhs0To0, ReassociateCommutiveBitwise,
// ReassociateNestedGenericInt, MergeBinaryOpSelect), then the single registrations. The lists below are those
// sequences flattened per opcode, in that order.

pub fn foldingRulesFor(ctx: *Ctx, inst: *const Inst) []const FoldingRule {
    if (ctx.fold_amd) return AmdExtensionToKhr.foldingRulesFor(ctx, inst);
    if (ctx.fold_interp) {
        // InterpFoldingRules: only the three InterpolateAt* rules, keyed on the GLSL.std.450 import id at construction.
        if (inst.op != .OpExtInst) return &.{};
        const glsl_id: u32 = ctx.getFeatureMgr().extinst_importid_glsl_std_450;
        if (glsl_id == 0 or inst.getSingleWordInOperand(0) != glsl_id) return &.{};
        const num: u32 = inst.getSingleWordInOperand(1);
        if (num == glslNum("InterpolateAtCentroid") or num == glslNum("InterpolateAtSample") or num == glslNum("InterpolateAtOffset")) {
            return comptime &[_]FoldingRule{InterpFixup.replaceInternalInterpolate};
        }
        return &.{};
    }
    if (inst.op == .OpExtInst) {
        // the C++ registers FMix under the GLSL.std.450 import id seen when the folder was built (0: none)
        const glsl_id: u32 = foldGlslId(ctx);
        if (glsl_id != 0 and inst.getSingleWordInOperand(0) == glsl_id and inst.getSingleWordInOperand(1) == glslNum("FMix")) {
            return comptime &[_]FoldingRule{frRedundantFMix};
        }
        return &.{};
    }
    return switch (inst.op) {
        .OpBitwiseOr => comptime &[_]FoldingRule{
            frRedundantBinaryRhs0(.OpBitwiseOr),
            frRedundantBinaryLhs0(.OpBitwiseOr),
            frReassociateCommutiveBitwise(.OpBitwiseOr),
            frReassociateNestedGenericInt(.OpBitwiseOr),
            frMergeBinaryOpSelect(.OpBitwiseOr),
        },
        .OpBitwiseXor => comptime &[_]FoldingRule{
            frRedundantBinaryRhs0(.OpBitwiseXor),
            frRedundantBinaryLhs0(.OpBitwiseXor),
            frReassociateCommutiveBitwise(.OpBitwiseXor),
            frReassociateNestedGenericInt(.OpBitwiseXor),
            frMergeBinaryOpSelect(.OpBitwiseXor),
        },
        .OpBitwiseAnd => comptime &[_]FoldingRule{
            frReassociateCommutiveBitwise(.OpBitwiseAnd),
            frReassociateNestedGenericInt(.OpBitwiseAnd),
            frMergeBinaryOpSelect(.OpBitwiseAnd),
            frRedundantAndOrXor,
            frRedundantAndAddSub,
            frRedundantAndShift,
        },
        .OpShiftRightLogical => comptime &[_]FoldingRule{
            frRedundantBinaryRhs0(.OpShiftRightLogical),
            frRedundantBinaryLhs0To0(.OpShiftRightLogical),
            frMergeBinaryOpSelect(.OpShiftRightLogical),
        },
        .OpShiftRightArithmetic => comptime &[_]FoldingRule{
            frRedundantBinaryRhs0(.OpShiftRightArithmetic),
            frRedundantBinaryLhs0To0(.OpShiftRightArithmetic),
            frMergeBinaryOpSelect(.OpShiftRightArithmetic),
        },
        .OpShiftLeftLogical => comptime &[_]FoldingRule{
            frRedundantBinaryRhs0(.OpShiftLeftLogical),
            frRedundantBinaryLhs0To0(.OpShiftLeftLogical),
            frMergeBinaryOpSelect(.OpShiftLeftLogical),
        },
        .OpIAdd => comptime &[_]FoldingRule{
            frRedundantBinaryRhs0(.OpIAdd),
            frRedundantBinaryLhs0(.OpIAdd),
            frMergeBinaryOpSelect(.OpIAdd),
            frMergeAddNegateArithmetic,
            frMergeAddAddArithmetic,
            frMergeAddSubArithmetic,
            frMergeGenericAddSubArithmetic,
            frReassociateNestedAddSub,
            frFactorAddSubMuls,
        },
        .OpISub => comptime &[_]FoldingRule{
            frRedundantBinaryRhs0(.OpISub),
            frMergeBinaryOpSelect(.OpISub),
            frMergeSubNegateArithmetic,
            frMergeSubAddArithmetic,
            frMergeSubSubArithmetic,
            frReassociateNestedAddSub,
            frFactorAddSubMuls,
        },
        .OpIMul => comptime &[_]FoldingRule{
            frReassociateNestedGenericInt(.OpIMul),
            frMergeBinaryOpSelect(.OpIMul),
            frIntMultipleBy1,
            frMergeMulMulArithmetic,
            frMergeMulNegateArithmetic,
            frMergeDivMulDoubleNegative,
        },
        .OpSDiv => comptime &[_]FoldingRule{
            frRedundantBinaryLhs0To0(.OpSDiv),
            frMergeBinaryOpSelect(.OpSDiv),
            frRedundantSUDiv,
            frMergeDivMulDoubleNegative,
        },
        .OpUDiv => comptime &[_]FoldingRule{
            frRedundantBinaryLhs0To0(.OpUDiv),
            frMergeBinaryOpSelect(.OpUDiv),
            frRedundantSUDiv,
        },
        .OpSMod => comptime &[_]FoldingRule{
            frRedundantBinaryLhs0To0(.OpSMod),
            frRedundantSUMod,
        },
        .OpUMod => comptime &[_]FoldingRule{
            frRedundantBinaryLhs0To0(.OpUMod),
            frRedundantSUMod,
        },
        .OpFAdd => comptime &[_]FoldingRule{
            frMergeBinaryOpSelect(.OpFAdd),
            frRedundantFAdd,
            frMergeAddNegateArithmetic,
            frMergeAddAddArithmetic,
            frMergeAddSubArithmetic,
            frMergeGenericAddSubArithmetic,
            frReassociateNestedAddSub,
            frFactorAddSubMuls,
        },
        .OpFSub => comptime &[_]FoldingRule{
            frMergeBinaryOpSelect(.OpFSub),
            frRedundantFSub,
            frMergeSubNegateArithmetic,
            frMergeSubAddArithmetic,
            frMergeSubSubArithmetic,
            frReassociateNestedAddSub,
            frFactorAddSubMuls,
        },
        .OpFMul => comptime &[_]FoldingRule{
            frMergeBinaryOpSelect(.OpFMul),
            frRedundantFMul,
            frMergeMulMulArithmetic,
            frMergeMulDivArithmetic,
            frMergeMulNegateArithmetic,
            frMergeDivMulDoubleNegative,
            frReassociateNestedMulDivFloat,
        },
        .OpFDiv => comptime &[_]FoldingRule{
            frMergeBinaryOpSelect(.OpFDiv),
            frRedundantFDiv,
            frReciprocalFDiv,
            frMergeDivDivArithmetic,
            frMergeDivMulArithmetic,
            frMergeDivNegateArithmetic,
            frMergeDivMulDoubleNegative,
            frReassociateNestedMulDivFloat,
        },
        .OpFMod => comptime &[_]FoldingRule{frRedundantFMod},
        .OpVectorTimesScalar => comptime &[_]FoldingRule{
            frMergeBinaryOpSelect(.OpVectorTimesScalar),
            frMergeDivMulDoubleNegative,
        },
        .OpFNegate => comptime &[_]FoldingRule{
            frMergeNegateArithmetic,
            frMergeNegateAddSubArithmetic,
            frMergeNegateMulDivArithmetic,
        },
        .OpSNegate => comptime &[_]FoldingRule{
            frMergeNegateArithmetic,
            frMergeNegateMulDivArithmetic,
            frMergeNegateAddSubArithmetic,
        },
        .OpLogicalEqual => comptime &[_]FoldingRule{
            frMergeBinaryOpSelect(.OpLogicalEqual),
            frRedundantLogicalEqual,
        },
        .OpLogicalNotEqual => comptime &[_]FoldingRule{
            frMergeBinaryOpSelect(.OpLogicalNotEqual),
            frRedundantLogicalEqual,
        },
        .OpLogicalAnd => comptime &[_]FoldingRule{
            frMergeBinaryOpSelect(.OpLogicalAnd),
            frRedundantLogicalAnd,
        },
        .OpLogicalOr => comptime &[_]FoldingRule{
            frMergeBinaryOpSelect(.OpLogicalOr),
            frRedundantLogicalOr,
        },
        .OpLogicalNot => comptime &[_]FoldingRule{
            frRedundantLogicalNot,
            frFoldLogicalNotComparison,
        },
        // the remaining ops of MergeBinaryOpSelectOps have no other rule
        inline .OpIEqual,
        .OpINotEqual,
        .OpUGreaterThan,
        .OpSGreaterThan,
        .OpUGreaterThanEqual,
        .OpSGreaterThanEqual,
        .OpULessThan,
        .OpSLessThan,
        .OpULessThanEqual,
        .OpSLessThanEqual,
        .OpFOrdEqual,
        .OpFUnordEqual,
        .OpFOrdNotEqual,
        .OpFUnordNotEqual,
        .OpFOrdLessThan,
        .OpFUnordLessThan,
        .OpFOrdGreaterThan,
        .OpFUnordGreaterThan,
        .OpFOrdLessThanEqual,
        .OpFUnordLessThanEqual,
        .OpFOrdGreaterThanEqual,
        .OpFUnordGreaterThanEqual,
        => |op| comptime &[_]FoldingRule{frMergeBinaryOpSelect(op)},
        .OpBitcast => comptime &[_]FoldingRule{ frBitCastScalarOrVector, frRedundantBitcast },
        .OpBitReverse => comptime &[_]FoldingRule{frBitReverseScalarOrVector},
        .OpCompositeConstruct => comptime &[_]FoldingRule{frCompositeExtractFeedingConstruct},
        .OpCopyLogical => comptime &[_]FoldingRule{frCompositeConstructFeedingCopyLogical},
        .OpCompositeExtract => comptime &[_]FoldingRule{
            frInsertFeedingExtract,
            frCompositeConstructFeedingExtract,
            frVectorShuffleFeedingExtract,
            frFMixFeedingExtract,
            frCopyLogicalFeedingExtract,
            frLoadFeedingExtract,
        },
        .OpCompositeInsert => comptime &[_]FoldingRule{frCompositeInsertToCompositeConstruct},
        .OpDot => comptime &[_]FoldingRule{frDotProductDoingExtract},
        .OpEntryPoint => comptime &[_]FoldingRule{frRemoveRedundantOperands},
        .OpPhi => comptime &[_]FoldingRule{frRedundantPhi},
        .OpSelect => comptime &[_]FoldingRule{ frRedundantSelect, frFoldConstantBooleanSelect },
        .OpStore => comptime &[_]FoldingRule{frStoringUndef},
        .OpVectorShuffle => comptime &[_]FoldingRule{frVectorShuffleFeedingShuffle},
        .OpImageSampleImplicitLod,
        .OpImageSampleExplicitLod,
        .OpImageSampleDrefImplicitLod,
        .OpImageSampleDrefExplicitLod,
        .OpImageSampleProjImplicitLod,
        .OpImageSampleProjExplicitLod,
        .OpImageSampleProjDrefImplicitLod,
        .OpImageSampleProjDrefExplicitLod,
        .OpImageFetch,
        .OpImageGather,
        .OpImageDrefGather,
        .OpImageRead,
        .OpImageWrite,
        .OpImageSparseSampleImplicitLod,
        .OpImageSparseSampleExplicitLod,
        .OpImageSparseSampleDrefImplicitLod,
        .OpImageSparseSampleDrefExplicitLod,
        .OpImageSparseSampleProjImplicitLod,
        .OpImageSparseSampleProjExplicitLod,
        .OpImageSparseSampleProjDrefImplicitLod,
        .OpImageSparseSampleProjDrefExplicitLod,
        .OpImageSparseFetch,
        .OpImageSparseGather,
        .OpImageSparseDrefGather,
        .OpImageSparseRead,
        => comptime &[_]FoldingRule{frUpdateImageOperands},
        else => &.{},
    };
}

// ---- SSAPropagator (propagator.h / propagator.cpp) ----------------------------------------------------
//
// The sparse conditional propagation engine that CCP is built on. The C++ class stores a std::function
// visitor; here the visitor is a comptime callback given to `run` together with a
// context value, and receives the propagator so it can call setStatus/hasStatus/status/isPhiArgExecutable.
//
// Edge executability is keyed on (source id, dest id): the C++ std::set<Edge> orders and compares edges by
// those two ids only. The pseudo entry block has id 0 and the pseudo exit block id `max_result_id`.
// bb_preds_ of the C++ class is write-only and therefore not kept.

/// The lattice values of the C++ enum SSAPropagator::PropStatus (declaration order is the lattice order).
pub const PropStatus = enum(u8) { not_interesting, interesting, varying, failed };

pub const PropEdge = struct {
    source: *Block,
    dest: *Block,
};

fn spEdgeKey(source: *const Block, dest: *const Block) u64 {
    return (@as(u64, source.id()) << 32) | @as(u64, dest.id());
}

/// The sparse SSA propagation engine (Wegman-Zadeck style) behind CCP: it simulates blocks and SSA edges until no
/// status changes.
pub const SsaPropagator = struct {
    ctx: *Ctx,
    ssa_edge_uses: Queue(*Inst) = .{},
    blocks: Queue(*Block) = .{},
    simulated_blocks: Set(*Block) = .{},
    do_not_simulate: Set(*Inst) = .{},
    bb_succs: Map(*Block, List(PropEdge)) = .{},
    executable_edges: Set(u64) = .{},
    statuses: Map(*Inst, PropStatus) = .{},

    pub fn init(ctx: *Ctx) SsaPropagator {
        return .{ .ctx = ctx };
    }

    // ---- status table ----------------------------------------------------------------------------

    pub fn hasStatus(self: *const SsaPropagator, inst: *const Inst) bool {
        return self.statuses.contains(@constCast(inst));
    }

    pub fn status(self: *const SsaPropagator, inst: *const Inst) PropStatus {
        return self.statuses.get(@constCast(inst)) orelse
            fatal("SsaPropagator.status: instruction (result id {d}) has no status", .{inst.resultId()});
    }

    /// Returns true when the stored status changed (or was newly set). The C++ lattice-order assert is
    /// not reproduced (a release build does not check it).
    pub fn setStatus(self: *SsaPropagator, inst: *Inst, new_status: PropStatus) bool {
        const r: Map(*Inst, PropStatus).GetOrPutResult = self.statuses.getOrPut(inst);
        if (!r.found_existing) {
            r.value_ptr.* = new_status;
            return true;
        }
        if (r.value_ptr.* != new_status) {
            r.value_ptr.* = new_status;
            return true;
        }
        return false;
    }

    // ---- small predicates ------------------------------------------------------------------------

    fn shouldSimulateAgain(self: *const SsaPropagator, instr: *const Inst) bool {
        return !self.do_not_simulate.contains(@constCast(instr));
    }

    fn dontSimulateAgain(self: *SsaPropagator, instr: *Inst) void {
        _ = self.do_not_simulate.insert(instr);
    }

    fn blockHasBeenSimulated(self: *const SsaPropagator, block: *const Block) bool {
        return self.simulated_blocks.contains(@constCast(block));
    }

    fn markBlockSimulated(self: *SsaPropagator, block: *Block) void {
        _ = self.simulated_blocks.insert(block);
    }

    fn markEdgeExecutable(self: *SsaPropagator, edge: PropEdge) bool {
        return self.executable_edges.insert(spEdgeKey(edge.source, edge.dest));
    }

    pub fn isEdgeExecutable(self: *const SsaPropagator, source: *const Block, dest: *const Block) bool {
        return self.executable_edges.contains(spEdgeKey(source, dest));
    }

    /// Is the incoming edge of the phi argument whose value operand is operand `i` (absolute operand
    /// index, so `i + 1` is the parent label) executable?
    pub fn isPhiArgExecutable(self: *SsaPropagator, phi: *const Inst, i: u32) bool {
        const ctx: *Ctx = self.ctx;
        const phi_bb: *Block = ctx.getInstrBlock(phi) orelse
            fatal("SsaPropagator.isPhiArgExecutable: phi %{d} is not in a block", .{phi.resultId()});
        const in_label_id: u32 = phi.getSingleWordOperand(i + 1);
        const in_label_instr: *Inst = ctx.getDefUseMgr().getDef(in_label_id) orelse
            fatal("SsaPropagator.isPhiArgExecutable: undefined label %{d}", .{in_label_id});
        const in_bb: *Block = ctx.getInstrBlock(in_label_instr) orelse
            fatal("SsaPropagator.isPhiArgExecutable: label %{d} has no block", .{in_label_id});
        return self.isEdgeExecutable(in_bb, phi_bb);
    }

    // ---- edges ------------------------------------------------------------------------------------

    fn addControlEdge(self: *SsaPropagator, edge: PropEdge) void {
        if (edge.dest == self.ctx.pseudoExitBlock()) return;
        if (!self.markEdgeExecutable(edge)) return;
        self.blocks.push(edge.dest);
    }

    fn addSsaEdges(self: *SsaPropagator, instr: *const Inst) void {
        if (instr.resultId() == 0) return;
        for (self.ctx.getDefUseMgr().registeredUsersOfId(instr.resultId())) |use_instr| {
            // BlockHasBeenSimulated(get_instr_block(use)): module-level users have no block, never simulated.
            const use_bb: *Block = self.ctx.getInstrBlock(use_instr) orelse continue;
            if (!self.blockHasBeenSimulated(use_bb)) continue;
            if (self.shouldSimulateAgain(use_instr)) self.ssa_edge_uses.push(use_instr);
        }
    }

    fn addSucc(self: *SsaPropagator, block: *Block, edge: PropEdge) void {
        const r: Map(*Block, List(PropEdge)).GetOrPutResult = self.bb_succs.getOrPut(block);
        if (!r.found_existing) r.value_ptr.* = .{};
        r.value_ptr.push(edge);
    }

    fn succsOf(self: *const SsaPropagator, block: *Block) []const PropEdge {
        const l: *List(PropEdge) = self.bb_succs.getPtr(block) orelse
            fatal("SsaPropagator: block %{d} has no successor table entry", .{block.id()});
        return l.items;
    }

    const SuccCollect = struct {
        prop: *SsaPropagator,
        block: *Block,
    };

    fn collectSucc(c: *SuccCollect, label_id: u32) void {
        const ctx: *Ctx = c.prop.ctx;
        const label_def: *Inst = ctx.getDefUseMgr().getDef(label_id) orelse
            fatal("SsaPropagator.initialize: undefined successor label %{d}", .{label_id});
        const succ_bb: *Block = ctx.getInstrBlock(label_def) orelse
            fatal("SsaPropagator.initialize: label %{d} has no block", .{label_id});
        c.prop.addSucc(c.block, .{ .source = c.block, .dest = succ_bb });
    }

    fn initialize(self: *SsaPropagator, fun: *Func) void {
        const ctx: *Ctx = self.ctx;
        const pseudo_entry: *Block = ctx.pseudoEntryBlock();
        const pseudo_exit: *Block = ctx.pseudoExitBlock();
        self.addSucc(pseudo_entry, .{ .source = pseudo_entry, .dest = fun.entry() });
        for (fun.blocks.items) |block| {
            var c: SsaPropagator.SuccCollect = SuccCollect{ .prop = self, .block = block };
            block.forEachSuccessorLabel(&c, collectSucc);
            if (block.isReturnOrAbort()) {
                self.addSucc(block, .{ .source = block, .dest = pseudo_exit });
            }
        }
        for (self.succsOf(pseudo_entry)) |e| self.addControlEdge(e);
    }

    // ---- driver -------------------------------------------------------------------------------------

    /// Runs the propagation on `fun`. Returns true when any visited instruction was "interesting".
    /// `visit(vctx, propagator, inst, &dest_bb)` is the visitor: it returns the new lattice value and may
    /// set `dest_bb` for an interesting control-flow instruction.
    pub fn run(
        self: *SsaPropagator,
        fun: *Func,
        vctx: anytype,
        comptime visit: fn (@TypeOf(vctx), *SsaPropagator, *Inst, *?*Block) PropStatus,
    ) bool {
        const R = SpRunner(@TypeOf(vctx), visit);
        var runner = R{ .prop = self, .vctx = vctx };
        self.initialize(fun);
        var changed: bool = false;
        while (!self.blocks.isEmpty() or !self.ssa_edge_uses.isEmpty()) {
            if (!self.blocks.isEmpty()) {
                const block: *Block = self.blocks.front();
                const st: PassStatus = runner.simulateBlock(block);
                if (st == .failure) return false;
                changed = changed or st == .success_with_change;
                _ = self.blocks.pop();
                continue;
            }
            const instr: *Inst = self.ssa_edge_uses.front();
            const st: PassStatus = runner.simulateInst(instr);
            if (st == .failure) return changed;
            changed = changed or st == .success_with_change;
            _ = self.ssa_edge_uses.pop();
        }
        return changed;
    }
};

/// The part of the propagator that needs the visitor; instantiated per (context type, visit function).
fn SpRunner(comptime V: type, comptime visit: fn (V, *SsaPropagator, *Inst, *?*Block) PropStatus) type {
    return struct {
        const Self = @This();

        prop: *SsaPropagator,
        vctx: V,

        const Acc = struct {
            runner: *Self,
            changed: bool = false,
        };

        fn accSimulate(acc: *Acc, instr: *Inst) bool {
            const st: PassStatus = acc.runner.simulateInst(instr);
            if (st == .failure) return false;
            if (st == .success_with_change) acc.changed = true;
            return true;
        }

        const OperandScan = struct {
            prop: *SsaPropagator,
        };

        /// WhileEachInId callback: stop (false) as soon as an operand's definition is still to be simulated.
        fn operandSettled(s: *OperandScan, use: *u32) bool {
            const def_instr: *Inst = s.prop.ctx.getDefUseMgr().getDef(use.*) orelse
                fatal("SsaPropagator.simulate: use of undefined id %{d}", .{use.*});
            if (s.prop.shouldSimulateAgain(def_instr)) return false;
            return true;
        }

        fn simulateInst(self: *Self, instr: *Inst) PassStatus {
            const prop: *SsaPropagator = self.prop;
            const ctx: *Ctx = prop.ctx;
            var changed: bool = false;
            if (!prop.shouldSimulateAgain(instr)) return .success_without_change;

            var dest_bb: ?*Block = null;
            const st: PropStatus = visit(self.vctx, prop, instr, &dest_bb);
            if (st == .failed) return .failure;

            const status_changed: bool = prop.setStatus(instr, st);
            if (st == .varying) {
                prop.dontSimulateAgain(instr);
                if (status_changed) prop.addSsaEdges(instr);
                if (instr.isBlockTerminator()) {
                    const block: *Block = ctx.getInstrBlock(instr) orelse
                        fatal("SsaPropagator.simulate: terminator not in a block", .{});
                    for (prop.succsOf(block)) |e| prop.addControlEdge(e);
                }
                return .success_without_change;
            } else if (st == .interesting) {
                if (status_changed) prop.addSsaEdges(instr);
                if (dest_bb) |dest| {
                    const src: *Block = ctx.getInstrBlock(instr) orelse
                        fatal("SsaPropagator.simulate: instruction with a destination block is not in a block", .{});
                    prop.addControlEdge(.{ .source = src, .dest = dest });
                }
                changed = true;
            }

            var has_operands_to_simulate: bool = false;
            if (instr.op == .OpPhi) {
                var i: u32 = 2;
                while (i < instr.numOperands()) : (i += 2) {
                    const arg_id: u32 = instr.getSingleWordOperand(i);
                    const arg_def_instr: *Inst = ctx.getDefUseMgr().getDef(arg_id) orelse
                        fatal("SsaPropagator.simulate: phi argument %{d} is undefined", .{arg_id});
                    if (!prop.isPhiArgExecutable(instr, i) or prop.shouldSimulateAgain(arg_def_instr)) {
                        has_operands_to_simulate = true;
                        break;
                    }
                }
            } else {
                var scan = OperandScan{ .prop = prop };
                has_operands_to_simulate = !instr.whileEachInId(&scan, operandSettled);
            }
            if (!has_operands_to_simulate) prop.dontSimulateAgain(instr);
            return if (changed) .success_with_change else .success_without_change;
        }

        fn simulateBlock(self: *Self, block: *Block) PassStatus {
            const prop: *SsaPropagator = self.prop;
            if (block == prop.ctx.pseudoExitBlock()) return .success_without_change;

            var acc = Acc{ .runner = self };
            if (!block.whileEachPhiInst(&acc, accSimulate, false)) return .failure;

            if (!prop.blockHasBeenSimulated(block)) {
                if (!block.whileEachInst(&acc, accSimulate, false)) return .failure;
                prop.markBlockSimulated(block);
                const succs: []const PropEdge = prop.succsOf(block);
                if (succs.len == 1) prop.addControlEdge(succs[0]);
            }
            return if (acc.changed) .success_with_change else .success_without_change;
        }
    };
}

// Pass infrastructure: what a pass is and how passes are run (pass.cpp / pass.h / pass_manager.cpp).
//
// A pass is a plain struct:
//     pub const name = "..."          -- Pass::name()
//     pub const preserved: u32 = ...  -- Pass::GetPreservedAnalyses() (documentation only: analyses are dropped at the end
//                                        of every pass)
//     pub fn run(self: *@This(), ctx: *Ctx) PassStatus   -- Pass::Process()
// `PassSpec` has one field per pass; the pass manager dispatches with `inline else` (no vtable). PassStatus is
// declared next to the sparse propagator.

/// Pass::CombineStatus (std::min over the enum values failure < success_with_change < success_without_change).
pub fn statusCombine(a: PassStatus, b: PassStatus) PassStatus {
    return if (@intFromEnum(a) <= @intFromEnum(b)) a else b;
}

// ---- helpers that live on the C++ Pass base class ------------------------------------------------------

/// Pass::GetPointeeTypeId
pub fn passGetPointeeTypeId(ctx: *Ctx, ptr_inst: *const Inst) u32 {
    const ptr_type_id: u32 = ptr_inst.typeId();
    const ptr_type_inst: *Inst = ctx.getDefUseMgr().getDef(ptr_type_id) orelse
        fatal("GetPointeeTypeId: pointer type %{d} is not defined", .{ptr_type_id});
    return ptr_type_inst.getSingleWordInOperand(1);
}

/// Pass::GetBaseType: the scalar type of a scalar, vector or matrix type.
pub fn passGetBaseType(ctx: *Ctx, ty_id: u32) *Inst {
    const du: *DefUseMgr = ctx.getDefUseMgr();
    var ty_inst: *Inst = du.getDef(ty_id) orelse fatal("GetBaseType: type %{d} is not defined", .{ty_id});
    if (ty_inst.op == .OpTypeMatrix) {
        const vty_id: u32 = ty_inst.getSingleWordInOperand(0);
        ty_inst = du.getDef(vty_id) orelse fatal("GetBaseType: type %{d} is not defined", .{vty_id});
    }
    if (ty_inst.op == .OpTypeVector) {
        const cty_id: u32 = ty_inst.getSingleWordInOperand(0);
        ty_inst = du.getDef(cty_id) orelse fatal("GetBaseType: type %{d} is not defined", .{cty_id});
    }
    return ty_inst;
}

/// Pass::IsFloat
pub fn passIsFloat(ctx: *Ctx, ty_id: u32, width: u32) bool {
    const ty_inst: *Inst = passGetBaseType(ctx, ty_id);
    if (ty_inst.op != .OpTypeFloat) return false;
    return ty_inst.getSingleWordInOperand(0) == width;
}

/// Pass::GetNullId: the id of the null constant of `type_id` (declared when missing).
pub fn passGetNullId(ctx: *Ctx, type_id: u32) u32 {
    if (passIsFloat(ctx, type_id, 16)) ctx.addCapability(.Float16);
    const type_mgr: *TypeMgr = ctx.getTypeMgr();
    const const_mgr: *ConstMgr = ctx.getConstantMgr();
    const ty: ?*Type = type_mgr.getType(type_id);
    const null_const: ?*const Constant = const_mgr.getConstant(ty, &.{});
    const null_inst: *Inst = const_mgr.getDefiningInstruction(null_const, type_id, null) orelse
        fatal("GetNullId: cannot build the null constant of type %{d}", .{type_id});
    return null_inst.resultId();
}

/// Pass::GenerateCopy. Returns 0 when no copy can be generated (like the C++).
pub fn passGenerateCopy(ctx: *Ctx, object_to_copy: *Inst, new_type_id: u32, insertion_position: *Inst) u32 {
    const const_mgr: *ConstMgr = ctx.getConstantMgr();
    const du: *DefUseMgr = ctx.getDefUseMgr();
    const original_type_id: u32 = object_to_copy.typeId();
    if (original_type_id == new_type_id) return object_to_copy.resultId();

    const ir_builder = InstBuilder.init(ctx, insertion_position, Analysis.instr_to_block | Analysis.def_use);
    const original_type: *Inst = du.getDef(original_type_id) orelse fatal("GenerateCopy: type %{d} is not defined", .{original_type_id});
    const new_type: *Inst = du.getDef(new_type_id) orelse fatal("GenerateCopy: type %{d} is not defined", .{new_type_id});
    if (new_type.op != original_type.op) return 0;

    switch (original_type.op) {
        .OpTypeArray => {
            const original_element_type_id: u32 = original_type.getSingleWordInOperand(0);
            const new_element_type_id: u32 = new_type.getSingleWordInOperand(0);
            var element_ids: List(u32) = .{};
            const length_id: u32 = original_type.getSingleWordInOperand(1);
            const length_const: *const Constant = const_mgr.findDeclaredConstant(length_id) orelse
                fatal("GenerateCopy: array length %{d} is not a declared constant", .{length_id});
            const array_length: u32 = length_const.getU32();
            var i: u32 = 0;
            while (i < array_length) : (i += 1) {
                const extract: *Inst = ir_builder.addCompositeExtract(original_element_type_id, object_to_copy.resultId(), &.{i}) orelse return 0;
                const new_id: u32 = passGenerateCopy(ctx, extract, new_element_type_id, insertion_position);
                if (new_id == 0) return 0;
                element_ids.push(new_id);
            }
            const construct: *Inst = ir_builder.addCompositeConstruct(new_type_id, element_ids.items) orelse return 0;
            return construct.resultId();
        },
        .OpTypeStruct => {
            var element_ids: List(u32) = .{};
            var i: u32 = 0;
            while (i < original_type.numInOperands()) : (i += 1) {
                const orig_member_type_id: u32 = original_type.getSingleWordInOperand(i);
                const new_member_type_id: u32 = new_type.getSingleWordInOperand(i);
                const extract: *Inst = ir_builder.addCompositeExtract(orig_member_type_id, object_to_copy.resultId(), &.{i}) orelse return 0;
                const new_id: u32 = passGenerateCopy(ctx, extract, new_member_type_id, insertion_position);
                if (new_id == 0) return 0;
                element_ids.push(new_id);
            }
            const construct: *Inst = ir_builder.addCompositeConstruct(new_type_id, element_ids.items) orelse return 0;
            return construct.resultId();
        },
        else => return 0,
    }
}

// The simple passes, each a short walk over the module:
//
//   StripDebugInfo, StripNonSemanticInfo, CompactIds, EliminateDeadFunctions, EliminateDeadConstant,
//   FreezeSpecConstantValue, RemoveDontInline, SetSpecConstantDefaultValue, UnifyConstant, RemoveDuplicates,
//   FlattenDecoration.
//
// Every pass is a struct with `name`, `preserved` (documentation only, analyses are dropped at every pass boundary)
// and `run(self, ctx) PassStatus`. Helper functions that are not methods are prefixed with the pass initials.

/// True when in-operand 0 of `inst` is a literal string equal to `text` (OpExtension names).
fn spInOperandStringIs(inst: *const Inst, text: []const u8) bool {
    const o: *Operand = inst.getInOperand(0);
    if (o.kind != .LiteralString) return false;
    return std.mem.eql(u8, o.asString(), text);
}

// ---------------------------------------------------------------------------------------------
// StripDebugInfo (strip_debug_info_pass.cpp)
// ---------------------------------------------------------------------------------------------

/// Drops the line instructions attached to `inst`.
fn sdiClearLines(modified: *bool, inst: *Inst) void {
    if (inst.dbg_lines.len() != 0) {
        modified.* = true;
        inst.dbg_lines.clear();
    }
}

/// --strip-debug: removes the debug instructions that do not change what the module computes: OpString / OpSource and
/// the other instructions of the first debug section, OpName and OpMemberName, OpModuleProcessed, and the OpLine /
/// OpNoLine attached to instructions. In a module that declares SPV_KHR_non_semantic_info, an OpString that a
/// NonSemantic instruction uses is kept.
pub const StripDebugInfo = struct {
    pub const name = "strip-debug";
    pub const preserved: u32 = Analysis.none;

    pub fn run(self: *StripDebugInfo, ctx: *Ctx) PassStatus {
        _ = self;
        var uses_non_semantic_info: bool = false;
        var ext_it: ?*Inst = ctx.module.extensions.first;
        while (ext_it) |inst| : (ext_it = inst.next) {
            if (spInOperandStringIs(inst, "SPV_KHR_non_semantic_info")) uses_non_semantic_info = true;
        }

        var to_kill: List(*Inst) = .{};
        var d1: ?*Inst = ctx.module.debugs1.first;
        while (d1) |inst| : (d1 = inst.next) {
            if (!uses_non_semantic_info) {
                to_kill.push(inst);
                continue;
            }
            switch (inst.op) {
                .OpString => {
                    const du: *DefUseMgr = ctx.getDefUseMgr();
                    var no_nonsemantic_use: bool = true;
                    for (du.registeredUsers(inst)) |use| {
                        if (!opIsExtendedInstruction(use.op)) continue;
                        const set_id: u32 = use.getSingleWordInOperand(0);
                        const ext_inst_set: *Inst = du.getDef(set_id) orelse fatal("strip-debug: extended instruction set %{d} is not defined", .{set_id});
                        const extension_name: []const u8 = ext_inst_set.getInOperand(0).asString();
                        if (std.mem.startsWith(u8, extension_name, "NonSemantic.")) {
                            no_nonsemantic_use = false;
                            break;
                        }
                    }
                    if (no_nonsemantic_use) to_kill.push(inst);
                },
                else => to_kill.push(inst),
            }
        }
        var d2: ?*Inst = ctx.module.debugs2.first;
        while (d2) |inst| : (d2 = inst.next) to_kill.push(inst);
        var d3: ?*Inst = ctx.module.debugs3.first;
        while (d3) |inst| : (d3 = inst.next) to_kill.push(inst);
        // (the C++ also collects ext_inst_debuginfo(); extended debug info is rejected or stripped by the loader)

        // The C++ std::sort puts every OpName before everything else (a partition; the order inside both classes does not
        // matter): names are killed first so that no later kill meets an already removed name.
        var ordered: List(*Inst) = .{};
        for (to_kill.items) |i| {
            if (i.op == .OpName) ordered.push(i);
        }
        for (to_kill.items) |i| {
            if (i.op != .OpName) ordered.push(i);
        }

        var modified: bool = ordered.len() != 0;
        for (ordered.items) |i| _ = ctx.killInst(i);

        ctx.module.forEachInst(&modified, sdiClearLines, false);
        if (ctx.module.trailing_dbg_lines.len() != 0) {
            modified = true;
            ctx.module.trailing_dbg_lines.clear();
        }
        return if (modified) .success_with_change else .success_without_change;
    }
};

// ---------------------------------------------------------------------------------------------
// StripNonSemanticInfo (strip_nonsemantic_info_pass.cpp)
// ---------------------------------------------------------------------------------------------

/// The ids of the NonSemantic instruction sets and the instructions collected for removal.
const SniState = struct {
    sets: *Set(u32),
    to_remove: *List(*Inst),
};

/// Collects an OpExtInst of one of the NonSemantic sets.
fn sniCollectUses(st: SniState, inst: *Inst) void {
    if (opIsExtendedInstruction(inst.op)) {
        if (st.sets.contains(inst.getSingleWordInOperand(0))) st.to_remove.push(inst);
    }
}

/// --strip-nonsemantic: removes the NonSemantic instruction sets: their imports and instructions, the extension
/// SPV_KHR_non_semantic_info, and the decorations that only carry HLSL information (HlslSemanticGOOGLE, UserTypeGOOGLE,
/// HlslCounterBufferGOOGLE) with the extensions that introduced them. SPV_GOOGLE_decorate_string is removed too when no
/// other string decoration remains.
pub const StripNonSemanticInfo = struct {
    pub const name = "strip-nonsemantic";
    pub const preserved: u32 = Analysis.instr_to_block | Analysis.combinators | Analysis.cfg | Analysis.dominator |
        Analysis.loops | Analysis.name_map | Analysis.constants | Analysis.types;

    pub fn run(self: *StripNonSemanticInfo, ctx: *Ctx) PassStatus {
        _ = self;
        var modified: bool = false;
        var to_remove: List(*Inst) = .{};
        var other_uses_for_decorate_string: bool = false;

        const hlsl_semantic: u32 = @intFromEnum(Decoration.HlslSemanticGOOGLE);
        const user_type: u32 = @intFromEnum(Decoration.UserTypeGOOGLE);
        const hlsl_counter_buffer: u32 = @intFromEnum(Decoration.HlslCounterBufferGOOGLE);

        var ia: ?*Inst = ctx.module.annotations.first;
        while (ia) |inst| : (ia = inst.next) {
            switch (inst.op) {
                .OpDecorateStringGOOGLE => {
                    const d: u32 = inst.getSingleWordInOperand(1);
                    if (d == hlsl_semantic or d == user_type) {
                        to_remove.push(inst);
                    } else {
                        other_uses_for_decorate_string = true;
                    }
                },
                .OpMemberDecorateStringGOOGLE => {
                    const d: u32 = inst.getSingleWordInOperand(2);
                    if (d == hlsl_semantic or d == user_type) {
                        to_remove.push(inst);
                    } else {
                        other_uses_for_decorate_string = true;
                    }
                },
                .OpDecorateId => {
                    if (inst.getSingleWordInOperand(1) == hlsl_counter_buffer) to_remove.push(inst);
                },
                else => {},
            }
        }

        var ie: ?*Inst = ctx.module.extensions.first;
        while (ie) |inst| : (ie = inst.next) {
            if (spInOperandStringIs(inst, "SPV_GOOGLE_hlsl_functionality1")) {
                to_remove.push(inst);
            } else if (spInOperandStringIs(inst, "SPV_GOOGLE_user_type")) {
                to_remove.push(inst);
            } else if (!other_uses_for_decorate_string and spInOperandStringIs(inst, "SPV_GOOGLE_decorate_string")) {
                to_remove.push(inst);
            } else if (spInOperandStringIs(inst, "SPV_KHR_non_semantic_info")) {
                to_remove.push(inst);
            }
        }

        var non_semantic_sets: Set(u32) = .{};
        var ii: ?*Inst = ctx.module.ext_inst_imports.first;
        while (ii) |inst| : (ii = inst.next) {
            check(inst.op == .OpExtInstImport, "Expecting an import of an extension's instruction set.");
            const extension_name: []const u8 = inst.getInOperand(0).asString();
            if (std.mem.startsWith(u8, extension_name, "NonSemantic.")) {
                _ = non_semantic_sets.insert(inst.resultId());
                to_remove.push(inst);
            }
        }
        if (non_semantic_sets.count() != 0) {
            const st: SniState = .{ .sets = &non_semantic_sets, .to_remove = &to_remove };
            ctx.module.forEachInst(st, sniCollectUses, true);
        }

        for (to_remove.items) |inst| {
            modified = true;
            _ = ctx.killInst(inst);
        }
        return if (modified) .success_with_change else .success_without_change;
    }
};

// ---------------------------------------------------------------------------------------------
// CompactIds (compact_ids_pass.cpp)
// ---------------------------------------------------------------------------------------------

/// The mapping from old ids to new ids and whether any id changed.
const CidState = struct {
    mapping: Map(u32, u32) = .{},
    modified: bool = false,
};

/// GetRemappedId: new ids are handed out in order of first encounter, starting at 1.
fn cidRemap(mapping: *Map(u32, u32), id: u32) u32 {
    const gop: Map(u32, u32).GetOrPutResult = mapping.getOrPut(id);
    if (!gop.found_existing) gop.value_ptr.* = @intCast(mapping.count()); // size() + 1 before the insertion
    return gop.value_ptr.*;
}

/// Renumbers every id operand of `inst` (results, types and uses alike).
fn cidVisit(st: *CidState, inst: *Inst) void {
    for (inst.ops.items) |*operand| {
        if (!kindIsId(operand.kind)) continue;
        check(operand.n == 1, "compact-ids: an id operand with more than one word");
        const new_id: u32 = cidRemap(&st.mapping, operand.w[0]);
        if (operand.w[0] != new_id) {
            st.modified = true;
            operand.w[0] = new_id;
        }
    }
}

/// --compact-ids: renumbers the ids in order of first appearance, from 1, and lowers the id bound to match. Closes the gaps
/// that other passes leave in the id space.
pub const CompactIds = struct {
    pub const name = "compact-ids";
    pub const preserved: u32 = Analysis.instr_to_block | Analysis.dominator | Analysis.loops;

    pub fn run(self: *CompactIds, ctx: *Ctx) PassStatus {
        _ = self;
        var st: CidState = .{};
        ctx.module.forEachInst(&st, cidVisit, true);
        const new_bound: u32 = @intCast(st.mapping.count() + 1);
        if (ctx.module.idBound() != new_bound) {
            st.modified = true;
            ctx.module.setIdBound(new_bound);
            ctx.resetFeatureManager();
        }
        return if (st.modified) .success_with_change else .success_without_change;
    }
};

// ---------------------------------------------------------------------------------------------
// EliminateDeadFunctions (eliminate_dead_functions_pass.cpp, eliminate_dead_functions_util.cpp)
// ---------------------------------------------------------------------------------------------

/// Marks a function that is reachable from an entry point or exported.
fn edfMarkLive(live: *Set(*Func), f: *Func) bool {
    _ = live.insert(f);
    return false;
}

/// State while one function is removed: its position in the module, whether OpFunctionEnd has been passed, and the
/// instructions to kill once the walk is over.
const EdfState = struct {
    ctx: *Ctx,
    func_index: usize, // position of the function being eliminated in Module.functions
    seen_func_end: bool = false,
    to_kill: Set(*Inst) = .{},
};

/// Removes one instruction of a dead function, together with the NonSemantic instructions that use it. An OpExtInst that
/// follows OpFunctionEnd belongs to the code before the function, so it survives: it moves to the previous function, or
/// to the global values when the dead function is the first one.
fn edfVisit(st: *EdfState, inst: *Inst) void {
    const ctx: *Ctx = st.ctx;
    if (inst.op == .OpFunctionEnd) st.seen_func_end = true;
    if (st.seen_func_end and inst.op == .OpExtInst) {
        // a non-semantic instruction that follows the function: it survives, moved to the previous function (or to the
        // global section when this is the first function)
        if (st.to_kill.contains(inst)) return;
        const clone: *Inst = inst.clone();
        ctx.getDefUseMgr().clearInst(inst);
        ctx.analyzeDefUse(clone);
        if (st.func_index == 0) {
            ctx.addGlobalValue(clone);
        } else {
            ctx.module.functions.items[st.func_index - 1].addNonSemanticInstruction(clone);
        }
        inst.toNop();
    } else if (!st.to_kill.contains(inst)) {
        ctx.collectNonSemanticTree(inst, &st.to_kill);
        _ = ctx.killInst(inst);
    }
}

/// eliminatedeadfunctionsutil::EliminateFunction: kills every instruction of module.functions[index] and removes the
/// function from the module.
fn edfEliminateFunction(ctx: *Ctx, index: usize) void {
    const fun: *Func = ctx.module.functions.items[index];
    var st: EdfState = .{ .ctx = ctx, .func_index = index };
    fun.forEachInst(&st, edfVisit, true, true);
    var it: Map(*Inst, void).Hm.Iterator = st.to_kill.iterator();
    while (it.next()) |entry| _ = ctx.killInst(entry.key_ptr.*);
    _ = ctx.module.functions.orderedRemove(index);
}

/// --eliminate-dead-functions: removes the functions that are not reachable from an entry point or an exported function
/// through calls.
pub const EliminateDeadFunctions = struct {
    pub const name = "eliminate-dead-functions";
    pub const preserved: u32 = Analysis.def_use | Analysis.constants | Analysis.types;

    pub fn run(self: *EliminateDeadFunctions, ctx: *Ctx) PassStatus {
        _ = self;
        var live: Set(*Func) = .{};
        _ = ctx.processReachableCallTree(&live, edfMarkLive);
        var modified: bool = false;
        var k: usize = 0;
        while (k < ctx.module.functions.len()) {
            if (live.contains(ctx.module.functions.items[k])) {
                k += 1;
            } else {
                modified = true;
                edfEliminateFunction(ctx, k);
            }
        }
        return if (modified) .success_with_change else .success_without_change;
    }
};

// ---------------------------------------------------------------------------------------------
// EliminateDeadConstant (eliminate_dead_constant_pass.cpp)
// ---------------------------------------------------------------------------------------------

/// --eliminate-dead-const: removes constants that nothing uses. Decorations and debug instructions do not count as uses.
/// A composite constant that is removed releases its operands, which may become dead in turn.
pub const EliminateDeadConstant = struct {
    pub const name = "eliminate-dead-const";
    pub const preserved: u32 = Analysis.none;

    pub fn run(self: *EliminateDeadConstant, ctx: *Ctx) PassStatus {
        _ = self;
        const du: *DefUseMgr = ctx.getDefUseMgr();
        var use_counts: Map(*Inst, u32) = .{};
        var working_list: List(*Inst) = .{}; // every constant enters it at most once, so a stack is enough
        const constants: List(*Inst) = ctx.module.getConstants();
        for (constants.items) |c| {
            var count: u32 = 0;
            var uses: DefUseMgr.UseIter = du.usesOf(c);
            while (uses.next()) |use| {
                const op: Op = use.user.op;
                if (!(opIsAnnotation(op) or opIsDebug1(op) or opIsDebug2(op) or opIsDebug3(op))) count += 1;
            }
            use_counts.put(c, count);
            if (count == 0) working_list.push(c);
        }

        var dead_consts: List(*Inst) = .{};
        while (working_list.pop()) |inst| {
            switch (inst.op) {
                .OpConstantComposite, .OpSpecConstantComposite, .OpSpecConstantOp => {
                    for (0..inst.numInOperands()) |i| {
                        if (inst.getInOperand(i).kind != .IdRef) continue;
                        const operand_id: u32 = inst.getSingleWordInOperand(i);
                        const def_inst: *Inst = du.getDef(operand_id) orelse continue;
                        const cnt: *u32 = use_counts.getPtr(def_inst) orelse continue;
                        cnt.* -%= 1; // the C++ assert is a no-op in the release build
                        if (cnt.* == 0) working_list.push(def_inst);
                    }
                },
                else => {},
            }
            dead_consts.push(inst);
        }
        for (dead_consts.items) |dc| _ = ctx.killDef(dc.resultId());
        return if (dead_consts.len() == 0) .success_without_change else .success_with_change;
    }
};

// ---------------------------------------------------------------------------------------------
// FreezeSpecConstantValue (freeze_spec_constant_value_pass.cpp)
// ---------------------------------------------------------------------------------------------

/// The context and whether anything changed.
const FscState = struct {
    ctx: *Ctx,
    modified: bool = false,
};

/// Turns a specialization constant into the matching ordinary constant and removes its SpecId decoration.
fn fscVisit(st: *FscState, inst: *Inst) void {
    switch (inst.op) {
        .OpSpecConstant => {
            inst.setOpcode(.OpConstant);
            st.modified = true;
        },
        .OpSpecConstantTrue => {
            inst.setOpcode(.OpConstantTrue);
            st.modified = true;
        },
        .OpSpecConstantFalse => {
            inst.setOpcode(.OpConstantFalse);
            st.modified = true;
        },
        .OpSpecConstantDataKHR => {
            inst.setOpcode(.OpConstantDataKHR);
            st.modified = true;
        },
        .OpDecorate => {
            if (inst.getSingleWordInOperand(1) == @intFromEnum(Decoration.SpecId)) {
                _ = st.ctx.killInst(inst);
                st.modified = true;
            }
        },
        else => {},
    }
}

/// --freeze-spec-const: turns every specialization constant (OpSpecConstant, OpSpecConstantTrue / False and
/// OpSpecConstantDataKHR) into an ordinary constant with its default value, and removes the SpecId decorations.
pub const FreezeSpecConstantValue = struct {
    pub const name = "freeze-spec-const";
    pub const preserved: u32 = Analysis.none;

    pub fn run(self: *FreezeSpecConstantValue, ctx: *Ctx) PassStatus {
        _ = self;
        var st: FscState = .{ .ctx = ctx };
        ctx.module.forEachInst(&st, fscVisit, false);
        return if (st.modified) .success_with_change else .success_without_change;
    }
};

// ---------------------------------------------------------------------------------------------
// RemoveDontInline (remove_dontinline_pass.cpp)
// ---------------------------------------------------------------------------------------------

/// --remove-dont-inline: clears the DontInline bit of the function control mask of every function.
pub const RemoveDontInline = struct {
    pub const name = "remove-dont-inline";
    pub const preserved: u32 = Analysis.none;

    pub fn run(self: *RemoveDontInline, ctx: *Ctx) PassStatus {
        _ = self;
        for (ctx.module.functions.items) |fun| {
            const control: u32 = fun.def.getSingleWordInOperand(0);
            const dont_inline: u32 = 0x2; // FunctionControlMask::DontInline
            if ((control & dont_inline) == 0) continue;
            fun.def.setInOperand(0, &.{control & ~dont_inline});
        }
        // The C++ pass discards the per-function results and reports `modified = false` unconditionally. Replicated.
        return .success_without_change;
    }
};

// ---------------------------------------------------------------------------------------------
// SetSpecConstantDefaultValue (set_spec_constant_default_value_pass.cpp)
// ---------------------------------------------------------------------------------------------

/// One `<spec id>:<value>` entry of the default-value string.
pub const SpecIdValue = struct {
    spec_id: u32,
    text: []const u8, // IR arena
};

/// ParseDefaultValueStr: the words of the value, empty when the text does not fit the type.
fn ssParseDefaultValueStr(text: []const u8, ty: *const Type) List(u32) {
    var result: List(u32) = .{};
    if (std.mem.eql(u8, text, "true") and ty.kind() == .bool_) {
        result.push(1);
    } else if (std.mem.eql(u8, text, "false") and ty.kind() == .bool_) {
        result.push(0);
    } else {
        var number_type: NumberType = .{ .bitwidth = 32, .kind = .unsigned_int };
        if (ty.as(.integer)) |it| {
            number_type.bitwidth = it.width;
            number_type.kind = if (it.is_signed) .signed_int else .unsigned_int;
        } else if (ty.as(.float)) |ft| {
            number_type.bitwidth = ft.width;
            number_type.kind = .floating;
        } else {
            return result;
        }
        const rc: EncodeStatus = parseAndEncodeNumber(text, number_type, &result);
        if (rc != .success) result.clear();
    }
    return result;
}

/// True for the instructions that a SpecId decoration may name.
fn ssCanHaveSpecId(inst: *const Inst) bool {
    return switch (inst.op) {
        .OpSpecConstant, .OpSpecConstantFalse, .OpSpecConstantTrue, .OpSpecConstantDataKHR => true,
        else => false,
    };
}

/// The specialization constant that a decoration group decorates through OpGroupDecorate, or null when it decorates
/// something else or more than one constant.
fn ssSpecIdTargetFromDecorationGroup(group_def: *const Inst, du: *DefUseMgr) ?*Inst {
    const gd: *Inst = for (du.registeredUsers(group_def)) |user| {
        if (user.op == .OpGroupDecorate) break user;
    } else return null;
    var target_inst: ?*Inst = null;
    var i: usize = 1;
    while (i < gd.numInOperands()) : (i += 1) {
        const candidate_id: u32 = gd.getSingleWordInOperand(i);
        const candidate_inst: *Inst = du.getDef(candidate_id) orelse continue;
        if (target_inst == null) {
            if (ssCanHaveSpecId(candidate_inst)) {
                target_inst = candidate_inst;
            } else {
                return null;
            }
        } else {
            if (candidate_inst != target_inst.?) return null;
        }
    }
    return target_inst;
}

/// --set-spec-const-default-value "<spec id>:<value> ...": changes the default value of the specialization constants
/// that carry the given SpecId, found directly or through a decoration group. Values that do not fit the type of
/// the constant are ignored.
pub const SetSpecConstantDefaultValue = struct {
    pub const name = "set-spec-const-default-value";
    pub const preserved: u32 = Analysis.none;

    /// spec id -> value text. (The C++ pass also has a bit-pattern map filled by an API the tool never uses; the
    /// pass only consults it when this map is empty, in which case nothing can match. Not ported.)
    entries: IrList(SpecIdValue) = .{},

    pub fn run(self: *SetSpecConstantDefaultValue, ctx: *Ctx) PassStatus {
        var modified: bool = false;
        var cur: ?*Inst = ctx.module.annotations.first;
        while (cur) |inst| : (cur = inst.next) {
            if (inst.op != .OpDecorate) continue;
            if (inst.numOperands() != 3) continue;
            if (inst.getSingleWordInOperand(1) != @intFromEnum(Decoration.SpecId)) continue;
            const spec_id: u32 = inst.getSingleWordOperand(2);
            const target_id: u32 = inst.getSingleWordOperand(0);

            const du: *DefUseMgr = ctx.getDefUseMgr();
            const target_inst: *Inst = du.getDef(target_id) orelse continue;
            const spec_inst: *Inst = blk: {
                if (target_inst.op == .OpDecorationGroup) {
                    break :blk ssSpecIdTargetFromDecorationGroup(target_inst, du) orelse continue;
                }
                break :blk target_inst;
            };

            // with an empty table the C++ takes its bit-pattern branch, whose map is empty: every decoration is skipped
            var value_text: ?[]const u8 = null;
            for (self.entries.items) |e| {
                if (e.spec_id == spec_id) {
                    value_text = e.text;
                    break;
                }
            }
            const text: []const u8 = value_text orelse continue;

            const ty: *Type = ctx.getTypeMgr().getType(spec_inst.typeId()) orelse
                fatal("set-spec-const-default-value: the type %{d} of the specialization constant is not known", .{spec_inst.typeId()});
            const bit_pattern: List(u32) = ssParseDefaultValueStr(text, ty);
            if (bit_pattern.len() == 0) continue;

            switch (spec_inst.op) {
                .OpSpecConstant => {
                    if (!std.mem.eql(u32, spec_inst.getInOperand(0).words(), bit_pattern.items)) {
                        spec_inst.setInOperand(0, bit_pattern.items);
                        modified = true;
                    }
                },
                .OpSpecConstantTrue => {
                    if (bit_pattern.items[0] == 0) {
                        spec_inst.setOpcode(.OpSpecConstantFalse);
                        modified = true;
                    }
                },
                .OpSpecConstantFalse => {
                    if (bit_pattern.items[0] != 0) {
                        spec_inst.setOpcode(.OpSpecConstantTrue);
                        modified = true;
                    }
                },
                .OpSpecConstantDataKHR => {
                    if (!std.mem.eql(u32, spec_inst.getInOperand(0).words(), bit_pattern.items)) {
                        var operands: List(Operand) = .{};
                        operands.push(spec_inst.getOperand(0).*);
                        operands.push(spec_inst.getOperand(1).*);
                        for (bit_pattern.items) |w| operands.push(Operand.single(.LiteralInteger, w));
                        spec_inst.replaceOperands(operands.items);
                        modified = true;
                    }
                },
                else => {},
            }
        }
        return if (modified) .success_with_change else .success_without_change;
    }
};

// ---------------------------------------------------------------------------------------------
// UnifyConstant (unify_const_pass.cpp)
// ---------------------------------------------------------------------------------------------

/// ResultIdTrie node: the keys are the opcode followed by the words of every operand but the result id.
const UcNode = struct {
    result_id: u32 = 0,
    next: Map(u32, *UcNode) = .{},
};

/// The child of `node` for `key`, created when it is missing.
fn ucStep(node: *UcNode, key: u32) *UcNode {
    const gop: Map(u32, *UcNode).GetOrPutResult = node.next.getOrPut(key);
    if (!gop.found_existing) {
        const fresh = scAllocator().create(UcNode) catch oom();
        fresh.* = .{};
        gop.value_ptr.* = fresh;
    }
    return gop.value_ptr.*;
}

/// The result id of the first instruction with the same opcode and operands (result id aside) as `inst`; `inst` itself
/// when it is the first one.
fn ucLookupEquivalentResultFor(root: *UcNode, inst: *const Inst) u32 {
    var node: *UcNode = ucStep(root, opcodeValue(inst.op));
    for (inst.ops.items) |*operand| {
        if (operand.kind == .IdResult) continue;
        for (operand.words()) |w| node = ucStep(node, w);
    }
    if (node.result_id == 0) node.result_id = inst.resultId();
    return node.result_id;
}

/// --unify-const: merges constants that have the same opcode, type and operands: the users of a duplicate are redirected
/// to the first one and the duplicate is removed. Constants that carry decorations are left alone.
pub const UnifyConstant = struct {
    pub const name = "unify-const";
    pub const preserved: u32 = Analysis.none;

    pub fn run(self: *UnifyConstant, ctx: *Ctx) PassStatus {
        _ = self;
        var modified: bool = false;
        const root = scAllocator().create(UcNode) catch oom();
        root.* = .{};
        var cur: ?*Inst = ctx.module.types_values.first;
        while (cur) |inst| {
            const next_instruction: ?*Inst = inst.next;
            cur = next_instruction;
            const annos: List(*Inst) = ctx.getDefUseMgr().getAnnotations(inst.resultId());
            if (annos.len() != 0) continue;
            switch (inst.op) {
                .OpConstantTrue, .OpConstantFalse, .OpConstant, .OpConstantNull, .OpConstantSampler,
                .OpConstantComposite, .OpSpecConstantOp, .OpSpecConstantComposite,
                => {
                    const id: u32 = ucLookupEquivalentResultFor(root, inst);
                    if (id != inst.resultId()) {
                        _ = ctx.replaceAllUsesWith(inst.resultId(), id);
                        _ = ctx.killInst(inst);
                        modified = true;
                    }
                },
                else => {},
            }
        }
        return if (modified) .success_with_change else .success_without_change;
    }
};

// ---------------------------------------------------------------------------------------------
// RemoveDuplicates (remove_duplicates_pass.cpp)
// ---------------------------------------------------------------------------------------------

/// Identifies a capability (with the condition id of OpConditionalCapabilityINTEL, 0 for the plain form).
const RdCapKey = struct { cond: u32, cap: u32 };

/// Removes repeated OpCapability instructions.
fn rdRemoveDuplicateCapabilities(ctx: *Ctx) bool {
    var modified: bool = false;
    if (ctx.module.capabilities.isEmpty()) return modified;
    var seen: List(RdCapKey) = .{};
    var cur: ?*Inst = ctx.module.capabilities.first;
    while (cur) |inst| {
        var cond_id: u32 = 0;
        var i_cap: usize = 0;
        if (inst.op == .OpConditionalCapabilityINTEL) {
            cond_id = inst.getOperand(0).asId();
            i_cap = 1;
        }
        const key: RdCapKey = .{ .cond = cond_id, .cap = inst.getSingleWordOperand(i_cap) };
        var found: bool = false;
        for (seen.items) |s| {
            if (s.cond == key.cond and s.cap == key.cap) found = true;
        }
        if (!found) {
            seen.push(key);
            cur = inst.next;
        } else {
            cur = ctx.killInst(inst);
            modified = true;
        }
    }
    return modified;
}

/// Identifies an extension by name (with the condition id of OpConditionalExtensionINTEL, 0 for the plain form).
const RdExtKey = struct { cond: u32, name: []const u8 };

/// Removes repeated OpExtension instructions.
fn rdRemoveDuplicateExtensions(ctx: *Ctx) bool {
    var modified: bool = false;
    if (ctx.module.extensions.isEmpty()) return modified;
    var seen: List(RdExtKey) = .{};
    var cur: ?*Inst = ctx.module.extensions.first;
    while (cur) |inst| {
        var cond_id: u32 = 0;
        var i_name: usize = 0;
        if (inst.op == .OpConditionalExtensionINTEL) {
            cond_id = inst.getOperand(0).asId();
            i_name = 1;
        }
        const key: RdExtKey = .{ .cond = cond_id, .name = inst.getOperand(i_name).asString() };
        var found: bool = false;
        for (seen.items) |s| {
            if (s.cond == key.cond and std.mem.eql(u8, s.name, key.name)) found = true;
        }
        if (!found) {
            seen.push(key);
            cur = inst.next;
        } else {
            cur = ctx.killInst(inst);
            modified = true;
        }
    }
    return modified;
}

/// An extended instruction set import by name, and the id of the first import of it.
const RdImportKey = struct { name: []const u8, id: u32 };

/// Removes repeated imports of the same extended instruction set; the uses of a removed import go to the first one.
fn rdRemoveDuplicatesExtInstImports(ctx: *Ctx) bool {
    var modified: bool = false;
    if (ctx.module.ext_inst_imports.isEmpty()) return modified;
    var seen: List(RdImportKey) = .{};
    var cur: ?*Inst = ctx.module.ext_inst_imports.first;
    while (cur) |i| {
        const name: []const u8 = i.getInOperand(0).asString();
        var first_id: u32 = 0;
        for (seen.items) |s| {
            if (std.mem.eql(u8, s.name, name)) {
                first_id = s.id;
                break;
            }
        }
        if (first_id == 0) {
            seen.push(.{ .name = name, .id = i.resultId() });
            cur = i.next;
        } else {
            _ = ctx.replaceAllUsesWith(i.resultId(), first_id);
            cur = ctx.killInst(i);
            modified = true;
        }
    }
    return modified;
}

/// Merges types that are the same type (Type.isSame), including repeated OpTypeForwardPointer: the users of a duplicate go
/// to the first one. The type manager used here is a private one: it is not told about the instructions removed.
fn rdRemoveDuplicateTypes(ctx: *Ctx) bool {
    var modified: bool = false;
    if (ctx.module.types_values.isEmpty()) return modified;
    // a fresh TypeManager like the C++ (it is not the context's one and never learns about the kills below)
    const type_manager: *TypeMgr = TypeMgr.init(ctx);
    var visited_types: List(*Inst) = .{};
    var visited_forward_pointers: List(*const Type) = .{};
    var to_delete: List(*Inst) = .{};

    var cur: ?*Inst = ctx.module.types_values.first;
    while (cur) |i| : (cur = i.next) {
        const is_i_forward_pointer: bool = i.op == .OpTypeForwardPointer;
        if (!opGeneratesType(i.op) and !is_i_forward_pointer) continue;

        if (!is_i_forward_pointer) {
            var id_to_keep: u32 = 0;
            const i_type: *Type = type_manager.getType(i.resultId()) orelse fatal("remove-duplicates: type %{d} is unknown", .{i.resultId()});
            for (visited_types.items) |j| {
                const j_type: *Type = type_manager.getType(j.resultId()) orelse fatal("remove-duplicates: type %{d} is unknown", .{j.resultId()});
                if (i_type.isSame(j_type)) {
                    id_to_keep = j.resultId();
                    break;
                }
            }
            if (id_to_keep == 0) {
                visited_types.push(i);
            } else {
                ctx.killNamesAndDecoratesId(i.resultId());
                _ = ctx.replaceAllUsesWith(i.resultId(), id_to_keep);
                modified = true;
                to_delete.push(i);
            }
        } else {
            var i_type = Type.forwardPointer(i.getSingleWordInOperand(0), i.getSingleWordInOperand(1));
            const target_id: u32 = i_type.data.forward_pointer.target_id;
            const target: *Type = type_manager.getType(target_id) orelse fatal("remove-duplicates: type %{d} is unknown", .{target_id});
            if (target.kind() == .pointer) i_type.data.forward_pointer.pointer = target;
            const boxed: *Type = i_type.boxed();
            var found_a_match: bool = false;
            for (visited_forward_pointers.items) |v| {
                if (v.isSame(boxed)) {
                    found_a_match = true;
                    break;
                }
            }
            if (!found_a_match) {
                visited_forward_pointers.push(boxed);
            } else {
                modified = true;
                to_delete.push(i);
            }
        }
    }
    for (to_delete.items) |i| _ = ctx.killInst(i);
    return modified;
}

/// Removes decorations that repeat an earlier one.
fn rdRemoveDuplicateDecorations(ctx: *Ctx) bool {
    var modified: bool = false;
    var visited_decorations: List(*const Inst) = .{};
    const decoration_manager: *DecorMgr = ctx.getDecorationMgr();
    var cur: ?*Inst = ctx.module.annotations.first;
    while (cur) |i| {
        var already_visited: bool = false;
        for (visited_decorations.items) |j| {
            if (decoration_manager.areDecorationsTheSame(i, j, false)) {
                already_visited = true;
                break;
            }
        }
        if (!already_visited) {
            visited_decorations.push(i);
            cur = i.next;
        } else {
            modified = true;
            cur = ctx.killInst(i);
        }
    }
    return modified;
}

/// --remove-duplicates: removes repeated capabilities, extensions, extended instruction set imports, types and
/// decorations, in that order.
pub const RemoveDuplicates = struct {
    pub const name = "remove-duplicates";
    pub const preserved: u32 = Analysis.none;

    pub fn run(self: *RemoveDuplicates, ctx: *Ctx) PassStatus {
        _ = self;
        var modified: bool = rdRemoveDuplicateCapabilities(ctx);
        if (rdRemoveDuplicateExtensions(ctx)) modified = true;
        if (rdRemoveDuplicatesExtInstImports(ctx)) modified = true;
        if (rdRemoveDuplicateTypes(ctx)) modified = true;
        if (rdRemoveDuplicateDecorations(ctx)) modified = true;
        return if (modified) .success_with_change else .success_without_change;
    }
};

// ---------------------------------------------------------------------------------------------
// FlattenDecoration (flatten_decoration_pass.cpp)
// ---------------------------------------------------------------------------------------------

/// --flatten-decorations: replaces decoration groups by the individual OpDecorate and OpMemberDecorate instructions they
/// stand for, and removes OpDecorationGroup, OpGroupDecorate, OpGroupMemberDecorate and the names of the groups.
pub const FlattenDecoration = struct {
    pub const name = "flatten-decorations";
    pub const preserved: u32 = Analysis.none;

    pub fn run(self: *FlattenDecoration, ctx: *Ctx) PassStatus {
        _ = self;
        var modified: bool = false;
        var group_ids: Set(u32) = .{};
        var normal_uses: Map(u32, List(u32)) = .{};
        var member_uses: Map(u32, List(u32)) = .{};

        var ia: ?*Inst = ctx.module.annotations.first;
        while (ia) |inst| : (ia = inst.next) {
            switch (inst.op) {
                .OpDecorationGroup => {
                    _ = group_ids.insert(inst.resultId());
                },
                .OpGroupDecorate => {
                    const gop: Map(u32, List(u32)).GetOrPutResult = normal_uses.getOrPut(inst.getSingleWordInOperand(0));
                    if (!gop.found_existing) gop.value_ptr.* = .{};
                    var i: usize = 1;
                    while (i < inst.numInOperandWords()) : (i += 1) gop.value_ptr.push(inst.getSingleWordInOperand(i));
                },
                .OpGroupMemberDecorate => {
                    const gop: Map(u32, List(u32)).GetOrPutResult = member_uses.getOrPut(inst.getSingleWordInOperand(0));
                    if (!gop.found_existing) gop.value_ptr.* = .{};
                    var i: usize = 1;
                    while (i < inst.numInOperandWords()) : (i += 1) gop.value_ptr.push(inst.getSingleWordInOperand(i));
                },
                else => {},
            }
        }

        var cur: ?*Inst = ctx.module.annotations.first;
        while (cur) |inst| {
            var replace: bool = false;
            switch (inst.op) {
                .OpDecorationGroup, .OpGroupDecorate, .OpGroupMemberDecorate => replace = true,
                .OpDecorate => {
                    const group: u32 = inst.getSingleWordOperand(0);
                    if (normal_uses.getPtr(group)) |targets| {
                        for (targets.items) |target| {
                            const new_inst: *Inst = inst.clone();
                            new_inst.setInOperand(0, &.{target});
                            ctx.module.annotations.insertBefore(inst, new_inst);
                            replace = true;
                        }
                    }
                    if (member_uses.getPtr(group)) |member_id_pairs| {
                        check(member_id_pairs.len() % 2 == 0, "flatten-decorations: odd number of words in an OpGroupMemberDecorate");
                        var k: usize = 0;
                        while (k < member_id_pairs.len()) : (k += 2) {
                            const target: u32 = member_id_pairs.items[k];
                            const member: u32 = member_id_pairs.items[k + 1];
                            var operands: List(Operand) = .{};
                            operands.push(Operand.id(.IdRef, target));
                            operands.push(Operand.single(.LiteralInteger, member));
                            var oi: usize = 1;
                            while (oi < inst.numOperands()) : (oi += 1) {
                                const o: *Operand = inst.getOperand(oi);
                                operands.push(Operand.fromWords(o.kind, o.words()));
                            }
                            const new_inst: *Inst = Inst.make(.OpMemberDecorate, 0, 0, operands.items);
                            ctx.module.annotations.insertBefore(inst, new_inst);
                            replace = true;
                        }
                    }
                    if (!replace and group_ids.contains(group)) replace = true;
                },
                else => {},
            }
            const next_instruction: ?*Inst = inst.next;
            if (replace) {
                ctx.module.annotations.unlink(inst);
                modified = true;
            }
            cur = next_instruction;
        }

        if (group_ids.count() != 0) {
            var d: ?*Inst = ctx.module.debugs2.first;
            while (d) |inst| {
                if (inst.op != .OpName) {
                    // the C++ loop only advances on OpName / erase and therefore never terminates here
                    fatal("flatten-decorations: the debug section holds an {s} while decoration groups exist (the C++ pass loops forever)", .{@tagName(inst.op)});
                }
                const next_instruction: ?*Inst = inst.next;
                if (group_ids.contains(inst.getSingleWordOperand(0))) {
                    ctx.module.debugs2.unlink(inst);
                    modified = true;
                }
                d = next_instruction;
            }
        }
        return if (modified) .success_with_change else .success_without_change;
    }
};

// BlockMerge (block_merge_pass.cpp, block_merge_util.cpp), which merges a block into its only predecessor, and
// WrapOpKill (wrap_opkill.cpp), which replaces OpKill by a call to a function that kills.

// ---------------------------------------------------------------------------------------------
// block_merge_util
// ---------------------------------------------------------------------------------------------

/// Returns true if |block| contains a merge instruction.
fn bmIsHeader(block: *Block) bool {
    return block.getMergeInst() != null;
}

fn bmIsHeaderId(ctx: *Ctx, id: u32) bool {
    const def: *Inst = ctx.getDefUseMgr().getDef(id) orelse fatal("BlockMerge: id %{d} is not defined", .{id});
    const blk: *Block = def.block orelse fatal("BlockMerge: %{d} is not in a block", .{id});
    return bmIsHeader(blk);
}

/// Returns true if |id| is the merge target of a merge instruction.
fn bmIsMergeId(ctx: *Ctx, id: u32) bool {
    var uses: DefUseMgr.UseIter = ctx.getDefUseMgr().usesOfId(id);
    while (uses.next()) |use| {
        if ((use.user.op == .OpLoopMerge or use.user.op == .OpSelectionMerge) and use.index == 0) return true;
    }
    return false;
}

/// Returns true if |id| is the continue target of a merge instruction.
fn bmIsContinueId(ctx: *Ctx, id: u32) bool {
    var uses: DefUseMgr.UseIter = ctx.getDefUseMgr().usesOfId(id);
    while (uses.next()) |use| {
        if (use.user.op == .OpLoopMerge and use.index == 1) return true;
    }
    return false;
}

pub fn blockMergeCanMergeWithSuccessor(ctx: *Ctx, block: *Block) bool {
    // Find block with single successor which has no other predecessors.
    const br: *Inst = block.insts.last.?;
    if (br.op != .OpBranch) return false;

    const lab_id: u32 = br.getSingleWordInOperand(0);
    if (ctx.cfg().preds(lab_id).len != 1) return false;

    const pred_is_merge: bool = bmIsMergeId(ctx, block.id());
    const succ_is_merge: bool = bmIsMergeId(ctx, lab_id);
    if (pred_is_merge and succ_is_merge) return false; // Cannot merge two merges together.

    // The instructions in a break block would execute as if they were still diverged according to the loop iteration.
    if (succ_is_merge and ctx.getFeatureMgr().hasExtension(.SPV_KHR_maximal_reconvergence)) return false;

    if (pred_is_merge and bmIsContinueId(ctx, lab_id)) return false; // Cannot merge a continue target with a merge block.

    const merge_inst: ?*Inst = block.getMergeInst();
    const pred_is_header: bool = bmIsHeader(block);
    if (pred_is_header and lab_id != merge_inst.?.getSingleWordInOperand(0)) {
        const succ_is_header: bool = bmIsHeaderId(ctx, lab_id);
        if (pred_is_header and succ_is_header) return false; // Cannot merge two headers together.

        // A header whose successor is not its merge: OpLoopMerge must be followed by a conditional or unconditional
        // branch, so the merged block must end in one of these.
        const succ_block: *Block = ctx.getInstrBlockById(lab_id).?;
        const succ_term_op: Op = succ_block.terminator().?.op;
        if (succ_term_op != .OpBranch and succ_term_op != .OpBranchConditional) return false;
    }

    if (succ_is_merge or bmIsContinueId(ctx, lab_id)) {
        const struct_cfg: *StructCfg = ctx.getStructuredCfgAnalysis();
        const switch_block_id: u32 = struct_cfg.containingSwitch(block.id());
        if (switch_block_id != 0) {
            const switch_merge_id: u32 = struct_cfg.switchMergeBlock(switch_block_id);
            const switch_inst: *Inst = block.parent.?.findBlock(switch_block_id).?.tail();
            var i: usize = 1;
            while (i < switch_inst.numInOperands()) : (i += 2) {
                const target_id: u32 = switch_inst.getSingleWordInOperand(i);
                if (target_id == block.id() and target_id != switch_merge_id) {
                    // Case constructs must be structurally dominated by the OpSwitch.
                    return false;
                }
            }
        }
    }
    return true;
}

/// Removes any OpPhi instructions in |block|, which has exactly one predecessor, replacing uses of the OpPhi ids with
/// the values associated with the predecessor.
fn bmEliminateOpPhiInstructions(ctx: *Ctx, block: *Block) void {
    var it: ?*Inst = block.insts.first;
    while (it) |phi| {
        const nxt: ?*Inst = phi.next;
        if (phi.op != .OpPhi) break;
        check(phi.numInOperands() == 2, "A block can only have one predecessor for block merging to make sense.");
        _ = ctx.replaceAllUsesWith(phi.resultId(), phi.getSingleWordInOperand(0));
        _ = ctx.killInst(phi);
        it = nxt;
    }
}

/// MergeWithSuccessor: `bi` is the index of the block in `func`.
pub fn blockMergeMergeWithSuccessor(ctx: *Ctx, func: *Func, bi: usize) void {
    check(blockMergeCanMergeWithSuccessor(ctx, func.blocks.items[bi]), "Precondition failure for MergeWithSuccessor: it must be legal to merge the block and its successor.");
    const block: *Block = func.blocks.items[bi];
    const br: *Inst = block.insts.last.?;
    const lab_id: u32 = br.getSingleWordInOperand(0);
    const merge_inst: ?*Inst = block.getMergeInst();
    const pred_is_header: bool = bmIsHeader(block);

    // Merge blocks.
    _ = ctx.killInst(br);
    var sbi: usize = bi;
    while (sbi < func.blocks.len()) : (sbi += 1) {
        if (func.blocks.items[sbi].id() == lab_id) break;
    }
    // If bi is sbi's only predecessor, it dominates sbi and thus sbi must follow bi in the function's ordering.
    check(sbi < func.blocks.len(), "BlockMerge: the successor block is not after the block");
    const succ: *Block = func.blocks.items[sbi];

    if (succ.tail().op == .OpSwitch and succ.mergeBlockIdIfAny() != 0) {
        ctx.invalidateAnalyses(Analysis.structured_cfg);
    }

    bmEliminateOpPhiInstructions(ctx, succ);

    // Now actually move the instructions (Inst.block is updated by the list).
    block.addInstructions(succ);

    if (merge_inst) |mi| {
        if (pred_is_header and lab_id == mi.getSingleWordInOperand(0)) {
            // Merging the header and merge blocks: remove the structured control flow declaration.
            _ = ctx.killInst(mi);
        } else {
            // Move OpLine/OpNoLine information to the merge instruction (avoids OpLine between OpLoopMerge and
            // OpBranchConditional).
            const terminator: *Inst = block.terminator().?;
            if (terminator.dbg_lines.len() > 0) {
                const du: *DefUseMgr = ctx.getDefUseMgr();
                // merge_inst->ClearDbgLineInsts()
                if (ctx.areAnalysesValid(Analysis.def_use)) {
                    for (mi.dbg_lines.items) |l| du.clearInst(l);
                }
                mi.dbg_lines.clear();
                for (terminator.dbg_lines.items) |l| mi.dbg_lines.push(l);
                // terminator->ClearDbgLineInsts()
                if (ctx.areAnalysesValid(Analysis.def_use)) {
                    for (terminator.dbg_lines.items) |l| du.clearInst(l);
                }
                terminator.dbg_lines.clear();
                for (mi.dbg_lines.items) |l| du.analyzeInstDefUse(l);
            }
            // Move the merge instruction to just before the terminator.
            mi.moveBefore(terminator);
        }
    }
    _ = ctx.replaceAllUsesWith(lab_id, block.id());
    _ = ctx.killInst(succ.label);
    _ = func.blocks.orderedRemove(sbi);
}

// ---------------------------------------------------------------------------------------------
// BlockMergePass
// ---------------------------------------------------------------------------------------------

/// --merge-blocks: merges a block that ends in an unconditional branch with its successor when it is the only predecessor
/// of that successor. Merges that would break a structured construct are refused (two merge blocks, two headers, a
/// merge block and a continue target, ...).
pub const BlockMerge = struct {
    pub const name = "merge-blocks";
    pub const preserved: u32 = Analysis.def_use | Analysis.instr_to_block | Analysis.decorations | Analysis.combinators |
        Analysis.name_map | Analysis.constants | Analysis.types;

    fn mergeBlocks(ctx: *Ctx, func: *Func) bool {
        var modified: bool = false;
        var bi: usize = 0;
        while (bi < func.blocks.len()) {
            const b: *Block = func.blocks.items[bi];
            // Don't bother trying to merge unreachable blocks.
            if (ctx.isReachable(b) and blockMergeCanMergeWithSuccessor(ctx, b)) {
                blockMergeMergeWithSuccessor(ctx, func, bi);
                // Reprocess block.
                modified = true;
            } else {
                bi += 1;
            }
        }
        return modified;
    }

    pub fn run(self: *BlockMerge, ctx: *Ctx) PassStatus {
        _ = self;
        const modified: bool = ctx.processReachableCallTree(ctx, mergeBlocks);
        return if (modified) .success_with_change else .success_without_change;
    }
};

/// Instruction::AddDebugLine + UpdateDebugInfoFrom (the line part; there is no DebugScope in this port).
pub fn instUpdateDebugInfoFrom(ctx: *Ctx, inst: *Inst, from: ?*const Inst, line: ?*const Inst) void {
    const f: *const Inst = from orelse return;
    // ClearDbgLineInsts
    if (ctx.areAnalysesValid(Analysis.def_use)) {
        const du: *DefUseMgr = ctx.getDefUseMgr();
        for (inst.dbg_lines.items) |l| du.clearInst(l);
    }
    inst.dbg_lines.clear();
    const from_line: *const Inst = line orelse f;
    if (from_line.dbg_lines.len() != 0) {
        const copy: *Inst = from_line.dbg_lines.last().clone();
        inst.dbg_lines.push(copy);
        if (ctx.areAnalysesValid(Analysis.def_use)) ctx.getDefUseMgr().analyzeInstDefUse(copy);
    }
}

// ---------------------------------------------------------------------------------------------
// WrapOpKill
// ---------------------------------------------------------------------------------------------

/// --wrap-opkill: in the functions called from a loop continue construct, replaces every OpKill and OpTerminateInvocation by
/// a call to a generated function that contains just that instruction, followed by a return (of an undefined value
/// when the caller returns one). A continue construct may not contain a terminating instruction directly.
pub const WrapOpKill = struct {
    pub const name = "wrap-opkill";
    pub const preserved: u32 = Analysis.def_use | Analysis.instr_to_block | Analysis.decorations | Analysis.combinators |
        Analysis.name_map | Analysis.builtin_var_id | Analysis.constants | Analysis.types;

    const State = struct {
        ctx: *Ctx,
        void_type_id: u32 = 0,
        opkill_function: ?*Func = null,
        opterminateinvocation_function: ?*Func = null,
        modified: bool = false,
    };

    fn getVoidTypeId(st: *State) u32 {
        if (st.void_type_id != 0) return st.void_type_id;
        const void_type = Type.simple(.void_);
        st.void_type_id = st.ctx.getTypeMgr().getTypeInstruction(&void_type);
        return st.void_type_id;
    }

    fn getVoidFunctionTypeId(st: *State) u32 {
        const type_mgr: *TypeMgr = st.ctx.getTypeMgr();
        const void_type = Type.simple(.void_);
        const registered_void_type: *Type = type_mgr.getRegisteredType(&void_type).?;
        const func_type = Type.function(registered_void_type, &.{});
        return type_mgr.getTypeInstruction(&func_type);
    }

    fn getKillingFuncId(st: *State, opcode: Op) u32 {
        const ctx: *Ctx = st.ctx;
        const killing_func: *?*Func = if (opcode == .OpKill) &st.opkill_function else &st.opterminateinvocation_function;
        if (killing_func.*) |f| return f.id();

        const killing_func_id: u32 = ctx.takeNextId();
        if (killing_func_id == 0) return 0;

        const void_type_id: u32 = getVoidTypeId(st);
        if (void_type_id == 0) return 0;

        // Generate the function start instruction
        const func_start: *Inst = Inst.make(.OpFunction, void_type_id, killing_func_id, &.{
            Operand.single(.FunctionControl, 0),
            Operand.id(.IdRef, getVoidFunctionTypeId(st)),
        });
        const f: *Func = Func.new(func_start);
        killing_func.* = f;

        // Generate the function end instruction
        f.setFunctionEnd(Inst.make(.OpFunctionEnd, 0, 0, &.{}));

        // Create the one basic block for the function.
        const lab_id: u32 = ctx.takeNextId();
        if (lab_id == 0) return 0;
        const bb: *Block = Block.new(Inst.make(.OpLabel, 0, lab_id, &.{}));

        // Add the OpKill to the basic block
        bb.addInst(Inst.make(opcode, 0, 0, &.{}));

        // Add the bb to the function
        f.addBlock(bb);

        // Add the function to the module.
        if (ctx.areAnalysesValid(Analysis.def_use)) {
            f.forEachInst(ctx, wrapAnalyzeDefUse, false, false);
        }
        return f.id();
    }

    fn wrapAnalyzeDefUse(ctx: *Ctx, inst: *Inst) void {
        ctx.analyzeDefUse(inst);
    }

    fn replaceWithFunctionCall(st: *State, inst: *Inst) bool {
        const ctx: *Ctx = st.ctx;
        const ir_builder = InstBuilder.init(ctx, inst, Analysis.def_use | Analysis.instr_to_block);
        const func_id: u32 = getKillingFuncId(st, inst.op);
        if (func_id == 0) return false;
        const call_inst: *Inst = ir_builder.addFunctionCall(getVoidTypeId(st), func_id, &.{}) orelse return false;
        instUpdateDebugInfoFrom(ctx, call_inst, inst, null);

        const bb: ?*Block = ctx.getInstrBlock(inst);
        const return_type_id: u32 = if (bb) |b| b.parent.?.typeId() else 0;
        var return_inst: ?*Inst = null;
        if (return_type_id != getVoidTypeId(st)) {
            const undef: *Inst = ir_builder.addNullaryOp(return_type_id, .OpUndef) orelse return false;
            return_inst = ir_builder.addUnaryOp(0, .OpReturnValue, undef.resultId());
        } else {
            return_inst = ir_builder.addNullaryOp(0, .OpReturn);
        }
        if (return_inst == null) return false;

        _ = ctx.killInst(inst);
        return true;
    }

    fn visitInst(st: *State, inst: *Inst) bool {
        if (inst.op == .OpKill or inst.op == .OpTerminateInvocation) {
            st.modified = true;
            if (!replaceWithFunctionCall(st, inst)) return false;
        }
        return true;
    }

    pub fn run(self: *WrapOpKill, ctx: *Ctx) PassStatus {
        _ = self;
        var st: State = .{ .ctx = ctx };
        const func_to_process: StdUSet32 = ctx.getStructuredCfgAnalysis().findFuncsCalledFromContinue();
        for (func_to_process.items()) |func_id| {
            const func: *Func = ctx.getFunction(func_id) orelse fatal("WrapOpKill: no function %{d}", .{func_id});
            if (!func.whileEachInst(&st, visitInst, false, false)) return .failure;
        }
        if (st.opkill_function) |f| {
            check(st.modified, "The function should only be generated if something was modified.");
            ctx.addFunction(f);
        }
        if (st.opterminateinvocation_function) |f| {
            check(st.modified, "The function should only be generated if something was modified.");
            ctx.addFunction(f);
        }
        return if (st.modified) .success_with_change else .success_without_change;
    }
};

/// The instruction that defines `id`.
fn memDef(ctx: *Ctx, id: u32) *Inst {
    return ctx.getDefUseMgr().getDef(id) orelse fatal("MemPass: id %{d} is not defined", .{id});
}

// ---------------------------------------------------------------------------------------------
// PrivateToLocal
// ---------------------------------------------------------------------------------------------

/// --private-to-local: a Private variable that only one function uses becomes a Function variable of that function (at the
/// start of its first block), and the pointer types derived from it are updated.
pub const PrivateToLocal = struct {
    pub const name = "private-to-local";
    pub const preserved: u32 = Analysis.def_use | Analysis.instr_to_block | Analysis.decorations | Analysis.combinators |
        Analysis.cfg | Analysis.dominator | Analysis.name_map | Analysis.constants | Analysis.types;

    const MoveItem = struct { inst: *Inst, func: *Func };

    fn findLocalFunction(ctx: *Ctx, inst: *const Inst) ?*Func {
        const var_id: u32 = inst.resultId();
        var target_function: ?*Func = null;
        var found_first_use: bool = false;
        for (ctx.getDefUseMgr().registeredUsers(inst)) |use| {
            const current_block: *Block = ctx.getInstrBlock(use) orelse continue;
            if (!isValidUse(ctx, use, var_id)) {
                found_first_use = true;
                target_function = null;
                continue;
            }
            const current_function: *Func = current_block.parent.?;
            if (!found_first_use) {
                found_first_use = true;
                target_function = current_function;
            } else if (target_function != current_function) {
                target_function = null;
            }
        }
        return target_function;
    }

    fn isValidUse(ctx: *Ctx, inst: *const Inst, private_variable_id: u32) bool {
        // The cases in this switch have to match the cases in updateUse. If we don't know how to update it, it is not valid.
        switch (inst.op) {
            .OpLoad, .OpImageTexelPointer => return true,
            .OpStore => return inst.getOperand(1).asId() != private_variable_id,
            .OpAccessChain => {
                for (ctx.getDefUseMgr().registeredUsers(inst)) |user| {
                    if (!isValidUse(ctx, user, inst.resultId())) return false;
                }
                return true;
            },
            .OpName => return true,
            else => return opIsDecoration(inst.op),
        }
    }

    fn getNewType(ctx: *Ctx, old_type_id: u32) u32 {
        const type_mgr: *TypeMgr = ctx.getTypeMgr();
        const old_type_inst: *Inst = memDef(ctx, old_type_id);
        const pointee_type_id: u32 = old_type_inst.getSingleWordInOperand(1);
        const new_type_id: u32 = type_mgr.findPointerToType(pointee_type_id, @intFromEnum(StorageClass.Function));
        if (new_type_id != 0) ctx.updateDefUse(memDef(ctx, new_type_id));
        return new_type_id;
    }

    fn updateUse(ctx: *Ctx, inst: *Inst) bool {
        switch (inst.op) {
            .OpLoad, .OpStore, .OpImageTexelPointer => {},
            .OpAccessChain => {
                ctx.forgetUses(inst);
                const new_type_id: u32 = getNewType(ctx, inst.typeId());
                if (new_type_id == 0) return false;
                inst.setResultType(new_type_id);
                ctx.analyzeUses(inst);
                // Update uses where the type may have changed.
                if (!updateUses(ctx, inst)) return false;
            },
            .OpName, .OpEntryPoint => {},
            else => {},
        }
        return true;
    }

    fn updateUses(ctx: *Ctx, inst: *Inst) bool {
        var uses: List(*Inst) = .{};
        uses.pushSlice(ctx.getDefUseMgr().usersOf(inst));
        for (uses.items) |use| {
            if (!updateUse(ctx, use)) return false;
        }
        return true;
    }

    fn moveVariable(ctx: *Ctx, variable: *Inst, function: *Func) bool {
        // The variable needs to be removed from the global section, and placed in the header of the function.
        _ = variable.removeFromList();
        ctx.forgetUses(variable);

        // Update the storage class of the variable.
        variable.setInOperand(0, &.{@intFromEnum(StorageClass.Function)});

        // Update the type as well.
        const new_type_id: u32 = getNewType(ctx, variable.typeId());
        if (new_type_id == 0) return false;
        variable.setResultType(new_type_id);

        // Place the variable at the start of the first basic block.
        ctx.analyzeUses(variable);
        const entry: *Block = function.entry();
        entry.insts.insertBefore(entry.insts.first.?, variable);

        // Update uses where the type may have changed.
        return updateUses(ctx, variable);
    }

    pub fn run(self: *PrivateToLocal, ctx: *Ctx) PassStatus {
        _ = self;
        // Private variables require the shader capability. If this is not a shader, there is no work to do.
        if (ctx.getFeatureMgr().hasCapability(.Addresses)) return .success_without_change;

        var variables_to_move: List(MoveItem) = .{};
        var localized_variables: Set(u32) = .{};
        var it: ?*Inst = ctx.module.types_values.first;
        while (it) |inst| : (it = inst.next) {
            if (inst.op != .OpVariable) continue;
            if (inst.getSingleWordInOperand(0) != @intFromEnum(StorageClass.Private)) continue;
            if (findLocalFunction(ctx, inst)) |target_function| {
                variables_to_move.push(.{ .inst = inst, .func = target_function });
            }
        }

        const modified: bool = variables_to_move.len() != 0;
        for (variables_to_move.items) |p| {
            if (!moveVariable(ctx, p.inst, p.func)) return .failure;
            _ = localized_variables.insert(p.inst.resultId());
        }

        if (ctx.module.header.version >= 0x00010400) {
            // In SPIR-V 1.4 and later entry points must list private storage class variables that are statically used by
            // the entry point. Remove any references to variables that were localized.
            var ep: ?*Inst = ctx.module.entry_points.first;
            while (ep) |entry| : (ep = entry.next) {
                var new_operands: List(Operand) = .{};
                for (0..entry.numInOperands()) |i| {
                    // Execution model, function id and name are always kept.
                    if (i < 3 or !localized_variables.contains(entry.getSingleWordInOperand(i))) {
                        new_operands.push(entry.getInOperand(i).*);
                    }
                }
                if (new_operands.len() != entry.numInOperands()) {
                    entry.setInOperands(new_operands.items);
                    ctx.analyzeUses(entry);
                }
            }
        }
        return if (modified) .success_with_change else .success_without_change;
    }
};

// MemPass helpers (mem_pass.cpp), shared by the passes that rewrite loads and stores of function-local variables, and
// PrivateToLocal (private_to_local_pass.cpp)
//
// The C++ MemPass is a base class of several passes holding three sets/maps; here those live in `MemState`, which
// each derived pass owns (re-initialised at the start of `run`), and the member functions are free functions
// taking `ctx` and, when needed, the state.

/// The state the C++ MemPass base class holds for its derived passes: which variables were seen as targets /
/// non-targets and the OpUndef created per type.
pub const MemState = struct {
    seen_target_vars: Set(u32) = .{},
    seen_non_target_vars: Set(u32) = .{},
    type2undefs: Map(u32, u32) = .{},
};

/// True for the access chains that are not pointer access chains (no extra leading element index).
pub fn memIsNonPtrAccessChain(op: Op) bool {
    return op == .OpAccessChain or op == .OpInBoundsAccessChain or op == .OpUntypedAccessChainKHR;
}

/// True for the decorations that apply to a whole id (OpDecorate, OpDecorateId), not to a struct member.
pub fn memIsNonTypeDecorate(op: Op) bool {
    return op == .OpDecorate or op == .OpDecorateId;
}

/// MemPass::GetPtr(ptrId, &varId): returns the pointer instruction (copies skipped); `var_id` receives the id of the
/// OpVariable at the base of the pointer, or 0.
pub fn memGetPtr(ctx: *Ctx, ptr_id: u32, var_id: *u32) *Inst {
    var_id.* = ptr_id;
    var ptr_inst: *Inst = memDef(ctx, var_id.*);
    var var_inst: *Inst = undefined;
    switch (ptr_inst.op) {
        .OpVariable, .OpUntypedVariableKHR, .OpFunctionParameter => var_inst = ptr_inst,
        .OpAccessChain,
        .OpInBoundsAccessChain,
        .OpUntypedAccessChainKHR,
        .OpPtrAccessChain,
        .OpInBoundsPtrAccessChain,
        .OpImageTexelPointer,
        .OpCopyObject,
        => var_inst = instGetBaseAddress(ctx, ptr_inst),
        else => {
            var_id.* = 0;
            return ptr_inst;
        },
    }
    if (var_inst.op == .OpVariable or var_inst.op == .OpUntypedVariableKHR) {
        var_id.* = var_inst.resultId();
    } else {
        var_id.* = 0;
    }
    while (ptr_inst.op == .OpCopyObject) {
        const temp: u32 = ptr_inst.getSingleWordInOperand(0);
        ptr_inst = memDef(ctx, temp);
    }
    return ptr_inst;
}

/// MemPass::GetPtr(Instruction* ip, &varId)
pub fn memGetPtrOfInst(ctx: *Ctx, ip: *const Inst, var_id: *u32) *Inst {
    return memGetPtr(ctx, ip.getSingleWordInOperand(0), var_id);
}

/// True for the types that the local memory passes can promote to SSA values without looking inside: scalars, vectors,
/// matrices, images, samplers, pointers and cooperative matrices.
pub fn memIsBaseTargetType(type_inst: *const Inst) bool {
    return switch (type_inst.op) {
        .OpTypeInt,
        .OpTypeFloat,
        .OpTypeBool,
        .OpTypeVector,
        .OpTypeMatrix,
        .OpTypeImage,
        .OpTypeSampler,
        .OpTypeSampledImage,
        .OpTypePointer,
        .OpTypeCooperativeMatrixNV,
        .OpTypeCooperativeMatrixKHR,
        => true,
        else => false,
    };
}

/// True for a type the local memory passes can handle: a base target type, or an array or struct made only of target
/// types.
pub fn memIsTargetType(ctx: *Ctx, type_inst: *const Inst) bool {
    if (memIsBaseTargetType(type_inst)) return true;
    if (type_inst.op == .OpTypeArray) {
        return memIsTargetType(ctx, memDef(ctx, type_inst.getSingleWordOperand(1)));
    }
    if (type_inst.op != .OpTypeStruct) return false;
    for (0..type_inst.numInOperands()) |k| {
        const op: *Operand = type_inst.getInOperand(k);
        if (!kindIsId(op.kind)) continue;
        if (!memIsTargetType(ctx, memDef(ctx, op.word0()))) return false;
    }
    return true;
}

/// True when `var_id` is a Function variable of a target type. The answers are cached in the state.
pub fn memIsTargetVar(ctx: *Ctx, st: *MemState, var_id: u32) bool {
    if (var_id == 0) return false;
    if (st.seen_non_target_vars.contains(var_id)) return false;
    if (st.seen_target_vars.contains(var_id)) return true;
    const var_inst: *Inst = memDef(ctx, var_id);
    if (var_inst.op != .OpVariable) return false;
    const var_type_inst: *Inst = memDef(ctx, var_inst.typeId());
    if (var_type_inst.getSingleWordInOperand(0) != @intFromEnum(StorageClass.Function)) {
        _ = st.seen_non_target_vars.insert(var_id);
        return false;
    }
    const var_pte_type_inst: *Inst = memDef(ctx, var_type_inst.getSingleWordInOperand(1));
    if (!memIsTargetType(ctx, var_pte_type_inst)) {
        _ = st.seen_non_target_vars.insert(var_id);
        return false;
    }
    _ = st.seen_target_vars.insert(var_id);
    return true;
}

