/// True when `name` is in the allowlist (std::unordered_set<std::string>::find).
fn extAllowed(list: []const []const u8, name: []const u8) bool {
    for (list) |e| {
        if (std.mem.eql(u8, e, name)) return true;
    }
    return false;
}

/// The shared part of the four `AllExtensionsSupported` implementations: every OpExtension must be allowlisted, and the
/// only NonSemantic extended instruction sets allowed are NonSemantic.Shader.DebugInfo.* (and, for AggressiveDCE,
/// NonSemantic.DebugPrintf).
pub fn passAllExtensionsSupported(ctx: *Ctx, list: []const []const u8, allow_debug_printf: bool) bool {
    var e: ?*Inst = ctx.module.extensions.first;
    while (e) |ei| : (e = ei.next) {
        if (!extAllowed(list, ei.getInOperand(0).asString())) return false;
    }
    var i: ?*Inst = ctx.module.ext_inst_imports.first;
    while (i) |inst| : (i = inst.next) {
        const extension_name: []const u8 = inst.getInOperand(0).asString();
        if (std.mem.startsWith(u8, extension_name, "NonSemantic.") and
            !std.mem.startsWith(u8, extension_name, "NonSemantic.Shader.DebugInfo.") and
            !(allow_debug_printf and std.mem.eql(u8, extension_name, "NonSemantic.DebugPrintf")))
        {
            return false;
        }
    }
    return true;
}

// Three passes over function-local variables whose address does not escape:
//   LocalSingleBlockLoadStoreElim (local_single_block_elim_pass.cpp): removes loads and stores that are redundant within
//                    one block (a load of a value just stored, a store overwritten before it is read);
//   LocalSingleStoreElim (local_single_store_elim_pass.cpp): replaces the loads of a variable that is stored exactly once
//                    by the stored value, where the store dominates the load;
//   LocalAccessChainConvert (local_access_chain_convert_pass.cpp): replaces loads and stores through access chains by a
//                    load / store of the whole variable and OpCompositeExtract / OpCompositeInsert.

fn lmModuleHasGroupDecorate(ctx: *Ctx) bool {
    var it: ?*Inst = ctx.module.annotations.first;
    while (it) |ai| : (it = ai.next) {
        if (ai.op == .OpGroupDecorate) return true;
    }
    return false;
}

// ---------------------------------------------------------------------------------------------
// LocalSingleBlockLoadStoreElim
// ---------------------------------------------------------------------------------------------

pub const LocalSingleBlockLoadStoreElim = struct {
    pub const name = "eliminate-local-single-block";
    pub const preserved: u32 = Analysis.def_use | Analysis.instr_to_block | Analysis.constants | Analysis.types;

    mem: MemState = .{},
    supported_ref_ptrs: Set(u32) = .{},
    var2store: Map(u32, *Inst) = .{},
    var2load: Map(u32, *Inst) = .{},

    const Runner = struct { ctx: *Ctx, pass: *LocalSingleBlockLoadStoreElim };

    fn hasOnlySupportedRefs(self: *LocalSingleBlockLoadStoreElim, ctx: *Ctx, ptr_id: u32) bool {
        if (self.supported_ref_ptrs.contains(ptr_id)) return true;
        for (ctx.getDefUseMgr().registeredUsersOfId(ptr_id)) |user| {
            const op: Op = user.op;
            if (memIsNonPtrAccessChain(op) or op == .OpCopyObject) {
                if (!self.hasOnlySupportedRefs(ctx, user.resultId())) return false;
            } else if (op != .OpStore and op != .OpLoad and op != .OpName and !memIsNonTypeDecorate(op)) {
                return false;
            }
        }
        _ = self.supported_ref_ptrs.insert(ptr_id);
        return true;
    }

    fn processFunction(r: *Runner, func: *Func) bool {
        const self: *LocalSingleBlockLoadStoreElim = r.pass;
        const ctx: *Ctx = r.ctx;
        // Perform local store/load, load/load and store/store elimination on each block
        var modified: bool = false;
        var instructions_to_kill: List(*Inst) = .{};
        var instructions_to_save: Set(*Inst) = .{};
        for (func.blocks.items) |bb| {
            self.var2store.clear();
            self.var2load.clear();
            var it: ?*Inst = bb.insts.first;
            while (it) |ii| {
                const next: ?*Inst = ii.next;
                it = next;
                switch (ii.op) {
                    .OpStore => {
                        // Verify store variable is target type
                        var var_id: u32 = 0;
                        const ptr_inst: *Inst = memGetPtrOfInst(ctx, ii, &var_id);
                        if (!memIsTargetVar(ctx, &self.mem, var_id)) continue;
                        if (!hasOnlySupportedRefs(self, ctx, var_id)) continue;
                        // If a store to the whole variable, remember it for succeeding loads and stores. Otherwise
                        // forget any previous store to that variable.
                        if (ptr_inst.op == .OpVariable) {
                            // If a previous store to the same variable, mark the store for deletion if not still used.
                            if (self.var2store.get(var_id)) |prev_store| {
                                if (!instructions_to_save.contains(prev_store)) {
                                    instructions_to_kill.push(prev_store);
                                    modified = true;
                                }
                            }
                            var kill_store: bool = false;
                            if (self.var2load.get(var_id)) |li| {
                                if (ii.getSingleWordInOperand(1) == li.resultId()) {
                                    // We are storing the same value that already exists in the memory location.
                                    kill_store = true;
                                }
                            }
                            if (!kill_store) {
                                self.var2store.put(var_id, ii);
                                _ = self.var2load.remove(var_id);
                            } else {
                                instructions_to_kill.push(ii);
                                modified = true;
                            }
                        } else {
                            _ = self.var2store.remove(var_id);
                            _ = self.var2load.remove(var_id);
                        }
                    },
                    .OpLoad => {
                        var var_id: u32 = 0;
                        const ptr_inst: *Inst = memGetPtrOfInst(ctx, ii, &var_id);
                        if (!memIsTargetVar(ctx, &self.mem, var_id)) continue;
                        if (!hasOnlySupportedRefs(self, ctx, var_id)) continue;
                        var repl_id: u32 = 0;
                        if (ptr_inst.op == .OpVariable) {
                            // If a load from a variable, look for a previous store or load from that variable.
                            if (self.var2store.get(var_id)) |si| {
                                repl_id = si.getSingleWordInOperand(1);
                            } else if (self.var2load.get(var_id)) |li| {
                                repl_id = li.resultId();
                            }
                        } else {
                            // If a partial load of a previously seen store, remember not to delete the store.
                            if (self.var2store.get(var_id)) |si| _ = instructions_to_save.insert(si);
                        }
                        if (repl_id != 0) {
                            // replace load's result id and delete load
                            ctx.killNamesAndDecorates(ii);
                            _ = ctx.replaceAllUsesWith(ii.resultId(), repl_id);
                            instructions_to_kill.push(ii);
                            modified = true;
                        } else {
                            if (ptr_inst.op == .OpVariable) self.var2load.put(var_id, ii); // register load
                        }
                    },
                    .OpFunctionCall => {
                        // Conservatively assume all locals are redefined for now.
                        self.var2store.clear();
                        self.var2load.clear();
                    },
                    else => {},
                }
            }
        }
        for (instructions_to_kill.items) |inst| _ = ctx.killInst(inst);
        return modified;
    }

    pub fn run(self: *LocalSingleBlockLoadStoreElim, ctx: *Ctx) PassStatus {
        self.* = .{};
        // Assumes relaxed logical addressing only.
        if (ctx.getFeatureMgr().hasCapability(.Addresses)) return .success_without_change;
        // Do not process if module contains OpGroupDecorate (KillNamesAndDecorates cannot handle it).
        if (lmModuleHasGroupDecorate(ctx)) return .success_without_change;
        // If any extensions in the module are not explicitly supported, return unmodified.
        if (!passAllExtensionsSupported(ctx, &ext_allow_lsbe, false)) return .success_without_change;
        var runner: Runner = .{ .ctx = ctx, .pass = self };
        const modified: bool = ctx.processReachableCallTree(&runner, processFunction);
        return if (modified) .success_with_change else .success_without_change;
    }
};

