// ---------------------------------------------------------------------------------------------
// LocalSingleStoreElim
// ---------------------------------------------------------------------------------------------

pub const LocalSingleStoreElim = struct {
    pub const name = "eliminate-local-single-store";
    pub const preserved: u32 = Analysis.def_use | Analysis.instr_to_block | Analysis.constants | Analysis.types;

    fn findUses(ctx: *Ctx, var_inst: *const Inst, users: *List(*Inst)) void {
        for (ctx.getDefUseMgr().registeredUsers(var_inst)) |user| {
            users.push(user);
            if (user.op == .OpCopyObject) findUses(ctx, user, users);
        }
    }

    fn feedsAStore(ctx: *Ctx, inst: *const Inst) bool {
        for (ctx.getDefUseMgr().registeredUsers(inst)) |user| {
            switch (user.op) {
                .OpStore => return true,
                .OpAccessChain, .OpInBoundsAccessChain, .OpCopyObject => {
                    if (feedsAStore(ctx, user)) return true;
                },
                .OpLoad, .OpImageTexelPointer, .OpName => {},
                // Don't know if this instruction modifies the variable.
                else => {
                    if (!user.isDecoration()) return true;
                },
            }
        }
        return false;
    }

    fn findSingleStoreAndCheckUses(ctx: *Ctx, var_inst: *Inst, users: []const *Inst) ?*Inst {
        // Make sure there is exactly 1 store.
        var store_inst: ?*Inst = null;
        // If |var_inst| has an initializer, then that will count as a store.
        if (var_inst.numInOperands() > 1) store_inst = var_inst;

        for (users) |user| {
            switch (user.op) {
                .OpStore => {
                    // In the relaxed addressing mode the use has to be the base address of the store.
                    if (store_inst == null) {
                        store_inst = user;
                    } else {
                        return null; // More than 1 store.
                    }
                },
                .OpAccessChain, .OpInBoundsAccessChain => {
                    if (feedsAStore(ctx, user)) return null; // Has a partial store. Cannot propagate that.
                },
                .OpLoad, .OpImageTexelPointer, .OpName, .OpCopyObject => {},
                .OpExtInst => return null, // (DebugDeclare / DebugValue cannot occur: no extended debug info in this port)
                else => {
                    // Don't know if this instruction modifies the variable. Conservatively assume it is a store.
                    if (!user.isDecoration()) return null;
                },
            }
        }
        return store_inst;
    }

    fn rewriteLoads(ctx: *Ctx, store_inst: *Inst, uses: []const *Inst, all_rewritten: *bool) bool {
        const store_block: *Block = ctx.getInstrBlock(store_inst).?;
        const dominator_analysis: *DominatorAnalysis = ctx.getDominatorAnalysis(store_block.parent.?);
        // the stored value is in-operand 1 for OpStore (kStoreValIdInIdx) and for an OpVariable initializer (kVariableInitIdInIdx)
        const stored_id: u32 = store_inst.getSingleWordInOperand(1);
        all_rewritten.* = true;
        var modified: bool = false;
        for (uses) |use| {
            if (use.op == .OpStore) continue;
            if (use.op == .OpLoad and dominator_analysis.dominatesInst(store_inst, use)) {
                modified = true;
                ctx.killNamesAndDecoratesId(use.resultId());
                _ = ctx.replaceAllUsesWith(use.resultId(), stored_id);
                _ = ctx.killInst(use);
            } else {
                all_rewritten.* = false;
            }
        }
        return modified;
    }

    fn processVariable(ctx: *Ctx, var_inst: *Inst) bool {
        var users: List(*Inst) = .{};
        findUses(ctx, var_inst, &users);
        const store_inst: *Inst = findSingleStoreAndCheckUses(ctx, var_inst, users.items) orelse return false;
        var all_rewritten: bool = false;
        // (the DebugDeclare / DebugValue rewrite cannot occur: no extended debug info in this port)
        return rewriteLoads(ctx, store_inst, users.items, &all_rewritten);
    }

    fn processFunction(ctx: *Ctx, func: *Func) bool {
        var modified: bool = false;
        // Check all function scope variables in |func|.
        const entry_block: *Block = func.blocks.items[0];
        var it: ?*Inst = entry_block.insts.first;
        while (it) |inst| {
            if (inst.op != .OpVariable) break;
            // processVariable kills loads of the variable, never the variable itself: the successor is read after it
            if (processVariable(ctx, inst)) modified = true;
            it = inst.next;
        }
        return modified;
    }

    pub fn run(self: *LocalSingleStoreElim, ctx: *Ctx) PassStatus {
        _ = self;
        // Assumes relaxed logical addressing only.
        if (ctx.getFeatureMgr().hasCapability(.Addresses)) return .success_without_change;
        // Do not process if any disallowed extensions are enabled
        if (!passAllExtensionsSupported(ctx, &ext_allow_lsse, false)) return .success_without_change;
        const modified: bool = ctx.processReachableCallTree(ctx, processFunction);
        return if (modified) .success_with_change else .success_without_change;
    }
};

/// True when the only users of `id` are OpName and decorations.
pub fn memHasOnlyNamesAndDecorates(ctx: *Ctx, id: u32) bool {
    for (ctx.getDefUseMgr().registeredUsersOfId(id)) |user| {
        if (user.op != .OpName and !memIsNonTypeDecorate(user.op)) return false;
    }
    return true;
}

/// True when anything reads through the variable: any user other than a store, a name or a decoration, looking through
/// access chains and copies.
pub fn memHasLoads(ctx: *Ctx, var_id: u32) bool {
    for (ctx.getDefUseMgr().registeredUsersOfId(var_id)) |user| {
        const op: Op = user.op;
        if (memIsNonPtrAccessChain(op) or op == .OpCopyObject) {
            if (memHasLoads(ctx, user.resultId())) return true;
        } else if (op != .OpStore and op != .OpName and !memIsNonTypeDecorate(op)) {
            return true;
        }
    }
    return false;
}

/// True when the variable has to stay: anything but a Function variable that nothing loads.
pub fn memIsLiveVar(ctx: *Ctx, var_id: u32) bool {
    const var_inst: *Inst = memDef(ctx, var_id);
    if (var_inst.op != .OpVariable) return true;
    const var_type_inst: *Inst = memDef(ctx, var_inst.typeId());
    if (var_type_inst.getSingleWordInOperand(0) != @intFromEnum(StorageClass.Function)) return true;
    return memHasLoads(ctx, var_id);
}

/// Appends to `insts` every store through `ptr_id` or through access chains derived from it.
pub fn memAddStores(ctx: *Ctx, ptr_id: u32, insts: *Queue(*Inst)) void {
    for (ctx.getDefUseMgr().registeredUsersOfId(ptr_id)) |user| {
        if (memIsNonPtrAccessChain(user.op)) {
            memAddStores(ctx, user.resultId(), insts);
        } else if (user.op == .OpStore) {
            insts.push(user);
        }
    }
}

/// Adds an id operand to the set.
fn memCollectInId(ids: *SortedSet(u32, ascending(u32)), id: *u32) void {
    _ = ids.insert(id.*);
}

/// MemPass::DCEInst: kills `inst` and, transitively, the combinator instructions that only it used and (for a load of a
/// dead function variable) the stores to that variable. `cb` is called on every instruction right before it is killed.
pub fn memDceInst(ctx: *Ctx, inst: *Inst, cb_ctx: anytype, comptime cb: fn (@TypeOf(cb_ctx), *Inst) void) void {
    var dead_insts: Queue(*Inst) = .{};
    dead_insts.push(inst);
    while (!dead_insts.isEmpty()) {
        const di: *Inst = dead_insts.front();
        if (di.op == .OpLabel) {
            _ = dead_insts.pop();
            continue;
        }
        var ids: SortedSet(u32, ascending(u32)) = .{}; // std::set<uint32_t>
        di.forEachInId(&ids, memCollectInId);
        var var_id: u32 = 0;
        if (di.op == .OpLoad) _ = memGetPtrOfInst(ctx, di, &var_id);
        cb(cb_ctx, di);
        _ = ctx.killInst(di);
        for (ids.items()) |id| {
            if (memHasOnlyNamesAndDecorates(ctx, id)) {
                const odi: *Inst = memDef(ctx, id);
                if (ctx.isCombinatorInstruction(odi)) dead_insts.push(odi);
            }
        }
        if (var_id != 0 and !memIsLiveVar(ctx, var_id)) memAddStores(ctx, var_id, &dead_insts);
        _ = dead_insts.pop();
    }
}

