// ---------------------------------------------------------------------------------------------
// LocalAccessChainConvert
// ---------------------------------------------------------------------------------------------

pub const LocalAccessChainConvert = struct {
    pub const name = "convert-local-access-chains";
    pub const preserved: u32 = Analysis.def_use | Analysis.constants | Analysis.types;

    mem: MemState = .{},
    supported_ref_ptrs: Set(u32) = .{},

    fn hasOnlySupportedRefs(self: *LocalAccessChainConvert, ctx: *Ctx, ptr_id: u32) bool {
        if (self.supported_ref_ptrs.contains(ptr_id)) return true;
        for (ctx.getDefUseMgr().registeredUsersOfId(ptr_id)) |user| {
            const op: Op = user.op;
            if (memIsNonPtrAccessChain(op) or op == .OpCopyObject) {
                if (!self.hasOnlySupportedRefs(ctx, user.resultId())) return false;
            } else if (op != .OpStore and op != .OpLoad and op != .OpName and !memIsNonTypeDecorate(op)) {
                return false;
            }
        }
        _ = self.supported_ref_ptrs.insert(ptr_id);
        return true;
    }

    fn is32BitConstantIndexAccessChain(ctx: *Ctx, acp: *Inst) bool {
        const du: *DefUseMgr = ctx.getDefUseMgr();
        var in_idx: u32 = 0;
        var k: usize = acp.typeResultIdCount();
        while (k < acp.ops.items.len) : (k += 1) {
            const o: *Operand = &acp.ops.items[k];
            if (!kindIsId(o.kind)) continue;
            if (in_idx > 0) {
                const op_inst: *Inst = du.getDef(o.word0()) orelse fatal("LocalAccessChainConvert: id %{d} is not defined", .{o.word0()});
                if (op_inst.op != .OpConstant) return false;
                const index: *const Constant = ctx.getConstantMgr().getConstantFromInst(op_inst).?;
                const index_value: i64 = index.getSignExtendedValue();
                if (index_value > std.math.maxInt(u32)) return false;
                if (index_value < 0) return false;
            }
            in_idx += 1;
        }
        return true;
    }

    fn isIndexOutOfBounds(index: ?*const Constant, ty: *const Type) bool {
        const c: *const Constant = index orelse return false;
        return c.getZeroExtendedValue() >= ty.numberOfComponents();
    }

    fn anyIndexIsOutOfBounds(ctx: *Ctx, access_chain_inst: *const Inst) bool {
        const type_mgr: *TypeMgr = ctx.getTypeMgr();
        const const_mgr: *ConstMgr = ctx.getConstantMgr();
        const constants: List(?*const Constant) = const_mgr.getOperandConstants(access_chain_inst);
        const base_pointer_id: u32 = access_chain_inst.getSingleWordInOperand(0);
        const base_pointer: *Inst = memDef(ctx, base_pointer_id);
        const base_pointer_type: *const TyPointer = type_mgr.getType(base_pointer.typeId()).?.as(.pointer) orelse
            fatal("The base of the access chain is not a pointer.", .{});
        var current_type: *const Type = base_pointer_type.pointee.?;
        var i: usize = 1;
        while (i < access_chain_inst.numInOperands()) : (i += 1) {
            if (isIndexOutOfBounds(constants.items[i], current_type)) return true;
            const index: u32 = if (constants.items[i]) |c| @truncate(c.getZeroExtendedValue()) else 0;
            current_type = type_mgr.getMemberType(current_type, &.{index});
        }
        return false;
    }

    fn markNonTarget(self: *LocalAccessChainConvert, var_id: u32) void {
        _ = self.mem.seen_non_target_vars.insert(var_id);
        _ = self.mem.seen_target_vars.remove(var_id);
    }

    fn findTargetVars(self: *LocalAccessChainConvert, ctx: *Ctx, func: *Func) void {
        for (func.blocks.items) |bb| {
            var it: ?*Inst = bb.insts.first;
            while (it) |ii| : (it = ii.next) {
                switch (ii.op) {
                    .OpStore, .OpLoad => {
                        var var_id: u32 = 0;
                        const ptr_inst: *Inst = memGetPtrOfInst(ctx, ii, &var_id);
                        if (!memIsTargetVar(ctx, &self.mem, var_id)) continue;
                        const op: Op = ptr_inst.op;
                        // Rule out variables with non-supported refs eg function calls
                        if (!hasOnlySupportedRefs(self, ctx, var_id)) {
                            markNonTarget(self, var_id);
                            continue;
                        }
                        // Rule out variables with nested access chains
                        const is_non_ptr_access_chain: bool = memIsNonPtrAccessChain(op);
                        if (is_non_ptr_access_chain and ptr_inst.getSingleWordInOperand(0) != var_id) {
                            markNonTarget(self, var_id);
                            continue;
                        }
                        // Rule out variables accessed with non-constant indices
                        if (!is32BitConstantIndexAccessChain(ctx, ptr_inst)) {
                            markNonTarget(self, var_id);
                            continue;
                        }
                        if (is_non_ptr_access_chain and anyIndexIsOutOfBounds(ctx, ptr_inst)) {
                            markNonTarget(self, var_id);
                            continue;
                        }
                    },
                    else => {},
                }
            }
        }
    }

    // ---- instruction construction ------------------------------------------------------------------

    fn buildAndAppendInst(ctx: *Ctx, opcode: Op, type_id: u32, result_id: u32, in_opnds: []const Operand, new_insts: *List(*Inst)) void {
        const new_inst: *Inst = Inst.make(opcode, type_id, result_id, in_opnds);
        ctx.getDefUseMgr().analyzeInstDefUse(new_inst);
        new_insts.push(new_inst);
    }

    /// BuildAndAppendVarLoad: returns the id of the load (0 on id overflow).
    fn buildAndAppendVarLoad(ctx: *Ctx, ptr_inst: *const Inst, var_id: *u32, var_pte_type_id: *u32, new_insts: *List(*Inst)) u32 {
        const ld_result_id: u32 = ctx.takeNextId();
        if (ld_result_id == 0) return 0;
        var_id.* = ptr_inst.getSingleWordInOperand(0);
        const var_inst: *Inst = memDef(ctx, var_id.*);
        var_pte_type_id.* = passGetPointeeTypeId(ctx, var_inst);
        buildAndAppendInst(ctx, .OpLoad, var_pte_type_id.*, ld_result_id, &.{Operand.single(.IdRef, var_id.*)}, new_insts);
        return ld_result_id;
    }

    fn appendConstantOperands(ctx: *Ctx, ptr_inst: *const Inst, in_opnds: *List(Operand)) void {
        var iid_idx: u32 = 0;
        var k: usize = ptr_inst.typeResultIdCount();
        while (k < ptr_inst.ops.items.len) : (k += 1) {
            const o: *Operand = &ptr_inst.ops.items[k];
            if (!kindIsId(o.kind)) continue;
            if (iid_idx > 0) {
                const c_inst: *Inst = memDef(ctx, o.word0());
                const constant_value: *const Constant = ctx.getConstantMgr().getConstantFromInst(c_inst) orelse
                    fatal("Expecting the index to be a constant.", .{});
                // The sign extended value is taken because OpAccessChain interprets the index as signed.
                const long_value: i64 = constant_value.getSignExtendedValue();
                const val: u32 = @truncate(@as(u64, @bitCast(long_value)));
                in_opnds.push(Operand.single(.LiteralInteger, val));
            }
            iid_idx += 1;
        }
    }

    fn replaceAccessChainLoad(ctx: *Ctx, address_inst: *const Inst, original_load: *Inst) bool {
        if (address_inst.numInOperands() == 1) {
            // An access chain with no indices is essentially a copy: propagate the address.
            _ = ctx.replaceAllUsesWith(address_inst.resultId(), address_inst.getSingleWordInOperand(0));
            return true;
        }
        var new_inst: List(*Inst) = .{};
        var var_id: u32 = 0;
        var var_pte_type_id: u32 = 0;
        const ld_result_id: u32 = buildAndAppendVarLoad(ctx, address_inst, &var_id, &var_pte_type_id, &new_inst);
        if (ld_result_id == 0) return false;

        instUpdateDebugInfoFrom(ctx, new_inst.items[0], original_load, null);
        ctx.getDecorationMgr().cloneDecorationsSubset(original_load.resultId(), ld_result_id, &.{.RelaxedPrecision});
        _ = original_load.insertBeforeMany(new_inst.items);

        // Rewrite |original_load| into an extract.
        var new_operands: List(Operand) = .{};
        new_operands.push(original_load.getOperand(0).*); // type id
        new_operands.push(original_load.getOperand(1).*); // result id
        new_operands.push(Operand.single(.IdRef, ld_result_id));
        appendConstantOperands(ctx, address_inst, &new_operands);
        original_load.setOpcode(.OpCompositeExtract);
        original_load.replaceOperands(new_operands.items);
        ctx.updateDefUse(original_load);
        return true;
    }

    fn genAccessChainStoreReplacement(ctx: *Ctx, ptr_inst: *const Inst, val_id: u32, new_insts: *List(*Inst)) bool {
        if (ptr_inst.numInOperands() == 1) {
            // An access chain with no indices is essentially a copy. A new store is still needed because the old
            // ones will be deleted.
            buildAndAppendInst(ctx, .OpStore, 0, 0, &.{
                Operand.single(.IdRef, ptr_inst.getSingleWordInOperand(0)),
                Operand.single(.IdRef, val_id),
            }, new_insts);
            return true;
        }
        // Build and append load of variable in ptrInst
        var var_id: u32 = 0;
        var var_pte_type_id: u32 = 0;
        const ld_result_id: u32 = buildAndAppendVarLoad(ctx, ptr_inst, &var_id, &var_pte_type_id, new_insts);
        if (ld_result_id == 0) return false;
        const decor: *DecorMgr = ctx.getDecorationMgr();
        decor.cloneDecorationsSubset(var_id, ld_result_id, &.{.RelaxedPrecision});

        // Build and append Insert
        const ins_result_id: u32 = ctx.takeNextId();
        if (ins_result_id == 0) return false;
        var ins_in_opnds: List(Operand) = .{};
        ins_in_opnds.push(Operand.single(.IdRef, val_id));
        ins_in_opnds.push(Operand.single(.IdRef, ld_result_id));
        appendConstantOperands(ctx, ptr_inst, &ins_in_opnds);
        buildAndAppendInst(ctx, .OpCompositeInsert, var_pte_type_id, ins_result_id, ins_in_opnds.items, new_insts);
        decor.cloneDecorationsSubset(var_id, ins_result_id, &.{.RelaxedPrecision});

        // Build and append Store
        buildAndAppendInst(ctx, .OpStore, 0, 0, &.{
            Operand.single(.IdRef, var_id),
            Operand.single(.IdRef, ins_result_id),
        }, new_insts);
        return true;
    }

    const DeadCb = struct {
        dead: *List(*Inst),
        fn f(c: DeadCb, other_inst: *Inst) void {
            if (c.dead.indexOf(other_inst)) |i| _ = c.dead.orderedRemove(i);
        }
    };

    fn convertLocalAccessChains(self: *LocalAccessChainConvert, ctx: *Ctx, func: *Func) PassStatus {
        findTargetVars(self, ctx, func);
        // Replace access chains of all targeted variables with equivalent extract and insert sequences
        var modified: bool = false;
        for (func.blocks.items) |bb| {
            var dead_instructions: List(*Inst) = .{};
            var it: ?*Inst = bb.insts.first;
            while (it) |ii| {
                switch (ii.op) {
                    .OpLoad => {
                        var var_id: u32 = 0;
                        const ptr_inst: *Inst = memGetPtrOfInst(ctx, ii, &var_id);
                        if (memIsNonPtrAccessChain(ptr_inst.op) and memIsTargetVar(ctx, &self.mem, var_id)) {
                            if (!replaceAccessChainLoad(ctx, ptr_inst, ii)) return .failure;
                            modified = true;
                        }
                        it = ii.next;
                    },
                    .OpStore => {
                        var var_id: u32 = 0;
                        const store: *Inst = ii;
                        const ptr_inst: *Inst = memGetPtrOfInst(ctx, store, &var_id);
                        if (!memIsNonPtrAccessChain(ptr_inst.op) or !memIsTargetVar(ctx, &self.mem, var_id)) {
                            it = ii.next;
                            continue;
                        }
                        var new_insts: List(*Inst) = .{};
                        const val_id: u32 = store.getSingleWordInOperand(1);
                        if (!genAccessChainStoreReplacement(ctx, ptr_inst, val_id, &new_insts)) return .failure;
                        dead_instructions.push(store);
                        // The new instructions go right after the old store; the walk continues after them.
                        const after: ?*Inst = store.next;
                        for (new_insts.items) |ni| {
                            if (after) |a| {
                                _ = a.insertBefore(ni);
                            } else {
                                bb.insts.pushBack(ni);
                            }
                        }
                        for (new_insts.items) |ni| instUpdateDebugInfoFrom(ctx, ni, store, null);
                        modified = true;
                        it = after;
                    },
                    else => it = ii.next,
                }
            }

            while (dead_instructions.pop()) |inst| {
                memDceInst(ctx, inst, DeadCb{ .dead = &dead_instructions }, DeadCb.f);
            }
        }
        return if (modified) .success_with_change else .success_without_change;
    }

    pub fn run(self: *LocalAccessChainConvert, ctx: *Ctx) PassStatus {
        self.* = .{};
        // Do not process if module contains OpGroupDecorate (KillNamesAndDecorates cannot handle it).
        if (lmModuleHasGroupDecorate(ctx)) return .success_without_change;
        // This pass only looks at function scope symbols, but VariablePointers is rejected like the C++ does.
        if (ctx.getFeatureMgr().hasCapability(.VariablePointers)) return .success_without_change;
        if (!passAllExtensionsSupported(ctx, &ext_allow_lacc, false)) return .success_without_change;
        // Process all functions in the module.
        var status: PassStatus = .success_without_change;
        for (ctx.module.functions.items) |func| {
            status = statusCombine(status, convertLocalAccessChains(self, ctx, func));
            if (status == .failure) break;
        }
        return status;
    }
};

/// MemPass::Type2Undef: the global OpUndef of `type_id` (created on first use). 0 on id overflow.
pub fn memType2Undef(ctx: *Ctx, st: *MemState, type_id: u32) u32 {
    if (st.type2undefs.get(type_id)) |u| return u;
    const undef_id: u32 = ctx.takeNextId();
    if (undef_id == 0) return 0;
    const undef_inst: *Inst = Inst.make(.OpUndef, type_id, undef_id, &.{});
    ctx.getDefUseMgr().analyzeInstDefUse(undef_inst);
    ctx.module.addGlobalValue(undef_inst);
    st.type2undefs.put(type_id, undef_id);
    return undef_id;
}

/// MemPass::GetUndefVal
pub fn memGetUndefVal(ctx: *Ctx, st: *MemState, var_id: u32) u32 {
    return memType2Undef(ctx, st, passGetPointeeTypeId(ctx, memDef(ctx, var_id)));
}

/// True when the only users of the variable are loads, stores, names and decorations.
fn memHasOnlySupportedRefs(ctx: *Ctx, var_id: u32) bool {
    for (ctx.getDefUseMgr().registeredUsersOfId(var_id)) |user| {
        // (DebugDeclare / DebugValue users cannot occur: extended debug info is rejected or stripped at load)
        const op: Op = user.op;
        if (op != .OpStore and op != .OpLoad and op != .OpName and !memIsNonTypeDecorate(op)) return false;
    }
    return true;
}

/// MemPass::CollectTargetVars
pub fn memCollectTargetVars(ctx: *Ctx, st: *MemState, func: *Func) void {
    st.seen_target_vars.clear();
    st.seen_non_target_vars.clear();
    st.type2undefs.clear();
    for (func.blocks.items) |blk| {
        var it: ?*Inst = blk.insts.first;
        while (it) |inst| : (it = inst.next) {
            switch (inst.op) {
                .OpStore, .OpLoad => {
                    var var_id: u32 = 0;
                    _ = memGetPtrOfInst(ctx, inst, &var_id);
                    if (!memIsTargetVar(ctx, st, var_id)) continue;
                    if (memHasOnlySupportedRefs(ctx, var_id)) continue;
                    _ = st.seen_non_target_vars.insert(var_id);
                    _ = st.seen_target_vars.remove(var_id);
                },
                else => {},
            }
        }
    }
}

// SSARewritePass (ssa_rewrite_pass.cpp), flag --eliminate-local-multi-store.
// Braun et al. "Simple and Efficient Construction of SSA Form": loads of function-local target variables are
// replaced by their reaching definitions, Phi candidates are created lazily at join points.
//
// Unordered C++ containers: defs_at_block_ (pointer keys), phi_candidates_, sealed_blocks_ are only looked up (here
// a flat map keyed by (block, variable), a dense table indexed by Phi id and a flag table). load_replacement_ is
// iterated in ApplyReplacements, where every step is independent of the others (the final replacement value is found
// by following the chain), so the visiting order cannot change the output. The C++ also walks the whole table in
// ReplacePhiUsersWith; here `loads_by_value` indexes the table by value, so only the entries that map to the removed
// Phi are touched (same result, no quadratic walk).

const SsaPhiCandidate = struct {
    var_id: u32,
    result_id: u32,
    bb: *Block,
    phi_args: List(u32) = .{},
    copy_of: u32 = 0,
    is_complete: bool = false,
    users: List(u32) = .{},

    fn isReady(self: *const SsaPhiCandidate) bool {
        return self.is_complete and self.copy_of == 0;
    }

    fn addUser(self: *SsaPhiCandidate, operand_id: u32) void {
        self.users.push(operand_id);
    }
};

const SsaRewriter = struct {
    ctx: *Ctx,
    st: *MemState,
    /// defs_at_block_[block][var_id] = val_id: one flat map keyed by (block label id, variable id) instead of a map of maps
    defs_at_block: Map(u64, u32) = .{},
    /// phi_candidates_: the Phi result ids are handed out in increasing order, so the candidate with result id `id`
    /// is `phi_candidates[id - phi_base]` (null: that id is not a candidate); `phi_base == 0` until the first candidate
    phi_candidates: List(?*SsaPhiCandidate) = .{},
    phi_base: u32 = 0,
    incomplete_phis: Queue(*SsaPhiCandidate) = .{},
    phis_to_generate: List(*SsaPhiCandidate) = .{},
    load_replacement: Map(u32, u32) = .{},
    /// The `load_replacement` entries grouped by their current value (value -> ids of the loads that map to it), so that
    /// re-routing the loads of a removed Phi touches just those entries instead of walking the whole table.
    loads_by_value: Map(u32, List(u32)) = .{},
    /// sealed_blocks_: flag per block label id
    sealed_blocks: List(bool) = .{},

    fn getPhiCandidate(self: *SsaRewriter, id: u32) ?*SsaPhiCandidate {
        if (self.phi_base == 0 or id < self.phi_base) return null;
        const ix: usize = id - self.phi_base;
        if (ix >= self.phi_candidates.len()) return null;
        return self.phi_candidates.items[ix];
    }

    fn isBlockSealed(self: *SsaRewriter, bb: *Block) bool {
        const id: usize = bb.id();
        return id < self.sealed_blocks.len() and self.sealed_blocks.items[id];
    }

    fn sealBlock(self: *SsaRewriter, bb: *Block) void {
        // C++ asserts that the block was not sealed before
        self.sealed_blocks.growFilled(@as(usize, bb.id()) + 1, false);
        self.sealed_blocks.items[bb.id()] = true;
    }

    fn createPhiCandidate(self: *SsaRewriter, var_id: u32, bb: *Block) *SsaPhiCandidate {
        const phi_result_id: u32 = self.ctx.takeNextId(); // id overflow is fatal in this port
        const pc = scAllocator().create(SsaPhiCandidate) catch oom();
        pc.* = .{ .var_id = var_id, .result_id = phi_result_id, .bb = bb };
        if (self.phi_base == 0) self.phi_base = phi_result_id;
        check(phi_result_id >= self.phi_base, "SSARewrite: Phi result ids are not increasing");
        self.phi_candidates.growFilled(@as(usize, phi_result_id - self.phi_base) + 1, null);
        self.phi_candidates.items[phi_result_id - self.phi_base] = pc;
        return pc;
    }

    fn defKey(bb: *const Block, var_id: u32) u64 {
        return (@as(u64, bb.id()) << 32) | var_id;
    }

    fn writeVariable(self: *SsaRewriter, var_id: u32, bb: *Block, val_id: u32) void {
        self.defs_at_block.put(defKey(bb, var_id), val_id);
        if (self.getPhiCandidate(val_id)) |pc| pc.addUser(bb.id());
    }

    fn getValueAtBlock(self: *SsaRewriter, var_id: u32, bb: *Block) u32 {
        return self.defs_at_block.get(defKey(bb, var_id)) orelse 0;
    }

    /// Every `load_replacement` entry whose value is `old_value` gets the value `new_value` (the C++ walks the whole table).
    fn retargetLoadReplacements(self: *SsaRewriter, old_value: u32, new_value: u32) void {
        const lst: *List(u32) = self.loads_by_value.getPtr(old_value) orelse return;
        const moved: List(u32) = lst.*;
        lst.* = .{};
        for (moved.items) |load_id| {
            const slot: *u32 = self.load_replacement.getPtr(load_id) orelse fatal("SSARewrite: load %{d} lost its replacement", .{load_id});
            slot.* = new_value;
        }
        const dst: Map(u32, List(u32)).GetOrPutResult = self.loads_by_value.getOrPut(new_value);
        if (dst.found_existing) dst.value_ptr.pushSlice(moved.items) else dst.value_ptr.* = moved;
    }

    fn setLoadReplacement(self: *SsaRewriter, load_id: u32, val_id: u32) void {
        const slot: Map(u32, u32).GetOrPutResult = self.load_replacement.getOrPut(load_id);
        check(!slot.found_existing, "SSARewrite: a load was processed twice");
        slot.value_ptr.* = val_id;
        const by: Map(u32, List(u32)).GetOrPutResult = self.loads_by_value.getOrPut(val_id);
        if (!by.found_existing) by.value_ptr.* = .{};
        by.value_ptr.push(load_id);
    }

    fn replacePhiUsersWith(self: *SsaRewriter, phi_to_remove: *SsaPhiCandidate, repl_id: u32) void {
        // One walk of the load replacement table rewrites every entry that refers to the Phi, so the C++ repeats the
        // same (then fruitless) walk for each further regular-load user: nothing in this loop changes the table.
        var load_table_walked: bool = false;
        var k: usize = 0;
        while (k < phi_to_remove.users.len()) : (k += 1) {
            const user_id: u32 = phi_to_remove.users.items[k];
            const user_phi: ?*SsaPhiCandidate = self.getPhiCandidate(user_id);
            const bb: ?*Block = self.ctx.getInstrBlockById(user_id);
            if (user_phi) |up| {
                // If the user is a Phi candidate, replace all arguments that refer to |phi_to_remove| with |repl_id|.
                for (up.phi_args.items) |*arg| {
                    if (arg.* == phi_to_remove.result_id) arg.* = repl_id;
                }
            } else if ((bb orelse fatal("SSARewrite: user %{d} is not in a block", .{user_id})).id() == user_id) {
                // The phi candidate is the definition of the variable at basic block |bb|: change it to the replacement.
                self.writeVariable(phi_to_remove.var_id, bb.?, repl_id);
            } else {
                // For regular loads, traverse the load replacement table looking for instances of |phi_to_remove|.
                if (!load_table_walked) {
                    load_table_walked = true;
                    self.retargetLoadReplacements(phi_to_remove.result_id, repl_id);
                }
            }
        }
    }

    fn tryRemoveTrivialPhi(self: *SsaRewriter, pc: *SsaPhiCandidate) u32 {
        var same_id: u32 = 0;
        for (pc.phi_args.items) |arg_id| {
            if (arg_id == same_id or arg_id == pc.result_id) continue; // self-reference or the same value again
            if (same_id != 0) return pc.result_id; // merges at least two values: not trivial
            same_id = arg_id;
        }
        // Trivial: result = Phi(same, same, ...). Mark it as a copy so it is not generated and re-route its users.
        pc.copy_of = same_id;
        self.replacePhiUsersWith(pc, same_id);
        return same_id;
    }

    fn addPhiOperands(self: *SsaRewriter, pc: *SsaPhiCandidate) u32 {
        const cfg: *Cfg = self.ctx.cfg();
        var found_0_arg: bool = false;
        for (cfg.preds(pc.bb.id())) |pred| {
            const pred_bb: *Block = cfg.block(pred);
            // An unsealed predecessor yields %0: the Phi is completed after the whole CFG has been processed.
            const arg_id: u32 = if (self.isBlockSealed(pred_bb)) self.getReachingDef(pc.var_id, pred_bb) else 0;
            pc.phi_args.push(arg_id);
            if (arg_id == 0) {
                found_0_arg = true;
            } else {
                if (self.getPhiCandidate(arg_id)) |defining_phi| {
                    if (defining_phi != pc) defining_phi.addUser(pc.result_id);
                }
            }
        }
        if (found_0_arg) {
            pc.is_complete = false;
            self.incomplete_phis.push(pc);
            return pc.result_id;
        }
        // Try to remove |pc|, if it is trivial.
        const repl_id: u32 = self.tryRemoveTrivialPhi(pc);
        if (repl_id == pc.result_id) {
            // complete and not trivial: it will become a real Phi
            pc.is_complete = true;
            self.phis_to_generate.push(pc);
        }
        return repl_id;
    }

    fn getReachingDef(self: *SsaRewriter, var_id: u32, bb: *Block) u32 {
        var val_id: u32 = self.getValueAtBlock(var_id, bb);
        if (val_id != 0) return val_id;

        const cfg: *Cfg = self.ctx.cfg();
        const predecessors: []const u32 = cfg.preds(bb.id());
        if (predecessors.len == 1) {
            val_id = self.getReachingDef(var_id, cfg.block(predecessors[0]));
        } else if (predecessors.len > 1) {
            // A join block which may require a Phi; the candidate acts as the current definition to break cycles.
            const pc: *SsaPhiCandidate = self.createPhiCandidate(var_id, bb);
            self.writeVariable(var_id, bb, pc.result_id);
            val_id = self.addPhiOperands(pc);
        }

        // No store on the path from the root of the CFG: the variable is undefined.
        if (val_id == 0) {
            val_id = memGetUndefVal(self.ctx, self.st, var_id);
            if (val_id == 0) return 0;
        }

        self.writeVariable(var_id, bb, val_id);
        return val_id;
    }

    fn processStore(self: *SsaRewriter, inst: *Inst, bb: *Block) void {
        var var_id: u32 = 0;
        var val_id: u32 = 0;
        if (inst.op == .OpStore) {
            _ = memGetPtrOfInst(self.ctx, inst, &var_id);
            val_id = inst.getSingleWordInOperand(1);
        } else if (inst.numInOperands() >= 2) {
            var_id = inst.resultId();
            val_id = inst.getSingleWordInOperand(1);
        }
        if (memIsTargetVar(self.ctx, self.st, var_id)) {
            self.writeVariable(var_id, bb, val_id);
            // (AddDebugValueForVariable: no extended debug info in this port)
        }
    }

    fn processLoad(self: *SsaRewriter, inst: *Inst, bb: *Block) bool {
        const ctx: *Ctx = self.ctx;
        var var_id: u32 = 0;
        _ = memGetPtrOfInst(ctx, inst, &var_id);

        // In the presence of variable pointers the reaching definition may be another pointer: keep looking up the
        // reaching definition chain until a value of the loaded type or a non-target variable is found.
        const du: *DefUseMgr = ctx.getDefUseMgr();
        const type_mgr: *TypeMgr = ctx.getTypeMgr();
        const load_type: *Type = type_mgr.getType(inst.typeId()) orelse fatal("SSARewrite: unknown load type %{d}", .{inst.typeId()});
        var val_id: u32 = 0;
        var found_reaching_def: bool = false;
        while (!found_reaching_def) {
            // Not an SSA target (globals, function parameters): nothing to do.
            if (!memIsTargetVar(ctx, self.st, var_id)) return true;

            val_id = self.getReachingDef(var_id, bb);
            if (val_id == 0) return false;

            // A pointer type different from the loaded type must be a reference to another pointer: continue
            // de-referencing it. No reaching definition instruction means |val_id| is an undef.
            const reaching_def_inst: ?*Inst = du.getDef(val_id);
            if (reaching_def_inst) |rdi| {
                const rtype: *Type = type_mgr.getType(rdi.typeId()) orelse fatal("SSARewrite: unknown type %{d}", .{rdi.typeId()});
                if (!rtype.isSame(load_type)) {
                    var_id = val_id;
                } else {
                    found_reaching_def = true;
                }
            } else {
                found_reaching_def = true;
            }
        }

        // Schedule a replacement for the result of this load with |val_id|.
        const load_id: u32 = inst.resultId();
        self.setLoadReplacement(load_id, val_id);
        if (self.getPhiCandidate(val_id)) |defining_phi| defining_phi.addUser(load_id);
        return true;
    }

    fn generateSsaReplacements(self: *SsaRewriter, bb: *Block) bool {
        var it: ?*Inst = bb.insts.first;
        while (it) |inst| : (it = inst.next) {
            if (inst.op == .OpStore or inst.op == .OpVariable) {
                self.processStore(inst, bb);
            } else if (inst.op == .OpLoad) {
                if (!self.processLoad(inst, bb)) return false;
            }
        }
        // All the stores of |bb| have been scanned: it is ready to feed its successors.
        self.sealBlock(bb);
        return true;
    }

    fn getReplacement(self: *SsaRewriter, repl_val: u32) u32 {
        var val_id: u32 = repl_val;
        while (self.load_replacement.get(val_id)) |next| val_id = next;
        return val_id;
    }

    fn getPhiArgument(self: *SsaRewriter, pc: *const SsaPhiCandidate, ix: usize) u32 {
        var arg_id: u32 = pc.phi_args.items[ix];
        while (arg_id != 0) {
            const phi_user: ?*SsaPhiCandidate = self.getPhiCandidate(arg_id);
            // Not a Phi, or a Phi candidate ready to be emitted.
            if (phi_user == null or phi_user.?.isReady()) return arg_id;
            arg_id = phi_user.?.copy_of;
        }
        fatal("SSARewrite: no Phi candidate in the copy-of chain is ready to be generated", .{});
    }

    fn applyReplacements(self: *SsaRewriter) bool {
        const ctx: *Ctx = self.ctx;
        const du: *DefUseMgr = ctx.getDefUseMgr();
        var modified: bool = false;

        // Add Phi instructions from completed Phi candidates.
        var generated_phis: List(*Inst) = .{};
        for (self.phis_to_generate.items) |pc| {
            const local_var: *Inst = du.getDef(pc.var_id) orelse fatal("SSARewrite: variable %{d} is not defined", .{pc.var_id});
            const type_id: u32 = passGetPointeeTypeId(ctx, local_var);
            var phi_operands: List(Operand) = .{};
            var already_seen: Map(u32, u32) = .{};
            var arg_ix: usize = 0;
            for (ctx.cfg().preds(pc.bb.id())) |pred_label| {
                const op_val_id: u32 = self.getPhiArgument(pc, arg_ix);
                arg_ix += 1;
                if (!already_seen.contains(pred_label)) {
                    phi_operands.push(Operand.id(.IdRef, op_val_id));
                    phi_operands.push(Operand.id(.IdRef, pred_label));
                    already_seen.put(pred_label, op_val_id);
                }
                // else: two edges from the same parent block; the values are consistent (C++ asserts it)
            }

            const phi_inst: *Inst = Inst.make(.OpPhi, type_id, pc.result_id, phi_operands.items);
            generated_phis.push(phi_inst);
            du.analyzeInstDef(phi_inst);
            pc.bb.insts.pushFront(phi_inst); // BasicBlock::begin().InsertBefore: before every other instruction
            ctx.getDecorationMgr().cloneDecorationsSubset(pc.var_id, pc.result_id, &.{.RelaxedPrecision});
            // (SetDebugScope / AddDebugValueForVariable: no extended debug info in this port)
            modified = true;
        }

        // Scan the uses of all inserted Phi instructions separately, after all of them are registered.
        for (generated_phis.items) |phi_inst| du.analyzeInstUse(phi_inst);

        // Apply replacements from the load replacement table.
        var it: Map(u32, u32).Hm.Iterator = self.load_replacement.iterator();
        while (it.next()) |e| {
            const load_id: u32 = e.key_ptr.*;
            const val_id: u32 = self.getReplacement(e.value_ptr.*);
            const load_inst: *Inst = du.getDef(load_id) orelse fatal("SSARewrite: load %{d} is not defined", .{load_id});
            // Kill the names and decorations of the load first so they are not rewritten to |val_id|.
            ctx.killNamesAndDecoratesId(load_id);
            _ = ctx.replaceAllUsesWith(load_id, val_id);
            _ = ctx.killInst(load_inst);
            modified = true;
        }
        return modified;
    }

    fn finalizePhiCandidate(self: *SsaRewriter, pc: *SsaPhiCandidate) void {
        const cfg: *Cfg = self.ctx.cfg();
        var ix: usize = 0;
        for (cfg.preds(pc.bb.id())) |pred| {
            const pred_bb: *Block = cfg.block(pred);
            const arg: *u32 = &pc.phi_args.items[ix];
            ix += 1;
            if (arg.* == 0) {
                // A still unsealed predecessor is unreachable: use Undef.
                arg.* = if (self.isBlockSealed(pred_bb))
                    self.getReachingDef(pc.var_id, pred_bb)
                else
                    memGetUndefVal(self.ctx, self.st, pc.var_id);
            }
        }
        pc.is_complete = true;
        if (self.tryRemoveTrivialPhi(pc) == pc.result_id) {
            // complete and not trivial
            self.phis_to_generate.push(pc);
        }
    }

    fn finalizePhiCandidates(self: *SsaRewriter) void {
        while (self.incomplete_phis.pop()) |pc| self.finalizePhiCandidate(pc);
    }

    fn rewriteFunctionIntoSsa(self: *SsaRewriter, func: *Func) PassStatus {
        const ctx: *Ctx = self.ctx;
        // Collect variables that can be converted into SSA ids.
        memCollectTargetVars(ctx, self.st, func);

        // Generate all the SSA replacements and Phi candidates (incomplete and trivial Phis included).
        const succeeded: bool = ctx.cfg().whileEachBlockInReversePostOrder(func.entry(), self, generateSsaReplacements);
        if (!succeeded) return .failure;

        // Remove trivial Phis and add arguments to incomplete Phis.
        self.finalizePhiCandidates();

        // Finally apply all the replacements in the IR.
        const modified: bool = self.applyReplacements();
        return if (modified) .success_with_change else .success_without_change;
    }
};

pub const SsaRewrite = struct {
    pub const name = "ssa-rewrite";
    pub const preserved: u32 = 0;

    mem: MemState = .{},

    pub fn run(self: *SsaRewrite, ctx: *Ctx) PassStatus {
        self.* = .{};
        var status: PassStatus = .success_without_change;
        for (ctx.module.functions.items) |func| {
            if (func.isDeclaration()) continue;
            var rw = SsaRewriter{ .ctx = ctx, .st = &self.mem };
            status = statusCombine(status, rw.rewriteFunctionIntoSsa(func));
            if (status == .failure) return .failure;
            // (KillDebugDeclares of the target variables: no extended debug info in this port)
        }
        return status;
    }
};

// DeadBranchElimPass (dead_branch_elim_pass.cpp), flag --eliminate-dead-branches: replaces a conditional branch or switch
// on a constant by a branch to the live target and removes the blocks that become unreachable (patching OpPhi operands
// and structured merge / continue targets on the way).
//
// Unordered C++ containers: live_blocks / unreachable_merges / unreachable_continues / blocks_with_backedge are
// pointer-keyed sets and maps that are only probed for membership (live_blocks is iterated in
// MarkUnreachableStructuredTargets, but only to fill other sets/maps: the result does not depend on the order for
// valid input).

/// BasicBlock::KillAllInsts: label first (when `kill_label`), then every instruction (next read before the kill).
fn blockKillAllInsts(ctx: *Ctx, block: *Block, kill_label: bool) void {
    if (kill_label) _ = ctx.killInst(block.label);
    var it: ?*Inst = block.insts.first;
    while (it) |inst| {
        const nxt: ?*Inst = inst.next;
        _ = ctx.killInst(inst);
        it = nxt;
    }
}

pub const DeadBranchElim = struct {
    pub const name = "eliminate-dead-branches";
    pub const preserved: u32 = Analysis.def_use | Analysis.instr_to_block | Analysis.constants | Analysis.types;

    const kBranchCondTrueLabIdInIdx = 1;
    const kBranchCondFalseLabIdInIdx = 2;

    mem: MemState = .{},
    failure: bool = false,

    const Runner = struct { ctx: *Ctx, pass: *DeadBranchElim };
    const CondToSimplify = struct { block: *Block, live_lab_id: u32 };

    fn getConstCondition(ctx: *Ctx, cond_id: u32, cond_val: *bool) bool {
        const c_inst: *Inst = ctx.getDefUseMgr().getDef(cond_id) orelse fatal("DeadBranchElim: condition %{d} is not defined", .{cond_id});
        switch (c_inst.op) {
            .OpConstantNull, .OpConstantFalse => {
                cond_val.* = false;
                return true;
            },
            .OpConstantTrue => {
                cond_val.* = true;
                return true;
            },
            .OpLogicalNot => {
                var neg_val: bool = false;
                const cond_is_const: bool = getConstCondition(ctx, c_inst.getSingleWordInOperand(0), &neg_val);
                if (cond_is_const) cond_val.* = !neg_val;
                return cond_is_const;
            },
            else => return false,
        }
    }

    fn getConstInteger(ctx: *Ctx, sel_id: u32, sel_val: *u32) bool {
        const du: *DefUseMgr = ctx.getDefUseMgr();
        const s_inst: *Inst = du.getDef(sel_id) orelse fatal("DeadBranchElim: selector %{d} is not defined", .{sel_id});
        const type_inst: *Inst = du.getDef(s_inst.typeId()) orelse return false;
        if (type_inst.op != .OpTypeInt) return false;
        // Non-32 bit ints are not supported (like the C++).
        if (type_inst.getSingleWordInOperand(0) != 32) return false;
        if (s_inst.op == .OpConstant) {
            sel_val.* = s_inst.getSingleWordInOperand(0);
            return true;
        } else if (s_inst.op == .OpConstantNull) {
            sel_val.* = 0;
            return true;
        }
        return false;
    }

    fn addBranch(ctx: *Ctx, label_id: u32, bp: *Block) void {
        const new_branch: *Inst = Inst.make(.OpBranch, 0, 0, &.{Operand.id(.IdRef, label_id)});
        ctx.analyzeDefUse(new_branch);
        bp.addInst(new_branch);
    }

    fn getParentBlock(ctx: *Ctx, id: u32) *Block {
        return ctx.getInstrBlockById(id) orelse fatal("DeadBranchElim: id %{d} is not defined in a block", .{id});
    }

    const BackEdgeCtx = struct {
        header_id: u32,
        visited: *Set(u32),
        work_list: *List(u32),
        has_back_edge: bool = false,
    };

    fn backEdgeSuccessor(c: *BackEdgeCtx, succ_label_id: u32) void {
        if (c.visited.insert(succ_label_id)) c.work_list.push(succ_label_id);
        if (succ_label_id == c.header_id) c.has_back_edge = true;
    }

    fn addBlocksWithBackEdge(ctx: *Ctx, cont_id: u32, header_id: u32, merge_id: u32, blocks_with_back_edges: *Set(*Block)) void {
        var visited: Set(u32) = .{};
        _ = visited.insert(cont_id);
        _ = visited.insert(header_id);
        _ = visited.insert(merge_id);

        var work_list: List(u32) = .{};
        work_list.push(cont_id);

        while (work_list.pop()) |bb_id| {
            const bb: *Block = getParentBlock(ctx, bb_id);
            var c: BackEdgeCtx = .{ .header_id = header_id, .visited = &visited, .work_list = &work_list };
            bb.forEachSuccessorLabel(&c, backEdgeSuccessor);
            if (c.has_back_edge) _ = blocks_with_back_edges.insert(bb);
        }
    }

    const PushSuccCtx = struct { ctx: *Ctx, stack: *List(*Block) };

    fn pushSuccessor(c: PushSuccCtx, label: u32) void {
        c.stack.push(getParentBlock(c.ctx, label));
    }

    fn markLiveBlocks(ctx: *Ctx, func: *Func, live_blocks: *Set(*Block)) bool {
        var conditions_to_simplify: List(CondToSimplify) = .{};
        var blocks_with_backedge: Set(*Block) = .{};
        var stack: List(*Block) = .{};
        stack.push(func.blocks.items[0]);
        var modified: bool = false;
        while (stack.pop()) |block| {
            // Live blocks doubles as visited set.
            if (!live_blocks.insert(block)) continue;

            const cont_id: u32 = block.continueBlockIdIfAny();
            if (cont_id != 0) {
                addBlocksWithBackEdge(ctx, cont_id, block.id(), block.mergeBlockIdIfAny(), &blocks_with_backedge);
            }

            const terminator: *Inst = block.tail();
            var live_lab_id: u32 = 0;
            // Check if the terminator has a single valid successor.
            if (terminator.op == .OpBranchConditional) {
                var cond_val: bool = false;
                if (getConstCondition(ctx, terminator.getSingleWordInOperand(0), &cond_val)) {
                    live_lab_id = terminator.getSingleWordInOperand(if (cond_val) kBranchCondTrueLabIdInIdx else kBranchCondFalseLabIdInIdx);
                }
            } else if (terminator.op == .OpSwitch) {
                var sel_val: u32 = 0;
                if (getConstInteger(ctx, terminator.getSingleWordInOperand(0), &sel_val)) {
                    // Search switch operands for the selector value, use the default label when not found.
                    var case_val: u32 = 0;
                    for (0..terminator.numInOperands()) |icnt| {
                        const word: u32 = terminator.getInOperand(icnt).w[0];
                        if (icnt == 1) {
                            live_lab_id = word; // start with the default label
                        } else if (icnt > 1) {
                            if (icnt % 2 == 0) {
                                case_val = word;
                            } else if (case_val == sel_val) {
                                live_lab_id = word;
                                break;
                            }
                        }
                    }
                }
            }

            // Don't simplify back edges unless it becomes a branch to the header. Every loop must have exactly one
            // back edge to the loop header, so it cannot be removed.
            var simplify: bool = false;
            if (live_lab_id != 0) {
                if (!blocks_with_backedge.contains(block)) {
                    simplify = true; // not a back edge
                } else {
                    const struct_cfg_analysis: *StructCfg = ctx.getStructuredCfgAnalysis();
                    const header_id: u32 = struct_cfg_analysis.containingLoop(block.id());
                    if (live_lab_id == header_id) simplify = true; // the new branch will be a branch to the header
                }
            }

            if (simplify) {
                conditions_to_simplify.push(.{ .block = block, .live_lab_id = live_lab_id });
                stack.push(getParentBlock(ctx, live_lab_id));
            } else {
                // All successors are live.
                block.forEachSuccessorLabel(PushSuccCtx{ .ctx = ctx, .stack = &stack }, pushSuccessor);
            }
        }

        // Traverse the conditions in reverse order so nested constructs are simplified before the constructs that
        // contain them.
        var k: usize = conditions_to_simplify.len();
        while (k > 0) {
            k -= 1;
            const b: DeadBranchElim.CondToSimplify = conditions_to_simplify.items[k];
            if (simplifyBranch(ctx, b.block, b.live_lab_id)) modified = true;
        }
        return modified;
    }

    fn simplifyBranch(ctx: *Ctx, block: *Block, live_lab_id: u32) bool {
        const merge_inst: ?*Inst = block.getMergeInst();
        const terminator: *Inst = block.tail();
        if (merge_inst != null and merge_inst.?.op == .OpSelectionMerge) {
            const mi: *Inst = merge_inst.?;
            if (mi.nextNode().?.op == .OpSwitch and switchHasNestedBreak(ctx, block.id())) {
                if (terminator.numInOperands() == 2) {
                    // The branch cannot be removed and it already has a single case: no work to do.
                    return false;
                }
                // The switch has to stay because of a nested break: remove all cases except for the live one.
                const new_operands = [_]Operand{ terminator.getInOperand(0).*, Operand.id(.IdRef, live_lab_id) };
                terminator.setInOperands(&new_operands);
                ctx.updateDefUse(terminator);
            } else {
                // Check if the merge instruction is still needed because of a non-nested break from the construct.
                // Move the merge instruction if it is still needed.
                const cfg_analysis: *StructCfg = ctx.getStructuredCfgAnalysis();
                const first_break: ?*Inst = findFirstExitFromSelectionMerge(
                    ctx,
                    live_lab_id,
                    mi.getSingleWordInOperand(0),
                    cfg_analysis.loopMergeBlock(live_lab_id),
                    cfg_analysis.loopContinueBlock(live_lab_id),
                    cfg_analysis.switchMergeBlock(live_lab_id),
                );

                addBranch(ctx, live_lab_id, block);
                _ = ctx.killInst(terminator);
                if (first_break == null) {
                    _ = ctx.killInst(mi);
                } else {
                    _ = mi.removeFromList();
                    _ = first_break.?.insertBefore(mi);
                }
            }
        } else {
            addBranch(ctx, live_lab_id, block);
            _ = ctx.killInst(terminator);
        }
        return true;
    }

    fn markUnreachableStructuredTargets(
        ctx: *Ctx,
        live_blocks: *const Set(*Block),
        unreachable_merges: *Set(*Block),
        unreachable_continues: *Map(*Block, *Block),
    ) void {
        var it: Map(*Block, void).Hm.Iterator = live_blocks.iterator();
        while (it.next()) |e| {
            const block: *Block = e.key_ptr.*;
            const merge_id: u32 = block.mergeBlockIdIfAny();
            if (merge_id != 0) {
                const merge_block: *Block = getParentBlock(ctx, merge_id);
                if (!live_blocks.contains(merge_block)) _ = unreachable_merges.insert(merge_block);
                const cont_id: u32 = block.continueBlockIdIfAny();
                if (cont_id != 0) {
                    const cont_block: *Block = getParentBlock(ctx, cont_id);
                    if (!live_blocks.contains(cont_block)) unreachable_continues.put(cont_block, block);
                }
            }
        }
    }

    fn fixPhiNodesInLiveBlocks(
        self: *DeadBranchElim,
        ctx: *Ctx,
        func: *Func,
        live_blocks: *const Set(*Block),
        unreachable_continues: *const Map(*Block, *Block),
    ) PassStatus {
        const du: *DefUseMgr = ctx.getDefUseMgr();
        var modified: bool = false;
        for (func.blocks.items) |block| {
            if (!live_blocks.contains(block)) continue;
            var iter: ?*Inst = block.insts.first;
            while (iter) |inst| {
                if (inst.op != .OpPhi) break;

                var changed: bool = false;
                var backedge_added: bool = false;
                // Build a complete set of operands (not just input operands), starting with type and result id.
                var operands: List(Operand) = .{};
                operands.push(inst.getOperand(0).*);
                operands.push(inst.getOperand(1).*);
                // Iterate through the incoming labels and determine which to keep and/or modify. If there is an
                // unreachable continue block there will be an edge from that block to the header: it is kept to
                // maintain the structured control flow. If the header has more than 2 incoming edges the OpPhi
                // must have an entry for that edge, otherwise the OpPhi can be eliminated.
                var i: usize = 1;
                while (i < inst.numInOperands()) : (i += 2) {
                    // The predecessor id may name something that is not in a block (the function, on invalid input): C++
                    // gets a null block here, which is in neither map, so the incoming edge is dropped below.
                    const inc_opt: ?*Block = ctx.getInstrBlockById(inst.getSingleWordInOperand(i));
                    const cont_header: ?*Block = if (inc_opt) |inc_b| unreachable_continues.get(inc_b) else null;
                    if (cont_header != null and cont_header.? == block and inst.numInOperands() > 4) {
                        const val_def: *Inst = du.getDef(inst.getSingleWordInOperand(i - 1)) orelse fatal("DeadBranchElim: phi operand is not defined", .{});
                        if (val_def.op == .OpUndef) {
                            // Already an undef incoming value: no change necessary.
                            operands.push(inst.getInOperand(i - 1).*);
                            operands.push(inst.getInOperand(i).*);
                            backedge_added = true;
                        } else {
                            // Replace the incoming value with undef if this phi exists in the loop header.
                            // Otherwise this edge is not live since the unreachable continue block will be replaced
                            // with an unconditional branch to the header only.
                            const undef_id: u32 = memType2Undef(ctx, &self.mem, inst.typeId());
                            if (undef_id == 0) return .failure;
                            operands.push(Operand.id(.IdRef, undef_id));
                            operands.push(inst.getInOperand(i).*);
                            changed = true;
                            backedge_added = true;
                        }
                    } else if (inc_opt != null and live_blocks.contains(inc_opt.?) and inc_opt.?.isSuccessor(block)) {
                        // Keep the live incoming edge.
                        operands.push(inst.getInOperand(i - 1).*);
                        operands.push(inst.getInOperand(i).*);
                    } else {
                        changed = true; // remove the incoming edge
                    }
                }

                if (changed) {
                    modified = true;
                    const continue_id: u32 = block.continueBlockIdIfAny();
                    if (!backedge_added and continue_id != 0 and unreachable_continues.contains(getParentBlock(ctx, continue_id)) and operands.len() > 4) {
                        // The backedge now branches from the continue block instead of a successor of the continue
                        // block: add an entry to the phi providing an undef for the continue block. Since the
                        // successor of the continue must also be unreachable (dominated by the continue block), any
                        // entry for the original backedge has been removed from the phi operands.
                        const undef_id: u32 = memType2Undef(ctx, &self.mem, inst.typeId());
                        if (undef_id == 0) return .failure;
                        operands.push(Operand.id(.IdRef, undef_id));
                        operands.push(Operand.id(.IdRef, continue_id));
                    }

                    // Either replace the phi with a single value or rebuild the phi out of |operands|. Type and
                    // result id are always present: the phi has a single source if two more operands follow.
                    if (operands.len() == 4) {
                        const repl_id: u32 = operands.items[2].w[0];
                        ctx.killNamesAndDecoratesId(inst.resultId());
                        _ = ctx.replaceAllUsesWith(inst.resultId(), repl_id);
                        iter = ctx.killInst(inst);
                    } else {
                        // Forget the uses in the phi, replace the operands, re-analyze the used ids.
                        du.eraseUseRecordsOfOperandIds(inst);
                        inst.replaceOperands(operands.items);
                        du.analyzeInstUse(inst);
                        iter = inst.next;
                    }
                } else {
                    iter = inst.next;
                }
            }
        }
        return if (modified) .success_with_change else .success_without_change;
    }

    fn eraseDeadBlocks(
        ctx: *Ctx,
        func: *Func,
        live_blocks: *const Set(*Block),
        unreachable_merges: *const Set(*Block),
        unreachable_continues: *const Map(*Block, *Block),
    ) bool {
        const du: *DefUseMgr = ctx.getDefUseMgr();
        var modified: bool = false;
        var ebi: usize = 0;
        while (ebi < func.blocks.len()) {
            const blk: *Block = func.blocks.items[ebi];
            if (unreachable_continues.get(blk)) |header| {
                const cont_id: u32 = header.id();
                const t: *Inst = blk.tail();
                if (blk.insts.first != blk.insts.last or t.op != .OpBranch or t.getSingleWordInOperand(0) != cont_id) {
                    // Make unreachable, but leave the label.
                    blockKillAllInsts(ctx, blk, false);
                    // Add an unconditional branch to the header.
                    const br: *Inst = Inst.make(.OpBranch, 0, 0, &.{Operand.id(.IdRef, cont_id)});
                    blk.addInst(br);
                    du.analyzeInstUse(br);
                    modified = true;
                }
                ebi += 1;
            } else if (unreachable_merges.contains(blk)) {
                const t: *Inst = blk.tail();
                if (blk.insts.first != blk.insts.last or t.op != .OpUnreachable) {
                    // Make unreachable, but leave the label.
                    blockKillAllInsts(ctx, blk, false);
                    // Add an unreachable terminator.
                    const un: *Inst = Inst.make(.OpUnreachable, 0, 0, &.{});
                    blk.addInst(un);
                    ctx.analyzeUses(un);
                    modified = true;
                }
                ebi += 1;
            } else if (!live_blocks.contains(blk)) {
                // Kill this block.
                blockKillAllInsts(ctx, blk, true);
                _ = func.blocks.orderedRemove(ebi);
                modified = true;
            } else {
                ebi += 1;
            }
        }
        return modified;
    }

    fn eliminateDeadBranches(self: *DeadBranchElim, ctx: *Ctx, func: *Func) PassStatus {
        if (func.isDeclaration()) return .success_without_change;

        var modified: bool = false;
        var live_blocks: Set(*Block) = .{};
        if (markLiveBlocks(ctx, func, &live_blocks)) modified = true;

        var unreachable_merges: Set(*Block) = .{};
        var unreachable_continues: Map(*Block, *Block) = .{};
        markUnreachableStructuredTargets(ctx, &live_blocks, &unreachable_merges, &unreachable_continues);
        const phi_status: PassStatus = self.fixPhiNodesInLiveBlocks(ctx, func, &live_blocks, &unreachable_continues);
        if (phi_status == .failure) return .failure;
        if (phi_status == .success_with_change) modified = true;
        if (eraseDeadBlocks(ctx, func, &live_blocks, &unreachable_merges, &unreachable_continues)) modified = true;

        return if (modified) .success_with_change else .success_without_change;
    }

    fn reorderStructured(ctx: *Ctx, func: *Func) bool {
        if (func.isDeclaration()) return true; // (the C++ reads blocks_[0] of an empty vector here)
        var order: List(*Block) = .{};
        ctx.cfg().computeStructuredOrderNoEnd(func, func.blocks.items[0], &order);
        func.reorderBasicBlocks(order.items);
        return true;
    }

    fn reorderDominators(ctx: *Ctx, func: *Func) bool {
        if (func.isDeclaration()) return true;
        const dominators: *DominatorAnalysis = ctx.getDominatorAnalysis(func);
        const nodes: List(*DomNode) = dominators.getDomTree().nodesPreOrder();
        var blocks: List(*Block) = .{};
        for (nodes.items) |n| {
            if (n.id() != 0) blocks.push(n.bb);
        }
        var i: usize = 1;
        while (i < blocks.len()) : (i += 1) func.moveBasicBlockToAfter(blocks.items[i].id(), blocks.items[i - 1]);
        return true;
    }

    fn fixBlockOrder(ctx: *Ctx) void {
        ctx.buildInvalidAnalyses(Analysis.cfg | Analysis.dominator);
        // Structured order is more intuitive so use it where possible.
        if (ctx.getFeatureMgr().hasCapability(.Shader)) {
            _ = ctx.processReachableCallTree(ctx, reorderStructured);
        } else {
            _ = ctx.processReachableCallTree(ctx, reorderDominators);
        }
    }

    fn findFirstExitFromSelectionMerge(
        ctx: *Ctx,
        start_block_id_in: u32,
        merge_block_id: u32,
        loop_merge_id: u32,
        loop_continue_id: u32,
        switch_merge_id: u32,
    ) ?*Inst {
        // To find the "first" exit, follow branches looking for a conditional branch that is not in a nested
        // construct and is not the header of a new construct.
        var start_block_id: u32 = start_block_id_in;
        while (start_block_id != merge_block_id and start_block_id != loop_merge_id and start_block_id != loop_continue_id) {
            const start_block: *Block = getParentBlock(ctx, start_block_id);
            const branch: *Inst = start_block.tail();
            var next_block_id: u32 = 0;
            switch (branch.op) {
                .OpBranchConditional => {
                    next_block_id = start_block.mergeBlockIdIfAny();
                    if (next_block_id == 0) {
                        // If a possible target is the |loop_merge_id| or |loop_continue_id|, which are not the
                        // current merge node, continue the search with the other target.
                        var i: usize = 1;
                        while (i < 3) : (i += 1) {
                            if (branch.getSingleWordInOperand(i) == loop_merge_id and loop_merge_id != merge_block_id) {
                                next_block_id = branch.getSingleWordInOperand(3 - i);
                                break;
                            }
                            if (branch.getSingleWordInOperand(i) == loop_continue_id and loop_continue_id != merge_block_id) {
                                next_block_id = branch.getSingleWordInOperand(3 - i);
                                break;
                            }
                            if (branch.getSingleWordInOperand(i) == switch_merge_id and switch_merge_id != merge_block_id) {
                                next_block_id = branch.getSingleWordInOperand(3 - i);
                                break;
                            }
                        }
                        if (next_block_id == 0) return branch;
                    }
                },
                .OpSwitch => {
                    next_block_id = start_block.mergeBlockIdIfAny();
                    if (next_block_id == 0) {
                        // A switch with no merge instruction can have at most 5 targets: the merge block, the loop
                        // merge, the loop continue, the switch merge (== merge block) and 1 block inside the
                        // current region.
                        //  1. No jump to a block inside the current construct: no conditional break (null).
                        //  2. Jumps to the merge block and a block inside: conditional break (this branch).
                        //  3. Otherwise it may break, but not to the current merge block: continue inside.
                        var found_break: bool = false;
                        var i: usize = 1;
                        while (i < branch.numInOperands()) : (i += 2) {
                            const target: u32 = branch.getSingleWordInOperand(i);
                            if (target == merge_block_id) {
                                found_break = true;
                            } else if (target != loop_merge_id and target != loop_continue_id) {
                                next_block_id = branch.getSingleWordInOperand(i);
                            }
                        }
                        if (next_block_id == 0) return null; // case 1
                        if (found_break) return branch; // case 2
                        // case 3 falls through
                    }
                },
                .OpBranch => {
                    // Check if this is the header of a loop nested in the selection construct.
                    next_block_id = start_block.mergeBlockIdIfAny();
                    if (next_block_id == 0) next_block_id = branch.getSingleWordInOperand(0);
                },
                else => return null,
            }
            start_block_id = next_block_id;
        }
        return null;
    }

    fn switchHasNestedBreak(ctx: *Ctx, switch_header_id: u32) bool {
        const start_block: *Block = getParentBlock(ctx, switch_header_id);
        const merge_block_id: u32 = start_block.mergeBlockIdIfAny();
        const cfg_analysis: *StructCfg = ctx.getStructuredCfgAnalysis();
        for (ctx.getDefUseMgr().registeredUsersOfId(merge_block_id)) |inst| {
            if (!inst.isBranch()) continue;
            const bb: *Block = ctx.getInstrBlock(inst) orelse fatal("DeadBranchElim: branch is not in a block", .{});
            if (bb.id() == switch_header_id) continue;
            // A branch to the merge block from inside the switch construct that is not a header of its own construct is a nested break.
            if (cfg_analysis.containingConstructOfInst(inst) == switch_header_id and bb.getMergeInst() == null) continue;
            return true;
        }
        return false;
    }

    fn processFn(r: Runner, func: *Func) bool {
        const status: PassStatus = r.pass.eliminateDeadBranches(r.ctx, func);
        if (status == .failure) {
            r.pass.failure = true;
            return false;
        }
        return status == .success_with_change;
    }

    pub fn run(self: *DeadBranchElim, ctx: *Ctx) PassStatus {
        self.* = .{};
        // Do not process if the module contains OpGroupDecorate (KillNamesAndDecorates cannot handle it).
        var ai: ?*Inst = ctx.module.annotations.first;
        while (ai) |a| : (ai = a.next) {
            if (a.op == .OpGroupDecorate) return .success_without_change;
        }
        const modified: bool = ctx.processReachableCallTree(Runner{ .ctx = ctx, .pass = self }, processFn);
        if (self.failure) return .failure;
        if (modified) {
            ctx.invalidateAnalyses(Analysis.cfg | Analysis.dominator | Analysis.structured_cfg);
            fixBlockOrder(ctx);
        }
        return if (modified) .success_with_change else .success_without_change;
    }
};

// MergeReturnPass (merge_return_pass.cpp), flag --merge-return: makes every function return from a single block while
// keeping the control flow structured (a return inside a loop or selection becomes a branch to the merge block, and the
// code after it is guarded by a flag).
//
// std::list<BasicBlock*> order -> MrOrder (a List plus the index the traversal loop is currently at, adjusted when an
// element is inserted at or before it, so the visit sequence equals the std::list iteration).
// Unordered C++ containers: original_dominator_, new_edges_, return_blocks_, predicated, seen are only probed.
// Members that survive from function to function in the C++ (constant_true_, original_dominator_, new_edges_,
// return_blocks_) are kept across functions here as well.

const MrState = struct {
    break_merge: ?*Inst,
    current_merge: ?*Inst,

    fn inBreakable(self: MrState) bool {
        return self.break_merge != null;
    }
    fn currentMergeId(self: MrState) u32 {
        return if (self.current_merge) |m| m.getSingleWordInOperand(0) else 0;
    }
    fn breakMergeId(self: MrState) u32 {
        return if (self.break_merge) |m| m.getSingleWordInOperand(0) else 0;
    }
    fn breakMergeInst(self: MrState) ?*Inst {
        return self.break_merge;
    }
};

const MrOrder = struct {
    items: List(*Block) = .{},
    /// index of the element the traversal loop is visiting
    cursor: usize = 0,

    /// InsertAfterElement
    fn insertAfterElement(self: *MrOrder, element: *Block, new_element: *Block) void {
        var pos: usize = 0;
        while (pos < self.items.len() and self.items.items[pos] != element) pos += 1;
        check(pos < self.items.len(), "MergeReturn.insertAfterElement: element not in the order");
        self.items.insert(pos + 1, new_element);
        if (pos + 1 <= self.cursor) self.cursor += 1;
    }
};

pub const MergeReturn = struct {
    pub const name = "merge-return";
    pub const preserved: u32 = Analysis.constants | Analysis.types;

    mem: MemState = .{},
    state: List(MrState) = .{},
    function: ?*Func = null,
    return_flag: ?*Inst = null,
    return_value: ?*Inst = null,
    constant_true: ?*Inst = null,
    final_return_block: ?*Block = null,
    original_dominator: Map(*Block, ?*Inst) = .{},
    new_edges: Map(*Block, Set(u32)) = .{},
    return_blocks: Set(u32) = .{},
    failed: bool = false,

    const Runner = struct { ctx: *Ctx, pass: *MergeReturn, is_shader: bool };

    fn currentState(self: *MergeReturn) MrState {
        return self.state.items[self.state.len() - 1];
    }

    fn stateAt(self: *MergeReturn, idx: isize) MrState {
        if (idx < 0) fatal("MergeReturn: ran past the outermost structured control flow state", .{});
        return self.state.items[@intCast(idx)];
    }

    fn newEdgesOf(self: *MergeReturn, b: *Block) *Set(u32) {
        const gop: Map(*Block, Set(u32)).GetOrPutResult = self.new_edges.getOrPut(b);
        if (!gop.found_existing) gop.value_ptr.* = .{};
        return gop.value_ptr;
    }

    fn generateState(self: *MergeReturn, block: *Block) void {
        if (block.getMergeInst()) |merge_inst| {
            if (merge_inst.op == .OpLoopMerge) {
                // If new loop, break to this loop merge block
                self.state.push(.{ .break_merge = merge_inst, .current_merge = merge_inst });
            } else {
                const branch_inst: *Inst = merge_inst.nextNode().?;
                if (branch_inst.op == .OpSwitch) {
                    // If switch inside of loop, break to the innermost loop merge block. Otherwise break to this
                    // switch merge block.
                    const last_merge_inst: ?*Inst = self.currentState().breakMergeInst();
                    if (last_merge_inst != null and last_merge_inst.?.op == .OpLoopMerge) {
                        self.state.push(.{ .break_merge = last_merge_inst, .current_merge = merge_inst });
                    } else {
                        self.state.push(.{ .break_merge = merge_inst, .current_merge = merge_inst });
                    }
                } else {
                    // If branch conditional inside loop, always break to the innermost loop merge block. If branch
                    // conditional inside switch, break to the innermost switch merge block.
                    const last_merge_inst: ?*Inst = self.currentState().breakMergeInst();
                    self.state.push(.{ .break_merge = last_merge_inst, .current_merge = merge_inst });
                }
            }
        }
    }

    fn collectReturnBlocks(func: *Func) List(*Block) {
        var out: List(*Block) = .{};
        for (func.blocks.items) |block| {
            // C++ reads the tail of an empty block through the list sentinel (undefined behaviour; a truncated function
            // whose last block has no terminator). The garbage opcode is not a return in practice: skip such blocks.
            if (block.insts.last == null) continue;
            const t: *Inst = block.tail();
            if (t.op == .OpReturn or t.op == .OpReturnValue) out.push(block);
        }
        return out;
    }

    // ---- structured path --------------------------------------------------------------------------------

    fn hasNontrivialUnreachableBlocks(ctx: *Ctx, func: *Func) bool {
        var reachable_blocks: Set(u32) = .{};
        const Mark = struct {
            fn f(s: *Set(u32), bb: *Block) void {
                _ = s.insert(bb.id());
            }
        };
        ctx.cfg().forEachBlockInPostOrder(func.entry(), &reachable_blocks, Mark.f);

        for (func.blocks.items) |bb| {
            if (reachable_blocks.contains(bb.id())) continue;

            const struct_cfg_analysis: *StructCfg = ctx.getStructuredCfgAnalysis();
            if (struct_cfg_analysis.isContinueBlock(bb.id())) {
                // |bb| must be an empty block ending with a branch to the header.
                const inst: *Inst = bb.insts.first.?;
                if (inst.op != .OpBranch) return true;
                if (inst.getSingleWordInOperand(0) != struct_cfg_analysis.containingLoop(bb.id())) return true;
            } else if (struct_cfg_analysis.isMergeBlock(bb.id())) {
                // |bb| must be an empty block ending with OpUnreachable.
                if (bb.insts.first.?.op != .OpUnreachable) return true;
            } else {
                return true;
            }
        }
        return false;
    }

    fn recordImmediateDominators(self: *MergeReturn, ctx: *Ctx, func: *Func) void {
        const dom_tree: *DominatorAnalysis = ctx.getDominatorAnalysis(func);
        for (func.blocks.items) |bb| {
            const dominator_bb: ?*Block = dom_tree.immediateDominator(bb);
            if (dominator_bb != null and dominator_bb.? != ctx.cfg().pseudo_entry_block) {
                self.original_dominator.put(bb, dominator_bb.?.terminator());
            } else {
                self.original_dominator.put(bb, null);
            }
        }
    }

    fn createReturnBlock(self: *MergeReturn, ctx: *Ctx) bool {
        const label_id: u32 = ctx.takeNextId();
        const return_block: *Block = Block.new(Inst.make(.OpLabel, 0, label_id, &.{}));
        self.function.?.addBlock(return_block);
        self.final_return_block = return_block;
        ctx.analyzeDefUse(return_block.label);
        return true;
    }

    fn createReturn(self: *MergeReturn, ctx: *Ctx, block: *Block) bool {
        if (!self.addReturnValue(ctx)) return false;

        if (self.return_value) |rv| {
            // Load and return the final return value
            const load_id: u32 = ctx.takeNextId();
            const load: *Inst = Inst.make(.OpLoad, self.function.?.typeId(), load_id, &.{Operand.id(.IdRef, rv.resultId())});
            block.addInst(load);
            ctx.analyzeDefUse(load);
            ctx.getDecorationMgr().cloneDecorationsSubset(rv.resultId(), load_id, &.{.RelaxedPrecision});

            const ret: *Inst = Inst.make(.OpReturnValue, 0, 0, &.{Operand.id(.IdRef, load_id)});
            block.addInst(ret);
            ctx.analyzeDefUse(ret);
        } else {
            const ret: *Inst = Inst.make(.OpReturn, 0, 0, &.{});
            block.addInst(ret);
            ctx.analyzeDefUse(ret);
        }
        return true;
    }

    fn addReturnValue(self: *MergeReturn, ctx: *Ctx) bool {
        if (self.return_value != null) return true;

        const func: *Func = self.function.?;
        const return_type_id: u32 = func.typeId();
        const rt: *Inst = ctx.getDefUseMgr().getDef(return_type_id) orelse fatal("MergeReturn: return type %{d} is not defined", .{return_type_id});
        if (rt.op == .OpTypeVoid) return true;

        const return_ptr_type: u32 = ctx.getTypeMgr().findPointerToType(return_type_id, @intFromEnum(StorageClass.Function));

        const var_id: u32 = ctx.takeNextId();
        const return_value: *Inst = Inst.make(.OpVariable, return_ptr_type, var_id, &.{Operand.single(.StorageClass, @intFromEnum(StorageClass.Function))});

        const entry_block: *Block = func.blocks.items[0];
        _ = entry_block.insts.first.?.insertBefore(return_value);
        self.return_value = return_value;
        ctx.analyzeDefUse(return_value);

        ctx.getDecorationMgr().cloneDecorationsSubset(func.id(), var_id, &.{.RelaxedPrecision});
        return true;
    }

    fn addReturnFlag(self: *MergeReturn, ctx: *Ctx) bool {
        if (self.return_flag != null) return true;

        const type_mgr: *TypeMgr = ctx.getTypeMgr();
        const const_mgr: *ConstMgr = ctx.getConstantMgr();

        const temp = Type.simple(.bool_);
        const bool_id: u32 = type_mgr.getTypeInstruction(&temp);
        if (bool_id == 0) return false;
        const bool_type: *Type = type_mgr.getType(bool_id) orelse fatal("MergeReturn: bool type %{d} is unknown", .{bool_id});

        const false_const: ?*const Constant = const_mgr.getConstant(bool_type, &.{0});
        const false_inst: *Inst = const_mgr.getDefiningInstruction(false_const, 0, null) orelse return false;
        const const_false_id: u32 = false_inst.resultId();

        const bool_ptr_id: u32 = type_mgr.findPointerToType(bool_id, @intFromEnum(StorageClass.Function));
        if (bool_ptr_id == 0) return false;

        const var_id: u32 = ctx.takeNextId();
        const return_flag: *Inst = Inst.make(.OpVariable, bool_ptr_id, var_id, &.{
            Operand.single(.StorageClass, @intFromEnum(StorageClass.Function)),
            Operand.id(.IdRef, const_false_id),
        });

        const entry_block: *Block = self.function.?.blocks.items[0];
        _ = entry_block.insts.first.?.insertBefore(return_flag);
        self.return_flag = return_flag;
        ctx.analyzeDefUse(return_flag);
        return true;
    }

    fn recordReturned(self: *MergeReturn, ctx: *Ctx, block: *Block) bool {
        const t: *Inst = block.tail();
        if (t.op != .OpReturn and t.op != .OpReturnValue) return true;

        check(self.return_flag != null, "Did not generate the return flag variable.");

        if (self.constant_true == null) {
            const temp = Type.simple(.bool_);
            const type_mgr: *TypeMgr = ctx.getTypeMgr();
            const bool_type: *Type = type_mgr.getRegisteredType(&temp) orelse fatal("MergeReturn: cannot register the bool type", .{});
            const const_mgr: *ConstMgr = ctx.getConstantMgr();
            const true_const: ?*const Constant = const_mgr.getConstant(bool_type, &.{1});
            self.constant_true = const_mgr.getDefiningInstruction(true_const, 0, null) orelse return false;
            ctx.updateDefUse(self.constant_true.?);
        }

        const return_store: *Inst = Inst.make(.OpStore, 0, 0, &.{
            Operand.id(.IdRef, self.return_flag.?.resultId()),
            Operand.id(.IdRef, self.constant_true.?.resultId()),
        });
        _ = block.tail().insertBefore(return_store);
        ctx.analyzeDefUse(return_store);
        return true;
    }

    fn recordReturnValue(self: *MergeReturn, ctx: *Ctx, block: *Block) void {
        const terminator: *Inst = block.tail();
        if (terminator.op != .OpReturnValue) return;

        check(self.return_value != null, "Did not generate the variable to hold the return value.");

        const value_store: *Inst = Inst.make(.OpStore, 0, 0, &.{
            Operand.id(.IdRef, self.return_value.?.resultId()),
            Operand.id(.IdRef, terminator.getSingleWordInOperand(0)),
        });
        _ = terminator.insertBefore(value_store);
        ctx.analyzeDefUse(value_store);
    }

    fn updatePhiNodes(self: *MergeReturn, ctx: *Ctx, new_source: *Block, target: *Block) bool {
        var it: ?*Inst = target.insts.first;
        while (it) |inst| {
            const nxt: ?*Inst = inst.next;
            if (inst.op != .OpPhi) break;
            const undef_id: u32 = memType2Undef(ctx, &self.mem, inst.typeId());
            if (undef_id == 0) return false;
            inst.addOperand(Operand.id(.IdRef, undef_id));
            inst.addOperand(Operand.id(.IdRef, new_source.id()));
            ctx.updateDefUse(inst);
            it = nxt;
        }
        return true;
    }

    fn branchToBlock(self: *MergeReturn, ctx: *Ctx, block: *Block, target: u32) bool {
        const t: *Inst = block.tail();
        if (t.op == .OpReturn or t.op == .OpReturnValue) {
            if (!self.recordReturned(ctx, block)) return false;
            self.recordReturnValue(ctx, block);
        }

        const target_block: *Block = ctx.getInstrBlockById(target) orelse fatal("MergeReturn: target %{d} is not in a block", .{target});
        if (target_block.getLoopMergeInst() != null) {
            _ = cfgSplitLoopHeader(ctx, target_block);
        }
        if (!self.updatePhiNodes(ctx, block, target_block)) return false;

        const return_inst: *Inst = block.tail();
        return_inst.setOpcode(.OpBranch);
        return_inst.replaceOperands(&.{Operand.id(.IdRef, target)});
        ctx.getDefUseMgr().analyzeInstDefUse(return_inst);
        _ = self.newEdgesOf(target_block).insert(block.id());
        ctx.cfg().addEdge(block.id(), target);
        return true;
    }

    fn processStructuredBlock(self: *MergeReturn, ctx: *Ctx, block: *Block) bool {
        if (block.insts.last == null) return true;

        const tail_opcode: Op = block.tail().op;
        if (tail_opcode == .OpReturn or tail_opcode == .OpReturnValue) {
            if (self.return_flag == null) {
                if (!self.addReturnFlag(ctx)) return false;
            }
        }

        if (tail_opcode == .OpReturn or tail_opcode == .OpReturnValue or tail_opcode == .OpUnreachable) {
            check(self.currentState().inBreakable(), "Should be in the placeholder construct.");
            if (!self.branchToBlock(ctx, block, self.currentState().breakMergeId())) return false;
            _ = self.return_blocks.insert(block.id());
        }
        return true;
    }

    // ---- phi creation after predication -----------------------------------------------------------------

    const RegenCtx = struct {
        self: *MergeReturn,
        ctx: *Ctx,
        dom_tree: *DominatorAnalysis,
        merge_block: *Block,
        succeeded: *bool,
    };

    fn regenVisitId(c: RegenCtx, use_id: *u32) void {
        if (!c.succeeded.*) return;
        const use: *Inst = c.ctx.getDefUseMgr().getDef(use_id.*) orelse fatal("MergeReturn: id %{d} is not defined", .{use_id.*});
        const use_bb: ?*Block = c.ctx.getInstrBlock(use);
        if (use_bb != null and !c.dom_tree.dominates(use_bb.?, c.merge_block)) {
            if (!c.self.createPhiNodesForInst(c.ctx, c.merge_block, use)) c.succeeded.* = false;
        }
    }

    const ReplaceUse = struct { old_id: u32, new_id: u32 };

    fn replaceUseCb(c: ReplaceUse, id: *u32) void {
        if (id.* == c.old_id) id.* = c.new_id;
    }

    fn createPhiNodesForInst(self: *MergeReturn, ctx: *Ctx, merge_block: *Block, inst: *Inst) bool {
        const dom_tree: *DominatorAnalysis = ctx.getDominatorAnalysis(merge_block.parent.?);

        if (inst.resultId() != 0) {
            const inst_bb: *Block = ctx.getInstrBlock(inst) orelse fatal("MergeReturn: instruction %{d} is not in a block", .{inst.resultId()});
            var users_to_update: List(*Inst) = .{};
            for (ctx.getDefUseMgr().registeredUsers(inst)) |user| {
                var user_bb: ?*Block = null;
                if (user.op != .OpPhi) {
                    user_bb = ctx.getInstrBlock(user);
                } else {
                    // For OpPhi, the use is considered to be in the predecessor.
                    var i: usize = 0;
                    while (i < user.numInOperands()) : (i += 2) {
                        if (user.getSingleWordInOperand(i) == inst.resultId()) {
                            const user_bb_id: u32 = user.getSingleWordInOperand(i + 1);
                            user_bb = ctx.getInstrBlockById(user_bb_id);
                            break;
                        }
                    }
                }
                // If |user_bb| is null, |user| is not in the function: an OpName or decoration, which must not be replaced
                // with the result of the OpPhi.
                if (user_bb) |ub| {
                    if (!dom_tree.dominates(inst_bb, ub)) users_to_update.push(user);
                }
            }

            if (users_to_update.len() == 0) return true;

            // There is at least one value that needs to be replaced. First create the OpPhi instruction.
            const undef_id: u32 = memType2Undef(ctx, &self.mem, inst.typeId());
            var phi_operands: List(u32) = .{};
            const new_edges: *Set(u32) = self.newEdgesOf(merge_block);

            // Add the OpPhi operands. If the predecessor is a return block use undef, otherwise use |inst|'s id.
            var preds: List(u32) = .{};
            preds.pushSlice(ctx.cfg().preds(merge_block.id()));
            for (preds.items) |pred_id| {
                if (new_edges.contains(pred_id)) {
                    phi_operands.push(undef_id);
                } else {
                    phi_operands.push(inst.resultId());
                }
                phi_operands.push(pred_id);
            }

            var new_phi: *Inst = undefined;
            // If the instruction is a pointer and variable pointers are not an option, the instruction has to be
            // regenerated instead of creating an OpPhi: otherwise the SPIR-V would be invalid.
            const inst_type: *Inst = ctx.getDefUseMgr().getDef(inst.typeId()) orelse fatal("MergeReturn: type %{d} is not defined", .{inst.typeId()});
            var regenerate_instruction: bool = false;
            if (inst_type.op == .OpTypePointer) {
                if (!ctx.getFeatureMgr().hasCapability(.VariablePointers)) regenerate_instruction = true;
                const storage_class: u32 = inst_type.getSingleWordInOperand(0);
                if (storage_class != @intFromEnum(StorageClass.Workgroup) and storage_class != @intFromEnum(StorageClass.StorageBuffer)) {
                    regenerate_instruction = true;
                }
            }

            if (regenerate_instruction) {
                const regen_inst: *Inst = inst.clone();
                const new_id: u32 = ctx.takeNextId();
                regen_inst.setResultId(new_id);
                var insert_pos: *Inst = merge_block.insts.first.?;
                while (insert_pos.op == .OpPhi) insert_pos = insert_pos.nextNode().?;
                new_phi = insert_pos.insertBefore(regen_inst);
                ctx.getDefUseMgr().analyzeInstDefUse(new_phi);

                var succeeded: bool = true;
                new_phi.forEachInId(RegenCtx{ .self = self, .ctx = ctx, .dom_tree = dom_tree, .merge_block = merge_block, .succeeded = &succeeded }, regenVisitId);
                if (!succeeded) return false;
            } else {
                const builder = InstBuilder.init(ctx, merge_block.insts.first.?, Analysis.def_use | Analysis.instr_to_block);
                new_phi = builder.addPhi(inst.typeId(), phi_operands.items, 0) orelse return false;
            }
            const result_of_phi: u32 = new_phi.resultId();

            // Update all of the users to use the result of the new OpPhi.
            for (users_to_update.items) |user| {
                user.forEachInId(ReplaceUse{ .old_id = inst.resultId(), .new_id = result_of_phi }, replaceUseCb);
                ctx.analyzeUses(user);
            }
        }
        return true;
    }

    fn addNewPhiNodesForBlock(self: *MergeReturn, ctx: *Ctx, bb: *Block) bool {
        // New phi nodes are needed for any id whose definition used to dominate |bb|, but no longer dominates it.
        // These are found by walking the dominator tree starting at the original immediate dominator of |bb| and
        // ending at its current dominator. The new phi nodes of the original dominators of |bb| have to be added
        // first, so the order of the structured order traversal matters.
        const dom_tree: *DominatorAnalysis = ctx.getDominatorAnalysis(self.function.?);

        const dominator: *Block = dom_tree.immediateDominator(bb) orelse return true;

        // original_dominator_[bb]: blocks created by the pass have no entry (the C++ operator[] yields nullptr)
        const orig: ?*Inst = self.original_dominator.get(bb) orelse null;
        var current_bb: ?*Block = if (orig) |o| ctx.getInstrBlock(o) else null;
        while (current_bb != null and current_bb.? != dominator) {
            var it: ?*Inst = current_bb.?.insts.first;
            while (it) |inst| : (it = inst.next) {
                if (!self.createPhiNodesForInst(ctx, bb, inst)) return false;
            }
            current_bb = dom_tree.immediateDominator(current_bb.?);
        }
        return true;
    }

    fn addNewPhiNodes(self: *MergeReturn, ctx: *Ctx) bool {
        var order: List(*Block) = .{};
        ctx.cfg().computeStructuredOrderNoEnd(self.function.?, self.function.?.blocks.items[0], &order);
        for (order.items) |bb| {
            if (!self.addNewPhiNodesForBlock(ctx, bb)) return false;
        }
        return true;
    }

    // ---- predication ------------------------------------------------------------------------------------

    fn breakFromConstruct(self: *MergeReturn, ctx: *Ctx, block: *Block, predicated: *Set(*Block), order: *MrOrder, break_merge_inst: *Inst) bool {
        // Make sure the CFG is built here: otherwise it is very hard to know which new blocks need updating.
        ctx.invalidateAnalyses(Analysis.cfg);
        ctx.buildInvalidAnalyses(Analysis.cfg);
        const cfg: *Cfg = ctx.cfg();

        // If |block| is a loop header, the back edge must jump to the original code, not the new header.
        if (block.getLoopMergeInst() != null) {
            if (cfgSplitLoopHeader(ctx, block) == null) return false;
        }

        const merge_block_id: u32 = break_merge_inst.getSingleWordInOperand(0);
        const merge_block: *Block = ctx.getInstrBlockById(merge_block_id) orelse fatal("MergeReturn: merge block %{d} not found", .{merge_block_id});
        if (merge_block.getLoopMergeInst() != null) {
            _ = cfgSplitLoopHeader(ctx, merge_block);
        }

        // Leave the phi instructions behind.
        const iter: ?*Inst = firstNonPhi(block);

        // Forget about the edges leaving block. They will be removed.
        cfg.removeSuccessorEdges(block);

        const old_body_id: u32 = ctx.takeNextId();
        const old_body: *Block = blockSplit(ctx, block, old_body_id, iter);
        _ = predicated.insert(old_body);

        // If a return block is being split, mark the new body block also as a return block.
        if (self.return_blocks.contains(block.id())) {
            _ = self.return_blocks.insert(old_body_id);
        }

        // If |block| was a continue target for a loop |old_body| is now the correct continue target.
        if (break_merge_inst.op == .OpLoopMerge and break_merge_inst.getSingleWordInOperand(1) == block.id()) {
            break_merge_inst.setInOperand(1, &.{old_body.id()});
            ctx.updateDefUse(break_merge_inst);
        }

        // Update |order| so old_block will be traversed.
        order.insertAfterElement(block, old_body);

        // Within the new header: 1. load of the return status flag, 2. branch to |merge_block| (true) or old body
        // (false), 3. update the OpPhi instructions in |merge_block|, 4. update the CFG.
        const builder = InstBuilder.initAtBlockEnd(ctx, block, Analysis.def_use | Analysis.instr_to_block);
        // 1. Load of the return status flag
        const bool_type = Type.simple(.bool_);
        const bool_id: u32 = ctx.getTypeMgr().getId(&bool_type);
        check(bool_id != 0, "MergeReturn: the module has no bool type");
        const load_inst: *Inst = builder.addLoad(bool_id, self.return_flag.?.resultId(), 0) orelse return false;
        const load_id: u32 = load_inst.resultId();

        // 2. Branch to |merge_block| (true) or |old_body| (false); the construct merge is |old_body|.
        _ = builder.addConditionalBranch(load_id, merge_block.id(), old_body.id(), old_body.id(), 0);

        if (!self.newEdgesOf(merge_block).insert(block.id())) {
            // An edge to the merge block was inserted already: it now goes from |old_body| to |merge_block|.
            _ = self.newEdgesOf(merge_block).insert(old_body.id());
        }

        // 3. Update OpPhi instructions in |merge_block|.
        if (!self.updatePhiNodes(ctx, block, merge_block)) return false;

        // 4. Update the CFG. This is done after updating the OpPhi instructions because updatePhiNodes assumes the
        // edge from |block| has not been added to the CFG yet.
        cfg.addEdges(block);
        cfg.registerBlock(old_body);
        return true;
    }

    fn predicateBlocks(self: *MergeReturn, ctx: *Ctx, return_block: *Block, predicated: *Set(*Block), order: *MrOrder) bool {
        // The CFG is modified as the function proceeds so successors are not cached.
        if (predicated.contains(return_block)) return true;

        var block: ?*Block = null;
        const Succ = struct {
            ctx: *Ctx,
            out: *?*Block,
            fn f(c: @This(), label: u32) void {
                c.out.* = c.ctx.getInstrBlockById(label);
            }
        };
        return_block.forEachSuccessorLabel(Succ{ .ctx = ctx, .out = &block }, Succ.f);
        check(block != null, "Return blocks should have returns already replaced by a single unconditional branch.");

        // `state` is a reverse iterator over state_: index from the back, moving towards the outermost state.
        var state_idx: isize = @as(isize, @intCast(self.state.len())) - 1;
        if (block.?.id() == self.stateAt(state_idx).currentMergeId()) {
            state_idx -= 1;
        } else if (block.?.id() == self.stateAt(state_idx).breakMergeId()) {
            while (self.stateAt(state_idx).breakMergeId() == block.?.id()) state_idx -= 1;
        }

        while (block != null and block.? != self.final_return_block.?) {
            if (!predicated.insert(block.?)) break;
            // Skip structured subgraphs.
            check(self.stateAt(state_idx).inBreakable(), "Should be in the placeholder construct at the very least.");
            const break_merge_inst: *Inst = self.stateAt(state_idx).breakMergeInst().?;
            const merge_block_id: u32 = break_merge_inst.getSingleWordInOperand(0);
            while (self.stateAt(state_idx).breakMergeId() == merge_block_id) state_idx -= 1;
            if (!self.breakFromConstruct(ctx, block.?, predicated, order, break_merge_inst)) return false;
            block = ctx.getInstrBlockById(merge_block_id);
        }
        return true;
    }

    fn createSingleCaseSwitch(self: *MergeReturn, ctx: *Ctx, merge_target: *Block) bool {
        // Insert the switch before any code is run. The entry block is split so the OpVariable instructions remain
        // in the entry block.
        const func: *Func = self.function.?;
        const start_block: *Block = func.blocks.items[0];
        var split_pos: ?*Inst = start_block.insts.first;
        while (split_pos != null and split_pos.?.op == .OpVariable) split_pos = split_pos.?.next;

        const new_block_id: u32 = ctx.takeNextId();
        const old_block: *Block = blockSplit(ctx, start_block, new_block_id, split_pos);

        // (DebugFunctionDefinition of NonSemantic.Shader.DebugInfo cannot occur: that set is rejected or stripped at load)

        // Add the switch to the end of the entry block.
        const builder = InstBuilder.initAtBlockEnd(ctx, start_block, Analysis.def_use | Analysis.instr_to_block);
        const const_zero_id: u32 = builder.getUintConstantId(0);
        if (const_zero_id == 0) return false;
        _ = builder.addSwitch(const_zero_id, old_block.id(), &.{}, merge_target.id(), 0);

        if (ctx.areAnalysesValid(Analysis.cfg)) {
            ctx.cfg().registerBlock(old_block);
            ctx.cfg().addEdges(start_block);
        }
        return true;
    }

    fn addSingleCaseSwitchAroundFunction(self: *MergeReturn, ctx: *Ctx) bool {
        if (!self.createReturnBlock(ctx)) return false;
        if (!self.createReturn(ctx, self.final_return_block.?)) return false;

        if (ctx.areAnalysesValid(Analysis.cfg)) {
            ctx.cfg().registerBlock(self.final_return_block.?);
        }

        return self.createSingleCaseSwitch(ctx, self.final_return_block.?);
    }

    fn processStructured(self: *MergeReturn, ctx: *Ctx, func: *Func, return_blocks: []const *Block) bool {
        if (hasNontrivialUnreachableBlocks(ctx, func)) {
            ctx.emitErrorMessage("Module contains unreachable blocks during merge return.  Run dead branch elimination before merge return.", null);
            return false;
        }

        self.recordImmediateDominators(ctx, func);
        if (!self.addSingleCaseSwitchAroundFunction(ctx)) return false;

        var order: MrOrder = .{};
        ctx.cfg().computeStructuredOrderNoEnd(func, func.blocks.items[0], &order.items);

        self.state.clear();
        self.state.push(.{ .break_merge = null, .current_merge = null });
        for (order.items.items) |block| {
            if (ctx.cfg().isPseudoEntryBlock(block) or ctx.cfg().isPseudoExitBlock(block) or block == self.final_return_block.?) continue;

            const block_id: u32 = block.label.resultId();
            if (block_id == self.currentState().currentMergeId()) {
                // Pop the current state as we've hit the merge
                _ = self.state.pop();
            }

            if (!self.processStructuredBlock(ctx, block)) return false;

            // Generate state for next block if warranted
            self.generateState(block);
        }

        self.state.clear();
        self.state.push(.{ .break_merge = null, .current_merge = null });
        var predicated: Set(*Block) = .{};
        order.cursor = 0;
        while (order.cursor < order.items.len()) : (order.cursor += 1) {
            const block: *Block = order.items.items[order.cursor];
            if (ctx.cfg().isPseudoEntryBlock(block) or ctx.cfg().isPseudoExitBlock(block)) continue;

            const block_id: u32 = block.id();
            if (block_id == self.currentState().currentMergeId()) {
                // Pop the current state as we've hit the merge
                _ = self.state.pop();
            }

            // Predicate successors of the original return blocks as necessary.
            var is_return_block: bool = false;
            for (return_blocks) |rb| {
                if (rb == block) is_return_block = true;
            }
            if (is_return_block) {
                if (!self.predicateBlocks(ctx, block, &predicated, &order)) return false;
            }

            // Generate state for next block if warranted
            self.generateState(block);
        }

        // The dominator tree has not been kept up to date: make sure it is rebuilt.
        ctx.removeDominatorAnalysis(func);
        if (!self.addNewPhiNodes(ctx)) return false;
        return true;
    }

    // ---- non structured path (kernels) --------------------------------------------------------------------

    fn mergeReturnBlocks(self: *MergeReturn, ctx: *Ctx, func: *Func, return_blocks: []const *Block) bool {
        if (return_blocks.len <= 1) return true; // no work to do

        if (!self.createReturnBlock(ctx)) return false;
        const ret_block: *Block = self.final_return_block.?;
        const return_id: u32 = ret_block.id();

        // Create the PHI for the merged block (if necessary) and the new return.
        var phi_ops: List(Operand) = .{};
        for (return_blocks) |block| {
            if (block.tail().op == .OpReturnValue) {
                phi_ops.push(Operand.id(.IdRef, block.tail().getSingleWordInOperand(0)));
                phi_ops.push(Operand.id(.IdRef, block.id()));
            }
        }

        if (phi_ops.len() != 0) {
            // Need a PHI node to select the correct return value.
            const phi_result_id: u32 = ctx.takeNextId();
            const phi_type_id: u32 = func.typeId();
            const phi_inst: *Inst = Inst.make(.OpPhi, phi_type_id, phi_result_id, phi_ops.items);
            ret_block.addInst(phi_inst);

            const return_inst: *Inst = Inst.make(.OpReturnValue, 0, 0, &.{Operand.id(.IdRef, phi_result_id)});
            ret_block.addInst(return_inst);

            // Register the phi def and mark instructions for use updates.
            const du: *DefUseMgr = ctx.getDefUseMgr();
            du.analyzeInstDefUse(phi_inst);
            du.analyzeInstDef(return_inst);
        } else {
            ret_block.addInst(Inst.make(.OpReturn, 0, 0, &.{}));
        }

        // Replace returns with branches
        for (return_blocks) |block| {
            const term: *Inst = block.tail();
            ctx.forgetUses(term);
            term.setOpcode(.OpBranch);
            term.replaceOperands(&.{Operand.id(.IdRef, return_id)});
            const du: *DefUseMgr = ctx.getDefUseMgr();
            du.analyzeInstUse(term);
            du.analyzeInstUse(block.label);
        }

        ctx.getDefUseMgr().analyzeInstDefUse(ret_block.label);
        return true;
    }

    fn processFn(r: Runner, func: *Func) bool {
        const self: *MergeReturn = r.pass;
        const ctx: *Ctx = r.ctx;
        var return_blocks: List(*Block) = collectReturnBlocks(func);
        if (return_blocks.len() <= 1) {
            if (!r.is_shader or return_blocks.len() == 0) return false;
            const is_in_construct: bool = ctx.getStructuredCfgAnalysis().containingConstruct(return_blocks.items[0].id()) != 0;
            const ends_with_return: bool = return_blocks.items[0] == func.tail();
            if (!is_in_construct and ends_with_return) return false;
        }

        self.function = func;
        self.return_flag = null;
        self.return_value = null;
        self.final_return_block = null;

        if (r.is_shader) {
            if (!self.processStructured(ctx, func, return_blocks.items)) self.failed = true;
        } else {
            if (!self.mergeReturnBlocks(ctx, func, return_blocks.items)) self.failed = true;
        }
        return true;
    }

    pub fn run(self: *MergeReturn, ctx: *Ctx) PassStatus {
        self.* = .{};
        const is_shader: bool = ctx.getFeatureMgr().hasCapability(.Shader);
        const modified: bool = ctx.processReachableCallTree(Runner{ .ctx = ctx, .pass = self, .is_shader = is_shader }, processFn);
        if (self.failed) return .failure;
        return if (modified) .success_with_change else .success_without_change;
    }
};

// InlinePass base (inline_pass.cpp) and InlineExhaustivePass (inline_exhaustive_pass.cpp), flag
// --inline-entry-points-exhaustive: inlines every call in the functions reachable from the entry points.
//
// The C++ base class becomes `InlineState` (embedded in each derived pass) plus free `inl*` functions taking
// (`st`, `ctx`). Debug-info extensions (DebugScope, DebugInlinedAt, DebugDeclare) do not exist in this port; only
// the OpLine attachments are copied like the C++ does. Unordered C++ containers (id2function_, id2block_,
// callee2caller, preCallSB, postCallSB, funcs_called_from_continue_) are only probed for membership/lookup.

/// State of the inliner (the C++ InlinePass base class): lookup tables by id, and what has been learned about each
/// function. `inlinable` is the set of functions whose calls may be inlined; `early_return_funcs` holds those with a
/// return that is not in their last block (they can only be inlined after merge-return), `no_return_in_loop` those
/// without a return inside a loop, and `funcs_called_from_continue` the functions called from a loop continue target.
pub const InlineState = struct {
    id2function: Map(u32, *Func) = .{},
    id2block: Map(u32, *Block) = .{},
    early_return_funcs: Set(u32) = .{},
    no_return_in_loop: Set(u32) = .{},
    inlinable: Set(u32) = .{},
    false_id: u32 = 0,
    funcs_called_from_continue: StdUSet32 = .{},
};

/// Operand indices of OpFunctionCall: the callee, then the arguments (operand 0 is the result type, 1 the result).
const kSpvFunctionCallFunctionId = 2;

/// A new OpLabel with the id `label_id`.
fn inlNewLabel(label_id: u32) *Inst {
    return Inst.make(.OpLabel, 0, label_id, &.{});
}

/// The line instruction that applies to `inst` (the last one attached to it), or null.
fn inlLineInst(inst: *const Inst) ?*const Inst {
    if (inst.dbg_lines.len() == 0) return null;
    return inst.dbg_lines.last();
}

/// Appends `result_id = OpLoad type_id ptr_id` to `block`, with a copy of the line of the instruction it stands for.
fn inlAddLoad(type_id: u32, result_id: u32, ptr_id: u32, block: *Block, line_inst: ?*const Inst) void {
    const new_load: *Inst = Inst.make(.OpLoad, type_id, result_id, &.{Operand.id(.IdRef, ptr_id)});
    if (line_inst) |l| new_load.dbg_lines.push(l.clone());
    block.addInst(new_load);
}

// ---- parameters and locals -------------------------------------------------------------------------------

/// Maps each parameter of the callee to the argument of the call that has the same position.
const MapParamsCtx = struct { callee2caller: *Map(u32, u32), call_inst: *const Inst, param_idx: usize = 0 };

const kSpvFunctionCallArgumentId = 3;

/// Maps parameter number `param_idx` of the callee to the matching argument of the call.
fn inlMapParam(c: *MapParamsCtx, cpi: *Inst) void {
    c.callee2caller.put(cpi.resultId(), c.call_inst.getSingleWordOperand(kSpvFunctionCallArgumentId + c.param_idx));
    c.param_idx += 1;
}

/// Clones the OpVariables at the start of the entry block of the callee under fresh ids (the clones go in `new_vars`; the
/// caller puts them in its own entry block) and maps the old ids to the new ones.
fn inlCloneAndMapLocals(ctx: *Ctx, callee_fn: *Func, new_vars: *List(*Inst), callee2caller: *Map(u32, u32)) bool {
    var it: ?*Inst = callee_fn.blocks.items[0].insts.first;
    while (it) |v| : (it = v.next) {
        if (v.op != .OpVariable) break;
        const var_inst: *Inst = v.clone();
        const new_id: u32 = ctx.takeNextId();
        ctx.getDecorationMgr().cloneDecorations(v.resultId(), new_id);
        var_inst.setResultId(new_id);
        callee2caller.put(v.resultId(), new_id);
        new_vars.push(var_inst);
    }
    return true;
}

/// Declares the Function variable that carries the return value of a non-void callee and returns its id.
fn inlCreateReturnVar(ctx: *Ctx, callee_fn: *Func, new_vars: *List(*Inst)) u32 {
    const callee_type_id: u32 = callee_fn.typeId();
    const type_mgr: *TypeMgr = ctx.getTypeMgr();
    // FindPointerToType declares the pointer type when it does not exist yet; 0 only on id overflow (fatal here).
    const return_var_type_id: u32 = type_mgr.findPointerToType(callee_type_id, @intFromEnum(StorageClass.Function));
    check(return_var_type_id != 0, "Inline: cannot declare the return variable pointer type");

    const return_var_id: u32 = ctx.takeNextId();
    const var_inst: *Inst = Inst.make(.OpVariable, return_var_type_id, return_var_id, &.{Operand.single(.StorageClass, @intFromEnum(StorageClass.Function))});
    new_vars.push(var_inst);
    ctx.getDecorationMgr().cloneDecorations(callee_fn.id(), return_var_id);

    const ptr_type: *Type = type_mgr.getType(return_var_type_id) orelse fatal("Inline: unknown pointer type %{d}", .{return_var_type_id});
    const ptr: *const TyPointer = ptr_type.as(.pointer) orelse fatal("Inline: %{d} is not a pointer type", .{return_var_type_id});
    if (ptr.pointee) |pointee| {
        if (pointee.as(.pointer)) |inner| {
            if (inner.storage_class == @intFromEnum(StorageClass.PhysicalStorageBuffer)) {
                ctx.getDecorationMgr().addDecorationVal0(return_var_id, @intFromEnum(Decoration.AliasedPointer));
            }
        }
    }
    return return_var_id;
}

/// The results of OpSampledImage and OpImage may only be used in the block that defines them, so after inlining
/// they are re-created in every block that uses them ("same-block ops").
fn inlIsSameBlockOp(inst: *const Inst) bool {
    return inst.op == .OpSampledImage or inst.op == .OpImage;
}

// ---- code generation ------------------------------------------------------------------------------------

/// Moves the instructions that precede the call into the first new block, remembering the same-block ops among them.
fn inlMoveInstsBeforeEntryBlock(pre_call_sb: *Map(u32, *Inst), new_blk: *Block, call_inst: *Inst, call_block: *Block) void {
    while (call_block.insts.first != call_inst) {
        const inst: *Inst = call_block.insts.first.?;
        _ = inst.removeFromList();
        if (inlIsSameBlockOp(inst)) pre_call_sb.put(inst.resultId(), inst);
        new_blk.addInst(inst);
    }
}

/// Appends `OpBranch label_id` to `block`.
fn inlAddBranch(label_id: u32, block: *Block) void {
    block.addInst(Inst.make(.OpBranch, 0, 0, &.{Operand.id(.IdRef, label_id)}));
}

/// Ends `new_blk` with a branch to a new guard block, which stands for the entry block of the callee, and returns the
/// guard block. Used when a call in a loop header has a callee whose entry block starts structured control flow.
fn inlAddGuardBlock(ctx: *Ctx, new_blocks: *List(*Block), callee2caller: *Map(u32, u32), new_blk: *Block, entry_blk_label_id: u32) *Block {
    const guard_block_id: u32 = ctx.takeNextId();
    inlAddBranch(guard_block_id, new_blk);
    new_blocks.push(new_blk);
    const next_blk: *Block = Block.new(inlNewLabel(guard_block_id));
    callee2caller.put(entry_blk_label_id, guard_block_id);
    return next_blk;
}

/// The id mapping of the code being inlined (callee id -> new id).
const MapIdCtx = struct { callee2caller: *const Map(u32, u32) };

/// Replaces an id by its mapping, when it has one.
fn inlMapInId(c: MapIdCtx, iid: *u32) void {
    if (c.callee2caller.get(iid.*)) |m| iid.* = m;
}

/// Copies one instruction of the callee into `new_blk` with its ids renamed through `callee2caller`, and gives the
/// decorations of its result to the new result id. Returns are not copied (see inlInlineReturn); the result is false
/// when the instruction's result has no mapping.
fn inlInlineSingleInstruction(ctx: *Ctx, callee2caller: *const Map(u32, u32), new_blk: *Block, inst: *const Inst) bool {
    if (inst.op == .OpReturnValue or inst.op == .OpReturn) return true;

    const cp_inst: *Inst = inst.clone();
    cp_inst.forEachInId(MapIdCtx{ .callee2caller = callee2caller }, inlMapInId);

    const rid: u32 = cp_inst.resultId();
    if (rid != 0) {
        const nid: u32 = callee2caller.get(rid) orelse return false;
        cp_inst.setResultId(nid);
        ctx.getDecorationMgr().cloneDecorations(rid, nid);
    }
    new_blk.addInst(cp_inst);
    return true;
}

/// Appends `OpStore ptr_id, val_id` to `block`, with a copy of the line of the instruction it stands for.
fn inlAddStore(ptr_id: u32, val_id: u32, block: *Block, line_inst: ?*const Inst) void {
    const new_store: *Inst = Inst.make(.OpStore, 0, 0, &.{ Operand.id(.IdRef, ptr_id), Operand.id(.IdRef, val_id) });
    if (line_inst) |l| new_store.dbg_lines.push(l.clone());
    block.addInst(new_store);
}

/// AddStoresForVariableInitializers: stores for the initialized variables of the callee entry block; returns the
/// first instruction that is not an OpVariable.
fn inlAddStoresForVariableInitializers(callee2caller: *const Map(u32, u32), new_blk: *Block, callee_first_block: *Block) ?*Inst {
    var callee_itr: ?*Inst = callee_first_block.insts.first;
    while (callee_itr) |ci| : (callee_itr = ci.next) {
        if (ci.op != .OpVariable) break;
        if (ci.numInOperands() == 2) {
            const new_var_id: u32 = callee2caller.get(ci.resultId()) orelse fatal("Inline: expected the variable %{d} to have already been mapped", .{ci.resultId()});
            const val_id: u32 = ci.getSingleWordInOperand(1);
            inlAddStore(new_var_id, val_id, new_blk, inlLineInst(ci));
        }
    }
    return callee_itr;
}

/// Copies the entry block of the callee: first the stores of the initializers of its variables, then the other instructions.
fn inlInlineEntryBlock(ctx: *Ctx, callee2caller: *const Map(u32, u32), new_blk: *Block, callee_first_block: *Block) bool {
    var callee_inst_itr: ?*Inst = inlAddStoresForVariableInitializers(callee2caller, new_blk, callee_first_block);
    while (callee_inst_itr) |ci| : (callee_inst_itr = ci.next) {
        if (!inlInlineSingleInstruction(ctx, callee2caller, new_blk, ci)) return false;
    }
    return true;
}

/// Copies the blocks of the callee after the entry block, one new block for each. Returns the last new block, or null when
/// a label has no mapping.
fn inlInlineBasicBlocks(ctx: *Ctx, new_blocks: *List(*Block), callee2caller: *const Map(u32, u32), new_blk_in: *Block, callee_fn: *Func) ?*Block {
    var new_blk: *Block = new_blk_in;
    var bi: usize = 1;
    while (bi < callee_fn.blocks.len()) : (bi += 1) {
        const callee_block: *Block = callee_fn.blocks.items[bi];
        new_blocks.push(new_blk);
        const mapped: u32 = callee2caller.get(callee_block.label.resultId()) orelse return null;
        new_blk = Block.new(inlNewLabel(mapped));

        var it: ?*Inst = callee_block.insts.first;
        while (it) |inst| : (it = inst.next) {
            if (!inlInlineSingleInstruction(ctx, callee2caller, new_blk, inst)) return null;
        }
    }
    return new_blk;
}

/// Replaces the return that ends the callee by a store of the returned value into the return variable. When some block of
/// the callee ends in an abort instruction, the new block also branches to a new block for the code that follows the
/// call, and that block is returned; otherwise the code continues in `new_blk`.
fn inlInlineReturn(
    ctx: *Ctx,
    callee2caller: *const Map(u32, u32),
    new_blocks: *List(*Block),
    new_blk: *Block,
    callee_fn: *Func,
    inst: *const Inst,
    return_var_id: u32,
) *Block {
    if (inst.op == .OpReturnValue) {
        // C++ asserts returnVarId != 0; the release build goes on and stores to id 0 (void callee with OpReturnValue).
        var val_id: u32 = inst.getInOperand(0).w[0];
        if (callee2caller.get(val_id)) |m| val_id = m;
        inlAddStore(return_var_id, val_id, new_blk, inlLineInst(inst));
    }

    var return_label_id: u32 = 0;
    for (callee_fn.blocks.items) |callee_block| {
        if (opIsAbort(callee_block.tail().op)) {
            return_label_id = ctx.takeNextId();
            break;
        }
    }
    if (return_label_id == 0) return new_blk;

    if (inst.op == .OpReturn or inst.op == .OpReturnValue) inlAddBranch(return_label_id, new_blk);
    new_blocks.push(new_blk);
    return Block.new(inlNewLabel(return_label_id));
}

// ---- same-block ops -----------------------------------------------------------------------------------------

/// State for re-creating same-block ops: the ones defined before the call (`pre_call_sb`, by result id), the clones made
/// after it (`post_call_sb`, old id -> new id) and the block that receives the clones.
const SameBlockCtx = struct {
    ctx: *Ctx,
    post_call_sb: *Map(u32, u32),
    pre_call_sb: *Map(u32, *Inst),
    block: *Block,
};

/// Visits one id used by an instruction that follows the call. If it names a same-block op defined before the call, a
/// clone of that op (and, recursively, of the same-block ops it uses) is added to the block and the id is redirected
/// to the clone.
fn inlCloneSameBlockOpsId(c: SameBlockCtx, iid: *u32) bool {
    if (c.post_call_sb.get(iid.*)) |mapped| {
        iid.* = mapped;
        return true;
    }
    const in_inst: *Inst = c.pre_call_sb.get(iid.*) orelse return true;
    const sb_inst: *Inst = in_inst.clone();
    if (!inlCloneSameBlockOps(c, sb_inst)) return false;

    const rid: u32 = sb_inst.resultId();
    const nid: u32 = c.ctx.takeNextId();
    c.ctx.getDecorationMgr().cloneDecorations(rid, nid);
    sb_inst.setResultId(nid);
    c.post_call_sb.put(rid, nid);
    iid.* = nid;
    c.block.addInst(sb_inst);
    return true;
}

/// Redirects every id of `inst` that names a same-block op defined before the call.
fn inlCloneSameBlockOps(c: SameBlockCtx, inst: *Inst) bool {
    return inst.whileEachInId(c, inlCloneSameBlockOpsId);
}

/// Moves the instructions that follow the call into the last new block. When the callee has several blocks, the same-block
/// ops they use are re-created in that block.
fn inlMoveCallerInstsAfterFunctionCall(
    ctx: *Ctx,
    pre_call_sb: *Map(u32, *Inst),
    post_call_sb: *Map(u32, u32),
    new_blk: *Block,
    call_inst: *Inst,
    multi_blocks: bool,
) bool {
    while (call_inst.nextNode()) |inst| {
        _ = inst.removeFromList();
        if (multi_blocks) {
            const c: SameBlockCtx = .{ .ctx = ctx, .post_call_sb = post_call_sb, .pre_call_sb = pre_call_sb, .block = new_blk };
            if (!inlCloneSameBlockOps(c, inst)) return false;
            if (inlIsSameBlockOp(inst)) {
                const rid: u32 = inst.resultId();
                post_call_sb.put(rid, rid);
            }
        }
        new_blk.addInst(inst);
    }
    return true;
}

/// The call was in a loop header and was replaced by several blocks: the OpLoopMerge, which came along with the end of the
/// header, moves in front of the terminator of the first new block, which is the loop header now.
fn inlMoveLoopMergeInstToFirstBlock(new_blocks: *List(*Block)) void {
    const first: *Block = new_blocks.items[0];
    const last: *Block = new_blocks.items[new_blocks.len() - 1];
    check(first != last, "Inline: expected more than one block");

    const loop_merge: *Inst = last.tail().prev orelse fatal("Inline: no loop merge before the terminator", .{});
    check(loop_merge.op == .OpLoopMerge, "Inline: expected an OpLoopMerge before the terminator of the last block");
    const cp_inst: *Inst = loop_merge.clone();
    _ = first.tail().insertBefore(cp_inst);

    _ = loop_merge.removeFromList();
}

/// A loop made of a single block (header and continue target) cannot stay one after inlining: the back-edge branch moves
/// to a new continue block `new_id`, which the old last block branches to, and the OpLoopMerge names it.
fn inlUpdateSingleBlockLoopContinueTarget(new_id: u32, new_blocks: *List(*Block)) void {
    const header: *Block = new_blocks.items[0];
    const merge_inst: *Inst = header.getLoopMergeInst().?;

    const new_block: *Block = Block.new(inlNewLabel(new_id));
    const old_backedge: *Block = new_blocks.items[new_blocks.len() - 1];
    const old_branch: *Inst = old_backedge.tail();

    // The old branch moves to the new block (the intrusive list insertion unlinks it from its old list).
    _ = old_branch.removeFromList();
    new_block.addInst(old_branch);

    inlAddBranch(new_id, old_backedge);
    new_blocks.push(new_block);

    merge_inst.setInOperand(1, &.{new_id});
}

/// Builds the code that replaces `call_inst`. The new blocks go in `new_blocks` (the first has the id of the caller block and
/// holds what preceded the call, the last holds what followed it) and the variables for the entry block of the caller
/// in `new_vars`. Returns false when an id of the callee cannot be mapped.
fn inlGenInlineCode(st: *InlineState, ctx: *Ctx, new_blocks: *List(*Block), new_vars: *List(*Inst), call_inst: *Inst, call_block: *Block) bool {
    var callee2caller: Map(u32, u32) = .{};
    var pre_call_sb: Map(u32, *Inst) = .{};
    var post_call_sb: Map(u32, u32) = .{};

    ctx.invalidateAnalyses(Analysis.def_use);

    const caller_is_loop_header: bool = call_block.getLoopMergeInst() != null;

    const callee_fn_id: u32 = call_inst.getSingleWordOperand(kSpvFunctionCallFunctionId);
    const callee_fn: *Func = st.id2function.get(callee_fn_id) orelse fatal("Inline: no function %{d}", .{callee_fn_id});

    var mp: MapParamsCtx = .{ .callee2caller = &callee2caller, .call_inst = call_inst };
    callee_fn.forEachParam(&mp, inlMapParam, false);

    if (!inlCloneAndMapLocals(ctx, callee_fn, new_vars, &callee2caller)) return false;

    // Create the first block of the new code: it takes the id of the caller block.
    const entry_blk_label_id: u32 = callee_fn.blocks.items[0].label.resultId();
    callee2caller.put(entry_blk_label_id, call_block.id());
    var new_blk: *Block = Block.new(inlNewLabel(call_block.id()));

    // Move the instructions before the call into the new first block.
    inlMoveInstsBeforeEntryBlock(&pre_call_sb, new_blk, call_inst, call_block);

    // If the caller is a loop header and the callee has a merge in its entry block, a guard block keeps the header
    // free of the callee's structured control flow.
    if (caller_is_loop_header and callee_fn.blocks.items[0].getMergeInst() != null) {
        new_blk = inlAddGuardBlock(ctx, new_blocks, &callee2caller, new_blk, entry_blk_label_id);
    }

    const callee_type_id: u32 = callee_fn.typeId();
    var return_var_id: u32 = 0;
    const callee_type: *Type = ctx.getTypeMgr().getType(callee_type_id) orelse fatal("Inline: unknown callee type %{d}", .{callee_type_id});
    if (callee_type.as(.void_) == null) {
        return_var_id = inlCreateReturnVar(ctx, callee_fn, new_vars);
    }

    // Map every callee result id (function, labels, instructions) that is not mapped yet to a fresh id.
    const MapRes = struct {
        ctx: *Ctx,
        callee2caller: *Map(u32, u32),
        fn f(c: @This(), cpi: *Inst) bool {
            const rid: u32 = cpi.resultId();
            if (rid != 0 and !c.callee2caller.contains(rid)) {
                const nid: u32 = c.ctx.takeNextId();
                c.callee2caller.put(rid, nid);
            }
            return true;
        }
    };
    _ = callee_fn.whileEachInst(MapRes{ .ctx = ctx, .callee2caller = &callee2caller }, MapRes.f, false, false);

    // (debug instructions in the function header: none, no extended debug info in this port)

    if (!inlInlineEntryBlock(ctx, &callee2caller, new_blk, callee_fn.blocks.items[0])) return false;

    new_blk = inlInlineBasicBlocks(ctx, new_blocks, &callee2caller, new_blk, callee_fn) orelse return false;

    // Inline the return: the last instruction of the last callee block.
    new_blk = inlInlineReturn(ctx, &callee2caller, new_blocks, new_blk, callee_fn, callee_fn.tail().tail(), return_var_id);

    // Load the return value into the result id of the call.
    if (return_var_id != 0) {
        const res_id: u32 = call_inst.resultId();
        check(res_id != 0, "Inline: the call has no result id");
        inlAddLoad(callee_type_id, res_id, return_var_id, new_blk, inlLineInst(call_inst));
    }

    // Move the instructions after the call into the last new block.
    if (!inlMoveCallerInstsAfterFunctionCall(ctx, &pre_call_sb, &post_call_sb, new_blk, call_inst, callee_fn.blocks.len() != 0)) return false;

    new_blocks.push(new_blk);

    if (caller_is_loop_header and new_blocks.len() > 1) {
        inlMoveLoopMergeInstToFirstBlock(new_blocks);

        const header: *Block = new_blocks.items[0];
        const merge_inst: *Inst = header.getLoopMergeInst().?;
        if (merge_inst.getSingleWordInOperand(1) == header.id()) {
            const new_id: u32 = ctx.takeNextId();
            inlUpdateSingleBlockLoopContinueTarget(new_id, new_blocks);
        }
    }

    for (new_blocks.items) |blk| st.id2block.put(blk.id(), blk);

    ctx.killNamesAndDecorates(call_inst);
    return true;
}

// ---- analysis of the callees ----------------------------------------------------------------------------

/// True for a call to an inlinable function. A callee with an early return is reported (merge-return would make it
/// inlinable) and skipped.
fn inlIsInlinableFunctionCall(st: *InlineState, inst: *const Inst) bool {
    if (inst.op != .OpFunctionCall) return false;
    const callee_fn_id: u32 = inst.getSingleWordOperand(kSpvFunctionCallFunctionId);
    if (!st.inlinable.contains(callee_fn_id)) return false;

    if (st.early_return_funcs.contains(callee_fn_id)) {
        std.debug.print("warning: The function '%{d}' could not be inlined because the return instruction is not at the end of the function. This could be fixed by running merge-return before inlining.\n", .{callee_fn_id});
        return false;
    }
    return true;
}

/// The code that replaced a call ends in another block than it starts in. The phis of the successors that named the first
/// new block as their predecessor are updated to name the last one.
fn inlUpdateSucceedingPhis(st: *InlineState, new_blocks: *const List(*Block)) void {
    const first_id: u32 = new_blocks.items[0].id();
    const last_blk: *Block = new_blocks.items[new_blocks.len() - 1];
    const last_id: u32 = last_blk.id();
    const Fix = struct {
        first_id: u32,
        last_id: u32,
        fn id(c: @This(), p: *u32) void {
            if (p.* == c.first_id) p.* = c.last_id;
        }
        fn phi(c: @This(), phi_inst: *Inst) void {
            phi_inst.forEachInId(c, id);
        }
    };
    const Succ = struct {
        st: *InlineState,
        fix: Fix,
        fn f(c: @This(), succ: u32) void {
            const sbp: *Block = c.st.id2block.get(succ) orelse fatal("Inline: no block %{d}", .{succ});
            sbp.forEachPhiInst(c.fix, Fix.phi, false);
        }
    };
    last_blk.forEachSuccessorLabel(Succ{ .st = st, .fix = .{ .first_id = first_id, .last_id = last_id } }, Succ.f);
}

/// True when no return of `func` is inside a loop. Without the Shader capability this is conservatively false.
fn inlHasNoReturnInLoop(ctx: *Ctx, func: *Func) bool {
    if (!ctx.getFeatureMgr().hasCapability(.Shader)) return false;
    const structured_analysis: *StructCfg = ctx.getStructuredCfgAnalysis();
    var return_in_loop: bool = false;
    for (func.blocks.items) |blk| {
        if (opIsReturn(blk.tail().op) and structured_analysis.containingLoop(blk.id()) != 0) {
            return_in_loop = true;
            break;
        }
    }
    return !return_in_loop;
}

/// Records whether `func` has no return in a loop and whether it has a return that is not in its last block.
fn inlAnalyzeReturns(st: *InlineState, ctx: *Ctx, func: *Func) void {
    if (inlHasNoReturnInLoop(ctx, func)) _ = st.no_return_in_loop.insert(func.id());
    const func_tail: *Block = func.tail();
    for (func.blocks.items) |blk| {
        if (opIsReturn(blk.tail().op) and blk != func_tail) {
            _ = st.early_return_funcs.insert(func.id());
            break;
        }
    }
}

/// The function whose recursion is being tested.
const RecursiveCtx = struct { target: *const Func };

/// Stops the walk over the call tree when it reaches the function itself.
fn inlMarkVisited(c: RecursiveCtx, fp: *Func) bool {
    return fp == c.target;
}

/// Function::IsRecursive
fn inlFuncIsRecursive(ctx: *Ctx, func: *Func) bool {
    var roots: Queue(u32) = .{};
    ctx.addCalls(func, &roots);
    return ctx.processCallTreeFromRoots(RecursiveCtx{ .target = func }, inlMarkVisited, &roots);
}

/// Visitor: false for an abort instruction other than OpUnreachable.
fn inlAbortOtherThanUnreachable(_: void, inst: *Inst) bool {
    return inst.op == .OpUnreachable or !opIsAbort(inst.op);
}

/// True when `func` has an abort instruction other than OpUnreachable.
fn inlContainsAbortOtherThanUnreachable(func: *Func) bool {
    return !func.whileEachInst({}, inlAbortOtherThanUnreachable, false, false);
}

/// Whether calls to `func` can be inlined: it has a body, is not marked DontInline, has no return in a loop, is not
/// recursive, and does not contain an abort other than OpUnreachable when it is called from a continue target.
fn inlIsInlinableFunction(st: *InlineState, ctx: *Ctx, func: *Func) bool {
    if (func.blocks.len() == 0) return false;

    if (func.controlMask() & 0x2 != 0) return false; // FunctionControlMask::DontInline

    inlAnalyzeReturns(st, ctx, func);
    if (!st.no_return_in_loop.contains(func.id())) return false;

    if (inlFuncIsRecursive(ctx, func)) return false;

    const func_is_called_from_continue: bool = st.funcs_called_from_continue.contains(func.id());
    if (func_is_called_from_continue and inlContainsAbortOtherThanUnreachable(func)) return false;

    return true;
}

/// Resets the state and fills the id tables and the set of inlinable functions.
fn inlInitializeInline(st: *InlineState, ctx: *Ctx) void {
    st.* = .{};
    st.funcs_called_from_continue = ctx.getStructuredCfgAnalysis().findFuncsCalledFromContinue();

    for (ctx.module.functions.items) |fn_| {
        st.id2function.put(fn_.id(), fn_);
        for (fn_.blocks.items) |blk| st.id2block.put(blk.id(), blk);
        if (inlIsInlinableFunction(st, ctx, fn_)) _ = st.inlinable.insert(fn_.id());
    }
}

// ---- InlineExhaustivePass -------------------------------------------------------------------------------

/// --inline-entry-points-exhaustive: inlines every call, in every function reachable from an entry point. Calls inside the
/// inlined code are inlined as well.
pub const InlineExhaustive = struct {
    pub const name = "inline-entry-points-exhaustive";
    pub const preserved: u32 = 0;

    st: InlineState = .{},
    status: PassStatus = .success_without_change,

    fn inlineExhaustive(self: *InlineExhaustive, ctx: *Ctx, func: *Func) PassStatus {
        const st: *InlineState = &self.st;
        var modified: bool = false;
        var bi: usize = 0;
        while (bi < func.blocks.len()) : (bi += 1) {
            var ii: ?*Inst = func.blocks.items[bi].insts.first;
            while (ii) |inst| {
                if (inlIsInlinableFunctionCall(st, inst)) {
                    const call_block: *Block = func.blocks.items[bi];
                    const prev_inst: ?*Inst = inst.prev; // null when the call is the first instruction

                    var new_blocks: List(*Block) = .{};
                    var new_vars: List(*Inst) = .{};
                    if (!inlGenInlineCode(st, ctx, &new_blocks, &new_vars, inst, call_block)) return .failure;
                    if (new_blocks.len() > 1) inlUpdateSucceedingPhis(st, &new_blocks);

                    // Replace the caller block by the new blocks.
                    _ = func.blocks.orderedRemove(bi);
                    for (new_blocks.items, 0..) |bb, k| {
                        bb.parent = func;
                        func.blocks.insert(bi + k, bb);
                    }
                    // New variables go in front of the entry block, in order.
                    if (new_vars.len() > 0) {
                        const entry_first: *Inst = func.blocks.items[0].insts.first.?;
                        for (new_vars.items) |v| _ = entry_first.insertBefore(v);
                    }
                    ii = if (prev_inst) |p| p.next else func.blocks.items[bi].insts.first;
                    modified = true;
                } else {
                    ii = inst.next;
                }
            }
        }

        // (FixDebugDeclares: no DebugDeclare in this port)
        return if (modified) .success_with_change else .success_without_change;
    }

    pub fn run(self: *InlineExhaustive, ctx: *Ctx) PassStatus {
        self.* = .{};
        inlInitializeInline(&self.st, ctx);
        _ = ctx.processReachableCallTree(RunnerT{ .ctx = ctx, .pass = self }, processFnRunner);
        return self.status;
    }

    const RunnerT = struct { ctx: *Ctx, pass: *InlineExhaustive };

    fn processFnRunner(r: RunnerT, func: *Func) bool {
        r.pass.status = statusCombine(r.pass.status, r.pass.inlineExhaustive(r.ctx, func));
        return false;
    }
};

/// Instruction::IsOpcodeSafeToDelete
pub fn instIsOpcodeSafeToDelete(ctx: *Ctx, inst: *const Inst) bool {
    if (ctx.isCombinatorInstruction(inst)) return true;
    // (DebugDeclare / DebugValue of the NonSemantic debug info set cannot occur: that set is rejected or stripped at load)
    return opIsSafeToDeleteExtra(inst.op);
}

// ---- CFG cleanup (RemoveUnreachableBlocks) ---------------------------------------------------------

/// MemPass::RemovePhiOperands. False on id overflow.
fn memRemovePhiOperands(ctx: *Ctx, st: *MemState, phi: *Inst, reachable: *const Set(*Block)) bool {
    var keep_operands: List(Operand) = .{};
    var type_id: u32 = 0;
    var undef_id: u32 = 0;
    var i: usize = 0;
    while (i < phi.numOperands()) {
        if (i < 2) {
            keep_operands.push(phi.getOperand(i).*);
            i += 1;
            continue;
        }
        const in_block: *Block = ctx.cfg().block(phi.getSingleWordOperand(i + 1));
        if (!reachable.contains(in_block)) {
            i += 2;
            continue;
        }
        const arg_id: u32 = phi.getSingleWordOperand(i);
        const arg_def_instr: *Inst = memDef(ctx, arg_id);
        const def_block: ?*Block = ctx.getInstrBlock(arg_def_instr);
        if (def_block != null and !reachable.contains(def_block.?)) {
            if (undef_id == 0) {
                type_id = arg_def_instr.typeId();
                undef_id = memType2Undef(ctx, st, type_id);
                if (undef_id == 0) return false;
            }
            keep_operands.push(Operand.single(.IdRef, undef_id));
        } else {
            keep_operands.push(phi.getOperand(i).*);
        }
        keep_operands.push(phi.getOperand(i + 1).*);
        i += 2;
    }
    ctx.forgetUses(phi);
    phi.replaceOperands(keep_operands.items);
    ctx.analyzeUses(phi);
    return true;
}

/// MemPass::RemoveBlock: kills every instruction of the block (label last) and unlinks it from the function.
fn memRemoveBlock(ctx: *Ctx, func: *Func, index: usize) void {
    const rm_block: *Block = func.blocks.items[index];
    var it: ?*Inst = rm_block.insts.first;
    while (it) |inst| {
        const nxt: ?*Inst = inst.next;
        _ = ctx.killInst(inst);
        it = nxt;
    }
    _ = ctx.killInst(rm_block.label);
    _ = func.blocks.orderedRemove(index);
}

/// MemPass::RemoveUnreachableBlocks
pub fn memRemoveUnreachableBlocks(ctx: *Ctx, st: *MemState, func: *Func) PassStatus {
    if (func.isDeclaration()) return .success_without_change;
    var modified: bool = false;
    var reachable_blocks: Set(*Block) = .{};
    var visited_blocks: Set(*Block) = .{};
    var worklist: Queue(*Block) = .{};
    const cfg: *Cfg = ctx.cfg();

    _ = reachable_blocks.insert(func.entry());
    worklist.push(func.entry());

    const Mark = struct {
        cfg: *Cfg,
        reachable: *Set(*Block),
        visited: *Set(*Block),
        worklist: *Queue(*Block),
        fn f(c: *const @This(), label_id: u32) void {
            const successor: *Block = c.cfg.block(label_id);
            if (!c.visited.contains(successor)) {
                _ = c.reachable.insert(successor);
                c.worklist.push(successor);
                _ = c.visited.insert(successor);
            }
        }
    };
    const mark: Mark = .{ .cfg = cfg, .reachable = &reachable_blocks, .visited = &visited_blocks, .worklist = &worklist };
    while (worklist.pop()) |block| {
        block.forEachSuccessorLabel(&mark, Mark.f);
        block.forMergeAndContinueLabel(&mark, Mark.f);
    }

    for (func.blocks.items) |block| {
        if (!reachable_blocks.contains(block)) continue;
        var it: ?*Inst = block.insts.first;
        while (it) |phi| {
            const nxt: ?*Inst = phi.next;
            if (phi.op != .OpPhi) break;
            if (!memRemovePhiOperands(ctx, st, phi, &reachable_blocks)) return .failure;
            it = nxt;
        }
    }

    var ebi: usize = 0;
    while (ebi < func.blocks.len()) {
        if (!reachable_blocks.contains(func.blocks.items[ebi])) {
            memRemoveBlock(ctx, func, ebi);
            modified = true;
        } else {
            ebi += 1;
        }
    }
    return if (modified) .success_with_change else .success_without_change;
}

/// MemPass::CFGCleanup
pub fn memCfgCleanup(ctx: *Ctx, st: *MemState, func: *Func) PassStatus {
    return memRemoveUnreachableBlocks(ctx, st, func);
}

