// ---- Optimizer::RegisterPassFromFlag -----------------------------------------------------------------------------

/// atof() restricted to the characters ".0123456789": the longest prefix of the form digits[.digits] (0 if none).
fn drvAtof(s: []const u8) f64 {
    var i: usize = 0;
    while (i < s.len and s[i] >= '0' and s[i] <= '9') i += 1;
    if (i < s.len and s[i] == '.') {
        i += 1;
        while (i < s.len and s[i] >= '0' and s[i] <= '9') i += 1;
    }
    const prefix: []const u8 = s[0..i];
    if (prefix.len == 0 or std.mem.eql(u8, prefix, ".")) return 0;
    return std.fmt.parseFloat(f64, prefix) catch 0;
}

/// std::from_chars for uint32_t starting at `start`: digits only (no sign, no space); null on no digits or overflow.
const DrvFromChars = struct { value: u32, end: usize };
fn drvFromCharsU32(s: []const u8, start: usize) ?DrvFromChars {
    var i: usize = start;
    var v: u64 = 0;
    while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {
        v = v * 10 + (s[i] - '0');
        if (v > 0xffffffff) return null;
    }
    if (i == start) return null;
    return .{ .value = @intCast(v), .end = i };
}

/// Appends the pass (or the -O / -Os recipe) that `flag` names to the pass list. False, after printing an error, when the
/// flag is not valid or its argument is wrong.
fn drvRegisterPassFromFlag(d: *Driver, flag: []const u8, preserve_interface: bool) bool {
    // FlagHasValidForm
    const valid_form: bool = std.mem.eql(u8, flag, "-O") or std.mem.eql(u8, flag, "-Os") or (flag.len > 2 and drvStartsWith(flag, "--"));
    if (!valid_form) {
        drvError("{s} is not a valid flag.  Flag passes should have the form '--pass_name[=pass_args]'. Special flag names also accepted: -O and -Os.", .{flag});
        return false;
    }
    var pass_name: []const u8 = undefined;
    var pass_args: []const u8 = undefined;
    drvSplitFlagArgs(flag, &pass_name, &pass_args);
    const pm: *PassManager = &d.pm;
    const eql = std.mem.eql;

    if (eql(u8, pass_name, "strip-debug")) {
        pm.add(.{ .strip_debug_info = .{} });
    } else if (eql(u8, pass_name, "strip-reflect") or eql(u8, pass_name, "strip-nonsemantic")) {
        pm.add(.{ .strip_nonsemantic_info = .{} });
    } else if (eql(u8, pass_name, "set-spec-const-default-value")) {
        if (pass_args.len > 0) {
            const entries: IrList(SpecIdValue) = ssParseDefaultValuesString(pass_args) orelse {
                drvError("Invalid argument for --set-spec-const-default-value: {s}", .{pass_args});
                return false;
            };
            pm.add(.{ .set_spec_constant_default_value = .{ .entries = entries } });
        } else {
            drvError("Invalid spec constant value string '{s}'. Expected a string of <spec id>:<default value> pairs.", .{pass_args});
            return false;
        }
    } else if (eql(u8, pass_name, "freeze-spec-const")) {
        pm.add(.{ .freeze_spec_constant_value = .{} });
    } else if (eql(u8, pass_name, "eliminate-dead-functions")) {
        pm.add(.{ .eliminate_dead_functions = .{} });
    } else if (eql(u8, pass_name, "eliminate-dead-const")) {
        pm.add(.{ .eliminate_dead_constant = .{} });
    } else if (eql(u8, pass_name, "unify-const")) {
        pm.add(.{ .unify_constant = .{} });
    } else if (eql(u8, pass_name, "flatten-decorations")) {
        pm.add(.{ .flatten_decoration = .{} });
    } else if (eql(u8, pass_name, "compact-ids")) {
        pm.add(.{ .compact_ids = .{} });
    } else if (eql(u8, pass_name, "remove-duplicates")) {
        pm.add(.{ .remove_duplicates = .{} });
    } else if (eql(u8, pass_name, "remove-dont-inline")) {
        pm.add(.{ .remove_dont_inline = .{} });
    } else if (eql(u8, pass_name, "merge-blocks")) {
        pm.add(.{ .block_merge = .{} });
    } else if (eql(u8, pass_name, "wrap-opkill")) {
        pm.add(.{ .wrap_opkill = .{} });
    } else if (eql(u8, pass_name, "private-to-local")) {
        pm.add(.{ .private_to_local = .{} });
    } else if (eql(u8, pass_name, "eliminate-local-single-block")) {
        pm.add(.{ .local_single_block_elim = .{} });
    } else if (eql(u8, pass_name, "eliminate-local-single-store")) {
        pm.add(.{ .local_single_store_elim = .{} });
    } else if (eql(u8, pass_name, "convert-local-access-chains")) {
        pm.add(.{ .local_access_chain_convert = .{} });
    } else if (eql(u8, pass_name, "eliminate-local-multi-store") or eql(u8, pass_name, "ssa-rewrite")) {
        pm.add(.{ .ssa_rewrite = .{} });
    } else if (eql(u8, pass_name, "eliminate-dead-branches")) {
        pm.add(.{ .dead_branch_elim = .{} });
    } else if (eql(u8, pass_name, "merge-return")) {
        pm.add(.{ .merge_return = .{} });
    } else if (eql(u8, pass_name, "inline-entry-points-exhaustive")) {
        pm.add(.{ .inline_exhaustive = .{} });
    } else if (eql(u8, pass_name, "eliminate-dead-code-aggressive")) {
        pm.add(.{ .adce = .{ .preserve_interface = preserve_interface } });
    } else if (eql(u8, pass_name, "inline-entry-points-opaque")) {
        pm.add(.{ .inline_opaque = .{} });
    } else if (eql(u8, pass_name, "eliminate-dead-variables")) {
        pm.add(.{ .dead_variable_elimination = .{} });
    } else if (eql(u8, pass_name, "workaround-1209")) {
        pm.add(.{ .workaround1209 = .{} });
    } else if (eql(u8, pass_name, "relax-float-ops")) {
        pm.add(.{ .relax_float_ops = .{} });
    } else if (eql(u8, pass_name, "strength-reduction")) {
        pm.add(.{ .strength_reduction = .{} });
    } else if (eql(u8, pass_name, "replace-invalid-opcode")) {
        pm.add(.{ .replace_invalid_opcode = .{} });
    } else if (eql(u8, pass_name, "fix-func-call-param")) {
        pm.add(.{ .fix_func_call_arguments = .{} });
    } else if (eql(u8, pass_name, "nonwritable-propagation")) {
        pm.add(.{ .nonwritable_propagation = .{} });
    } else if (eql(u8, pass_name, "switch-descriptorset")) {
        if (pass_args.len == 0) {
            drvError("--switch-descriptorset requires a from:to argument.", .{});
            return false;
        }
        const from: DrvFromChars = drvFromCharsU32(pass_args, 0) orelse {
            drvError("Invalid argument for --switch-descriptorset: {s}", .{pass_args});
            return false;
        };
        if (from.end >= pass_args.len or pass_args[from.end] != ':') {
            drvError("Invalid argument for --switch-descriptorset: {s}", .{pass_args});
            return false;
        }
        const to: DrvFromChars = drvFromCharsU32(pass_args, from.end + 1) orelse {
            drvError("Invalid argument for --switch-descriptorset: {s}", .{pass_args});
            return false;
        };
        if (to.end != pass_args.len) {
            drvError("Invalid argument for --switch-descriptorset: {s}", .{pass_args});
            return false;
        }
        pm.add(.{ .switch_descriptorset = .{ .ds_from = from.value, .ds_to = to.value } });
    } else if (eql(u8, pass_name, "modify-maximal-reconvergence")) {
        if (pass_args.len == 0) {
            drvError("--modify-maximal-reconvergence requires an argument", .{});
            return false;
        }
        if (eql(u8, pass_args, "add")) {
            pm.add(.{ .modify_maximal_reconvergence = .{ .add = true } });
        } else if (eql(u8, pass_args, "remove")) {
            pm.add(.{ .modify_maximal_reconvergence = .{ .add = false } });
        } else {
            drvError("Invalid argument for --modify-maximal-reconvergence: {s} (must be 'add' or 'remove')", .{pass_args});
            return false;
        }
    } else if (eql(u8, pass_name, "spread-volatile-semantics")) {
        pm.add(.{ .spread_volatile_semantics = .{} });
    } else if (eql(u8, pass_name, "canonicalize-ids")) {
        pm.add(.{ .canonicalize_ids = .{} });
    } else if (eql(u8, pass_name, "resolve-binding-conflicts")) {
        pm.add(.{ .resolve_binding_conflicts = .{} });
    } else if (eql(u8, pass_name, "eliminate-dead-input-components")) {
        pm.add(.{ .eliminate_dead_io_components = .{ .elim_sclass = .Input, .safe_mode = true } });
    } else if (eql(u8, pass_name, "convert-to-sampled-image")) {
        if (pass_args.len > 0) {
            const pairs: IrList(ConvertToSampledImage.DescriptorSetAndBinding) = ConvertToSampledImage.parseDescriptorSetBindingPairsString(pass_args) orelse {
                drvError("Invalid argument for --convert-to-sampled-image: {s}", .{pass_args});
                return false;
            };
            pm.add(.{ .convert_to_sampled_image = .{ .pairs = pairs } });
        } else {
            drvError("Invalid pairs of descriptor set and binding '{s}'. Expected a string of <descriptor set>:<binding> pairs.", .{pass_args});
            return false;
        }
    } else if (eql(u8, pass_name, "upgrade-memory-model")) {
        pm.add(.{ .upgrade_memory_model = .{} });
    } else if (eql(u8, pass_name, "amd-ext-to-khr")) {
        pm.add(.{ .amd_ext_to_khr = .{} });
    } else if (eql(u8, pass_name, "graphics-robust-access")) {
        pm.add(.{ .graphics_robust_access = .{} });
    } else if (eql(u8, pass_name, "loop-invariant-code-motion")) {
        pm.add(.{ .loop_invariant_code_motion = .{} });
    } else if (eql(u8, pass_name, "split-combined-image-sampler")) {
        pm.add(.{ .split_combined_image_sampler = .{} });
    } else if (eql(u8, pass_name, "replace-desc-array-access-using-var-index")) {
        pm.add(.{ .replace_desc_array_access_using_var_index = .{} });
    } else if (eql(u8, pass_name, "descriptor-scalar-replacement")) {
        pm.add(.{ .descriptor_scalar_replacement = .{ .flatten_composites = true, .flatten_arrays = true } });
    } else if (eql(u8, pass_name, "descriptor-composite-scalar-replacement")) {
        pm.add(.{ .descriptor_scalar_replacement = .{ .flatten_composites = true, .flatten_arrays = false } });
    } else if (eql(u8, pass_name, "descriptor-array-scalar-replacement")) {
        pm.add(.{ .descriptor_scalar_replacement = .{ .flatten_composites = false, .flatten_arrays = true } });
    } else if (eql(u8, pass_name, "convert-relaxed-to-half")) {
        pm.add(.{ .convert_to_half = .{} });
    } else if (eql(u8, pass_name, "struct-packing")) {
        if (pass_args.len == 0) {
            drvError("--struct-packing requires a name:rule argument.", .{});
            return false;
        }
        const separator_pos: usize = std.mem.indexOfScalar(u8, pass_args, ':') orelse {
            drvError("Invalid argument for --struct-packing: {s}", .{pass_args});
            return false;
        };
        if (separator_pos == 0 or separator_pos + 1 == pass_args.len) {
            drvError("Invalid argument for --struct-packing: {s}", .{pass_args});
            return false;
        }
        pm.add(.{ .struct_packing = .{
            .struct_to_pack = pass_args[0..separator_pos],
            .rules = StructPacking.parsePackingRuleFromString(pass_args[separator_pos + 1 ..]),
        } });
    } else if (eql(u8, pass_name, "trim-capabilities")) {
        pm.add(.{ .trim_capabilities = .{} });
    } else if (eql(u8, pass_name, "code-sink")) {
        pm.add(.{ .code_sink = .{} });
    } else if (eql(u8, pass_name, "fold-spec-const-op-composite")) {
        pm.add(.{ .fold_spec_constant_op_and_composite = .{} });
    } else if (eql(u8, pass_name, "ccp")) {
        pm.add(.{ .ccp = .{} });
    } else if (eql(u8, pass_name, "simplify-instructions") or eql(u8, pass_name, "eliminate-insert-extract")) {
        pm.add(.{ .simplification = .{} });
    } else if (eql(u8, pass_name, "local-redundancy-elimination")) {
        pm.add(.{ .local_redundancy_elim = .{} });
    } else if (eql(u8, pass_name, "redundancy-elimination")) {
        pm.add(.{ .redundancy_elim = .{} });
    } else if (eql(u8, pass_name, "combine-access-chains")) {
        pm.add(.{ .combine_access_chains = .{} });
    } else if (eql(u8, pass_name, "vector-dce")) {
        pm.add(.{ .vector_dce = .{} });
    } else if (eql(u8, pass_name, "eliminate-dead-inserts")) {
        pm.add(.{ .dead_insert_elim = .{} });
    } else if (eql(u8, pass_name, "copy-propagate-arrays")) {
        pm.add(.{ .copy_propagate_arrays = .{} });
    } else if (eql(u8, pass_name, "if-conversion")) {
        pm.add(.{ .if_conversion = .{} });
    } else if (eql(u8, pass_name, "reduce-load-size")) {
        if (pass_args.len == 0) {
            pm.add(.{ .reduce_load_size = .{} });
        } else {
            var load_replacement_threshold: f64 = 0.9;
            if (std.mem.indexOfNone(u8, pass_args, ".0123456789") == null) {
                load_replacement_threshold = drvAtof(pass_args);
            }
            if (load_replacement_threshold >= 0) {
                pm.add(.{ .reduce_load_size = .{ .replacement_threshold = load_replacement_threshold } });
            } else {
                drvError("--reduce-load-size must have no arguments or a non-negative double argument", .{});
                return false;
            }
        }
    } else if (eql(u8, pass_name, "scalar-replacement")) {
        if (pass_args.len == 0) {
            pm.add(.{ .scalar_replacement = .{ .max_num_elements = 0 } });
        } else {
            var limit: i32 = -1;
            if (std.mem.indexOfNone(u8, pass_args, "0123456789") == null) {
                limit = drvAtoi(pass_args);
            }
            if (limit >= 0) {
                pm.add(.{ .scalar_replacement = .{ .max_num_elements = @intCast(limit) } });
            } else {
                drvError("--scalar-replacement must have no arguments or a non-negative integer argument", .{});
                return false;
            }
        }
    } else if (eql(u8, pass_name, "eliminate-dead-members")) {
        pm.add(.{ .eliminate_dead_members = .{} });
    } else if (eql(u8, pass_name, "fix-storage-class")) {
        pm.add(.{ .fix_storage_class = .{} });
    } else if (eql(u8, pass_name, "legalize-multidim-array")) {
        pm.add(.{ .legalize_multidim_array = .{} });
    } else if (eql(u8, pass_name, "cfg-cleanup")) {
        pm.add(.{ .cfg_cleanup = .{} });
    } else if (eql(u8, pass_name, "remove-unused-interface-variables")) {
        pm.add(.{ .remove_unused_interface_variables = .{} });
    } else if (eql(u8, pass_name, "fix-opextinst-opcodes")) {
        pm.add(.{ .opextinst_forward_ref_fixup = .{} });
    } else if (eql(u8, pass_name, "interpolate-fixup")) {
        pm.add(.{ .interp_fixup = .{} });
    } else if (eql(u8, pass_name, "loop-unroll")) {
        pm.add(.{ .loop_unroller = .{ .fully_unroll = true, .unroll_factor = 0 } });
    } else if (eql(u8, pass_name, "loop-unroll-partial")) {
        const factor: i32 = if (pass_args.len > 0) drvAtoi(pass_args) else 0;
        if (factor > 0) {
            pm.add(.{ .loop_unroller = .{ .fully_unroll = false, .unroll_factor = factor } });
        } else {
            drvError("--loop-unroll-partial must have a positive integer argument", .{});
            return false;
        }
    } else if (eql(u8, pass_name, "loop-fission")) {
        const register_threshold_to_split: i32 = if (pass_args.len > 0) drvAtoi(pass_args) else -1;
        if (register_threshold_to_split > 0) {
            pm.add(.{ .loop_fission = .{ .register_threshold_to_split = @intCast(register_threshold_to_split), .split_multiple_times = true } });
        } else {
            drvError("--loop-fission must have a positive integer argument", .{});
            return false;
        }
    } else if (eql(u8, pass_name, "convert-to-untyped")) {
        pm.add(.{ .convert_to_untyped = .{} });
    } else if (eql(u8, pass_name, "loop-fusion")) {
        const max_registers_per_loop: i32 = if (pass_args.len > 0) drvAtoi(pass_args) else -1;
        if (max_registers_per_loop > 0) {
            pm.add(.{ .loop_fusion = .{ .max_registers_per_loop = @intCast(max_registers_per_loop) } });
        } else {
            drvError("--loop-fusion must have a positive integer argument", .{});
            return false;
        }
    } else if (eql(u8, pass_name, "loop-unswitch")) {
        pm.add(.{ .loop_unswitch = .{} });
    } else if (eql(u8, pass_name, "loop-peeling")) {
        pm.add(.{ .loop_peeling = .{} });
    } else if (eql(u8, pass_name, "loop-peeling-threshold")) {
        const factor: i32 = if (pass_args.len > 0) drvAtoi(pass_args) else 0;
        if (factor > 0) {
            LoopPeelingPass.code_grow_threshold = @intCast(factor);
        } else {
            drvError("--loop-peeling-threshold must have a positive integer argument", .{});
            return false;
        }
    } else if (eql(u8, pass_name, "eliminate-dead-output-stores")) {
        // library-only pass: the live input locations/builtins of the consumer stage come from AnalyzeLiveInputPass run on
        // the module <consumer.spv> (C++: CreateAnalyzeLiveInputPass + CreateEliminateDeadOutputStoresPass with shared sets)
        if (pass_args.len == 0) {
            drvError("--eliminate-dead-output-stores requires the consumer shader: --eliminate-dead-output-stores=<consumer.spv>", .{});
            return false;
        }
        const live = irAllocator().create(LiveIoSets) catch oom();
        live.* = .{};
        d.pending_consumers.append(d.gpa, .{ .path = pass_args, .live = live }) catch oom();
        pm.add(.{ .eliminate_dead_output_stores = .{ .live = live } });
    } else if (eql(u8, pass_name, "interface-variable-scalar-replacement")) {
        // library-only pass (CreateInterfaceVariableScalarReplacementPass): flag added by this port
        pm.add(.{ .interface_variable_scalar_replacement = .{} });
    } else if (eql(u8, pass_name, "O")) {
        drvRegisterPerformancePasses(pm, preserve_interface);
    } else if (eql(u8, pass_name, "Os")) {
        drvRegisterSizePasses(pm, preserve_interface);
    } else if (eql(u8, pass_name, "legalize-hlsl")) {
        drvRegisterLegalizationPasses(pm, preserve_interface);
    } else {
        drvError("Unknown flag '--{s}'. Use --help for a list of valid flags", .{pass_name});
        return false;
    }
    d.num_pass_flags += 1;
    return true;
}

// ---- opt.cpp ParseFlags / ReadFlagsFromFile ----------------------------------------------------------------------

/// ReadFlagsFromFile, including the std::istringstream quirk: a line that ends in whitespace yields an extra empty word.
fn drvReadFlagsFromFile(d: *Driver, oconfig_flag: []const u8, file_flags: *List([]const u8)) bool {
    const eq: usize = std.mem.indexOfScalar(u8, oconfig_flag, '=') orelse {
        drvError("Invalid -Oconfig flag {s}", .{oconfig_flag});
        return false;
    };
    const fname: []const u8 = oconfig_flag[eq + 1 ..];
    const bytes: []align(1) u8 = std.Io.Dir.cwd().readFileAllocOptions(d.io, fname, d.gpa, .limited(1 << 28), .of(u8), null) catch {
        drvError("Could not open file '{s}'", .{fname});
        return false;
    };
    defer d.gpa.free(bytes);
    var lines: std.mem.SplitIterator(u8, .scalar) = std.mem.splitScalar(u8, bytes, '\n');
    while (lines.next()) |line_in| {
        const line = irAllocator().dupe(u8, line_in) catch oom();
        if (line.len == 0 or line[0] == '#') continue;
        var i: usize = 0;
        while (true) { // while (!iss.eof())
            while (i < line.len and spIsSpace(line[i])) i += 1;
            if (i >= line.len) { // `iss >> flag` failed: the word stays empty and is pushed anyway
                file_flags.push("");
                break;
            }
            const start: usize = i;
            while (i < line.len and !spIsSpace(line[i])) i += 1;
            file_flags.push(line[start..i]);
            if (i >= line.len) break; // reading the word hit the end of the line: eofbit
        }
    }
    return true;
}

/// -Oconfig=<file>: reads the flags from the file and handles them like flags of the command line.
fn drvParseOconfigFlag(d: *Driver, prog_name: []const u8, opt_flag: []const u8) DrvStatus {
    var file_flags: List([]const u8) = .{};
    if (!drvReadFlagsFromFile(d, opt_flag, &file_flags)) {
        drvError("Could not read optimizer flags from configuration file", .{});
        return .{ .stop = true, .code = 1 };
    }
    var flags: List([]const u8) = .{};
    flags.push(prog_name);
    for (file_flags.items) |f| flags.push(f);
    for (flags.items) |f| {
        if (std.mem.indexOf(u8, f, "-Oconfig=") != null) {
            drvError("Flag -Oconfig= may not be used inside the configuration file", .{});
            return .{ .stop = true, .code = 1 };
        }
    }
    return drvParseFlags(d, flags.items);
}

/// Handles the command line: every pass flag appends a pass, in order; the other options set fields of the driver.
fn drvParseFlags(d: *Driver, args: []const []const u8) DrvStatus {
    var pass_flags: List([]const u8) = .{};
    var preserve_interface: bool = false;
    const eql = std.mem.eql;
    var argi: usize = 1;
    while (argi < args.len) : (argi += 1) {
        const cur_arg: []const u8 = args[argi];
        if (cur_arg.len > 0 and cur_arg[0] == '-') {
            if (eql(u8, cur_arg, "--version")) {
                std.debug.print("spirvopt (port of SPIRV-Tools spirv-opt)\n", .{});
                return .{ .stop = true, .code = 0 };
            } else if (eql(u8, cur_arg, "--help") or eql(u8, cur_arg, "-h")) {
                drvUsage();
                return .{ .stop = true, .code = 0 };
            } else if (eql(u8, cur_arg, "-o")) {
                if (d.out_file == null and argi + 1 < args.len) {
                    argi += 1;
                    d.out_file = args[argi];
                } else {
                    drvUsage();
                    return .{ .stop = true, .code = 1 };
                }
            } else if (cur_arg.len == 1) {
                if (d.in_file == null) {
                    d.in_file = cur_arg;
                } else {
                    drvError("More than one input file specified", .{});
                    return .{ .stop = true, .code = 1 };
                }
            } else if (drvStartsWith(cur_arg, "-Oconfig=")) {
                const status: DrvStatus = drvParseOconfigFlag(d, args[0], cur_arg);
                if (status.stop) return status;
            } else if (eql(u8, cur_arg, "--skip-validation") or eql(u8, cur_arg, "--time-report") or
                eql(u8, cur_arg, "--relax-struct-store") or eql(u8, cur_arg, "--validate-after-all") or
                eql(u8, cur_arg, "--before-hlsl-legalization") or eql(u8, cur_arg, "--relax-logical-pointer") or
                eql(u8, cur_arg, "--relax-block-layout") or eql(u8, cur_arg, "--scalar-block-layout") or
                eql(u8, cur_arg, "--workgroup-scalar-block-layout") or eql(u8, cur_arg, "--skip-block-layout"))
            {
                // validator / reporting options: nothing to do without a validator
            } else if (eql(u8, cur_arg, "--print-all")) {
                d.print_names = true;
            } else if (eql(u8, cur_arg, "--preserve-bindings")) {
                d.preserve_bindings = true;
            } else if (eql(u8, cur_arg, "--preserve-spec-constants")) {
                d.preserve_spec_constants = true;
            } else if (drvStartsWith(cur_arg, "--max-id-bound=")) {
                var name: []const u8 = undefined;
                var value: []const u8 = undefined;
                drvSplitFlagArgs(cur_arg, &name, &value);
                const max_id_bound: u32 = @bitCast(drvAtoi(value));
                if (max_id_bound < default_max_id_bound) {
                    drvError("The max id bound must be at least 0x3FFFFF", .{});
                    return .{ .stop = true, .code = 1 };
                }
                d.max_id_bound = max_id_bound;
            } else if (drvStartsWith(cur_arg, "--target-env=")) {
                // accepted and ignored: the target environment is fixed to 1.6 and nothing is checked against it
            } else if (eql(u8, cur_arg, "--preserve-interface")) {
                preserve_interface = true;
            } else if (eql(u8, cur_arg, "--strip-debug-ext")) {
                d.strip_debug_ext = true;
            } else if (eql(u8, cur_arg, "--keep-nops")) {
                d.keep_nops = true;
            } else if (eql(u8, cur_arg, "--keep-dup-decorations")) {
                d.keep_dup_decorations = true;
            } else if (eql(u8, cur_arg, "--no-opt")) {
                d.no_opt = true;
            } else if (eql(u8, cur_arg, "--check-pass-status")) {
                d.check_status = true;
            } else {
                pass_flags.push(drvCanonicalizeFlag(d, args, &argi));
            }
        } else {
            if (d.in_file == null) {
                d.in_file = cur_arg;
            } else {
                drvError("More than one input file specified", .{});
                return .{ .stop = true, .code = 1 };
            }
        }
    }
    for (pass_flags.items) |flag| {
        if (!drvRegisterPassFromFlag(d, flag, preserve_interface)) return .{ .stop = true, .code = 1 };
    }
    return .{ .stop = false, .code = 0 };
}

// ---- main ------------------------------------------------------------------------------------------------------

/// True for no path and for "-": standard input or output.
fn drvIsStdio(path: ?[]const u8) bool {
    const p: []const u8 = path orelse return true;
    return std.mem.eql(u8, p, "-");
}

/// Reads a binary (a file, or standard input) as little-endian words in the IR arena.
fn drvReadWords(d: *Driver, in_path: ?[]const u8) []u32 {
    var bytes: []u8 = undefined;
    if (drvIsStdio(in_path)) {
        var buf: [4096]u8 = undefined;
        var rdr: std.Io.File.Reader = std.Io.File.stdin().reader(d.io, &buf);
        bytes = rdr.interface.allocRemaining(d.gpa, .limited(1 << 30)) catch |e| fatal("cannot read standard input: {t}", .{e});
    } else {
        const path: []const u8 = in_path.?;
        bytes = std.Io.Dir.cwd().readFileAllocOptions(d.io, path, d.gpa, .limited(1 << 30), .of(u8), null) catch |e|
            fatal("cannot read '{s}': {t}", .{ path, e });
    }
    defer d.gpa.free(bytes);
    if (bytes.len % 4 != 0) fatal("input size {d} is not a multiple of 4", .{bytes.len});
    const words = irAllocator().alloc(u32, bytes.len / 4) catch oom();
    for (words, 0..) |*w, k| w.* = std.mem.readInt(u32, bytes[k * 4 ..][0..4], .little);
    return words;
}

/// Reads the input binary.
fn drvReadInput(d: *Driver) []u32 {
    return drvReadWords(d, d.in_file);
}

/// Writes the binary to the output file, to standard output for "-", or next to the input as `<input>.opt.spv` when no
/// output was named.
fn drvWriteOutput(d: *Driver, words: []const u32) void {
    const buf = d.gpa.alloc(u8, words.len * 4) catch oom();
    defer d.gpa.free(buf);
    for (words, 0..) |wd, k| std.mem.writeInt(u32, buf[k * 4 ..][0..4], wd, .little);
    var out_path: []const u8 = undefined;
    if (d.out_file) |p| {
        out_path = p;
    } else if (drvIsStdio(d.in_file)) {
        out_path = "-";
    } else {
        out_path = std.fmt.allocPrint(d.gpa, "{s}.opt.spv", .{d.in_file.?}) catch oom();
    }
    if (std.mem.eql(u8, out_path, "-")) {
        std.Io.File.stdout().writeStreamingAll(d.io, buf) catch |e| fatal("cannot write standard output: {t}", .{e});
    } else {
        std.Io.Dir.cwd().writeFile(d.io, .{ .sub_path = out_path, .data = buf }) catch |e|
            fatal("cannot write '{s}': {t}", .{ out_path, e });
    }
}

/// Entry point: parses the flags, analyzes the consumer shaders of --eliminate-dead-output-stores, loads the input, runs the
/// passes and writes the result. When a pass fails the input is written unchanged and the exit status is 1.
pub fn main(init: std.process.Init) !void {
    memInit(std.heap.page_allocator);
    defer memDeinit();

    var d: Driver = .{ .io = init.io, .gpa = init.gpa };
    defer d.pending_consumers.deinit(d.gpa);
    var args: List([]const u8) = .{};
    var it: std.process.Args.Iterator = init.minimal.args.iterate();
    while (it.next()) |a| args.push(a);
    if (args.len() == 0) args.push("spirvopt");

    const status: DrvStatus = drvParseFlags(&d, args.items);
    if (status.stop) std.process.exit(status.code);

    // spirv-opt runs no pass without pass flags; this tool runs -O unless --no-opt is given
    if (d.num_pass_flags == 0 and !d.no_opt) {
        if (!drvRegisterPassFromFlag(&d, "-O", false)) std.process.exit(1);
    }

    // consumer shaders of --eliminate-dead-output-stores: AnalyzeLiveInputPass fills the shared live sets
    for (d.pending_consumers.items) |pc| {
        const cwords: []u32 = drvReadWords(&d, pc.path);
        const cm: *Module = loadModule(cwords, if (d.strip_debug_ext) .strip else .fail);
        cm.max_id_bound = d.max_id_bound;
        const cctx: *Ctx = Ctx.init(cm);
        var apm: PassManager = .{};
        apm.add(.{ .analyze_live_input = .{ .live = pc.live } });
        if (apm.run(cctx, .{}) == .failure) {
            drvError("the live input analysis of '{s}' failed (supported stages: fragment, tessellation control/evaluation, geometry)", .{pc.path});
            std.process.exit(1);
        }
    }

    const input: []u32 = drvReadInput(&d);
    const m: *Module = loadModule(input, if (d.strip_debug_ext) .strip else .fail);
    m.max_id_bound = d.max_id_bound;
    const ctx: *Ctx = Ctx.init(m);
    ctx.preserve_bindings = d.preserve_bindings;
    ctx.preserve_spec_constants = d.preserve_spec_constants;

    const result: PassStatus = d.pm.run(ctx, .{ .print_names = d.print_names, .check_status = d.check_status });
    if (result == .failure) {
        // like opt.cpp: the unchanged input is written, then the exit code is 1
        drvError("the optimizer failed", .{});
        drvWriteOutput(&d, input);
        std.process.exit(1);
    }

    var out: List(u32) = .{};
    moduleToBinary(m, &out, !d.keep_nops, !d.keep_dup_decorations);
    drvWriteOutput(&d, out.items);
}
